window.PRM_DATA=window.PRM_DATA||{shards:{}};PRM_DATA.shards["2022"]={"c20220105_1270":[["p","Ahad, 02 Januari 2022/28 Jumaadal Uulaa 1443 Brosur No.: 2065/2105/IA"],["p","Qolbun salim"],["p","Qolbun salim berasal dari dua kata bahasa Arab."],["p","Qolbun berarti hati, sedangkan salim berarti selamat, bersih, suci."],["p","Jika digabungkan berarti hati yang selamat, hati yang bersih, hati yang suci."],["p","Qolbun salim mempunyai ma’na :"],["p","1) Hati yang selamat dari syirik dan kepercayaan-kepercayaan sesat, Allah SWT berfirman :"],["a","يَوْمَ لَا يَنْفَعُ مَالٌ وَّلَا بَنُوْنَ ۙ (88) اِلَّا مَنْ اَتَى اللّٰهَ بِقَلْبٍ سَلِيْمٍ ۗ (89) . الشعراء : 88 - 89"],["p","(yaitu) di hari harta dan anak-anak laki-laki tidak berguna, (88)"],["p","kecuali orang-orang yang menghadap Allah dengan hati yang bersih,(89) [QS. Asy Syu’araa’ : 88 – 89]"],["a","وَاِنَّ مِنْ شِيْعَتِهٖ لَاِبْرٰهِيْمَ ۘ (83) اِذْ جَاۤءَ رَبَّهٗ بِقَلْبٍ سَلِيْمٍۙ (84). الصافات : 83 - 84"],["p","Dan sesungguhnya Ibrahim benar-benar termasuk golongannya (Nuh). (83)"],["p","(Ingatlah) ketika ia datang kepada Tuhannya dengan hati yang suci. (84) [QS. Ash Shaaffaat : 83 – 84]"],["p","2) Hati yang sehat, bersih dari penyakit penyakit hati, Allah SWT berfirman :"],["a","قُلْ اِنَّ صَلَاتِيْ وَنُسُكِيْ وَمَحْيَايَ وَمَمَاتِيْ لِلّٰهِ رَبِّ الْعٰلَمِيْنَۙ (162) لَا شَرِيْكَ لَهٗ ۚ وَبِذٰلِكَ اُمِرْتُ وَاَنَا۠ اَوَّلُ الْمُسْلِمِيْنَ (163). الانعام: 162 – 163"],["p","Katakanlah: \"Sesungguhnya shalatku, ibadahku, hidup dan matiku hanyalah untuk Allah, Tuhan semesta alam,(162)"],["p","tiada sekutu bagi-Nya; dan demikian itulah yang diperintahkan kepadaku dan aku adalah orang yang pertama-tama menyerahkan diri (kepada Allah)\". (163) [QS. Al An’aam : 162 – 163]"],["p","3) Hati yang mampu melaksanakan sesuai tugas dan fungsinya, Allah SWT berfirman :"],["a","وَاللّٰهُ اَخْرَجَكُمْ مِّنْۢ بُطُوْنِ اُمَّهٰتِكُمْ لَا تَعْلَمُوْنَ شَيْـًٔاۙ وَّجَعَلَ لَكُمُ السَّمْعَ وَالْاَبْصَارَ وَالْاَفْـِٕدَةَ ۙ لَعَلَّكُمْ تَشْكُرُوْنَ. النحل :٧٨"],["p","Dan Allah mengeluarkan kamu dari perut ibumu dalam keadaan tidak mengetahui sesuatu pun, dan Dia memberi kamu pendengaran, penglihatan dan hati, agar kamu bersyukur.[QS. An Nahl : 78]"],["a","وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيْرًا مِّنَ الْجِنِّ وَالْاِنْسِۖ لَهُمْ قُلُوْبٌ لَّا يَفْقَهُوْنَ بِهَاۖ وَلَهُمْ اَعْيُنٌ لَّا يُبْصِرُوْنَ بِهَاۖ وَلَهُمْ اٰذَانٌ لَّا يَسْمَعُوْنَ بِهَاۗ اُولٰۤىِٕكَ كَالْاَنْعَامِ بَلْ هُمْ اَضَلُّ ۗ اُولٰۤىِٕكَ هُمُ الْغٰفِلُوْنَ.الاعراف :١٧٩"],["p","Dan sesungguhnya Kami jadikan untuk isi neraka Jahannam kebanyakan dari jin dan manusia, mereka mempunyai hati, tetapi tidak dipergunakannya untuk memahami (ayat-ayat Allah) dan mereka mempunyai mata (tetapi) tidak dipergunakannya untuk melihat (tanda-tanda kekuasaan Allah), dan mereka mempunyai telinga (tetapi) tidak dipergunakannya untuk mendengar (ayat-ayat Allah). Mereka itu sebagai binatang ternak, bahkan mereka lebih sesat lagi. Mereka itulah orang-orang yang lalai. [QS. Al A’raaf : 179]"],["a","مَآ اَصَابَ مِنْ مُّصِيْبَةٍ اِلَّا بِاِذْنِ اللّٰهِ ۗ وَمَنْ يُّؤْمِنْۢ بِاللّٰهِ يَهْدِ قَلْبَهٗ ۗ وَاللّٰهُ بِكُلِّ شَيْءٍ عَلِيْمٌ. التغابن :١١"],["p","Tidak ada sesuatu mushibah pun yang menimpa seseorang kecuali dengan izin Allah; Dan barang siapa yang beriman kepada Allah, niscaya Dia akan memberi petunjuk kepada hatinya. Dan Allah Maha Mengetahui segala sesuatu. [QS. At Taghaabun : 11]"],["a","وَاعْلَمُوْٓا اَنَّ فِيْكُمْ رَسُوْلَ اللّٰهِ ۗ لَوْ يُطِيْعُكُمْ فِيْ كَثِيْرٍ مِّنَ الْاَمْرِ لَعَنِتُّمْ وَلٰكِنَّ اللّٰهَ حَبَّبَ اِلَيْكُمُ الْاِيْمَانَ وَزَيَّنَهٗ فِيْ قُلُوْبِكُمْ وَكَرَّهَ اِلَيْكُمُ الْكُفْرَ وَالْفُسُوْقَ وَالْعِصْيَانَ ۗ اُولٰۤىِٕكَ هُمُ الرَّاشِدُوْنَۙ. الحجرات :٧"],["p","Dan ketahuilah olehmu bahwa di kalangan kamu ada Rasulullah. Kalau ia menuruti (kemauan) kamu dalam beberapa urusan benar-benarlah kamu akan mendapat kesusahan, tetapi Allah menjadikan kamu cinta kepada keimanan dan menjadikan iman itu indah dalam hatimu serta menjadikan kamu benci kepada kekafiran, kefasikan dan kedurhakaan. Mereka itulah orang-orang yang mengikuti jalan yang lurus, [QS. Al Hujuraat : 7]"],["p","Dan Rasulullah SAW bersabda :"],["a","اَلَا وَ اِنَّ فِي الْجَسَدِ مُضْغَةً، اِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَ اِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ، اَلَا وَهِيَ الْقَلْبُ. البخارى 1: 19"],["p","Dan ketahuilah, sesungguhnya di dalam jasad manusia itu ada segumpal daging, apabila segumpal daging itu baik, maka baik pulalah jasad itu seluruhnya, dan apabila segumpal daging itu rusak, maka rusak pulalah jasad itu seluruhnya. Ketahuilah, ia adalah hati\". [HR. Bukhari juz 1, hal. 19]"],["a","عَنْ اَبِيْ هُرَيْرَةَ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: لَا يَزْنِى الزَّانِى حِيْنَ يَزْنِيْ وَ هُوَ مُؤْمِنٌ، وَ لَا يَشْرَبُ الْخَمْرَ حِيْنَ يَشْرَبُ وَ هُوَ مُؤْمِنٌ، وَ لَا يَسْرِقُ حِيْنَ يَسْرِقُ وَ هُوَ مُؤْمِنٌ، وَ لَا يَنْتَهِبُ نُهْبَةً يَرْفَعُ النَّاسُ اِلَيْهِ فِيْهَا اَبْصَارَهُمْ وَ هُوَ مُؤْمِنٌ. البخارى 8: 13"],["p","Dari Abu Hurairah, bahwasanya Rasulullah SAW bersabda, “Tidaklah berzina seorang yang berzina ketika ia berzina dalam keadaan beriman. Dan tidaklah meminum khamr ketika ia meminumnya dalam keadaan beriman. Dan tidaklah mencuri ketika ia mencuri dalam keadaan beriman. Dan tidaklah pula orang yang merampok harta yang orang-orang melihatnya, ia dalam keadaan beriman”. [HR. Bukhari juz 8, hal. 13]"],["p","Adapun diantara tanda tanda orang yang hatinya sehat sebagai berikut:"],["p","1) Melakukan hal hal yang bermanfaat dan meninggalkan hal hal yang tidak bermanfaat."],["p","Allah SWT berfirman :"],["a","قَدْ اَفْلَحَ الْمُؤْمِنُوْنَۙ (1) الَّذِيْنَ هُمْ فِيْ صَلٰوتِهِمْ خَاشِعُوْنَ (2) وَالَّذِيْنَ هُمْ عَنِ اللَّغْوِ مُعْرِضُوْنَ ۙ (3). المؤمنون : 1 - 3"],["p","Sesungguhnya beruntunglah orang-orang yang beriman, (1)"],["p","(yaitu) orang-orang yang khusyu’ dalam shalatnya, (2)"],["p","dan orang-orang yang menjauhkan diri dari (perbuatan dan perkataan) yang tiada berguna, (3) [QS. Al Mu’minuun : 1-3]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مِنْ حُسْنِ اِسْلَامِ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيْهِ . ابن مجه 2 : 1315 رقم 3976"],["p","Dari Abu Hurairah, ia berkata, Rasulullah SAW bersabda: \"Diantara tanda baiknya Islamnya seseorang adalah meninggalkan hal-hal yang tidak berguna.\" [HR. Ibnu Majah juz 2 : 1315 no 3976]"],["p","2) Lebih mengutamakan akhirat daripada dunia."],["p","Allah berfirman :"],["a","مَنْ كَانَ يُرِيْدُ حَرْثَ الْاٰخِرَةِ نَزِدْ لَهٗ فِيْ حَرْثِهٖ ۚ وَمَنْ كَانَ يُرِيْدُ حَرْثَ الدُّنْيَا نُؤْتِهٖ مِنْهَاۙ وَمَا لَهٗ فِى الْاٰخِرَةِ مِنْ نَّصِيْبٍ .الشورى :٢٠"],["p","Barangsiapa yang menghendaki keuntungan di akhirat akan Kami tambah keuntungan itu baginya dan barangsiapa yang menghendaki keuntungan di dunia Kami berikan kepadanya sebagian dari keuntungan dunia dan tidak ada baginya suatu bahagian pun di akhirat. [QS. Asy Syuraa : 20]"],["a","وَابْتَغِ فِيْمَآ اٰتٰىكَ اللّٰهُ الدَّارَ الْاٰخِرَةَ وَلَا تَنْسَ نَصِيْبَكَ مِنَ الدُّنْيَا وَاَحْسِنْ كَمَآ اَحْسَنَ اللّٰهُ اِلَيْكَ وَلَا تَبْغِ الْفَسَادَ فِى الْاَرْضِ ۗ اِنَّ اللّٰهَ لَا يُحِبُّ الْمُفْسِدِيْنَ. القصص :٧٧"],["p","Dan carilah pada apa yang telah dianugerahkan Allah kepadamu (kebahagiaan) negeri akhirat, dan janganlah kamu melupakan bahagianmu dari (kenikmatan) duniawi dan berbuat baiklah (kepada orang lain) sebagaimana Allah telah berbuat baik kepadamu, dan janganlah kamu berbuat kerusakan di (muka) bumi. Sesungguhnya Allah tidak menyukai orang-orang yang berbuat kerusakan. [QS. Al Qashash : 77]"],["a","مَنْ كَانَ يُرِيْدُ الْعَاجِلَةَ عَجَّلْنَا لَهٗ فِيْهَا مَا نَشَاۤءُ لِمَنْ نُّرِيْدُ ثُمَّ جَعَلْنَا لَهٗ جَهَنَّمَۚ يَصْلٰىهَا مَذْمُوْمًا مَّدْحُوْرًا (18) وَمَنْ اَرَادَ الْاٰخِرَةَ وَسَعٰى لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَاُولٰۤىِٕكَ كَانَ سَعْيُهُمْ مَّشْكُوْرًا (19). الاشراء : 18-19"],["p","Barangsiapa menghendaki kehidupan sekarang (duniawi), maka Kami segerakan baginya di dunia itu apa yang Kami kehendaki bagi orang yang Kami kehendaki dan Kami tentukan baginya neraka Jahannam; ia akan memasukinya dalam keadaan tercela dan terusir. (18)"],["p","Dan barangsiapa yang menghendaki kehidupan akhirat dan berusaha ke arah itu dengan sungguh-sungguh sedang ia adalah mukmin, maka mereka itu adalah orang-orang yang usahanya dibalas dengan baik. (19) [QS. Al Israa’ : 18 – 19]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَوْ كَانَتِ الدُّنْيَا تَعْدِلُ عِنْدَ اللهِ جَنَاحَ بَعُوْضَةٍ مَا سَقَى كَافِرًا مِنْهَا شَرْبَةَ مَاءٍ. الترمذى 3: 383، رقم: 2422"],["p","Dari Sahl bin Sa'ad, ia berkata : Rasulullah SAW bersabda, \"Seandainya dunia ini di sisi Allah ada nilainya sesayap nyamuk, niscaya Allah tidak akan memberi minum kepada orang kafir walaupun seteguk air\". [HR. Tirmidzi juz 3, ha. 383, no. 2422]"],["p","3) Selalu cinta kepada Allah, bertaubat dan mendekatkan diri kepada Allah"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا تُوْبُوْٓا اِلَى اللّٰهِ تَوْبَةً نَّصُوْحًاۗ عَسٰى رَبُّكُمْ اَنْ يُّكَفِّرَ عَنْكُمْ سَيِّاٰتِكُمْ وَيُدْخِلَكُمْ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُۙ يَوْمَ لَا يُخْزِى اللّٰهُ النَّبِيَّ وَالَّذِيْنَ اٰمَنُوْا مَعَهٗ ۚ نُوْرُهُمْ يَسْعٰى بَيْنَ اَيْدِيْهِمْ وَبِاَيْمَانِهِمْ يَقُوْلُوْنَ رَبَّنَآ اَتْمِمْ لَنَا نُوْرَنَا وَاغْفِرْ لَنَاۚ اِنَّكَ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ. التحريم :٨"],["p","Hai orang-orang yang beriman, bertaubatlah kepada Allah dengan taubat yang semurni-murninya, mudah-mudahan Tuhan kamu akan menghapus kesalahan-kesalahanmu dan memasukkan kamu ke dalam surga yang mengalir di bawahnya sungai-sungai, pada hari ketika Allah tidak menghinakan Nabi dan orang-orang yang beriman bersama dengan dia; sedang cahaya mereka memancar di hadapan dan di sebelah kanan mereka, sambil mereka mengatakan: \"Ya Tuhan kami, sempurnakanlah bagi kami cahaya kami dan ampunilah kami; sesungguhnya Engkau Maha Kuasa atas segala sesuatu\". [QS. At Tahriim : 8]"],["a","وَمِنَ النَّاسِ مَنْ يَّتَّخِذُ مِنْ دُوْنِ اللّٰهِ اَنْدَادًا يُّحِبُّوْنَهُمْ كَحُبِّ اللّٰهِ ۗ وَالَّذِيْنَ اٰمَنُوْٓا اَشَدُّ حُبًّا لِّلّٰهِ ۙ وَلَوْ يَرَى الَّذِيْنَ ظَلَمُوْٓا اِذْ يَرَوْنَ الْعَذَابَۙ اَنَّ الْقُوَّةَ لِلّٰهِ جَمِيْعًا ۙ وَّاَنَّ اللّٰهَ شَدِيْدُ الْعَذَابِ.البقره :١٦٥"],["p","Dan di antara manusia ada orang-orang yang menyembah tandingan-tandingan selain Allah; mereka mencintainya sebagaimana mereka mencintai Allah. Adapun orang-orang yang beriman sangat cinta kepada Allah. Dan jika seandainya orang-orang yang berbuat dhalim itu mengetahui ketika mereka melihat siksa (pada hari kiamat), bahwa kekuatan itu kepunyaan Allah semuanya dan bahwa Allah amat berat siksaan-Nya (niscaya mereka menyesal). [QS. Al Baqarah : 165]"],["a","وَمَنْ يُّطِعِ اللّٰهَ وَالرَّسُوْلَ فَاُولٰۤىِٕكَ مَعَ الَّذِيْنَ اَنْعَمَ اللّٰهُ عَلَيْهِمْ مِّنَ النَّبِيّٖنَ وَالصِّدِّيْقِيْنَ وَالشُّهَدَاۤءِ وَالصّٰلِحِيْنَ ۚ وَحَسُنَ اُولٰۤىِٕكَ رَفِيْقًا. النساء :٦٩"],["p","Dan barang siapa yang mentha’ati Allah dan Rasul (Nya), mereka itu akan bersama-sama dengan orang-orang yang dianugerahi nikmat oleh Allah, yaitu: Nabi-nabi, para shiddiiqiin, orang-orang yang mati syahid dan orang-orang shaleh. Dan mereka itulah teman yang sebaik-baiknya.[QS. An Nisaa’ : 69]"],["a","عَنْ اَنَسٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: ثَلَاثٌ مَنْ كُنَّ فِيْهِ وَجَدَ حَلَاوَةَ الْاِيْمَانِ: مَنْ كَانَ اللهُ وَرَسُوْلُهُ اَحَبَّ اِلَيْهِ مِمَّا سِوَاهُمَا، وَمَنْ اَحَبَّ عَبْدًا لَا يُحِبُّهُ اِلَّا لِلّٰهِ، وَمَنْ يَكْرَهُ اَنْ يَعُوْدَ فِى الْكُفْرِ بَعْدَ اِذْ اَنْقَذَهُ اللهُ كَمَا يَكْرَهُ اَنْ يُلْقَى فِى النَّارِ. البخارى 1: 11"],["p","Dari Anas RA, dari Nabi SAW, beliau bersabda, \"Ada tiga perkara barangsiapa yang tiga perkara itu ada padanya berarti ia mendapatkan manisnya iman, yaitu barangsiapa yang Allah dan Rasul-Nya lebih dicintainya dari pada selain keduanya, dan barangsiapa yang mencintai seseorang yang mana dia tidak mencintainya kecuali karena Allah, dan barangsiapa yang benci untuk kembali kepada kekafiran setelah Allah menyelamatkannya dari kekafiran itu sebagaimana dia tidak suka (takut) dilemparkan ke dalam api\". [HR. Bukhari Juz 1, hal. 11]"],["a","عَنْ اَبِيْ اُمَامَةَ عَنْ رَسُوْلِ اللهِ ﷺ اَنَّهُ قَالَ: مَنْ اَحَبَّ لِلّٰهِ وَاَبْغَضَ لِلّٰهِ وَاَعْطَى لِلّٰهِ وَمَنَعَ لِلّٰهِ فَقَدِ اسْتَكْمَلَ اْلاِيْمَانَ. ابو داود 4: 220، رقم: 4681"],["p","Dari Abu Umamah, dari Rasulullah SAW, beliau bersabda, \"Barangsiapa yang mencintai karena Allah, membenci karena Allah, memberi karena Allah dan mencegah karena Allah, berarti dia telah menyempurnakan iman\". [HR. Abu Dawud Juz 4, hal. 220, no. 4681]"],["h","4) Selalu dzikir mengingat Allah"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اذْكُرُوا اللّٰهَ ذِكْرًا كَثِيْرًاۙ (41) وَّسَبِّحُوْهُ بُكْرَةً وَّاَصِيْلًا(42) هُوَ الَّذِيْ يُصَلِّيْ عَلَيْكُمْ وَمَلٰۤىِٕكَتُهٗ لِيُخْرِجَكُمْ مِّنَ الظُّلُمٰتِ اِلَى النُّوْرِۗ وَكَانَ بِالْمُؤْمِنِيْنَ رَحِيْمًا (43). الاحزاب:41-43"],["p","Hai orang-orang yang beriman, berdzikirlah (dengan menyebut nama) Allah, dzikir yang sebanyak-banyaknya.(41)"],["p","Dan bertasbihlah kepada-Nya di waktu pagi dan petang. (42)"],["p","Dialah yang memberi rahmat kepadamu, dan malaikat-Nya (memohonkan ampunan untukmu), supaya Dia mengeluarkan kamu dari kegelapan kepada cahaya (yang terang). Dan adalah Dia Maha Penyayang kepada orang-orang yang beriman. (42) [QS. Al Ahzaab : 41 – 43]"],["a","اِنَّ فِيْ خَلْقِ السَّمٰوٰتِ وَالْاَرْضِ وَاخْتِلَافِ الَّيْلِ وَالنَّهَارِ لَاٰيٰتٍ لِّاُولِى الْاَلْبَابِۙ (190) الَّذِيْنَ يَذْكُرُوْنَ اللّٰهَ قِيَامًا وَّقُعُوْدًا وَّعَلٰى جُنُوْبِهِمْ وَيَتَفَكَّرُوْنَ فِيْ خَلْقِ السَّمٰوٰتِ وَالْاَرْضِۚ رَبَّنَا مَا خَلَقْتَ هٰذَا بَاطِلًاۚ سُبْحٰنَكَ فَقِنَا عَذَابَ النَّارِ(191). ال عمران : 190 - 191"],["p","Sesungguhnya dalam penciptaan langit dan bumi, dan silih bergantinya malam dan siang terdapat tanda-tanda bagi orang-orang yang berakal,(190)"],["p","(yaitu) orang-orang yang mengingat Allah sambil berdiri atau duduk atau dalam keadaan berbaring dan mereka memikirkan tentang penciptaan langit dan bumi (seraya berkata): \"Ya Tuhan kami, tiadalah Engkau menciptakan ini dengan sia-sia. Maha Suci Engkau, maka peliharalah kami dari siksa neraka. (191) [QS. Ali ‘Imraan : 190 – 191]"],["h","5) Merasa rugi apabila lalai dari ibadahnya, meskipun sedikit"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تُلْهِكُمْ اَمْوَالُكُمْ وَلَآ اَوْلَادُكُمْ عَنْ ذِكْرِ اللّٰهِ ۚ وَمَنْ يَّفْعَلْ ذٰلِكَ فَاُولٰۤىِٕكَ هُمُ الْخٰسِرُوْنَ. المنافقون :٩"],["p","Hai orang-orang yang beriman, janganlah harta-hartamu dan anak-anakmu melalaikan kamu dari mengingat Allah. Barangsiapa yang membuat demikian maka mereka itulah orang-orang yang rugi. [QS. Al Munaafiquun : 9]"],["a","رِجَالٌ لَّا تُلْهِيْهِمْ تِجَارَةٌ وَّلَا بَيْعٌ عَنْ ذِكْرِ اللّٰهِ وَاِقَامِ الصَّلٰوةِ وَاِيْتَاۤءِ الزَّكٰوةِ ۙ يَخَافُوْنَ يَوْمًا تَتَقَلَّبُ فِيْهِ الْقُلُوْبُ وَالْاَبْصَارُ ۙ . النور :٣٧"],["p","Laki-laki yang tidak dilalaikan oleh perniagaan dan tidak (pula) oleh jual beli dari mengingat Allah, dan (dari) mendirikan shalat, dan (dari) membayarkan zakat. Mereka takut kepada suatu hari yang (di hari itu) hati dan penglihatan menjadi guncang. [QS. An Nuur : 37]"],["h","6) Selalu rindu untuk beribadah kepada Allah"],["a","وَمَا خَلَقْتُ الْجِنَّ وَالْاِنْسَ اِلَّا لِيَعْبُدُوْنِ. الذاريات :٥٦"],["p","Dan Aku tidak menciptakan jin dan manusia melainkan supaya mereka menyembah-Ku. [QS. Adz Dzaariyaat : 56]"],["a","وَاِذْ اَخَذَ رَبُّكَ مِنْۢ بَنِيْٓ اٰدَمَ مِنْ ظُهُوْرِهِمْ ذُرِّيَّتَهُمْ وَاَشْهَدَهُمْ عَلٰٓى اَنْفُسِهِمْۚ اَلَسْتُ بِرَبِّكُمْۗ قَالُوْا بَلٰى ۛ شَهِدْنَا ۛ اَنْ تَقُوْلُوْا يَوْمَ الْقِيٰمَةِ اِنَّا كُنَّا عَنْ هٰذَا غٰفِلِيْنَۙ (172) اَوْ تَقُوْلُوْٓا اِنَّمَآ اَشْرَكَ اٰبَاۤؤُنَا مِنْ قَبْلُ وَكُنَّا ذُرِّيَّةً مِّنْۢ بَعْدِهِمْۚ اَفَتُهْلِكُنَا بِمَا فَعَلَ الْمُبْطِلُوْنَ(173 ) وَكَذٰلِكَ نُفَصِّلُ الْاٰيٰتِ وَلَعَلَّهُمْ يَرْجِعُوْنَ(174) .الاعراف :172 - 174"],["p","Dan (ingatlah), ketika Tuhanmu mengeluarkan keturunan anak-anak Adam dari sulbi mereka dan Allah mengambil kesaksian terhadap jiwa mereka (seraya berfirman): \"Bukankah Aku ini Tuhanmu?\" Mereka menjawab: \"Betul (Engkau Tuhan kami), kami menjadi saksi\". (Kami lakukan yang demikian itu) agar di hari kiamat kamu tidak mengatakan: \"Sesungguhnya kami (bani Adam) adalah orang-orang yang lengah terhadap ini (keesaan Tuhan)\",(172)"],["p","atau agar kamu tidak mengatakan: \"Sesungguhnya orang-orang tua kami telah mempersekutukan Tuhan sejak dahulu, sedang kami ini adalah anak-anak keturunan yang (datang) sesudah mereka. Maka apakah Engkau akan membinasakan kami karena perbuatan orang-orang yang sesat dahulu?\" (173)"],["p","Dan demikianlah Kami menjelaskan ayat-ayat itu, agar mereka kembali (kepada kebenaran). (174) [QS. Al ‘Araaf : 172 – 174]"],["a","وَمَآ اُمِرُوْٓا اِلَّا لِيَعْبُدُوا اللّٰهَ مُخْلِصِيْنَ لَهُ الدِّيْنَۙ حُنَفَاۤءَ وَيُقِيْمُوا الصَّلٰوةَ وَيُؤْتُوا الزَّكٰوةَ وَذٰلِكَ دِيْنُ الْقَيِّمَةِۗ . البينة :٥"],["p","Padahal mereka tidak disuruh kecuali supaya menyembah Allah dengan memurnikan ketha’atan kepada-Nya dalam (menjalankan) agama dengan lurus, dan supaya mereka mendirikan shalat dan menunaikan zakat; dan yang demikian itulah agama yang lurus. [QS. Al Bayyinah : 5]"],["p","7) Ketika shalat, hilang semua kerisauan dalam hatinya, karena menikmati lezatnya shalat."],["a","حَافِظُوْا عَلَى الصَّلَوٰتِ وَالصَّلٰوةِ الْوُسْطٰى وَقُوْمُوْا لِلّٰهِ قٰنِتِيْنَ.البقرة :٢٣٨"],["p","Peliharalah segala shalat (mu), dan (peliharalah) shalat wusthaa. Berdirilah karena Allah (dalam shalatmu) dengan khusyu’. [QS. Al Baqarah : 238]"],["a","اُتْلُ مَآ اُوْحِيَ اِلَيْكَ مِنَ الْكِتٰبِ وَاَقِمِ الصَّلٰوةَۗ اِنَّ الصَّلٰوةَ تَنْهٰى عَنِ الْفَحْشَاۤءِ وَالْمُنْكَرِ ۗ وَلَذِكْرُ اللّٰهِ اَكْبَرُ ۗ وَاللّٰهُ يَعْلَمُ مَا تَصْنَعُوْنَ. العنكبوت :٤٥"],["p","Bacalah apa yang telah diwahyukan kepadamu, yaitu Al Kitab (Al Qur'an) dan dirikanlah shalat. Sesungguhnya shalat itu mencegah dari (perbuatan-perbuatan) keji dan mungkar. Dan sesungguhnya mengingat Allah (shalat) adalah lebih besar (keutamaannya dari ibadah-ibadah yang lain). Dan Allah mengetahui apa yang kamu kerjakan. [QS. Al ‘Ankabuut : 45]"],["a","اِنَّنِيْٓ اَنَا اللّٰهُ لَآ اِلٰهَ اِلَّآ اَنَا۠ فَاعْبُدْنِيْۙ وَاَقِمِ الصَّلٰوةَ لِذِكْرِيْ. طه:١٤"],["p","Sesungguhnya Aku ini adalah Allah, tidak ada Tuhan (yang hak) selain Aku, maka sembahlah Aku dan dirikanlah shalat untuk mengingat Aku. [QS. Thaahaa : 14]"],["a","وَاَقِمِ الصَّلٰوةَ طَرَفَيِ النَّهَارِ وَزُلَفًا مِّنَ الَّيْلِ ۗ اِنَّ الْحَسَنٰتِ يُذْهِبْنَ السَّيِّاٰتِۗ ذٰلِكَ ذِكْرٰى لِلذَّاكِرِيْنَ. هود :١١٤"],["p","Dan dirikanlah shalat itu pada kedua tepi siang (pagi dan petang) dan pada bahagian permulaan daripada malam. Sesungguhnya perbuatan-perbuatan yang baik itu menghapuskan (dosa) perbuatan-perbuatan yang buruk. Itulah peringatan bagi orang-orang yang ingat. [QS. Huud : 114]"],["a","عَنْ اَبِيْ هُرَيْرَةَ اَنَّهُ سَمِعَ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: اَرَأَيْتُمْ لَوْ اَنَّ نَهْرًا بِبَابِ اَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ. هَلْ يَبْقَى مِنْ دَرَنِهِ شَيْءٌ؟ قَالُوْا: لَا يَبْقَى مِنْ دَرَنِهِ شَيْءٌ. قَالَ: فَذٰلِكَ مَثَلُ الصَّلَوَاتِ الْخَمْسِ يَـمْحُو اللهُ بِـهِنَّ الْخَطَايَا. مسلم 1: 462"],["p","Dari Abu Hurairah bahwasanya ia mendengar Rasulullah SAW bersabda, \"Bagaimana pendapat kalian seandainya ada sebuah sungai di depan pintu seseorang diantara kalian, lalu ia mandi di dalamnya sehari lima kali. Apakah masih ada daki (di badannya) sedikitpun ?\". Para shahabat menjawab, \"Tentu sudah tidak ada dakinya sedikitpun\". Beliau bersabda, \"Demikian itulah perumpamaan shalat lima (waktu), Allah menghapus dosa-dosa dengannya\". [HR. Muslim juz 1, hal. 462, no. 283]"],["a","عَنِ الْبَيَاضِيِّ اَنَّ رَسُوْلَ اللهِ ﷺ خَرَجَ عَلَى النَّاسِ وَهُمْ يُصَلُّوْنَ، وَقَدْ عَلَتْ اَصْوَاتُـهُمْ بِالْقِرَاءَةِ، فَقَالَ: اِنَّ الْمُصَلِّيَ يُنَاجِيْ رَبَّهُ فَلْيَنْظُرْ بِـمَا يُنَاجِيْهِ بِهِ وَلَا يَجْهَرْ بَعْضُكُمْ عَلَى بَعْضٍ بِالْقُرْاٰنِ.مالك فى الموطأ 1:80"],["p","Dari Al-Bayaadliy bahwasanya Rasulullah SAW keluar mendatangi para shahabat yang sedang shalat (malam), mereka mengeraskan suara bacaan, maka beliau bersabda, “Sesungguhnya orang yang shalat itu sedang bermunajat dengan Tuhannya, maka hendaklah ia memperhatikan apa yang ia munajatkan kepada-Nya, dan janganlah sebagian kalian mengeraskan bacaan Al-Qur’an atas sebagian yang lain, karena mengganggu yang lain”. [HR. Maalik dalam Al-Muwaththa’ juz 1, hal. 80]"],["h","8) Idolanya hanya satu, yaitu bertaqorrub kepada Allah"],["a","وَكُنْتُمْ اَزْوَاجًا ثَلٰثَةً (7) فَاَصْحٰبُ الْمَيْمَنَةِۙ مَآ اَصْحٰبُ الْمَيْمَنَةِ (8) وَاَصْحٰبُ الْمَشْـَٔمَةِ ۙ مَآ اَصْحٰبُ الْمَشْـَٔمَةِ (9) وَالسّٰبِقُوْنَ السّٰبِقُوْنَۙ (10) اُولٰۤىِٕكَ الْمُقَرَّبُوْنَۚ(١١). الواقعة : 7 - 11"],["p","dan kamu menjadi tiga golongan.(7)"],["p","Yaitu golongan kanan. Alangkah mulianya golongan kanan itu. (8)"],["p","Dan golongan kiri. Alangkah sengsaranya golongan kiri itu.(9)"],["p","Dan orang-orang yang paling dahulu beriman, merekalah yang paling dulu (masuk surga). (10)"],["p","Mereka itulah orang yang didekatkan (kepada Allah). (11) [QS. Al Waaqi’ah : 7 – 11]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ ﷺ: يَقُوْلُ اللهُ تَعَالَى: اَنَا عِنْدَ ظَنِّ عَبْدِيْ بِيْ وَاَنَا مَعَهُ اِذَا ذَكَرَنِيْ. فَاِنْ ذَكَرَنِيْ فِيْ نَفْسِهِ ذَكَرْتُهُ فِيْ نَفْسِيْ، وَاِنْ ذَكَرَنِيْ فِيْ مَلَأٍ ذَكَرْتُهُ فِيْ مَلَأٍ خَيْرٍ مِنْهُمْ. وَاِنْ تَقَرَّبَ اِلَيَّ بِشِبْرٍ تَقَرَّبْتُ اِلَيْهِ ذِرَاعًا. وَاِنْ تَقَرَّبَ اِلَيَّ ذِرَاعًا تَقَرَّبْتُ اِلَيْهِ بَاعًا. وَاِنْ اَتَانِيْ يَمْشِيْ اَتَيْتُهُ هَرْوَلَةً. البخارى 8: 171"],["p","Dari Abu Hurairah RA, ia berkata : Nabi SAW bersabda, \"Allah Ta'aalaa berfirman, \"Aku menurut persangkaan hamba-Ku terhadap-Ku, dan Aku besertanya apabila ia mengingat-Ku. Maka jika ia mengingat-Ku di hatinya, Aku pun mengingatnya pada diri-Ku, Jika ia mengingat (menyebut)-Ku pada sekumpulan orang, maka Aku menyebutnya dalam sekumpulan yang lebih baik dari pada mereka. Dan jika ia mendekat kepada-Ku sejengkal, maka Aku akan mendekat kepadanya sehasta. Jika ia mendekat kepada-Ku sehasta, maka Aku akan mendekat kepadanya sedepa. Dan jika ia datang kepada-Ku dengan berjalan, maka Aku akan datang kepadanya dengan berlari\". [HR. Bukhari juz 8, hal. 171]"],["a","عَنْ اَبِيْ ذَرٍّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: يَقُوْلُ اللهُ عَزَّ وَجَلَّ: مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ اَمْثَالِهَا وَاَزِيْدُ، وَمَنْ جَاءَ بِالسَّيِّئَةِ فَجَزَاؤُهُ سَيِّئَةٌ مِثْلُهَا اَوْ اَغْفِرُ، وَمَنْ تَقَرَّبَ مِنِّى شِبْرًا تَقَرَّبْتُ مِنْهُ ذِرَاعًا, وَمَنْ تَقَرَّبَ مِنِّى ذِرَاعًا تَقَرَّبْتُ مِنْهُ بَاعًا. وَمَنْ اَتَانِى يَمْشِى اَتَيْتُهُ هَرْوَلَةً. وَمَنْ لَقِيَنِى بِقُرَابِ الْاَرْضِ خَطِيْئَةً لَا يُشْرِكُ بِىْ شَيْئًا لَقِيْتُهُ بِمِثْلِهَا مَغْفِرَةً. مسلم 4: 2068 رقم 22"],["p","Dari Abu Dzarr, ia berkata :Rasulullah SAW bersabda, Allah 'Azza wa Jalla berfirman, \"Barangsiapa melakukan kebaikan,maka ia mendapatkan pahala sepuluh kali lipat atau lebih. Dan barangsiapa melakukan kajahatan, maka ia mendapat balasan yang setimpal dengan kejahatannya, atau Aku mengampuninya. Barangsiapa mendekat kepada-Ku sejengkal, maka Aku akan mendekat kepadanya sehasta. Dan barangsiapa mendekat kepada-Ku sehasta, maka Aku akan mendekat kepadanya sedepa. Dan barangsiapa yang datang kepada-Ku dengan berjalan, maka Aku akan datang kepadanya dengan berlari. Dan barangsiapa yang menghadap kepada-Ku dengan kesalahan sepenuh bumi, sedang ia tidak menyekutukan Aku dengan sesuatu, maka Aku akan memberinya ampunan yang sama dengan kesalahan-kesalahannya\". [HR. Muslim juz 4, hal. 2068, no. 22]"],["h","9) Tidak ingin kehilangan waktunya secara sia sia"],["a","وَالْعَصْرِۙ (1) اِنَّ الْاِنْسَانَ لَفِيْ خُسْرٍۙ (2) اِلَّا الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ وَتَوَاصَوْا بِالْحَقِّ ۙ وَتَوَاصَوْا بِالصَّبْرِ (3). العصر : 1-3"],["p","Demi masa. (1)"],["p","Sesungguhnya manusia itu benar-benar berada dalam kerugian, (2)"],["p","kecuali orang-orang yang beriman dan mengerjakan amal shaleh dan nasihat menasihati supaya mentha’ati kebenaran dan nasihat menasihati supaya menetapi keshabaran. (3) [QS. Al ‘Ashr : 1-3]"],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ لِرَجُلٍ وَهُوَ يَعِظُهُ: اِغْتَنِمْ خَمْسًا قَبْلَ خَمْسٍ: شَبَابَكَ قَبْلَ هَرَمِكَ، وَصِحَّتَكَ قَبْلَ سَقَمِكَ، وَغِنَاكَ قَبْلَ فَقْرِكَ، وَفَرَاغَكَ قَبْلَ شُغْلِكَ، وَحَيَاتَكَ قَبْلَ مَوْتِكَ. البيهقى فى شعب الايمان 7: 263، رقم: 10248"],["p","Dari Ibnu Abbas, ia berkata : Rasulullah SAW bersabda kepada seorang laki-laki, pada waktu itu beliau menasehatinya, “Gunakanlah lima (kesempatan) sebelum datangnya lima (kesempitan)"],["p","1. Gunakan masa mudamu sebelum datang masa tuamu,"],["p","2. Gunakan masa sehatmu sebelum datang masa sakitmu,"],["p","3. Gunaan masa kayamu sebelum datang masa faqir (miskin)mu,"],["p","4. Gunakan masa longgarmu sebelum datang masa sibukmu,"],["p","5. Gunakan masa hidupmu sebelum datang kematianmu”."],["p","[HR. Baihaqiy dalam Syu'abul iimaan juz 7, hal.263, no. 10248]"],["p","10) Selalu berusaha memperbaiki diri, memperbaiki amal amalnya penuh ikhlash dan mengikuti tuntunan Allah dan Rasul Nya."],["a","قُلْ اِنَّ صَلَاتِيْ وَنُسُكِيْ وَمَحْيَايَ وَمَمَاتِيْ لِلّٰهِ رَبِّ الْعٰلَمِيْنَۙ(١٦٢) لَا شَرِيْكَ لَهٗ ۚ وَبِذٰلِكَ اُمِرْتُ وَاَنَا۠ اَوَّلُ الْمُسْلِمِيْنَ (1٦٣). الانعام : 162-163"],["p","Katakanlah: \"Sesungguhnya shalatku, ibadahku, hidup dan matiku hanyalah untuk Allah, Tuhan semesta alam, (162)"],["p","tiada sekutu bagi-Nya; dan demikian itulah yang diperintahkan kepadaku dan aku adalah orang yang pertama-tama menyerahkan diri (kepada Allah)\". (163) [QS. Al An’aam : 162 – 163]"],["a","وَالَّذِيْنَ اجْتَنَبُوا الطَّاغُوْتَ اَنْ يَّعْبُدُوْهَا وَاَنَابُوْٓا اِلَى اللّٰهِ لَهُمُ الْبُشْرٰىۚ فَبَشِّرْ عِبَادِۙ (١٧) الَّذِيْنَ يَسْتَمِعُوْنَ الْقَوْلَ فَيَتَّبِعُوْنَ اَحْسَنَهٗ ۗ اُولٰۤىِٕكَ الَّذِيْنَ هَدٰىهُمُ اللّٰهُ وَاُولٰۤىِٕكَ هُمْ اُولُوا الْاَلْبَابِ(١٨). الزمر: 17-18"],["p","Dan orang-orang yang menjauhi thaghut (yaitu) tidak menyembahnya dan kembali kepada Allah, bagi mereka berita gembira; sebab itu sampaikanlah berita itu kepada hamba-hamba-Ku, (17)"],["p","yang mendengarkan perkataan lalu mengikuti apa yang paling baik di antaranya. Mereka itulah orang-orang yang telah diberi Allah petunjuk dan mereka itulah orang-orang yang mempunyai akal. (18) [QS. Az Zumar : 17-18]"],["a","قُلْ اِنْ كُنْتُمْ تُحِبُّوْنَ اللّٰهَ فَاتَّبِعُوْنِيْ يُحْبِبْكُمُ اللّٰهُ وَيَغْفِرْ لَكُمْ ذُنُوْبَكُمْ ۗ وَاللّٰهُ غَفُوْرٌ رَّحِيْمٌ (٣١) قُلْ اَطِيْعُوا اللّٰهَ وَالرَّسُوْلَ ۚ فَاِنْ تَوَلَّوْا فَاِنَّ اللّٰهَ لَا يُحِبُّ الْكٰفِرِيْنَ (٣٢). ال عمران: 31-32"],["p","Katakanlah: \"Jika kamu (benar-benar) mencintai Allah, ikutilah aku, niscaya Allah mengasihi dan mengampuni dosa-dosamu.\" Allah Maha Pengampun lagi Maha Penyayang. (31)"],["p","Katakanlah: \"Tha’atilah Allah dan Rasul-Nya; jika kamu berpaling, maka sesungguhnya Allah tidak menyukai orang-orang kafir\". (32) [QS. Ali ‘Imraan : 31-32]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اِنَّ اللهَ لَا يَنْظُرُ اِلىَ صُوَرِكُمْ وَاَمْوَالِكُمْ وَلٰكِنْ يَنْظُرُ اِلىَ قُلُوْبِكُمْ وَاَعْمَالِكُمْ. مسلم 4: 1987 رقم 34"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Sesungguhnya Allah tidak melihat (menilai) bentuk tubuhmu dan harta-bendamu, tetapi Allah melihat (menilai) pada hatimu dan amalmu\". [HR. Muslim juz 4, hal. 1987, no. 34]"],["p","Demikianlah semoga bermanfaat dan semoga Allah mengampuni kita. Aamiin!"],["p","--oo0oo--"]],"c20220116_1271":[["p","Ahad, 16 Januari 2022/13 Jumaadal Aakhirah 1443 Brosur No.: 2066/2106/IA"],["p","Menunaikan amanat dan menjauhi khianat"],["p","Amaanah adalah mashdar dari :"],["a","أَمُنَ – يَأْمُنُ –أَمَانَةً : ضِدُّ خَانَ فَهُوَ أَمِيْنٌ (المنجد)"],["p","Yang berarti jujur, dapat dipercaya, kebalikan dari khiyanat, orangnya disebut “amiin” (orang yang bisa dipercaya)."],["p","Amaanah bisa pula berarti titipan, bisa pula berarti segala perintah Allah kepada hamba Nya."],["p","Firman Allah SWT :"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تَخُوْنُوا اللّٰهَ وَالرَّسُوْلَ وَتَخُوْنُوْٓا اَمٰنٰتِكُمْ وَاَنْتُمْ تَعْلَمُوْنَ. الانفال:27"],["p","Hai orang-orang yang beriman, janganlah kamu mengkhianati Allah dan Rasul dan janganlah kamu mengkhianati amanat-amanat yang dipercayakan kepadamu sedang kamu mengetahui. [QS. Al-Anfaal : 27]"],["a","اِنَّ اللّٰهَ يَأْمُرُكُمْ اَنْ تُؤَدُّوا الْاَمٰنٰتِ اِلٰٓى اَهْلِهَاۙ وَاِذَا حَكَمْتُمْ بَيْنَ النَّاسِ اَنْ تَحْكُمُوْا بِالْعَدْلِ ۗ اِنَّ اللّٰهَ نِعِمَّا يَعِظُكُمْ بِهٖ ۗ اِنَّ اللّٰهَ كَانَ سَمِيْعًاۢ بَصِيْرًا . النساء:58"],["p","Sesungguhnya Allah menyuruh kamu menyampaikan amanat kepada yang berhak menerimanya, dan (menyuruh kamu) apabila menetapkan hukum di antara manusia supaya kamu menetapkan dengan adil. Sesungguhnya Allah memberi pengajaran yang sebaik-baiknya kepadamu. Sesungguhnya Allah adalah Maha Mendengar lagi Maha Melihat. [QS. An-Nisaa' : 58]"],["a","وَالَّذِيْنَ هُمْ لِاَمٰنٰتِهِمْ وَعَهْدِهِمْ رَاعُوْنَ ۙ(8) وَالَّذِيْنَ هُمْ عَلٰى صَلَوٰتِهِمْ يُحَافِظُوْنَ ۘ (9) اُولٰۤىِٕكَ هُمُ الْوَارِثُوْنَ ۙ (10) الَّذِيْنَ يَرِثُوْنَ الْفِرْدَوْسَۗ هُمْ فِيْهَا خٰلِدُوْنَ(11) المؤمنون:8-11"],["p","Dan orang-orang yang memelihara amanat-amanat (yang dipikulnya) dan janjinya, (8)"],["p","dan orang-orang yang memelihara shalatnya. (9)"],["p","Mereka itulah orang-orang yang akan mewarisi, (10)"],["p","(ya’ni) yang akan mewarisi surga Firdaus. Mereka kekal di dalamnya. (11) [QS. Al-Mukminuun : 8-11]"],["a","وَالَّذِيْنَ هُمْ لِاَمٰنٰتِهِمْ وَعَهْدِهِمْ رَاعُوْنَۖ (32) وَالَّذِيْنَ هُمْ بِشَهٰدٰتِهِمْ قَاۤىِٕمُوْنَۖ (33) وَالَّذِيْنَ هُمْ عَلٰى صَلَاتِهِمْ يُحَافِظُوْنَۖ (34) اُولٰۤىِٕكَ فِيْ جَنّٰتٍ مُّكْرَمُوْنَ ࣖ ۗ (35) المعارج:32-35"],["p","Dan orang-orang yang memelihara amanat-amanat (yang dipikulnya) dan janjinya. (32)"],["p","Dan orang-orang yang memberikan kesaksiannya. (33)"],["p","Dan orang-orang yang memelihara shalatnya. (34)"],["p","Mereka itu (kekal) di surga lagi dimuliakan. (35) [QS. Al-Ma’aarij : 32-35]"],["a","اِنَّا عَرَضْنَا الْاَمَانَةَ عَلَى السَّمٰوٰتِ وَالْاَرْضِ وَالْجِبَالِ فَاَبَيْنَ اَنْ يَّحْمِلْنَهَا وَاَشْفَقْنَ مِنْهَا وَحَمَلَهَا الْاِنْسَانُۗ اِنَّهٗ كَانَ ظَلُوْمًا جَهُوْلًاۙ(72) لِّيُعَذِّبَ اللّٰهُ الْمُنٰفِقِيْنَ وَالْمُنٰفِقٰتِ وَالْمُشْرِكِيْنَ وَالْمُشْرِكٰتِ وَيَتُوْبَ اللّٰهُ عَلَى الْمُؤْمِنِيْنَ وَالْمُؤْمِنٰتِۗ وَكَانَ اللّٰهُ غَفُوْرًا رَّحِيْمًا ࣖ . (73) الاحزاب: 72- 73"],["p","Sesungguhnya Kami telah menawarkan amanat kepada langit, bumi dan gunung-gunung, maka semuanya enggan untuk memikulnya dan mereka takut akan mengkhianatinya, dan dipikullah amanat itu oleh manusia. Sesungguhnya manusia itu amat dhalim dan amat bodoh. (72)"],["p","sehingga Allah mengadzab orang-orang munafik laki-laki dan perempuan dan orang-orang musyrikin laki-laki dan perempuan; dan sehingga Allah menerima taubat orang-orang mukmin laki-laki dan perempuan. Dan adalah Allah Maha Pengampun lagi Maha Penyayang. (73) [QS. Al-Ahzaab : 72-73]"],["a","اِنَّ اللّٰهَ يُدَافِعُ عَنِ الَّذِيْنَ اٰمَنُوْاۗ اِنَّ اللّٰهَ لَا يُحِبُّ كُلَّ خَوَّانٍ كَفُوْرٍ ࣖ . الحج: 38"],["p","Sesungguhnya Allah membela orang-orang yang telah beriman. Sesungguhnya Allah tidak menyukai tiap-tiap orang yang berkhianat lagi mengingkari ni’mat. [QS. Al-Hajj : 38]"],["a","اِنَّآ اَنْزَلْنَآ اِلَيْكَ الْكِتٰبَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَآ اَرٰىكَ اللّٰهُ ۗ وَلَا تَكُنْ لِّلْخَاۤىِٕنِيْنَ خَصِيْمًا (105) وَّاسْتَغْفِرِ اللّٰهَ ۗ اِنَّ اللّٰهَ كَانَ غَفُوْرًا رَّحِيْمًاۚ (106) وَلَا تُجَادِلْ عَنِ الَّذِيْنَ يَخْتَانُوْنَ اَنْفُسَهُمْ ۗ اِنَّ اللّٰهَ لَا يُحِبُّ مَنْ كَانَ خَوَّانًا اَثِيْمًاۙ (107). النساء:105 - 107"],["p","Sesungguhnya Kami telah menurunkan Kitab kepadamu dengan membawa kebenaran, supaya kamu mengadili antara manusia dengan apa yang telah Allah wahyukan kepadamu, dan janganlah kamu menjadi penantang (orang yang tidak bersalah), karena (membela) orang-orang yang khianat, (105)"],["p","dan mohonlah ampun kepada Allah. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang. (106)"],["p","Dan janganlah kamu berdebat (untuk membela) orang-orang yang mengkhianati dirinya. Sesungguhnya Allah tidak menyukai orang-orang yang selalu berkhianat lagi bergelimang dosa,(107) [QS. An-Nisaa’ : 105 - 107]"],["p","Hadits-hadits Nabi SAW :"],["a","عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ ﷺ: خَيْرُكُمْ قَرْنِيْ ثُمَّ الَّذِيْنَ يَلُوْنَهُمْ ثُمَّ الَّذِيْنَ يَلُوْنَهُمْ. قَالَ عِمْرَانُ: لَا اَدْرِيْ اَذَكَرَ النَّبِيُّ ﷺ بَعْدُ قَرْنَيْنِ اَوْ ثَلَاثَةً. قَالَ النَّبِيُّ ﷺ: اِنَّ بَعْدَكُمْ قَوْمًا يَخُوْنُوْنَ وَلَا يُؤْتَمَنُوْنَ، وَيَشْهَدُوْنَ وَلَا يُسْتَشْهَدُوْنَ، وَيَنْذِرُوْنَ وَلَا يَفُوْنَ، وَيَظْهَرُ فِيْهِمُ السِّمَنُ. البخارى 3: 151"],["p","Dari 'Imran bin Hushain RA, ia berkata : Nabi SAW bersabda, \"Sebaik-baik kalian ialah orang-orang pada zamanku, kemudian orang-orang berikutnya, kemudian orang-orang berikutnya lagi. 'Imran berkata : Aku tidak tahu apakah Nabi SAW sesudah itu menyebutkan dua generasi atau tiga generasi. Nabi SAW bersabda, \"Sesungguhnya sesudah kalian akan ada orang-orang yang mereka itu berkhianat dan tidak dapat dipercaya, mereka bersaksi padahal tidak diminta menjadi saksi, mereka bernadzar tetapi tidak melaksanakan (nadzarnya), dan tampaklah kegemukan di kalangan mereka (karena memakan harta tidak memperdulikan halal-haramnya). [HR. Bukhari juz 3, hal. 151]"],["a","عَنْ اَبِيْ هُرَيْرَةَ عَنِ النَّبِيِّ ﷺ قَالَ: اٰيَةُ الْمُنَافِقِ ثَلَاثٌ. اِذَا حَدَّثَ كَذَبَ وَاِذَا وَعَدَ اَخْلَفَ وَاِذَا ائْتُمِنَ خَانَ. البخارى 1: 14"],["p","Dari Abu Hurairah dari Nabi SAW, beliau bersabda, \"Tanda orang munafiq itu ada tiga, yaitu : 1. Apabila berbicara ia berdusta, 2. Apabila berjanji menyelisihi dan 3. Apabila diberi amanat ia khianat”. [HR. Bukhari juz 1, hal. 14]"],["a","عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو اَنَّ النَّبِيَّ ﷺ قَالَ: اَرْبَعٌ مَنْ كُنَّ فِيْهِ كَانَ مُنَافِقًا خَالِصًا، وَمَنْ كَانَتْ فِيْهِ خَصْلَةٌ مِنْهُنَّ كَانَتْ فِيْهِ خَصْلَةٌ مِنَ النِّفَاقِ حَتَّى يَدَعَهَا. اِذَا ائْتُمِنَ خَانَ، وَاِذَا حَدَّثَ كَذَبَ، وَاِذَا عَاهَدَ غَدَرَ، وَاِذَا خَاصَمَ فَجَرَ. البخارى 1: 14"],["p","Dari Abdullah bin 'Amr, bahwasanya Nabi SAW bersabda, \"Ada empat hal, barangsiapa yang empat hal itu ada padanya maka ia adalah orang munafiq yang sebenarnya. Dan barangsiapa ada padanya satu bagian dari yang empat hal itu berarti ada padanya satu bagian dari kemunafiqan sehingga ia meninggalkannya, yaitu : 1. Apabila diberi amanat ia khianat, 2. Apabila berbicara ia berdusta, 3. Apabila berjanji menyelisihi dan 4. Apabila bertengkar ia curang. [HR. Bukhari juz 1, hal. 14]"],["a","عَنْ اَنــَسِ بْنِ مَالِكٍ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَـقُوْلُ: ثَلَاثٌ مَنْ كُنَّ فِـيْهِ فَهُوَ مُنَافِقٌ وَاِنْ صَامَ وَصَلَّى وَحَجَّ وَاعْتَمَرَ، وَقَالَ اِنِّيْ مُسْلِمٌ. اِذَا حَدَّثَ كَذَبَ وَاِذَا وَعَدَ اَخْلَفَ وَاِذَا ائْـتُمِنَ خَانَ. ابو يعلى 3: 396، رقم: 4084"],["p","Dari Anas bin Maalik, ia berkata : Saya mendengar Rasulullah SAW bersabda : \"Ada tiga perkara yang apabila tiga perkara itu ada padanya maka ia adalah orang munafiq, meskipun ia puasa, shalat, hajji, 'umrah dan mengatakan : \"Sesungguhnya saya orang Islam\", yaitu : 1. Apabila berbicara ia berdusta, 2. Apabila berjanji menyelisihi dan 3. Apabila diberi amanat ia khianat. [HR. Abu Ya'la juz 3, hal. 396, no. 4084, dla'if karena dalam sanadnya ada perawi bernama Yazid Ar-Raqaasyiy]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: بَيْنَمَا النَّبِيُّ ﷺ فِيْ مَجْلِسٍ يُحَدِّثُ الْقَوْمَ جَاءَهُ اَعْرَابِيٌّ فَقَالَ: مَتَى السَّاعَةُ؟ فَمَضَى رَسُوْلُ اللهِ ﷺ يُحَدِّثُ، فَقَالَ بَعْضُ الْقَوْمِ سَمِعَ مَا قَالَ فَكَرِهَ مَا قَالَ. وَقَالَ بَعْضُهُمْ بَلْ لَمْ يَسْمَعْ، حَتَّى اِذَا قَضَى حَدِيْثَهُ قَالَ: اَيْنَ اُرَاهُ السَّائِلُ عَنِ السَّاعَةِ؟ قَالَ: هَا اَنَا يَا رَسُوْلَ اللهِ. قَالَ: فَاِذَا ضُيِّعَتِ الْاَمَانَةُ فَانْتَظِرِ السَّاعَةَ. قَالَ: كَيْفَ اِضَاعَتُهَا؟ قَالَ: اِذَا وُسِّدَ الْاَمْرُ اِلَى غَيْرِ اَهْلِهِ فَانْتَظِرِ السَّاعَةَ. البخارى 1: 21"],["p","Dari Abu Hurairah, ia berkata : Pada suatu ketika Nabi SAW berada di majlis sedang berbicara dengan suatu kaum, tiba-tiba datang seorang 'Arab gunung, lalu bertanya, \"Kapan terjadinya kehancuran ?\". Rasulullah SAW terus saja berbicara dengan orang banyak. Sebagian orang ada yang berkata, \"Beliau mendengar pertanyaan itu, tetapi beliau tidak suka dengan pertanyaan tersebut\". Sebagian yang lain berkata : \"Beliau tidak mendengar pertanyaan itu\", sehingga setelah beliau menyelesaikan pembicaraannya dengan orang banyak, lalu beliau bertanya, \"Di mana orang yang bertanya tentang (hari) kehancuran tadi ?\". (Orang 'Arab gunung yang bertanya tadi) menjawab, \"Saya ya Rasulullah\". Beliau SAW bersabda, \"Apabila amanah disia-siakan, maka tunggulah kehancurannya\". Orang itu bertanya, \"Bagaimanakah menyia-nyiakan amanah itu ?\". Nabi SAW menjawab, \"Apabila urusan diserahkan kepada orang yang bukan ahlinya, maka tunggulah kehancurannya\". [HR. Bukhari juz 1, hal. 21]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اِذَا ضُيِّعَتِ الْاَمَانَةُ فَانْتَظِرِ السَّاعَةَ. قَالَ: كَيْفَ اِضَاعَتُهَا يَا رَسُوْلَ اللهِ؟ قَالَ: اِذَا اُسْنِدَ الْاَمْرُ اِلَى غَيْرِ اَهْلِهِ فَانْتَظِرِ السَّاعَةَ. البخارى 7: 188"],["p","Dari Abu Hurairah RA, ia berkata : Rasulullah SAW bersabda, \"Apabila amanah sudah disia-siakan, maka tunggulah kehancurannya\". Shahabat bertanya, \"Bagaimanakah menyia-nyiakan amanah itu ya Rasulullah ?\". Rasulullah SAW bersabda, \"Apabila suatu urusan diserahkan kepada orang yang bukan ahlinya, maka tunggulah kehancurannya\". [HR. Bukhari juz 7. Hal. 188]"],["a","عَنْ اَبِيْ ذَرٍّ قَالَ، قُلْتُ: يَا رَسُوْلَ اللهِ، اَلَا تَسْتَعْمِلُنِىْ؟ قَالَ: فَضَرَبَ بِيَدِهِ عَلَى مَنْكِبِيَّ ثُمَّ قَالَ: يَا اَبَا ذَرٍّ، اِنَّكَ ضَعِيْفٌ، وَاِنَّهَا اَمَانَةٌ، وَاِنَّهَا يَوْمَ الْقِيَامَةِ خِزْيٌ وَنَدَامَةٌ، اِلَّا مَنْ اَخَذَهَا بِحَقِّهَا وَاَدَّى الَّذِيْ عَلَيْهِ فِيْهَا. مسلم 3: 1457"],["p","Dari Abu Dzarr, ia berkata : Saya berkata kepada Rasulullah SAW, \"Ya Rasulullah, mengapa engkau tidak memberi jabatan kepadaku ?\". Maka Rasulullah SAW menepuk punggungku dengan tangan beliau lalu bersabda, \"Wahai Abu Dzarr, sesungguhnya kamu orang yang lemah, sesungguhnya jabatan itu adalah amanat, dan sesungguhnya pada hari qiyamat nanti akan menjadi kehinaan dan penyesalan, kecuali orang yang mengambilnya dengan haknya dan bisa menunaikan kewajibannya\". [HR. Muslim juz 3, hal. 1457, no. 16]"],["a","عَنْ اَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَنَا رَسُوْلُ اللهِ ﷺ فَقَالَ: لَا اِيْمَانَ لِمَنْ لَا اَمَانَةَ لَهُ وَلَا دِيْنَ لِمَنْ لَا عَهْدَ لَهُ. البيهقى 9: 231"],["p","Dari Anas (bin Maalik) RA, ia berkata : Rasulullah SAW pernah berkhutbah kepada kami dan beliau bersabda, \"Tidak (sempurna) iman bagi orang yang tidak ada amanat baginya, dan tidak ada agama bagi orang yang janjinya tidak bisa dipercaya\". [HR. Baihaqi juz 9, hal. 231]"],["a","عَنْ عُبَادَةَ بْنِ الصَّامِتِ اَنَّ النَّبِيَّ ﷺ قَالَ: اِضْمَنُوْا لِيْ سِتًّا مِنْ اَنْفُسِكُمْ، اَضْمَنْ لَكُمُ الْجَنَّةَ. اُصْدُقُوْا اِذَا حَدَّثْتُمْ، وَاَوْفُوْا اِذَا وَعَدْتُمْ، وَاَدُّوْا اِذَا ائْتُمِنْتُمْ، وَاحْفَظُوْا فُرُوْجَكُمْ، وَغُضُّوْا اَبْصَارَكُمْ، وَكُفُّوْا اَيْدِيَكُمْ. احمد 8: 412، رقم: 22821"],["p","Dari 'Ubaadah bin Shaamit, bahwasanya Nabi SAW bersabda, \"Hendaklah kalian menjamin padaku enam perkara dari diri kalian, niscaya aku menjamin surga bagi kalian : 1. Jujurlah apabila kalian berbicara, 2. Sempurnakanlah (janji kalian) apabila kalian berjanji, 3. Tunaikanlah apabila kalian diberi amanat, 4. Jagalah kemaluan kalian, 5. Tundukkanlah pandangan kalian (dari ma'shiyat) dan 6. Tahanlah tangan kalian (dari hal yang tidak baik)\". [HR. Ahmad juz 8, hal. 412, no. 22821, munqathi' karena Al-Muththalib tidak mendengar dari 'Ubaadah bin Ash-Shaamit]"],["a","عَنْ عُبَادَةَ بْنِ الصَّامِتِ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اِضْمَنُوْا لِيْ سِتًّا، اَضْمَنْ لَكُمُ الْجَنَّةَ. اُصْدُقُوْا اِذَا حَدَّثْتُمْ، وَاَوْفُوْا اِذَا وَعَدْتُمْ، وَاَدُّوْا اِذَا ائْتُمِنْتُمْ، وَاحْفَظُوْا فُرُوْجَكُمْ، وَغُضُّوْا اَبْصَارَكُمْ، وَكُفُّوْا اَيْدِيَكُمْ. ابن حبان 1: 506، رقم: 271"],["p","Dari 'Ubaadah bin Shaamit, bahwasanya Rasulullah SAW bersabda, \"Hendaklah kalian menjamin padaku enam perkara, niscaya aku menjamin surga bagi kalian : 1. Jujurlah apabila kalian berbicara, 2. Sempurnakanlah (janji kalian) apabila kalian berjanji, 3. Tunaikanlah apabila kalian diberi amanat, 4. Jagalah kemaluan kalian, 5. Tundukkanlah pandangan kalian (dari ma'shiyat) dan 6. Tahanlah tangan kalian (dari hal yang tidak baik). [HR. Ibnu Hibban juz 1, hal. 506, no. 271, munqathi' karena Al-Muththalib tidak mendengar dari 'Ubaadah bin Ash-Shaamit]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: قَالَ اللهُ: ثَلَاثَةٌ اَنَا خَصْمُهُمْ يَوْمَ الْقِيَامَةِ، رَجُلٌ اَعْطَى بِيْ ثُمَّ غَدَرَ، وَرَجُلٌ بَاعَ حُرًّا فَأَكَلَ ثَمَنَهُ، وَرَجُلٌ اِسْتَأْجَرَ اَجِيْرًا فَاسْتَوْفَى مِنْهُ وَلَـمْ يُعْطِهِ اَجْرَهُ. البخارى 3: 41"],["p","Dari Abu Hurairah RA, dari Nabi SAW, beliau bersabda : \"Allah berfirman : Ada tiga golongan yang besuk pada hari qiyamat menjadi musuh-Ku; 1. Orang yang berjanji dengan nama-Ku, kemudian dia khianat, 2. Orang yang menjual orang merdeka, lalu ia makan harganya (hasil penjualan itu), dan 3. orang yang mempekerjakan buruh (karyawan) dan karyawan itu telah bekerja dengan baik, tetapi orang tersebut tidak memberikan upahnya”. [HR. Bukhari juz 3, hal. 41]"],["a","عَنِ ابـْنِ عُمَرَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا اِيـْمَانَ لِـمَنْ لَا اَمَانَةَ لَهُ، وَلَا صَلَاةَ لـِمَنْ لَا طَهُوْرَ لَهُ، وَلَا دِيْنَ لِمَنْ لَا صَلَاةَ لَهُ، اِنَّمَا الصَّلَاةُ مِنَ الدِّيْنِ كَمَوْضِعِ الرَّأْسِ مِنَ الْجَسَدِ. الطبرانى فى الصغير ص: 338، رقم : 161"],["p","Dari Ibnu 'Umar, ia berkata : Rasulullah SAW bersabda : \"Tidak beriman bagi orang yang tidak amanat, tidak sah shalat bagi orang yang tidak bersuci terlebih dulu, dan tidak ada agama bagi orang yang tidak shalat, sesungguhnya shalat itu bagi agama seperti kedudukan kepala pada badan\". [HR. Thabarani, dalam Al-Mu'jamush Shaghiir hal. 338, no. 161]"],["a","عَنْ عَلِيٍّ قَالَ: كُنَّا جُلُوْسًا مَعَ رَسُوْلِ اللهِ ﷺ، فَطَلَعَ عَلَيْنَا رَجُلٌ مِنْ اَهْلِ الْعَالِيَةِ، فَقَالَ: يَا رَسُوْلَ اللهِ، اَخْبِرْنِيْ بِاَشَدِّ شَيْءٍ فِيْ هٰذَا الدِّيْنِ وَاَلْيَنِهِ. قَالَ: اَلْيَنُهُ شَهَادَةُ اَنْ لَا اِلٰهَ اِلَّا اللهُ وَاَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُوْلُهُ، وَاَشَدُّهُ يَا اَخَا الْعَالِيَةِ، اَلْاَمَانَةُ، اِنَّهُ لَا دِيْنَ لِمَنْ لَا اَمَانَةَ لَهُ وَلَا صَلَاةَ لَهُ وَلَا زَكَاةَ لَهُ. البزار 3: 61، رقم: 819"],["p","Dari Ali RA, ia berkata : Dahulu kami sedang duduk bersama Rasulullah SAW, tiba-tiba datang seorang laki-laki dari penduduk 'Aliyah lalu bertanya : \"Ya Rasulullah, beritahukanlah kepadaku tentang sesuatu yang paling berat di dalam agama ini maupun yang paling mudah\". Kemudian Nabi SAW bersabda : \"Yang paling mudah ialah mengucapkan syahadat bahwa sesungguhnya tiada Tuhan selain Allah, dan sesungguhnya Muhammad itu hamba-Nya dan utusan-Nya. Adapun yang paling berat wahai saudara dari 'Aliyah, ialah amanat. Sesungguhnya tidak ada agama bagi orang yang tidak amanat, tidak shalat dan tidak zakat\". [HR. Al-Bazzar juz 3, hal. 61, no. 819, dla'if karena dalam sanadnya ada perawi bernama 'Abdur Rahman bin Manshur dan Abul Janub]"],["a","عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اِذَا جَمَعَ اللهُ الْاَوَّلــِيْنَ وَالْآخِرِيـْنَ يَوْمَ الْقِيَامَةِ يُرْفَعُ لـِكُلِّ غَادِرٍ لـِوَاءٌ، فَـقِيْلَ: هٰذِهِ غَدْرَةُ فُلَانِ بـْنِ فُلاَنٍ. مسلم 3: 1359"],["p","Dari Ibnu 'Umar, ia berkata : Rasulullah SAW bersabda, \"Apabila Allah telah mengumpulkan orang-orang yang dahulu dan orang-orang yang akhir besuk pada hari qiyamat, maka setiap orang yang berkhianat (mengingkari janji) akan diberi bendera (sebagai tanda), lalu dikatakan : \"Ini adalah khianatnya si fulan bin fulan\". [HR. Muslim juz 3, hal. 1359, no. 9]"],["a","عَنْ سَالِـمٍ اَنَّ ابْنَ عُمَرَ كَانَ يَقُوْلُ لِلرَّجُلِ اِذَا اَرَادَ سَفَرًا اَنْ اُدْنُ مِنِّيْ اُوَدِّعْكَ كَمَا كَانَ رَسُوْلُ اللهِ ﷺ يُوَدِّعُنَا، فَيَقُوْلُ: اَسْتَوْدِعُ اللهَ دِيْنَكَ وَاَمَانَتَكَ وَخَوَاتِيْمَ عَمَلِكَ. الترمذى 5: 163، رقم: 3506، هذا حديث حسن صحيح غريب"],["p","Dari Salim bahwasanya dahulu Ibnu ‘Umar berkata kepada seseorang apabila ia hendak bepergian, “Dekatlah kepadaku, aku akan melepas kamu sebagaimana dahulu Rasulullah SAW melepas kami”, lalu ia mengucapkan, “Astaudi’ullooha diinaka wa amaanataka wa khowaatiima ‘amalika” (Aku pasrahkan kepada Allah agamamu dan amanatmu dan akhir dari amalmu). [HR. Tirmidzi juz 5, hal. 163, no. 3506, ini hadits hasan shahih gharib]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ يَقُوْلُ: اَللّٰهُمَّ اِنِّيْ اَعُوْذُ بِكَ مِنَ الْجُوْعِ فَاِنَّهُ بِئْسَ الضَّجـِيْعُ، وَاَعُوْذُ بِكَ مِنَ الْخِيَانَةِ فَاِنَّهَا بِئْسَتِ الْبِطَانَةُ. ابن ماجه 2: 1113، رقم: 3354"],["p","Dari Abu Hurairah, ia berkata : Dahulu Rasulullah SAW berdo'a, \"Ya Allah, sesungguhnya aku berlindung kepada-Mu dari lapar, karena sesungguhnya lapar itu adalah sejelek-jelek teman tidur, dan aku berlindung kepada-Mu dari sifat khianat, karena sesungguhnya khianat itu adalah seburuk-buruk perilaku. [HR. Ibnu Majah juz 2, hal. 1113, no. 3354, dla'if karena dalam sanadnya ada perawi bernama Laits bin Sulaim]"],["a","عَنْ ثَوْبَانَ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: مَنْ مَاتَ وَهُوَ بَرِيْءٌ مِنَ الْكِبْرِ وَالْغُلُوْلِ وَالدَّيْنِ دَخَلَ الْجَنَّةَ. الترمذى 3: 67، رقم: 1620"],["p","Dari Tsauban ia berkata, \"Rasulullah SAW bersabda: \"Barangsiapa meninggal dunia dalam keadaan terbebas dari sombong, khianat dan hutang, maka ia masuk surga”. [HR. Tirmidzi juz 3, hal. 67, no. 1620]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ :قَالَ رَسُوْلُ اللهِ ﷺ : اَدِّ الْاَمَانَةَ اِلىَ مَنِ ائْتَمَنَكَ ، وَ لَا تَخُنْ مَنْ خَانَكَ . ابو داود 3 : 290 رقم 3535"],["p","Dari Abu Hurairah, ia berkata: Rasulullah SAW bersabda : “Tunaikanlah amanat orang yang mempercayakan kepadamu, dan janganlah kamu berkhiyanat kepada orang yang mengkhiyanatimu” [HR. Abu Dawud juz 3 hal 290, no 3535]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ :قَالَ رَسُوْلُ اللهِ ﷺ : اَدِّ الْاَمَانَةَ اِلَى مَنِ ائْتَمَنَكَ ، وَ لَا تَخُنْ مَنْ خَانَكَ. الترمذي 2 : 368 رقم 1282 هذا حديث حسن غريب"],["p","Dari Abu Hurairah, ia berkata: Rasulullah SAW bersabda : “Tunaikanlah amanat orang yang mempercayakan kepadamu, dan janganlah kamu berkhiyanat kepada orang yang mengkhiyanatimu” [HR. Tirmidzi, juz 2 hal 368 no 1282, ini hadits hasan gharib]"],["a","عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اَلَا كُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُوْلٌ عَنْ رَعِيَّتِهِ، فَالْاِمَامُ الَّذِيْ عَلَى النَّاسِ رَاعٍ وَهُوَ مَسْئُوْلٌ عَنْ رَعِيَّتِهِ، وَالرَّجُلُ رَاعٍ عَلَى اَهْلِ بَيْتِهِ وَهُوَ مَسْئُوْلٌ عَنْ رَعِيَّتِهِ، وَالْمَرْأَةُ رَاعِيَةٌ عَلَى اَهْلِ بَيْتِ زَوْجِهَا وَوَلَدِهِ وَهِيَ مَسْئُوْلَةٌ عَنْهُمْ، وَعَبْدُ الرَّجُلِ رَاعٍ عَلَى مَالِ سَيِّدِهِ وَهُوَ مَسْئُوْلٌ عَنْهُ، اَلَا فَكُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُوْلٌ عَنْ رَعِيَّتِهِ . البخاري 8 : 104"],["p","Dari ‘Abdullah bin ‘Umar RA, bahwasanya Rasulullah SAW bersabda: \"Ketahuilah, masing masing dari kalian adalah pemimpin, dan masing masing kalian akan ditanya (dimintai pertanggungan jawab) terhadap apa yang dipimpinnya. Imam (pemimpin) yang memimpin rakyatnya adalah pemimpin dan ia akan dimintai pertanggungan jawab atas apa yang dipimpinnya. Seorang suami adalah pemimpin bagi anggota keluarganya dan ia akan dimintai pertanggungan jawab atas apa yang dipimpinnya. Seorang istri adalah pemimpin bagi rumah tangga suami dan anak-anaknya dan ia akan dimintai pertanggungan jawab atas apa yang dipimpinnya. Seorang hamba sahaya adalah pemimpin bagi harta tuannya dan ia akan dimintai pertanggungan jawab atas apa yang dipimpinnya. Ketahuilah, bahwa masing masing dari kalian adalah pemimpin dan masing masing kalian akan dimintai pertanggungan jawab atas apa yang dipimpinnya.\" [HR. Bukhari Juz 8, hal 104]"],["p","Demikianlah semoga bermanfaat dan semoga Allah mengampuni kita. Aamiin!"],["p","--oo0oo--"]],"c20220130_1272":[["p","Ahad, 30 Januari 2022/27 Jumaadal Aakhirah 1443 Brosur No.: 2067/2107/IA"],["p","Penyebab Kerasnya Hati (1)"],["p","Hati adalah bagian terpenting dari diri manusia. Hati adalah yang menentukan baik buruknya manusia. Maka hati harus selalu diupayakan bersih dari segala noda, dosa dan kesalahan. Jangan sampai hati kita tergores oleh dosa dan tertutup kesalahan yang bertumpuk dan berkarat."],["p","Ketahuilah bahwa hati manusia laksana kaca. Kalau kaca itu tertutup oleh kotoran dan debu maka tidak bisa tertembus oleh cahaya. Begitu juga manusia kalau hatinya tertutup oleh noda dosa dan kesalahan maka cahaya hidayah tidak akan bisa masuk ke dalam hatinya."],["p","Al Qur’an mengungkapkan tentang kerasnya hati. Allah SWT berfirman :"],["a","اَلَمْ يَأْنِ لِلَّذِيْنَ اٰمَنُوْٓا اَنْ تَخْشَعَ قُلُوْبُهُمْ لِذِكْرِ اللّٰهِ وَمَا نَزَلَ مِنَ الْحَقِّۙ وَلَا يَكُوْنُوْا كَالَّذِيْنَ اُوْتُوا الْكِتٰبَ مِنْ قَبْلُ فَطَالَ عَلَيْهِمُ الْاَمَدُ فَقَسَتْ قُلُوْبُهُمْۗ وَكَثِيْرٌ مِّنْهُمْ فٰسِقُوْنَ. الحديد : 16"],["p","Belumkah datang waktunya bagi orang-orang yang beriman, untuk tunduk hati mereka mengingat Allah dan kepada kebenaran yang telah turun, dan janganlah mereka seperti orang-orang yang sebelumnya telah diturunkan Al Kitab kepadanya, kemudian berlalulah masa yang panjang atas mereka lalu hati mereka menjadi keras. Dan kebanyakan di antara mereka adalah orang-orang yang fasik. [QS. Al Hadiid : 16]"],["a","وَلَقَدْ اَرْسَلْنَآ اِلٰٓى اُمَمٍ مِّنْ قَبْلِكَ فَاَخَذْنٰهُمْ بِالْبَأْسَاۤءِ وَالضَّرَّاۤءِ لَعَلَّهُمْ يَتَضَرَّعُوْنَ(42) فَلَوْلَآ اِذْ جَاۤءَهُمْ بَأْسُنَا تَضَرَّعُوْا وَلٰكِنْ قَسَتْ قُلُوْبُهُمْ وَزَيَّنَ لَهُمُ الشَّيْطٰنُ مَا كَانُوْا يَعْمَلُوْنَ(43).الانعام : 42-43"],["p","Dan sesungguhnya Kami telah mengutus (rasul-rasul) kepada ummat-ummat yang sebelum kamu, kemudian Kami siksa mereka dengan (menimpakan) kesengsaraan dan kemelaratan, supaya mereka bermohon (kepada Allah) dengan tunduk merendahkan diri. (42)"],["p","Maka mengapa mereka tidak memohon (kepada Allah) dengan tunduk merendahkan diri ketika datang siksaan Kami kepada mereka, bahkan hati mereka telah menjadi keras dan syetan pun menampakkan kepada mereka kebagusan apa yang selalu mereka kerjakan.(43) [QS. Al An’aam : 42-43]"],["a","ثُمَّ قَسَتْ قُلُوْبُكُمْ مِّنْۢ بَعْدِ ذٰلِكَ فَهِيَ كَالْحِجَارَةِ اَوْ اَشَدُّ قَسْوَةً ۗ وَاِنَّ مِنَ الْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ الْاَنْهٰرُ ۗ وَاِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ الْمَاۤءُ ۗ وَاِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ اللّٰهِ ۗ وَمَا اللّٰهُ بِغَافِلٍ عَمَّا تَعْمَلُوْنَ. البقرة : 74"],["p","Kemudian setelah itu hatimu menjadi keras seperti batu, bahkan lebih keras lagi. Padahal di antara batu-batu itu sungguh ada yang mengalir sungai-sungai daripadanya, dan di antaranya sungguh ada yang terbelah lalu keluarlah mata air daripadanya, dan di antaranya sungguh ada yang meluncur jatuh karena takut kepada Allah. Dan Allah sekali-kali tidak lengah dari apa yang kamu kerjakan. [QS. Al-Baqarah : 74]"],["a","وَمَآ اَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَّسُوْلٍ وَّلَا نَبِيٍّ اِلَّآ اِذَا تَمَنّٰىٓ اَلْقَى الشَّيْطٰنُ فِيْٓ اُمْنِيَّتِهٖۚ فَيَنْسَخُ اللّٰهُ مَا يُلْقِى الشَّيْطٰنُ ثُمَّ يُحْكِمُ اللّٰهُ اٰيٰتِهٖۗ وَاللّٰهُ عَلِيْمٌ حَكِيْمٌ ۙ (52) لِيَجْعَلَ مَا يُلْقِى الشَّيْطٰنُ فِتْنَةً لِّلَّذِيْنَ فِيْ قُلُوْبِهِمْ مَّرَضٌ وَّالْقَاسِيَةِ قُلُوْبُهُمْۗ وَاِنَّ الظّٰلِمِيْنَ لَفِيْ شِقَاقٍۢ بَعِيْدٍ(53) . الحج : 52-53"],["p","Dan Kami tidak mengutus sebelum kamu seorang rasul pun dan tidak (pula) seorang nabi, melainkan apabila ia mempunyai sesuatu keinginan, syetan pun memasukkan godaan-godaan terhadap keinginan itu, Allah menghilangkan apa yang dimasukkan oleh syetan itu, dan Allah menguatkan ayat-ayat-Nya. Dan Allah Maha Mengetahui lagi Maha Bijaksana,(52)"],["p","agar Dia menjadikan apa yang dimasukkan oleh syetan itu, sebagai cobaan bagi orang-orang yang di dalam hatinya ada penyakit, dan yang keras hatinya. Dan sesungguhnya orang-orang yang dhalim itu benar-benar dalam permusuhan yang sangat. (53) [QS. Al Hajj : 52-53]"],["a","اَفَمَنْ شَرَحَ اللّٰهُ صَدْرَهٗ لِلْاِسْلَامِ فَهُوَ عَلٰى نُوْرٍ مِّنْ رَّبِّهٖ ۗ فَوَيْلٌ لِّلْقٰسِيَةِ قُلُوْبُهُمْ مِّنْ ذِكْرِ اللّٰهِ ۗ اُولٰۤىِٕكَ فِيْ ضَلٰلٍ مُّبِيْنٍ. الزمر : 22"],["p","Maka apakah orang-orang yang dibukakan Allah hatinya untuk (menerima) agama Islam lalu ia mendapat cahaya dari Tuhannya (sama dengan orang yang membatu hatinya)? Maka kecelakaan yang besarlah bagi mereka yang telah membatu hatinya untuk mengingat Allah. Mereka itu dalam kesesatan yang nyata. [QS. Az Zumar : 22]"],["a","فَبِمَا نَقْضِهِمْ مِّيْثَاقَهُمْ لَعَنّٰهُمْ وَجَعَلْنَا قُلُوْبَهُمْ قٰسِيَةً ۚ يُحَرِّفُوْنَ الْكَلِمَ عَنْ مَّوَاضِعِهٖۙ وَنَسُوْا حَظًّا مِّمَّا ذُكِّرُوْا بِهٖۚ وَلَا تَزَالُ تَطَّلِعُ عَلٰى خَاۤىِٕنَةٍ مِّنْهُمْ اِلَّا قَلِيْلًا مِّنْهُمْ ۖ فَاعْفُ عَنْهُمْ وَاصْفَحْ ۗ اِنَّ اللّٰهَ يُحِبُّ الْمُحْسِنِيْنَ. المائدة : 13"],["p","Maka karena mereka melanggar janjinya, Kami kutuk mereka, dan Kami jadikan hati mereka keras membatu. Mereka suka merobah perkataan (Allah) dari tempat-tempatnya, dan mereka melupakan sebagian dari apa yang mereka telah diperingatkan dengannya, dan kamu (Muhammad) senantiasa akan melihat kekhianatan dari mereka kecuali sedikit di antara mereka (yang tidak berkhianat), maka maafkanlah mereka dan biarkanlah mereka, sesungguhnya Allah menyukai orang-orang yang berbuat baik. [QS. Al Maaidah : 13]"],["p","Hal-hal yang menyebabkan hati menjadi keras diantaranya sebagai berikut :"],["h","1. Lalai dari mengingat Allah dan mentadabburi Al-Qur’an"],["a","اَلَمْ يَأْنِ لِلَّذِيْنَ اٰمَنُوْٓا اَنْ تَخْشَعَ قُلُوْبُهُمْ لِذِكْرِ اللّٰهِ وَمَا نَزَلَ مِنَ الْحَقِّۙ وَلَا يَكُوْنُوْا كَالَّذِيْنَ اُوْتُوا الْكِتٰبَ مِنْ قَبْلُ فَطَالَ عَلَيْهِمُ الْاَمَدُ فَقَسَتْ قُلُوْبُهُمْۗ وَكَثِيْرٌ مِّنْهُمْ فٰسِقُوْنَ . الحديد : 16"],["p","Belumkah datang waktunya bagi orang-orang yang beriman, untuk tunduk hati mereka mengingat Allah dan kepada kebenaran yang telah turun, dan janganlah mereka seperti orang-orang yang sebelumnya telah diturunkan Al Kitab kepadanya, kemudian berlalulah masa yang panjang atas mereka lalu hati mereka menjadi keras. Dan kebanyakan di antara mereka adalah orang-orang yang fasik. [QS. Al Hadiid: 16]"],["a","اَفَلَا يَتَدَبَّرُوْنَ الْقُرْاٰنَ اَمْ عَلٰى قُلُوْبٍ اَقْفَالُهَا. محمد : 24"],["p","Maka apakah mereka tidak memperhatikan Al Qur'an ataukah hati mereka terkunci? [QS. Muhammad : 24]"],["a","اَفَلَا يَتَدَبَّرُوْنَ الْقُرْاٰنَ ۗ وَلَوْ كَانَ مِنْ عِنْدِ غَيْرِ اللّٰهِ لَوَجَدُوْا فِيْهِ اخْتِلَافًا كَثِيْرًا. النساء : 82"],["p","Maka apakah mereka tidak memperhatikan Al Qur'an? Kalau kiranya Al Qur'an itu bukan dari sisi Allah, tentulah mereka mendapati pertentangan yang banyak di dalamnya. [QS. An Nisaa’ : 82]"],["a","وَمَنْ اَعْرَضَ عَنْ ذِكْرِيْ فَاِنَّ لَهٗ مَعِيْشَةً ضَنْكًا وَّنَحْشُرُهٗ يَوْمَ الْقِيٰمَةِ اَعْمٰى . طه :124"],["p","Dan barang siapa berpaling dari peringatan-Ku, maka sesungguhnya baginya penghidupan yang sempit, dan Kami akan menghimpunkannya pada hari kiamat dalam keadaan buta\". [QS. Thaahaa : 124]"],["a","لَوْ اَنْزَلْنَا هٰذَا الْقُرْاٰنَ عَلٰى جَبَلٍ لَّرَاَيْتَهٗ خَاشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ اللّٰهِ ۗ وَتِلْكَ الْاَمْثَالُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُوْنَ. الحشر : 21"],["p","Kalau sekiranya Kami menurunkan Al Qur'an ini kepada sebuah gunung, pasti kamu akan melihatnya tunduk terpecah belah disebabkan takut kepada Allah. Dan perumpamaan-perumpamaan itu Kami buat untuk manusia supaya mereka berfikir. [QS. Al Hasyr : 21]"],["h","2. Banyak melakukan kemaksiatan"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اِنَّ الْمُؤْمِنَ اِذَا اَذْنَبَ ذَنْبًا كَانَتْ نُكْتَةٌ سَوْدَاءُ فِيْ قَلْبِهِ، فَاِنْ تَابَ وَ نَزَعَ وَ اسْتَغْفَرَ سُقِلَ مِنْهَا قَلْبُهُ، وَ اِنْ زَادَ زَادَتْ حَتَّى يُعْلَقَ بِهَا قَلْبُهُ، فَذٰلِكَ الرَّانُ الَّذِيْ ذَكَرَ اللهُ فِيْ كِتَابِهِ: كَلَّا بَلْ ۜ رَانَ عَلٰى قُلُوْبِهِمْ مَّا كَانُوْا يَكْسِبُوْنَ. الحاكم في المستدرك 2 : 562 رقم 3908"],["p","Dari Abu Hurairah RA, bahwasanya Rasulullah SAW bersabda, “Sesungguhnya orang mukmin itu apabila berbuat suatu dosa, ada titik hitam di hatinya. Jika ia bertaubat dan mencabut (tidak terus menerus berbuat dosa) serta memohon ampun, maka hati itu dibersihkan kembali dari titik hitam tersebut. Dan jika ia bertambah dalam berbuat dosa, maka bertambah pulalah titik hitam tersebut sehingga hati itu tertutup olehnya. Itulah yang dinamakan “Ar-Roon” yang Allah sebutkan di dalam kitab-Nya “Kallaa bal roona ‘alaa quluubihim maa kaanuu yaksibuun “ (Sekali-kali tidak demikian, sebenarnya apa yang selalu mereka usahakan itu menutupi hati mereka) (QS. Al-Muthaffifiin : 14). [HR. Al-Hakim di dalam Al Mustadrok juz 2, hal 562, no 3908]"],["a","عَنْ اَبِيْ هُرَيْرَةَ عَنْ رَسُوْلِ اللهِ ﷺ قَالَ: اِنَّ الْعَبْدَ اِذَا اَخْطَأَ خَطِيْئَةً نُكِتَتْ فِيْ قَلْبِهِ نُكْتَةٌ سَوْدَاءُ، فَاِذَا هُوَ نَزَعَ وَاسْتَغْفَرَ وَتَابَ سُقِلَ قَلْبُهُ، وَاِنْ عَادَ زِيْدَ فِيْهَا حَتَّى تَعْلُوَ قَلْبَهُ، وَهُوَ الرَّانُ الَّذِيْ ذَكَرَ اللهُ: كَلَّا بَلْ ۜ رَانَ عَلٰى قُلُوْبِهِمْ مَّا كَانُوْا يَكْسِبُوْنَ. الترمذي 5 : 105 رقم 3390 هذا حديث حسن صحيح"],["p","Dari Abu Hurairah, dari Rasulullah SAW, beliau bersabda, \"Sesungguhnya, seorang hamba apabila melakukan suatu kesalahan (dosa), maka hatinya akan tertitik dengan titik hitam. Apabila ia meninggalkan (perbuatan dosa tersebut) memohon ampun dan bertaubat, maka hatinya dibersihkan kembali. Dan jika ia kembali (mengerjakan perbuatan dosa), maka titik hitam itu akan ditambah di dalam hatinya, hingga titik hitam itu memenuhi hatinya. Itulah yang dinamakan “Ar-Roon” yang Allah sebutkan (di dalam kitab-Nya) “Kallaa bal roona ‘alaa quluubihim maa kaanuu yaksibuun “ (Sekali-kali tidak demikian, sebenarnya apa yang selalu mereka usahakan itu menutupi hati mereka) (QS. Al-Muthaffifiin : 14) [HR. Tirmidzi juz 5 hal 105 no 3390, ini hadits hasan shahih]"],["a","عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ اِنَّ هٰذِهِ القُلُوْبَ تَصْدَأُ كَمَا يَصْدَأُ الْحَدِيْدُ اِذَا اَصَابَهُ الْمَاءُ. قِيْلَ: يَارَسُوْلَ اللهِ، وَمَا جِلَاؤُهَا ؟ قَالَ: كَثْرَةُ ذِكْرِ الْمَوْتِ وَتِلَاوَةُ اْلقُرْآنِ. رواه البيهقي في شعب الإيمان 2 : 352 رقم 2014"],["p","Dari Ibnu Umar, ia berkata: Rasulullah SAW bersabda, “Sesungguhnya hati ini dapat berkarat sebagaimana berkaratnya besi apabila terkena air.” Ada yang bertanya: “Ya Rasulullah, bagaimana cara membersihkannya?” Rasulullah SAW. bersabda, “Memperbanyak mengingat mati dan membaca Al Qur’an.” [HR. Baihaqi dalam Syu’abul Iman juz 2 hal 352 no 2014 dlo’if, karena di dalam isnadnya ada perawi bernama ‘Abdullah bin ‘Abdul ‘Aziz bin Abi Rowwaad]"],["h","3. Banyak tertawa"],["a","عَنْ اَبيْ سَعِيْدِ قَالَ: دَخَلَ رَسُوْلُ اللهِ ﷺ مُصَلَّاهُ فَرَأَى نَاسًا كَاَنَّهُمْ يَكْتَشِرُوْنَ، قَالَ: اَمَا اِنَّكُمْ لَوْ اَكْثَرْتُمْ ذِكْرَ هَاذِمِ اللَّذَّاتِ لَشَغَلَكُمْ عَمَّا أَرَى، فَاَكْثِرُوْا مِنْ ذِكْرِ هَاذِمِ اللَّذَّاتِ الْمَوْتِ. الترمدي 4 : 55 رقم 2578 هذا حديث غريب"],["p","Dari Abu Sa’id (Al-Khudriy), ia berkata : Rasulullah SAW masuk ke tempat shalat beliau, lalu beliau melihat orang-orang sama tertawa terkekeh-kekeh, maka beliau bersabda: “Ketahuilah, seandainya kamu sekalian banyak mengingat pemutus kesenangan, tentu kalian tidak sempat berbuat apa yang aku lihat. Maka banyak-banyaklah mengingat pemutus kesenangan, yaitu mati. [HR. Tirmidzi juz 4, hal. 55, no 2578, ini hadits gharib]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا تُكْثِرُوا الضَّحِكَ، فَاِنَّ كَثْرَةَ الضَّحِكِ تُمِيْتُ الْقَلْبَ. ابن ماجه 2 : 1403 رقم 4193"],["p","Dari Abu Hurairah, ia berkata, \"Rasulullah SAW bersabda: \"Janganlah kalian banyak tertawa, karena banyak tertawa akan mematikan hati. “ [HR. Ibnu Majah juz 2, hal 1403, no 4193]"],["a","عَنْ اَنَسٍ قَالَ: صَلَّى بِنَا رَسُوْلُ اللهِ ﷺ ذَاتَ يَوْمٍ. فَلَمَّا قَضَى الصَّلَاةَ اَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ: اَيُّهَا النَّاسُ، اِنِّيْ اِمَامُكُمْ، فَلَا تَسْبِقُوْنِيْ بِالرُّكُوْعِ وَلَا بِالسُّجُوْدِ وَلَا بِالْقِيَامِ وَلَا بِاْلاِنْصِرَافِ، فَاِنِّيْ اَرَاكُمْ اَمَامِيْ وَمِنْ خَلْفِيْ. ثُمَّ قَالَ: وَالَّذِيْ نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَوْ رَأَيْتُمْ مَا رَأَيْتُ لَضَحِكْتُمْ قَلِيْلًا وَلَبَكَيْتُمْ كَثِيْرًا. قَالُوْا: وَمَا رَأَيْتَ يَا رَسُوْلَ اللهِ؟ قَالَ: رَأَيْتُ الْجَنَّةَ وَالنَّارَ. مسلم 1 : 320 رقم 112"],["p","Dari Anas, ia berkata, \"Pada suatu hari Rasulullah SAW shalat mengimami kami. Setelah selesai shalat, beliau menghadap kami dengan wajahnya lalu bersabda: “Wahai para manusia, aku adalah imam kalian, maka janganlah kalian mendahului aku dengan ruku’, sujud, berdiri, dan berpaling dari shalat. Karena aku melihat kalian dari arah depanku dan belakangku.” Kemudian beliau bersabda: “Demi Tuhan yang jiwa Muhammad berada di tangan-Nya, seandainya kalian melihat apa yang aku lihat, tentu kalian akan sedikit tertawa dan banyak menangis.” Shahabat bertanya: “Apa yang engkau lihat wahai Rasulullah?” Beliau menjawab: “Aku melihat surga dan neraka.” (HR. Muslim juz 1, hal 320, no 112)"],["a","عَنْ بَهْزِ بْنِ حَكِيْمٍ قَالَ حَدَّثَنِيْ أَبِيْ عَنْ جَدِّيْ قَالَ: سَمِعْتُ النَّبِيَّ ﷺ يَقُولُ: وَيْلٌ لِلَّذِيْ يُحَدِّثُ بِالْحَدِيْثِ لِيُضْحِكَ بِهِ الْقَوْمَ فَيَكْذِبُ، وَيْلٌ لَهُ، وَيْلٌ لَهُ.الترمذي3: 382 رقم 2417، هذا حديث حسن"],["p","Dari Bahz bin Hakim, ia berkata: Telah menceritakan kepadaku ayahku dari kakekku ia berkata: \"Aku mendengar Rasulullah SAW bersabda: \"Celakalah bagi orang yang berbicara dengan suatu pembicaraan, ia berdusta untuk membuat orang orang tertawa. Celakalah ia, celakalah ia.\" [HR. Tirmidzi juz 3, hal 382 no 2417, ini hadits hasan]"],["h","4. Banyak bertanya sesuatu yang tidak perlu"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تَسْـَٔلُوْا عَنْ اَشْيَاۤءَ اِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ ۚ وَاِنْ تَسْـَٔلُوْا عَنْهَا حِيْنَ يُنَزَّلُ الْقُرْاٰنُ تُبْدَ لَكُمْ ۗ عَفَا اللّٰهُ عَنْهَا ۗ وَاللّٰهُ غَفُوْرٌ حَلِيْمٌ. المائدة : 101"],["p","Hai orang-orang yang beriman, janganlah kamu menanyakan (kepada Nabimu) hal-hal yang jika diterangkan kepadamu, niscaya menyusahkan kamu, dan jika kamu menanyakan di waktu Al Qur'an itu sedang diturunkan, niscaya akan diterangkan kepadamu. Allah memaafkan (kamu) tentang hal-hal itu. Allah Maha Pengampun lagi Maha Penyantun. [QS. Al Maaidah : 101]"],["a","وَاِذْ قَالَ مُوْسٰى لِقَوْمِهٖٓ اِنَّ اللّٰهَ يَأْمُرُكُمْ اَنْ تَذْبَحُوْا بَقَرَةً ۗ قَالُوْٓا اَتَتَّخِذُنَا هُزُوًا ۗ قَالَ اَعُوْذُ بِاللّٰهِ اَنْ اَكُوْنَ مِنَ الْجٰهِلِيْنَ.(67) قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّنْ لَّنَا مَا هِيَ ۗ قَالَ اِنَّهٗ يَقُوْلُ اِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَّلَا بِكْرٌۗ عَوَانٌۢ بَيْنَ ذٰلِكَ ۗ فَافْعَلُوْا مَا تُؤْمَرُوْنَ. (68) البقرة : 67 - 68"],["p","Dan (ingatlah), ketika Musa berkata kepada kaumnya: \"Sesungguhnya Allah menyuruh kamu menyembelih seekor sapi betina\". Mereka berkata: \"Apakah kamu hendak menjadikan kami buah ejekan?\" Musa menjawab: \"Aku berlindung kepada Allah agar tidak menjadi salah seorang dari orang-orang yang jahil\". (67)"],["p","Mereka menjawab: \"Mohonkanlah kepada Tuhanmu untuk kami, agar Dia menerangkan kepada kami, sapi betina apakah itu.\" Musa menjawab: \"Sesungguhnya Allah berfirman bahwa sapi betina itu adalah sapi betina yang tidak tua dan tidak muda; pertengahan antara itu; maka kerjakanlah apa yang diperintahkan kepadamu\". (68) [QS. Al Baqarah :67-68]"],["a","قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّنْ لَّنَا مَا لَوْنُهَا ۗ قَالَ اِنَّهٗ يَقُوْلُ اِنَّهَا بَقَرَةٌ صَفْرَاۤءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ النّٰظِرِيْنَ.(69) قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّنْ لَّنَا مَا هِيَۙ اِنَّ الْبَقَرَ تَشٰبَهَ عَلَيْنَاۗ وَاِنَّآ اِنْ شَاۤءَ اللّٰهُ لَمُهْتَدُوْنَ(70) قَالَ اِنَّهٗ يَقُوْلُ اِنَّهَا بَقَرَةٌ لَّا ذَلُوْلٌ تُثِيْرُ الْاَرْضَ وَلَا تَسْقِى الْحَرْثَۚ مُسَلَّمَةٌ لَّاشِيَةَ فِيْهَا ۗ قَالُوا الْـٰٔنَ جِئْتَ بِالْحَقِّ فَذَبَحُوْهَا وَمَا كَادُوْا يَفْعَلُوْنَ ࣖ (71). البقرة :69-71"],["p","Mereka berkata: \"Mohonkanlah kepada Tuhanmu untuk kami agar Dia menerangkan kepada kami apa warnanya\". Musa menjawab: \"Sesungguhnya Allah berfirman bahwa sapi betina itu adalah sapi betina yang kuning, yang kuning tua warnanya, lagi menyenangkan orang-orang yang memandangnya.“ (69)"],["p","Mereka berkata: \"Mohonkanlah kepada Tuhanmu untuk kami agar Dia menerangkan kepada kami bagaimana hakikat sapi betina itu, karena sesungguhnya sapi itu (masih) samar bagi kami dan sesungguhnya kami insya Allah akan mendapat petunjuk (untuk memperoleh sapi itu).“ (70)"],["p","Musa berkata: \"Sesungguhnya Allah berfirman bahwa sapi betina itu adalah sapi betina yang belum pernah dipakai untuk membajak tanah dan tidak pula untuk mengairi tanaman, tidak bercacat, tidak ada belangnya.\" Mereka berkata: “Sekarang barulah kamu menerangkan hakikat sapi betina yang sebenarnya\". Kemudian mereka menyembelihnya dan hampir saja mereka tidak melaksanakan perintah itu.(71) [QS. Al Baqarah :69 - 71]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اُتْرُكُوْنِيْ مَا تَرَكْتُكُمْ، فَاِذَا حَدَّثْتُكُمْ فَخُذُوْا عَنِّيْ، فَاِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِكَثْرَةِ سُؤَالِهِمْ وَاخْتِلَافِهِمْ عَلَى اَنْبِيَائِهِمْ. الترمذى 4: 152، رقم 2820، هذا حديث حسن صحيح"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Biarkanlah aku dengan apa yang aku tinggalkan pada kamu sekalian. Apabila aku ceritakan kepada kamu sekalian (tentang sesuatu), maka ambillah dariku. Sesungguhnya telah binasa orang-orang sebelum kalian disebabkan mereka banyak bertanya (hal-hal yang tidak perlu ditanyakan), lalu mereka menyelisihi nabi-nabi mereka. [HR.Tirmidzi juz 4, hal. 152, no. 2820, ini hadits hasan shahih]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اِنَّ اللهَ يَرْضَى لَكُمْ ثَلاَثًا وَيَكْرَهُ لَكُمْ ثَلاَثًا. فَيَرْضَى لَكُمْ اَنْ تَعْبُدُوْهُ وَلَا تُشْرِكُوْا بِهِ شَيْئًا، وَ اَنْ تَعْتَصِمُوْا بِحَبْلِ اللهِ جَمِيْعًا، وَلَا تَفَرَّقُوْا، وَيَكْرَهُ لَكُمْ قِيْلَ وَقَالَ، وَكَثْرَةَ السُّؤَالِ، وَ اِضَاعَةَ الْمَالِ. مسلم 3: 1340رقم 10"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Sesungguhnya Allah senang pada kalian tiga hal, dan benci pada kalian tiga hal. 1) Allah senang pada kalian bahwa kalian menyembah-Nya dan tidak menyekutukan-Nya dengan sesuatu. 2) Allah senang bahwa kalian semua berpegang teguh kepada tali Allah,dan 3) Allah senang kalian tidak bercerai-berai. Dan Allah benci kepada kalian tiga hal. 1) Allah benci pada kalian \"Katanya dan katanya\", 2) Allah benci kalian banyak bertanya (yang tidak diamalkan), dan 3) Allah benci kalian menyia-nyiakan harta\". [HR. Muslim juz 3, hal. 1340, no 10]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: خَطَبَنَا رَسُوْلُ اللهِ ﷺ فَقَالَ: اَيُّهَا النَّاسُ، قَدْ فَرَضَ اللهُ عَلَيْكُمُ الْحَجَّ فَحُجُّوْا. فَقَالَ رَجُلٌ: اَكُلَّ عَامٍ يَا رَسُوْلَ اللهِ؟ فَسَكَتَ، حَتَّى قَالَهَا ثَلَاثًا. فَقَالَ رَسُوْلُ اللهِ ﷺ: لَوْ قُلْتُ نَعَمْ، لَوَجَبَتْ، وَلَمَا اسْتَطَعْتُمْ. ثُمَّ قَالَ: ذَرُوْنِيْ مَا تَرَكْتُكُمْ، فَاِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِكَثْرَةِ سُؤَالِهِمْ وَاخْتِلَافِهِمْ عَلَى اَنْبِيَائِهِمْ. فَاِذَا اَمَرْتُكُمْ بِشَىْءٍ فَأْتُوْا مِنْهُ مَا اسْتَطَعْتُمْ، وَ اِذَا نَهَيْتُكُمْ عَنْ شَىْءٍ فَدَعُوْهُ. مسلم 2: 975 رقم 412"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW berkhutbah kepada kami,beliau bersabda,\"Wahai para manusia, sesungguhnya Allah telah mewajibkan kepada kalian untuk berhajji, maka berhajjilah kalian\". Lalu ada seorang laki-laki bertanya, \"Ya Rasulullah, apakah setiap tahun ?\".Maka Rasulullah SAW diam, sehingga orang laki-laki tersebut menanyakan sampai tiga kali. Kemudian Rasulullah SAW menjawab, \"Seandainya aku mengatakan, \"Ya\", tentu menjadi wajib. Dan kalian pasti tidak mampu melaksanakannya\". Kemudian beliau bersabda, \"Biarkanlah aku, dengan apa yang aku tinggalkan pada kalian. Sesungguhnya telah binasa orang-orang sebelum kalian disebabkan banyaknya pertanyaan mereka, lalu mereka menyelisihi Nabi-nabi mereka. Maka apabila aku perintahkan kepada kalian tentang sesuatu, laksanakanlah semaksimalnya. Dan apabila aku melarang kepada kalian tentang sesuatu, maka tinggalkanlah\". [HR. Muslim juz 2, hal. 975, no 412]"],["p","(Bersambung …)"]],"c20220206_1273":[["p","Ahad, 06 Februari 2022/5 Rajab 1443 Brosur No.: 2068/2108/IA"],["p","Penyebab Kerasnya Hati (2)"],["p","5. Sombong, mengandalkan Kekuasaan, kekuatan, kepandaian, keindahan tubuh, maupun banyaknya harta."],["p","Allah SWT berfirman :"],["a","اِذْ قَالَ رَبُّكَ لِلْمَلٰۤىِٕكَةِ اِنِّيْ خَالِقٌۢ بَشَرًا مِّنْ طِيْنٍ(71) فَاِذَا سَوَّيْتُهٗ وَنَفَخْتُ فِيْهِ مِنْ رُّوْحِيْ فَقَعُوْا لَهٗ سٰجِدِيْنَ(72) فَسَجَدَ الْمَلٰۤىِٕكَةُ كُلُّهُمْ اَجْمَعُوْنَۙ (73) اِلَّآ اِبْلِيْسَۗ اِسْتَكْبَرَ وَكَانَ مِنَ الْكٰفِرِيْنَ (74) ص : 71-74"],["p","(Ingatlah) ketika Tuhanmu berfirman kepada malaikat: \"Sesungguhnya Aku akan menciptakan manusia dari tanah\".(71)"],["p","Maka apabila telah Kusempurnakan kejadiannya dan Kutiupkan kepadanya ruh (ciptaan) Ku; maka hendaklah kamu tersungkur dengan bersujud kepadanya\". (72)"],["p","Lalu seluruh malaikat itu bersujud semuanya. (73)"],["p","kecuali iblis; dia menyombongkan diri dan adalah dia termasuk orang-orang yang kafir. (74) [QS. Shaad : 71-74]"],["a","وَلَقَدْ خَلَقْنٰكُمْ ثُمَّ صَوَّرْنٰكُمْ ثُمَّ قُلْنَا لِلْمَلٰۤىِٕكَةِ اسْجُدُوْا لِاٰدَمَ فَسَجَدُوْٓا اِلَّآ اِبْلِيْسَۗ لَمْ يَكُنْ مِّنَ السّٰجِدِيْنَ(11) قَالَ مَا مَنَعَكَ اَلَّا تَسْجُدَ اِذْ اَمَرْتُكَ ۗ قَالَ اَنَا۠ خَيْرٌ مِّنْهُۚ خَلَقْتَنِيْ مِنْ نَّارٍ وَّخَلَقْتَهٗ مِنْ طِيْنٍ(12) قَالَ فَاهْبِطْ مِنْهَا فَمَا يَكُوْنُ لَكَ اَنْ تَتَكَبَّرَ فِيْهَا فَاخْرُجْ اِنَّكَ مِنَ الصّٰغِرِيْنَ(13) الاعراف : 11-13"],["p","Sesungguhnya Kami telah menciptakan kamu (Adam), lalu Kami bentuk tubuhmu, kemudian Kami katakan kepada para malaikat: \"Bersujudlah kamu kepada Adam\"; maka mereka pun bersujud kecuali iblis. Dia tidak termasuk mereka yang bersujud. (11)"],["p","Allah berfirman: \"Apakah yang menghalangimu untuk bersujud (kepada Adam) di waktu Aku menyuruhmu?\". Menjawab iblis: \"Saya lebih baik daripadanya: Engkau ciptakan saya dari api sedang dia Engkau ciptakan dari tanah\". (12)"],["p","Allah berfirman: \"Turunlah kamu dari surga itu; karena kamu tidak sepatutnya menyombongkan diri di dalamnya, maka keluarlah, sesungguhnya kamu termasuk orang-orang yang hina\". (13) [QS. Al A’raaf : 11-13]"],["a","فَاَمَّا عَادٌ فَاسْتَكْبَرُوْا فِى الْاَرْضِ بِغَيْرِ الْحَقِّ وَقَالُوْا مَنْ اَشَدُّ مِنَّا قُوَّةً ۗ اَوَلَمْ يَرَوْا اَنَّ اللّٰهَ الَّذِيْ خَلَقَهُمْ هُوَ اَشَدُّ مِنْهُمْ قُوَّةً ۗ وَكَانُوْا بِاٰيٰتِنَا يَجْحَدُوْنَ (15) فَاَرْسَلْنَا عَلَيْهِمْ رِيْحًا صَرْصَرًا فِيْٓ اَيَّامٍ نَّحِسَاتٍ لِّنُذِيْقَهُمْ عَذَابَ الْخِزْيِ فِى الْحَيٰوةِ الدُّنْيَا ۗ وَلَعَذَابُ الْاٰخِرَةِ اَخْزٰى وَهُمْ لَا يُنْصَرُوْنَ (16) فصلت : 15-16"],["p","Adapun kaum 'Aad maka mereka menyombongkan diri di muka bumi tanpa alasan yang benar dan berkata, \"Siapakah yang lebih besar kekuatannya dari kami ?\". Dan apakah mereka itu tidak memperhatikan bahwa Allah yang menciptakan mereka adalah lebih besar kekuatan-Nya dari mereka ? Dan adalah mereka mengingkari tanda-tanda (kekuatan) Kami. (15)"],["p","Maka Kami meniupkan angin yang amat gemuruh kepada mereka dalam beberapa hari yang sial, karena Kami hendak merasakan kepada mereka itu siksaan yang menghinakan dalam kehidupan dunia. Dan sesungguhnya siksaan akhirat lebih menghinakan sedang mereka tidak diberi pertolongan. (16) [QS. Fushshilat :15-16]"],["a","وَاِلٰى ثَمُوْدَ اَخَاهُمْ صٰلِحًاۘ قَالَ يٰقَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِّنْ اِلٰهٍ غَيْرُهٗۗ قَدْ جَاۤءَتْكُمْ بَيِّنَةٌ مِّنْ رَّبِّكُمْۗ هٰذِهٖ نَاقَةُ اللّٰهِ لَكُمْ اٰيَةً فَذَرُوْهَا تَأْكُلْ فِيْٓ اَرْضِ اللّٰهِ وَلَا تَمَسُّوْهَا بِسُوْۤءٍ فَيَأْخُذَكُمْ عَذَابٌ اَلِيْمٌ (73) وَاذْكُرُوْٓا اِذْ جَعَلَكُمْ خُلَفَاۤءَ مِنْۢ بَعْدِ عَادٍ وَّبَوَّاَكُمْ فِى الْاَرْضِ تَتَّخِذُوْنَ مِنْ سُهُوْلِهَا قُصُوْرًا وَّتَنْحِتُوْنَ الْجِبَالَ بُيُوْتًا ۚ فَاذْكُرُوْٓا اٰلَاۤءَ اللّٰهِ وَلَا تَعْثَوْا فِى الْاَرْضِ مُفْسِدِيْنَ (74) قَالَ الْمَلَاُ الَّذِيْنَ اسْتَكْبَرُوْا مِنْ قَوْمِهٖ لِلَّذِيْنَ اسْتُضْعِفُوْا لِمَنْ اٰمَنَ مِنْهُمْ اَتَعْلَمُوْنَ اَنَّ صٰلِحًا مُّرْسَلٌ مِّنْ رَّبِّهٖۗ قَالُوْٓا اِنَّا بِمَآ اُرْسِلَ بِهٖ مُؤْمِنُوْنَ (75) قَالَ الَّذِيْنَ اسْتَكْبَرُوْٓا اِنَّا بِالَّذِيْٓ اٰمَنْتُمْ بِهٖ كٰفِرُوْنَ (76) فَعَقَرُوا النَّاقَةَ وَعَتَوْا عَنْ اَمْرِ رَبِّهِمْ وَقَالُوْا يٰصٰلِحُ ائْتِنَا بِمَا تَعِدُنَآ اِنْ كُنْتَ مِنَ الْمُرْسَلِيْنَ (77) فَاَخَذَتْهُمُ الرَّجْفَةُ فَاَصْبَحُوْا فِيْ دَارِهِمْ جٰثِمِيْنَ. (78) فَتَوَلّٰى عَنْهُمْ وَقَالَ يٰقَوْمِ لَقَدْ اَبْلَغْتُكُمْ رِسَالَةَ رَبِّيْ وَنَصَحْتُ لَكُمْ وَلٰكِنْ لَّا تُحِبُّوْنَ النّٰصِحِيْنَ (79) الاعراف : 73-79"],["p","Dan (Kami telah mengutus) kepada kaum Tsamud saudara mereka Shaleh. Ia berkata. \"Hai kaumku, sembahlah Allah, sekali-kali tidak ada Tuhan bagimu selain-Nya. Sesungguhnya telah datang bukti yang nyata kepadamu dari Tuhanmu. Unta betina Allah ini menjadi tanda bagimu, maka biarkanlah dia makan di bumi Allah, dan janganlah kamu mengganggunya dengan gangguan apa pun, (yang karenanya) kamu akan ditimpa siksaan yang pedih.\" (73)"],["p","Dan ingatlah olehmu di waktu Tuhan menjadikan kamu pengganti-pengganti (yang berkuasa) sesudah kaum 'Aad dan memberikan tempat bagimu di bumi. Kamu dirikan istana-istana di tanah-tanahnya yang datar dan kamu pahat gunung-gunungnya untuk dijadikan rumah; maka ingatlah ni’mat-ni’mat Allah dan janganlah kamu merajalela di muka bumi membuat kerusakan. (74)"],["p","Pemuka-pemuka yang menyombongkan diri di antara kaumnya berkata kepada orang-orang yang dianggap lemah yang telah beriman di antara mereka: \"Tahukah kamu bahwa Shaleh di utus (menjadi rasul) oleh Tuhannya?\". Mereka menjawab: \"Sesungguhnya kami beriman kepada wahyu, yang Shaleh diutus untuk menyampaikannya\". (75)"],["p","Orang-orang yang menyombongkan diri berkata: \"Sesungguhnya kami adalah orang yang tidak percaya kepada apa yang kamu imani itu\". (76)"],["p","Kemudian mereka sembelih unta betina itu, dan mereka berlaku angkuh terhadap perintah Tuhan. Dan mereka berkata: \"Hai Shaleh, datangkanlah apa yang kamu ancamkan itu kepada kami, jika (betul) kamu termasuk orang-orang yang diutus (Allah)\". (77)"],["p","Karena itu mereka ditimpa gempa, maka jadilah mereka mayit-mayit yang bergelimpangan di tempat tinggal mereka. (78)"],["p","Maka Shaleh meninggalkan mereka seraya berkata: \"Hai kaumku sesungguhnya aku telah menyampaikan kepadamu amanat Tuhanku, dan aku telah memberi nasihat kepadamu, tetapi kamu tidak menyukai orang-orang yang memberi nasihat\". (79) [ QS. Al A’raaf : 73-79]"],["a","اَلَمْ تَرَ اِلَى الَّذِيْ حَاۤجَّ اِبْرٰهٖمَ فِيْ رَبِّهٖٓ اَنْ اٰتٰىهُ اللّٰهُ الْمُلْكَ ۘ اِذْ قَالَ اِبْرٰهٖمُ رَبِّيَ الَّذِيْ يُحْيٖ وَيُمِيْتُ ۙ قَالَ اَنَا۠ اُحْيٖ وَاُمِيْتُ ۗ قَالَ اِبْرٰهٖمُ فَاِنَّ اللّٰهَ يَأْتِيْ بِالشَّمْسِ مِنَ الْمَشْرِقِ فَأْتِ بِهَا مِنَ الْمَغْرِبِ فَبُهِتَ الَّذِيْ كَفَرَ ۗ وَاللّٰهُ لَا يَهْدِى الْقَوْمَ الظّٰلِمِيْنَ(258) البقرة : 258"],["p","Apakah kamu tidak memperhatikan orang yang mendebat Ibrahim tentang Tuhannya (Allah) karena Allah telah memberikan kepada orang itu pemerintahan (kekuasaan). Ketika Ibrahim mengatakan: \"Tuhanku ialah Yang menghidupkan dan mematikan,\" orang itu berkata: \"Saya dapat menghidupkan dan mematikan\". Ibrahim berkata: \"Sesungguhnya Allah menerbitkan matahari dari timur, maka terbitkanlah dia dari barat,\" lalu heran terdiamlah orang kafir itu; dan Allah tidak memberi petunjuk kepada orang-orang yang dhalim.(258) [QS. Al Baqarah : 258]"],["a","وَقَالَ فِرْعَوْنُ يٰٓاَيُّهَا الْمَلَاُ مَا عَلِمْتُ لَكُمْ مِّنْ اِلٰهٍ غَيْرِيْۚ فَاَوْقِدْ لِيْ يٰهَامٰنُ عَلَى الطِّيْنِ فَاجْعَلْ لِّيْ صَرْحًا لَّعَلِّيْٓ اَطَّلِعُ اِلٰٓى اِلٰهِ مُوْسٰىۙ وَاِنِّيْ لَاَظُنُّهٗ مِنَ الْكٰذِبِيْنَ (38) وَاسْتَكْبَرَ هُوَ وَجُنُوْدُهٗ فِى الْاَرْضِ بِغَيْرِ الْحَقِّ وَظَنُّوْٓا اَنَّهُمْ اِلَيْنَا لَا يُرْجَعُوْنَ (39) القصص : 38-39"],["p","Dan berkata Fir'aun, \"Hai pembesar kaumku, aku tidak mengetahui tuhan bagimu selain aku. Maka bakarlah hai Haamaan untukku tanah liat, kemudian buatkanlah untukku bangunan yang tinggi supaya aku dapat naik melihat Tuhan Musa, dan sesungguhnya aku benar-benar yaqin bahwa dia termasuk orang-orang pendusta\". (38)"],["p","Dan dia (Fir'aun) dan bala tentaranya berlaku sombong di bumi (Mesir) tanpa alasan yang benar dan mereka menyangka bahwa mereka tidak akan dikembalikan kepada Kami. (39) [QS. Al-Qashash : 38-39]"],["a","قَالَ اَجِئْتَنَا لِتُخْرِجَنَا مِنْ اَرْضِنَا بِسِحْرِكَ يٰمُوْسٰى (57) فَلَنَأْتِيَنَّكَ بِسِحْرٍ مِّثْلِهٖ فَاجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِدًا لَّا نُخْلِفُهٗ نَحْنُ وَلَآ اَنْتَ مَكَانًا سُوًى (58) قَالَ مَوْعِدُكُمْ يَوْمُ الزِّيْنَةِ وَاَنْ يُّحْشَرَ النَّاسُ ضُحًى (59) فَتَوَلّٰى فِرْعَوْنُ فَجَمَعَ كَيْدَهٗ ثُمَّ اَتٰى (60) قَالَ لَهُمْ مُّوْسٰى وَيْلَكُمْ لَا تَفْتَرُوْا عَلَى اللّٰهِ كَذِبًا فَيُسْحِتَكُمْ بِعَذَابٍۚ وَقَدْ خَابَ مَنِ افْتَرٰى (61) فَتَنَازَعُوْٓا اَمْرَهُمْ بَيْنَهُمْ وَاَسَرُّوا النَّجْوٰى (62) قَالُوْٓا اِنْ هٰذٰنِ لَسٰحِرٰنِ يُرِيْدَانِ اَنْ يُّخْرِجٰكُمْ مِّنْ اَرْضِكُمْ بِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيْقَتِكُمُ الْمُثْلٰى (63) فَاَجْمِعُوْا كَيْدَكُمْ ثُمَّ ائْتُوْا صَفًّاۚ وَقَدْ اَفْلَحَ الْيَوْمَ مَنِ اسْتَعْلٰى (64) طه : 57 - 64"],["p","Berkata Fir’aun: \"Adakah kamu datang kepada kami untuk mengusir kami dari negeri kami (ini) dengan sihirmu, hai Musa? (57)"],["p","Dan kami pun pasti akan mendatangkan (pula) kepadamu sihir semacam itu, maka buatlah suatu waktu untuk pertemuan antara kami dan kamu, yang kami tidak akan menyalahinya dan tidak (pula) kamu di suatu tempat yang pertengahan (letaknya)\". (58)"],["p","Berkata Musa: \"Waktu untuk pertemuan (kami dengan) kamu itu ialah di hari raya dan hendaklah dikumpulkan manusia pada waktu matahari sepenggalahan naik\". (59)"],["p","Maka Fir’aun meninggalkan (tempat itu), lalu mengatur tipu dayanya, kemudian dia datang. (60)"],["p","Berkata Musa kepada mereka: \"Celakalah kamu, janganlah kamu mengada-adakan kedustaan terhadap Allah, maka Dia membinasakan kamu dengan siksa\". Dan sesungguhnya telah merugi orang yang mengada-adakan kedustaan. (61)"],["p","Maka mereka berbantah-bantahan tentang urusan mereka di antara mereka, dan mereka merahasiakan percakapan (mereka). (62)"],["p","Mereka berkata: \"Sesungguhnya dua orang ini adalah benar-benar ahli sihir yang hendak mengusir kamu dari negeri kamu dengan sihirnya dan hendak melenyapkan kedudukan kamu yang utama. (63)"],["p","Maka himpunkanlah segala daya (sihir) kamu sekalian, kemudian datanglah dengan berbaris, dan sesungguhnya beruntunglah orang yang menang pada hari ini. (64) [QS. Thahaa : 57 -64]"],["a","قَالُوْا يٰمُوْسٰٓى اِمَّآ اَنْ تُلْقِيَ وَاِمَّآ اَنْ نَّكُوْنَ اَوَّلَ مَنْ اَلْقٰى (65) قَالَ بَلْ اَلْقُوْاۚ فَاِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ اِلَيْهِ مِنْ سِحْرِهِمْ اَنَّهَا تَسْعٰى (66) فَاَوْجَسَ فِيْ نَفْسِهٖ خِيْفَةً مُّوْسٰى (67) قُلْنَا لَا تَخَفْ اِنَّكَ اَنْتَ الْاَعْلٰى (68) وَاَلْقِ مَا فِيْ يَمِيْنِكَ تَلْقَفْ مَا صَنَعُوْاۗ اِنَّمَا صَنَعُوْا كَيْدُ سٰحِرٍۗ وَلَا يُفْلِحُ السّٰحِرُ حَيْثُ اَتٰى (69) فَاُلْقِيَ السَّحَرَةُ سُجَّدًا قَالُوْٓا اٰمَنَّا بِرَبِّ هٰرُوْنَ وَمُوْسٰى (70) قَالَ اٰمَنْتُمْ لَهٗ قَبْلَ اَنْ اٰذَنَ لَكُمْۗ اِنَّهٗ لَكَبِيْرُكُمُ الَّذِيْ عَلَّمَكُمُ السِّحْرَۚ فَلَاُقَطِّعَنَّ اَيْدِيَكُمْ وَاَرْجُلَكُمْ مِّنْ خِلَافٍ وَّلَاُصَلِّبَنَّكُمْ فِيْ جُذُوْعِ النَّخْلِۖ وَلَتَعْلَمُنَّ اَيُّنَآ اَشَدُّ عَذَابًا وَّاَبْقٰى(71) قَالُوْا لَنْ نُّؤْثِرَكَ عَلٰى مَا جَاۤءَنَا مِنَ الْبَيِّنٰتِ وَالَّذِيْ فَطَرَنَا فَاقْضِ مَآ اَنْتَ قَاضٍۗ اِنَّمَا تَقْضِيْ هٰذِهِ الْحَيٰوةَ الدُّنْيَا ۗ (72) اِنَّآ اٰمَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطٰيٰنَا وَمَآ اَكْرَهْتَنَا عَلَيْهِ مِنَ السِّحْرِۗ وَاللّٰهُ خَيْرٌ وَّاَبْقٰى(73) طه : 65 - 73"],["p","(Setelah mereka berkumpul) mereka berkata: \"Hai Musa (pilihlah), apakah kamu yang melemparkan (dahulu) atau kamikah orang yang mula-mula melemparkan?\" (65)"],["p","Berkata Musa: \"Silakan kamu sekalian melemparkan\". Maka tiba-tiba tali-tali dan tongkat-tongkat mereka terbayang kepada Musa seakan-akan ia merayap cepat, lantaran sihir mereka. (66)"],["p","Maka Musa merasa takut dalam hatinya. (67)"],["p","Kami berkata: \"Janganlah kamu takut, sesungguhnya kamulah yang paling unggul (menang). (68)"],["p","Dan lemparkanlah apa yang ada di tangan kananmu, niscaya ia akan menelan apa yang mereka perbuat. Sesungguhnya apa yang mereka perbuat itu adalah tipu daya tukang sihir (belaka). Dan tidak akan menang tukang sihir itu, dari mana saja ia datang\". (69)"],["p","Lalu tukang-tukang sihir itu tersungkur dengan bersujud, seraya berkata: \"Kami telah percaya kepada Tuhan Harun dan Musa\". (70)"],["p","Berkata Fir’aun: \"Apakah kamu telah beriman kepadanya (Musa) sebelum aku memberi izin kepadamu sekalian. Sesungguhnya ia adalah pemimpinmu yang mengajarkan sihir kepadamu sekalian. Maka sesungguhnya aku akan memotong tangan dan kaki kamu sekalian dengan bersilang secara bertimbal balik, dan sesungguhnya aku akan menyalib kamu sekalian pada pangkal pohon kurma, dan sesungguhnya kamu akan mengetahui siapa di antara kita yang lebih pedih dan lebih kekal siksanya\". (71)"],["p","Mereka berkata: \"Kami sekali-kali tidak akan mengutamakan kamu daripada bukti-bukti yang nyata (mu’jizat), yang telah datang kepada kami dan daripada Tuhan yang telah menciptakan kami; maka putuskanlah apa yang hendak kamu putuskan. Sesungguhnya kamu hanya akan dapat memutuskan pada kehidupan di dunia ini saja. (72)"],["p","Sesungguhnya kami telah beriman kepada Tuhan kami, agar Dia mengampuni kesalahan-kesalahan kami dan sihir yang telah kamu paksakan kepada kami melakukannya. Dan Allah lebih baik (pahala-Nya) dan lebih kekal (adzab-Nya).\" (73) [QS. Thaahaa : 65-73]"],["a","اِنَّ قَارُوْنَ كَانَ مِنْ قَوْمِ مُوْسٰى فَبَغٰى عَلَيْهِمْ ۖ وَاٰتَيْنٰهُ مِنَ الْكُنُوْزِ مَآ اِنَّ مَفَاتِحَهٗ لَتَنُوْۤاُ بِالْعُصْبَةِ اُولِى الْقُوَّةِ اِذْ قَالَ لَهٗ قَوْمُهٗ لَا تَفْرَحْ اِنَّ اللّٰهَ لَا يُحِبُّ الْفَرِحِيْنَ(76) وَابْتَغِ فِيْمَآ اٰتٰىكَ اللّٰهُ الدَّارَ الْاٰخِرَةَ وَلَا تَنْسَ نَصِيْبَكَ مِنَ الدُّنْيَا وَاَحْسِنْ كَمَآ اَحْسَنَ اللّٰهُ اِلَيْكَ وَلَا تَبْغِ الْفَسَادَ فِى الْاَرْضِ ۗ اِنَّ اللّٰهَ لَا يُحِبُّ الْمُفْسِدِيْنَ(77) قَالَ اِنَّمَآ اُوْتِيْتُهٗ عَلٰى عِلْمٍ عِنْدِيْۗ اَوَلَمْ يَعْلَمْ اَنَّ اللّٰهَ قَدْ اَهْلَكَ مِنْ قَبْلِهٖ مِنَ الْقُرُوْنِ مَنْ هُوَ اَشَدُّ مِنْهُ قُوَّةً وَّاَكْثَرُ جَمْعًا ۗ وَلَا يُسْـَٔلُ عَنْ ذُنُوْبِهِمُ الْمُجْرِمُوْنَ(78) القصص : 76 - 78"],["p","Sesungguhnya Qarun adalah termasuk kaum Musa, maka ia berlaku aniaya terhadap mereka, dan Kami telah menganugerahkan kepadanya perbendaharaan harta yang kunci-kuncinya sungguh berat dipikul oleh sejumlah orang yang kuat-kuat. (Ingatlah) ketika kaumnya berkata kepadanya: \"Janganlah kamu terlalu bangga; sesungguhnya Allah tidak menyukai orang-orang yang terlalu membanggakan diri\". (76)"],["p","Dan carilah pada apa yang telah dianugerahkan Allah kepadamu (kebahagiaan) negeri akhirat, dan janganlah kamu melupakan bahagianmu dari (keni’matan) duniawi dan berbuat baiklah (kepada orang lain) sebagaimana Allah telah berbuat baik kepadamu, dan janganlah kamu berbuat kerusakan di (muka) bumi. Sesungguhnya Allah tidak menyukai orang-orang yang berbuat kerusakan. (77)"],["p","Qarun berkata: \"Sesungguhnya aku hanya diberi harta itu, karena ilmu yang ada padaku\". Dan apakah ia tidak mengetahui, bahwasanya Allah sungguh telah membinasakan ummat-ummat sebelumnya yang lebih kuat daripadanya, dan lebih banyak mengumpulkan harta? Dan tidaklah perlu ditanya kepada orang-orang yang berdosa itu, tentang dosa-dosa mereka. (78) [QS. Al-Qashash : 76-78]"],["a","فَخَرَجَ عَلٰى قَوْمِهٖ فِيْ زِيْنَتِهٖ ۗ قَالَ الَّذِيْنَ يُرِيْدُوْنَ الْحَيٰوةَ الدُّنْيَا يٰلَيْتَ لَنَا مِثْلَ مَآ اُوْتِيَ قَارُوْنُۙ اِنَّهٗ لَذُوْ حَظٍّ عَظِيْمٍ (79) وَقَالَ الَّذِيْنَ اُوْتُوا الْعِلْمَ وَيْلَكُمْ ثَوَابُ اللّٰهِ خَيْرٌ لِّمَنْ اٰمَنَ وَعَمِلَ صَالِحًا ۚ وَلَا يُلَقّٰىهَآ اِلَّا الصّٰبِرُوْنَ(80) فَخَسَفْنَا بِهٖ وَبِدَارِهِ الْاَرْضَ ۗ فَمَا كَانَ لَهٗ مِنْ فِئَةٍ يَّنْصُرُوْنَهٗ مِنْ دُوْنِ اللّٰهِ ۖ وَمَا كَانَ مِنَ الْمُنْتَصِرِيْنَ (81) وَاَصْبَحَ الَّذِيْنَ تَمَنَّوْا مَكَانَهٗ بِالْاَمْسِ يَقُوْلُوْنَ وَيْكَاَنَّ اللّٰهَ يَبْسُطُ الرِّزْقَ لِمَنْ يَّشَاۤءُ مِنْ عِبَادِهٖ وَيَقْدِرُۚ لَوْلَآ اَنْ مَّنَّ اللّٰهُ عَلَيْنَا لَخَسَفَ بِنَا ۗ وَيْكَاَنَّهٗ لَا يُفْلِحُ الْكٰفِرُوْنَ (82) القصص : 79 - 82"],["p","Maka keluarlah Qarun kepada kaumnya dalam kemegahannya. Berkatalah orang-orang yang menghendaki kehidupan dunia: \"Moga-moga kiranya kita mempunyai seperti apa yang telah diberikan kepada Qarun; sesungguhnya ia benar-benar mempunyai keberuntungan yang besar\". (79)"],["p","Berkatalah orang-orang yang dianugerahi ilmu: \"Kecelakaan yang besarlah bagimu, pahala Allah adalah lebih baik bagi orang-orang yang beriman dan beramal shaleh, dan tidak diperoleh pahala itu kecuali oleh orang-orang yang shabar\". (80)"],["p","Maka Kami benamkanlah Qarun beserta rumahnya ke dalam bumi. Maka tidak ada baginya suatu golongan pun yang menolongnya terhadap adzab Allah, dan tiadalah ia termasuk orang-orang (yang dapat) membela (dirinya). (81)"],["p","Dan jadilah orang-orang yang kemarin mencita-citakan kedudukan Qarun itu berkata: \"Aduhai, benarlah Allah melapangkan rezeki bagi siapa yang Dia kehendaki dari hamba-hambaNya dan menyempitkannya; kalau Allah tidak melimpahkan karunia-Nya atas kita, benar-benar Dia telah membenamkan kita (pula). Aduhai benarlah, tidak beruntung orang-orang yang mengingkari (ni’mat Allah)\". (82) [QS. Al-Qashash : 79-82]"],["p","Hadits-hadits Nabi SAW :"],["a","عَنْ عَبْدِ اللهِ بْنِ مَسْعُوْدٍ عَنِ النَّبِيِّ ﷺ قَالَ: لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِيْ قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ كِبْرٍ. قَالَ رَجُلٌ: اِنَّ الرَّجُلَ يُحِبُّ اَنْ يَكُوْنَ ثَوْبُهُ حَسَنًا وَنَعْلُهُ حَسَنَةً؟ قَالَ: اِنَّ اللهَ جَمِيْلٌ يُحِبُّ الْجَمَالَ. اَلْكِبْرُ بَطَرُ الْحَقِّ وَغَمْطُ النَّاسِ. مسلم 1: 93 رقم :147"],["p","Dari Abdullah bin Mas'ud, dari Nabi SAW beliau bersabda, \"Tidak akan masuk surga orang yang di dalam hatinya ada sebesar dzarrah dari sombong\". Lalu ada seorang laki-laki bertanya : \"Sesungguhnya ada orang senang bajunya itu bagus dan sandalnya bagus, (yang demikian itu bagaimana, ya Rasulullah ?\"). Rasulullah SAW bersabda : \"Sesungguhnya Allah itu indah dan suka pada keindahan. Sombong itu ialah menolak kebenaran dan merendahkan manusia\". [HR. Muslim juz 1, hal. 93, no 147]"],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: يَقُوْلُ اللهُ سُبْحَانَهُ: اَلْكِبْرِيَاءُ رِدَاءِيْ وَالْعَظَمَةُ اِزَارِيْ. فَمَنْ نَازَعَنِيْ وَاحِدًا مِنْهُمَا اَلْقَيْتُهُ فِى النَّارِ. ابن ماجه 2: 1397، رقم: 4175"],["p","Dari Ibnu Abbas, ia berkata : Rasulullah SAW bersabda, \"Allah Yang Maha Suci berfirman : Sombong itu adalah selendang-Ku dan kebesaran itu adalah pakaian-Ku, maka barangsiapa mencabut salah satunya dari-Ku, Aku akan melemparkan orang itu ke neraka\". [HR. Ibnu Majah juz 2, hal. 1397, no. 4175]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اِنَّ اللهَ لَا يَنْظُرُ اِلىَ صُوَرِكُمْ وَاَمْوَالِكُمْ وَلٰكِنْ يَنْظُرُ اِلىَ قُلُوْبِكُمْ وَاَعْمَالِكُمْ. مسلم 4: 1987 رقم 34"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Sesungguhnya Allah tidak melihat (menilai) bentuk tubuhmu dan harta-bendamu, tetapi Allah melihat (menilai) pada hatimu dan amalmu\". [HR. Muslim juz 4, hal. 1987 no 34]"],["a","عَنْ اَبِيْ هُرَيْرَةَ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: يَقُوْلُ الْعَبْدُ: مَالِيْ، مَالِيْ. اِنَّمَا لَهُ مِنْ مَالِهِ ثَلَاثٌ، مَا اَكَلَ فَاَفْنَى اَوْ لَبِسَ فَاَبْلَى اَوْ اَعْطَى فَاقْتَنَى، وَمَا سِوَى ذٰلِكَ فَهُوَ ذَاهِبٌ وَتَارِكُهُ لِلنَّاسِ. مسلم 4: 2273 رقم : 4"],["p","Dari Abu Hurairah, bahwasanya Rasulullah SAW bersabda : Manusia berkata, \"Ini hartaku, ini hartaku !\". Padahal yang ia punyai itu hanya tiga macam, yaitu apa yang ia makan sehingga habis, atau sesuatu yang ia pakai sehingga usang, atau harta yang ia shadaqahkan sehingga menjadi tabungan (diakhirat). Adapun yang selain dari itu, semuanya akan hilang dan ia tinggalkan untuk orang lain\". [HR. Muslim juz 4, hal. 2273, no. 4]"],["p","(Bersambung)"]],"c20220213_1274":[["p","Ahad, 13 Februari 2022/12 Rajab 1443 Brosur No.: 2069/2109/IA"],["p","Penyebab Kerasnya Hati (3)"],["h","6. Cinta dunia"],["p","Firman Allah SWT :"],["a","اِعْلَمُوْٓا اَنَّمَا الْحَيٰوةُ الدُّنْيَا لَعِبٌ وَّلَهْوٌ وَّزِيْنَةٌ وَّتَفَاخُرٌۢ بَيْنَكُمْ وَتَكَاثُرٌ فِى الْاَمْوَالِ وَالْاَوْلَادِۗ كَمَثَلِ غَيْثٍ اَعْجَبَ الْكُفَّارَ نَبَاتُهٗ ثُمَّ يَهِيْجُ فَتَرٰىهُ مُصْفَرًّا ثُمَّ يَكُوْنُ حُطَامًاۗ وَفِى الْاٰخِرَةِ عَذَابٌ شَدِيْدٌۙ وَّمَغْفِرَةٌ مِّنَ اللّٰهِ وَرِضْوَانٌ ۗ وَمَا الْحَيٰوةُ الدُّنْيَآ اِلَّا مَتَاعُ الْغُرُوْرِ(20) الحديد:20"],["p","Ketahuilah, bahwa sesungguhnya kehidupan dunia itu hanyalah permainan dan suatu yang melalaikan, perhiasan dan bermegah-megah antara kamu serta berbangga-bangga tentang banyaknya harta dan anak, seperti hujan yang tanam-tanamannya mengagumkan para petani; kemudian tanaman itu menjadi kering dan kamu lihat warnanya kuning kemudian menjadi hancur. Dan di akhirat (nanti) ada adzab yang keras dan ampunan dari Allah serta keridlaan-Nya. Dan kehidupan dunia ini tidak lain hanyalah kesenangan yang menipu. [QS. Al-Hadiid : 20]"],["a","زُيِّنَ لِلنَّاسِ حُبُّ الشَّهَوٰتِ مِنَ النِّسَاۤءِ وَالْبَنِيْنَ وَالْقَنَاطِيْرِ الْمُقَنْطَرَةِ مِنَ الذَّهَبِ وَالْفِضَّةِ وَالْخَيْلِ الْمُسَوَّمَةِ وَالْاَنْعَامِ وَالْحَرْثِ ۗ ذٰلِكَ مَتَاعُ الْحَيٰوةِ الدُّنْيَا ۗ وَاللّٰهُ عِنْدَهٗ حُسْنُ الْمَاٰبِ (14) ال عمران: 14"],["p","Dijadikan indah pada (pandangan) manusia kecintaan kepada apa-apa yang diingini, yaitu: wanita-wanita, anak-anak, harta yang banyak dari jenis emas, perak, kuda pilihan, binatang-binatang ternak dan sawah ladang. Itulah kesenangan hidup di dunia, dan di sisi Allah-lah tempat kembali yang baik (surga). [QS. Ali ‘Imraan : 14]"],["a","وَمَا هٰذِهِ الْحَيٰوةُ الدُّنْيَآ اِلَّا لَهْوٌ وَّلَعِبٌۗ وَاِنَّ الدَّارَ الْاٰخِرَةَ لَهِيَ الْحَيَوَانُۘ لَوْ كَانُوْا يَعْلَمُوْنَ (64) العنكبوت: 64"],["p","Dan tiadalah kehidupan dunia ini melainkan senda gurau dan main-main. Dan sesungguhnya akhirat itulah yang sebenarnya kehidupan, kalau mereka mengetahui. [QS. Al-‘Ankabuut : 64]"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تُلْهِكُمْ اَمْوَالُكُمْ وَلَآ اَوْلَادُكُمْ عَنْ ذِكْرِ اللّٰهِ ۚ وَمَنْ يَّفْعَلْ ذٰلِكَ فَاُولٰۤىِٕكَ هُمُ الْخٰسِرُوْنَ (9) المنافقون: 9"],["p","Hai orang-orang yang beriman, janganlah harta-hartamu dan anak-anakmu melalaikan kamu dari mengingat Allah. Barangsiapa yang berbuat demikian, maka mereka itulah orang-orang yang rugi. [QS. Al-Munaafiquun : 9]"],["p","Hadits-hadits Nabi SAW:"],["a","عَنْ عَبَّاسِ بْنِ سَهْلِ بْنِ سَعْدٍ قَالَ: سَمِعْتُ ابْنَ الزُّبَيْرِ عَلَى الْمِنْبَرِ بِـمَكَّةَ فِي خُطْبَتِهِ يَقُوْلُ: يَا اَيُّهَا النَّاسُ، اِنَّ النَّبِيَّ ﷺ كَانَ يَقُوْلُ: لَوْ اَنَّ ابْنَ آدَمَ اُعْطِيَ وَادِيًا مَلْأً مِنْ ذَهَبٍ اَحَبَّ اِلَيْهِ ثَانِيًا وَلَوْ اُعْطِيَ ثَانِيًا اَحَبَّ اِلَيْهِ ثَالِثًا وَلَا يَسُدُّ جَوْفَ ابْنِ آدَمَ اِلَّا التُّرَابُ، وَيَتُوْبُ اللهُ عَلَى مَنْ تَابَ. البخارى 7: 175"],["p","Dari 'Abbas bin Sahl, bin Sa'ad, ia berkata : Aku mendengar Ibnu Zubair berkhutbah di atas mimbar di Makkah, ia berkata : Wahai para manusia, sesungguhnya Nabi SAW bersabda, \"Seandainya anak Adam diberi kekayaan harta satu lembah penuh berupa emas, tentu ia masih menginginkan lembah yang kedua, dan seandainya ia diberi dua lembah emas, tentu ia masih menginginkan lembah yang ketiga, dan tidak ada yang menutup perut anak Adam kecuali tanah. Dan Allah akan menerima taubatnya orang yang mau bertaubat\". [HR Bukhari juz 7, hal. 175]"],["a","عَنْ قَيْسٍ قَالَ: سَمِعْتُ مُسْتَوْرِدًا اَخَا بَنِيْ فِهْرٍ يَقُوْلُ: قَالَ رَسُوْلُ اللهِ ﷺ: وَاللهِ، مَا الدُّنْيَا فِى الْاٰخِرَةِ اِلَّا مِثْلُ مَا يَجْعَلُ اَحَدُكُمْ اِصْبَعَهُ هٰذِهِ (وَاَشَارَ يَحْيَى بِالسَّبَّابَةِ) فِى الْيَمِّ فَلْيَنْظُرْ بِـمَ يَرْجِعُ. مسلم 4: 2193 رقم : 55"],["p","Dari Qais, ia berkata : Aku mendengar Mustaurid saudara dari Bani Fihr berkata : Rasulullah SAW bersabda, \"Demi Allah, tidaklah kehidupan dunia ini jika dibandingkan dengan kehidupan akhirat, kecuali seperti salah seorang diantara kalian memasukkan jarinya ini ke dalam laut. (Yahya (perawi) sambil menunjukkan jari telunjuknya), maka lihatlah seberapa air yang menetes kembali\". [HR. Muslim juz 4, hal. 2193, no 55]"],["a","عَنْ سَعِيْدِ بْنِ الْمُسَيَّبِ اَنَّ اَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ سَمِعْتُ رَسُولَ اللهِ ﷺ يَقُوْلُ: لَا يَزَالُ قَلْبُ الْكَبِيْرِ شَابًّا فِي اثْنَتَيْنِ، فِي حُبِّ الدُّنْيَا وَطُوْلِ الْأَمَلِ. البخارى 7: 171"],["p","Dari Sa'id bin Musayyab, bahwasanya Abu Hurairah RA berkata, \"Aku mendengar Rasulullah SAW bersabda, \"Senantiasalah hati orang tua menjadi muda untuk mendapatkan dua keinginan, yaitu cinta dunia dan tingginya keinginan\". [HR. Bukhari juz 7, hal. 171]"],["a","عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَوْ كَانَتِ الدُّنْيَا تَعْدِلُ عِنْدَ اللهِ جَنَاحَ بَعُوْضَةٍ مَا سَقَى كَافِرًا مِنْهَا شَرْبَةَ مَاءٍ. الترمذى 3: 383، رقم: 2422"],["p","Dari Sahl bin Sa'ad, ia berkata : Rasulullah SAW bersabda, \"Seandainya dunia ini di sisi Allah ada nilainya sesayap nyamuk, niscaya Allah tidak akan memberi minum kepada orang kafir walaupun seteguk air\". [HR. Tirmidzi juz 3, ha. 383, no. 2422]"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ اَنَّ رَسُوْلَ اللهِ ﷺ مَرَّ بِالسُّوْقِ دَاخِلًا مِنْ بَعْضِ الْعَالِيَةِ وَالنَّاسُ كَنَفَتَهُ، فَمَرَّ بِجَدْىٍ اَسَكَّ مَيِّتٍ، فَتَنَاوَلَهُ فَاَخَذَ بِاُذُنِهِ ثُـمَّ قَالَ: اَيُّكُمْ يُحِبُّ اَنَّ هٰذَا لَهُ بِدِرْهَمٍ؟ فَقَالُوْا: مَا نُحِبُّ اَنَّهُ لَنَا بِشَيْءٍ وَمَا نَصْنَعُ بِهِ؟ قَالَ: اَتُحِبُّوْنَ اَنَّهُ لَكُمْ؟ قَالُوْا: وَاللهِ، لَوْ كَانَ حَيًّا كَانَ عَيْبًا فِيْهِ لِاَنَّهُ اَسَكُّ، فَكَيْفَ وَهُوَ مَيِّتٌ؟ فَقَالَ: فَوَ اللهِ، لَلدُّنْيَا اَهْوَنُ عَلَى اللهِ مِنْ هٰذَا عَلَيْكُمْ. مسلم 4: 2272"],["p","Dari Jabir bin 'Abdullah, bahwasanya Rasulullah SAW pernah melewati sebuah pasar, beliau datang dari bagian tanah yang tinggi, sedangkan para shahabat di samping (kiri kanan) beliau. Kemudian beliau melewati bangkai seekor anak kambing yang telinganya perung (kecil), lalu beliau mengambilnya dengan memegang telinganya. Kemudian beliau bersabda, \"Siapakah diantara kalian yang mau membeli ini dengan satu dirham ?\". Para shahabat menjawab, \"Kami tidak mau menukarnya dengan sesuatu milik kami, dan akan kami apakan ?\".Beliau SAW bersabda, \"Apakah kalian suka kalau bangkai ini saya berikan saja untuk kalian ?\". Mereka menjawab, \"Demi Allah,seandainya anak kambing itu dalam keadaan hidup saja ada cacatnya, karena telinganya perung, apalagi anak kambing itu sudah menjadi bangkai ?\". Beliau bersabda, \"Demi Allah, sungguh dunia ini di sisi Allah nilainya lebih rendah daripada bangkai ini di hadapan kalian\". [HR. Muslim juz 4, hal. 2272, no. 2]"],["a","عَنْ مُطَرِّفٍ عَنْ اَبِيْهِ قَالَ: اَتَيْتُ النَّبِىَّ ﷺ وَهُوَ يَقْرَأُ (اَلْهٰىكُمُ التَّكَاثُرُ) قَالَ: يَقُوْلُ ابْنُ آدَمَ: مَالِيْ، مَالِيْ. قَالَ: وَهَلْ لَكَ يَا ابْنَ آدَمَ مِنْ مَالِكَ اِلَّا مَا اَكَلْتَ فَاَفْنَيْتَ اَوْ لَبِسْتَ فَاَبْلَيْتَ اَوْ تَصَدَّقْتَ فَاَمْضَيْتَ. مسلم 4: 2273"],["p","Dari Muthorrif, dari ayahnya, ia berkata : Saya datang kepada Nabi SAW pada waktu itu beliau membaca ayat \"alhaakumut takaatsur\" (Bermegah-megahan telah melalaikan kalian). Beliau bersabda : Anak Adam berkata, \"Ini hartaku, ini hartaku !\". Padahal hai anak Adam, tidaklah kamu punyai dari hartamu melainkan apa yang kamu makan sehingga habis, atau yang kamu pakai sehingga usang, atau yang kamu sedeqahkan sehingga menjadi tabungan (di akhirat)\". [HR. Muslim juz 4, hal. 2273, no. 3]"],["a","عَنْ ثَوْبَانَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: يُوْشِكُ الْاُمَمُ اَنْ تَدَاعَى عَلَيْكُمْ كَمَا تَدَاعَى الْاَكَلَةُ اِلَى قَصْعَتِهَا. فَقَالَ قَائِلٌ: وَمِنْ قِلَّةٍ نَحْنُ يَوْمَئِذٍ؟ قَالَ: بَلْ اَنْتُمْ يَوْمَئِذٍ كَثِيْرٌ وَلٰكِنَّكُمْ غُثَاءٌ كَغُثَاءِ السَّيْلِ وَلَيَنْزِعَنَّ اللهُ مِنْ صُدُوْرِ عَدُوِّكُمُ الْمَهَابَةَ مِنْكُمْ وَلَيَقْذِفَنَّ اللهُ فِيْ قُلُوْبِكُمُ الْوَهْنَ. فَقَالَ قَائِلٌ: يَا رَسُوْلَ اللهِ، وَمَا الْوَهْنُ؟ قَالَ: حُبُّ الدُّنْيَا وَكَرَاهِيَةُ الْمَوْتِ. ابو داود 4: 111، رقم: 4297"],["p","Dari Tsauban, ia berkata : Rasulullah SAW bersabda, “Hampir-hampir orang-orang (musuh-musuh kalian) memperebutkan kalian (umat Islam), layaknya orang-orang rakus memperebutkan makanan pada satu nampan. Ada seorang yang bertanya, \"Apakah kami waktu itu berjumlah sedikit ?\". Rasulullah SAW menjawab, “Bahkan jumlah kalian pada waktu itu sangat banyak, namun kalian seperti buih pada air bah. Dan sungguh Allah akan mencabut rasa takut dari dada musuh kalian, dan akan memasukkan ke dalam hati kalian Al-Wahn”. Ada seorang yang bertanya, \"Wahai Rasulullah, apakah Al-Wahn itu ?\". Beliau menjawab, “Cinta dunia dan takut mati”. [HR. Abu Dawud juz 4, hal. 111, no. 4297]"],["a","عَنْ اَنَسٍ قَالَ : قَالَ رَسُوْلُ اللهِ ص : اَرْبَعَةٌ مِنَ الشَّقَاءِ، جُمُوْدُ الْعَيْنِ، وَ قَسْوَةُ الْقَلْبِ، وَ طُوْلُ الْأَمَلِ، وَ الْحِرْصُ عَلَي الدُّنْيَا . البزار في مجمع الزوائد 10 : 278 رقم 17685 ، فيه هانئ بن المتوكل ، و هو ضعيف"],["p","Dari Anas, ia berkata: Rasulullah SAW bersabda : “Ada empat hal dari kecelakaan, yaitu : 1) kerasnya mata (tidak menangis takut kepada Allah, 2) kerasnya hati, 3) panjang angan angan dan 4) rakus kepada dunia.” [HR. Al Bazzar, dalam Majmauz Zawaaid juz 10, hal 278 no 17685, dlo’if, karena dalam isnadnya ada perawi bernama Hani’ bin Al Mutawakkil]"],["p","7. Tidak memperhatikan ayat ayat kauniyah."],["p","Firman Allah SWT:"],["a","اِنَّ فِى السَّمٰوٰتِ وَالْاَرْضِ لَاٰيٰتٍ لِّلْمُؤْمِنِيْنَۗ (3)وَفِيْ خَلْقِكُمْ وَمَا يَبُثُّ مِنْ دَاۤبَّةٍ اٰيٰتٌ لِّقَوْمٍ يُّوْقِنُوْنَۙ (4) وَاخْتِلَافِ الَّيْلِ وَالنَّهَارِ وَمَآ اَنْزَلَ اللّٰهُ مِنَ السَّمَاۤءِ مِنْ رِّزْقٍ فَاَحْيَا بِهِ الْاَرْضَ بَعْدَ مَوْتِهَا وَتَصْرِيْفِ الرِّيٰحِ اٰيٰتٌ لِّقَوْمٍ يَّعْقِلُوْنَ (5)تِلْكَ اٰيٰتُ اللّٰهِ نَتْلُوْهَا عَلَيْكَ بِالْحَقِّ ۚ فَبِاَيِّ حَدِيْثٍۢ بَعْدَ اللّٰهِ وَاٰيٰتِهٖ يُؤْمِنُوْنَ (6) الجاثية : 3-6"],["p","Sesungguhnya pada langit dan bumi benar-benar terdapat tanda-tanda (kekuasaan Allah) untuk orang-orang yang beriman. (3)"],["p","Dan pada penciptaan kamu dan pada binatang-binatang yang melata yang bertebaran (di muka bumi) terdapat tanda-tanda (kekuasaan Allah) untuk kaum yang meyakini, (4)"],["p","dan pada pergantian malam dan siang dan hujan yang diturunkan Allah dari langit lalu dihidupkan-Nya dengan air hujan itu bumi sesudah matinya; dan pada perkisaran angin terdapat pula tanda-tanda (kekuasaan Allah) bagi kaum yang berakal. (5)"],["p","Itulah ayat-ayat Allah yang Kami membacakannya kepadamu dengan sebenarnya; maka dengan perkataan manakah lagi mereka akan beriman sesudah (kalam) Allah dan keterangan-keterangan-Nya. (6) [QS. Al Jaatsiyah : 3-6]"],["a","اَوَلَمْ يَرَ الَّذِيْنَ كَفَرُوْٓا اَنَّ السَّمٰوٰتِ وَالْاَرْضَ كَانَتَا رَتْقًا فَفَتَقْنٰهُمَاۗ وَجَعَلْنَا مِنَ الْمَاۤءِ كُلَّ شَيْءٍ حَيٍّ ۗ اَفَلَا يُؤْمِنُوْنَ(30)وَجَعَلْنَا فِى الْاَرْضِ رَوَاسِيَ اَنْ تَمِيْدَ بِهِمْ ۖ وَجَعَلْنَا فِيْهَا فِجَاجًا سُبُلًا لَّعَلَّهُمْ يَهْتَدُوْنَ(31)وَجَعَلْنَا السَّمَاۤءَ سَقْفًا مَّحْفُوْظًاۚ وَهُمْ عَنْ اٰيٰتِهَا مُعْرِضُوْنَ(32)وَهُوَ الَّذِيْ خَلَقَ الَّيْلَ وَالنَّهَارَ وَالشَّمْسَ وَالْقَمَرَۗ كُلٌّ فِيْ فَلَكٍ يَّسْبَحُوْنَ(33) الانبياء : 30 - 33"],["p","Dan apakah orang-orang yang kafir tidak mengetahui bahwasanya langit dan bumi itu keduanya dahulu adalah suatu yang padu, kemudian Kami pisahkan antara keduanya. Dan dari air Kami jadikan segala sesuatu yang hidup. Maka mengapakah mereka tiada juga beriman? (30)"],["p","Dan telah Kami jadikan di bumi ini gunung-gunung yang kokoh supaya bumi itu (tidak) goncang bersama mereka, dan telah Kami jadikan (pula) di bumi itu jalan-jalan yang luas, agar mereka mendapat petunjuk. (31)"],["p","Dan Kami menjadikan langit itu sebagai atap yang terpelihara, sedang mereka berpaling dari segala tanda-tanda (kekuasaan Allah) yang terdapat padanya. (32)"],["p","Dan Dialah yang telah menciptakan malam dan siang, matahari dan bulan. Masing-masing dari keduanya itu beredar di dalam garis edarnya.(33) [QS. Al Anbiyaa’ : 30 – 33]"],["a","اَلَمْ تَرَ اَنَّ اللّٰهَ يُسَبِّحُ لَهٗ مَنْ فِى السَّمٰوٰتِ وَالْاَرْضِ وَالطَّيْرُ صٰۤفّٰتٍۗ كُلٌّ قَدْ عَلِمَ صَلَاتَهٗ وَتَسْبِيْحَهٗۗ وَاللّٰهُ عَلِيْمٌۢ بِمَا يَفْعَلُوْنَ (41) وَلِلّٰهِ مُلْكُ السَّمٰوٰتِ وَالْاَرْضِۚ وَاِلَى اللّٰهِ الْمَصِيْرُ (42) اَلَمْ تَرَ اَنَّ اللّٰهَ يُزْجِيْ سَحَابًا ثُمَّ يُؤَلِّفُ بَيْنَهٗ ثُمَّ يَجْعَلُهٗ رُكَامًا فَتَرَى الْوَدْقَ يَخْرُجُ مِنْ خِلٰلِهٖۚ وَيُنَزِّلُ مِنَ السَّمَاۤءِ مِنْ جِبَالٍ فِيْهَا مِنْۢ بَرَدٍ فَيُصِيْبُ بِهٖ مَنْ يَّشَاۤءُ وَيَصْرِفُهٗ عَنْ مَّنْ يَّشَاۤءُۗ يَكَادُ سَنَا بَرْقِهٖ يَذْهَبُ بِالْاَبْصَارِ ۗ (43) يُقَلِّبُ اللّٰهُ الَّيْلَ وَالنَّهَارَۗ اِنَّ فِيْ ذٰلِكَ لَعِبْرَةً لِّاُولِى الْاَبْصَارِ (44) وَاللّٰهُ خَلَقَ كُلَّ دَاۤبَّةٍ مِّنْ مَّاۤءٍۚ فَمِنْهُمْ مَّنْ يَّمْشِيْ عَلٰى بَطْنِهٖۚ وَمِنْهُمْ مَّنْ يَّمْشِيْ عَلٰى رِجْلَيْنِۚ وَمِنْهُمْ مَّنْ يَّمْشِيْ عَلٰٓى اَرْبَعٍۗ يَخْلُقُ اللّٰهُ مَا يَشَاۤءُۗ اِنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ (45) النور : 41-45"],["p","Tidakkah kamu tahu bahwasanya Allah: kepada-Nya bertasbih apa yang di langit dan di bumi dan (juga) burung dengan mengembangkan sayapnya. Masing-masing telah mengetahui (cara) shalat dan tasbihnya, dan Allah Maha Mengetahui apa yang mereka kerjakan. (41)"],["p","Dan kepunyaan Allah-lah kerajaan langit dan bumi dan kepada Allah-lah kembali (semua makhluk). (42)"],["p","Tidakkah kamu melihat bahwa Allah mengarak awan, kemudian mengumpulkan antara (bagian-bagian) nya, kemudian menjadikannya bertindih-tindih, maka kelihatanlah olehmu hujan keluar dari celah-celahnya dan Allah (juga) menurunkan (butiran-butiran) es dari langit, (yaitu) dari (gumpalan-gumpalan awan seperti) gunung-gunung, maka ditimpakan-Nya (butiran-butiran) es itu kepada siapa yang dikehendaki-Nya dan dipalingkan-Nya dari siapa yang dikehendaki-Nya. Kilauan kilat awan itu hampir-hampir menghilangkan penglihatan. (43)"],["p","Allah mempergantikan malam dan siang. Sesungguhnya pada yang demikian itu, terdapat pelajaran yang besar bagi orang-orang yang mempunyai penglihatan. (44)"],["p","Dan Allah telah menciptakan semua jenis hewan dari air, maka sebagian dari hewan itu ada yang berjalan di atas perutnya dan sebagian berjalan dengan dua kaki, sedang sebagian (yang lain) berjalan dengan empat kaki. Allah menciptakan apa yang dikehendaki-Nya, sesungguhnya Allah Maha Kuasa atas segala sesuatu. (45) [QS. An Nuur : 41-45]"],["a","اَفَلَا يَنْظُرُوْنَ اِلَى الْاِبِلِ كَيْفَ خُلِقَتْۗ (17) وَاِلَى السَّمَاۤءِ كَيْفَ رُفِعَتْۗ (18) وَاِلَى الْجِبَالِ كَيْفَ نُصِبَتْۗ (19) وَاِلَى الْاَرْضِ كَيْفَ سُطِحَتْ (20) الغاشية : 17 – 20"],["p","Maka apakah mereka tidak memperhatikan unta, bagaimana dia diciptakan,(17)"],["p","Dan langit, bagaimana ia ditinggikan? (18)"],["p","Dan gunung-gunung, bagaimana ia ditegakkan? (19)"],["p","Dan bumi, bagaimana ia dihamparkan? (20) [QS. Al Ghaatsiyah : 17-20]"],["a","هُوَ الَّذِيْ جَعَلَ الشَّمْسَ ضِيَاۤءً وَّالْقَمَرَ نُوْرًا وَّقَدَّرَهٗ مَنَازِلَ لِتَعْلَمُوْا عَدَدَ السِّنِيْنَ وَالْحِسَابَۗ مَا خَلَقَ اللّٰهُ ذٰلِكَ اِلَّا بِالْحَقِّ ۗ يُفَصِّلُ الْاٰيٰتِ لِقَوْمٍ يَّعْلَمُوْنَ (5) اِنَّ فِى اخْتِلَافِ الَّيْلِ وَالنَّهَارِ وَمَا خَلَقَ اللّٰهُ فِى السَّمٰوٰتِ وَالْاَرْضِ لَاٰيٰتٍ لِّقَوْمٍ يَّتَّقُوْنَ(6) يونس : 5-6"],["p","Dia-lah yang menjadikan matahari bersinar dan bulan bercahaya dan ditetapkan-Nya manzilah-manzilah (tempat-tempat) bagi perjalanan bulan itu, supaya kamu mengetahui bilangan tahun dan perhitungan (waktu). Allah tidak menciptakan yang demikian itu melainkan dengan hak. Dia menjelaskan tanda-tanda (kebesaran-Nya) kepada orang-orang yang mengetahui.(5)"],["p","Sesungguhnya pada pertukaran malam dan siang itu dan pada apa yang diciptakan Allah di langit dan di bumi, benar-benar terdapat tanda-tanda (kekuasaan-Nya) bagi orang-orang yang bertakwa.(6) [QS. Yuunus : 5-6]"],["a","وَمِنْ اٰيٰتِهٖٓ اَنْ خَلَقَكُمْ مِّنْ تُرَابٍ ثُمَّ اِذَآ اَنْتُمْ بَشَرٌ تَنْتَشِرُوْنَ (20) وَمِنْ اٰيٰتِهٖٓ اَنْ خَلَقَ لَكُمْ مِّنْ اَنْفُسِكُمْ اَزْوَاجًا لِّتَسْكُنُوْٓا اِلَيْهَا وَجَعَلَ بَيْنَكُمْ مَّوَدَّةً وَّرَحْمَةً ۗاِنَّ فِيْ ذٰلِكَ لَاٰيٰتٍ لِّقَوْمٍ يَّتَفَكَّرُوْنَ (21) وَمِنْ اٰيٰتِهٖ خَلْقُ السَّمٰوٰتِ وَالْاَرْضِ وَاخْتِلَافُ اَلْسِنَتِكُمْ وَاَلْوَانِكُمْۗ اِنَّ فِيْ ذٰلِكَ لَاٰيٰتٍ لِّلْعٰلِمِيْنَ (22) وَمِنْ اٰيٰتِهٖ مَنَامُكُمْ بِالَّيْلِ وَالنَّهَارِ وَابْتِغَاۤؤُكُمْ مِّنْ فَضْلِهٖۗ اِنَّ فِيْ ذٰلِكَ لَاٰيٰتٍ لِّقَوْمٍ يَّسْمَعُوْنَ (23) وَمِنْ اٰيٰتِهٖ يُرِيْكُمُ الْبَرْقَ خَوْفًا وَّطَمَعًا وَّيُنَزِّلُ مِنَ السَّمَاۤءِ مَاۤءً فَيُحْيٖ بِهِ الْاَرْضَ بَعْدَ مَوْتِهَاۗ اِنَّ فِيْ ذٰلِكَ لَاٰيٰتٍ لِّقَوْمٍ يَّعْقِلُوْنَ (24) وَمِنْ اٰيٰتِهٖٓ اَنْ تَقُوْمَ السَّمَاۤءُ وَالْاَرْضُ بِاَمْرِهٖۗ ثُمَّ اِذَا دَعَاكُمْ دَعْوَةًۖ مِّنَ الْاَرْضِ اِذَآ اَنْتُمْ تَخْرُجُوْنَ (25) وَلَهٗ مَنْ فِى السَّمٰوٰتِ وَالْاَرْضِۗ كُلٌّ لَّهٗ قٰنِتُوْنَ (26) وَهُوَ الَّذِيْ يَبْدَؤُا الْخَلْقَ ثُمَّ يُعِيْدُهٗ وَهُوَ اَهْوَنُ عَلَيْهِۗ وَلَهُ الْمَثَلُ الْاَعْلٰى فِى السَّمٰوٰتِ وَالْاَرْضِۚ وَهُوَ الْعَزِيْزُ الْحَكِيْمُ (27) الروم : 20 - 27"],["p","Dan di antara tanda-tanda kekuasaan-Nya ialah Dia menciptakan kamu dari tanah, kemudian tiba-tiba kamu (menjadi) manusia yang berkembang biak. (20)"],["p","Dan di antara tanda-tanda kekuasaan-Nya ialah Dia menciptakan untukmu istri-istri dari jenismu sendiri, supaya kamu cenderung dan merasa tenteram kepadanya, dan dijadikan-Nya di antaramu rasa kasih dan sayang. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda bagi kaum yang berpikir. (21)"],["p","Dan di antara tanda-tanda kekuasaan-Nya ialah menciptakan langit dan bumi dan berlain-lainan bahasamu dan warna kulitmu. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda bagi orang-orang yang mengetahui. (22)"],["p","Dan di antara tanda-tanda kekuasaan-Nya ialah tidurmu di waktu malam dan siang hari dan usahamu mencari sebagian dari karunia-Nya. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda bagi kaum yang mendengarkan. (23)"],["p","Dan di antara tanda-tanda kekuasaan-Nya, Dia memperlihatkan kepadamu kilat untuk (menimbulkan) ketakutan dan harapan, dan Dia menurunkan air hujan dari langit, lalu menghidupkan bumi dengan air itu sesudah matinya. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda bagi kaum yang mempergunakan akalnya. (24)"],["p","Dan di antara tanda-tanda kekuasaan-Nya ialah berdirinya langit dan bumi dengan iradah-Nya. Kemudian apabila Dia memanggil kamu sekali panggil dari bumi, seketika itu (juga) kamu keluar (dari kubur). (25)"],["p","Dan kepunyaan-Nyalah siapa saja yang ada di langit dan di bumi. Semuanya hanya kepada-Nya tunduk. (26)"],["p","Dan Dialah yang menciptakan (manusia) dari permulaan, kemudian mengembalikan (menghidupkan) nya kembali, dan menghidupkan kembali itu adalah lebih mudah bagi-Nya. Dan bagi-Nya lah sifat yang Maha Tinggi di langit dan di bumi; dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.(27) [QS. Ar Ruum : 20 – 27]"],["a","يٰٓاَيُّهَا النَّاسُ اعْبُدُوْا رَبَّكُمُ الَّذِيْ خَلَقَكُمْ وَالَّذِيْنَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُوْنَۙ (21) الَّذِيْ جَعَلَ لَكُمُ الْاَرْضَ فِرَاشًا وَّالسَّمَاۤءَ بِنَاۤءً ۖ وَّاَنْزَلَ مِنَ السَّمَاۤءِ مَاۤءً فَاَخْرَجَ بِهٖ مِنَ الثَّمَرٰتِ رِزْقًا لَّكُمْ ۚ فَلَا تَجْعَلُوْا لِلّٰهِ اَنْدَادًا وَّاَنْتُمْ تَعْلَمُوْنَ (22) البقرة : 21-22"],["p","Hai manusia, sembahlah Tuhanmu Yang telah menciptakanmu dan orang-orang yang sebelummu, agar kamu bertakwa.(21)"],["p","Dialah Yang menjadikan bumi sebagai hamparan bagimu dan langit sebagai atap, dan Dia menurunkan air (hujan) dari langit, lalu Dia mengeluarkan dengan hujan itu segala buah-buahan sebagai rezeki untukmu; karena itu janganlah kamu mengadakan sekutu-sekutu bagi Allah, padahal kamu mengetahui. (22) [QS. Al Baqarah : 21-22]"],["p","Demikianlah semoga bermanfaat dan semoga Allah menjauhkan kita dari kerasnya hati."],["a","رَبَّنَا لَا تُزِغْ قُلُوْبَنَا بَعْدَ اِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَّدُنْكَ رَحْمَةً ۚ اِنَّكَ اَنْتَ الْوَهَّابُ (8) ال عمران : 8"],["p","\"Ya Tuhan kami, janganlah Engkau jadikan hati kami condong kepada kesesatan sesudah Engkau beri petunjuk kepada kami, dan karuniakanlah kepada kami rahmat dari sisi Engkau; karena sesungguhnya Engkau-lah Maha Pemberi (karunia).\" (8) [ QS. Ali ‘Imraan : 8]"],["p","--oo0oo--"]],"c20220227_1275":[["p","Ahad, 27 Februari 2022/26 Rajab 1443 Brosur No.: 2070/2110/IA"],["p","Menebarkan Kasih Sayang"],["p","Firman Allah SWT:"],["a","وَمَآ اَرْسَلْنٰكَ اِلَّا رَحْمَةً لِّلْعٰلَمِيْنَ (107) الانبياء : 107"],["p","Dan tiadalah Kami mengutus kamu, melainkan untuk (menjadi) rahmat bagi semesta alam. [QS. Al Anbiyaa’ : 107]"],["a","وَاِذَا جَاۤءَكَ الَّذِيْنَ يُؤْمِنُوْنَ بِاٰيٰتِنَا فَقُلْ سَلٰمٌ عَلَيْكُمْ كَتَبَ رَبُّكُمْ عَلٰى نَفْسِهِ الرَّحْمَةَۙ اَنَّهٗ مَنْ عَمِلَ مِنْكُمْ سُوْۤءًاۢ بِجَهَالَةٍ ثُمَّ تَابَ مِنْۢ بَعْدِهٖ وَاَصْلَحَ فَاَنَّهٗ غَفُوْرٌ رَّحِيْمٌ (54) الانعام : 54"],["p","Apabila orang-orang yang beriman kepada ayat-ayat Kami itu datang kepadamu, maka katakanlah: \"Salaamun ‘alaikum.” Tuhanmu telah menetapkan atas diri-Nya kasih sayang, (yaitu) bahwasanya barang siapa yang berbuat kejahatan di antara kamu lantaran kejahilan, kemudian ia bertaubat setelah mengerjakannya dan mengadakan perbaikan, maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang. [QS. Al An’aam : 54]"],["a","ذٰلِكَ الَّذِيْ يُبَشِّرُ اللّٰهُ عِبَادَهُ الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِۗ قُلْ لَّآ اَسْـَٔلُكُمْ عَلَيْهِ اَجْرًا اِلَّا الْمَوَدَّةَ فِى الْقُرْبٰىۗ وَمَنْ يَّقْتَرِفْ حَسَنَةً نَّزِدْ لَهٗ فِيْهَا حُسْنًا ۗ اِنَّ اللّٰهَ غَفُوْرٌ شَكُوْرٌ (23) الشورى : 23"],["p","Itulah (karunia) yang (dengan itu) Allah menggembirakan hamba-hamba-Nya yang beriman dan mengerjakan amal shaleh. Katakanlah: \"Aku tidak meminta kepadamu sesuatu upah pun atas seruanku kecuali kasih sayang dalam kekeluargaan\". Dan siapa yang mengerjakan kebaikan akan Kami tambahkan baginya kebaikan pada kebaikannya itu. Sesungguhnya Allah Maha Pengampun lagi Maha Mensyukuri. [QS. Asy Syuuraa : 23]"],["a","وَمِنْ اٰيٰتِهٖٓ اَنْ خَلَقَ لَكُمْ مِّنْ اَنْفُسِكُمْ اَزْوَاجًا لِّتَسْكُنُوْٓا اِلَيْهَا وَجَعَلَ بَيْنَكُمْ مَّوَدَّةً وَّرَحْمَةً ۗ اِنَّ فِيْ ذٰلِكَ لَاٰيٰتٍ لِّقَوْمٍ يَّتَفَكَّرُوْنَ (21) الروم : 21"],["p","Dan di antara tanda-tanda kekuasaan-Nya ialah Dia menciptakan untukmu istri-istri dari jenismu sendiri, supaya kamu cenderung dan merasa tenteram kepadanya, dan dijadikan-Nya di antaramu rasa kasih dan sayang. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda bagi kaum yang berfikir. [QS. Ar Ruum : 21]"],["a","اِنَّ الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ سَيَجْعَلُ لَهُمُ الرَّحْمٰنُ وُدًّا (96) مريم : 96"],["p","Sesungguhnya orang-orang yang beriman dan beramal shaleh, kelak Allah Yang Maha Pemurah akan menanamkan dalam (hati) mereka rasa kasih sayang. [QS. Maryam : 96]"],["a","قُلْ لِّمَنْ مَّا فِى السَّمٰوٰتِ وَالْاَرْضِۗ قُلْ لِّلّٰهِ ۗ كَتَبَ عَلٰى نَفْسِهِ الرَّحْمَةَ ۗ لَيَجْمَعَنَّكُمْ اِلٰى يَوْمِ الْقِيٰمَةِ لَا رَيْبَ فِيْهِۗ اَلَّذِيْنَ خَسِرُوْٓا اَنْفُسَهُمْ فَهُمْ لَا يُؤْمِنُوْنَ ( 12) الانعام : 12"],["p","Katakanlah: \"Kepunyaan siapakah apa yang ada di langit dan di bumi?\" Katakanlah: \"Kepunyaan Allah\". Dia telah menetapkan atas diri-Nya kasih sayang. Dia sungguh-sungguh akan menghimpun kamu pada hari kiamat yang tidak ada keraguan terhadapnya. Orang-orang yang merugikan dirinya, mereka itu tidak beriman. [QS. Al An’aam : 12]"],["a","وَاكْتُبْ لَنَا فِيْ هٰذِهِ الدُّنْيَا حَسَنَةً وَّفِى الْاٰخِرَةِ اِنَّا هُدْنَآ اِلَيْكَۗ قَالَ عَذَابِيْٓ اُصِيْبُ بِهٖ مَنْ اَشَاۤءُۚ وَرَحْمَتِيْ وَسِعَتْ كُلَّ شَيْءٍۗ فَسَاَكْتُبُهَا لِلَّذِيْنَ يَتَّقُوْنَ وَيُؤْتُوْنَ الزَّكٰوةَ وَالَّذِيْنَ هُمْ بِاٰيٰتِنَا يُؤْمِنُوْنَۚ (156 ) اَلَّذِيْنَ يَتَّبِعُوْنَ الرَّسُوْلَ النَّبِيَّ الْاُمِّيَّ الَّذِيْ يَجِدُوْنَهٗ مَكْتُوْبًا عِنْدَهُمْ فِى التَّوْرٰىةِ وَالْاِنْجِيْلِ يَأْمُرُهُمْ بِالْمَعْرُوْفِ وَيَنْهٰىهُمْ عَنِ الْمُنْكَرِ وَيُحِلُّ لَهُمُ الطَّيِّبٰتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبٰۤىِٕثَ وَيَضَعُ عَنْهُمْ اِصْرَهُمْ وَالْاَغْلٰلَ الَّتِيْ كَانَتْ عَلَيْهِمْۗ فَالَّذِيْنَ اٰمَنُوْا بِهٖ وَعَزَّرُوْهُ وَنَصَرُوْهُ وَاتَّبَعُوا النُّوْرَ الَّذِيْٓ اُنْزِلَ مَعَهٗٓ ۙ اُولٰۤىِٕكَ هُمُ الْمُفْلِحُوْنَ (157) الاعراف : 156 - 157"],["p","Dan tetapkanlah untuk kami kebajikan di dunia ini dan di akhirat; sesungguhnya kami kembali (bertaubat) kepada Engkau. Allah berfirman: \"Siksa Ku akan Kutimpakan kepada siapa yang Aku kehendaki dan rahmat-Ku meliputi segala sesuatu. Maka akan Aku tetapkan rahmat-Ku untuk orang-orang yang bertakwa, yang menunaikan zakat dan orang-orang yang beriman kepada ayat-ayat Kami\".(156)"],["p","(Yaitu) orang-orang yang mengikut Rasul, Nabi yang ummi yang (namanya) mereka dapati tertulis di dalam Taurat dan Injil yang ada di sisi mereka, yang menyuruh mereka mengerjakan yang ma’ruf dan melarang mereka dari mengerjakan yang mungkar dan menghalalkan bagi mereka segala yang baik dan mengharamkan bagi mereka segala yang buruk dan membuang dari mereka beban-beban dan belenggu-belenggu yang ada pada mereka. Maka orang-orang yang beriman kepadanya, memuliakannya, menolongnya dan mengikuti cahaya yang terang yang diturunkan kepadanya (Al Qur'an), mereka itulah orang-orang yang beruntung.(157) [QS. Al A’raaf : 156-157]"],["a","مُحَمَّدٌ رَّسُوْلُ اللّٰهِ ۗ وَالَّذِيْنَ مَعَهٗٓ اَشِدَّاۤءُ عَلَى الْكُفَّارِ رُحَمَاۤءُ بَيْنَهُمْ تَرٰىهُمْ رُكَّعًا سُجَّدًا يَّبْتَغُوْنَ فَضْلًا مِّنَ اللّٰهِ وَرِضْوَانًا ۖ سِيْمَاهُمْ فِيْ وُجُوْهِهِمْ مِّنْ اَثَرِ السُّجُوْدِ ۗ ذٰلِكَ مَثَلُهُمْ فِى التَّوْرٰىةِ ۖ وَمَثَلُهُمْ فِى الْاِنْجِيْلِۚ كَزَرْعٍ اَخْرَجَ شَطْـَٔهٗ فَاٰزَرَهٗ فَاسْتَغْلَظَ فَاسْتَوٰى عَلٰى سُوْقِهٖ يُعْجِبُ الزُّرَّاعَ لِيَغِيْظَ بِهِمُ الْكُفَّارَ ۗ وَعَدَ اللّٰهُ الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ مِنْهُمْ مَّغْفِرَةً وَّاَجْرًا عَظِيْمًا (29) الفتح : 29"],["p","Muhammad itu adalah utusan Allah dan orang-orang yang bersama dengan dia adalah keras terhadap orang-orang kafir, tetapi berkasih sayang sesama mereka, kamu lihat mereka ruku’ dan sujud mencari karunia Allah dan keridlaan-Nya, tanda-tanda mereka tampak pada muka mereka dari bekas sujud. Demikianlah sifat-sifat mereka dalam Taurat dan sifat-sifat mereka dalam Injil, yaitu seperti tanaman yang mengeluarkan tunasnya maka tunas itu menjadikan tanaman itu kuat lalu menjadi besarlah dia dan tegak lurus di atas pokoknya; tanaman itu menyenangkan hati penanam-penanamnya karena Allah hendak menjengkelkan hati orang-orang kafir (dengan kekuatan orang-orang mukmin). Allah menjanjikan kepada orang-orang yang beriman dan mengerjakan amal yang shaleh di antara mereka ampunan dan pahala yang besar.(29) [QS. Al Fath : 29]"],["a","لَقَدْ جَاۤءَكُمْ رَسُوْلٌ مِّنْ اَنْفُسِكُمْ عَزِيْزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيْصٌ عَلَيْكُمْ بِالْمُؤْمِنِيْنَ رَءُوْفٌ رَّحِيْمٌ (128) فَاِنْ تَوَلَّوْا فَقُلْ حَسْبِيَ اللّٰهُ لَآ اِلٰهَ اِلَّا هُوَ ۗ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ (129) التوبة : 128-129"],["p","Sesungguhnya telah datang kepadamu seorang rasul dari kaummu sendiri, berat terasa olehnya penderitaanmu, sangat menginginkan (keimanan dan keselamatan) bagimu, amat belas kasihan lagi penyayang terhadap orang-orang mukmin.(128)"],["p","Jika mereka berpaling (dari keimanan), maka katakanlah: \"Cukuplah Allah bagiku; tidak ada Tuhan selain Dia. Hanya kepada-Nya aku bertawakkal dan Dia adalah Tuhan yang memiliki ‘Arsy yang agung\"(129) [QS. At Taubah : 128-129]"],["p","Hadits Nabi SAW :"],["a","عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ ﷺ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: يَا عَائِشَةُ، اِنَّ اللهَ رَفِيْقٌ يُحِبُّ الرِّفْقَ، وَيُعْطِى عَلَى الرِّفْقِ مَا لَا يُعْطِى عَلَى الْعُنْفِ وَمَا لَا يُعْطِى عَلَى مَا سِوَاهُ. مسلم 4: 2003 رقم 77"],["p","Dari ‘Aisyah istri Nabi SAW, bahwasanya Rasulullah SAW bersabda, “Hai ‘Aisyah, sesungguhnya Allah itu Maha Kasih Sayang dan senang kepada kasih sayang, dan Dia memberi (kebaikan) pada kasih sayang itu apa-apa yang Dia tidak berikan kepada kekerasan, dan tidak pula Dia berikan kepada apapun selainnya”. [HR. Muslim juz 4, hal. 2003, no 77]"],["a","عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ ﷺ عَنِ النَّبِيِّ ﷺ قَالَ: اِنَّ الرِّفْقَ لَا يَكُوْنُ فِى شَيْءٍ اِلَّا زَانَهُ، وَلَا يُنْزَعُ مِنْ شَيْءٍ اِلَّا شَانَهُ. مسلم 4: 2004 رقم 78"],["p","Dari ‘Aisyah istri Nabi SAW, dari Nabi SAW, beliau bersabda, “Sesungguhnya kasih sayang itu tidaklah berada pada sesuatu kecuali ia pasti menghiasinya dan tidaklah dicabut dari sesuatu kecuali menjadikannya tercela”. [HR. Muslim juz 4, hal. 2004, no 78]"],["a","عَنْ اَبِي الدَّرْدَاءِ عَنِ النَّبِيِّ ﷺ قَالَ: مَنْ اُعْطِيَ حَظَّهُ مِنَ الرِّفْقِ فَقَدْ اُعْطِيَ حَظَّهُ مِنَ الْخَيْرِ. وَمَنْ حُرِمَ حَظَّهُ مِنَ الرِّفْقِ فَقَدْ حُرِمَ حَظَّهُ مِنَ الْخَيْرِ. الترمذى 3: 248، رقم: 2082 حديث حسن صحيح"],["p","Dari Abu Darda’, dari Nabi SAW, beliau bersabda, “Barangsiapa yang diberi bagiannya berupa kasih sayang, maka sungguh ia telah diberi bagiannya berupa kebaikan. Dan barangsiapa yang terhalang dari bagiannya berupa kasih sayang, maka sungguh ia terhalang dari bagiannya berupa kebaikan”. [HR. Tirmidzi juz 3, hal. 248, no. 2082, Hadits hasan shahih]"],["a","عَنْ جَرِيْرٍ عَنِ النَّبِيِّ ﷺ قَالَ: مَنْ يُحْرَمِ الرِّفْقَ يُحْرَمِ الْخَيْرَ. مسلم 4: 2003 رقم 74"],["p","Dari Jarir, dari Nabi SAW, beliau bersabda, “Barangsiapa yang terhalang dari sifat kasih sayang, berarti dia terhalang dari kebaikan”. [HR. Muslim juz 4, hal. 2003, no 74]"],["a","عَنْ جَرِيْرِ بْنِ عَبْدِ اللهِ اَنَّ النَّبِيَّ ﷺ قَالَ: اِنَّ اللهَ عَزَّ وَجَلَّ لَيُعْطِى عَلَى الرِّفْقِ مَا لَا يُعْطِى عَلَى الْخُرْقِ. وَاِذَا اَحَبَّ اللهُ عَبْدًا اَعْطَاهُ الرِّفْقَ. مَا مِنْ اَهْلِ بَيْتٍ يُحْرَمُوْنَ الرِّفْقَ اِلَّا قَدْ حُرِمُوْا. الطبرانى فى الكبير 2: 306، رقم: 2274"],["p","Dari Jarir bin ‘Abdullah, bahwasanya Nabi SAW bersabda, “Sesungguhnya Allah ‘Azza wa Jalla memberi kepada orang yang kasih sayang apa-apa yang tidak Dia berikan kepada orang yang pandir (bodoh). Dan apabila Allah mencintai kepada seorang hamba, Allah memberinya kasih sayang. Dan tidaklah suatu keluarga yang terhalang dari kasih sayang, melainkan sungguh mereka terhalang pula dari kebaikan”. [HR. Thabarani di dalam Al-Mu'jamul Kabiir juz 2, hal. 306, no. 2274]"],["a","عَنْ اَبِيْ مُوْسَى قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ اِذا بَعَثَ اَحَدًا مِنْ اَصْحَابِهِ فِيْ بَعْضِ اَمْرِهِ قَالَ: بَشِّرُوْا وَلَا تُنَفِّرُوْا وَيَسِّرُوْا وَلَا تُعَسِّرُوْا. مسلم 3: 1358 رقم 6"],["p","Dari Abu Musa, ia berkata : Dahulu Rasulullah SAW apabila mengutus seseorang diantara shahabatnya untuk sesuatu urusan, beliau bersabda, “Gembirakanlah, jangan kalian buat lari, dan mudahkanlah, jangan kalian persulit”. [HR. Muslim juz 3, hal. 1358, no 6]"],["a","عَنْ سَعِيْدِ بْنِ اَبِيْ بُرْدَةَ عَنْ اَبِيْهِ عَنْ جَدِّهِ اَنَّ النَّبِيَّ ﷺ بَعَثَهُ وَمُعَاذًا اِلىَ الْيَمَنِ، فَقَالَ: يَسِّرَا وَلَا تُعَسِّرَا وَبَشِّرَا وَلَا تُنَفِّرَا وَتَطَاوَعَا وَلَا تَخْتَلِفَا. مسلم 3: 1359 رقم 7"],["p","Dari Sa’id bin Abu Burdah, dari ayahnya, dari kakeknya, bahwasanya Nabi SAW pernah mengutusnya bersama Mu’adz ke Yaman, beliau berpesan, “Mudahkanlah, dan janganlah kalian berdua mempersulit, gembirakanlah dan janganlah kalian berdua membuat lari, rukunlah dan janganlah kalian berdua berselisih”. [HR. Muslim juz 3, hal. 1359, no 7]"],["a","عَنْ اَبِي التَّيَّاحِ قَالَ: سَمِعْتُ اَنَسَ بْنَ مَالِكٍ يَقُوْلُ: قَالَ رَسُوْلُ اللهِ ﷺ: يَسِّرُوْا وَلَا تُعَسِّرُوْا وَسَكِّنُوْا وَلَا تُنَفِّرُوْا.مسلم 3: 1359رقم 8"],["p","Dari Abu Tayyah, ia berkata : Aku mendengar Anas bin Maalik berkata : Rasulullah SAW bersabda, “Mudahkanlah, dan janganlah kalian mempersulit, dan tenangkanlah, janganlah kalian membuat lari”. [HR. Muslim juz 3, hal. 1359, no 8]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَامَ اَعْرَابِيٌّ فَبَالَ فِى الْمَسْجِدِ فَتَنَاوَلَهُ النَّاسُ، فَقَالَ لَـهُمُ النَّبِيُّ ﷺ :دَعُوْهُ وَهَرِيْقُوْا عَلَى بَوْلِهِ سَجْلًا مِنْ مَاءٍ اَوْ ذَنُوْبًا مِنْ مَاءٍ. فَاِنَّـمَا بُعِثْتُمْ مُيَسِّرِيْنَ وَلَـمْ تُبْعَثُوْا مُعَسِّرِيْنَ. البخارى 1: 61"],["p","Dari Abu Hurairah, ia berkata : Ada seorang ‘Arab gunung berdiri, lalu kencing di dalam masjid, maka orang-orang mencegahnya. Lalu Nabi SAW bersabda, “Biarkanlah ia, dan siramlah pada (bekas) kencingnya itu dengan seember air atau setimba air, karena sesungguhnya kamu sekalian diutus untuk memudahkan, bukan diutus untuk menyulitkan”. [HR. Bukhari juz 1, hal. 61]"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ قَالَ: كُنْتُ اَمْشِى مَعَ رَسُوْلِ اللهِ ﷺ وَعَلَيْهِ رِدَاءٌ نَجْرَانِيٌّ غَلِيْظُ الْحَاشِيَةِ. فَاَدْرَكَهُ اَعْرَابِيٌّ فَجَبَذَهُ بِرِدَائِهِ جَبْذَةً شَدِيْدَةً. نَظَرْتُ اِلَى صَفْحَةِ عُنُقِ رَسُوْلِ اللهِ ﷺ وَقَدْ اَثَّرَتْ بِـهَا حَاشِيَةُ الرِّدَاءِ مِنْ شِدَّةِ جَبْذَتِهِ، ثُـمَّ قَالَ: يَا مُحَمَّدُ، مُرْلِيْ مِنْ مَالِ اللهِ الَّذِيْ عِنْدَكَ. فَالْتَفَتَ اِلَيْهِ رَسُوْلُ اللهِ ﷺ فَضَحِكَ ثُـمَّ اَمَرَ لَهُ بِعَطَاءٍ. مسلم 2: 730 رقم 128"],["p","Dari Anas bin Maalik, ia berkata : Dahulu saya pernah berjalan-jalan bersama Rasulullah SAW, beliau memakai rida’ buatan Najran (Yaman) yang tebal bagian pinggirnya. Kemudian ada seorang ‘Arab gunung menemui beliau dan menarik rida’ beliau dengan tarikan yang sangat keras. Lalu saya melihat leher Rasulullah SAW bagian samping ada bekas pinggiran rida’ akibat kerasnya tarikan. Kemudian orang itu berkata, “Hai Muhammad, berikan kepadaku harta Allah yang ada padamu !”. Kemudian Rasulullah SAW menoleh kepadanya dan tersenyum, lalu beliau menyuruh memberikan suatu pemberian kepada orang itu. [HR. Muslim juz 2, hal. 730, no 128]"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ ﷺ قَالَتْ: دَخَلَ رَهْطٌ مِنَ الْيَهُوْدِ عَلَى رَسُوْلِ اللهِ ﷺ فَقَالُوْا: اَلسَّامُ عَلَيْكُمْ. قَالَتْ عَائِشَةُ: فَفَهِمْتُهَا فَقُلْتُ: وَعَلَيْكُمُ السَّامُ وَاللَّعْنَةُ. قَالَتْ، فَقَالَ رَسُوْلُ اللهِ ﷺ: مَهْلًا يَا عَائِشَةُ، اِنَّ اللهَ يُحِبُّ الرِّفْقَ فِى الْاَمْرِ كُلِّهِ. فَقُلْتُ: يَا رَسُوْلَ اللهِ، وَلَـمْ تَسْمَعْ مَا قَالُوْا؟ قَالَ رَسُوْلُ اللهِ ﷺ: قَدْ قُلْتُ وَعَلَيْكُمْ. البخارى 7: 80"],["p","Dari ‘Aisyah RA istri Nabi SAW, ia berkata : Sekelompok orang Yahudi datang kepada Rasulullah SAW, lalu mengucapkan, “Assaamu ‘alaikum” (Semoga kebinasaan atas kalian). ‘Aisyah berkata : Dan aku mengerti ucapan itu, dan aku menjawab, “Wa ‘alaikumus saamu walla’natu” (Dan semoga kebinasaan dan la’nat atas kalian). ‘Aisyah berkata : Maka Rasulullah SAW bersabda, “Pelan-pelan hai ‘Aisyah, sesungguhnya Allah menyukai kelembutan dan kasih sayang dalam segala urusan”. Lalu ‘Aisyah berkata, “Ya Rasulullah, apakah engkau tidak mendengar yang mereka ucapkan ?”. Beliau bersabda, “(Aku mendengar) dan aku sudah menjawab, “Wa ‘alaikum”. [HR. Bukhari juz 7, hal. 80]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَبَّلَ رَسُوْلُ اللهِ ﷺ الْحَسَنَ بْنَ عَلِيٍّ وَعِنْدَهُ الْاَقْرَعُ بْنُ حَابِسٍ التَّمِيْمِيُّ جَالِسًا، فَقَالَ الْاَقْرَعُ: اِنَّ لِيْ عَشْرَةً مِنَ الْوَلَدِ مَا قَبَّلْتُ مِنْهُمْ اَحَدًا. فَنَظَرَ اِلَيْهِ رَسُوْلُ اللهِ ﷺ ، ثُـمَّ قَالَ: مَنْ لَا يَرْحَمْ لَا يُرْحَمْ. البخارى 7: 75"],["p","Dari Abu Hurairah RA, ia berkata : Rasulullah SAW pernah mencium Al Hasan bin ‘Ali, sedang di situ ada Aqra’ bin Haabis At-Tamiimiy sedang duduk, lalu Aqra’ berkata, “Sesungguhnya aku mempunyai sepuluh orang anak, seorang pun saya tidak pernah menciumnya”. Maka Rasulullah SAW memandangnya, lalu bersabda, “Barangsiapa yang tidak menyayangi, maka ia tidak disayangi”. [HR. Bukhari juz 7 , hal. 75]."],["a","عَنْ عَائِشَةَ قَالَتْ: قَدِمَ نَاسٌ مِنَ الْاَعْرَابِ عَلَى رَسُوْلِ اللهِ ﷺ، فَقَالُوْا: اَتُقَبِّلُوْنَ صِبْيَانَكُمْ؟ فَقَالُوْا: نَعَمْ. فَقَالُوْا: لٰكِنَّا وَاللهِ، مَا نُقَبِّلُ. فَقَالَ رَسُوْلُ اللهِ ﷺ: وَاَمْلِكُ اِنْ كَانَ اللهُ نَزَعَ مِنْكُمُ الرَّحْمَةَ؟. مسلم 4: 1808 رقم 64"],["p","Dari ‘Aisyah, ia berkata : Orang-orang ‘Arab gunung datang kepada Rasulullah SAW, lalu mereka bertanya (kepada para shahabat), “Apakah kalian (biasa) mencium anak-anak kalian ?”. Para shahabat menjawab, “Ya”. Orang-orang tersebut berkata, “Demi Allah, sedangkan kami tidak pernah menciumnya”. Lalu Rasulullah SAW bersabda, “Apakah aku bisa menolong kalian jika Allah telah mencabut kasih sayang dari hati kalian ?”. [HR. Muslim juz 4, hal. 1808, no 64]"],["a","عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اَلرَّاحِمُوْنَ يَرْحَمُهُمُ الرَّحْمٰنُ، اِرْحَمُوْا مَنْ فِى الْاَرْضِ يَرْحَمْكُمْ مَنْ فِى السَّمَآءِ. الترمذى 3: 217، رقم: 1989، هذا حديث حسن صحيح"],["p","Dari ‘Abdullah bin ‘Amr, ia berkata : Rasulullah SAW bersabda, “Orang-orang yang penyayang itu dikasihi oleh Tuhan Yang Maha Penyayang. Maka sayangilah yang di bumi, pasti yang di langit akan menyayangi kalian. [HR. Tirmidzi juz 3, hal. 217, no. 1989, Ini hadits hasan shahih]"],["a","عَنْ زَرْبِيٍّ قَالَ: سَمِعْتُ اَنَسَ بْنَ مَالِكٍ يَقُوْلُ: جَاءَ شَيْخٌ يُرِيْدُ النَّبِيَّ ﷺ فَاَبْطَأَ الْقَوْمُ عَنْهُ اَنْ يُوَسِّعُوْا لَهُ، فَقَالَ النَّبِيُّ ﷺ: لَيْسَ مِنَّا مَنْ لَـمْ يَرْحَمْ صَغِيْرَنَا وَلَـمْ يُوَقِّرْ كَبِيْرَنَا. الترمذى 3: 215، رقم: 1984"],["p","Dari Zarbiy, ia berkata : Aku mendengar Anas bin Maalik berkata : Ada seorang tua yang datang ingin menemui Rasulullah SAW, lalu orang-orang tidak segera memberi jalan kepadanya, maka Nabi SAW bersabda, “Tidak termasuk golongan kami orang yang tidak kasih sayang kepada yang lebih muda, dan tidak menghormati kepada yang lebih tua”. [HR. Tirmidzi juz 3, hal. 215, no. 1984, dla'if karena dalam isnadnya ada perawi bernama Zarbiy, ia meriwayatkan hadits-hadits munkar]"],["a","عَنْ عَمْرِو بْنِ شُعَيْبٍ عَنْ اَبِيْهِ عَنْ جَدِّهِ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَيْسَ مِنَّا مَنْ لَـمْ يَرْحَمْ صَغِيْرَنَا وَلَـمْ يَعْرِفْ شَرَفَ كَبِيْرِنَا. الترمذى 3: 215، رقم 1985 حديث حسن صحيح"],["p","Dari 'Amr bin Syu'aib, dari ayahnya, dari kakeknya, ia berkata : Rasulullah SAW bersabda, \"Bukan dari golongan kami orang yang tidak kasih sayang kepada yang lebih muda, dan tidak mengerti kemuliaan yang lebih tua\". [HR. Tirmidzi juz 3, hal. 215, no. 1985, Hadits hasan shahih]"],["a","عَنْ جَرِيْرِ بْنِ عَبْدِ اللهِ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : مَنْ لَـمْ يَرْحَمِ النَّاسَ لَا يَرْحَمْهُ اللهُ. الترمذى 3: 216، رقم: 1987"],["p","Dari Jarir bin ‘Abdullah, ia berkata : Rasulullah SAW bersabda, “Barangsiapa yang tidak kasih sayang kepada manusia, Allah tidak akan kasih sayang kepadanya”. [HR. Tirmidzi juz 3, hal. 216, no. 1987]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: سَمِعْتُ اَبَا الْقَاسِمِ ﷺ يَقُوْلُ: لَا تُنْزَعُ الرَّحْمَةُ اِلَّا مِنْ شَقِيٍّ. الترمذى 3: 216، رقم: 1988 هذا حديث حسن"],["p","Dari Abu Hurairah, ia berkata : Aku mendengar Abul Qasim SAW bersabda, “Tidak dicabut kasih sayang itu kecuali dari orang yang celaka”. [HR. Tirmidzi juz 3, hal. 216, no. 1988, Ini hadits hasan]"],["a","عَنِ ابْنِ عَبَّاسٍ اَنَّ النَّبِيَّ ﷺ قَالَ لِاَشَجّ ِعَبْدِ الْقَيْسِ: اِنَّ فِيْكَ خَصْلَتَيْنِ يُحِبُّهُمَا اللهُ. اَلْحِلْمُ وَالْاَنَاةُ. الترمذى3: 247، رقم: 2080"],["p","Dari Ibnu ‘Abbas, bahwasanya Nabi SAW bersabda kepada Asyajji ‘Abdul Qais, “Sesungguhnya pada dirimu ada dua perangai yang dicintai oleh Allah, yaitu penyantun dan shabar”. [HR. Tirmidzi juz 3, hal. 247, no. 2080]"],["a","عَنْ عَبْدِ اللهِ بْنِ مَسْعُوْدٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اَلَا اُخْبِرُكُمْ بِمَنْ يَحْرُمُ عَلَى النَّارِ وَبِمَنْ تَحْرُمُ عَلَيْهِ النَّارُ؟ عَلَى كُلِّ قَرِيْبٍ هَيِّنٍ سَهْلٍ. الترمذى 4: 66 رقم 2606"],["p","Dari ‘Abdullah bin Mas’ud, ia berkata : Rasulullah SAW bersabda, “Maukah aku khabarkan kepada kalian orang yang haram masuk neraka atau orang yang neraka itu haram baginya ?. (Neraka itu diharamkan atas) setiap orang yang dekat (kepada Allah), lembut dan mudah”. [HR. Tirmidzi juz 4, hal. 66, no. 2606]"],["a","عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ: لَقِيْتُ رَسُوْلَ اللهِ ﷺ فَقَالَ لِيْ: يَا عُقْبَةُ بْنَ عَامِرٍ، صِلْ مَنْ قَطَعَكَ وَاَعْطِ مَنْ حَرَمَكَ وَاعْفُ عَمَّنْ ظَلَمَكَ. احمد 6: 148، رقم: 17457"],["p","Dari ‘Uqbah bin ‘Aamir, ia berkata : Aku bertemu Rasulullah SAW, lalu beliau berpesan kepadaku, “Hai ‘Uqbah bin ‘Aamir, sambunglah orang yang memutuskan hubungan denganmu, berilah orang yang tidak mau memberi kepadamu, dan maafkanlah orang yang berbuat dhalim kepadamu”. [HR. Ahmad juz 6, hal. 148, no. 17457]"],["p","--oo0oo--"]],"c20220306_1276":[["p","Ahad, 6 Maret 2022/3 Sya’baan 1443 Brosur No.: 2071/2111/IA"],["h","AL WA’DU WAL WA’IID (JANJI DAN ANCAMAN ) (1)"],["p","A. Al Wa’du wal Wa’iid (Janji dan Ancaman)."],["p","Al wa’du adalah mashdar dari :"],["a","وَعَدَ – يَعِدُ - وَعْدًا"],["p","Artinya : Janji"],["p","Al wa’du yang disebutkan di dalam Al Qur’an kebanyakan berma’na janji berupa kebaikan."],["p","Contoh Al Wa’du berupa janji kebaikan, firman Allah SWT:"],["a","اِنَّ اللّٰهَ اشْتَرٰى مِنَ الْمُؤْمِنِيْنَ اَنْفُسَهُمْ وَاَمْوَالَهُمْ بِاَنَّ لَهُمُ الْجَنَّةَۗ يُقَاتِلُوْنَ فِيْ سَبِيْلِ اللّٰهِ فَيَقْتُلُوْنَ وَيُقْتَلُوْنَ وَعْدًا عَلَيْهِ حَقًّا فِى التَّوْرٰىةِ وَالْاِنْجِيْلِ وَالْقُرْاٰنِۗ وَمَنْ اَوْفٰى بِعَهْدِهٖ مِنَ اللّٰهِ فَاسْتَبْشِرُوْا بِبَيْعِكُمُ الَّذِيْ بَايَعْتُمْ بِهٖۗ وَذٰلِكَ هُوَ الْفَوْزُ الْعَظِيْمُ (111) التوبة : 111"],["p","Sesungguhnya Allah telah membeli dari orang-orang mukmin, diri dan harta mereka dengan memberikan surga untuk mereka. Mereka berperang pada jalan Allah; lalu mereka membunuh atau terbunuh. (Itu telah menjadi) janji yang benar dari Allah di dalam Taurat, Injil dan Al Qur'an. Dan siapakah yang lebih menepati janjinya (selain) daripada Allah? Maka bergembiralah dengan jual beli yang telah kamu lakukan itu, dan itulah kemenangan yang besar. (111) [QS. At Taubah : 111]"],["a","اَفَمَنْ وَّعَدْنٰهُ وَعْدًا حَسَنًا فَهُوَ لَاقِيْهِ كَمَنْ مَّتَّعْنٰهُ مَتَاعَ الْحَيٰوةِ الدُّنْيَا ثُمَّ هُوَ يَوْمَ الْقِيٰمَةِ مِنَ الْمُحْضَرِيْنَ (61) القصص : 61"],["p","Maka apakah orang yang Kami janjikan kepadanya suatu janji yang baik (surga) lalu ia memperolehnya, sama dengan orang yang Kami berikan kepadanya keni’matan hidup duniawi; kemudian dia pada hari kiamat termasuk orang-orang yang diseret (ke dalam neraka)?(61) [QS. Al Qashash : 61]"],["a","قُلْ اَذٰلِكَ خَيْرٌ اَمْ جَنَّةُ الْخُلْدِ الَّتِيْ وُعِدَ الْمُتَّقُوْنَۗ كَانَتْ لَهُمْ جَزَاۤءً وَّمَصِيْرًا (15) لَهُمْ فِيْهَا مَا يَشَاۤءُوْنَ خٰلِدِيْنَۗ كَانَ عَلٰى رَبِّكَ وَعْدًا مَّسْـُٔوْلًا (16) الفرقان : 15-16"],["p","Katakanlah: \"Apa (adzab) yang demikian itukah yang baik, atau surga yang kekal yang telah dijanjikan kepada orang-orang yang bertaqwa?\" Dia menjadi balasan dan tempat kembali bagi mereka?\" (15)"],["p","Bagi mereka di dalam surga itu apa yang mereka kehendaki, sedang mereka kekal (di dalamnya). (Hal itu) adalah janji dari Tuhanmu yang patut dimohonkan (kepada-Nya). (16) [QS. Al Furqaan : 15-16]"],["p","Adapun al wa’iid juga mashdar dari wa’ada – ya’idu , tetapi ma’nanya adalah janji berupa keburukan atau ancaman."],["p","Contoh al wa’iid berupa janji keburukan atau ancaman, firman Allah SWT:"],["a","وَكَذٰلِكَ اَنْزَلْنٰهُ قُرْاٰنًا عَرَبِيًّا وَّصَرَّفْنَا فِيْهِ مِنَ الْوَعِيْدِ لَعَلَّهُمْ يَتَّقُوْنَ اَوْ يُحْدِثُ لَهُمْ ذِكْرًا (113) طه : 113"],["p","Dan demikianlah Kami menurunkan Al Qur'an dalam bahasa Arab, dan Kami telah menerangkan dengan berulang kali di dalamnya sebahagian dari ancaman, agar mereka bertakwa atau (agar) Al Qur'an itu menimbulkan pengajaran bagi mereka. (113) [QS. Thaahaa: 113]"],["a","كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوْحٍ وَّاَصْحٰبُ الرَّسِّ وَثَمُوْدُ (12) وَعَادٌ وَّفِرْعَوْنُ وَاِخْوَانُ لُوْطٍۙ (13) وَّاَصْحٰبُ الْاَيْكَةِ وَقَوْمُ تُبَّعٍۗ كُلٌّ كَذَّبَ الرُّسُلَ فَحَقَّ وَعِيْدِ (14) ق : 12-14"],["p","Sebelum mereka telah mendustakan (pula) kaum Nuh dan penduduk Rass dan Tsamud, (12)"],["p","dan kaum ‘Aad, kaum Fir’aun dan kaum Luth, (13)"],["p","dan penduduk Aikah serta kaum Tubba’, semuanya telah mendustakan rasul-rasul, maka sudah semestinyalah ancaman-Ku menimpa mereka. (14) [QS. Qaaf : 12-14]"],["a","نَحْنُ اَعْلَمُ بِمَا يَقُوْلُوْنَ وَمَآ اَنْتَ عَلَيْهِمْ بِجَبَّارٍۗ فَذَكِّرْ بِالْقُرْاٰنِ مَنْ يَّخَافُ وَعِيْدِ (45) ق : 45"],["p","Kami lebih mengetahui tentang apa yang mereka katakan, dan kamu sekali-kali bukanlah seorang pemaksa terhadap mereka. Maka beri peringatanlah dengan Al Qur'an orang yang takut kepada ancaman-Ku. (45) [QS. Qaaf : 45]"],["p","B. Di dalam Al Qur’an banyak ayat yang berisi janji kebaikan maupun ayat yang berisi ancaman."],["p","1. Ayat-ayat yang berisi janji kebaikan, diantaranya:"],["a","وَبَشِّرِ الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ اَنَّ لَهُمْ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ ۗ كُلَّمَا رُزِقُوْا مِنْهَا مِنْ ثَمَرَةٍ رِّزْقًا ۙ قَالُوْا هٰذَا الَّذِيْ رُزِقْنَا مِنْ قَبْلُ وَاُتُوْا بِهٖ مُتَشَابِهًا ۗ وَلَهُمْ فِيْهَآ اَزْوَاجٌ مُّطَهَّرَةٌ وَّهُمْ فِيْهَا خٰلِدُوْنَ (25) البقرة : 25"],["p","Dan sampaikanlah berita gembira kepada mereka yang beriman dan berbuat baik, bahwa bagi mereka disediakan surga-surga yang mengalir sungai-sungai di dalamnya. Setiap mereka diberi rezeki buah-buahan dalam surga-surga itu, mereka mengatakan: \"Inilah yang pernah diberikan kepada kami dahulu.\" Mereka diberi buah-buahan yang serupa dan untuk mereka di dalamnya ada istri-istri yang suci dan mereka kekal di dalamnya. (25) [QS. Al Baqarah : 25]"],["a","مَنْ عَمِلَ صَالِحًا مِّنْ ذَكَرٍ اَوْ اُنْثٰى وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهٗ حَيٰوةً طَيِّبَةًۚ وَلَنَجْزِيَنَّهُمْ اَجْرَهُمْ بِاَحْسَنِ مَا كَانُوْا يَعْمَلُوْنَ (97) النحل : 97"],["p","Barangsiapa yang mengerjakan amal shaleh, baik laki-laki maupun perempuan dalam keadaan beriman, maka sesungguhnya akan Kami berikan kepadanya kehidupan yang baik dan sesungguhnya akan Kami beri balasan kepada mereka dengan pahala yang lebih baik dari apa yang telah mereka kerjakan. (97) [QS. An Nahl : 97]"],["a","مَنْ عَمِلَ سَيِّئَةً فَلَا يُجْزٰىٓ اِلَّا مِثْلَهَاۚ وَمَنْ عَمِلَ صَالِحًا مِّنْ ذَكَرٍ اَوْ اُنْثٰى وَهُوَ مُؤْمِنٌ فَاُولٰۤىِٕكَ يَدْخُلُوْنَ الْجَنَّةَ يُرْزَقُوْنَ فِيْهَا بِغَيْرِ حِسَابٍ (40) غافر : 40"],["p","Barangsiapa mengerjakan perbuatan jahat, maka dia tidak akan dibalas melainkan sebanding dengan kejahatan itu. Dan barang siapa mengerjakan amal yang shaleh baik laki-laki maupun perempuan sedang ia dalam keadaan beriman, maka mereka akan masuk surga, mereka diberi rezeki di dalamnya tanpa hisab. (40) [QS. Ghaafir : 40]"],["a","وَالْمُؤْمِنُوْنَ وَالْمُؤْمِنٰتُ بَعْضُهُمْ اَوْلِيَاۤءُ بَعْضٍۘ يَأْمُرُوْنَ بِالْمَعْرُوْفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُقِيْمُوْنَ الصَّلٰوةَ وَيُؤْتُوْنَ الزَّكٰوةَ وَيُطِيْعُوْنَ اللّٰهَ وَرَسُوْلَهٗ ۗ اُولٰۤىِٕكَ سَيَرْحَمُهُمُ اللّٰهُ ۗ اِنَّ اللّٰهَ عَزِيْزٌ حَكِيْمٌ (71) وَعَدَ اللّٰهُ الْمُؤْمِنِيْنَ وَالْمُؤْمِنٰتِ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَا وَمَسٰكِنَ طَيِّبَةً فِيْ جَنّٰتِ عَدْنٍ ۗ وَرِضْوَانٌ مِّنَ اللّٰهِ اَكْبَرُ ۗ ذٰلِكَ هُوَ الْفَوْزُ الْعَظِيْمُ (72) التوبة : 71-72"],["p","Dan orang-orang yang beriman, lelaki dan perempuan, sebahagian mereka (adalah) menjadi penolong bagi sebahagian yang lain. Mereka menyuruh (mengerjakan) yang ma’ruf, mencegah dari yang mungkar, mendirikan shalat, menunaikan zakat, dan mereka thaat kepada Allah dan Rasul-Nya. Mereka itu akan diberi rahmat oleh Allah; sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana. (71)"],["p","Allah menjanjikan kepada orang-orang yang mukmin lelaki dan perempuan, (akan mendapat) surga yang di bawahnya mengalir sungai-sungai, kekal mereka di dalamnya, dan (mendapat) tempat-tempat yang bagus di surga ‘Adn. Dan keridlaan Allah adalah lebih besar; itu adalah keberuntungan yang besar. (72) [QS. At Taubah : 71-72]"],["a","وَالَّذِيْنَ صَبَرُوا ابْتِغَاۤءَ وَجْهِ رَبِّهِمْ وَاَقَامُوا الصَّلٰوةَ وَاَنْفَقُوْا مِمَّا رَزَقْنٰهُمْ سِرًّا وَّعَلَانِيَةً وَّيَدْرَءُوْنَ بِالْحَسَنَةِ السَّيِّئَةَ اُولٰۤىِٕكَ لَهُمْ عُقْبَى الدَّارِۙ (22) جَنّٰتُ عَدْنٍ يَّدْخُلُوْنَهَا وَمَنْ صَلَحَ مِنْ اٰبَاۤىِٕهِمْ وَاَزْوَاجِهِمْ وَذُرِّيّٰتِهِمْ وَالْمَلٰۤىِٕكَةُ يَدْخُلُوْنَ عَلَيْهِمْ مِّنْ كُلِّ بَابٍۚ (23) سَلٰمٌ عَلَيْكُمْ بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى الدَّارِ (24) الرعد : 22-24"],["p","Dan orang-orang yang shabar karena mencari keridlaan Tuhannya, mendirikan shalat, dan menafkahkan sebagian rezeki yang Kami berikan kepada mereka, secara sembunyi atau terang-terangan serta menolak kejahatan dengan kebaikan; orang-orang itulah yang mendapat tempat kesudahan (yang baik),(22)"],["p","(yaitu) surga ‘Adn yang mereka masuk ke dalamnya bersama-sama dengan orang-orang yang shaleh dari bapak-bapaknya, istri-istrinya dan anak cucunya, sedang malaikat-malaikat masuk ke tempat-tempat mereka dari semua pintu; (23)"],["p","(sambil mengucapkan): \"Salaamun 'alaikum bimaa shabartum\". Maka alangkah baiknya tempat kesudahan itu. (24) [QS. Ar Ra’d : 22-24]"],["a","وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِّنَ الْخَوْفِ وَالْجُوْعِ وَنَقْصٍ مِّنَ الْاَمْوَالِ وَالْاَنْفُسِ وَالثَّمَرٰتِۗ وَبَشِّرِ الصّٰبِرِيْنَ(155) اَلَّذِيْنَ اِذَآ اَصَابَتْهُمْ مُّصِيْبَةٌ ۗ قَالُوْٓا اِنَّا لِلّٰهِ وَاِنَّآ اِلَيْهِ رٰجِعُوْنَۗ (156) اُولٰۤىِٕكَ عَلَيْهِمْ صَلَوٰتٌ مِّنْ رَّبِّهِمْ وَرَحْمَةٌ ۗ وَاُولٰۤىِٕكَ هُمُ الْمُهْتَدُوْنَ (157) البقرة : 155-157"],["p","Dan sungguh akan Kami berikan cobaan kepadamu, dengan sedikit ketakutan, kelaparan, kekurangan harta, jiwa dan buah-buahan. Dan berikanlah berita gembira kepada orang-orang yang shabar, (155)"],["p","(yaitu) orang-orang yang apabila ditimpa mushibah, mereka mengucapkan, \"Innaa lillaahi wa innaa ilaihi raaji`uun\" (156)"],["p","Mereka itulah yang mendapat keberkatan yang sempurna dan rahmat dari Tuhan mereka, dan mereka itulah orang-orang yang mendapat petunjuk. (157) [QS. Al Baqarah : 155-157]"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا هَلْ اَدُلُّكُمْ عَلٰى تِجَارَةٍ تُنْجِيْكُمْ مِّنْ عَذَابٍ اَلِيْمٍ (10) تُؤْمِنُوْنَ بِاللّٰهِ وَرَسُوْلِهٖ وَتُجَاهِدُوْنَ فِيْ سَبِيْلِ اللّٰهِ بِاَمْوَالِكُمْ وَاَنْفُسِكُمْۗ ذٰلِكُمْ خَيْرٌ لَّكُمْ اِنْ كُنْتُمْ تَعْلَمُوْنَۙ (11) يَغْفِرْ لَكُمْ ذُنُوْبَكُمْ وَيُدْخِلْكُمْ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ وَمَسٰكِنَ طَيِّبَةً فِيْ جَنّٰتِ عَدْنٍۗ ذٰلِكَ الْفَوْزُ الْعَظِيْمُ (12) الصف : 10-12"],["p","Hai orang-orang yang beriman, sukakah kamu Aku tunjukkan suatu perniagaan yang dapat menyelamatkan kamu dari adzab yang pedih?(10)"],["p","(yaitu) kamu beriman kepada Allah dan Rasul-Nya dan berjihad di jalan Allah dengan harta dan jiwamu. Itulah yang lebih baik bagi kamu jika kamu mengetahuinya,(11)"],["p","niscaya Allah akan mengampuni dosa-dosamu dan memasukkan kamu ke dalam surga yang mengalir di bawahnya sungai-sungai, dan (memasukkan kamu) ke tempat tinggal yang baik di dalam surga ‘Adn. Itulah keberuntungan yang besar.(12) [QS. Ash Shaff : 10-12]"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اِنْ تَنْصُرُوا اللّٰهَ يَنْصُرْكُمْ وَيُثَبِّتْ اَقْدَامَكُمْ (7) محمد : 7"],["p","Hai orang-orang yang beriman, jika kamu menolong (agama) Allah, niscaya Dia akan menolongmu dan meneguhkan kedudukanmu.(7) [QS. Muhammad : 7]"],["a","اِنَّا لَنَنْصُرُ رُسُلَنَا وَالَّذِيْنَ اٰمَنُوْا فِى الْحَيٰوةِ الدُّنْيَا وَيَوْمَ يَقُوْمُ الْاَشْهَادُۙ (51) غافر : 51"],["p","Sesungguhnya Kami menolong rasul-rasul Kami dan orang-orang yang beriman dalam kehidupan dunia dan pada hari berdirinya saksi-saksi (hari kiamat), (51) [QS. Ghaafir : 51]"],["a","وَلَقَدْ اَرْسَلْنَا مِنْ قَبْلِكَ رُسُلًا اِلٰى قَوْمِهِمْ فَجَاۤءُوْهُمْ بِالْبَيِّنٰتِ فَانْتَقَمْنَا مِنَ الَّذِيْنَ اَجْرَمُوْاۗ وَكَانَ حَقًّاۖ عَلَيْنَا نَصْرُ الْمُؤْمِنِيْنَ (47) الروم : 47"],["p","Dan sesungguhnya Kami telah mengutus sebelum kamu beberapa orang rasul kepada kaumnya, mereka datang kepadanya dengan membawa keterangan-keterangan (yang cukup), lalu Kami melakukan pembalasan terhadap orang-orang yang berdosa. Dan Kami selalu berkewajiban menolong orang-orang yang beriman. (47) [QS. Ar Ruum : 47]"],["a","اِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِيْنًاۙ (1) لِّيَغْفِرَ لَكَ اللّٰهُ مَا تَقَدَّمَ مِنْ ذَنْۢبِكَ وَمَا تَاَخَّرَ وَيُتِمَّ نِعْمَتَهٗ عَلَيْكَ وَيَهْدِيَكَ صِرَاطًا مُّسْتَقِيْمًاۙ (2) وَّيَنْصُرَكَ اللّٰهُ نَصْرًا عَزِيْزًا (3) هُوَ الَّذِيْٓ اَنْزَلَ السَّكِيْنَةَ فِيْ قُلُوْبِ الْمُؤْمِنِيْنَ لِيَزْدَادُوْٓا اِيْمَانًا مَّعَ اِيْمَانِهِمْ ۗ وَلِلّٰهِ جُنُوْدُ السَّمٰوٰتِ وَالْاَرْضِۗ وَكَانَ اللّٰهُ عَلِيْمًا حَكِيْمًاۙ (4) لِّيُدْخِلَ الْمُؤْمِنِيْنَ وَالْمُؤْمِنٰتِ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَا وَيُكَفِّرَ عَنْهُمْ سَيِّاٰتِهِمْۗ وَكَانَ ذٰلِكَ عِنْدَ اللّٰهِ فَوْزًا عَظِيْمًا (5) الفتح : 1-5"],["p","Sesungguhnya Kami telah memberikan kepadamu kemenangan yang nyata, (1)"],["p","supaya Allah memberi ampunan kepadamu terhadap dosamu yang telah lalu dan yang akan datang serta menyempurnakan ni’mat-Nya atasmu dan memimpin kamu kepada jalan yang lurus, (2)"],["p","dan supaya Allah menolongmu dengan pertolongan yang kuat (banyak). (3)"],["p","Dia-lah yang telah menurunkan ketenangan ke dalam hati orang-orang mukmin supaya keimanan mereka bertambah di samping keimanan mereka (yang telah ada). Dan kepunyaan Allah-lah tentara langit dan bumi dan adalah Allah Maha Mengetahui lagi Maha Bijaksana, (4)"],["p","supaya Dia memasukkan orang-orang mukmin laki-laki dan perempuan ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya dan supaya Dia menutupi kesalahan-kesalahan mereka. Dan yang demikian itu adalah keberuntungan yang besar di sisi Allah, (5) [QS. Al Fath : 1-5]"],["a","وَلَوْ اَنَّ اَهْلَ الْقُرٰٓى اٰمَنُوْا وَاتَّقَوْا لَفَتَحْنَا عَلَيْهِمْ بَرَكٰتٍ مِّنَ السَّمَاۤءِ وَالْاَرْضِ وَلٰكِنْ كَذَّبُوْا فَاَخَذْنٰهُمْ بِمَا كَانُوْا يَكْسِبُوْنَ (96) الاعراف : 96"],["p","Jika sekiranya penduduk negeri-negeri beriman dan bertaqwa, pastilah Kami akan melimpahkan kepada mereka berkah dari langit dan bumi, tetapi mereka mendustakan (ayat-ayat Kami), maka Kami siksa mereka disebabkan perbuatannya.(96) [QS. Al A’raaf : 96]"],["a","اِنَّ اللّٰهَ يُدْخِلُ الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ يُحَلَّوْنَ فِيْهَا مِنْ اَسَاوِرَ مِنْ ذَهَبٍ وَّلُؤْلُؤًاۗ وَلِبَاسُهُمْ فِيْهَا حَرِيْرٌ (23) وَهُدُوْٓا اِلَى الطَّيِّبِ مِنَ الْقَوْلِۚ وَهُدُوْٓا اِلٰى صِرَاطِ الْحَمِيْدِ (24) الحخ : 23-24"],["p","Sesungguhnya Allah memasukkan orang-orang yang beriman dan mengerjakan amal shaleh ke dalam surga-surga yang dibawahnya mengalir sungai-sungai. Di surga itu mereka diberi perhiasan dengan gelang-gelang dari emas dan mutiara, dan pakaian mereka adalah sutera. (23)"],["p","Dan mereka diberi petunjuk kepada ucapan-ucapan yang baik, dan ditunjuki (pula) kepada jalan (Allah) yang terpuji. (24) [QS. Al Hajj : 23-24]"],["a","وَقُلِ الْحَقُّ مِنْ رَّبِّكُمْۗ فَمَنْ شَاۤءَ فَلْيُؤْمِنْ وَّمَنْ شَاۤءَ فَلْيَكْفُرْۚ اِنَّآ اَعْتَدْنَا لِلظّٰلِمِيْنَ نَارًاۙ اَحَاطَ بِهِمْ سُرَادِقُهَاۗ وَاِنْ يَّسْتَغِيْثُوْا يُغَاثُوْا بِمَاۤءٍ كَالْمُهْلِ يَشْوِى الْوُجُوْهَۗ بِئْسَ الشَّرَابُۗ وَسَاۤءَتْ مُرْتَفَقًا (29) اِنَّ الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ اِنَّا لَا نُضِيْعُ اَجْرَ مَنْ اَحْسَنَ عَمَلًاۚ (30) اُولٰۤىِٕكَ لَهُمْ جَنّٰتُ عَدْنٍ تَجْرِيْ مِنْ تَحْتِهِمُ الْاَنْهٰرُ يُحَلَّوْنَ فِيْهَا مِنْ اَسَاوِرَ مِنْ ذَهَبٍ وَّيَلْبَسُوْنَ ثِيَابًا خُضْرًا مِّنْ سُنْدُسٍ وَّاِسْتَبْرَقٍ مُّتَّكِـِٕيْنَ فِيْهَا عَلَى الْاَرَاۤىِٕكِۗ نِعْمَ الثَّوَابُۗ وَحَسُنَتْ مُرْتَفَقًا (31) الكهف: 29-31"],["p","Dan katakanlah: \"Kebenaran itu datangnya dari Tuhanmu; maka barangsiapa yang ingin (beriman) hendaklah ia beriman, dan barang siapa yang ingin (kafir) biarlah ia kafir\". Sesungguhnya Kami telah sediakan bagi orang-orang dhalim itu neraka, yang gejolaknya mengepung mereka. Dan jika mereka meminta minum, mereka akan diberi minum dengan air seperti besi yang mendidih yang menghanguskan muka. Itulah minuman yang paling buruk, dan tempat istirahat yang paling jelek.(29)"],["p","Sesungguhnya mereka yang beriman dan beramal shaleh, tentulah Kami tidak akan menyia-nyiakan pahala orang-orang yang mengerjakan amalan (nya) dengan baik.(30)"],["p","Mereka itulah (orang-orang yang) bagi mereka surga ‘Adn, mengalir sungai-sungai di bawahnya; dalam surga itu mereka diberi perhiasan dengan gelang-gelang emas dan mereka memakai pakaian hijau dari sutera halus dan sutera tebal, sedang mereka duduk sambil bersandar di atas dipan-dipan yang indah. Itulah pahala yang sebaik-baiknya, dan tempat-istirahat yang indah; (31) [QS. Al Kahfi : 29-31]"],["a","وَسِيْقَ الَّذِيْنَ اتَّقَوْا رَبَّهُمْ اِلَى الْجَنَّةِ زُمَرًا ۗ حَتّٰىٓ اِذَا جَاۤءُوْهَا وَفُتِحَتْ اَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلٰمٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوْهَا خٰلِدِيْنَ (73) وَقَالُوا الْحَمْدُ لِلّٰهِ الَّذِيْ صَدَقَنَا وَعْدَهٗ وَاَوْرَثَنَا الْاَرْضَ نَتَبَوَّاُ مِنَ الْجَنَّةِ حَيْثُ نَشَاۤءُ ۚ فَنِعْمَ اَجْرُ الْعٰمِلِيْنَ (74) الزمر : 73-74"],["p","Dan orang-orang yang bertakwa kepada Tuhannya dibawa ke dalam surga berombong-rombongan. Sehingga apabila mereka sampai ke surga itu sedang pintu-pintunya telah terbuka dan berkatalah kepada mereka penjaga-penjaganya: \"Kesejahteraan (dilimpahkan) atasmu, berbahagialah kamu! maka masukilah surga ini, sedang kamu kekal di dalamnya\". (73)"],["p","Dan mereka mengucapkan: \"Segala puji bagi Allah yang telah memenuhi janji-Nya kepada kami dan telah (memberi) kepada kami tempat ini sedang kami (diperkenankan) menempati tempat dalam surga di mana saja yang kami kehendaki.\" Maka surga itulah sebaik-baik balasan bagi orang-orang yang beramal.(74) [QS. Az Zumar : 73-74]"],["a","اِنَّ الْمُتَّقِيْنَ فِيْ جَنّٰتٍ وَّنَعِيْمٍۙ (17) فٰكِهِيْنَ بِمَآ اٰتٰىهُمْ رَبُّهُمْۚ وَوَقٰىهُمْ رَبُّهُمْ عَذَابَ الْجَحِيْمِ (18) كُلُوْا وَاشْرَبُوْا هَنِيْۤـًٔا ۢ بِمَا كُنْتُمْ تَعْمَلُوْنَۙ (19) مُتَّكِـِٕيْنَ عَلٰى سُرُرٍ مَّصْفُوْفَةٍۚ وَزَوَّجْنٰهُمْ بِحُوْرٍ عِيْنٍ (20) وَالَّذِيْنَ اٰمَنُوْا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُمْ بِاِيْمَانٍ اَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَآ اَلَتْنٰهُمْ مِّنْ عَمَلِهِمْ مِّنْ شَيْءٍۗ كُلُّ امْرِئٍ ۢ بِمَا كَسَبَ رَهِيْنٌ (21) وَاَمْدَدْنٰهُمْ بِفَاكِهَةٍ وَّلَحْمٍ مِّمَّا يَشْتَهُوْنَ (22) يَتَنَازَعُوْنَ فِيْهَا كَأْسًا لَّا لَغْوٌ فِيْهَا وَلَا تَأْثِيْمٌ(23) وَيَطُوْفُ عَلَيْهِمْ غِلْمَانٌ لَّهُمْ كَاَنَّهُمْ لُؤْلُؤٌ مَّكْنُوْنٌ (24) الطور : 17-24"],["p","Sesungguhnya orang-orang yang bertakwa berada dalam surga dan kenii’matan, (17)"],["p","mereka bersuka ria dengan apa yang diberikan kepada mereka oleh Tuhan mereka; dan Tuhan mereka memelihara mereka dari adzab neraka. (18)"],["p","(Dikatakan kepada mereka): \"Makan dan minumlah dengan enak sebagai balasan dari apa yang telah kamu kerjakan\", (19)"],["p","mereka bersandar di atas dipan-dipan berderetan dan Kami kawinkan mereka dengan bidadari-bidadari yang cantik bermata jeli. (20)"],["p","Dan orang-orang yang beriman, dan yang anak cucu mereka mengikuti mereka dalam keimanan, Kami hubungkan anak cucu mereka dengan mereka, dan Kami tiada mengurangi sedikit pun dari pahala amal mereka. Tiap-tiap manusia terikat dengan apa yang dikerjakannya. (21)"],["p","Dan Kami beri mereka tambahan dengan buah-buahan dan daging dari segala jenis yang mereka ingini. (22)"],["p","Di dalam surga mereka saling memperebutkan piala (gelas) yang isinya tidak (menimbulkan) kata-kata yang tidak berfaedah dan tiada pula perbuatan dosa. (23)"],["p","Dan berkeliling di sekitar mereka anak-anak muda untuk (melayani) mereka, seakan-akan mereka itu mutiara yang tersimpan. (24) [QS. Ath Thuur : 17-24]"],["p","Hikmah yang terkandung dalam Al Wa’du (janji)."],["p","1. Memberi motivasi/dorongan kepada orang yang beriman untuk beribadah dengan sungguh- sungguh dan memperbanyak melakukan kebaikan."],["p","2. Orang yang beriman dan beramal shaleh lebih bershabar dalam menghadapi cobaan hidup yang berat di dunia ini, karena ia punya keyaqinan bahwa Allah SWT. akan memberi pahala terhadap keshabarannya berupa ni’mat yang berlipat ganda di akhirat kelak"],["p","3. Dapat menunjukkan kepada orang yang beriman bahwa betapa besar rahmat yang diberikan oleh Allah SWT kepada ummat manusia. Amal shaleh yang dilakukan oleh manusia tidak seimbang dengan ganjaran yang Allah berikan kepadanya"],["p","4. Memberi kesadaran kepada orang yang beriman bahwa jika ia beriman dan beramal shaleh, ganjaran itu tidak hanya diperoleh di akhirat saja, tetapi ada juga ganjaran yang langsung diberikan oleh Allah SWT. di dunia berupa kehidupan yang tenang, damai dan berkecukupan."],["p","(Bersambung)"]],"c20220320_1277":[["p","Ahad, 20 Maret 2022/17 Sya’baan 1443 Brosur No.: 2072/2112/IA"],["h","ADABUL MAJLIS DAN THALABUL ‘ILMI"],["p","Sebagai seorang muslim, hendaknya kita menghadiri majlis ilmu dengan adab yang sesuai dengan syariat Islam. Adab menunjukkan kepribadian dari seorang muslim. Rasulullah sendiri telah mencontohkan bagaimana seharusnya beradab dalam setiap aktivitas, termasuk majlis. Berikut ini adalah beberapa adab dalam majelis yang perlu diketahui:"],["h","1. Meluruskan niat ikhlas karena mengharap ridla Allah"],["p","Diantara salah satu syarat diterima amal adalah melakukan amal perbuatan semata-mata karena ingin mendapatkan ridla Allah SWT."],["a","وَمَنْ اَحْسَنُ دِيْنًا مِّمَّنْ اَسْلَمَ وَجْهَهٗ لِلّٰهِ وَهُوَ مُحْسِنٌ وَّاتَّبَعَ مِلَّةَ اِبْرٰهِيْمَ حَنِيْفًا ۗ وَاتَّخَذَ اللّٰهُ اِبْرٰهِيْمَ خَلِيْلًا(125) النساء : 125"],["p","Dan siapakah yang lebih baik agamanya daripada orang yang ikhlas menyerahkan dirinya kepada Allah, sedang dia pun mengerjakan kebaikan, dan ia mengikuti agama Ibrahim yang lurus? Dan Allah mengambil Ibrahim menjadi kesayangan-Nya. [Q.S An Nisaa’ : 125]"],["a","وَمَآ اُمِرُوْٓا اِلَّا لِيَعْبُدُوا اللّٰهَ مُخْلِصِيْنَ لَهُ الدِّيْنَ ۙ حُنَفَاۤءَ وَيُقِيْمُوا الصَّلٰوةَ وَيُؤْتُوا الزَّكٰوةَ وَذٰلِكَ دِيْنُ الْقَيِّمَةِ (5) البينة : 5"],["p","Padahal mereka tidak disuruh kecuali supaya menyembah Allah dengan memurnikan kethaatan kepada-Nya dalam (menjalankan) agama dengan lurus, dan supaya mereka mendirikan shalat dan menunaikan zakat; dan yang demikian itulah agama yang lurus. [Q.S Al Bayyinah : 5]"],["h","2. Memberikan salam kepada orang yang ada di majlis ‘ilmu"],["p","Salah satu dari keindahan ajaran Islam adalah bahwa Islam mengajarkan kepada setiap pemeluknya untuk mengucapkan salam setiap kali bertemu dengan saudaranya sesama muslim, baik ketika memasuki rumah atau memasuki majlis. Salam menurut ajaran Islam pada hakikatnya adalah do'a yang kita panjatkan kepada Allah SWT untuk keselamatan dan kesejahteraan saudara kita yang kita jumpai."],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا تَدْخُلُوْنَ الْجَنَّةَ حَتَّى تُؤْمِنُوْا وَلَا تُؤْمِنُوْا حَتَّى تَحَابُّوا. اَوَلَا اَدُلُّكُمْ عَلَى شَىْءٍ اِذَا فَعَلْتُمُوْهُ تَحَابَبْتُمْ؟ اَفْشُوا السَّلَامَ بَيْنَكُمْ. مسلم 1: 74 رقم 93"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Kamu sekalian tidak akan masuk surga sehingga kalian beriman, dan kalian tidak akan beriman sehingga berkasih sayang. Maukah aku tunjukkan kepada kalian sesuatu perbuatan, apabila kalian melakukannya niscaya kalian saling berkasih sayang ? Tebarkanlah salam diantara kalian\". [HR. Muslim juz 1, hal. 74, no. 93]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اِذَا انْتَهَى اَحَدُكُمْ اِلَى الْمَجْلِسِ فَلْيُسَلِّمْ، اِذَا اَرَادَ اَنْ يَقُوْمَ فَلْيُسَلِّمْ. فَلَيْسَتِ الْاُوْلَى بِاَحَقَّ مِنَ الْاٰخِرَةِ. ابو داود 4: 353، رقم: 5208"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Apabila seseorang dari kalian tiba di majlis, hendaklah mengucapkan salam. Dan apabila ia ingin meninggalkan majlis, maka hendaklah mengucapkan salam. Maka yang pertama (mengucap salam ketika tiba di majlis) tidaklah lebih berhaq (lebih utama) dari pada yang akhir (ketika akan berpisah)”. [HR. Abu Dawud juz 4, hal. 353, no. 5208]"],["p","3. Duduk di tempat yang dekat dengan guru, berusaha menempati tempat yang tersisa dan berlapang di dalam majlis ‘ilmu"],["a","عَنْ اَبِيْ وَاقِدٍ اللَّيْثِيِّ اَنَّ رَسُوْلَ الله ﷺ بَيْنَمَا هُوَ جَالِسٌ فِى الْمَسْجِدِ وَالنَّاسُ مَعَهُ، اِذْ اَقْبَلَ ثَلَاثَةُ نَفَرٍ، فَاَقْبَلَ اثْنَانِ اِلىَ رَسُوْلِ اللهِ ﷺ ، وَذَهَبَ وَاحِدٌ. قَالَ فَوَقَفَا عَلَى رَسُوْلِ اللهِ ﷺ، فَاَمَّا اَحَدُهُمَا فَرَأَى فُرْجَةً فِى الْحَلْقَةِ فَجَلَسَ فِيْهَا. وَاَمَّا الْاٰخَرُ فَجَلَسَ خَلْفَهُمْ. وَاَمَّا الثَّالِثُ فَاَدْبَرَ ذَاهِبًا. فَلَمَّا فَرَغَ رَسُوْلُ اللهِ ﷺ قَالَ: اَلَا اُخْبِرُ كُمْ عَنِ النَّفَرِ الثَّلَاثَةِ؟ اَمَّا اَحَدُهُمْ فَاَوَى اِلىَ اللهِ فَاٰوَاهُ اللهُ. وَاَمَّا الْاٰخَرُ فَاسْتَحْيَا فَاسْتَحْيَا اللهُ تَعَالىَ مِنْهُ. وَاَمَّا الْاٰخَرُ فَاَعْرَضَ فَاَعْرَضَ اللهُ عَنْهُ. البخارى 1: 24"],["p","Dari Abu Waqid Al-Laitsiy, ia berkata, \"Pada suatu waktu Rasulullah SAW sedang duduk di masjid bersama orang banyak, kemudian datang tiga orang. Yang dua orang langsung maju menghadap Rasulullah SAW, sedangkan yang seorang lagi berpaling lalu pergi. Perawi berkata : Lalu dua orang tersebut berhenti pada majlis Rasulullah SAW. Adapun salah satu diantaranya melihat tempat yang masih longgar di dalam majlis tersebut, kemudian ia duduk padanya. Dan yang satunya lagi duduk di belakang mereka. Sedangkan orang yang ketiga langsung berpaling lalu pergi. Setelah selesai, kemudian Rasulullah SAW bersabda : \"Maukah aku beritahukan kepada kalian perihal tiga orang tersebut ? Adapun yang satu orang, ia mencari keridlaan Allah, maka Allah-pun ridla kepadanya. Yang satunya lagi, ia malu kepada Allah, maka Allah Ta’aalaa-pun malu kepadanya. Sedangkan yang satunya lagi, ia berpaling, maka Allah-pun berpaling pula darinya. [HR. Bukhari juz 1, hal. 24]"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اِذَا قِيْلَ لَكُمْ تَفَسَّحُوْا فِى الْمَجٰلِسِ فَافْسَحُوْا يَفْسَحِ اللّٰهُ لَكُمْۚ وَاِذَا قِيْلَ انْشُزُوْا فَانْشُزُوْا يَرْفَعِ اللّٰهُ الَّذِيْنَ اٰمَنُوْا مِنْكُمْۙ وَالَّذِيْنَ اُوْتُوا الْعِلْمَ دَرَجٰتٍۗ وَاللّٰهُ بِمَا تَعْمَلُوْنَ خَبِيْرٌ(11) المجادلة : 11"],["p","Hai orang-orang yang beriman, apabila dikatakan kepadamu: \"Berlapang-lapanglah dalam majlis\", maka lapangkanlah, niscaya Allah akan memberi kelapangan untukmu. Dan apabila dikatakan: \"Berdirilah kamu”, maka berdirilah, niscaya Allah akan meninggikan orang-orang yang beriman di antaramu dan orang-orang yang diberi ilmu pengetahuan beberapa derajat. Dan Allah Maha Mengetahui apa yang kamu kerjakan. [QS. Al-Mujaadalah : 11]"],["h","4. Disiplin dan menepati waktu kehadiran di majlis ‘ilmu"],["a","وَالْعَصْرِۙ(1) اِنَّ الْاِنْسَانَ لَفِيْ خُسْرٍۙ(2) اِلَّا الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ وَتَوَاصَوْا بِالْحَقِّ ۙ وَتَوَاصَوْا بِالصَّبْرِ (3) العصر : 1-3"],["p","Demi masa (1)"],["p","Sesungguhnya manusia itu benar-benar berada dalam kerugian (2)"],["p","kecuali orang-orang yang beriman dan mengerjakan amal shaleh dan nasihat menasihati supaya menthaati kebenaran dan nasihat menasihati supaya menetapi keshabaran. (3) [Q.S. Al ‘Ashr : 1-3]"],["a","اِنَّ اللّٰهَ يُحِبُّ الَّذِيْنَ يُقَاتِلُوْنَ فِيْ سَبِيْلِهٖ صَفًّا كَاَنَّهُمْ بُنْيَانٌ مَّرْصُوْصٌ (4) الصف : 4"],["p","Sesungguhnya Allah menyukai orang-orang yang berperang di jalan-Nya dalam barisan yang teratur seakan-akan mereka seperti suatu bangunan yang tersusun kokoh.(4) [ QS. As Shaff : 4]"],["p","Perkataan dari Ali bin Abi Thalib :"],["a","اَلْحَقُّ بِلَا نِظَامٍ يَغْلِبُهُ الْبَاطِلُ بِالنِّظَامِ"],["p","“Kebenaran yang tidak disiplin/diorganisir dapat dikalahkan oleh kebathilan yang disiplin/diorganisir”"],["h","5. Bersungguh-sungguh dalam belajar dan selalu merasa membutuhkan ilmu"],["a","وَجَاهِدُوْا فِى اللّٰهِ حَقَّ جِهَادِهٖ (78) الجح : 78"],["p","Dan berjihadlah kamu pada jalan Allah dengan jihad yang sebenar-benarnya. [QS. Al Hajj : 78]"],["a","وَمَآ اَرْسَلْنَا مِنْ قَبْلِكَ اِلَّا رِجَالًا نُّوْحِيْٓ اِلَيْهِمْ فَسْـَٔلُوْٓا اَهْلَ الذِّكْرِ اِنْ كُنْتُمْ لَا تَعْلَمُوْنَ (43) النحل : 43"],["p","Dan Kami tidak mengutus sebelum kamu (Muhammad), kecuali orang-orang lelaki yang Kami beri wahyu kepada mereka; maka bertanyalah kepada orang yang mempunyai pengetahuan jika kalian tidak mengetahui. [QS. An Nahl : 43]"],["a","وَالَّذِيْنَ جَاهَدُوْا فِيْنَا لَنَهْدِيَنَّهُمْ سُبُلَنَاۗ وَاِنَّ اللّٰهَ لَمَعَ الْمُحْسِنِيْنَ (69) العنكبوت :69"],["p","Dan orang-orang yang berjihad untuk (mencari keridlaan) Kami, benar-benar akan Kami tunjukkan Kepada mereka jalan-jalan Kami. Dan sesungguhnya Allah benar-benar beserta orang-orang yang berbuat baik. [Q.S. Al ‘Ankabuut : 69]"],["p","Ada 6 syarat yang harus dimiliki oleh seorang penuntut ilmu:"],["a","اَخِيْ لَنْ تَنَالَ العِلْمَ اِلاَّ بِسِتَّةٍ، سَأُنْبِيْكَ عَنْ تَفْصِيْلِهَا بِبَيَانٍ"],["a","ذَكَاءٌ وَحِرْصٌ وَاجْتِهَادٌ وَبُلْغَةٌ، وَصُحْبَةُ اُسْتَاذٍ وَطُوْلُ زَمَانٍ"],["p","\"Saudaraku, ilmu tidak akan diperoleh kecuali dengan enam perkara, akan saya beritahukan rinciannya: (1) kecerdasan, (2) rakus (sangat menginginkan), (3) bersungguh-sungguh, (4) biaya (kesediaan mengeluarkan uang), (5) bersahabat dengan ustadz/guru, (6) memerlukan waktu yang lama.” [Kata kata hikmah]"],["h","6. Membawa Al-Qur'an, buku catatan dan alat tulis"],["p","Salah satu nama Al-Qur’an adalah Al-Kitab. Bahkan, penyebutan kata Al-Kitab di dalam Al-Qur’an jauh lebih banyak dibandingkan dengan kata Al-Qur’an. Kata “Al-kitab” disebutkan sebanyak 230 kali sedangkan kata “Al-Qur’an” hanya disebutkan sebanyak 58 kali."],["p","Al-Qur’an berarti bacaan, sedangkan Al-Kitab berarti tulisan. Lebih banyaknya penggunaan kata Al-Kitab daripada Al-Qur’an menunjukkan tingginya anjuran Al-Qur’an untuk menulis (tanpa mengesampingkan pentingnya membaca)."],["a","اِقْرَأْ بِاسْمِ رَبِّكَ الَّذِيْ خَلَقَۚ (1) خَلَقَ الْاِنْسَانَ مِنْ عَلَقٍۚ (2) اِقْرَأْ وَرَبُّكَ الْاَكْرَمُۙ (3) الَّذِيْ عَلَّمَ بِالْقَلَمِۙ (4) عَلَّمَ الْاِنْسَانَ مَا لَمْ يَعْلَمْ(5) العلق : 1-5"],["p","Bacalah dengan (menyebut) nama Tuhanmu Yang menciptakan,(1)"],["p","Dia telah menciptakan manusia dari segumpal darah.(2)"],["p","Bacalah, dan Tuhanmulah Yang Maha Pemurah, (3)"],["p","Yang mengajar (manusia) dengan perantaraan pena. (4)"],["p","Dia mengajarkan kepada manusia apa yang tidak diketahuinya. (5) [Q.S. Al ‘Alaq : 1-5]"],["a","عَنْ عَمْرِو بْنِ اَبِيْ سُفْيَانَ اَنَّهُ سَمِعَ عُمَرَ بْنَ الْخَطَّابِ يَقُوْلُ : قَيِّدُوا الْعِلْمَ بِالْكِتَابِ . الدارمى 1: 127 رقم 484"],["p","Dari ‘Amr bin Abu Sufyan, bahwasanya ia mendengar ‘Umar bin Khaththab berkata : “Ikatlah ilmu dengan tulisan.” [HR. Darimi juz 1, hal 127, no 484]"],["a","عَنِ ابْنِ عُمَرَ اَنَّهُ قَالَ : قَيِّدُوْا هٰذَا الْعِلْمَ بِالْكِتَابِ . الدارمى 1 : 128 رقم 485"],["p","Dari Ibnu ‘Umar, bahwasanya ia berkata: “Ikatlah ilmu ini dengan tulisan.” [HR. Darimi Juz 1, hal 128, no 485]"],["p","Hadits marfu’ dari Anas:"],["a","قَيِّدُوْا الْعِلْمَ بِالْكِتَابِ . ميزان الاعتدال 2 : 541 رقم 4777"],["p","“Ikatlah ilmu dengan tulisan” [ Mizaanul I’tidaal juz 2, hal 541, no 4777]"],["p","Keterangan :"],["p","Hadits ini dlo’if, Ibnul Madiniy berkata : ‘Abdul Hamid (bin Sulaiman) dan saudaranya yaitu Fulaih, kedua-duanya dlo’if."],["h","7. Berpakaian yang rapi dan sopan"],["a","يٰبَنِيْٓ اٰدَمَ قَدْ اَنْزَلْنَا عَلَيْكُمْ لِبَاسًا يُّوَارِيْ سَوْاٰتِكُمْ وَرِيْشًاۗ وَلِبَاسُ التَّقْوٰى ذٰلِكَ خَيْرٌۗ ذٰلِكَ مِنْ اٰيٰتِ اللّٰهِ لَعَلَّهُمْ يَذَّكَّرُوْنَ(26) الاعراف : 26"],["p","Hai anak Adam, sesungguhnya Kami telah menurunkan kepadamu pakaian untuk menutupi ‘auratmu dan pakaian indah untuk perhiasan. Dan pakaian takwa itulah yang paling baik. Yang demikian itu adalah sebahagian dari tanda-tanda kekuasaan Allah, mudah-mudahan mereka selalu ingat. [Q.S. Al A’raaf : 26]"],["a","عَنْ عَبْدِ اللهِ بْنِ مَسْعُوْدٍ عَنِ النَّبِيِّ ﷺ قَالَ: لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِى قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ كِبْرٍ. قَالَ رَجُلٌ: اِنَّ الرَّجُلَ يُحِبُّ اَنْ يَكُوْنَ ثَوْبُهُ حَسَنًا وَ نَعْلُهُ حَسَنَةً؟ قَالَ: اِنَّ اللهَ جَمِيْلٌ يُحِبُّ الْجَمَالَ. اَلْكِبْرُ بَطَرُ الْحَقِّ وَ غَمْطُ النَّاسِ. مسلم 1: 93 رقم 147"],["p","Dari Abdullah bin Mas'ud, dari Nabi SAW beliau bersabda, \"Tidak akan masuk surga orang yang di dalam hatinya ada sebesar dzarrah dari sombong\". Lalu ada seorang laki-laki bertanya : \"Sesungguhnya ada orang senang bajunya itu bagus dan sandalnya bagus, (yang demikian itu bagaimana, ya Rasulullah ?\"). Rasulullah SAW bersabda : \"Sesungguhnya Allah itu indah dan suka pada keindahan. Sombong itu ialah menolak kebenaran dan merendahkan manusia\". [HR. Muslim juz 1, hal. 93, no 147]"],["p","8. Rendah hati (tawaadlu’) dan tidak sombong."],["a","وَاخْفِضْ جَنَاحَكَ لِمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِيْنَ (215) الشعراء: 215"],["p","Dan rendahkanlah dirimu (Muhammad) terhadap orang-orang yang mengikutimu, yaitu orang-orang yang beriman. [QS. Asy-Syu’araa’: 215]."],["a","وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِى الْاَرْضِ مَرَحًاۗ اِنَّ اللّٰهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُوْرٍ (18) لقمان :18"],["p","Dan janganlah kamu memalingkan mukamu dari manusia (karena sombong) dan janganlah kamu berjalan di muka bumi dengan angkuh. Sesungguhnya Allah tidak menyukai orang-orang yang sombong lagi membanggakan diri. [Q.S. Luqmaan : 18]"],["a","عَنْ مُجَاهِدٍ قَالَ: لَا يَتَعَلَّمُ مَنِ اسْتَحْيَى وَاسْتَكْبَرَ. الدارمى 1: 138 رقم 538"],["p","Dari Mujaahid, ia berkata: \"Orang pemalu dan orang sombong tidak bakalan bisa menuntut ilmu\". [H.R. Darimi juz 1, hal 138, no.538, perkataan tabi’iy, dlo’if, karena dalam isnadnya ada perawi yang tidak disebutkan namanya]"],["a","اُنْظُرْ اِلَى مَا قَالَ وَلَا تَنْظُرْ اِلَى مَنْ قَالَ"],["p","“Perhatikanlah apa yang dikatakan, jangan memperhatikan siapa yang mengatakan.” [ Kata-kata hikmah]"],["h","9. Mendengarkan dan diam memperhatikan"],["a","وَاِذَا قُرِئَ الْقُرْاٰنُ فَاسْتَمِعُوْا لَهٗ وَاَنْصِتُوْا لَعَلَّكُمْ تُرْحَمُوْنَ (204) الاعراف : 204"],["p","\"Dan apabila dibacakan Al-Qur'an, maka dengarkanlah dan diamlah, agar kamu mendapat rahmat.\" [QS. Al-A'raaf : 204]"],["p","Kata al-istimaa’ pada ayat tersebut memiliki ma’na yang lebih khusus daripada as-sam’u sebab kata al-istimaa’ (mendengarkan) dapat dihasilkan dengan sengaja dan niat atau dengan menfokuskan panca indera terhadap suatu pembicaraan untuk memahaminya."],["p","Sementara kata “as-sam’u” dapat dihasilkan walaupun dengan tanpa sengaja. Dan kata “al-inshoot” memiliki ma’na diam untuk mendengarkan, sehingga tidak ada gangguan untuk mendengarkan segala yang dibacakan."],["p","10. Tidak boleh membuat gaduh, hiruk pikuk serta bermain dengan sesuatu (Misal : HP, dan peralatan lainnya) di dalam majlis ilmu"],["a","وَقَالَ الَّذِيْنَ كَفَرُوْا لَا تَسْمَعُوْا لِهٰذَا الْقُرْاٰنِ وَالْغَوْا فِيْهِ لَعَلَّكُمْ تَغْلِبُوْنَ(26) فصلت : 26"],["p","Dan orang-orang yang kafir berkata: \"Janganlah kamu mendengar dengan sungguh-sungguh akan Al Qur'an ini dan buatlah hiruk-pikuk terhadapnya, supaya kamu dapat mengalahkan (mereka). [QS. Fushshilat : 26]"],["a","وَمِنْهُمْ مَّنْ يَّسْتَمِعُ اِلَيْكَۚ حَتّٰىٓ اِذَا خَرَجُوْا مِنْ عِنْدِكَ قَالُوْا لِلَّذِيْنَ اُوْتُوا الْعِلْمَ مَاذَا قَالَ اٰنِفًا ۗ اُولٰۤىِٕكَ الَّذِيْنَ طَبَعَ اللّٰهُ عَلٰى قُلُوْبِهِمْ وَاتَّبَعُوْٓا اَهْوَاۤءَهُمْ (16) محمد : 16"],["p","Dan di antara mereka ada orang yang mendengarkan perkataanmu sehingga apabila mereka keluar dari sisimu mereka berkata kepada orang yang telah diberi ilmu pengetahuan (shahabat-shahabat Nabi): \"Apakah yang dikatakannya tadi?\" Mereka itulah orang-orang yang dikunci mati hati mereka oleh Allah dan mengikuti hawa nafsu mereka.[Q.S. Muhammad: 16]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ تَوَضَّأَ فَاَحْسَنَ الْوُضُوْءَ ثُـمَّ اَتَى الْجُمُعَةَ فَاسْتَمَعَ وَاَنْصَتَ غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ وَزِيَادَةُ ثَلَاثَةِ اَيَّامٍ. وَمَنْ مَسَّ الْحَصَى فَقَدْ لَغَا. مسلم 2: 588 رقم 27"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Barangsiapa berwudlu dengan memperbagus wudlunya, kemudian datang ke shalat Jum’at, lalu ia mendengarkan dan diam, maka diampuni baginya apa yang terjadi antara Jum’at itu dengan Jum’at berikutnya, dan ditambah tiga hari. Dan barangsiapa yang bermain-main dengan kerikil, sungguh dia telah berbuat sia-sia”. [HR. Muslim juz, 2, hal. 588, no. 27]"],["p","11. Tidak boleh menuntut ilmu untuk mencari keuntungan dunia seperti agar mendapatkan jabatan, pekerjaan dengan gaji tinggi, dan sebagainya."],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ ﷺ : مَنْ تَعَلَّمَ عِلْمًا مِمَّا يُبْتَغَى بِهِ وَجْهُ اللَّهِ عَزَّ وَجَلَّ لَا يَتَعَلَّمُهُ، اِلَّا لِيُصِيْبَ بِهِ عَرَضًا مِنْ الدُّنْيَا لَمْ يَجِدْ عَرْفَ الْجَنَّةِ يَوْمَ الْقِيَامَةِ. يَعْنِيْ رِيْحَهَا. ابو داود 3 : 323 رقم 3664"],["p","Dari Abu Hurairah, ia berkata, \"Rasulullah SAW bersabda: \"Barangsiapa mempelajari suatu ilmu yang seharusnya karena Allah Azza Wa Jalla, namun ia tidak mempelajarinya kecuali untuk mendapatkan sebagian dari dunia, maka ia tidak akan mendapatkan baunya surga pada hari kiyamat.\" [H.R. Abu Dawud juz 3, hal 323 no 3664, dlo’if karena dalam isnadnya ada perawi bernama Fulaih (bin Sulaiman)]"],["h","12. Tidak banyak tertawa saat berada di dalam majlis ilmu"],["p","Di dalam hadits disebutkan :"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا تُكْثِرُوا الضَّحِكَ، فَاِنَّ كَثْرَةَ الضَّحِكِ تُمِيْتُ الْقَلْبَ. ابن ماجه 2 : 1403 رقم 4193"],["p","Dari Abu Hurairah, ia berkata, \"Rasulullah SAW bersabda: \"Janganlah kalian banyak tertawa, karena banyak tertawa akan mematikan hati. “ [HR. Ibnu Majah juz 2, hal 1403, no 4193]"],["p","13. Tidak duduk di tengah lingkaran majlis ilmu atau di antara dua orang yang sedang duduk."],["a","عَنْ عَمْرِو بْنِ شُعَيْبٍ عَنْ اَبِيْهِ عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو عَنْ رَسُوْلِ اللهِ ﷺ قَالَ: لَا يَحِلُّ لِرَجُلٍ اَنْ يُفَرِّقَ بَيْنَ اثْنَيْنِ اِلاَّ بِاِذْنِهِمَا. ابو داود 4: 262، رقم: 4845"],["p","Dari ‘Amr bin Syu’aib dari ayahnya, dari Abdullah bin ‘Amr, dari Rasulullah SAW, beliau bersabda, “Tidak halal bagi seseorang untuk memisahkan diantara dua orang (yang duduk), kecuali dengan izin dari keduanya”. [HR. Abu Dawud juz 4, hal. 262, no. 4845]"],["a","عَنْ حُذَيْفَةَ اَنَّ رَسُوْلَ اللهِ ﷺ لَعَنَ مَنْ جَلَسَ وَسَطَ اْلحَلْقَةِ. ابو داود 4: 258، رقم: 4826"],["p","Dari Hudzaifah, bahwasanya Rasulullah SAW mela’nat orang yang duduk di tengah-tengah lingkaran orang. [HR. Abu Dawud juz 4, hal. 258, no. 4826]"],["h","14. Tidak mengambil tempat orang lain yang pergi sebentar dari majlis"],["p","Terkadang, seseorang bisa pergi sebentar dari majlis untuk suatu keperluan. Hal ini tidak menjadikan tempat duduknya yang kosong boleh diisi siapa saja. Seorang muslim tidak dibenarkan menduduki tempat yang kosong sementara. Dan lebih dianjurkan untuk menempati tempat lain yang belum terisi."],["a","عَنْ سَعِيْدِ بْنِ اَبِى اْلحَسَنِ قَالَ: جَاءَنَا اَبُوْ بَكْرَةَ فِى شَهَادَةٍ، فَقَامَ لَهُ رَجُلٌ مِنْ مَجْلِسِهِ، فَاَبَى اَنْ يَجْلِسَ فِيْهِ، وَقَالَ: اِنَّ النَّبِيَّ ص نَهَى عَنْ ذَا. ابو داود 4: 258، رقم: 4827"],["p","Dari Sa’id bin Abul Hasan, ia berkata : Abu Bakrah datang dalam suatu kesaksian, lalu ada seorang laki-laki bangkit dari tempat duduknya (agar Abu Bakrah duduk di situ), maka Abu Bakrah enggan untuk duduk pada tempat tersebut, dan ia berkata, “Sesungguhnya Nabi SAW melarang dari yang demikian itu”. [HR. Abu Dawud juz 4, hal. 258, no. 4827]"],["a","عَنِ ابْنِ عُمَرَ عَنِ النَّبِيِّ ﷺ قَالَ: لَا يُقِيْمُ الرَّجُلُ الرَّجُلَ مِنْ مَقْعَدِهِ ثُمَّ يَجْلِسُ فِيْهِ، وَلٰكِنْ تَفَسَّحُوْا وَتَوَسَّعُوْا. مسلم 4: 1714 رقم 28"],["p","Dari Ibnu ‘Umar, dari Nabi SAW, beliau bersabda, “Tidak boleh seseorang menyuruh orang lain untuk berdiri dari tempat duduknya lalu ia duduk di situ, akan tetapi longgarkanlah dan luaskanlah”. [HR Muslim juz 4, hal. 1714 no 28]"],["a","عَنْ وَهْبِ بْنِ حُذَيْفَةَ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اَلرَّجُلُ اَحَقُّ بِمَجْلِسِهِ، وَاِنْ خَرَجَ لِحَاجَتِهِ ثُمَّ عَادَ فَهُوَ اَحَقُّ بِمَجْلِسِهِ. الترمذى 4: 183، رقم: 2899"],["p","Dari Wahab bin Hudzaifah, bahwasanya Rasulullah SAW bersabda, “Seseorang itu lebih berhak pada tempat duduknya. Dan apabila ia keluar untuk suatu keperluan, kemudian ia kembali lagi, maka ia lebih berhak pada tempat duduknya itu”. [HR. Tirmidzi juz 4, hal. 183, no. 2899]"],["h","15. Memperhatikan kesopanan selama berada di dalam majlis ilmu"],["p","Saat berada di majlis, seorang muslim juga dianjurkan untuk memperhatikan kesopanan. Yaitu dengan menjaga sikap dari hal yang dapat mengganggu orang lain di majlis tersebut. Seperti menguap, membuang ingus, bersendawa, dan lain sebagainya. Di dalam hadits disebutkan :"],["a","عَنْ اَبِيْ هُرَيْرَةَ اَنَّ رَسُوْلُ اللهِ ﷺ قَالَ : اَلتَّثَاؤُبُ مِنَ الشَّيْطَانِ، فَاِذَا تَثَاءَبَ اَحَدُكُمْ فَلْيَكْظِمْ مَا اسْتَطَاعَ. مسلم 4 : 2293 رقم 56"],["p","Dari Abu Hurairah, bahwasanya Rasulullah SAW bersabda: “Menguap itu dari gangguan syetan, maka apabila seseorang diantara kalian menguap hendaklah ia menahan semampunya.” [HR. Muslim Juz 4, hal 2293, no 56]"],["a","عَنْ اَبِيْ سَعِيْدِ الْخُدْرِيِّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اِذَا تَثَاؤَبَ اَحَدُكُمْ فَلْيُمْسِكْ بِيَدِهِ عَلَى فِيْهِ فَاِنَّ الشَّيْطَانَ يَدْخُلُ. مسلم 4: 2293 رقم 57"],["p","Dari Abu Sa'id Al-Khudriy, ia berkata : Rasulullah SAW bersabda, \"Apabila seseorang diantara kalian menguap, hendaklah ia menahan dengan tangannya pada mulutnya, karena syaithan akan masuk\". [HR. Muslim juz 4, hal. 2293, no. 57]"],["p","16. Menjauhkan diri dari dosa dan ma’shiyat serta mengingatkan orang yang melakukan pelanggaran"],["p","Seseorang terhalang dari ilmu yang bermanfaat disebabkan banyak melakukan dosa dan ma’shiyat. Sesungguhnya dosa dan ma’shiyat dapat menghalangi ilmu yang bermanfaat, bahkan dapat mematikan hati, merusak kehidupan dan mendatangkan siksa Allah Ta’aalaa."],["a","وَاتَّقُوْا فِتْنَةً لَّا تُصِيْبَنَّ الَّذِيْنَ ظَلَمُوْا مِنْكُمْ خَاۤصَّةً ۚ وَاعْلَمُوْٓا اَنَّ اللّٰهَ شَدِيْدُ الْعِقَابِ (25) الانفال : 25"],["p","Dan peliharalah dirimu daripada siksaan yang tidak khusus menimpa orang-orang yang dhalim saja di antara kamu. Dan ketahuilah bahwa Allah amat keras siksaan-Nya. [QS. Al Anfaal : 25]"],["a","لُعِنَ الَّذِيْنَ كَفَرُوْا مِنْۢ بَنِيْٓ اِسْرَاۤءِيْلَ عَلٰى لِسَانِ دَاوٗدَ وَعِيْسَى ابْنِ مَرْيَمَ ۗ ذٰلِكَ بِمَا عَصَوْا وَّكَانُوْا يَعْتَدُوْنَ (78) كَانُوْا لَا يَتَنَاهَوْنَ عَنْ مُّنْكَرٍ فَعَلُوْهُۗ لَبِئْسَ مَا كَانُوْا يَفْعَلُوْنَ (79) المائدة: 78-79"],["p","Telah dila’nati orang-orang kafir dari Bani Israil dengan lisan Daud dan ‘Isa putra Maryam. Yang demikian itu disebabkan mereka durhaka dan selalu melampaui batas. (78)"],["p","Mereka tidak saling melarang tindakan mungkar yang mereka perbuat. Sesungguhnya amat buruklah apa yang selalu mereka perbuat itu. (79) [QS. Al-Maaidah : 78 - 79]"],["a","عَنْ حُذَيْفَةَ بْنِ اْليَمَانِ عَنِ النَّبِيِّ ﷺ قَالَ: وَالَّذِيْ نَفْسِيْ بِيَدِهِ لَتَأْمُرُنَّ بِالْمَعْرُوْفِ وَلَتَنْهَوُنَّ عَنِ الْمُنْكَرِ وَلَيُوْشِكَنَّ اللهُ اَنْ يَبْعَثَ عَلَيْكُمْ عِقَابًا مِنْهُ وَتَدْعُوْنَهُ فَلَا يَسْتَجِيْبُ لَكُمْ. الترمذى 3: 316، رقم: 2259 هذا حديث حسن"],["p","Dari Hudzaifah bin Yaman, dari Nabi SAW, beliau bersabda, \"Demi Allah yang jiwaku ada ditangan-Nya, sungguh kamu sekalian akan menyuruh kepada yang ma'ruf dan mencegah dari yang mungkar atau (kalau tidak) pasti Allah akan menurunkan siksa kepada kalian, kemudian kalian berdo'a kepada Allah, namun Dia tidak mengabulkan do'a kalian\". [HR. Tirmidzi juz 3, hal. 316, no. 2259, Ini hadits hasan]"],["a","عَنْ قَيْسٍ قَالَ، قَالَ اَبُوْ بَكْرٍ بَعْدَ اَنْ حَمِدَ اللهَ وَاَثْنَى عَلَيْهِ: يَا اَيُّهَا النَّاسُ، اِنَّكُمْ تَقْرَءُوْنَ هٰذِهِ اْلاٰيَةَ وَتَضَعُوْنَهَا عَلَى غَيْرِ مَوَاضِعِهَا عَلَيْكُمْ اَنْفُسَكُمْ لَا يَضُرُّكُمْ مَنْ ضَلَّ اِذَا اهْتَدَيْتُمْ. وَاِنَّا سَمِعْنَا النَّبِىَّ ﷺ يَقُوْلُ: اِنَّ النَّاسَ اِذَا رَأَوُا الظَّالِمَ فَلَمْ يَأْخُذُوْا عَلَى يَدَيْهِ اَوْشَكَ اَنْ يَعُمَّهُمُ اللهُ بِعِقَابٍ. وَاِنِّيْ سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: مَا مِنْ قَوْمٍ يُعْمَلُ فِيْهِمْ بِالْمَعَاصِى ثُمَّ يَقْدِرُوْنَ عَلَى اَنْ يُغَيِّرُوْا ثُمَّ لَا يُغَيِّرُوْا اِلَّا يُوْشِكُ اَنْ يَعُمَّهُمُ اللهُ مِنْهُ بِعِقَابٍ. ابو داود 4: 122، رقم: 4338"],["p","Dari Qais, ia berkata : Abu Bakar (Ash-Shiddiq) berkhutbah, setelah ia memuji Allah dan menyanjung-Nya, ia berkata, \"Wahai para manusia, sesungguhnya kalian telah membaca ayat ini, tetapi kalian keliru dalam memahaminya, yaitu ayat (yang artinya), \"Hai orang-orang yang beriman, jagalah dirimu. Orang yang sesat tidak akan mendatangkan madlarat kepadamu bila kamu telah mendapat petunjuk\". [QS. Al-Maaidah : 105]. Sesungguhnya kami mendengar Nabi SAW bersabda, \"Sesungguhnya sekelompok orang apabila mereka melihat kedhaliman, lalu mereka tidak mencegahnya, hampir-hampir Allah akan meratakan siksa kepada mereka\". Dan sesungguhnya aku mendengar Rasulullah SAW bersabda, \"Tidaklah suatu kaum yang di dalamnya dilakukan kema'shiyatan-kema'shiyatan, sedangkan mereka mampu mencegahnya tetapi mereka tidak mau mencegahnya, melainkan Allah mendatangkan adzab secara merata kepada mereka\". [HR. Abu Dawud, juz 4, hal. 122, no. 4338]"],["h","17. Mengucapkan do’a ketika bangkit dari majlis"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ جَلَسَ فِى مَجْلِسٍ فَكَثُرَ فِيْهِ لَغَطُهُ فَقَالَ قَبْلَ اَنْ يَقُوْمَ مِنْ مَجْلِسِهِ ذٰلِكَ: سُبْحَانَكَ اللّٰهُمَّ وَبِحَمْدِكَ اَشْهَدُ اَنْ لَا اِلٰهَ اِلَّا اَنْتَ اَسْتَغْفِرُكَ وَاَتُوْبُ اِلَيْكَ، اِلَّا غُفِرَ لَهُ مَا كَانَ فِيْ مَجْلِسِهِ ذٰلِكَ. الترمذى 5: 158 رقم: 3494، هذا حديث حسن صحيح غريب"],["p","Dari Abu Hurairah RA, ia berkata : Rasulullah SAW bersabda, “Barangsiapa duduk di suatu majlis dan banyak gaduh padanya, lalu sebelum bangkit dari majlisnya ia membaca Subhaanakalloohumma wa bi hamdika asyhadu allaa ilaaha illaa anta astaghfiruka wa atuubu ilaik (Maha Suci Engkau ya Allah dan dengan memuji-Mu aku bersaksi bahwa tidak ada Tuhan selain Engkau, aku mohon ampun kepada-Mu dan aku bertaubat kepada-Mu), niscaya diampuni baginya apa yang telah terjadi di majlisnya itu. [HR. Tirmidzi juz 5, hal. 158, no. 3494, ini hadits hasan shahih gharib]"],["p","--oo0oo—"]],"c20220327_1278":[["p","Ahad, 27 Maret 2022/24 Sya’ban 1443 Brosur No. : 2073/2113/IF"],["h","PUASA"],["p","Puasa, yang di dalam bahasa Al-Qur'an Ash-Shaum/Ash-Shiyaam adalah salah satu dari beberapa kewajiban yang harus dilaksanakan oleh orang-orang beriman. Firman Allah :"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِيْنَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُوْنَۙ (183)اَيَّامًا مَّعْدُوْدٰتٍۗ فَمَنْ كَانَ مِنْكُمْ مَّرِيْضًا اَوْ عَلٰى سَفَرٍ فَعِدَّةٌ مِّنْ اَيَّامٍ اُخَرَ ۗ وَعَلَى الَّذِيْنَ يُطِيْقُوْنَهٗ فِدْيَةٌ طَعَامُ مِسْكِيْنٍۗ فَمَنْ تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهٗ ۗ وَاَنْ تَصُوْمُوْا خَيْرٌ لَّكُمْ اِنْ كُنْتُمْ تَعْلَمُوْنَ (184) شَهْرُ رَمَضَانَ الَّذِيْٓ اُنْزِلَ فِيْهِ الْقُرْاٰنُ هُدًى لِّلنَّاسِ وَبَيِّنٰتٍ مِّنَ الْهُدٰى وَالْفُرْقَانِۚ فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ ۗ وَمَنْ كَانَ مَرِيْضًا اَوْ عَلٰى سَفَرٍ فَعِدَّةٌ مِّنْ اَيَّامٍ اُخَرَ ۗ يُرِيْدُ اللّٰهُ بِكُمُ الْيُسْرَ وَلَا يُرِيْدُ بِكُمُ الْعُسْرَ ۖ وَلِتُكْمِلُوا الْعِدَّةَ وَلِتُكَبِّرُوا اللّٰهَ عَلٰى مَا هَدٰىكُمْ وَلَعَلَّكُمْ تَشْكُرُوْنَ (185) البقرة: 183-185"],["p","Hai orang-orang yang beriman, diwajibkan atas kamu berpuasa seba-gaimana diwajibkan atas orang-orang sebelum kamu agar kamu bertaqwa. (183)"],["p","(yaitu) dalam beberapa hari yang tertentu. Maka barangsiapa diantara kamu ada yang sakit atau dalam perjalanan (lalu ia berbuka), maka (wajiblah baginya berpuasa) sebanyak hari yang ditinggalkan itu pada hari-hari yang lain. Dan wajib bagi orang-orang yang berat menjalankannya (jika mereka tidak berpuasa) membayar fidyah, (yaitu): memberi makan seorang miskin. Barangsiapa yang dengan kerelaan hati mengerjakan kebajikan, maka itulah yang lebih baik baginya. Dan berpuasa lebih baik bagimu jika kamu mengetahui. (184)"],["p","(Beberapa hari yang ditentukan itu ialah) bulan Ramadlan, bulan yang di dalamnya diturunkan (permulaan) Al-Qur'an sebagai petunjuk bagi manusia dan penjelasan-penjelasan mengenai petunjuk itu dan pembeda (antara yang haq dan yang bathil). Karena itu, barangsiapa diantara kamu hadir (di negeri tempat tinggalnya) di bulan itu, maka hendaklah ia berpuasa pada bulan itu, dan barangsiapa sakit atau dalam perjalanan (lalu ia berbuka), maka (wajiblah baginya berpuasa) sebanyak hari yang ditinggalkannya itu pada hari-hari yang lain. Allah menghendaki kemudahan bagimu, dan tidak menghendaki kesukaran bagimu. Dan hendaklah kamu mencukupkan bilangannya dan hendaklah kamu mengagungkan Allah atas petunjuk-Nya yang diberikan kepadamu, supaya kamu bersyukur. (185) [QS. Al-Baqarah : 183-185]"],["h","1. Pengertian Ash-Shiyam (Puasa)"],["p","Ash-Shiyam atau Ash-shaum menurut lughah/bahasa, artinya : \"Menahan diri dari melakukan sesuatu\". Seperti firman Allah kepada Maryam :"],["a","فَاِمَّا تَرَيِنَّ مِنَ الْبَشَرِ اَحَدًاۙ فَقُوْلِيْٓ اِنِّيْ نَذَرْتُ لِلرَّحْمٰنِ صَوْمًا فَلَنْ اُكَلِّمَ الْيَوْمَ اِنْسِيًّا (26) مريم: 26"],["p","Jika kamu melihat seorang manusia, maka katakanlah, Sesungguhnya aku telah bernadzar akan berpuasa karena Tuhan Yang Maha Pemurah, maka aku tidak akan berbicara dengan seseorang manusiapun pada hari ini. [QS. Maryam : 26]"],["p","Menurut Syara', ialah :"],["a","اَلاِمْسَاكُ عَنِ الْاَكْلِ وَالشُّرْبِ وَغَشَيَانِ النِّسَاءِ مِنَ الْفَجْرِ اِلىَ الْمَغْرِبِ اِحْتِسَابًا لِلّٰهِ وَاِعْدَادًا لِلنَّفْسِ وَتَـهْيِئَةً لَهَا لِتَقْوَى اللهِ بِالْمُرَاقَبَةِ لَهُ وَتَرْبِيَةِ الْاِرَادَةِ. تفسير المنار 2: 143"],["p","Menahan diri dari makan, minum dan bersetubuh, mulai fajar hingga Maghrib, karena mengharap ridla Allah dan menyiapkan diri untuk bertaqwa kepada-Nya dengan jalan mendekatkan diri kepada Allah dan mendidik kehendak. [Tafsir Al-Manaar juz 2, hal. 143]"],["a","اَلاِمْسَاكُ عَنِ الْاَكْلِ وَالشُّرْبِ وَالْجِمَاعِ وَغَيْرِهِمَا مِـمَّا وَرَدَ بِهِ الشَّرْعُ فِى النَّهَارِ عَلَى الْوَجْهِ الْمَشْرُوْعِ. وَيَتْبَعُ ذٰلِكَ الْاِمْسَاكُ عَنِ اللَّغْوِ وَالرَّفَثِ وَغَيْرِهِمَا مِنَ الْكَلَامِ الْمُحَرَّمِ وَالْمَكْرُوْهِ فِيْ وَقْتٍ مَخْصُوْصٍ بِشُرُوْطٍ مَخْصُوْصَةٍ. سبل السلام 2: 150"],["p","Menahan diri dari makan, minum, jima' dan lain-lain yang telah diperintahkan syara’ kepada kita menahan diri padanya sepanjang hari menurut cara yang disyariatkan. Disertai pula menahan diri dari perkataan sia-sia, perkataan keji/kotor dan lainnya dari perkataan yang diharamkan dan dimakruhkan pada waktu yang telah ditentukan serta menurut syarat-syarat yang telah ditetapkan. [Subulus Salaam juz 2, hal. 150]"],["p","Tegasnya : \"PUASA\", ialah : Menahan diri untuk tidak makan, minum, termasuk merokok dan bersetubuh dari mulai Fajar hingga terbenam matahari pada bulan Ramadlan karena mencari ridla Allah."],["h","2. Hukum Ash-Shiyam (Puasa)"],["p","Wajib 'Ain, artinya setiap orang Islam yang telah baligh (dewasa) dan sehat akalnya serta tidak ada sebab-sebab yang dibenarkan agama untuk tidak berpuasa, maka mereka itu wajib melakukannya, dan berdosa bagi yang meninggalkannya dengan sengaja. Firman Allah :"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِيْنَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُوْنَ (183) البقرة: 183"],["p","Hai orang-orang yang beriman, diwajibkan atas kamu berpuasa sebagaimana diwajibkan atas orang-orang sebelum kamu agar kamu bertaqwa. [QS. Al-Baqarah : 183]"],["p","Dan hadits-hadits Rasulullah SAW :"],["a","بُنِيَ الْاِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ اَنْ لَا اِلٰهَ اِلَّا اللهُ وَاَنَّ مُحَمَّدًا رَسُوْلُ اللهِ وَاِقَامِ الصَّلَاةِ وَاِيْتَاءِ الزَّكَاةِ وَصِيَامِ رَمَضَانَ وَحَجِّ الْبَيْتِ. البخارى و مسلم"],["p","Islam didirikan atas lima sendi, yaitu 1. Mengakui bahwa tak ada Tuhan melainkan Allah dan bahwasanya Muhammad pesuruh Allah, 2. Mendirikan Shalat, 3. Menunaikan zakat, 4. Berpuasa Ramadlan dan 5. Berhajji. [HR. Bukhari dan Muslim]"],["a","اِنَّ رَجُلًا سَأَلَ النَّبِيَّ ﷺ فَقَالَ يَا رَسُوْلَ اللهِ، اَخْبِرْنِيْ عَمَّا فَرَضَ اللهُ عَلَيَّ مِنَ الصِّيَامِ! قَالَ:شَهْرُ رَمَضَانَ. قَالَ: هَلْ عَلَيَّ غَيْرُهُ ؟ قَالَ: لَا. اِلَّا اَنْ تَطَوَّعَ. متفق عليه عن طلحة بن عبيد الله"],["p","Sesungguhnya seorang laki-laki bertanya kepada Nabi SAW, \"Ya Rasulullah, saya mohon diterangkan tentang puasa yang diwajibkan oleh Allah kepada saya\". Nabi SAW menjawab, \"Puasa di bulan Ramadlan\". Orang itu bertanya pula, \"Adakah puasa yang lain yang diwajibkan atas diri saya ?\". Jawab Nabi SAW, \"Tidak, kecuali bila engkau hendak mengerjakan tathawwu' (puasa sunnah). [HR. Muttafaq 'Alaih dari Thalhah bin 'Ubaidillah]"],["h","3. Yang wajib berpuasa"],["p","Ketentuan-ketentuan orang yang berkewajiban menjalankan puasa di bulan Ramadlan :"],["p","a. Orang Islam, tidak diwajibkan selain orang Islam."],["p","b. 'Aqil baligh (dewasa), bukan anak-anak."],["p","c. Sehat."],["p","d. Muqim (berada di daerah tempat tinggalnya/daerah iqomahnya), bukan sebagai musafir."],["p","e. Kuat, yakni tidak memaksakan diri karena sangat berat dan payah bila berpuasa."],["p","f. Khusus bagi wanita pada waktu suci, artinya tidak sedang haidl atau nifas."],["h","4. Yang membatalkan puasa"],["p","Sepanjang tuntunan Allah dan Rasul-Nya hal-hal yang membatalkan puasa adalah sebagai berikut :"],["p","Firman Allah SWT dalam surat Al-Baqarah ayat 187,"],["a","اُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ اِلٰى نِسَاۤىِٕكُمْ ۗ هُنَّ لِبَاسٌ لَّكُمْ وَاَنْتُمْ لِبَاسٌ لَّهُنَّ ۗ عَلِمَ اللّٰهُ اَنَّكُمْ كُنْتُمْ تَخْتَانُوْنَ اَنْفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنْكُمْ ۚ فَالْـٰٔنَ بَاشِرُوْهُنَّ وَابْتَغُوْا مَا كَتَبَ اللّٰهُ لَكُمْ ۗ وَكُلُوْا وَاشْرَبُوْا حَتّٰى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْاَبْيَضُ مِنَ الْخَيْطِ الْاَسْوَدِ مِنَ الْفَجْرِۖ ثُمَّ اَتِمُّوا الصِّيَامَ اِلَى الَّيْلِۚ ...(187) البقرة: 187"],["p","Dihalalkan bagi kamu pada malam hari puasa bercampur dengan isteri-isteri kamu; mereka itu pakaian bagimu, dan kamupun pakaian bagi mereka. Allah mengetahui bahwasanya kamu tidak dapat menahan nafsumu, karena itu Allah mengampuni kamu dan memberi keringanan kepadamu. Maka sekarang campurilah mereka dan carilah apa yang telah ditetapkan Allah untukmu, dan makan minumlah hingga terang bagimu benang putih dari benang hitam, yaitu Fajar. Kemudian sempurnakanlah puasa itu sampai malam ..... . [QS. Al-Baqarah: 187]"],["p","Dari ayat tersebut dapat diambil pengertian bahwa yang membatalkan puasa itu ialah :"],["p","a. Bersetubuh suami-isteri dengan sengaja dan dilakukan pada saat puasa (dari mulai masuk waktu Shubuh hingga masuk waktu Maghrib), padahal mereka termasuk orang yang berkewajiban puasa."],["p","Dan yang dimaksud dengan \"bersetubuh\", ialah masuknya kemaluan laki-laki/suami pada kemaluan wanita/istri. Jadi baik mengeluarkan mani maupun tidak, hukumnya tetap sama. Karena tidak adanya ayat-ayat lain maupun hadits-hadits yang membatasi, bahwa yang dimaksud \"bersetubuh\" adalah yang mengeluarkan mani, maka ayat itu tetap berlaku sesuai dengan keumuman lafadhnya."],["p","b. Makan dengan sengaja, baik makanan yang mengenyangkan atau tidak."],["p","c. Minum, baik yang menghilangkan haus atau tidak, termasuk merokok."],["p","5. Yang boleh tidak berpuasa dan wajib mengganti di hari-hari yang lain :"],["p","a. Orang yang sakit, yang apabila ia tetap berpuasa akan menambah berat atau akan memperlambat kesembuhan sakitnya, sedang sakitnya itu dapat diharapkan kesembuhannya (bukan sakit yang menahun atau sakit yang kronis dan terus-menerus sehingga sulit diharapkan kesembuhannya)."],["p","b. Musafir, ialah : Orang yang sedang bepergian keluar dari daerah iqomahnya, baik dengan perjalanan yang berat dan sukar maupun dengan ringan dan mudah; kesemuanya diperbolehkan untuk tidak berpuasa, tetapi berkewajiban mengganti di hari yang lain. Berdasarkan firman Allah :"],["a","فَمَنْ كَانَ مِنْكُمْ مَّرِيْضًا اَوْ عَلٰى سَفَرٍ فَعِدَّةٌ مِّنْ اَيَّامٍ اُخَرَ ۗ .البقرة: 184"],["p","Dan barangsiapa diantara kamu yang sakit atau dalam bepergian (musafir) ~maka bolehlah ia berbuka~ dan mengganti di hari-hari yang lain (sebanyak yang ditinggalkannya). [QS. Al-Baqarah : 184]."],["a","وَمَنْ كَانَ مَرِيْضًا اَوْ عَلٰى سَفَرٍ فَعِدَّةٌ مِّنْ اَيَّامٍ اُخَرَ. البقرة: 185"],["p","Dan barangsiapa yang sakit atau dalam bepergian (musafir) ~maka bolehlah ia berbuka~ dan mengganti di hari-hari yang lain (sebanyak yang ditinggalkannya). [QS. Al-Baqarah : 185]."],["p","Keterangan :"],["p","Tentang berapa kilometer jauhnya seseorang disebut sebagai musafir itu tidak ada penjelasan yang tegas dari Nabi SAW, namun yang jelas beliau bepergian dari Madinah ke Makkah, ketika baru sampai di Dzul Hulaifah beliau sudah mengqashar shalat, sedangkan jarak dari Madinah sampai Dzul Hulaifah itu kira-kira 6 mil (kira-kira 12 km)"],["h","6. Batas waktu mengganti"],["p","Tidak ada ketentuan dalam agama tentang batas waktu mengganti puasa yang ditinggalkan. Dapat dilaksanakan pada bulan-bulan sesudah selesai Ramadlan tahun itu atau bulan-bulan sesudah Ramadlan tahun berikutnya."],["p","Tegasnya selama ia masih hidup, kapanpun boleh, tanpa menambah fidyah atau melipat gandakan puasanya (misalnya hutang satu hari diganti dua hari dan sebagainya). Hanya sebaiknya segera diganti."],["p","7. Yang boleh tidak berpuasa dan hanya mengganti fidyah tanpa harus mengganti puasa di hari yang lain."],["p","Yaitu : Orang-orang yang bila dipaksakan untuk berpuasa masih dapat, tetapi sungguh amat payah sekali dalam melaksanakannya. Perhatikan Firman Allah:"],["a","وَعَلَى الَّذِيْنَ يُطِيْقُوْنَهٗ فِدْيَةٌ طَعَامُ مِسْكِيْنٍ ... البقرة: 184"],["p","Dan terhadap orang-orang yang bisa berpuasa tetapi dengan susah payah (boleh tidak berpuasa), wajib membayar fidyah (yaitu) memberi makan orang miskin….. [QS. Al-Baqarah : 184]"],["p","Ayat tersebut umum, maka siapa saja yang walaupun mampu berpuasa tetapi dengan amat payah (rekoso) dalam menjalankannya, maka termasuk yang dimaksud oleh ayat di atas, misalnya :"],["p","a. Wanita yang sedang hamil yang bila berpuasa dikhawatirkan akan menimbulkan gangguan pada dirinya dan/atau anak yang dikandungnya."],["p","b. Wanita yang sedang menyusui, baik anaknya sendiri maupun anak orang lain yang diserahkan kepadanya untuk disusui, yang bila dipaksakan untuk berpuasa akan sangat berat bagi dirinya dan/atau bagi anak yang sedang disusuinya itu. Rasulullah SAW bersabda :"],["a","اِنَّ اللهَ وَضَعَ عَنِ الْمُسَافِرِ الصَّوْمَ وَشَطْرَ الصَّلَاةِ وَعَنِ الْحُبْلَى وَالْمُرْضِعِ الصَّوْمَ. احمد عن انس بن مالك الكعبى"],["p","Sesungguhnya Allah SWT telah membolehkan bagi musafir meninggalkan puasa dan mengqashar shalat, dan Allah telah membolehkan perempuan hamil dan yang sedang menyusui meninggalkan puasa. [HR. Ahmad dari Anas bin Malik Al-Ka'biy]."],["p","Dan riwayat dari Ibnu Abbas RA. tentang istrinya yang sedang hamil, katanya:"],["a","اَنْتِ بِـمَنْزِلَةِ الَّذِيْ لَا يُطِيْقُهُ فَعَلَيْكِ الْفِدَاءُ وَلَا قَضَاءَ عَلَيْكِ. البزار وصححه الدارقطنى"],["p","Engkau sekedudukan dengan orang yang amat payah untuk berpuasa. Maka wajib atasmu fidyah dan tidak ada qadla' bagimu. [HR. Al-Bazzar dan dishahihkan oleh Ad-Daraquthni]"],["p","Serta riwayat dari Ibnu 'Umar ketika beliau ditanya oleh seorang wanita Quraisy yang sedang hamil tentang hal puasanya, maka jawab beliau :"],["a","اَفْطِرِيْ وَاَطْعِمِيْ كُلَّ يَوْمٍ مِسْكِيْنًا وَلَا تَقْضِيْ. ابن حزم"],["p","Berbukalah kamu dan berilah makan tiap hari seorang miskin, dan jangan mengqadla'nya. [HR. Ibnu Hazm]."],["p","c. Orang yang lanjut usia/orang tua yang apabila berpuasa akan sangat memayahkannya. Berdasar keumuman ayat (Surat Al-Baqarah ayat 184) dan riwayat dari Ibnu ‘Abbas sebagai berikut :"],["a","رُخِّصَ لِلشَّيْخِ الْكَبِيْرِ اَنْ يُفْطِرَ وَيُطْعِمَ وَلَا قَضَاءَ عَلَيْهِ. الدارقطنى والحاكم"],["p","Orang yang sangat tua, dibenarkan untuk berbuka dan wajib memberikan (fidyah) serta tidak ada qadla' atasnya. [HR. Ad-Daraquthni dan Al-Hakim]."],["p","d. Orang yang pekerjaannya sangat berat, yang bila tetap berpuasa walaupun ia kuat akan sangat berat dan memayahkannya. Misalnya : Pengemudi becak, pekerja tambang, karyawan-karyawan pengangkat barang di stasiun, terminal, pelabuhan dan sebagainya."],["p","e. Orang yang sakit menahun yang (menurut ahli kesehatan) sulit diharapkan sembuhnya, atau walaupun sembuh tetapi memakan waktu yang lama sekali."],["p","f. Siapa saja yang karena kondisi badannya atau sebab-sebab lain akan amat berat bila berpuasa, walaupun bila dipaksa kuat juga."],["p","Untuk nomor d), e) dan f), ini pun dasarnya adalah keumuman lafadh dari ayat 184 surat Al-Baqarah diatas."],["p","Semua yang tersebut diatas, boleh tidak berpuasa dan wajib membayar fidyah tanpa harus mengganti puasa di hari yang lain."],["p","8. Yang wajib untuk tidak berpuasa dan wajib mengganti dengan puasa di hari yang lain."],["p","Yaitu khusus bagi wanita yang sedang haidl atau nifas. Berdasar riwayat :"],["a","عَنْ عَائِشَةَ قَالَتْ: كُنَّا نَحِيْضُ عَلَى عَهْدِ رَسُوْلِ اللهِ ﷺ فَنُؤْمَرُ بِقَضَاءِ الصَّوْمِ وَلَا نُؤْمَرُ بِقَضَاءِ الصَّلَاةِ. الجماعة عن المعاذة"],["p","Dari 'Aisyah, ia berkata, \"Dahulu kami haidl dimasa Rasulullah SAW maka kami diperintahkan supaya mengqadla’ (mengganti) puasa dan kami tidak diperintahkan mengqadla’ shalat\". [HR. Al-Jama'ah dari Al-Mu'adzah]"],["a","عَنْ اَبِيْ سَعِيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ ﷺ: اَلَيْسَ اِذَا حَاضَتْ لَـمْ تُصَلِّ وَلَـمْ تَصُمْ؟ فَذٰلِكَ نُقْصَانُ دِيْنِهَا. البخارى 2: 239"],["p","Dari Abu Sa'id (Al-Khudriy) RA, ia berkata : Nabi SAW bersabda, \"Bukankah apabila seorang wanita itu haidl, ia tidak shalat dan tidak berpuasa ? Itulah dari kekurangan agamanya\". [HR. Bukhari juz 2, hal. 239]"],["h","1. Pengertian Sahur"],["p","Sahur, ialah makanan yang dimakan pada waktu sahar. Sahar menurut bahasa ialah \"Nama bagi akhir suku malam dan permulaan suku siang\". Lawannya ialah: Ashil, akhir suku siang."],["p","Menurut Az-Zamakhsyari, dinamai waktu Sahar dengan Sahar karena ia adalah waktu berlalunya malam dan datangnya siang."],["p","Dengan demikian, jelaslah bahwa Sahar bukanlah satu atau dua jam sebelum terbit fajar, namun yang dimaksud adalah nama waktu pergantian siang dan malam."],["p","Jadi apabila kita makan pada jam 24.00 (jam 12 malam) atau sedikit setelah itu tidaklah dapat dinamakan \"Bersahur (mengerjakan makan Sahur)\"."],["p","Adapun yang dinamakan makan Sahur adalah sebagaimana yang dilakukan Rasulullah SAW pada riwayat di bawah ini :"],["a","عَنْ اَنَسٍ عَنْ زَيْدِ بْنِ ثَابِتٍ قَالَ: تَسَحَّرْنَا مَعَ رَسُوْلِ اللهِ ﷺ: ثُـمَّ قُمْنَا اِلىَ الصَّلَاةِ. قُلْتُ: كَمْ كَانَ قَدْرُ مَا بَيْنَهُمَا ؟ قَالَ: قَدْرَ خَمْسِيْنَ اٰيَةً. احمد و البخارى و مسلم"],["p","Dari Anas dari Zaid bin Tsabit, ia berkata, \"Kami pernah bersahur bersama Rasulullah SAW kemudian kami mengerjakan shalat (Shubuh)\". Aku (Anas) bertanya kepada Zaid. \"Berapa tempo antara keduanya ?\". Zaid menjawab, \"Sekadar membaca 50 ayat Al-Qur'an\". [HR. Ahmad, Bukhari dan Muslim]."],["h","2. Hikmah Sahur"],["p","Diriwayatkan oleh Ahmad dari Abu Sa'id bahwa Nabi SAW bersabda :"],["a","اَلسَّحُوْرُ اَكْلُهُ بَرَكَةٌ فَلَا تَدَعُوْهُ وَلَوْ اَنْ يَجْرَعَ اَحَدُكُمْ جَرْعَةً مِنْ مَاءٍ فَاِنَّ اللهَ وَمَلَائِكَتَهُ يُصَلُّوْنَ عَلَى الْمُتَسَحِّرِيْنَ. احمد"],["p","Sahur itu suatu berkah. Maka janganlah kalian meninggalkannya, walaupun hanya dengan meneguk seteguk air, karena sesungguhnya Allah dan para malaikat-Nya bershalawat atas orang-orang yang bersahur. [HR. Ahmad]"],["p","Diriwayatkan oleh Muslim dari 'Amr bin 'Ash bahwa Rasulullah SAW bersabda:"],["a","فَصْلُ مَابَيْنَ صِيَامِنَا وَصِيَامِ اَهْلِ الْكِتَابِ اَكْلَةُ السَّحَرِ. مسلم"],["p","Yang membedakan antara puasa kita dengan puasa ahli kitab ialah makan sahur. [HR. Muslim]."],["h","3. Keraguan tentang waktu Sahur"],["p","Bila seseorang ragu apakah telah habis waktu sahur ataukah belum, maka ia diperbolehkan makan dan minum hingga nyata-nyata baginya bahwa waktu sahur telah habis dan masuk waktu Shubuh. Firman Allah :"],["a","وَكُلُوْا وَاشْرَبُوْا حَتّٰى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْاَبْيَضُ مِنَ الْخَيْطِ الْاَسْوَدِ مِنَ الْفَجْرِ. البقرة: 187."],["p","Dan makanlah, minumlah, sehingga nyata kepadamu benang putih dari pada benang hitam yaitu Fajar. [QS. Al Baqarah : 187]"],["p","Dari ayat di atas jelaslah bahwa Allah memperkenankan makan dan minum, sehingga nyata benar terbitnya Fajar."],["h","4. Adab Berbuka"],["p","Apabila sudah tiba waktunya dianjurkan untuk segera berbuka :"],["a","عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: لَا يَزَالُ النَّاسُ بِخَيْرٍ مَا عَجَّلُوا الْفِطْرَ. مسلم 2: 771"],["p","Dari Sahl bin Sa'ad RA. bahwasanya Rasulullah SAW bersabda, \"Senantiasalah hamba itu dalam kebaikan apabila mereka menyegerakan berbuka\". [HR. Muslim juz 2, hal. 771, no. 48]."],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: قَالَ اللهُ عَزَّ وَجَلَّ: اَحَبُّ عِبَادِيْ اِلَيَّ اَعْجَلُهُمْ فِطْرًا. الترمذى 2: 103، رقم: 696"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda : Allah 'Azza wa Jalla berfirman, \"Yang paling Ku-sayangi dari hamba-hamba-Ku ialah yang paling segera berbuka\". [HR. Tirmidzi juz 2, hal. 103, no. 696]"],["p","Diriwayatkan oleh Ibnu Abdil Barr dari Anas bin Malik, katanya :"],["a","مَا رَأَيْتُ رَسُوْلَ اللهِ ﷺ قَطُّ صَلَّى صَلَاةَ الْمَغْرِبِ حَتَّى يُفْطِرَ وَلَوْ عَلَى شَرْبَةِ مَاءٍ. ابن عبد البر عن انس بن مالك"],["p","Tidak pernah aku melihat walau sekali Rasulullah SAW shalat Maghrib lebih dahulu sebelum berbuka, walaupun hanya dengan seteguk air. [HR. Ibnu ‘Abdil Barr dari Anas bin Malik]"],["p","Diriwayatkan oleh Abu Dawud, Ahmad dan Tirmidzi dari Anas, sbb :"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ يُفْطِرُ عَلَى رُطَبَاتٍ قَبْلَ اَنْ يُصَلِّىَ فَاِنْ لَـمْ تَكُنْ رُطَبَاتٌ فَعَلَى تَـمَرَاتٍ فَاِنْ لَـمْ تَكُنْ حَسَا حَسَوَاتٍ مِنْ مَاءٍ. ابوداود و احمد و الترمذى"],["p","Dari Anas bin Maalik, ia berkata : Dahulu Rasulullah SAW berbuka dengan kurma basah sebelum shalat (Maghrib), jika tidak ada kurma basah, maka beliau berbuka dengan kurma kering, dan jika tak ada kurma kering, beliau menyendok beberapa sendok air. [HR. Abu Dawud, Ahmad dan Tirmidzi]"],["a","كَانَ رَسُوْلُ اللهِ ﷺ يُحِبُّ اَنْ يُفْطِرَ عَلَى ثَلَاثِ تَـمَرَاتٍ اَوْ شَىْءٍ لَـمْ تُصِبْهُ النَّارُ. ابو يعلى عن انس"],["p","Dahulu Rasulullah SAW suka berbuka puasa dengan tiga biji kurma atau sesuatu yang tidak dimasak dengan api. [HR. Abu Ya'la dari Anas]"],["p","Rasulullah SAW bersabda :"],["a","اِذَا اَفْطَرَ اَحَدُكُمْ فَلْيُفْطِرْ عَلَى تَـمْرٍ، فَاِنْ لَـمْ يَجِدْ فَلْيُفْطِرْ عَلَى مَاءٍ فَاِنَّهُ طَهُوْرٌ. ابو داود و الترمذى عن سليمان بن عامر"],["p","Apabila seseorang diantara kalian berbuka, maka hendaklah ia berbuka dengan korma. Jika ia tidak memperoleh korma, hendaklah ia berbuka dengan air, karena air itu bersih dan membersihkan. [HR. Abu Dawud dan At-Tirmidzi dari Sulaiman bin 'Amir]"],["p","Kesimpulan :"],["p","Hadits-hadits di atas menerangkan kepada kita, bahwa apabila kita berbuka puasa maka disunnahkan untuk :"],["p","1. Menyegerakan berbuka."],["p","2. Sebelum shalat Maghrib kita berbuka dahulu walaupun dengan seteguk air."],["p","3. Berbuka dengan tiga biji korma, bila tidak ada, dengan sesuatu makanan yang manis dan tidak dimasak dengan api. Seperti : pisang, kates, nanas dan lain-lain."],["p","4. Bila tidak ada buah-buahan maka disunnahkan kita untuk berbuka dengan air."],["p","5. Dan dikala berbuka dituntunkan untuk membaca do'a sebagai berikut :"],["a","ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوْقُ وَثَبَتَ الْاَجْرُ اِنْ شَاءَ اللهُ. ابو داود 2: 306، رقم: 2357، عن ابن عمر"],["p","Haus telah hilang, urat-urat telah basah dan semoga pahala tetap didapatkan. Insya Allah. [HR. Abu Dawud juz 2, hal. 306, no. 2357, dari Ibnu Umar]"],["p","Tentang doa berbuka puasa"],["p","Ada bermacam-macam doa berbuka puasa, diantaranya sebagai berikut :"],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: كَانَ النَّبِيُّ ﷺ اِذَا اَفْطَرَ قَالَ: اَللّٰهُمَّ لَكَ صُمْنَا وَعَلَى رِزْقِكَ اَفْطَرْنَا فَتَقَبَّلْ مِنَّا اِنَّكَ اَنْتَ السَّمِيْعُ اْلعَلِيْمُ. الدارقطنى 2: 185، رقم 26، ضعيف لان فى اسناده عبد الملك بن هارون بن عنترة."],["p","Dari Ibnu ‘Abbas, ia berkata : Adalah Nabi SAW apabila berbuka puasa beliau berdoa, “Alloohumma laka shumnaa wa ‘alaa rizqika afthornaa fataqobbal minnaa innaka antas samii’ul ‘aliim (Ya Allah, untuk-Mu kami berpuasa, dan atas rizqi-Mu kami berbuka, maka terimalah (ibadah) dari kami, sesungguhnya Engkau Maha Mendengar lagi Maha Mengetahui)”. [HR. Daraquthni juz 2, hal. 185 no. 26, dlaif karena dalam sanadnya ada perawi bernama ‘Abdul Malik bin Harun bin ‘Antarah]"],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: كَانَ النَّبِيُّ ﷺ اِذَا اَفْطَرَ قَالَ: لَكَ صُمْتُ وَعَلَى رِزْقِكَ اَفْطَرْتُ فَتَقَبَّلْ مِنِّيْ اِنَّكَ اَنْتَ السَّمِيْعُ الْعَلِيْمُ. الطبرانى فى الكبير 12: 113، رقم: 12720، فيه عبد الملك بن هارون بن عنترة و هو ضعيف"],["p","Dari Ibnu ‘Abbas, ia berkata : Adalah Nabi SAW apabila berbuka puasa beliau berdoa, “Laka shumtu wa ‘alaa rizqika afthartu fataqabbal minnii innaka antas samii’ul ‘aliim (Untuk-Mu aku berpuasa, dan atas rizqi-Mu aku berbuka, maka terimalah ibadahku, sesungguhnya Engkau Maha Mendengar lagi Maha Mengetahui)”. [HR. Thabarani dalam Al-Kabir juz 12, hal. 113, no. 12720, dalam sanadnya ada perawi bernama ‘Abdul Malik bin Harun bin ‘Antarah, ia dlaif]"],["a","بِسْمِ اللهِ، اَللّٰهُمَّ لَكَ صُمْتُ وَعَلَى رِزْقِكَ اَفْطَرْتُ. الطبرانى فى الاوسط رقم: 7547، و فيه داود بن الزبرقان و هو ضعيف - مجمع الزوائد"],["p","Bismillaah, Alloohumma laka shumtu wa ‘alaa rizqika afthortu (Dengan nama Allah. Ya Allah, untuk-Mu aku berpuasa dan dengan rizqi-Mu aku berbuka). [HR. Thabarani, dalam Al-Ausath hadits no. 7547, dalam sanadnya ada perawi bernama Dawud bin Zabraqan, ia dlaif – Majma’uz Zawaaid juz 3, hal. 279]"],["a","عَنْ مُعَاذٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ اِذَا اَفْطَرَ قَالَ: اَلْحَمْدُ لِلّٰهِ الَّذِيْ اَعَانَنِيْ فَصُمْتُ وَرَزَقَنِيْ فَاَفْطَرْتُ. ابن السنى ص 169، رقم 479، اسناده ضعيف فيه رجل لم يسمَّ"],["p","Dari Mu’adz RA, ia berkata : Adalah Rasulullah SAW apabila berbuka puasa beliau berdoa, “Alhamdu lillaahil-ladzii a’aananii fa shumtu wa rozaqonii fa-afthortu (Segala puji bagi Allah yang telah menolongku, sehingga aku berpuasa dan telah memberi rizqi kepadaku, maka aku berbuka)”. [HR. Ibnu Sunni hal. 169, no. 479, sanadnya dlaif, karena di dalamnya ada perawi yang tidak disebutkan namanya]"],["a","عَنْ مُعَاذِ بْنِ زُهْرَةَ اَنَّهُ بَلَغَهُ اَنَّ النَّبِيَّ ﷺ كَانَ اِذَا اَفْطَرَ قَالَ: اَللّٰهُمَّ لَكَ صُمْتُ وَعَلَى رِزْقِكَ اَفْطَرْتُ. ابو داود 2: 306، رقم 2358، مرسل لان معاذ بن زهرة لم يدرك النبي ﷺ"],["p","Dari Mu’adz bin Zuhrah, bahwasanya telah sampai kepadanya bahwa Nabi SAW apabila berbuka puasa beliau berdoa, “Alloohumma laka shumtu wa ‘alaa rizqika afthortu (Ya Allah, untuk-Mu aku berpuasa, dan dengan rizqi-Mu aku berbuka puasa)”. [HR. Abu Dawud juz 2,hal. 306, no. 2358, hadits tersebut mursal, karena Mu’adz bin Zuhrah tidak bertemu Nabi SAW]"],["a","عَنِ ابْنِ اَبِيْ مُلَيْكَةَ قَالَ: سَمِعْتُ عَبْدَ اللهِ بْنَ عَمْرِو بْنِ الْعَاصِ يَقُوْلُ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: اِنَّ لِلصَّائِمِ عِنْدَ فِطْرِهِ لَدَعْوَةٌ مَا تُرَدُّ، قَالَ ابْنُ اَبِيْ مُلَيْكَةَ: سَمِعْتُ عَبْدَ اللهِ بْنَ عَمْرٍو يَقُوْلُ اِذَا اَفْطَرَ: اَللّٰهُمَّ اِنِّيْ اَسْأَلُكَ بِرَحْمَتِكَ الَّتِى وَسِعَتْ كُلَّ شَيْءٍ اَنْ تَغْفِرَ لِيْ. ابن ماجه 1: 557، رقم 1753 حسن"],["p","Dari Ibnu Abi Mulaikah, ia berkata : Saya mendengar ‘Abdullah bin ‘Amr bin Al-‘Ash berkata : Aku mendengar Rasulullah SAW bersabda, “Sesungguhnya bagi orang yang berpuasa itu ketika berbuka ada doa yang tidak akan ditolak”. Ibnu Abi Mulaikah berkata : Aku mendengar ‘Abdullah bin ‘Amr apabila berbuka puasa berdoa, “Alloohumma innii as-aluka birohmatikal-latii wasi’at kulla syai-in an taghfiro lii (Ya Allah, sesungguhnya aku memohon kepada-Mu dengan rohmat-Mu yang luas meliputi segala sesuatu agar Engkau mengampuni aku)”. [HR. Ibnu Majah juz 1, hal. 557, no. 1753, hadits hasan]"],["a","عَنْ مَرْوَانَ يَعْنِى ابْنَ سَالِمِ الْمُقَفَّعِ قَالَ: رَأَيْتُ ابْنَ عُمَرَ يَقْبِضُ عَلَى لِحْيَتِهِ فَيَقْطَعُ مَا زَادَ عَلَى الْكَفِّ وَقَالَ: كَانَ رَسُوْلُ اللهِ ﷺ اِذَا اَفْطَرَ قَالَ: ذَهَبَ الظَّمَأُ وَابْتَلَّتِ اْلعُرُوْقُ وَثَبَتَ اْلاَجْرُ اِنْ شَاءَ اللهُ. ابو داود 2: 306، رقم 2357، حسن"],["p","Dari Marwan, yakni bin Salim Al-Muqaffa’, ia berkata : Aku melihat Ibnu ‘Umar memegang jenggotnya, lalu memotong yang lebih dari genggaman tangannya. Ia berkata : Adalah Rasulullah SAW apabila berbuka puasa beliau berdoa, “Dzahabadh-dhoma-u wabtallatil ‘uruuqu wa tsabatal ajru, insyaa-allooh (Haus telah hilang, urat-urat telah basah dan semoga pahala tetap didapat, insyaa-allooh). [HR. Abu Dawud juz 2, hal. 306, no. 2357, hadits hasan]"],["p","Keterangan :"],["p","Dari riwayat-riwayat di atas bisa kita ketahui bahwa yang derajatnya hasan adalah riwayat Ibnu Majah dari Ibnu Abi Mulaikah dan riwayat Abu Dawud dari Marwan bin Salim. Namun pada riwayat Ibnu Abi Mulaikah di atas, doa tersebut adalah lafadhnya Ibnu ‘Amr. Adapun pada riwayat Abu Dawud tersebut lafadh doa itu dari Nabi SAW. Dengan demikian kita ketahui bahwa doa berbuka puasa yang paling kuat riwayatnya adalah yang diriwayatkan Abu Dawud dari Marwan bin Salim dari Ibnu ‘Umar (Dzahabadh-dhoma-u wabtallatil ‘uruuqu wa tsabatal ajru, insyaa-allooh)."],["p","~oO[ @ ]Oo~"]],"c20220403_1279":[["p","Ahad, 3 April 2022/1 Ramadlan1443 Brosur No. : 2074/2114/IF"],["h","SHALATUL LAIL"],["p","Shalat Sunnah Lail ialah : Shalat-shalat Sunnah yang dikerjakan pada malam hari selain Ba'diyah 'Isya'."],["p","Adapun waktunya ialah : Sehabis shalat 'Isya' hingga akhir waktu 'Isya' sebelum masuk waktu Shubuh. Dan shalat Lail itu boleh dikerjakan sebelum maupun sesudah tidur."],["p","Macam-macamnya :"],["p","A. Shalat Sunnah Tarawih. C. Shalat Sunnah Witir."],["p","B. Shalat Sunnah Tahajjud. D. Shalat Sunnah Iftitah."],["h","A. Shalat Tarawih"],["p","Tarawih artinya relax, santai, istirahat."],["p","Ulama mengistilahkan Shalat Sunnah ini dengan Shalat Tarawih, karena melihat riwayat yang menjelaskan tentang bagaimana cara Nabi SAW melakukannya. Yaitu dengan perlahan-lahan/relax/santai serta diselingi dengan istirahat setiap habis salam, sebagaimana riwayat dibawah ini:"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُوْلُ اللهِ ﷺ يُصَلِّى اَرْبَعَ رَكَعَاتٍ فِى اللَّيْلِ ثُـمَّ يَتَرَوَّحُ فَاَطَالَ حَتَّى رَحِمْتُهُ. فَقُلْتُ: بِاَبِيْ اَنْتَ وَاُمِّيْ يَارَسُوْلَ اللّٰهِ، قَدْ غَفَرَ اللّٰهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ. قَالَ: اَفَلَا اَكُوْنُ عَبْدًا شَكُوْرًا؟. البيهقى 2: 497"],["p","Dari ‘Aisyah RA, ia berkata : Dahulu Rasulullah SAW shalat 4 rekaat di malam hari. Kemudian beliau beristirahat/bertarawih lama sekali, sehingga aku merasa kasihan kepadanya. Lalu aku berkata, “Kutebusi engkau dengan ayah dan ibuku ya Rasulullah, sungguh Allah telah mengampuni engkau dari dosa-dosa yang telah lalu dan yang kemudian”. Rasulullah SAW bersabda, “Apakah aku tidak senang kalau aku menjadi hamba yang bersyukur ?”. [HR. Baihaqi juz 2, hal. 497]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: مَنْ قَامَ رَمَضَانَ اِيْـمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ. البخارى 2: 251"],["p","Dari Abu Hurairah RA, bahwasanya Rasulullah SAW bersabda, “Barangsiapa bangun (shalat malam) pada bulan Ramadlan karena iman dan mengharap pahala dari Allah, maka diampuni dosa-dosanya yang telah lalu”. [HR. Bukhari 2 : 251]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ يُرَغِّبُ فِيْ قِيَامِ رَمَضَانَ مِنْ غَيْرِ اَنْ يَأْمُرَهُمْ فِيْهِ بِعَزِيْـمَةٍ، فَيَقُوْلُ: مَنْ قَامَ رَمَضَانَ اِيْـمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ. فَتُوُفِّيَ رَسُوْلُ اللهِ ﷺ وَالْاَمْرُ عَلَى ذٰلِكَ، ثُـمَّ كَانَ الْاَمْرُ عَلَى ذٰلِكَ فِيْ خِلَافَةِ اَبِيْ بَكْرٍ وَصَدْرًا مِنْ خِلَافَةِ عُمَرَ عَلَى ذٰلِكَ. مسلم 1: 523 رقم 174"],["p","Dari Abu Hurairah, ia berkata : Dahulu Rasulullah SAW menganjurkan supaya shalat malam pada bulan Ramadlan, tetapi beliau tidak mewajibkannya, beliau bersabda, “Barangsiapa shalat malam di bulan Ramadlan karena iman dan mengharap pahala dari Allah, maka diampuni dosa-dosanya yang telah lalu”. Ketika Rasulullah SAW wafat, keadaannya seperti itu, begitu pula pada masa khalifah Abu Bakar, dan begitu pula pada masa permulaan khalifah ‘Umar. [HR. Muslim juz 1, hal. 523, no. 174]"],["a","عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ اَنَّ عَائِشَةَ اَخْبَرَتْهُ اَنَّ رَسُوْلَ اللهِ ﷺ خَرَجَ مِنْ جَوْفِ اللَّيْلِ فَصَلَّى فِى الْمَسْجِدِ، فَصَلَّى رِجَالٌ بِصَلَاتِهِ. فَاَصْبَحَ النَّاسُ يَتَحَدَّثُوْنَ بِذٰلِكَ، فَاجْتَمَعَ اَكْثَرُ مِنْهُمْ. فَخَرَجَ رَسُوْلُ اللهِ ﷺ فِى اللَّيْلَةِ الثَّانِيَةِ فَصَلَّوْا بِصَلَاتِهِ. فَاَصْبَحَ النَّاسُ يَذْكُرُوْنَ ذٰلِكَ، فَكَثُرَ اَهْلُ الْمَسْجِدِ مِنَ اللَّيْلَةِ الثَّالِثَةِ. فَخَرَجَ فَصَلَّوْا بِصَلَاتِهِ. فَلَمَّا كَانَتِ اللَّيْلَةُ الرَّابِعَةُ عَجَزَ الْمَسْجِدُ عَنْ اَهْلِهِ، فَلَمْ يَخْرُجْ اِلَيْهِمْ رَسُوْلُ اللهِ ﷺ فَطَفِقَ رِجَالٌ مِنْهُمْ يَقُوْلُوْنَ: اَلصَّلَاةَ. فَلَمْ يَخْرُجْ اِلَيْهِمْ رَسُوْلُ اللهِ ﷺ حَتَّى خَرَجَ لِصَلَاةِ الْفَجْرِ. فَلَمَّا قَضَى الْفَجْرَ اَقْبَلَ عَلَى النَّاسِ ثُـمَّ تَشَهَّدَ، فَقَالَ: اَمَّا بَعْدُ، فَاِنَّهُ لَـمْ يَخْفَ عَلَىَّ شَأْنُكُمُ اللَّيْلَةَ، وَلٰكِنِّيْ خَشِيْتُ اَنْ تُفْرَضَ عَلَيْكُمْ صَلَاةُ اللَّيْلِ، فَتَعْجِزُوْا عَنْهَا. مسلم 1: 524 رقم 178"],["p","Dari ‘Urwah bin Zubair, bahwasanya ‘Aisyah memberitahukan kepadanya, bahwa dahulu Rasulullah SAW pada tengah malam keluar ke masjid untuk shalat malam, lalu orang-orang ikut shalat bersama beliau. Di pagi harinya orang-orang yang ikut shalat itu bercerita kepada yang lain, Pada malam kedua, orang-orang yang berkumpul di masjid bertambah banyak. Kemudian Rasulullah SAW keluar ke masjid pada malam yang kedua, dan mereka ikut shalat bersama beliau. Di pagi harinya, orang-orang yang ikut shalat tersebut bercerita kepada yang lain. Maka pada malam yang ketiga, orang-orang yang berkumpul di masjid lebih banyak lagi. Kemudian Rasulullah SAW keluar ke masjid, dan orang-orang pun ikut shalat bersama beliau. Setelah malam keempat, yang datang ke masjid meluap, tetapi Rasulullah SAW tidak keluar ke masjid. Kemudian orang-orang berkata, “Mari shalat !”. Tetapi Rasulullah SAW tidak keluar, hingga beliau keluar ke masjid untuk shalat Shubuh. Setelah selesai shalat Shubuh beliau menghadap ke orang banyak, lalu beliau memuji Allah dan bersyahadat, lalu bersabda, “Amma ba’du, sesungguhnya bukan aku tidak mengetahui keadaan kalian tadi malam, tetapi aku khawatir apabila shalat malam tersebut diwajibkan kepada kalian, sehingga memberatkan kepada kalian”. [HR. Muslim juz 1, hal. 524, no. 178]"],["p","Waktu, bilangan dan cara pelaksanaan shalat tarawih"],["p","a. Waktunya."],["p","Setiap malam pada bulan Ramadlan, boleh dikerjakan diawwal malam atau di pertengahan maupun di akhirnya, baik sebelum tidur maupun sesudah tidur. Tegasnya, shalat Tarawih adalah shalat malam di bulan Ramadlan."],["a","عَنْ اَبِيْ ذَرٍّ قَالَ: صُمْنَا مَعَ رَسُوْلِ اللهِ ﷺ رَمَضَانَ. فَلَمْ يَقُمْ بِنَا شَيْئًا مِنْهُ حَتَّى بَقِيَ سَبْعُ لَيَالٍ. فَقَامَ بِنَا لَيْلَةَ السَّابِعَةِ حَتَّى مَضَى نَحْوٌ مِنْ ثُلُثِ اللَّيْلِ. ثُـمَّ كَانَتِ اللَّيْلَةُ السَّادِسَةُ الَّتِيْ تَلِيْهَا فَلَمْ يَقُمْهَا حَتَّى كَانَتِ الْخَامِسَةُ الَّتِيْ تَلِيْهَا ، ثُـمَّ قَامَ بِنَا حَتَّى مَضَى نَحْوٌ مِنْ شَطْرِ اللَّيْلِ. فَقُلْتُ: يَا رَسُوْلَ اللهِ، لَوْ نَفَّلْتَنَا بَقِيَّةَ لَيْلَتِنَا هٰذِهِ؟ فَقَالَ: اِنَّهُ مَنْ قَامَ مَعَ الْاِمَامِ حَتَّى يَنْصَرِفَ فَاِنَّهُ يَعْدِلُ قِيَامَ لَيْلَةٍ. ثُـمَّ كَانَتِ الرَّابِعَةُ الَّتِيْ تَلِيْهَا فَلَمْ يَقُمْهَا حَتَّى كَانَتِ الثَّالِثَةُ الَّتِيْ تَلِيْهَا. قَالَ: فَجَمَعَ نِسَاءَهُ وَاَهْلَهُ وَاجْتَمَعَ النَّاسُ. قَالَ: فَقَامَ بِنَا حَتَّى خَشِيْنَا اَنْ يَفُوْتَنَا الْفَلَاحُ. قِيْلَ: وَمَا اَلْفَلَاحُ؟ قَالَ: اَلسَّحُوْرُ. قَالَ: ثُـمَّ لَـمْ يَقُمْ بِنَا شَيْئًا مِنْ بَقِيَّةِ الشَّهْرِ. ابن ماجه 1: 420، رقم: 1327"],["p","Dari Abu Dzarr, ia berkata :Kami berpuasa Ramadlan bersama Rasulullah SAW. Beliau tidak shalat (malam) bersama kami sehingga tinggal tujuh malam (dari bulan itu). Lalu pada malam ketujuh, beliau shalat malam bersama kami hingga kira-kira lewat sepertiga malam (baru selesai). Kemudian pada malam keenam yang tersisa beliau tidak shalat malam bersama kami. Sehingga pada malam kelima yang tersisa beliau shalat malam bersama kami, hingga kira-kira lewat tengah malam (baru selesai). Lalu aku (Abu Dzarr) berkata, “Ya Rasulullah, alangkah baiknya apabila malam yang tersisa ini engkau gunakan shalat malam bersama kami ?”. Maka beliau bersabda, “Barangsiapa yang shalat malam bersama imam hingga selesai, maka ia mendapatkan (pahala) seperti shalat malam semalam penuh”, Kemudian malam yang keempat yang tersisa, beliau tidak shalat malam bersama kami. Sehingga malam yang ketiga yang tersisa, (Abu Dzarr) berkata, “Beliau mengumpulkan istri-istri beliau dan keluarga beliau, dan orang-orang juga berkumpul”. (Abu Dzarr) berkata, “Maka beliau shalat malam bersama kami hingga akhir malam (baru selesai), sehingga kami khawatir kehilangan Al-Falaah”. Ditanyakan kepada Abu Dzarr, “Apakah Al-Falaah itu ?”. (Abu Dzarr) menjawab, “Makan sahur”. Kemudian beliau tidak shalat malam bersama kami pada malam yang tersisa dari bulan itu. [HR. Ibnu Majah juz 1, hal. 420, no. 1327]"],["a","عَنْ عَبْدِ الرَّحْمٰنِ بْنِ عَبْدِ اْلقَارِيِّ اَنَّهُ قَالَ: خَرَجْتُ مَعَ عُمَرَ ابْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ لَيْلَةً فِيْ رَمَضَانَ اِلىَ الْمَسْجِدِ فَاِذَا النَّاسُ اَوْزَاعٌ مُتَفَرِّقُوْنَ يُصَلِّى الرَّجُلُ لِنَفْسِهِ، وَيُصَلِّى الرَّجُلُ فَيُصَلِّيْ بِصَلَاتِهِ الرَّهْطُ. فَقَالَ عُمَرُ: اِنِّيْ اَرَى لَوْ جَمَعْتُ هٰؤُلَاءِ عَلَى قَارِئٍ وَاحِدٍ لَكَانَ اَمْثَلَ. ثُـمَّ عَزَمَ فَجَمَعَهُمْ عَلَى اُبَيِّ بْنِ كَعْبٍ. ثُـمَّ خَرَجْتُ مَعَهُ لَيْلَةً اُخْرَى وَالنَّاسُ يُصَلُّوْنَ بِصَلَاةِ قَارِئِهِمْ. قَالَ عُمَرُ: نِعْمَ اْلبِدْعَةُ هٰذِهِ. وَالَّتِيْ يَنَامُوْنَ عَنْهَا اَفْضَلُ مِنَ الَّتِيْ يَقُوْمُوْنَ يُرِيْدُ اٰخِرَ اللَّيْلِ. وَكَانَ النَّاسُ يَقُوْمُوْنَ اَوَّلَهُ. البخارى 2: 252"],["p","Dari Abdur Rahman bin Abdul Qariyyi, bahwasanya ia berkata, \"Saya pernah keluar ke masjid bersama ‘Umar bin Khaththab RA. pada suatu malam di bulan Ramadlan, tiba-tiba kami dapati orang-orang berkelompok-kelompok dan terpisah-pisah, ada yang shalat sendirian dan ada yang shalat dengan diikuti beberapa orang. Maka ‘Umar berkata, \"Saya berpendapat lebih baik mereka ini saya kumpulkan dengan diimami oleh seorang imam\". Kemudian ‘Umar ber'azam dan mengumpulkan mereka itu dengan diimami oleh Ubay bin Ka'ab. Kemudian saya keluar lagi bersama ‘Umar pada malam yang lain, sedang orang-orang shalat dengan bermakmum kepada imam mereka. ‘Umar berkata, \"Sebaik-baik bid'ah adalah ini\". Dan shalat yang mereka kerjakan pada akhir malam adalah lebih utama dari pada yang mereka kerjakan di awwal malam. Sedangkan orang-orang biasa mengerjakannya di awwal malam. [HR. Bukhari juz 2 : 252]."],["h","b. Bilangan raka'atnya"],["p","Shalat Sunnah Tarawih ini, bilangan raka'at yang biasa dikerjakan oleh Nabi SAW adalah sebelas raka'at beserta Witirnya. Dan sebanyak-banyaknya tak terbatas, berapa saja seseorang mampu melaksanakan-nya hingga habis waktu shalat sunnah tersebut, yaitu masuk waktu Shubuh."],["a","عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ ﷺ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُوْلُ اللهِ ﷺ يُصَلِّيْ فِيْمَا بَيْنَ اَنْ يَفْرُغَ مِنْ صَلَاةِ اْلعِشَاءِ وَهِيَ الَّتِيْ يَدْعُو النَّاسُ الْعَتَمَةَ اِلَى اْلفَجْرِ اِحْدَى عَشْرَةَ رَكْعَةً، يُسَلِّمُ بَيْنَ كُلِّ رَكْعَتَيْنِ، وَيُوْتِرُ بِوَاحِدَةٍ. مسلم 1: 508 رقم: 122"],["p","Dari 'Aisyah RA istri Nabi SAW, ia berkata, \"Dahulu Rasulullah SAW shalat antara beliau selesai dari shalat 'Isyak, yang orang-orang menyebutnya dengan shalat Al-‘Atamah hingga fajar, 11 rekaat. Beliau salam antara tiap-tiap 2 rekaat, lalu berwitir 1 rekaat\". [HR. Muslim juz 1, hal. 508, no. 122]."],["a","عَنْ اَبِيْ سَلَمَةَ بْنِ عَبْدِ الرَّحْمٰنِ اَنَّهُ سَأَلَ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: كَيْفَ كَانَتْ صَلَاةُ رَسُوْلِ اللهِ ﷺ فِيْ رَمَضَانَ؟ قَالَتْ: مَا كَانَ رَسُوْلُ اللهِ ﷺ يَزِيْدُ فِيْ رَمَضَانَ وَلَا فِيْ غَيْرِهِ عَلَى اِحْدَى عَشْرَةَ رَكْعَةً، يُصَلِّيْ اَرْبَعًا فَلَا تَسْأَلْ عَنْ حُسْنِهِنَّ وَطُوْلِـهِنَّ، ثُـمَّ يُصَلِّيْ اَرْبَعًا فَلَا تَسْأَلْ عَنْ حُسْنِهِنَّ وَطُوْلِـهِنَّ، ثُـمَّ يُصَلِّيْ ثَلَاثًا. قَالَتْ عَائِشَةُ، فَقُلْتُ: يَا رَسُوْلَ اللّٰهِ، اَتَنَامُ قَبْلَ اَنْ تُوْتِرَ؟ فَقَالَ: يَا عَائِشَةُ، اِنَّ عَيْنَيَّ تَنَامَانِ وَلَا يَنَامُ قَلْبِيْ. البخارى 2: 47"],["p","Dari Abu Salamah bin 'Abdur Rahman, bahwasanya ia pernah bertanya kepada 'Aisyah RA, \"Bagaimanakah shalatnya Rasulullah SAW di bulan Ramadlan ?\". Maka 'Aisyah berkata, \"Dahulu Rasulullah SAW tidak melebihkan di bulan Ramadlan maupun di luar Ramadlan atas sebelas rekaat. Beliau shalat empat rekaat, jangan kamu tanya bagusnya dan panjangnya. Kemudian beliau shalat empat rekaat, jangan kamu tanya bagusnya dan panjangnya. Kemudian beliau shalat (witir) tiga rekaat. ‘Aisyah berkata : Aku bertanya, “Ya Rasulullah, apakah engkau tidur sebelum shalat witir ?”. Rasulullah SAW menjawab, “Sesungguhnya kedua mataku tidur, sedangkan hatiku tidak tidur\". [HR. Bukhari juz 2, hal. 47]"],["p","Keterangan :"],["p","“Sesungguhnya kedua mataku tidur, sedangkan hatiku tidak tidur”, ini adalah kekhususan untuk para Nabi."],["p","Maksud hadits tersebut, Nabi SAW shalat 2 raka'at salam, 2 raka'at salam lalu istirahat. Dilanjutkan lagi 2 raka'at salam, 2 raka'at salam lalu istirahat. Kemudian beliau shalat witir 3 reka'at."],["p","Namun hadits tersebut bukan merupakan batasan dari Nabi SAW, tetapi hanya menunjukkan bahwa biasanya Nabi SAW shalat malam sebelas raka'at."],["a","عَنِ ابْنِ عُمَرَ اَنَّ رَجُلًا سَأَلَ رَسُوْلَ اللهِ ﷺ عَنْ صَلَاةِ اللَّيْلِ. فَقَالَ رَسُوْلُ اللهِ ﷺ: صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى. فَاِذَا خَشِيَ اَحَدُكُمُ الصُّبْحَ صَلَّى رَكْعَةً وَاحِدَةً تُوْتِرُ لَهُ مَا قَدْ صَلَّى. مسلم 1: 516 رقم: 145"],["p","Dari Ibnu 'Umar bahwasanya ada seorang lelaki bertanya kepada Rasulullah SAW tentang shalat malam. Maka Rasulullah SAW menjawab, \"Shalat malam itu 2 raka'at 2 raka'at. Maka apabila seseorang diantara kalian khawatir masuk Shubuh, hendaklah ia shalat Witir 1 raka'at. Yang seraka'at itu mewitirkan untuk shalat yang telah ia kerjakan\". [HR. Muslim juz 1, hal. 516 no 145]"],["h","c. Cara Pelaksanaan"],["p","1. Boleh dengan Jahr (suara nyaring) maupun Sirr (suara lembut) :"],["a","عَنْ عَبْدِ اللهِ بْنِ اَبِيْ قَيْسٍ قَالَ: سَأَلْتُ عَائِشَةَ: كَيْفَ كَانَ قِرَاءَةُ النَّبِيِّ ﷺ بِاللَّيْلِ؟ فَقَالَتْ: كُلُّ ذٰلِكَ قَدْ كَانَ يَفْعَلُ، رُبَـمَا اَسَرَّ بِالْقِرَاءَةِ وَرُبَـمَا جَهَرَ. فَقُلْتُ: اَلْحَمْدُ لِلّٰهِ الَّذِيْ جَعَلَ فِى اْلاَمْرِ سَعَةً. الترمذى 1: 278، رقم: 447، هذا حديث صحيح غريب"],["p","Dari 'Abdullah bin Abu Qais, ia berkata : Aku bertanya kepada 'Aisyah, \"Bagaimana bacaan Nabi SAW pada waktu (shalat) malam ?\". Jawab 'Aisyah, \"Semuanya itu pernah dilakukan oleh Rasulullah SAW, terkadang beliau membaca sirr (pelan) dan terkadang beliau membaca jahr (nyaring)\". Maka aku berkata, \"Segala puji bagi Allah yang telah memberi kelonggaran dalam hal ini\". [HR. Tirmidzi juz 1, hal. 278, no. 447, ia berkata : Ini hadits shahih, gharib]"],["h","2. Boleh dikerjakan dengan berjama'ah maupun munfarid (sendirian)"],["a","عَنْ عَائِشَةَ اُمِّ الْمُؤْمِنِيْنَ رَضِيَ اللهُ عَنْهَا اَنَّ رَسُوْلَ اللهِ ﷺ صَلَّى ذَاتَ لَيْلَةٍ فِى الْمَسْجِدِ فَصَلَّى بِصَلَاتِهِ نَاسٌ. ثُـمَّ صَلَّى مِنَ الْقَابِلَةِ فَكَثُرَ النَّاسُ. ثُـمَّ اجْتَمَعُوْا مِنَ اللَّيْلَةِ الثَّالِثَةِ اَوِ الرَّابِعَةِ فَلَمْ يَخْرُجْ اِلَيْهِمْ رَسُوْلُ اللهِ ﷺ. فَلَمَّا اَصْبَحَ قَالَ:قَدْ رَأَيْتُ الَّذِيْ صَنَعْتُمْ فَلَمْ يَـمْنَعْنِيْ مِنَ الْخُرُوْجِ اِلَيْكُمْ اِلَّا اَنِّيْ خَشِيْتُ اَنْ تُفْرَضَ عَلَيْكُمْ. وَذٰلِكَ فِيْ رَمَضَانَ. البخارى 2: 44"],["p","Dari 'Aisyah Ummul Mu’minin RA, bahwasanya pada suatu malam Rasulullah SAW shalat malam di masjid, maka orang-orangpun turut shalat bersama beliau. Kemudian beliau shalat pula pada malam berikutnya, maka bertambah banyak orang yang mengikutinya. Kemudian malam ketiganya atau keempatnya mereka telah berkumpul, tetapi Rasulullah SAW tidak datang. Maka setelah shalat Shubuh beliau bersabda, \"Sungguh aku telah mengetahui apa yang kalian perbuat (tadi malam), dan tidak ada yang menghalangiku untuk keluar kepada kalian, melainkan karena aku khawatir apabila shalat malam itu diwajibkan kepada kalian\". (Perawi berkata), \"Kejadian tersebut pada bulan Ramadlan\". [HR. Bukhari juz 2, hal. 44]"],["h","B. Shalat sunnah Tahajjud"],["p","Shalat Sunnah Tahajjud adalah : Shalat malam yang dikerjakan di luar bulan Ramadlan."],["p","Nama Tahajjud diambil dari firman Allah ayat 79 surat Al-Israa' :"],["a","وَمِنَ الَّيْلِ فَتَهَجَّدْ بِهٖ نَافِلَةً لَّكَ. الاسراء: 79"],["p","Dan pada sebagian malam bershalat Tahajjudlah kamu sebagai suatu tambahan bagimu. [QS. Al-Israa' : 79]"],["p","Jadi, shalat sunnah tarawih dan shalat sunnah tahajjud adalah sama. Kalau dikerjakan di bulan Ramadlan disebut shalat Tarawih, sedangkan jika dikerjakan di luar Ramadlan disebut shalat Tahajjud."],["h","C. Shalat sunnah Witir"],["p","Shalat sunnah witir ialah shalat sunnah lail yang dikerjakan dengan bilangan rakaat yang ganjil (witir = ganjil)."],["a","عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ يَا اَهْلَ اْلقُرْاٰنِ اَوْتِرُوْا فَاِنَّ اللهَ وِتْرٌ يُحِبُّ اْلوِتْرَ. ابو داود 1: 61، رقم: 1416"],["p","Dari 'Ali RA, ia berkata : Rasulullah SAW bersabda, \"Wahai ahli Qur'an, berwitirlah kalian, karena sesungguhnya Allah itu witir/tunggal, Ia suka kepada (shalat) witir\". [HR. Abu Dawud juz 1, hal. 61, no. 1416]"],["p","Waktu, bilangan dan cara pelaksanaan shalat Witir"],["p","a. Waktunya :"],["p","Pada setiap malam, baik di dalam maupun di luar Ramadlan, boleh dikerjakan di awwal, pertengahan, ataupun diakhir malam, baik sebelum maupun sesudah tidur, kesemuanya itu pernah dicontohkan oleh Rasulullah SAW :"],["a","عَنْ عَائِشَةَ قَالَتْ: مِنْ كُلِّ اللَّيْلِ قَدْ اَوْتَرَ رَسُوْلُ اللهِ ﷺ مِنْ اَوَّلِ اللَّيْلِ وَاَوْسَطِهِ وَاٰخِرِهِ فَانْتَهَى وِتْرُهُ اِلىَ السَّحَرِ. مسلم 1: 512 رقم 137"],["p","Dari 'Aisyah RA, ia berkata, \"Dalam seluruh (bagian) malam Rasulullah SAW pernah mengerjakan witir, di permulaan malam, dipertengahannya, dan di akhirnya, hingga witirnya selesai pada waktu sahur\". [HR. Muslim juz 1, hal. 512, no. 137]"],["a","عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ خَافَ اَنْ لَا يَقُوْمَ مِنْ اٰخِرِ اللَّيْلِ فَلْيُوْتِرْ اَوَّلَهُ وَمَنْ طَمِعَ اَنْ يَقُوْمَ اٰخِرَهُ فَلْيُوْتِرْ اٰخِرَ اللَّيْلِ. فَاِنَّ صَلَاةَ اٰخِرِ اللَّيْلِ مَشْهُوْدَةٌ وَذٰلِكَ اَفْضَلُ. مسلم 1: 520 رقم 162"],["p","Dari Jabir RA, ia berkata, telah bersabda Rasulullah SAW, \"Barangsiapa khawatir tidak akan bangun pada akhir malam, maka bolehlah berwitir pada awwal malam. Dan barangsiapa berkeyakinan mampu bangun di akhir malam, maka hendaklah mengerjakan witir pada saat itu, karena shalat di akhir malam itu disaksikan dan yang demikian itu lebih utama\". [HR. Muslim juz 1, hal. 520, no. 162]."],["h","b. Bilangan raka'at serta cara pelaksanaannya"],["p","1) Satu raka’at,"],["a","عَنِ ابْنِ عُمَرَ اَنَّ رَجُلًا سَأَلَ رَسُوْلَ اللهِ ﷺ عَنْ صَلَاةِ اللَّيْلِ. فَقَالَ رَسُوْلُ اللهِ ﷺ: صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى. فَاِذَا خَشِيَ اَحَدُكُمُ الصُّبْحَ صَلَّى رَكْعَةً وَاحِدَةً تُوْتِرُ لَهُ مَا قَدْ صَلَّى. مسلم 1: 516 رقم 145"],["p","Dari Ibnu 'Umar bahwasanya ada seorang lelaki bertanya kepada Rasulullah SAW tentang shalat malam. Maka Rasulullah SAW menjawab, \"Shalat malam itu 2 raka'at 2 raka'at. Maka apabila seseorang diantara kamu khawatir masuk Shubuh hendaklah shalat witir 1 raka'at. Yang seraka'at itu mewitirkan untuk shalat yang telah dikerjakan\". [HR. Muslim juz 1, hal. 516, no. 145]"],["p","2) Tiga rakaat,"],["p","Bila melaksanakan 3 rakaat, harus dengan satu tasyahhud di rakaat yang terakhir, lalu salam, sebagaimana riwayat berikut :"],["a","عَنْ عَائِشَةَ اَنَّ رَسُوْلَ اللهِ ﷺ كَانَ اِذَا صَلَّى الْعِشَاءَ دَخَلَ الْمَنْزِلَ، ثُـمَّ صَلَّى رَكْعَتَيْنِ ثُـمَّ صَلَّى بَعْدَهُمَا رَكْعَتَيْنِ اَطْوَلَ مِنْهُمَا، ثُـمَّ اَوْتَرَ بِثَلَاثٍ لَا يَفْصِلُ فِيهِنَّ، ثُـمَّ صَلَّى رَكْعَتَيْنِ وَهُوَ جَالِسٌ، يَرْكَعُ وَهُوَ جَالِسٌ، وَيَسْجُدُ وَهُوَ قَاعِدٌ جَالِسٌ. احمد 11: 498، رقم: 25278"],["p","Dari 'Aisyah bahwasanya Rasulullah SAW apabila setelah shalat 'Isyak, beliau masuk ke rumah. Kemudian beliau shalat 2 rekaat, kemudian shalat lagi 2 reka'at yang lebih panjang daripada 2 reka'at yang pertama tadi, kemudian beliau berwitir 3 rekaat, dan beliau tidak memisahkan diantara tiga rekaat itu. Kemudian beliau shalat lagi 2 reka'at dalam keadaan duduk, beliau ruku' dalam keadaan duduk dan bersujud, dan beliau shalat dengan duduk\". [HR. Ahmad juz 11, hal. 498, no. 25278]"],["a","عَنْ عَائِشَةَ قَالَتْ:كَانَ رَسُوْلُ اللهِ ﷺ يُوْتِرُ بِثَلَاثٍ لَا يُسَلِّمُ اِلَّا فِيْ اٰخِرِهِنَّ. الحاكم فى المستدرك 1: 447، رقم: 1140"],["p","Dari 'Aisyah, ia berkata, \"Dahulu Rasulullah SAW pernah berwitir dengan 3 raka'at, beliau tidak salam kecuali pada rekaat yang terakhir\". [HR. Hakim dalam Al-Mustadrak juz 1 hal. 447, no. 1140]."],["a","عَنْ سَعْدِ بْنِ هِشَامٍ اَنَّ عَائِشَةَ حَدَّثَهُ اَنَّ رَسُوْلَ اللهِ ﷺ كَانَ لَا يُسَلِّمُ فِيْ رَكْعَتَيِ الْوِتْرِ. النسائى 3: 235"],["p","Dari Sa'ad bin Hisyam, bahwasanya 'Aisyah menceritakan kepadanya bahwasanya dahulu Rasulullah SAW tidak salam pada dua rekaat dalam shalat Witir\". [HR. Nasaiy juz 3, hal. 235]"],["p","Dan tidak diperkenankan shalat Witir yang 3 rekaat itu dengan 2 raka'at salam, kemudian disambung dengan 1 rakaat lalu salam. Hal ini menyalahi riwayat 'Aisyah di atas dan juga menyalahi arti witir itu sendiri, karena witir itu artinya ganjil, sedang 2 itu genap, jadi tidak dapat dikatakan witir. Dan juga kita tidak diperkenankan shalat 3 raka'at tersebut dengan 2 tasyahhud 1 salam. Sebab ini menyerupai Maghrib, yang demikian ini dilarang oleh Nabi SAW sebagaimana hadits di bawah ini. Sabda Nabi SAW :"],["a","لَا تُوْتِرُوْا بِثَلَاثٍ. اَوْتِرُوْا بِخَمْسٍ اَوْ بِسَبْعٍ وَلَا تُشَبِّهُوْا بِصَلَاةِ الْمَغْرِبِ. الدارقطنى 2: 24 رقم 1"],["p","Janganlah kalian shalat Witir 3 rekaat, (tetapi) shalatlah Witir 5 rekaat atau 7, dan janganlah kalian menyerupai dengan shalat Maghrib\". [HR. Daraquthniy juz 2, hal, 24, no. 1]."],["p","Keterangan :"],["p","Dalam hadits ini, Rasulullah SAW melarang kita shalat Witir 3 rekaat dan memerintahkan untuk shalat dengan 5 rekaat atau 7 rekaat. Sedang hadits-hadits lain menerangkan bahwa Rasulullah SAW sendiri mengerjakan shalat Witir 3 rekaat. Maka dari kedua hadits tersebut dapat diambil kesimpulan bahwa : \"Yang dilarang mengerjakan shalat Witir 3 rekaat itu adalah shalat Witir yang menyerupai shalat Maghrib, sedang shalat Witir 3 rekaat yang tidak serupa dengan shalat Maghrib tidak dilarang, bahkan dikerjakan oleh Rasulullah SAW\"."],["p","Adapun bentuk keserupaan itu ialah : Dengan 2 tasyahhud satu salam. Maka supaya tidak menyerupai shalat Maghrib hendaklah shalat Witir 3 rekaat tersebut dikerjakan dengan 3 rekaat sekaligus dengan satu tasyahhud di akhir rakaat dan satu salam."],["p","3) 5 reka’at dengan satu tasyahhud di raka’at yang terakhir lalu salam."],["p","Berdasar riwayat sebagai berikut :"],["a","عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُوْلُ اللهِ ﷺ يُصَلِّى مِنَ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً يُوْتِرُ مِنْ ذٰلِكَ بِخَمْسٍ لَا يَجْلِسُ فِى شَيْءٍ اِلَّا فِى اٰخِرِهَا. مسلم 1: 508 رقم 123"],["p","Dari ‘Aisyah, ia berkata, \"Dahulu Rasulullah SAW shalat di malam hari 13 rekaat, dari 13 rekaat itu beliau shalat Witir 5 rekaat. Dari 5 rekaat tersebut beliau tidak duduk (attahiyat) melainkan pada rekaat terakhir\". [HR. Muslim juz 1, hal. 508, no. 123]."],["p","4) 7 reka’at dengan 2 tasyahhud di reka’at 6 dan 7 lalu salam."],["p","Berdasar riwayat sebagai berikut :"],["a","عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُوْلُ اللهِ ﷺ اِذَا اَوْتَرَ بِتِسْعِ رَكَعَاتٍ لَـمْ يَقْعُدْ اِلَّا فِي الثَّامِنَةِ فَيَحْمَدُ اللهَ وَيَذْكُرُهُ وَيَدْعُوْ ثُـمَّ يَنْهَضُ وَلَا يُسَلِّمُ ثُـمَّ يُصَلِّي التَّاسِعَةِ فَيَجْلِسُ فَيَذْكُرُ اللهَ عَزَّ وَجَلَّ وَيَدْعُوْ ثُـمَّ يُسَلِّمُ تَسْلِيْمَةً يُسْمِعُنَا، ثُـمَّ يُصَلِّيْ رَكْعَتَيْنِ وَهُوَ جَالِسٌ، فَلَمَّا كَبُرَ وَضَعُفَ اَوْتَرَ بِسَبْعِ رَكَعَاتٍ لَا يَقْعُدُ اِلَّا فِي السَّادِسَةِ ثُـمَّ يَنْهَضُ وَلَا يُسَلِّمُ فَيُصَلِّي السَّابِعَةَ ثُـمَّ يُسَلِّمُ تَسْلِيْمَةً، ثُـمَّ يُصَلِّيْ رَكْعَتَيْنِ وَهُوَ جَالِسٌ. النسائى 3: 240"],["p","Dari Aisyah, ia berkata : Dahulu Rasulullah SAW apabila berwitir 9 rekaat, beliau tidak duduk (attahiyyat) melainkan pada rekaat kedelapan, beliau memuji Allah, menyebut-Nya dan berdo’a kepada-Nya. Kemudian beliau tidak mengucap salam, tetapi bangkit ke rekaat kesembilan, kemudian beliau duduk menyebut Allah ‘Azza wa Jalla dan berdo’a, kemudian beliau salam sekali salam dan memperdengarkan kepada kami. Kemudian beliau shalat dua rekaat dengan duduk. Setelah beliau lanjut usia dan lemah badannya, beliau berwitir dengan 7 rekaat, dan beliau tidak duduk attahiyyat melainkan pada rekaat yang keenam, kemudian beliau tidak mengucap salam, tetapi bangkit berdiri menyelesaikan rekaat yang ketujuh, kemudian beliau salam dengan sekali salam. Setelah itu beliau shalat dua rekaat dengan duduk. [HR Nasaaiy juz 3, hal. 240]."],["p","5) 9 reka’at dengan 2 tasyahhud di reka’at yang ke 8 dan ke 9 setelah itu salam."],["p","Berdasar riwayat sebagai berikut :"],["a","عَنْ سَعْدِ بْنِ هِشَامٍ اَنَّهُ قَالَ لِعَائِشَةَ: يَا اُمَّ الْمُؤْمِنِيْنَ، اَنْبِئِيْنِيْ عَنْ وِتْرِ رَسُوْلِ اللهِ ﷺ فَقَالَتْ: كُنَّا نُعِدُّ لَهُ سِوَاكَهُ وَطَهُوْرَهُ فَيَبْعَثُهُ اللهُ مَا شَاءَ اَنْ يَبْعَثَهُ مِنَ اللَّيْلِ فَيَتَسَوَّكُ وَيَتَوَضَّأُ وَيُصَلِّى تِسْعَ رَكَعَاتٍ، لَا يَجْلِسُ فِيْهَا اِلَّا فِى الثَّامِنَةِ فَيَذْكُرُ اللهَ وَيَحْمَدُهُ وَيَدْعُوْهُ ثُـمَّ يَنْهَضُ وَلَا يُسَلِّمُ ثُـمَّ يَقُوْمُ فَيُصَلِّى التَّاسِعَةَ ثُـمَّ يَقْعُدُ فَيَذْكُرُ اللهَ وَيَحْمَدُهُ وَيَدْعُوْهُ ثُـمَّ يُسَلِّمُ تَسْلِيْمًا يُسْمِعُنَا، ثُـمَّ يُصَلِّى رَكْعَتَيْنِ بَعْدَ مَا يُسَلِّمُ وَهُوَ قَاعِدٌ. فَتِلْكَ اِحْدَى عَشْرَةَ رَكْعَةً يَا بُنَيَّ. مسلم 1: 513 رقم 139"],["p","Dari Sa’d bin Hisyam, bahwasanya ia pernah bertanya kepada 'Aisyah, \"Wahai Ummul Mu’miniin, beritahukanlah kepadaku tentang shalat witir Rasulullah SAW\". Jawab 'Aisyah, \"Kami biasa menyediakan penggosok gigi dan air wudlu bagi Rasulullah SAW, lalu beliau bangun malam pada waktu yang dikehendaki Allah. Kemudian beliau menggosok gigi dan berwudlu lalu shalat (witir) sembilan reka’at, dan beliau tidak duduk (attahiyat) melainkan pada rekaat yang ke delapan, lalu beliau menyebut, memuji dan berdoa kepada Allah, kemudian beliau berdiri dengan tidak mengucap salam, berdiri shalat (rekaat) yang ke sembilan, kemudian beliau duduk (attahiyat) menyebut, memuji dan berdoa kepada Allah, kemudian beliau mengucap salam sehingga terdengar oleh kami. Setelah itu beliau shalat 2 rekaat dengan duduk. Yang demikian itu jadi 11 rekaat hai anakku\". [HR. Muslim juz 1, hal. 513, no. 139]."],["p","Dan kita dilarang mengerjakan 2 kali shalat Witir pada satu malam"],["a","عَنْ قَيْسِ بْنِ طَلْقِ بْنِ عَلِيٍّ عَنْ اَبِيْهِ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: لَا وِتْرَانِ فِيْ لَيْلَةٍ. الترمذى 1: 292، رقم: 468، هذا حديث حسن غريب"],["p","Dari Qais bin Thalq bin 'Ali, dari ayahnya, ia berkata : Saya mendengar Rasulullah SAW bersabda, \"Tidak ada dua Witir dalam satu malam\". [HR. Tirmidzi juz 1, hal. 292, no. 468, ini hadits hasan gharib]."],["p","c. Bacaan sesudah shalat Witir."],["p","Menurut riwayat Nasaaiy, Rasulullah SAW setelah shalat witir, beliau membaca Subhaanal Malikil Qudduus 3 kali."],["a","عَنْ قَتَادَةَ عَنْ زُرَارَةَ عَنْ عَبْدِ الرَّحْمٰنِ بْنِ اَبْزَى عَنْ رَسُوْلِ اللهِ ﷺ، كَانَ يُوْتِرُ بِسَبِّحِ اسْمَ رَبِّكَ الْاَعْلٰى، وَقُلْ يٰۤاَيُّهَا الْكَافِرُوْنَ، وَقُلْ هُوَ اللهُ اَحَدٌ. فَاِذَا فَرَغَ قَالَ: سُبْحَانَ الْمَلِكِ الْقُدُّوْسِ، ثَلَاثًا وَيـَمُدُّ فِى الثَّالِثَةِ. النسائى 3: 247"],["p","Dari Qatadah dari Zurarah dari ‘Abdur Rahman bin Abza dari Rasulullah SAW, biasanya beliau SAW di dalam shalat Witir membaca surat Al-A’laa, Al-Kaafirun dan Al-Ikhlash. Setelah selesai lalu beliau mengucapkan, “Subhaanal Malikil Qudduus (Maha Suci Allah Raja yang Maha Quddus) 3 X, dan beliau memanjangkan pada bacaan yang ketiga”. [HR. Nasaaiy juz 3, hal. 247]"],["p","Dan menurut riwayat Thabaraniy, setelah bacaan tersebut ada tambahan “Rabbul malaaikati war ruuh” (Tuhan nya para Malaikat dan Ruuh), namun tambahan ini tidak shahih, karena dalam sanadnya ada perawi bernama ‘Isa bin Yuunus, yang tidak diketahui jarh - ta’dilnya."],["p","Adapun bacaan “Alloohumma innaka ‘afuwwun tuhibbul ‘afwa, fa’fu ‘annii” itu adalah bacaan bila mengetahui Lailatul Qadr, sebagaimana riwayat berikut :"],["a","عَنْ عَائِشَةَ قَالَتْ قُلْتُ: يَا رَسُوْلَ اللهِ، اَرَأَيْتَ اِنْ عَلِمْتُ اَيَّ لَيْلَةٍ لَيْلَةُ اْلقَدْرِ مَا اَقُوْلُ فِيْهَا؟ قَالَ: قُوْلِيْ: اَللّٰهُمَّ اِنَّكَ عَفُوٌّ تُحِبُّ اْلعَفْوَ فَاعْفُ عَنِّيْ. الترمذى 5: 195، رقم: 3580، هذا حديث حسن صحيح"],["p","Dari ‘Aisyah, ia berkata : Aku bertanya, “Ya Rasulullah, bagaimana pendapat engkau apabila aku mengetahui bahwa malam itu malam Lailatul Qadr, apa yang harus aku baca ?”. Beliau bersabda, “Bacalah Alloohumma innaka ‘afuwwun tuhibbul ‘afwa fa’fu ‘annii (Ya Allah, sesungguhnya Engkau Maha Pemaaf, Engkau suka memaafkan, maka maafkanlah kesalahanku)”. [HR. Tirmidzi juz 5, hal. 195, no. 3580, ini hadits hasan shahih]"],["p","Lafadh tersebut juga diriwayatkan oleh Ahmad juz 9 hal. 526, juz 9 hal. 547 dan juz 10, hal. 24, juga diriwayatkan oleh Ibnu Majah juz 2, hal. 1265, no. 3850. Namun dalam ‘Aridlatul Ahwadzi dengan lafadh :"],["a","اَللّٰهُمَّ اِنَّكَ عَفُوٌّ كَرِيـْمٌ تُحِبُّ اْلعَفْوَ فَاعْفُ عَنِّيْ. الترمذى، فى عارضة الاحوذى، 13: 42، رقم: 3513"],["p","Ya Allah, sesungguhnya Engkau Maha Pemaaf lagi Maha Pemurah, Engkau suka memaafkan, maka maafkanlah kesalahanku. [HR. Tirmidzi, dalam ‘Aridlotul Ahwadzi juz 13, hal. 42, no. 3513]"],["p","D. Shalat Iftitah."],["p","Shalat Iftitah adalah shalat sunnah dua rekaat yang ringan untuk mengawali shalat lail."],["a","عَنْ اَبِيْ هُرَيْرَةَ عَنِ النَّبِيِّ ﷺ قَالَ: اِذَا قَامَ اَحَدُكُمْ مِنَ اللَّيْلِ فَلْيَفْتَتِحْ صَلَاتَهُ بِرَكْعَتَيْنِ خَفِيْفَتَيْنِ. مسلم 1: 532 رقم 198"],["p","Dari Abu Hurairah, dari Nabi SAW, beliau bersabda, \"Apabila seseorang diantara kalian bangun malam, maka hendaklah ia membuka shalatnya dengan dua rekaat yang ringan. [HR. Muslim juz 1, hal. 532, no. 198]."],["p","--oo0oo--"]],"c20220410_1280":[["p","Ahad, 10 April 2022/8 Ramadlan1443 Brosur No. : 2075/2115/IF"],["h","SEKITAR RAMADLAN"],["p","Hadits-hadits sekitar puasa Ramadlan."],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: مَنْ صَامَ رَمَضَانَ اِيْـمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ، وَمَنْ قَامَ لَيْلَةَ الْقَدْرِ اِيْـمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ. البخارى 2: 253"],["p","Dari Abu Hurairah RA, ia berkata, Nabi SAW bersabda, “Barangsiapa berpuasa Ramadlan karena iman dan mengharap pahala dari Allah, maka diampuni dosa-dosanya yang telah lalu. Dan barangsiapa shalat malam pada malam Lailatul Qadar karena iman dan mengharap pahala dari Allah, maka diampuni dosa-dosanya yang telah lalu”. [HR. Bukhari juz 2, hal 253]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ اَنَّ رَسُوْلَ اللهِﷺ قَالَ: مَنْ قَامَ رَمَضَانَ اِيْـمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ. البخارى 2: 251"],["p","Dari Abu Hurairah RA, bahwasanya Rasulullah SAW bersabda, “Barangsiapa bangun (shalat malam) pada bulan Ramadlan karena iman dan mengharap pahala dari Allah, maka diampuni dosa-dosanya yang telah lalu”. [HR. Bukhari 2 : 251]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِﷺ: قَالَ اللهُ: كُلُّ عَمَلِ ابْنِ اٰدَمَ لَهُ اِلَّا الصِّيَامَ فَاِنَّهُ لِيْ وَاَنَا اَجْزِيْ بِهِ، وَالصِّيَامُ جُنَّةٌ. وَاِذَا كَانَ يَوْمُ صَوْمِ اَحَدِكُمْ فَلَا يَرْفُثْ وَلَا يَصْخَبْ فَاِنْ سَابَّهُ اَحَدٌ اَوْ قَاتَلَهُ فَلْيَقُلْ اِنِّي امْرُؤٌ صَائِمٌ. وَالَّذِيْ نَفْسُ مُحَمَّدٍ بِيَدِهِ لَخُلُوْفُ فَمِ الصَّائِمِ اَطْيَبُ عِنْدَ اللهِ مِنْ رِيْحِ الْمِسْكِ. لِلصَّائِمِ فَرْحَتَانِ يَفْرَحُهُمَا، اِذَا اَفْطَرَ فَرِحَ وَاِذَا لَقِيَ رَبَّهُ فَرِحَ بِصَوْمِهِ. البخارى 2: 228"],["p","Dari Abu Hurairah RA, ia berkata : Rasulullah SAW bersabda : Allah berfirman, ”Setiap amal anak Adam itu untuknya kecuali puasa, sesungguhnya puasa itu untuk-Ku dan Aku akan membalasnya. Puasa itu perisai. Apabila salah seorang diantara kalian berpuasa pada suatu hari, maka janganlah berkata keji dan jangan berteriak-teriak. Jika ada seseorang yang mencaci makinya atau menyerangnya maka hendaklah ia mengatakan, ”Sesungguhnya saya sedang berpuasa”. Demi Dzat yang jiwa Muhammad di tangan-Nya, sungguh bau mulutnya orang yang berpuasa itu di sisi Allah lebih harum dari pada bau kasturi. Bagi orang yang berpuasa ada dua kegembiraan yang dirasakannya, yaitu apabila ia berbuka, bergembira karena bukanya, dan apabila ia bertemu dengan Tuhannya, bergembira karena puasanya”. [HR. Bukhari 2 : 228]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: كُلُّ عَمَلِ ابْنِ اٰدَمَ يُضَاعَفُ. اَلْحَسَنَةُ عَشْرُ اَمْثَالِـهَا اِلَى سَبْعِمِائَةِ ضِعْفٍ. قَالَ اللهُ عَزَّ وَجَلَّ: اِلَّا الصَّوْمَ فَاِنَّهُ لِيْ وَاَنَا اَجْزِيْ بِهِ. يَدَعُ شَهْوَتَهُ وَطَعَامَهُ مِنْ اَجْلِيْ. لِلصَّائِمِ فَرْحَتَانِ، فَرْحَةٌ عِنْدَ فِطْرِهِ وَفَرْحَةٌ عِنْدَ لِقَاءِ رَبِّهِ. وَلَخُلُوْفُ فِيْهِ اَطْيَبُ عِنْدَ اللهِ مِنْ رِيْحِ الْمِسْكِ. مسلم 2: 807"],["p","Dari Abu Hurairah RA, ia berkata : Rasulullah SAW bersabda, \"Setiap amal (kebaikan) anak Adam dilipat gandakan pahalanya, satu kebaikan diberi balasan sepuluh kali lipat sampai tujuh ratus kali lipat, Allah 'Azza wa Jalla berfirman, \"Kecuali puasa, karena puasa itu untuk-Ku, dan Aku yang akan membalasnya. Ia meninggalkan syahwatnya dan makannya karena Aku\". Bagi orang berpuasa ada dua kegembiraan yang dirasakannya, yaitu gembira ketika berbuka dan gembira ketika bertemu dengan Tuhan-nya. Dan sungguh bau mulut orang yang berpuasa di sisi Allah lebih harum dari pada bau minyak kasturi\". [HR. Muslim juz 2, hal. 807, no. 164]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اِذَا جَاءَ رَمَضَانُ فُتِّحَتْ اَبْوَابُ الْجَنَّةِ وَغُلِّقَتْ اَبْوَابُ النَّارِ وَصُفِّدَتِ الشَّيَاطِيْنُ. مسلم 2: 758"],["p","Dari Abu Hurairah RA bahwasanya Rasulullah SAW bersabda, “Apabila bulan Ramadlan datang maka dibukalah pintu-pintu surga, ditutuplah pintu-pintu neraka, dan syaithan-syaithan dibelenggu”. [HR. Muslim juz 2, hal. 758, no. 1]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: لَمَّا حَضَرَ رَمَضَانُ قَالَ رَسُوْلُ اللهِ ﷺ: قَدْ جَاءَكُمْ رَمَضَانُ شَهْرٌ مُبَارَكٌ اِفْتَرَضَ اللهُ عَلَيْكُمْ صِيَامَهُ تُفْتَحُ فِيْهِ اَبْوَابُ الْجَنَّةِ وَتُغْلَقُ فِيْهِ اَبْوَابُ الْجَحِيْمِ وَتُغَلُّ فِيْهِ الشَّيَاطِيْنُ، فِيْهِ لَيْلَةٌ خَيْرٌ مِنْ اَلْفِ شَهْرٍ. مَنْ حُرِمَ خَيْرَهَا فَقَدْ حُرِمَ. احمد 3: 412، 9502"],["p","Dari Abu Hurairah, ia berkata : Ketika tiba bulan Ramadlan Rasulullah SAW bersabda, “Telah datang pada kalian bulan Ramadlan, bulan yang diberkahi, Allah mewajibkan kepada kalian berpuasa pada bulan itu, ketika itu pintu-pintu surga dibuka, dan pintu-pintu neraka Jahim ditutup, dan syaithan-syaithan dibelenggu. Dalam bulan itu ada suatu malam yang lebih baik dari seribu bulan. Barangsiapa yang terhalang dari kebaikan-kebaikannya, maka sungguh dia telah terhalang (dari segala kebaikan)”. [HR. Ahmad juz 3, hal. 412, no 9502, munqathi’, karena Abu Qilabah tidak mendengar dari Abu Hurairah]"],["a","عَنْ زَيْدِ بْنِ خَالِدٍ اَلْجُهَنِيِّ قَالَ: قَالَ رَسُوْلُ اللّٰهِ ﷺ: مَنْ فَطَّرَ صَائِمًا كَانَ لَهُ مِثْلُ اَجْرِهِ غَيْرَ اَنَّهُ لَا يَنْقُصُ مِنْ اَجْرِ الصَّائِمِ شَيْئًا. الترمذى 2: 151، رقم: 804، هذا حديث حسن صحيح"],["p","Dari Zaid bin Khaalid Al-Juhaniy, ia berkata : Rasulullah SAW bersabda, “Barangsiapa yang memberi buka kepada orang yang berpuasa, maka dia mendapatkan pahala seperti pahalanya orang yang berpuasa itu dengan tidak mengurangi pahalanya orang yang berpuasa tersebut sedikitpun”. [HR. Tirmidziy juz 2, hal. 151, no. 804, ini hadits hasan shahih]"],["a","اَقْبَلَ رَمَضَانُ فَقَالَ رَسُوْلُ اللهِ ﷺ: اِنَّ رَمَضَانَ شَهْرٌ اِفْتَرَضَ اللهُ عَزَّ وَجَلَّ صِيَامَهُ وَاِنِّيْ سَنَنْتُ لِلْمُسْلِمِيْنَ قِيَامَهُ فَمَنْ صَامَهُ اِيْـمَانًا وَاحْتِسَابًا خَرَجَ مِنَ الذُّنُوْبِ كَيَوْمَ وَلَدَتْهُ اُمُّهُ. احمد 1: 413، رقم: 1688"],["p","Telah datang bulan Ramadlan, maka Rasulullah SAW bersabda, “Sesungguhnya Ramadlan adalah bulan dimana Allah ‘Azza wa Jalla mewajibkan puasa padanya, dan aku mensunnahkan shalat malam untuk kaum muslimin, maka barangsiapa berpuasa pada bulan Ramadlan karena iman dan mengharap pahala (dari Allah), maka ia keluar dari dosa-dosanya sebagaimana ketika ibunya melahirkannya”. [HR. Ahmad dari ‘Abdur Rahman bin 'Auf juz 1, hal. 413, no. 1688, dla’if karena dalam sanadnya ada An-Nadlr bin Syaiban]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ لَـمْ يَدَعْ قَوْلَ الزُّوْرِ وَالْعَمَلَ بِهِ فَلَيْسَ ِلِلّٰهِ حَاجَةٌ فِيْ اَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ. البخارى 2: 228"],["p","Dari Abu Hurairah RA, ia berkata : Rasulullah SAW bersabda, “Barangsiapa yang tidak meninggalkan kata-kata dusta dan perbuatan dusta, maka tidak ada kebutuhan bagi Allah dalam hal ia meninggalkan makan dan minumnya”. [HR. Bukhari juz 2, hal. 228]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: رُبَّ صَائِمٍ حَظُّهُ مِنْ صِيَامِهِ الْجُوْعُ، وَرُبَّ قَائِمٍ حَظُّهُ مِنْ قِيَامِهِ السَّهَرُ. الحاكم فى المستدرك 1: 596، رقم: 1571"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Betapa banyak orang yang berpuasa hanya mendapatkan lapar dari puasanya itu, dan betapa banyak orang yang shalat malam, dari shalat malamnya itu hanya mendapatkan tidak tidur\". [HR Hakim dalam Al-Mustadrak juz 1, hal. 596, no. 1571, ini hadits shahih atas syarat Bukhari, tetapi Bukhari dan Muslim tidak mengeluarkannya]"],["a","عَنْ اَبِيْ هُرَيْرَةَ، قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: رُبَّ صَائِمٍ حَظُّهُ مِنْ صِيَامِهِ الْجُوْعُ وَالْعَطَشُ، وَرُبَّ قَائِمٍ حَظُّهُ مِنْ قِيَامِهِ السَّهَرُ. احمد 3: 307، رقم: 8865"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Betapa banyak orang yang berpuasa hanya mendapatkan lapar dan haus, dan betapa banyak orang yang shalat malam, dari shalat malamnya itu hanya mendapatkan tidak tidur\". [HR. Ahmad juz 3, hal. 307, no. 8865]"],["a","عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ ﷺ اَجْوَدَ النَّاسِ بِالْخَيْرِ وَكَانَ اَجْوَدُ مَا يَكُوْنُ فِيْ رَمَضَانَ حِيْنَ يَلْقَاهُ جِبْرِيْلُ وَكَانَ جِبْرِيْلُ عَلَيْهِ السَّلَامُ يَلْقَاهُ كُلَّ لَيْلَةٍ فِيْ رَمَضَانَ حَتَّى يَنْسَلِخَ يَعْرِضُ عَلَيْهِ النَّبِيُّ ﷺ الْقُرْاٰنَ، فَاِذَا لَقِيَهُ جِبْرِيْلُ عَلَيْهِ السَّلَامُ كَانَ اَجْوَدَ بِالْخَيْرِ مِنَ الرِّيْحِ الْمُرْسَلَةِ. البخارى 2: 228"],["p","Dari Ibnu ‘Abbas RA, ia berkata, “Adalah Nabi SAW orang yang paling dermawan diantara manusia pada kebaikan. Dan beliau paling pemurah pada bulan Ramadlan, ketika Jibril bertemu beliau, dan Jibril AS bertemu beliau pada tiap malam di bulan Ramadlan hingga selesai. Nabi SAW menyimakkan Al-Qur’an kepadanya. Maka apabila Jibril AS menemui beliau, beliau adalah sangat dermawan dalam kebaikan, lebih murah dari pada angin yang terlepas”. [HR. Bukhari juz 2, hal. 228]"],["a","عَنْ سَهْلٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: اِنَّ فِى الْجَنَّةِ بَابًا يُقَالُ لَهُ الرَّيَّانُ يَدْخُلُ مِنْهُ الصَّائِمُوْنَ يَوْمَ الْقِيَامَةِ لَا يَدْخُلُ مِنْهُ اَحَدٌ غَيْرُهُمْ، يُقَالُ: اَيْنَ الصَّائِمُوْنَ؟ فَيَقُوْمُوْنَ لَا يَدْخُلُ مِنْهُ اَحَدٌ غَيْرُهُمْ. فَاِذَا دَخَلُوْا اُغْلِقَ فَلَمْ يَدْخُلْ مِنْهُ اَحَدٌ. البخارى 2 : 226"],["p","Dari Sahl RA, dari Nabi SAW, beliau bersabda, “Sesungguhnya di dalam surga terdapat pintu yang disebut Rayyan, yang mana besok pada hari qiyamat orang-orang yang berpuasa masuk dari pintu itu. Dan tidak ada seorangpun yang masuk dari pintu itu selain mereka. Dikatakan,”Dimanakah orang-orang yang berpuasa ?”. Maka mereka berdiri, tidak ada seorangpun selain mereka yang masuk darinya. Apabila mereka sudah masuk, maka pintu itu ditutup sehingga tidak ada seorangpun yang masuk darinya”. [HR. Bukhari 2 : 226]"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نُسَافِرُ مَعَ النَّبِيِّ ﷺ فَلَمْ يَعِبِ الصَّائِمُ عَلَى الْمُفْطِرِ وَلَا الْمُفْطِرُ عَلَى الصَّائِمِ. البخارى 2 : 238"],["p","Dari Anas bin Maalik RA, ia berkata, ”Kami bepergian bersama Nabi SAW. Dan orang yang berpuasa tidak mencela orang yang berbuka, dan orang yang berbuka tidak mencela orang yang berpuasa”. [HR. Bukhari 2 : 238]"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ فِيْ سَفَرٍ فَرَأَى زِحَامًا وَرَجُلًا قَدْ ظُلِّلَ عَلَيْهِ، فَقَالَ: مَا هٰذَا؟ فَقَالُوْا: صَائِمٌ. فَقَالَ: لَيْسَ مِنَ الْبِرِّ الصَّوْمُ فِى السَّفَرِ. البخارى 2 : 238"],["p","Dari Jabir bin Abdullah RA, ia berkata : Ketika dalam suatu perjalanan, Rasulullah SAW melihat kerumunan orang, dan seseorang telah dinaungi. Beliau SAW bertanya, ”Ada apa ini ?”. Mereka menjawab, ”Orang yang berpuasa“. Maka beliau bersabda, ”Tidak termasuk kebajikan berpuasa dalam bepergian“. [HR. Bukhari 2 : 238]"],["a","عَنْ سَلْمَانَ قَالَ: خَطَبَنَا رَسُوْلُ اللهِ ﷺ فِيْ آخِرِ يَوْمٍ مِنْ شَعْبَانَ فَقَالَ: اَيُّهَا النَّاسُ قَدْ اَظَلَّكُمْ شَهْرٌ عَظِيْمٌ، شَهْرٌ مُبَارَكٌ، شَهْرٌ فِيْهِ لَيْلَةٌ خَيْرٌ مِنْ اَلْفِ شَهْرٍ، جَعَلَ اللهُ صِيَامَهُ فَرِيْضَةً، وَقِيَامَ لَيْلِهِ تَطَوُّعًا. مَنْ تَقَرَّبَ فِيْهِ بِخَصْلَةٍ مِنَ الْخَيْرِ كَانَ كَمَنْ اَدَّى فَرِيْضَةً فِيْمَا سِوَاهُ، وَمَنْ اَدَّى فِيْهِ فَرِيْضَةً كَانَ كَمَنْ اَدَّى سَبْعِيْنَ فَرِيْضَةً فِيْمَا سِوَاهُ. وَهُوَ شَهْرُ الصَّبْرِ، وَالصَّبْرُ ثَوَابُهُ الْجَنَّةُ، وَشَهْرُ الْمُوَاسَاةِ، وَشَهْرٌ يَزْدَادُ فِيْهِ رِزْقُ الْمُؤْمِنِ. مَنْ فَطَّرَ فِيْهِ صَائِمًا كَانَ مَغْفِرَةً لِذُنُوْبِهِ وَعِتْقِ رَقَبَتِهِ مِنَ النَّارِ، وَكَانَ لَهُ مِثْلُ اَجْرِهِ مِنْ غَيْرِ اَنْ يَنْتَقِصَ مِنْ اَجْرِهِ شَيْءٌ. قَالُوْا: لَيْسَ كُلُّنَا نَجِدُ مَا يُفَطِّرُ الصَّائِمَ. فَقَالَ: يُعْطِي اللهُ هٰذَا الثَّوَابَ مَنْ فَطَّرَ صَائِمًا عَلَى تَـمْرَةٍ، اَوْ شَرْبَةِ مَاءٍ، اَوْ مَذْقَةِ لَبَنٍ. وَهُوَ شَهْرٌ اَوَّلُهُ رَحْمَةٌ، وَاَوْسَطُهُ مَغْفِرَةٌ، وَاٰخِرُهُ عِتْقٌ مِنَ النَّارِ. مَنْ خَفَّفَ عَنْ مَـمْلُوْكِهِ غَفَرَ اللهُ لَهُ، وَاَعْتَقَهُ مِنَ النَّارِ. وَاسْتَكثِرُوْا فِيْهِ مِنْ اَرْبَعِ خِصَالٍ: خَصْلَتَيْنِ تُرْضُوْنَ بِـهِمَا رَبَّكُمْ، وَخَصْلَتَيْنِ لَا غِنَى بِكُمْ عَنْهُمَا. فَاَمَّا الْخَصْلَتَانِ اللَّتَانِ تُرْضُوْنَ بِـهِمَا رَبَّكُمْ: فَشَهَادَةُ اَنْ لَا اِلٰهَ اِلَّا اللهُ، وَتَسْتَغْفِرُوْنَهُ، وَاَمَّا اللَّتَانِ لَا غِنَى بِكُمْ عَنْهُمَا: فَتَسْأَلُوْنَ اللهَ الْجَنَّةَ، وَتَعَوَّذُوْنَ بِهِ مِنَ النَّارِ. وَمَنْ اَشْبَعَ فِيْهِ صَائِمًا سَقَاهُ اللهُ مِنْ حَوْضِيْ شَرْبَةً لَا يَظْمَأُ حَتَّى يَدْخُلَ الْجَنَّةَ. ابن خزيمة 3: 191، رقم: 1887"],["p","Dari Salman, ia berkata : Rasulullah SAW berkhutbah pada hari terakhir bulan Sya’ban, beliau bersabda, “Hai para manusia, sungguh telah menaungi kalian bulan yang agung, bulan yang diberkahi, bulan yang di dalamnya ada satu malam lebih baik daripada seribu bulan. Allah menjadikan puasanya suatu kewajiban, dan shalat malamnya tathawwu’an (sunnah). Barangsiapa mendekatkan diri (kepada Allah) pada bulan itu dengan sesuatu berupa kebaikan, maka dia seperti orang yang menunaikan kewajiban di luar bulan Ramadlan. Barangsiapa yang menunaikan satu kewajiban (amalan fardlu) pada bulan itu, maka dia (pahalanya) seperti orang yang menunaikan tujuh puluh kewajiban di luar bulan Ramadlan. Dan bulan (Ramadlan) adalah bulan keshabaran, sedangkan shabar pahalanya adalah surga, dan bulan pertolongan dan bulan yang padanya bertambah rezqinya orang mu’min. Barangsiapa memberi buka kepada orang yang berpuasa pada bulan itu, maka yang demikian itu merupakan ampunan untuk dosa-dosanya dan membebaskan dirinya dari neraka, dan dia mendapatkan pahala seperti pahalanya orang yang berpuasa tanpa berkurang sedikitpun dari pahalanya”. Para shahabat bertanya, “(Ya Rasulullah), tidak setiap orang dari kami mesti mempunyai sesuatu untuk memberi makan berbuka kepada orang yang berpuasa”. Maka beliau menjawab, “Allah memberikan pahala ini kepada orang yang memberi buka orang yang berpuasa meskipun berupa sebuah kurma, seteguk air atau sedikit susu. Bulan Ramadlan itu adalah bulan yang permulaannya rahmat, pertengahannya ampunan dan akhirnya bebas dari neraka. Barangsiapa yang memberi keringanan kepada budaknya, maka Allah mengampuninya dan membebaskannya dari neraka. Dan perbanyaklah pada bulan itu melakukan empat hal, dua hal yang dengannya kalian membuat ridla Tuhan kalian, dan dua hal lagi yang kalian membutuhkannya. Adapun dua hal yang dengannya kalian bisa membuat ridla Tuhan kalian ialah kesaksian (syahadat) bahwa tidak ada Tuhan selain Allah, dan kalian mohon ampunan kepada-Nya. Adapun dua hal yang kalian membutuhkannya ialah kalian mohon surga kepada Allah dan mohon perlindungan dari neraka. Dan barangsiapa di bulan itu membuat kenyang kepada orang yang berpuasa, maka Allah akan memberinya minum dari telagaku, sekali minum dia tidak akan haus hingga masuk surga”. [HR. Ibnu Khuzaimah juz 3, hal. 191 no 1887, dla’if karena dalam sanadnya ada perawi bernama ‘Ali bin Zaid bin Jud’aan]"],["p","Keterangan :"],["p","Tentang perawi ‘Ali bin Zaid bin Jud’aan tersebut :"],["p","Ahmad bin Hanbal berkata : Ia dla’if"],["p","Bukhari dan Ibnu Hibban berkata : Tidak dapat dijadikan hujjah"],["p","Nasaiy berkata : Ia dla’if."],["p","Ibnu Khuzaimah berkata : Saya tidak berhujjah dengannya karena buruk hafalannya."],["p","Bisa dilihat dalam Mizaanul I’tidal juz 3, hal. 127, no. 5844. Dan Tahdzibut Tahdzib juz 7, hal. 283, no 545."],["a","عَنْ عَبْدِ اللهِ بْنِ كَعْبِ بْنِ مَالِكٍ يُحَدِّثُ عَنْ اَبِيْهِ قَالَ: كَانَ النَّاسُ فِيْ رَمَضَانَ، اِذَا صَامَ الرَّجُلُ فَاَمْسَى فَنَامَ حَرُمَ عَلَيْهِ الطَّعَامُ وَالشَّرَابُ وَالنِّسَاءُ حَتَّى يُفْطِرَ مِنَ الْغَدِ. فَرَجَعَ عُمَرُ بْنُ الْخَطَّابِ مِنْ عِنْدِ النَّبِيِّ ﷺ ذَاتَ لَيْلَةٍ قَدْ سَهِرَ عِنْدَهُ فَوَجَدَ امْرَأَتَهُ قَدْ نَامَتْ فَاَرَادَهَا. فَقَالَتْ: اِنِّيْ قَدْ نِـمْتُ. قَالَ: مَا نِـمْتُ. ثُـمَّ وَقَعَ بِـهَا. وَصَنَعَ كَعْبُ بْنُ مَالِكٍ مِثْلَ ذٰلِكَ. فَغَدَا عُمَرُ بْنُ الْخَطَّابِ اِلَى النَّبِيِّ ﷺ فَاَخْبَرَهُ، فَاَنْزَلَ اللهُ تَعَالَى: عَلِمَ اللهُ اَنَّكُمْ كُنْتُمْ تَخْتَانُوْنَ اَنْفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنْكُمْ. احمد 5: 356، رقم: 15795"],["p","Dari 'Abdullah bin Ka’ab bin Maalik, ia menceritakan dari ayahnya, ia berkata, \"Dahulu pada bulan Ramadlan orang-orang apabila berpuasa, ketika tiba saat berbuka lalu tidur, maka dia tidak boleh makan minum dan mencampuri istrinya hingga berbuka hari berikutnya. Pada suatu malam ‘Umar bin Khaththab datang dari sisi Nabi SAW setelah berbincang-bincang dengan beliau. Ketika itu ia mendapati istrinya telah tidur padahal ia ingin mencampurinya, (lalu ia membangunkannya). Maka istrinya berkata, “Sesungguhnya aku sudah tidur !”. ‘Umar berkata, “Tetapi aku belum tidur !”. Kemudian ‘Umar mencampurinya. Dan Ka’ab bin Malik pun berbuat seperti itu. Keesokan harinya ‘Umar bin Khaththab datang kepada Nabi SAW memberitahukan hal itu. Maka Allah Ta'aalaa menurunkan ayat ‘alimalloohu annakum kuntum takhtaanuuna anfusakum fataaba 'alaikum wa 'afaa 'ankum (Allah mengetahui bahwasanya kalian tidak dapat menahan nafsu kalian, oleh karena itu Allah mengampuni kalian dan mema'afkan kalian).(Al-Baqarah : 187) [HR. Ahmad, 5, : 356, no. 15795]"],["a","عَنْ سَمُرَةَ بْنِ جُنْدَبٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا يَـمْنَعَنَّ مِنْ سَحُوْرِكُمْ اَذَانُ بِلَالٍ وَلَا بَيَاضُ الْاُفُقِ الَّذِيْ هٰكَذَا حَتَّى يَسْتَطِيْرَ. ابو داود 2: 303، رقم: 2346"],["p","Dari Samurah bin Jundab, ia berkata : Rasulullah SAW bersabda, “Janganlah adzannya Bilal menghalangi sahur kalian, dan jangan pula terangnya ufuq yang (tegak) demikian, sehingga terangnya ufuq itu melintang dan menyebar”. [HR. Abu Dawud juz 2, hal. 303, no. 2346]"],["a","عَنْ سَالِـمِ بْنِ عَبْدِ اللهِ عَنْ اَبِيْهِ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اِنَّ بِلَالًا يُؤَذِّنُ بِلَيْلٍ فَكُلُوْا وَاشْرَبُوْا حَتَّى يُنَادِيَ ابْنُ اُمِّ مَكْتُوْمٍ. قَالَ: وَكَانَ رَجُلًا اَعْمَى لَا يُنَادِيْ حَتَّى يُقَالَ لَهُ: اَصْبَحْتَ اَصْبَحْتَ. البخارى 1: 153"],["p","Dari Salim bin ‘Abdullah, dari ayahnya, bahwasanya Rasulullah SAW bersabda, “Sesungguhnya Bilal itu adzan pada malam hari, maka makanlah dan minumlah sehingga Ibnu Ummi Maktum adzan”. (Abdullah bin ‘Umar) berkata, “Dia adalah seorang yang buta, tidak beradzan sehingga dikatakan kepadanya, “Sudah Shubuh, sudah Shubuh”. [HR. Bukhari juz 1, hal. 153]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اِذَا سَمِعَ اَحَدُكُمُ النِّدَاءَ وَالْاِنَاءُ عَلَى يَدِهِ فَلَا يَضَعْهُ حَتَّى يَقْضِيَ حَاجَتَهُ مِنْهُ. ابو داود 2: 304، رقم: 2350"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Apabila salah seorang diantara kalian mendengar seruan (adzan), sedangkan bejana sudah berada di tangannya, maka janganlah ia meletakkannya sehingga selesai keperluannya itu”. [HR. Abu Dawud juz 2, hal. 304, no. 2350]"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ ﷺ يُقَبِّلُ وَيُبَاشِرُ وَهُوَ صَائِمٌ وَكَانَ اَمْلَكَكُمْ لِاِرْبِهِ. البخارى 2 : 233"],["p","Dari ‘Aisyah RA, ia berkata, “Nabi SAW mencium dan bercumbu padahal beliau berpuasa, dan beliau adalah orang yang paling bisa menguasai nafsunya diantara kamu sekalian”. [HR. Bukhari juz 2, hal. 233]"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: اِنْ كَانَ رَسُوْلُ اللهِ ﷺ لَيُقَبِّلُ بَعْضَ اَزْوَاجِهِ وَهُوَ صَائِمٌ ثُـمَّ ضَحِكَتْ. البخارى 2 : 233"],["p","Dari ‘Aisyah RA, ia berkata, “Sesungguhnya Rasulullah SAW pernah mencium diantara para istri beliau sedangkan beliau berpuasa. Kemudian istrinya tertawa”. [HR. Bukhari juz 2, hal. 233]"],["a","عَنْ عَائِشَةَ وَاُمِّ سَلَمَةَ زَوْجَيِ النَّبِيِّ ﷺ اَنَّهُمَا قَالَتَا: اِنْ كَانَ رَسُوْلُ اللهِ ﷺ لَيُصْبِحُ جُنُبًا مِنْ جِمَاعٍ غَيْرِ احْتِلَامٍ فِيْ رَمَضَانَ ثُـمَّ يَصُوْمُ. مسلم 2 : 780"],["p","Dari 'Aisyah dan Ummu Salamah istri Nabi SAW, keduanya berkata, “Sesungguhnya dahulu Rasulullah SAW pernah pada waktu shubuh di bulan Ramadlan masih dalam keadaan junub karena persetubuhan bukan karena mimpi, kemudian beliau tetap berpuasa”. [HR. Muslim Juz 2, hal. 780, no. 78]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: اِذَا نَسِيَ فَاَكَلَ وَشَرِبَ فَلْيُتِمَّ صَوْمَهُ، فَاِنَّـمَا اَطْعَمَهُ اللهُ وَسَقَاهُ. البخارى 2 : 234"],["p","Dari Abu Hurairah RA, dari Nabi SAW, beliau bersabda, “Apabila seseorang sedang berpuasa, lalu lupa sehingga makan dan minum, maka hendaklah dia menyempurnakan puasanya. Hanyasanya Allah memberikan makan dan minum kepadanya”. [HR. Bukhari juz 2, hal. 234]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا نَحْنُ جُلُوْسٌ عِنْدَ النَّبِيِّ ﷺ اِذْ جَاءَهُ رَجُلٌ فَقَالَ: يَا رَسُوْلَ اللهِ، هَلَكْتُ. قَالَ: مَا لَكَ؟ قَالَ: وَقَعْتُ عَلَى امْرَأَتِيْ وَاَنَا صَائِمٌ. فَقَالَ رَسُوْلُ اللهِ ﷺ: هَلْ تَجِدُ رَقَبَةً تُعْتِقُهَا؟ قَالَ: لَا. قَالَ: فَهَلْ تَسْتَطِيْعُ اَنْ تَصُوْمَ شَهْرَيْنِ مُتَتَابِعَيْنِ؟ قَالَ: لَا. فَقَالَ: فَهَلْ تَجِدُ اِطْعَامَ سِتِّيْنَ مِسْكِيْنًا؟ قَالَ: لَا. قَالَ: فَمَكَثَ عِنْدَ النَّبِيِّ ﷺ فَبَيْنَا نَحْنُ عَلَى ذٰلِكَ اُتِيَ النَّبِيُّ ﷺ بِعَرَقٍ فِيْهِ تَـمْرٌ، وَالْعَرَقُ الْمِكْتَلُ. قَالَ: اَيْنَ السَّائِلُ؟ فَقَالَ: اَنَا. قَالَ: خُذْ هَا فَتَصَدَّقْ بِهِ. فَقَالَ الرَّجُلُ: اَعَلَى اَفْقَرَ مِنِّيْ يَا رَسُوْلَ اللهِ؟ فَوَ اللهِ مَا بَيْنَ لَابَتَيْهَا (يُرِيْدُ الْحَرَّتَيْنِ) اَهْلُ بَيْتٍ اَفْقَرَ مِنْ اَهْلِ بَيْتِيْ. فَضَحِكَ النَّبِيُّ ﷺ حَتَّى بَدَتْ اَنْيَابُهُ. ثُـمَّ قَالَ: اَطْعِمْهُ اَهْلَكَ. البخارى 2 : 235"],["p","Dari Abu Hurairah RA, ia berkata : Ketika kami sedang duduk-duduk di sisi Nabi SAW, tiba-tiba seorang laki-laki datang kepada beliau lalu berkata, ”Wahai Rasulullah, saya binasa“. Beliau bertanya, ”Ada apa engkau ?”. Ia berkata, ”Saya menyetubuhi istri saya diwaktu puasa (Ramadlan)”. Kemudian Rasulullah SAW bersabda, ”Apakah kamu mempunyai budak yang bisa kamu merdekakan ?”. Ia menjawab, ”Tidak”. Beliau bersabda, ”Apakah kamu mampu untuk berpuasa dua bulan berturut-turut ?”. Ia menjawab, ”Tidak” . Beliau bersabda, “Apakah kamu dapat memberi makan enam puluh orang miskin ?”. Ia berkata, “Tidak”. (Abu Hurairah) berkata : Lalu orang tersebut diam di sisi Nabi SAW. Ketika kami dalam keadaan demikian itu tiba-tiba dibawakan satu ‘araq kurma kepada Nabi SAW. Adapun ‘araq maksudnya adalah miktal (keranjang). Beliau bersabda, “Dimana orang yang bertanya tadi ?”. Ia menjawab, “Saya”. Beliau bersabda, “Ambillah ini dan sedeqahkanlah”. Ia berkata kepada beliau, “Apakah kepada orang yang lebih faqir daripada saya, wahai Rasulullah ? Demi Allah, diantara dua tepian kota Madinah (yang ia maksud dua tanah berbatu hitam), tidak ada keluarga yang lebih miskin daripada keluarga saya”. Maka Nabi SAW tertawa sehingga nampak gigi taring beliau. Kemudian beliau bersabda, “Berikan makan keluargamu dengan kurma itu”. [HR. Bukhari 2 : 235]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَفَعَهُ: مَنْ اَفْطَرَ يَوْمًا مِنْ رَمَضَانَ مِنْ غَيْرِ عُذْرٍ وَلَا مَرَضٍ لَـمْ يَقْضِهِ صِيَامُ الدَّهْرِ وَاِنْ صَامَهُ. البخارى 2: 235"],["p","Dari Abu Hurairah, ia merafa’kannya (ia mengatakan dari Nabi SAW), “Barangsiapa berbuka satu hari pada bulan Ramadlan tanpa halangan dan bukan karena sakit, maka tidak bisa diganti dengan puasa selamanya, jika dia akan melakukannya”. [HR. Bukhari juz 2, hal. 235]"],["p","Tentang I’tikaf"],["a","وَلَا تُبَاشِرُوْهُنَّ وَاَنْتُمْ عَاكِفُوْنَ فِي الْمَسَاجِدِ، تِلْكَ حُدُوْدُ اللهِ فَلَا تَقْرَبُوْهَا. البقرة: 187"],["p","Janganlah kamu campuri mereka (istri-istrimu), sedang kamu beri`tikaf dalam mesjid. Itulah larangan Allah, maka janganlah kamu mendekatinya. [QS. Al-Baqarah: 187]"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ ﷺ اِذَا دَخَلَ الْعَشْرُ شَدَّ مِئْزَرَهُ وَاَحْيَا لَيْلَهُ وَاَيْقَظَ اَهْلَهُ. البخارى 2: 255"],["p","Dari ‘Aisyah RA, ia berkata, “Dahulu Rasulullah SAW apabila memasuki malam-malam sepuluh (akhir Ramadlan) beliau mengencangkan ikat pinggang (lebih meningkatkan ibadahnya), menghidupkan malamnya, dan membangunkan keluarganya”. [HR. Bukhari juz 2, hal. 255]"],["a","عَنْ عَبْدِ اللهِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ يَعْتَكِفُ الْعَشْرَ الْاَوَاخِرَ مِنْ رَمَضَانَ. البخارى 2: 255"],["p","Dari 'Abdullah bin ‘Umar RA, ia berkata, “Dahulu Rasulullah SAW beri’tikaf pada sepuluh hari terakhir dari bulan Ramadlan”. [HR. Bukhari juz 2, hal. 255]"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُوْلُ اللهِ ﷺ يَعْتَكِفُ فِيْ كُلِّ رَمَضَانَ. وَاِذَا صَلَّى الْغَدَاةَ دَخَلَ مَكَانَهُ الَّذِى اعْتَكَفَ فِيْهِ. قَالَ: فَاسْتَأْذَنَتْهُ عَائِشَةُ اَنْ تَعْتَكِفَ فَاَذِنَ لَـهَا فَضَرَبَتْ فِيْهِ قُبَّةً، فَسَمِعَتْ بِـهَا حَفْصَةُ فَضَرَبَتْ قُبَّةً، وَسَمِعَتْ زَيْنَبُ بِـهَا فَضَرَبَتْ قُبَّةً اُخْرَى. فَلَمَّا انْصَرَفَ رَسُوْلُ اللهِ ﷺ مِنَ الْغَدِ اَبْصَرَ اَرْبَعَ قِبَابٍ فَقَالَ: مَا هٰذَا؟ فَاُخْبِرَ خَبَرَهُنَّ. فَقَالَ: مَا حَمَلَهُنَّ عَلَى هٰذَا الْبِرُّ، اِنْزَعُوْهَا فَلَا اُرَاهَا. فَنُزِعَتْ فَلَمْ يَعْتَكِفْ فِيْ رَمَضَانَ حَتَّى اعْتَكَفَ فِيْ اٰخِرِ الْعَشْرِ مِنْ شَوَّالٍ. البخارى 2: 259"],["p","Dari ‘Aisyah RA, ia berkata : Dahulu Rasulullah SAW beri’tikaf pada setiap bulan Ramadlan. Setelah shalat Shubuh beliau masuk ke tempat i’tikafnya. (Perawi) berkata : Lalu ‘Aisyah minta ijin kepada beliau untuk beri’tikaf, maka beliau mengijinkannya. Kemudian ‘Aisyah membuat kemah. Kemudian Hafshah mendengar hal itu, lalu ia pun membuat kemah. Kemudian Zainab juga mendengar hal itu, maka iapun membuat kemah. Setelah Rasulullah SAW selesai shalat Shubuh, maka beliau melihat ada empat kemah, lalu beliau bertanya, “Ada apa ini ?”. Lalu beliau diberitahu bahwa itu adalah kemah-kemah istri-istri beliau. Lalu beliau bertanya, “Apa yang mendorong mereka berbuat demikian ? Apakah yang demikian itu kebaikan ? Bongkarlah kemah-kemah itu, karena aku melihatnya bukanlah kebaikan”. Lalu kemah-kemah itu dibongkar, dan beliau tidak jadi beri’tikaf Ramadlan (tahun itu), sehingga beliau beri’tikaf pada sepuluh hari akhir di bulan Syawwal. [HR. Bukhari juz 2, hal. 259]"],["p","Keterangan :"],["p","Di dalam riwayat lain disebutkan “sehingga beri’tikaf sepuluh hari yang awwal di bulan Syawwal”. Di dalam riwayat yang lain lagi disebutkan, “sehingga beliau beri’tikaf sepuluh hari di bulan Syawwal”, walloohu a’lam."],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ ﷺ اَنَّ النَّبِيَّ ﷺ كَانَ يَعْتَكِفُ الْعَشْرَ الْاَوَاخِرَ مِنْ رَمَضَانَ حَتَّى تَوَفَّاهُ اللهُ تَعَالَى، ثُـمَّ اعْتَكَفَ اَزْوَاجُهُ مِنْ بَعْدِهِ. البخارى 2: 255"],["p","Dari ‘Aisyah RA istri Nabi SAW, bahwasanya Nabi SAW beri’tikaf pada sepuluh hari terakhir dari bulan Ramadlan sehingga Allah Ta'aalaa mewafatkannya, kemudian istri-istri beliau beri’tikaf sesudahnya”. [HR. Bukhari juz 2, hal. 255]"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ النَّبِيُّ ﷺ يَعْتَكِفُ فِى الْعَشْرِ الْاَوَاخِرِ مِنْ رَمَضَانَ، فَلَمْ يَعْتَكِفْ عَامًا. فَلَمَّا كَانَ فِى الْعَامِ الْمُقْبِلِ اِعْتَكَفَ عِشْرِيْنَ. الترمذى 2: 148، ررقم: 800"],["p","Dari Anas bin Maalik, ia berkata, \"Dahulu Nabi SAW beri’tikaf pada sepuluh hari terakhir di bulan Ramadlan, dan beliau pernah satu tahun tidak beri’tikaf padanya. Kemudian tahun berikutnya beliau beri’tikaf selama dua puluh hari\". [HR. Tirmdzi juz 2, hal. 148, no. 800, dan ia berkata : Ini hadits hasan gharib shahih]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ ﷺ يَعْتَكِفُ فِيْ كُلِّ رَمَضَانَ عَشْرَةَ اَيَّامٍ. فَلَمَّا كَانَ الْعَامُ الَّذِيْ قُبِضَ فِيْهِ اِعْتَكَفَ عِشْرِيْنَ يَوْمًا. البخارى 2: 260"],["p","Dari Abu Hurairah RA, ia berkata, “Adalah Nabi SAW beri’tikaf pada setiap Ramadlan selama sepuluh hari. Maka ketika pada tahun dimana beliau wafat, beliau beri’tikaf selama dua puluh hari”. [HR. Bukhari juz 2, hal. 260]"],["a","عَنْ عَائِشَةَ اَنَّـهَا قَالَتْ: اَلسُّنَّةُ عَلَى الْمُعْتَكِفِ اَنْ لَا يَعُوْدَ مَرِيْضًا وَلَا يَشْهَدَ جَنَازَةً وَلَا يَـمَسَّ امْرَأَةً وَلَا يُبَاشِرَهَا، وَلَا يَخْرُجَ لِحَاجَةٍ اِلَّا لِمَا لَا بُدَّ مِنْهُ. وَلَا اعْتِكَافَ اِلَّا بِصَوْمٍ وَلَا اعْتِكَافَ اِلَّا فِيْ مَسْجِدٍ جَامِعٍ. ابو داود 2: 333، رقم: 2473"],["p","Dari ‘Aisyah, ia berkata, “Menurut sunnah, bahwa orang i‘tikaf itu tidak menjenguk orang sakit, tidak melayat, tidak menyentuh wanita, tidak mengumpulinya, dan tidak keluar (dari tempat i’tikaf) untuk sesuatu keperluan, kecuali sesuatu yang ia harus melakukannya. Dan tidak ada I'tikaf melainkan dengan puasa, dan tidak ada I'tikaf melainkan di masjid jami'”. [HR. Abu Dawud juz 2, hal. 333, no. 2473]"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ ﷺ قَالَتْ: وَاِنْ كَانَ رَسُوْلُ اللهِ ﷺ لَيُدْخِلُ عَلَيَّ رَأْسَهُ وَهُوَ فِى الْمَسْجِدِ فَاُرَجِّلُهُ، وَكَانَ لَا يَدْخُلُ الْبَيْتَ اِلَّا لِحَاجَةٍ اِذَا كَانَ مُعْتَكِفًا. البخارى 2: 260"],["p","Dari 'Aisyah RA istri Nabi SAW, ia berkata, \"Sungguh, dahulu Rasulullah SAW pernah menjulurkan kepala beliau (ke kamarku), sedangkan beliau berada di masjid, lalu aku menyisir rambut beliau. Dan dahulu apabila beri'tikaf, beliau tidak masuk rumah kecuali untuk suatu keperluan\". [HR. Bukhari juz 2, hal. 260]"],["p","~oO[ @ ]Oo~"]],"c20220417_1281":[["p","Ahad, 17 April 2022/15 Ramadlan1443 Brosur No. : 2076/2116/IF"],["h","ZAKAT FITHRAH"],["p","Pengertian zakat fithrah"],["p","Zakat fithrah ialah : zakat berupa makanan pokok dalam suatu daerah, yang dikeluarkan sebelum shalat 'Idul Fithri."],["p","Yang wajib mengeluarkan"],["p","Zakat fithrah diwajibkan kepada orang Islam, baik tua maupun muda, laki-laki atau perempuan, merdeka, budak bahkan kanak-kanak sekalipun, yang mempunyai kelebihan makanan pada malam hari raya serta siang harinya."],["p","Ukuran/kadarnya"],["p","Tiap-tiap jiwa sebanyak satu Sha' (kira-kira 2,5 kg atau 3 liter), dari makanan pokok yang biasa dimakan oleh orang di dalam daerah tersebut."],["p","Waktu pengeluaran"],["p","Dari terbenam matahari pada akhir Ramadlan/malam hari raya 'Idul Fithri sampai sebelum mulai shalat 'Id."],["a","عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: فَرَضَ رَسُوْلُ اللهِ ﷺ زَكَاةَ الْفِطْرِ صَاعًا مِنْ تَمْرٍ اَوْ صَاعًا مِنْ شَعِيْرٍ عَلَى الْعَبْدِ وَالْحُرِّ وَالذَّكَرِ وَالْاُنْثَى وَالصَّغِيْرِ وَالْكَبِيْرِ مِنَ الْمُسْلِمِيْنَ وَاَمَرَ بِـهَا اَنْ تُؤَدَّى قَبْلَ خُرُوْجِ النَّاسِ اِلىَ الصَّلَاةِ. البخارى 2: 138"],["p","Dari Ibnu Umar RA, ia berkata, “Rasulullah SAW mewajibkan zakat fithrah satu sha' (kira-kira 2,5 kg atau 3 liter) dari korma atau satu sha' dari gandum atas budak maupun orang merdeka, laki-laki, perempuan, kecil dan dewasa dari orang-orang Islam, dan beliau menyuruh supaya dikeluarkan zakat fithrah itu sebelum orang-orang keluar pergi shalat ('Idul Fithri)\". [HR. Bukhari juz 2, hal. 138]."],["p","Boleh pula dikeluarkan 1 atau 2 hari sebelum hari raya :"],["a","وَكَانُوْا يُعْطُوْنَ قَبْلَ الْفِطْرِ بِيَوْمٍ اَوْ يَوْمَيْنِ. البخارى 2: 139"],["p",".... dan mereka (para shahabat) memberikannya (zakat fithrah) satu atau dua hari sebelum ‘Idul Fithri. [HR. Bukhari juz 2, hal. 139]."],["p","Dengan dasar atsar (perbuatan) shahabat tersebut, ada sebagian 'ulama (antara lain Imam Syafi'i) yang berpendapat bahwa boleh pula mengeluarkan zakat fithrah sejak awwal Ramadlan; karena hadits Nabi diatas hanya menerangkan bahwa waktu pengeluaran zakat fithrah adalah sebelum mulai shalat 'Id, tanpa penjelasan kapan permulaannya. Sedang para shahabat ada yang mengeluarkan 1 bahkan 2 hari sebelum hari raya. Maka berdasar inilah sebagian ulama berpendapat bahwa mengeluarkan zakat fithrah itu sejak awwal Ramadlan sudah boleh dan sah."],["p","Sasaran zakat fithrah"],["p","Sasaran atau orang yang berhak menerima zakat fithrah adalah tidak berbeda dengan yang berhaq menerima zakat yang lain, yaitu sebagaimana yang tertera pada surat At-Taubah ayat 60 :"],["a","اِنَّمَا الصَّدَقٰتُ لِلْفُقَرَآءِ وَالْمَسٰكِيْنِ وَالْعَامِلِيْنَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوْبُـهُمْ وَفِى الرِّقَابِ وَالْغَارِمِيْنَ وَفِيْ سَبِيْلِ اللهِ وَابْنِ السَّبِيْلِ، فَرِيْضَةً مِّنَ اللهِ، وَاللهُ عَلِيْمٌ حَكِيْمٌ. التوبة:60"],["p","Sesungguhnya zakat-zakat itu, hanyalah untuk orang-orang fakir, orang-orang miskin, pengurus-pengurus zakat, para muallaf yang dibujuk hatinya, untuk (memerdekakan) budak, orang-orang yang berhutang, untuk jalan Allah dan orang-orang yang sedang dalam perjalanan, sebagai suatu ketetapan yang diwajibkan Allah, dan Allah Maha Mengetahui lagi Maha Bijaksana. [QS. At-Taubah : 60]."],["p","Keterangan :"],["p","Yang berhaq menerima zakat fithrah ialah :"],["p","1. اَلْفُقَرَآء (Orang-orang fakir)"],["p","Orang-orang yang di dalam penghidupannya untuk kebutuhan hidupnya sehari-hari, baik bagi dirinya sendiri dan atau orang yang menjadi tanggungannya, hanya mampu mencukupi kurang dari separoh keperluannya. Misalnya : Kebutuhan setiap harinya Rp. 100.000,- ia hanya mampu menyediakan Rp. 40.000,-"],["p","2. اَلْمَسٰكِيْن (orang-orang miskin). Yaitu sebagaimana nomor 1, tetapi lebih dari separoh, namun kurang dari kebutuhannya. Misalnya : Kebutuhan setiap harinya Rp. 100.000,- ia hanya mampu menyediakan Rp.60.000,- Demikian menurut pendapat sebagian 'ulama."],["p","3. اَلْعَامِلِيْن (orang-orang yang mengurusi zakat). Yaitu beberapa orang yang ahli tentang seluk-beluk zakat (hukum-hukumnya, barang-barang dan kadar masing-masing yang dizakati dan sebagainya) yang diangkat oleh Nabi SAW / Pimpinan ummat Islam dan bertugas sebagai penghitung dan penerima serta penagih zakat dari kaum muslimin untuk disalurkan sebagaimana mestinya. Walaupun ia bukan fakir/ miskin, namun berhaq menerima zakat."],["p","Catatan :"],["p","Tentang \"Panitia Zakat Fithrah\". Karena yang berhaq mengangkat dan menugaskan 'Amil adalah Nabi SAW / Pimpinan ummat Islam, maka kami berpendapat dan menyarankan, sebaiknya kita tidak mendudukkan diri sebagai 'amil, tetapi menjadi sukarelawan saja untuk membantu pemerintah dan masyarakat dalam pengelolaan zakat fithrah tersebut. Jika diantara anggota panitia itu ada orang yang fakir/miskin, maka mereka berhaq menerima zakat sebagai fakir/miskin, bukan sebagai 'amil."],["p","4.اَلْمُؤَلَّفَةُ قُلُوْبُـهُمْ (orang-orang yang dijinakkan hatinya). Yaitu :"],["p","a. Orang yang baru masuk Islam, agar makin mantap keislamannya."],["p","b. Orang yang diharapkan masuk Islam dan telah tampak tanda-tanda simpati dan perhatiannya terhadap Islam, ia berhaq menerima zakat tersebut agar makin memperlancar keislaman orang itu."],["p","c. Orang-orang yang sangat memusuhi Islam dan berpengaruh dalam masyarakat. Minimal diharapkan dengan pemberian zakat kepadanya itu, dapat memperlunak sikapnya atau menghentikan sama sekali permusuhannya terhadap Islam."],["p","Ketiga golongan diatas termasuk (اَلْمُؤَلَّفَة) yang berhaq menerima zakat, sekalipun mereka tergolong mampu dan bukan fakir/miskin."],["p","5. اَلرِّقَاب (budak-budak). Mereka berhaq mendapat bagian zakat untuk membebaskan dirinya dari cengkeraman perbudakan."],["p","6.اَلْغَارِمِيْن (orang-orang yang berhutang). Yaitu orang-orang Islam yang kesulitan dan kepayahan karena terbelit oleh hutang-hutangnya yang bukan disebabkan karena pemborosan/ma'shiyat (judi dan sebagainya). Golongan ini berhaq mendapat penyaluran zakat untuk melunasi hutangnya."],["p","7. سَبِيْل اللهِ (jalan Allah). Yaitu setiap sarana dan tempat serta orang-orang yang berhubungan dengan hal-hal yang berguna bagi agama maupun masyarakat luas. Misalnya : Masjid-masjid, sekolahan-sekolahan, madrasah-madrasah, lembaga-lembaga da'wah, tempat pengajian dan sebagainya, termasuk orang-orang yang menyelenggarakan serta mengurusinya. Dan juga termasuk sabiilillaah ialah hal-hal yang bermanfaat bagi kepentingan umum dan dibenarkan oleh agama, seperti mendirikan rumah sakit, gedung pertemuan, membangun jembatan dan sebagainya."],["p","8. اِبْن السَّبِيْلِ (orang yang dalam perjalanan/musafir). Yaitu orang yang dalam perjalanan, lalu putus bekal dan dikhawatirkan terlantar dalam perantauannya itu, maka yang demikian inipun berhaq menerima zakat untuk bekal pulang ke negeri/daerah asalnya. Hal ini dapat dimengerti dan diambil hikmah yang besar yang terkandung di dalamnya, yaitu antara lain :"],["p","Agar dimana saja orang Islam itu berada, ia selalu merasa mempunyai saudara seiman yang selalu siap menolongnya, sehingga ia tidak merasa asing di perantauannya tersebut."],["p","Beberapa masalah yang berkaitan dengan zakat fithrah"],["p","1. Yang dikeluarkan harus sesuai dengan kualitas yang biasa dimakannya sehari-hari. Misalnya bila sehari-hari ia makan makanan pokok tersebut dari kualitas nomor 1, maka tidak selayaknya ia mengeluarkan kualitas nomor 2 atau nomor 3. Jika sampai terjadi demikian berarti menyalahi jiwa perintah zakat yang antara lain bertujuan untuk mensucikan jiwa seseorang dari kekikiran hati serta menundukkan hawa nafsunya terhadap perintah Allah. Firman Allah :"],["a","خُذْ مِنْ اَمْوَالِـهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيْهِمْ بِـهَا. التوبة.103"],["p","Ambillah shadaqah dari sebagian harta mereka, dengan shadaqah itu kamu membersihkan dan mensucikan mereka. [QS. At-Taubah : 103]."],["p","Sebaliknya apabila ia mengeluarkan yang lebih baik dari pada apa yang biasa dimakan, yang demikian itu lebih baik baginya. Karena kelebihan dan kebaikannya itu akan kembali kepada pelakunya itu sendiri, sesuai dengan jiwa agama dan jiwa perintah zakat fithrah tersebut."],["p","Firman Allah dalam surat Al-Baqarah ayat 184 :"],["a","... فَمَنْ تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌلَّهٗ. البقرة:184"],["p","..... maka barangsiapa yang dengan kerelaan hati mengerjakan kebajikan, maka itulah yang lebih baik baginya. [QS. Al-Baqarah : 184]."],["p","2. Zakat fithrah tersebut dapat pula berwujud uang, senilai dengan zakat fithrah yang diwajibkan baginya. Misalnya: 1 liter = Rp. 9.000,- maka ia mengeluarkan untuk dirinya sendiri sejumlah 3 X Rp. 9.000,- = Rp. 27.000,-"],["p","3. Anak-anak dan orang-orang yang menjadi tanggungan seseorang, maka kewajiban zakat fithrah mereka dibebankan kepada orang yang menanggungnya (ayah/majikan dan sebagainya). Jadi merekalah yang berkewajiban mengeluarkan untuk anak-anak atau orang yang menjadi tanggungannya tersebut, bila mereka itu orang Islam."],["p","4. Ada sementara 'ulama yang berpendapat bahwa zakat fithrah itu hanya diperuntukkan bagi orang-orang miskin saja, bukan untuk yang lain, berdasar pemahaman terhadap hadits :"],["a","عَنِ ابْنِ عُمَرَ قَالَ: اَمَرَنَا رَسُوْلُ اللهِ ﷺ اَنْ نُخْرِجَ زَكَاةَ الْفِطْرِ وَيَقُوْلُ: اَغْنُوْهُمْ عَنْ طَوَافِ هٰذَا الْيَوْمِ. البيهقى 4: 175"],["p","Dari Ibnu ‘Umar, ia berkata : Rasulullah SAW menyuruh kami supaya mengeluarkan zakat fithrah dan beliau bersabda, \"Berilah kecukupan kepada mereka (orang-orang miskin) supaya mereka tidak minta-minta pada hari ini”. [HR. Al-Baihaqi juz 4, hal. 175]."],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: فَرَضَ رَسُوْلُ اللهِ ﷺ زَكَاةَ الْفِطْرِ طُهْرَةً لِلصَّائِمِ مِنَ اللَّغْوِ وَالرَّفَثِ وَطُعْمَةً لِلْمَسَاكِيْنِ. مَنْ اَدَّاهَا قَبْلَ الصَّلَاةِ فَهِيَ زَكَاةٌ مَقْبُوْلَةٌ، وَمَنْ اَدَّاهَا بَعْدَ الصَّلَاةِ فَهِيَ صَدَقَةٌ مِنَ الصَّدَقَاتِ. ابو داود 2: 111، رقم: 1609"],["p","Dari Ibnu 'Abbas, ia berkata, \"Rasulullah SAW mewajibkan zakat fithrah untuk pembersih bagi orang yang puasa dari perkataan sia-sia dan kotor (yang telah dikerjakannya), dan untuk memberi makan orang-orang miskin. Barangsiapa mengeluarkannya sebelum shalat hari raya, maka ia jadi zakat yang maqbul, dan barangsiapa mengeluarkannya sesudah shalat, maka ia jadi sedeqah diantara beberapa sedeqah\". [HR. Abu Dawud juz 2, hal. 111, no. 1609]."],["p","Penjelasan :"],["p","a. Zakat fithrah adalah termasuk bagian dari \"Zakat\", maka orang-orang yang berhaq menerima zakat adalah 8 golongan, sebagaimana diterangkan pada ayat 60 surat At-Taubah diatas."],["p","b. Surat At-Taubah ayat 60 itu didahului dengan huruf Hashr (pembatas) اِنَّمَا (hanyasanya), maksudnya “bila tidak demikian maka tidak\"."],["p","Dan sifat ayat tersebut umum yang berarti setiap shadaqah/zakat apa saja baik zakat maal (harta benda), zakat tanaman dan lain-lain, termasuk zakat fithrah ini, salurannya adalah 8 ashnaf (orang-orang yang berhaq menerima zakat) itu, sedang hadits-hadits diatas bukan merupakan takhshish (pengecualian) dari ayat tersebut."],["p","c. Jadi jelaslah bahwa hadits-hadits itu bukan bermakna \"Zakat fithrah\" itu wajib hanya diberikan untuk fakir/miskin agar mereka terbebas dari kelaparan (hadits nomor 1), dan \"Zakat fithrah itu sebagai pensuci bagi orang-orang yang berpuasa dan hanya diperuntukkan orang-orang miskin\" (hadits nomor 2), melainkan : \"Zakat fithrah itu ~bila memang keenam golongan yang lain kurang membutuhkan~ sebaiknya disalurkan kepada para fakir/miskin agar mereka terbebas dari cengkeraman kelaparan pada hari raya itu\". (hadits nomor1) dan : \"Zakat fithrah itu dapat mensucikan orang-orang yang berpuasa dari kekurangan-kekurangan dan kesalahan-kesalahan kecil yang mungkin dilakukannya ketika sedang berpuasa, dan boleh diperuntukkan bagi orang-orang yang miskin, disamping bagi yang lain dari 8 golongan tersebut diatas\"."],["p","d. Bila dengan dasar hadits tersebut orang menetapkan bahwa zakat fithrah itu hanya untuk orang miskin dengan alasan bahwa dalam kedua hadits itu yang disebutkan hanyalah orang miskin, lalu bagaimana dengan hadits Nabi yang diriwayatkan oleh Bukhari dibawah ini :"],["a","عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا اَنَّ النَّبِيَّ ﷺ بَعَثَ مُعَاذًا اِلَى الْيَمَنِ فَقَالَ: اُدْعُهُمْ اِلَى شَهَادَةِ اَنْ لَا اِلٰهَ اِلَّا اللهُ وَاَنِّيْ رَسُوْلُ اللهِ، فَاِنْ هُمْ اَطَاعُوْا لِذٰلِكَ فَاَعْلِمْهُمْ اَنَّ اللهَ افْتَرَضَ عَلَيْهِمْ خَمْسَ صَلَوَاتٍ فِيْ كُلِّ يَوْمٍ وَلَيْلَةٍ، فَاِنْ هُمْ اَطَاعُوْا لِذٰلِكَ فَاَعْلِمْهُمْ اَنَّ اللهَ افْتَرَضَ عَلَيْهِمْ صَدَقَةً فِيْ اَمْوَالِـهِمْ تُؤْخَذُ مِنْ اَغْنِيَائِهِمْ وَتُرَدُّ عَلَى فُقَرَائِهِمْ. البخارى 2 : 108"],["p","Dari Ibnu 'Abbas RA, bahwasanya Nabi SAW mengutus Mu'adz ke Yaman, Rasulullah SAW bersabda, \"Serulah mereka kepada syahadat bahwasanya tidak ada Tuhan selain Allah, dan bahwasanya aku adalah utusan Allah. Jika mereka telah mentha’ati hal itu, maka beritahukanlah kepada mereka bahwa Allah mewajibkan kepada mereka shalat lima waktu dalam sehari-semalam. Jika mereka mentha’ati hal itu, maka beritahukanlah kepada mereka bahwasanya Allah mewajibkan kepada mereka zakat dari harta benda mereka yang diambil dari orang-orang kaya mereka, dan diberikan kepada orang-orang faqir mereka\". [HR. Bukhari juz 2, hal. 108]."],["p","Hadits di atas maksudnya, bukanlah \"Zakat itu diambil dari orang-orang kaya/mampu dan diperuntukkan hanya bagi orang-orang fakir saja\". Walaupun bunyi di dalam hadits itu begitu, karena (jika demikian) ini bertentangan dengan ayat 60 surat At-Taubah dimuka. Maka jelaslah makna hadits ini, yaitu menekankan bahwa yang wajib mengeluarkan zakat adalah orang yang mampu, bukan orang yang fakir/miskin."],["p","5. Di muka dijelaskan bahwa batas akhir pengeluarannya adalah sebelum orang melaksanakan shalat 'Ied. Jika ia mengeluarkannya setelah shalat, berdosalah ia, karena berarti tidak melaksanakan kewajiban. Dan yang dikeluarkannya itu hanya dinilai sebagai suatu sedeqah sebagaimana sedeqah-sedeqah yang lain."],["p","Tegasnya, dia berdosa karena tidak membayar zakat fithrah, sedang yang dikeluarkannya itu dinilai sebagai sedeqah sunnah."],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: فَرَضَ رَسُوْلُ اللهِ ﷺ زَكَاةَ الْفِطْرِ طُهْرَةً لِلصَّائِمِ مِنَ اللَّغْوِ وَالرَّفَثِ وَطُعْمَةً لِلْمَسَاكِيْنِ. مَنْ اَدَّاهَا قَبْلَ الصَّلَاةِ فَهِيَ زَكَاةٌ مَقْبُوْلَةٌ. وَمَنْ اَدَّاهَا بَعْدَ الصَّلَاةِ فَهِيَ صَدَقَةٌ مِنَ الصَّدَقَاتِ. ابو داود و 2: 111، رقم: 1609"],["p","Dari Ibnu 'Abbas, ia berkata, “Rasulullah SAW mewajibkan zakat fithrah untuk pembersih bagi orang yang puasa dari perkataan sia-sia dan kotor (yang telah dikerjakannya), dan untuk memberi makan orang-orang miskin. Barangsiapa mengeluarkannya sebelum shalat (hari raya), maka ia jadi zakat yang maqbul, dan barangsiapa mengeluarkannya sesudah shalat, maka ia jadi satu sedeqah diantara beberapa sedeqah\". [HR. Abu Dawud juz 2, hal. 111, no. 1609]."],["p","6. Dalam masalah zakat fithrah ini diperbolehkan membentuk Panitia Zakat Fithrah (bukan 'amil) yang bekerja secara sukarela sebagai pengabdian terhadap masyarakat dan negara sebagaimana riwayat di bawah ini :"],["a","عَنْ نَافِعٍ اَنَّ عَبْدَ اللهِ بْنَ عُمَرَكَانَ يَبْعَثُ بِزَكَاةِ الْفِطْرِ اِلىَ الَّذِى تُجْمَعُ عِنْدَهُ قَبْلَ الْفِطْرِ بِيَوْمَيْنِ اَوْ ثَلَاثَةٍ. مالك 1: 285، رقم: 55"],["p","Dari Nafi', bahwasanya Abdullah bin 'Umar biasa mengirimkan zakat fithrah kepada orang yang mengumpulkan zakat sebelum hari raya 'Idul Fithri dua atau tiga hari\". [HR. Maalik dalam Al-Muwaththa’ juz 1, hal. 285, no 55]."],["p","Dalam masalah mengeluarkan zakat fithrah dari tangan yang berkewajiban, agama memberikan ketentuan batas akhir sebagaimana diterangkan diatas. Sedang mengenai zakat fithrah itu harus sampai kepada tangan yang berhaq menerima, agama tidak memberikan ketentuan yang pasti, ini diserahkan pada kita semua. Yang penting zakat fithrah itu harus ditunaikan oleh orang yang mengeluarkan sesuai dengan batas waktu yang telah ditentukan. Dan jika tidak ada hal yang memaksa untuk menunda sampainya kepada yang berhaq menerima dengan alasan yang dibenarkan oleh syara'/hukum agama, maka harus segera disampaikan sebagaimana mestinya. Namun bila ada kendala sehingga sampainya kepada yang berhaq menerima sesudah shalat hari raya, yang demikian ini pun tidak mengapa."],["p","Adapun kendala tersebut antara lain :"],["p","~ Karena kesulitan-kesulitan pengangkutan, lantaran banyaknya yang harus dibagikan dan yang diberi bagian."],["p","~ Karena jauhnya perjalanan yang harus ditempuh (di lain daerah) sehingga sampainya sesudah hari raya, karena zakat itu tidak mesti harus dibagikan dalam daerahnya sendiri, karena ada daerah lain yang lebih memerlukannya."],["p","~ Dan lain-lain sebab yang dibenarkan oleh syara'."],["p","7. Kadar/ukuran zakat fithrah yang normal."],["p","Kadar yang normal adalah satu sha' (kira-kira 2 1/2 kg atau 3 liter) atau jika dinilai dengan uang, maka yang senilai dengan itu, bagi tiap-tiap jiwa, baik dirinya sendiri maupun orang-orang Islam yang menjadi tanggungannya sebagaimana telah diterangkan di muka."],["p","Maka jika sisa dari keperluan sehari semalam itu kurang dari satu sha', tetapi lebih dari keperluan dirinya dan orang yang menjadi tanggungannya, bolehlah ia mengeluarkan sekedar sisa yang dipunyai itu, walaupun kurang dari satu sha'. Hal ini tetap dipandang sah serta telah menunaikan kewajiban agama, berdasarkan kepada Sabda Nabi SAW :"],["a","اِذَا اَمَرْتُكُمْ بِشَيْءٍ فَأْتُوْا مِنْهُ مَا اسْتَطَعْتُمْ. البخارى و مسلم"],["p","Apabila aku memerintahkan kamu untuk mengerjakan sesuatu, maka kerjakanlah dia semaksimalmu. [HR. Bukhari 8 : 142, dan Muslim 2 : 975]."],["p","8. Boleh pula mengeluarkan zakat fithrah bagi bayi yang menjadi tanggungannya yang masih di dalam kandungan ibunya, beralasan dengan riwayat sebagai berikut :"],["a","عَنْ اَبِيْ قِلَابَةَ قَالَ: كَانَ يُعْجِبُهُمْ اَنْ يُعْطُوْا زَكَاةَ الْفِطْرِ عَنِ الصَّغِيْرِ وَالْكَبِيْرِ حَتَّى عَلَى الْحَبَلِ فِيْ بَطْنِ اُمِّهِ. عبد الرزاق 3: 319، رقم: 5788"],["p","Dari Abu Qilabah, ia berkata : Dahulu shahabat-shahabat Nabi SAW suka mengeluarkan zakat fithrah untuk anak-anak kecil dan dewasa, hingga untuk bayi yang masih dalam kandungan ibunya. [HR. ‘Abdurrazzaaq juz 3, hal. 319, no. 5788]."],["p","Arti fakir, miskin menurut hadits"],["a","مَنْ سَأَلَ وَعِنْدَهُ مَا يُغْنِيْهِ فَاِنَّمَا يَسْتَكْثِرُ مِنْ جَمْرِ جَهَنَّمَ. قَالَ: يَا رَسُوْلَ اللهِ، وَمَا يُغْنِيْهِ ؟ قَالَ: مَا يُغَدِّيْهِ وَيُعَشِّيْهِ. ابن حبان 1: 271، رقم: 545"],["p","Barangsiapa meminta-minta padahal ia mempunyai (makanan) yang mencukupi baginya, maka hanyalah ia memperbanyak bara api jahannam. Shahabat bertanya, \"Ya Rasulullah, apa yang mencukupi baginya itu ?\". Beliau bersabda, \"Yaitu yang cukup untuk dimakan pada siangnya dan malamnya\". [HR. Ibnu Hibban juz 1, hal. 271, no. 545]."],["p","Ucapan orang yang menerima zakat"],["a","عَنْ عَبْدِ اللهِ بْنِ اَبِيْ اَوْفَى قَالَ: كَانَ النَّبِيُّ ﷺ اِذَا اَتَاهُ قَوْمٌ بِصَدَقَتِهِمْ قَالَ: اَللّٰهُمَّ صَلِّ عَلَى اٰلِ فُلَانٍ، فَاَتَاهُ اَبِيْ بِصَدَقَتِهِ. فَقَالَ: اَللّٰهُمَّ صَلِّ عَلَى اٰلِ اَبِيْ اَوْفَى. البخارى 2: 136"],["p","Dari ‘Abdullah bin Abu Aufa, ia berkata, \"Dahulu Nabi SAW, apabila ada suatu kaum datang kepada beliau untuk menyerahkan zakat mereka, beliau mengucapkan Alloohumma sholli 'alaa aali fulaan (Ya Allah berilah shalawat kepada keluarga si Fulan). Kemudian ayahku (Abu Aufa) datang kepada beliau untuk menyerahkan zakatnya, lalu Nabi SAW mengucapkan Alloohumma sholli 'alaa aali abii aufaa (Ya Allah berilah shalawat kepada keluarganya Abu Aufa)\". [HR. Bukhari juz 2, hal. 136]"],["p","Zakat fithrah di zaman Rasulullah SAW"],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِيِّ قَالَ: كُنَّا نُخْرِجُ اِذْ كَانَ فِيْنَا رَسُوْلُ اللهِ ﷺ زَكَاةَ الْفِطْرِ عَنْ كُلِّ صَغِيْرٍ وَكَبِيْرٍ حُرٍّ اَوْ مَـمْلُوْكٍ صَاعًا مِنْ طَعَامٍ اَوْ صَاعًا مِنْ اَقِطٍ اَوْ صَاعًا مِنْ شَعِيْرٍ اَوْ صَاعًا مِنْ تَـمْرٍ اَوْ صَاعًا مِنْ زَبِيْبٍ. فَلَمْ نَزَلْ نُخْرِجُهُ حَتَّى قَدِمَ عَلَيْنَا مُعَاوِيَةُ بْنُ اَبِيْ سُفْيَانَ حَاجًّا اَوْ مُعْتَمِرًا. فَكَلَّمَ النَّاسَ عَلَى الْمِنْبَرِ، فَكَانَ فِيْمَا كَلَّمَ بِهِ النَّاسَ اَنْ قَالَ: اِنِّيْ اُرَى اَنَّ مُدَّيْنِ مِنْ سَمْرَاءِ الشَّامِ تَعْدِلُ صَاعًا مِنْ تَـمْرٍ. فَاَخَذَ النَّاسُ بِذٰلِكَ. قَالَ اَبُوْ سَعِيْدٍ: فَاَمَّا اَنَا فَلَا اَزَالُ اُخْرِجُهُ كَمَا كُنْتُ اُخْرِجُهُ اَبَدًا مَا عِشْتُ. مسلم 2: 678 رقم: 18"],["p","Dari Abu Sa’id Al-Khudriy, ia berkata : Ketika Rasulullah SAW masih berada di tengah-tengah kami, biasa kami mengeluarkan zakat fithrah dari setiap anak kecil dan orang dewasa, merdeka atau budak, satu sha’ makanan atau satu sha’ keju, atau satu sha’ gandum, atau satu sha’ kurma, atau satu sha’ anggur kering. Kami selalu mengeluarkannya seperti itu, hingga Mu’awiyah bin Abu Sufyan datang ke kota kami (Makkah) untuk berhajji atau ‘umrah. Dia berbicara di atas mimbar kepada kaum muslimin. Diantara pidatonya, dia mengatakan, “Aku berpendapat, bahwa dua mud gandum Syam nilainya sebanding dengan satu sha’ kurma (1 sha’ = 4 mud). Maka orang-orang pun berpegang pada pendapat itu. Abu Sa’id berkata, “Sedangkan aku tetap mengeluarkan seperti dulu, selamanya sepanjang hidupku”. [HR Muslim juz 2, hal. 678, no. 18]"],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِيِّ اَنَّ مُعَاوِيَةَ لَمَّا جَعَلَ نِصْفَ الصَّاعِ مِنَ الْحِنْطَةِ عَدْلَ صَاعٍ مِنْ تَـمْرٍ اَنْكَرَ ذٰلِكَ اَبُوْ سَعِيْدٍ وَقَالَ: لَا اُخْرِجُ فِيْهَا اِلَّا الَّذِيْ كُنْتُ اُخْرِجُ فِيْ عَهْدِ رَسُوْلِ اللهِ ﷺ صَاعًا مِنْ تَـمْرٍ اَوْ صَاعًا مِنْ زَبِيْبٍ اَوْ صَاعًا مِنْ شَعِيْرٍ اَوْ صَاعًا مِنْ اَقِطٍ.مسلم 2: 679 رقم:21"],["p","Dari Abu Sa’id Al-Khudriy, bahwasanya ketika Mu’awiyah menjadikan setengah sha’ hinthah (gandum yang kualitasnya bagus) sama dengan satu sha’ kurma, maka Abu Sa’id mengingkari hal itu dan berkata, “Aku tidak akan mengeluarkan zakat fithrah, kecuali seperti yang biasa aku keluarkan pada masa Rasulullah SAW, yaitu satu sha’ kurma, atau satu sha’ anggur kering, atau satu sha’ gandum sya’ir, atau satu sha’ keju”. [HR Muslim juz 2, hal. 679, no. 21]"],["p","Boleh menerima pemberian yang tidak meminta."],["a","عَنْ سَالِمِ بْنِ عَبْدِ اللهِ عَنْ اَبِيْهِ اَنَّ رَسُوْلَ اللهِ ﷺ يُعْطِى عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ الْعَطَاءَ، فَيَقُوْلُ لَهُ عُمَرُ: اَعْطِهِ يَا رَسُوْلَ اللهِ اَفْقَرَ اِلَيْهِ مِنِّيْ. فَقَالَ لَهُ رَسُوْلُ اللهِ ﷺ : خُذْهُ فَتَمَوَّلْهُ اَوْ تَصَدَّقْ بِهِ، وَمَا جَاءَكَ مِنْ هٰذَا الْمَالِ وَاَنْتَ غَيْرُ مُشْرِفٍ وَلَا سَائِلٍ فَخُذْهُ، وَمَا لَا، فَلَا تُتْبِعْهُ نَفْسَكَ. قَالَ سَالِـمٌ: فَمِنْ اَجْلِ ذٰلِكَ كَانَ ابْنُ عُمَرَ لَا يَسْأَلُ اَحَدًا شَيْئًا وَلَا يَرُدُّ شَيْئًا اُعْطِيَهُ. مسلم 2: 723 رقم:111"],["p","Dari Salim bin 'Abdullah, dari ayahnya ('Abdullah bin 'Umar) bahsawanya Rasulullah SAW pernah memberi pemberian kepada 'Umar bin Khaththab RA, lalu 'Umar berkata kepada beliau, \"Berikanlah kepada orang yang lebih membutuhkan daripada saya\". Lalu Rasulullah SAW bersabda, \"Terimalah saja sebagai hartamu, atau kamu bisa bersedeqah dengannya. Dan apa yang datang kepadamu seperti pemberian ini, sedangkan kamu tidak menginginkan dan tidak memintanya, maka terimalah. Adapun yang tidak begitu, maka janganlah kamu menuruti nafsumu\". Salim berkata, \"Oleh karena itu Ibnu 'Umar tidak pernah meminta sesuatu kepada seseorangpun dan tidak pula menolak sesuatu yang diberikan kepadanya\". [HR. Muslim juz 2, hal. 723, no. 111]."],["p","--oo0oo--"]],"c20220424_1282":[["p","Ahad, 24 April 2022/22 Ramadlan1443 Brosur No. : 2077/2117/IF"],["h","SHALAT 'IED"],["p","Adab mengerjakan shalat 'Ied dan sunnah-sunnahnya"],["h","1. Mandi dahulu"],["a","عَنِ ابْنِ السَّبَّاقِ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: يَا مَعْشَرَ الْمُسْلِمِيْنَ، اِنَّ هٰذَا (يَوْمَ الْجُمُعَةِ) يَوْمٌ جَعَلَهُ اللهُ عِيْدًا فَاغْسِلُوْا. مالك فى الموطأ 1: 65، رقم: 113"],["p","Dari Ibnus Sabbaaq, bahwasanya Rasulullah SAW bersabda, \"Hai kaum Muslimin, hari (Jum'ah) ini adalah satu hari yang Allah jadikan Hari Raya. Karena itu hendaklah kalian mandi\". [HR. Maalik, dalam Al-Muwaththa’ juz 1, hal. 65, no. 113]"],["p","Keterangan :"],["p","Menurut hadits tersebut, hari Jum'ah dipandang sebagai Hari Raya dan kita disuruh mandi padanya. Dengan demikian dapat difaham, bahwa mandi pada Hari Raya adalah lebih utama."],["h","2. Berpakaian dengan pakaian yang baik, bila ada"],["a","عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنْ اَبِيْهِ عَنْ جَدِّهِ اَنَّ النَّبِيَّ ﷺ كَانَ يَلْبَسُ بُرْدَ حِبَرَةٍ فِيْ كُلِّ عِيْدٍ. البيهقى 3: 280"],["p","Dari Ja’far bin Muhammad, dari ayahnya, dari kakeknya, bahwasanya Nabi SAW biasa memakai kain buatan Yaman pada tiap-tiap Hari Raya. [HR. Baihaqiy juz 3, hal. 280, dla'if, mursal]"],["h","3. Makan sebelum berangkat"],["a","عَنْ عَبْدِ اللهِ بْنِ بُرَيْدَةَ عَنْ اَبِيْهِ قَالَ: كَانَ النَّبِيُّ ﷺ لَا يَخْرُجُ يَوْمَ الْفِطْرِ حَتَّى يَطْعَمَ وَلَا يَطْعَمُ يَوْمَ الْاَضْحَى حَتَّى يُصَلِّيَ. الترمذى 2: 27، رقم: 540"],["p","Dari ‘Abdullah bin Buraidah, dari ayahnya, ia berkata, \"Dahulu Rasulullah SAW tidak pergi shalat Hari Raya 'Iedul Fithri melainkan sesudah makan. Dan tidak makan pada Hari Raya 'Iedul Adlha melainkan sesudah kembali dari shalat\". [HR. Tirmidzi juz 2, hal. 27, no. 540]"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ اَنَّ النَّبِيَّ ﷺ كَانَ يُفْطِرُ عَلَى تَـمَرَاتٍ يَوْمَ الْفِطْرِ قَبْلَ اَنْ يَخْرُجَ اِلَى الْمُصَلَّى. الترمذى 2: 27، رقم: 541"],["p","Dari Anas bin Malik, bahwasanya Nabi SAW dahulu makan beberapa kurma pada Hari Raya 'Iedul Fithri sebelum berangkat ke tempat shalat. [HR. Tirmidzi juz 2, hal. 27, no. 541, ia berkata : Ini hadits hasan shahih gharib]"],["h","4. Mengambil dua jalan"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ اِذَا خَرَجَ يَوْمَ الْعِيْدِ فِيْ طَرِيْقٍ رَجَعَ فِيْ غَيْرِهِ. الترمذى 2: 26، رقم: 539"],["p","Dari Abu Hurairah, ia berkata \"Dahulu Rasulullah SAW apabila melewati jalan saat pergi shalat Hari Raya, maka ketika pulang beliau mengambil jalan lain (dari yang telah dilalui waktu pergi)\". [HR. Tirmidzi juz 2, hal. 26, no. 539, hadits hasan gharib]"],["h","5. Waktu dan tempat takbir Hari Raya"],["a","عَنِ الزُّهْرِيِّ اَنَّهُ قَالَ:كَانَ النَّبِيُّ ﷺ يَخْرُجُ يَوْمَ الْفِطْرِ فَيُكَبِّرُ مِنْ حِيْنِ يَخْرُجُ مِنْ بَيْتِهِ حَتَّى يَأْتِيَ الْمُصَلَّى. ابو بكر النجاد، مرسل فى نيل الاوطار 3: 327"],["p","Dari Az-Zuhriy, ia berkata, \"Dahulu Nabi SAW keluar untuk shalat Hari Raya 'Iedul Fithri dengan takbir mulai dari rumahnya hingga tiba ditempat shalat\". [HR. Abu Bakar An-Najjaad, mursal, Nailul Authar juz 3, hal. 327]"],["a","عَنْ سَالِـمِ بْنِ عَبْدِ اللهِ اَنَّ عَبْدَ اللهِ بْنَ عُمَرَ اَخْبَرَهُ اَنَّ رَسُوْلَ اللهِ ﷺ كَانَ يُكَبِّرُ يَوْمَ الْفِطْرِ مِنْ حِيْنِ يَخْرُجُ مِنْ بَيْتِهِ حَتَّى يَأْتِيَ الْمُصَلَّى. البيهقى 3: 279"],["p","Dari Salim bin 'Abdullah, bahwasanya 'Abdullah bin 'Umar memberitahukan kepadanya, bahwasanya dahulu Rasulullah SAW bertakbir pada Hari Raya 'Iedul Fithri dari sejak keluar dari rumah beliau hingga tiba di tempat shalat. [HR. Baihaqi juz 3, hal. 279, dla’if karena dalam sanadnya ada perawi bernama Musa bin Muhammad bin 'Atho' dan Al-Walid bin Muhammad Al-Muqriy]"],["a","عَنْ نَافِعٍ اَنَّ ابْنَ عُمَرَ كَانَ يَغْدُوْ اِلَى الْعِيْدِ مِنَ الْمَسْجِدِ وَكَانَ يَرْفَعُ صَوْتَهُ بِالتَّكْبِيْرِ حَتَّى يَأْتِيَ الْمُصَلَّى وَيُكَبِّرُ حَتَّى يَأْتِيَ الْاِمَامُ. البيهقى 3: 279، موقوف"],["p","Dari Nafi' bahwasanya dahulu Ibnu 'Umar berangkat ke shalat 'Ied dengan bertakbir dengan suara keras sejak dari masjid sampai tiba di tempat shalat, dan ia terus bertakbir hingga imam datang. [HR. Baihaqi juz 3, hal. 279, mauquf]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: زَيِّنُوْا اَعْيَادَكُمْ بِالتَّكْبِيْرِ. الطبراني فى الاوسط 5: 189، رقم: 4370"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Hiasilah Hari Raya-Hari Raya kalian dengan takbir\". [HR. Thabarani di dalam Al-Mu'jamul Ausath juz 5, hal. 189, no. 4370, dla'if karena di dalam sanadnya ada perawi bernama 'Umar bin Rasyid, yang dilemahkan oleh Ibnu Ma'in, Abu Zur'ah dan Nasaiy]"],["p","Waktu dan tempat bertakbir Hari Raya menurut hadits yang shahih"],["a","عَنْ اُمِّ عَطِيَّةَ قَالَتْ: اَمَرَ رَسُوْلُ اللهِ ﷺ اَنْ نُخْرِجَهُنَّ فيِ الْفِطْرِ وَالْاَضْحَى الْعَوَاطِقَ وَالْحُيَّضَ وَذَوَاتِ الْخُدُوْرِ، فَاَمَّا الْحُيَّضُ فَيَعْتَزِلْنَ الصَّلَاةَ. مسلم 2: 606 رقم: 12"],["p","Dari Ummu 'Athiyah, ia berkata, \"Rasulullah SAW memerintahkan kepada kami untuk membawa keluar anak-anak perempuan yang hampir baligh, perempuan-perempuan yang haidl dan juga gadis-gadis dalam pingitan, pada Hari Raya 'Iedul Fithri dan 'Iedul Adlha. Adapun wanita-wanita yang haidl itu mereka tidak shalat\". [HR. Muslim, juz 2, hal. 606, no. 12]"],["a","عَنْ حَفْصَةَ عَنْ اُمِّ عَطِيَّةَ قَالَتْ: كُنَّا نُؤْمَرُ اَنْ نَخْرُجَ يَوْمَ الْعِيْدِ حَتَّى نُخْرِجَ الْبِكْرَ مِنْ خِدْرِهَا حَتَّى نُخْرِجَ الْحُيَّضَ، فَيَكُنَّ خَلْفَ النَّاسِ فَيُكَبِّرْنَ بِتَكْبِيْرِهِمْ وَيَدْعُوْنَ بِدُعَائِهِمْ يَرْجُوْنَ بَرَكَةَ ذٰلِكَ الْيَوْمِ وَطُهْرَتَهُ. البخارى 2: 7"],["p","Dari Hafshah, dari Ummi 'Athiyah, ia berkata, \"Dahulu kami diperintahkan untuk keluar pada Hari Raya (ke tempat shalat 'Ied), sehingga kami mengeluarkan para gadis yang dalam pingitannya, sehingga kami mengeluarkan para wanita yang sedang haidl, lalu mereka berada di tempat belakang para jama'ah, mereka para wanita bertakbir dengan takbir mereka, berdo'a dengan do'a mereka, para wanita itu mengharapkan berkahnya pada hari itu dan kesuciannya (dari dosa)\". [HR. Bukhari juz 2, hal. 7]"],["p","Dari hadits shahih di atas dapat kita fahami bahwa takbir Hari Raya itu dilaksanakan pada waktu tiba di tempat shalat sampai berdirinya shalat."],["h","6. Waktu shalat Hari Raya"],["a","قَالَ جُنْدَبٌ:كَانَ النَّبِيُّ ﷺ يُصَلِّى بِنَا يَوْمَ الْفِطْرِ وَالشَّمْسُ عَلَى قَيْدِ رُمْحَيْنِ وَالْاَضْحَى عَلَى قَيْدِ رُمْحٍ. احمد بن حسن، في نيل الاوطار 3: 333"],["p","Telah berkata Jundab, \"Adalah Nabi SAW shalat Hari Raya 'Iedul Fithri bersama kami di waktu matahari tingginya sekadar dua batang tombak dan beliau shalat Hari Raya 'Iedul Adlha diwaktu matahari tingginya sekadar satu batang tombak\". [HR. Ahmad bin Hasan, dalam Nailul Authar juz 3, hal. 333]"],["p","Keterangan :"],["p","Menurut riwayat di atas, waktu shalat Hari Raya 'Iedul Adlha itu lebih pagi daripada waktu shalat Hari Raya 'Iedul Fithri."],["h","7. Shalat sebelum khutbah"],["a","عَنِ ابْنِ عُمَرَ قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ وَاَبُوْ بَكْرٍ وَعُمَرُ رَضِيَ اللهُ عَنْهُمَا يُصَلُّوْنَ الْعِيْدَيْنِ قَبْلَ الْخُطْبَةِ. البخارى 2: 5"],["p","Dari Ibnu ‘Umar, ia berkata, \"Dahulu Rasulullah SAW, Abu Bakar dan ‘Umar RA shalat dua Hari Raya sebelum khutbah\". [HR. Bukhari juz 2, hal. 5]"],["p","Maksudnya : Rasulullah SAW dan shahabat-shahabatnya mengerjakan shalat 'Iedul Fithri dan 'Iedul Adha sebelum khutbah."],["h","8. Shalat Hari Raya tanpa adzan dan iqamah"],["a","عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ ﷺ الْعِيْدَيْنِ غَيْرَ مَرَّةٍ وَلَا مَرَّتَيْنِ بِغَيْرِ اَذَانٍ وَلَا اِقَامَةٍ. مسلم 2: 604"],["p","Dari Jabir bin Samurah, ia berkata \"Saya shalat dua Hari Raya bersama Rasulullah SAW bukan hanya sekali atau dua kali, (semuanya) tanpa adzan dan iqamah\". [HR. Muslim juz 2, hal. 604, no. 7]"],["p","Keterangan :"],["p","Maksud dari riwayat di atas menunjukkan bahwa Rasulullah SAW shalat Hari Raya 'Iedul Fithri dan Hari Raya 'Iedul Adha tanpa adzan dan iqamah."],["h","9. Hari Raya pada hari Jum'ah"],["a","عَنِ ابْنِ عَبَّاسٍ عَنْ رَسُوْلِ اللهِ ﷺ اَنَّهُ قَالَ: اِجْتَمَعَ عِيْدَانِ فيِ يَوْمِكُمْ هٰذَا، فَمَنْ شَاءَ اَجْزَأَهُ مِنَ الْجُمُعَةِ وَاِنَّا مُجَمِّعُوْنَ اِنْ شَاءَ اللهُ. ابن ماجه 1: 416، رقم: 1311"],["p","Dari Ibnu ‘Abbas, dari Rasulullah SAW, beliau bersabda, \"Telah terhimpun pada hari ini dua Hari Raya (Hari Raya dan Jum'ah). Maka barangsiapa mau, cukuplah shalat ini buat dia, tidak perlu lagi shalat Jum'ah, tetapi kami tetap akan mendirikan shalat Jum'ah, insyaa-Allooh\". [HR. Ibnu Majah juz 1, hal. 416, no. 1311]"],["h","10. Shalat dan khutbah di tanah lapang"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ اَنَّ النَّبِيَّ ﷺ كَانَ يُفْطِرُ عَلَى تَمَرَاتٍ يَوْمَ الْفِطْرِ قَبْلَ اَنْ يَخْرُجَ اِلىَ الْمُصَلَّى. الترمذى 2: 27، رقم: 541"],["p","Dari Anas bin Maalik, bahwasanya dahulu pada Hari Raya 'iedul Fithri Nabi SAW biasa makan beberapa kurma sebelum berangkat ke Mushalla (tempat shalat Hari Raya). [HR. Tirmidzi juz 2, hal. 27, no. 541, ia berkata : Ini hadits hasan shahih gharib]"],["p","Keterangan :"],["p","Dari hadits tersebut bisa difahami bahwa dahulu Nabi SAW mengadakan shalat Hari Raya di Mushalla (tanah lapang)."],["p","Diriwayatkan bahwa Nabi SAW pernah shalat 'ied di masjid ketika hujan :"],["a","عَنْ اَبِيْ هُرَيْرَةَ اَنَّهُ اَصَابَهُمْ مَطَرٌ فِيْ يَوْمِ عِيْدٍ فَصَلَّى بِـهِمُ النَّبِيُّ ﷺ صَلَاةَ الْعِيْدِ فيِ الْمَسْجِدِ. ابو داود 1: 301 رقم: 1160، ضعيف"],["p","Dari Abu Hurairah, bahwasanya pada suatu Hari Raya, para shahabat kehujanan, maka Nabi SAW mengerjakan shalat Hari Raya bersama mereka di masjid. [HR. Abu Dawud juz 1, hal. 301, no. 1160, dla’if karena dalam sanadnya ada perawi bernama 'Isa bin 'Abdul A'laa bin Abu Farwah, ia majhul]"],["p","Keterangan :"],["p","Menurut kebiasaan memang Nabi SAW mengerjakan shalat dan khutbah Hari Raya di tanah lapang. Tetapi hal itu tidak menunjukkan kepada hukum wajib. Sesuatu perbuatan bisa menunjukkan kepada hukum wajib jika disertai dengan perintah."],["p","Kebanyakan ulama memandang bahwa Nabi SAW mengerjakan yang demikian itu bukan karena tidak shah dikerjakan di masjid, tetapi karena tak cukup tempat di masjid, sebab pada waktu itu orang-orang yang berkumpul pada Hari Raya lebih banyak dari pada hari-hari yang lain."],["p","Dari seluruh pembicaraan tersebut, nyatalah bahwa shalat Hari Raya di masjid itu tidak dilarang, apalagi jika turun hujan atau lain-lain halangan. Oleh karena itu perkataan Abu Hurairah tadi walaupun lemah riwayatnya tetapi shahih maknanya. Perlu dijelaskan bahwa Rasulullah SAW shalat di tanah lapang itu diambil dari pengertian Mushalla. Adapun Mushalla di zaman Nabi SAW dijelaskan dalam kitab Fiqhus Sunnah sebagai berikut :"],["a","اَلْمُصَلَّى مَوْضِعٌ بِبَابِ الْمَدِيْنَةِ الشَّرْقِيِّ. فقه السنة 1: 268"],["p","\"Mushalla itu adalah suatu tempat di pintu gerbang Madinah sebelah timur\". [Fiqhus Sunnah juz 1, hal. 268]"],["a","اَلْمُصَلَّى مَوْضِعٌ بَيْنَهُ وَبَيْنَ الْمَسْجِدِ اَلْفَ ذِرَاعٍ. فقه السنة 1: 271"],["p","\"Mushalla itu tempatnya berjarak 1.000 hasta dari masjid Madinah\". [Fiqhus Sunnah juz 1, ha. 271]"],["p","Dengan keterangan ini, jelaslah bahwa Rasulullah SAW biasanya mengadakan shalat Hari Raya itu di tanah lapang."],["p","11. Khutbah Nabi SAW :"],["a","عَنْ عَبْدِ الرَّحْمٰنِ قَالَ سَمِعْتُ ابْنَ عَبَّاسٍ قَالَ خَرَجْتُ مَعَ النَّبِيِّ ﷺ يَوْمَ فِطْرٍ اَوْ اَضْحًى فَصَلَّى الْعِيْدَ ثُـمَّ خَطَبَ، ثُـمَّ اَتَى النِّسَاءَ فَوَعَظَهُنَّ وَذَكَّرَهُنَّ وَاَمَرَهُنَّ بِالصَّدَقَةِ. البخارى 2: 8"],["p","Dari 'Abdur Rahman, ia berkata : Aku mendengar Ibnu 'Abbas berkata, \"Aku pernah keluar bersama Nabi SAW pada Hari Raya 'Iedul Fithri atau 'Iedul Adlha, lalu beliau shalat 'Ied, kemudian berkhutbah. Kemudian beliau datang ke tempat para wanita, memberikan nasehat kepada mereka, mengingatkan mereka, dan menganjurkan kepada mereka untuk bershadaqah\". [HR. Bukhari juz 2, hal. 8]"],["a","عَنِ ابْنِ جُرَيْجٍ قَالَ اَخْبَرَنِيْ عَطَاءٌ عَنْ جَابِرِ بْنِ عَبْدِ اللهِ، قَالَ سَمِعْتُهُ يَقُوْلُ: قَامَ النَّبِيُّ ﷺ يَوْمَ الْفِطْرِ فَصَلَّى، فَبَدَأَ بِالصَّلَاةِ ثُمَّ خَطَبَ. فَلَمَّا فَرَغَ نَزَلَ فَأَتَى النِّسَاءَ فَذَكَّرَهُنَّ وَهُوَ يَتَوَكَّأُ عَلَى بِلَالٍ وَبِلَالٌ بَاسِطٌ ثَوْبَهُ يُلْقِيْ فِيْهِ النِّسَاءُ الصَّدَقَةَ. قُلْتُ لِعَطَاءٍ: زَكَاةَ يَوْمِ الْفِطْرِ؟ قَالَ: لَا وَلٰكِنْ صَدَقَةً يَتَصَدَّقْنَ حِيْنَئِذٍ تُلْقِيْ فَتَخَهَا وَيُلْقِيْنَ. قُلْتُ: اَتُرَى حَقًّا عَلَى الْاِمَامِ ذٰلِكَ وَيُذَكِّرُهُنَّ؟ قَالَ: اِنَّهُ لَحَقٌّ عَلَيْهِمْ، وَمَا لَـهُمْ لَا يَفْعَلُوْنَهُ. البخارى 2: 9"],["p","Dari ibnu Juraij, ia berkata : 'Atho' mengkhabarkan kepadaku dari Jabir bin 'Abdullah, ia mengatakan bahwa Jabir berkata : Nabi SAW melaksanakan shalat Hari Raya 'Iedul Fithri, yang mula-mula beliau lakukan adalah shalat, kemudian berkhutbah. Setelah selesai khutbah, beliau turun lalu datang ke tempat para wanita, beliau memberikan nasehat dan mengingatkan mereka dengan berpegang pada Bilal, sedangkan Bilal membentangkan kainnya, dan para wanita lalu memberikan shadaqahnya. (Ibnu Juraij berkata). Aku bertanya kepada 'Atho', \"Apakah yang mereka berikan itu zakat fithrah ?\". Ia menjawab, \"Bukan, tetapi shadaqah yang para wanita bershadaqah pada waktu itu. Ada wanita yang memberikan gelangnya, dan mereka para wanita memberikan shadaqahnya\". (Ibnu Juraij berkata) : Aku bertanya (kepada 'Atho'), \"Apakah kewajiban imam melakukan demikian itu, memberi nasehat kepada para wanita ?\". ('Atho' menjawab), \"Ya, itu adalah kewajiban mereka, tetapi entah mengapa mereka sekarang tidak melakukannya\". [HR. Bukhari juz 2, hal. 9]"],["a","عَنْ سَعِيْدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ اَنَّ النَّبِيَّ ﷺ صَلَّى يَوْمَ الْفِطْرِ رَكْعَتَيْنِ، لَـمْ يُصَلِّ قَبْلَهَا وَلَا بَعْدَهَا. ثُـمَّ اَتَى النِّسَاءَ وَمَعَهُ بِلَالٌ فَاَمَرَهُنَّ بِالصَّدَقَةِ، فَجَعَلْنَ يُلْقِيْنَ تُلْقِي الْمَرْأَةُ خُرْصَهَا وَسِخَابَهَا. البخارى 2: 5"],["p","Dari Sa'id bin Jubair, dari Ibnu 'Abbas bahwasanya dahulu Nabi SAW melaksanakan shalat Hari Raya 'Iedul Fithri 2 reka'at, beliau tidak shalat apapun sebelumnya maupun sesudahnya. Kemudian beliau datang bersama Bilal ke tempat para wanita, lalu beliau menganjurkan mereka untuk bershadaqah, lalu para wanita bershadaqah, ada yang memberikan anting-antingnya, dan ada pula yang memberikan kalungnya. [HR. Bukhari juz 2, hal. 5]"],["h","12. Takbir dalam shalat pada dua Hari Raya"],["p","Takbir shalat pada dua Hari Raya (Hari Raya 'Iedul Fithri dan 'Iedul Adlha), dilaksanakan dengan 7 kali pada rekaat pertama, dan 5 kali pada rekaat yang kedua sebelum membaca Al-Fatihah."],["p","Hal ini sesuai dengan sabda Nabi SAW maupun perbuatan para shahabat.:"],["a","عَنْ عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ قَالَ:قَالَ نَبِيُّ اللهِ ﷺ: اَلتَّكْبِيْرُ فيِ الْفِطْرِ سَبْعٌ فيِ الْاُوْلَى وَخَمْسٌ فيِ الْاٰخِرَةِ وَالْقِرَاءَةُ بَعْدَهُمَا كِلْتَيْهِمَا. ابو داود 1: 299، رقم: 1151"],["p","Dari ‘Abdullah bin ‘Amr bin Al-’Ash, ia berkata : Nabi Allah SAW bersabda, “Takbir pada (shalat) ‘Iedul Fithri adalah 7 kali di rekaat pertama dan 5 kali di rekaat yang akhir (kedua). Adapun bacaan, sesudah kedua-duanya itu\". [HR. Abu Dawud juz 1, hal. 299, no. 1151]"],["a","عَنْ عَمْرِو بْنِ شُعَيْبٍ عَنْ اَبِيْهِ عَنْ جَدِّهِ اَنَّ رَسُوْلَ اللهِ ﷺ كَبَّرَ فِى الْعِيْدِ يَوْمَ الْفِطْرِ سَبْعًا فِى الْاُوْلىَ وَفِى الْاٰخِرَةِ خَمْسًا سِوَى تَكْبِيْرَةِ الصَّلَاةِ. الدارقطنى 2: 48، رقم: 22"],["p","Dari 'Amr bin Syu'aib, dari ayahnya, dari kakeknya, bahwasanya Rasulullah SAW bertakbir dalam shalat Hari Raya 'Iedul Fithri tujuh takbir pada rekaat pertama dan lima takbir pada rekaat kedua, selain takbir (yang biasa dalam) shalat. [HR. Daraquthni, juz 2, hal. 48, no. 22]"],["p","Tentang atsar (perbuatan) para shahabat, diriwayatkan :"],["a","عَنْ نَافِعٍ مَوْلىَ عَبْدِ اللهِ بْنِ عُمَرَ اَنَّهُ قَالَ: شَهِدْتُ الْاَضْحَى وَالْفِطْرَ مَعَ اَبِيْ هُرَيْرَةَ فَكَبَّرَ فيِ الرَّكْعَةِ الْاُوْلىَ سَبْعَ تَكْبِيْرَاتٍ قَبْلَ الْقِرَاءَةِ وَفِى الْاٰخِرَةِ خَمْسَ تَكْبِيْرَاتٍ قَبْلَ الْقِرَاءَةِ. مالك فى الموطأ 1: 180"],["p","Dari Nafi' maula ‘Abdullah bin 'Umar, bahwa dia berkata, \"Aku pernah menyaksikan 'Iedul Adlha dan 'Iedul Fithri bersama Abu Hurairah. Maka ia bertakbir di rekaat pertama 7 takbir sebelum membaca, dan di rekaat kedua 5 takbir sebelum membaca\". [HR. Malik, di dalam Al-Muwaththa’ juz 1, hal. 180]"],["a","عَنْ عَطَاءٍ قَالَ: كَانَ ابْنُ عَبَّاسٍ يُكَبِّرُ فيِ الْعِيْدَيْنِ ثِنْتَيْ عَشْرَةَ تَكْبِيْرَةً. سَبْعٌ فيِ الْاُوْلىَ وَخَمْسٌ فيِ الْاٰخِرَةِ. البيهقى 3: 289"],["p","Dari 'Atha', ia berkata, \"Adalah Ibnu 'Abbas bertakbir di dua Hari Raya 12 takbir, yaitu 7 di rekaat pertama dan 5 di rekaat yang kedua\". [HR. Baihaqi juz 3, hal. 289]"],["h","13. Bacaan takbir Hari Raya"],["p","Bacaan takbir pada Hari Raya yang bersumber dari shahabat ‘Umar dan Ibnu Mas'ud adalah :"],["a","اَللهُ اَكْبَرُ اَللهُ اَكْبَرُ، لَا اِلٰهَ اِلَّا اللهُ وَاللهُ اَكْبَرُ،اَللهُ اَكْبَرُ وَلِلّٰهِ اْلحَمْدُ. فى نيل الاوطار 3 :358، فقه السنة 1: 275"],["p","Alloohu Akbar, Alloohu Akbar, Laa ilaaha illalloohu walloohu Akbar Alloohu Akbar wa lillaahil-hamdu."],["p","(Allah Maha Besar, Allah Maha Besar. Tidak ada Tuhan (yang sebenarnya) melainkan Allah, dan Allah Maha Besar. Allah Maha Besar dan kepunyaan Allah-lah segala pujian). [Dalam Nailul Authar juz 3 hal. 358, Fiqhus Sunnah juz 1 hal. 275]"],["h","14. Ucapan pada Hari Raya"],["p","Para shahabat Nabi SAW jika bertemu di antara mereka pada Hari Raya, mereka mengucapkan :"],["a","تَقَبَّلَ اللهُ مِنَّا وَمِنْكُمْ"],["p","\"Semoga Allah menerima amalan kami dan amalan kalian\"."],["p","Jubair bin Nufair meriwayatkan :"],["a","كَانَ اَصْحَابُ رَسُوْلِ اللهِ ﷺ اِذَا تَلَقَّوْا يَوْمَ الْعِيْدِ يَقُوْلُ بَعْضُهُمْ لِبَعْضٍ: تَقَبَّلَ اللهُ مِنَّا وَمِنْكُمْ. جبير بن نفير"],["p","Dahulu para shahabat Rasulullah SAW apabila mereka bertemu pada Hari Raya, satu dengan yang lain saling mengucapkan, “Taqobbalalloohu minnaa wa minkum”. [Jubair bin Nufair]"],["h","15. Menentukan awwal bulan dengan Ru’yah (melihat hilal/bulan sabit)"],["p","Kaum muslimin dan muslimat rahimakumullah, kita ketahui bahwa perhitungan hari/bulan Qamariyah itu dimulai berdasarkan Hilal, dimana saat itu terjadi ketika mula-mula matahari mendahului tenggelamnya bulan, sehingga saat matahari sudah tenggelam masih kita lihat bulan sabit di ufuq barat. Hal ini perlu kita ketahui karena erat sekali hubungannya dengan kapan kita memulai puasa Ramadlan, dan kapan kita mengakhirinya, dan juga ibadah-ibadah yang lain yang terkait dengan tanggal/bulan, misalnya puasa tasu'a dan 'asyuraa, ibadah hajji dan lain-lain."],["p","Bulan Qomariyah terkadang 29 hari dan terkadang 30 hari. Rasulullah SAW menuntunkan kepada kita cara untuk mengetahui pergantian bulan satu kepada bulan berikutnya, sebagai berikut :"],["a","عَنْ سَعِيْدِ بْنِ الْمُسَيَّبِ عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اِذَا رَأَيْتُمُ الْـهِلَالَ فَصُوْمُوْا وَاِذَا رَأَيْتُمُوْهُ فَاَفْطِرُوْا، فَاِنْ غُمَّ عَلَيْكُمْ فَصُوْمُوْا ثَلَاثِيْنَ يَوْمًا. مسلم 2: 762 رقم : 17"],["p","Dari Sa’id bin Al-Musayyab, dari Abu Hurairah RA, ia berkata : Rasulullah SAW bersabda, “Apabila kalian melihat hilal, berpuasalah, dan apabila kalian melihatnya (lagi), berbukalah. Maka apabila mendung (menghalangi kalian), berpuasalah tiga puluh hari. [HR. Muslim juz 2, hal. 762, no. 17]"],["a","عَنْ مُحَمَّدٍ وَهُوَ بْنُ زِيَادٍ عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ اَنَّ النَّبِيَّ ﷺ قَالَ: صُوْمُوْا لِرُؤْيَتِهِ وَاَفْطِرُوْا لِرُؤْيَتِهِ، فَاِن غُمِّيَ عَلَيْكُمْ فَاَكْمِلُوا الْعَدَدَ. مسلم 2: 762 رقم : 18"],["p","Dari Muhammad yaitu Ibnu Ziyad, dari Abu Hurairah RA, bahwasanya Nabi SAW bersabda, “Berpuasalah kalian karena melihat hilal dan berbukalah karena melihatnya. Dan jika mendung (menghalangi) kalian, maka sempurnakanlah hitungan (bulan menjadi 30). [HR. Muslim juz 2, hal. 762, no. 18]"],["a","عَنْ مُحَمَّدِ بْنِ زِيَادٍ قَالَ: سَمِعْتُ اَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ يَقُوْلُ: قَالَ رَسُوْلُ اللهِ ﷺ: صُوْمُوْا لِرُؤْيَتِهِ وَاَفْطِرُوْا لِرُؤْيَتِهِ، فَاِنْ غُمِّيَ عَلَيْكُمُ الشَّهْرُ فَعُدُّوْا ثَلَاثِيْنَ. مسلم 2: 762 رقم : 19"],["p","Dari Muhammad bin Ziyad, ia berkata : Aku mendengar Abu Hurairah RA berkata : Rasulullah SAW bersabda, “Berpuasalah kalian karena melihat hilal, dan berbukalah karena melihatnya (hilal). Maka jika mendung menghalangi kalian, hitunglah bulan itu tiga puluh hari. [HR Muslim juz 2, hal. 762, no. 19]"],["p","--oo0oo--"]],"c20220529_1283":[["p","Ahad, 29 Mei 2022/28 Syawwaal 1443 Brosur No. : 2078/2118/IA"],["p","Berpegang kepada Al Qur'an dan As Sunnah di masa kerusakan ummat"],["p","Firman Allah SWT :"],["a","يٰۤاَيُّهَا الَّذِيْنَ اٰمَنُوْا عَلَيْكُمْ اَنْفُسَكُمْ لَا يَضُرُّكُمْ مَّنْ ضَلَّ اِذَا اهْتَدَيْتُمْ، اِلَى اللهِ مَرْجِعُكُمْ جَمِيْعًا فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُوْنَ. المائدة: 105"],["p","Hai orang-orang yang beriman, jagalah dirimu; tiadalah orang yang sesat itu akan memberi mudlarat kepadamu apabila kamu telah mendapat petunjuk. Hanya kepada Allah kamu kembali semuanya, maka Dia akan menerangkan kepadamu apa yang telah kamu kerjakan. [QS. Al Maaidah : 105]"],["p","Hadits Rasulullah SAW :"],["a","عَنْ اَبِيْ اُمَيَّةَ الشَّعْبَانِيِّ قَالَ: اَتَيْتُ اَبَا ثَعْلَبَةَ الْخُشَنِيَّ فَقُلْتُ لَهُ: كَيْفَ تَصْنَعُ فِيْ هٰذِهِ الْاٰيَةِ ؟ قَالَ: اَيَّةُ آيَةٍ؟ قُلْتُ: قَوْلُهُ يٰۤاَيُّهَا الَّذِيْنَ اٰمَنُوْا عَلَيْكُمْ اَنْفُسَكُمْ لَا يَضُرُّكُمْ مَّنْ ضَلَّ اِذَا اهْتَدَيْتُمْ. قَالَ: اَمَا وَاللهِ، لَقَدْ سَأَلْتَ عَنْهَا خَبِيْرًا سَأَلْتُ عَنْهَا رَسُوْلَ اللهِ ﷺ ، قَالَ: بَلِ ائْتَمِرُوْا بِالْمَعْرُوْفِ وَتَنَاهَوْا عَنِ الْمُنْكَرِ حَتَّى اِذَا رَأَيْتَ شُحًّا مُطَاعًا وَهَوًى مُتَّبَعًا وَدُنْيَا مُؤْثَرَةً وَاِعْجَابَ كُلِّ ذِيْ رَأْىٍ بِرَأْيِهِ فَعَلَيْكَ بِخَاصَّةِ نَفْسِكَ وَدَعِ الْعَوَامَّ فَاِنَّ مِنْ وَرَائِكُمْ اَيَّامًا الصَّبْرُ فِيْهِنَّ مِثْلُ الْقَبْضِ عَلَى الْجَمْرِ، لِلْعَامِلِ فِيْهِنَّ مِثْلُ اَجْرِ خَمْسِيْنَ رَجُلًا يَعْمَلُوْنَ مِثْلَ عَمَلِكُمْ. قَالَ عَبْدُ اللهِ بْنُ الْمُبَارَكِ: وَزَادَنِيْ غَيْرُ عُتْبَةَ، قِيْلَ: يَا رَسُوْلَ اللهِ اَجْرُ خَمْسِيْنَ رَجُلًا مِنَّا اَوْ مِنْهُمْ؟ قَالَ: لَا، بَلْ اَجْرُ خَمْسِيْنَ مِنْكُمْ. الترمذى 4: 323، رقم: 5051 هذا حديث حسن غريب"],["p","Dari Abu Umayyah Asy-Sya’baniy, ia berkata : Saya pernah bertanya kepada Abu Tsa’labah Al-Khusyaniy, aku bertanya, “Hai Abu Tsa’labah, bagaimana pendapatmu tentang ayat ini ?\". Abu Tsa'labah balik bertanya, \"Ayat yang mana ?\". Aku berkata, \"Yaitu firman Allah Ta'aalaa \"Yaa ayyuhalladziina aamanuu ‘alaikum anfusakum laa yadlurrukum man dlolla idzahtadaitum\" ( Al Maaidah : 105). Abu Tsa'labah berkata, “Demi Allah, sungguh kamu menanyakan sesuatu yang aku pernah menanyakannya kepada Rasulullah SAW”, beliau bersabda, “Tetapi hendaklah kalian amar ma’ruf dan nahi munkar, sehingga apabila kamu melihat kebakhilan ditha’ati, hawa nafsu diikuti, keduniaan telah mewarnai, dan orang bangga dengan pendapatnya, maka wajib atasmu (yakni menjaga dirimu), tinggalkanlah keumuman orang, karena akan datang di belakang kalian hari-hari yang shabar pada waktu itu seperti orang yang menggenggam bara api. Bagi orang yang melakukan (amar ma’ruf nahi munkar) di tengah-tengah mereka pada hari itu akan mendapat pahala lima puluh orang yang beramal seperti kalian”. 'Abdullah bin Mubarak berkata : Dan menambahkan kepadaku selain 'Utbah, ada yang bertanya, “Ya Rasulullah, apakah pahala lima puluh orang dari kami atau dari mereka ?”. Beliau menjawab, “Pahala lima puluh orang dari kalian”. [HR. Tirmidzi juz 4, hal. 323, no. 5051 ini hadits hasan gharib]"],["a","عَنْ اَبِيْ اُمَيَّةَ الشَّعْبَانِيِّ قَالَ: سَأَلْتُ اَبَا ثَعْلَبَةَ الْخُشَنِيَّ فَقُلْتُ: يَا اَبَا ثَعْلَبَةَ، كَيْفَ تَقُوْلُ فِيْ هٰذِهِ الْاٰيَةِ عَلَيْكُمْ اَنْفُسَكُمْ. قَالَ: اَمَا وَاللهِ لَقَدْ سَأَلْتَ عَنْهَا خَبِيْرًا سَأَلْتُ عَنْهَا رَسُوْلَ اللهِ ﷺ فَقَالَ: بَلِ ائْتَمِرُوْا بِالْمَعْرُوْفِ وَتَنَاهَوْا عَنِ الْمُنْكَرِ حَتَّى اِذَا رَأَيْتَ شُحًّا مُطَاعًا وَهَوًى مُتَّبَعًا وَدُنْيَا مُؤْثَرَةً فَاِعْجَابَ كُلِّ ذِيْ رَأْيٍ بِرَأْيِهِ فَعَلَيْكَ يَعْنِى بِنَفْسِكَ وَدَعْ عَنْكَ الْعَوَامَّ، فَاِنَّ مِنْ وَرَائِكُمْ اَيَّامَ الصَّبْرِ. اَلصَّبْرُ فِيْهِ مِثْلُ قَبْضٍ عَلَى الْجَمْرِ، لِلْعَامِلِ فِيْهِمْ مِثْلُ اَجْرِ خَمْسِيْنَ رَجُلًا يَعْمَلُوْنَ مِثْلَ عَمَلِهِ. وَزَادَانِى غَيْرُهُ. يَا رَسُوْلَ اللهِ، اَجْرُ خَمْسِيْنَ مِنْهُمْ؟ قَالَ: اَجْرُ خَمْسِيْنَ مِنْكُمْ. ابو داود 4: 123، رقم: 4341"],["p","Dari Abu Umayyah Asy-Sya’baniy, ia berkata : Saya pernah bertanya kepada Abu Tsa’labah, aku bertanya, “Hai Abu Tsa’labah, bagaimana pendapatmu tentang ayat ‘alaikum anfusakum ? (Al Maaidah : 105). Ia berkata, “Demi Allah, sungguh kamu menanyakan sesuatu yang aku pernah menanyakannya kepada Rasulullah SAW”, beliau bersabda, “Tetapi hendaklah kalian amar ma’ruf dan nahi munkar, sehingga apabila kamu melihat kebakhilan ditha’ati, hawa nafsu diikuti, keduniaan telah mewarnai, dan orang bangga dengan pendapatnya, maka wajib atasmu (yakni menjaga dirimu), tinggalkanlah keumuman orang, karena akan datang di belakang kalian hari-hari keshabaran. Shabar pada waktu itu seperti orang yang menggenggam bara api. Bagi orang yang melakukan (amar ma’ruf nahi munkar) di tengah-tengah mereka pada hari itu akan mendapat pahala lima puluh orang yang beramal seperti dia”. Perawi berkata : Dan menambahkan kepadaku selain dia, ia berkata, “Ya Rasulullah, apakah pahala lima puluh orang dari mereka ?”. Beliau menjawab, “Pahala lima puluh orang dari kalian”. [HR. Abu Dawud juz 4, hal. 123, no. 4341]"],["a","عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ قَالَ: كَانَ النَّاسُ يَسْأَلُوْنَ رَسُوْلَ اللهِ ﷺ عَنِ الْخَيْرِ وَكُنْتُ اَسْأَلُهُ عَنِ الشَّرِّ مَخَافَةَ اَنْ يُدْرِكَنِيْ، فَقُلْتُ: يَا رَسُوْلَ اللهِ، اِنَّا كُنَّا فِيْ جَاهِلِيَّةٍ وَشَرٍّ فَجَاءَنَا اللهُ بِـهٰذَا الْخَيْرِ. فَهَلْ بَعْدَ هٰذَا الْخَيْرِ مِنْ شَرٍّ؟ قَالَ: نَعَمْ. قُلْتُ: وَهَلْ بَعْدَ ذٰلِكَ الشَّرِّ مِنْ خَيْرٍ؟ قَالَ: نَعَمْ، وَفِيْهِ دَخَنٌ. قُلْتُ: وَمَا دَخَنُهُ؟ قَالَ: قَوْمٌ يَهْدُوْنَ بِغَيْرِ هَدْيِيْ، تَعْرِفُ مِنْهُمْ وَتُنْكِرُ. قُلْتُ: فَهَلْ بَعْدَ ذٰلِكَ الْخَيْرِ مِنْ شَرٍّ؟ قَالَ: نَعَمْ، دُعَاةٌ اِلَى اَبْوَابِ جَهَنَّمَ. مَنْ اَجَابَهُمْ اِلَيْهَا قَذَفُوْهُ فِيْهَا. قُلْتُ: يَا رَسُوْلَ اللهِ، صِفْهُمْ لَنَا. قَالَ: هُمْ مِنْ جِلْدَتِنَا وَيَتَكَلَّمُوْنَ بِاَلْسِنَتِنَا. قُلْتُ: فَمَا تَأْمُرُنِيْ اِنْ اَدْرَكَنِيْ ذٰلِكَ؟ قَالَ: تَلْزَمُ جَمَاعَةَ الْمُسْلِمِيْنَ وَاِمَامَهُمْ. قُلْتُ: فَاِنْ لَمْ يَكُنْ لَهُمْ جَمَاعَةٌ وَلَا اِمَامٌ؟ قَالَ: فَاعْتَزِلْ تِلْكَ الْفِرَقَ كُلَّهَا وَلَوْ اَنْ تَعَضَّ بِاَصْلِ شَجَرَةٍ حَتَّى يُدْرِكَكَ الْمَوْتُ وَاَنْتَ عَلَى ذٰلِكَ. البخارى 4: 178"],["p","Dari Hudzaifah bin Yaman, ia berkata : Dahulu orang-orang bertanya kepada Rasulullah SAW tentang kebaikan, sedangkan saya bertanya kepada beliau tentang keburukan, karena khawatir kalau keburukan itu akan menimpa saya. Saya bertanya, “Ya Rasulullah, sesungguhnya kami dahulu berada di masa jahiliyah dan dalam keburukan, lalu Allah mendatangkan kebaikan ini kepada kami, maka apakah setelah kebaikan ini akan ada lagi keburukan ?”. Nabi SAW menjawab, “Ya”. Saya bertanya lagi, “Dan apakah setelah keburukan itu akan ada lagi kebaikan ?”. Nabi SAW menjawab, “Ya”. Dan padanya ada asap kelabu (percampuran yang baik dan yang buruk). Saya bertanya, “Apa itu yang dimaksud asap ?”. Nabi SAW menjawab, “Ada suatu kaum yang memakai petunjuk bukan dengan petunjukku, kamu mengenal mereka dan mengingkarinya”. Saya bertanya, “Apakah setelah kebaikan itu ada lagi keburukan ?”. Nabi SAW menjawab, “Ya, yaitu orang-orang yang menyeru ke pintu-pintu Jahannam. Barangsiapa yang menyambut seruan mereka (mengikutinya), maka mereka akan melemparkannya ke Jahannam”. Saya bertanya lagi, “Ya Rasulullah, terangkanlah sifat-sifat mereka kepada kami”. Nabi SAW bersabda, “Mereka adalah orang-orang dari daging kulit kita sendiri, dan mereka berbicara dengan lisan kita”. Saya bertanya lagi. “Lalu apa yang engkau perintahkan kepada saya jika saya mendapati yang demikian itu ?”. Beliau bersabda, “Tetaplah kamu menetapi jama’ah muslimin dan imam mereka”. Saya bertanya lagi, “Jika tidak ada jama’ah muslimin dan imam (lalu bagaimana) ?”. Beliau bersabda, “Tinggalkanlah firqah-firqah itu semuanya, meskipun kamu harus menggigit akar-akar pohon sehingga mati menjemputmu, sedangkan kamu dalam keadaan demikian itu”. [HR. Bukhari juz 4, hal. 178]"],["a","عَنْ خَبَّابِ بْنِ اْلاَرَتِّ قَالَ: شَكَوْنَا اِلَى رَسُوْلِ اللهِ ﷺ وَهُوَ مُتَوَسِّدٌ بُرْدَةً لَهُ فِيْ ظِلِّ الْكَعْبَةِ، قُلْنَا لَهُ: اَلَا تَسْتَنْصِرُ لَنَا، اَلَا تَدْعُو اللهَ لَنَا. قَالَ: كَانَ الرَّجُلُ فِيْمَنْ قَبْلَكُمْ يُحْفَرُ لَهُ فِي اْلاَرْضِ فَيُجْعَلُ فِيْهِ فَيُجَاءُ بِالْمِنْشَارِ فَيُوْضَعُ عَلَى رَأْسِهِ فَيُشَقُّ بِاثْنَتَيْنِ وَمَا يَصُدُّهُ ذٰلِكَ عَنْ دِيْنِهِ وَيُمْشَطُ بِاَمْشَاطِ اْلحَدِيْدِ مَا دُوْنَ لَحْمِهِ مِنْ عَظْمٍ اَوْ عَصَبٍ وَمَا يَصُدُّهُ ذٰلِكَ عَنْ دِيْنِهِ. وَاللهِ لَيَتِمَّنَّ هٰذَا الْاَمْرُ حَتَّى يَسِيْرَ الرَّاكِبُ مِنْ صَنْعَاءَ اِلَى حَضْرَمَوْتَ لَا يَخَافُ اِلَّا اللهَ اَوِ الذِّئْبَ عَلَى غَنَمِهِ وَلٰكِنَّكُمْ تَسْتَعْجِلُوْنَ. البخارى 4: 179"],["p","Dari Khabbaab bin Al Aratt, ia berkata; \"Kami pernah mengadu kepada Rasulullah SAW, ketika itu beliau sedang berada di bawah naungan Ka'bah dengan berbantalkan kain selimut beliau. Kami berkata, “Apakah tidak sebaiknya engkau memohonkan pertolongan buat kami ?. Apakah tidak sebaiknya engkau berdo'a memohon kepada Allah untuk kami ?\". Beliau bersabda, “Dahulu ada seorang laki-laki dari ummat sebelum kalian, dibuatkan lubang di tanah untuknya lalu ia dimasukkan di dalamnya, lalu diambilkan gergaji, kemudian gergaji itu diletakkan di kepalanya lalu ia dibelah menjadi dua, namun hal itu tidak menghalanginya dari agamanya. Dan adalagi yang disisir dengan sisir dari besi mengenai tulang dan urat di bawah dagingnya, namun hal itu tidak menghalanginya dari agamanya. Demi Allah, sungguh urusan (Islam) ini akan sempurna sehingga orang yang mengendarai unta berjalan dari Shan’aa’ ke Hadlramaut, tidak ada yang ditakutinya melainkan Allah, atau terhadap serigala atas kambing-kambingnya, akan tetapi kalian sangat tergesa-gesa\". [HR. Bukhari juz 4, hal. 179]"],["a","عَنْ ثَوْبَانَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: يُوْشِكُ الْاُمَمُ اَنْ تَدَاعَى عَلَيْكُمْ كَمَا تَدَاعَى الْأَكَلَةُ اِلَى قَصْعَتِهَا. فَقَالَ قَائِلٌ: وَمِنْ قِلَّةٍ نَحْنُ يَوْمَئِذٍ؟ قَالَ: بَلْ اَنْتُمْ يَوْمَئِذٍ كَثِيْرٌ، وَلٰكِنَّكُمْ غُثَاءٌ كَغُثَاءِ السَّيْلِ، وَلَيَنْزِعَنَّ اللهُ مِنْ صُدُوْرِ عَدُوِّكُمُ الْمَهَابَةَ مِنْكُمْ وَلَيَقْذِفَنَّ اللهُ فِيْ قُلُوْبِكُمُ الْوَهْنَ. فَقَالَ قَائِلٌ: يَا رَسُوْلَ اللهِ، وَمَا الْوَهْنُ؟ قَالَ: حُبُّ الدُّنْيَا وَكَرَاهِيَةُ الْمَوْتِ. ابو داود 4: 111، رقم: 4297"],["p","Dari Tsauban, ia berkata : Rasulullah SAW bersabda, “Hampir-hampir orang-orang (musuh-musuh kalian) memperebutkan kalian (ummat Islam), layaknya orang-orang rakus memperebutkan makanan pada satu nampan. Ada seorang yang bertanya, \"Apakah kami waktu itu berjumlah sedikit ?\". Rasulullah SAW menjawab, “Bahkan jumlah kalian pada waktu itu sangat banyak, namun kalian seperti buih pada air bah. Dan sungguh Allah akan mencabut rasa takut dari dada musuh kalian, dan akan memasukkan ke dalam hati kalian Al-Wahn”. Ada seorang yang bertanya, \"Wahai Rasulullah, apakah Al-Wahn itu ?\". Beliau menjawab, “Cinta dunia dan takut mati”. [HR. Abu Dawud juz 4, hal. 111, no. 4297]"],["a","عَنْ اَبِيْ سَعِيْدِ اْلخُدْرِيِّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : لَتَتْبَعُنَّ سُنَنَ الَّذِيْنَ مِنْ قَبْلِكُمْ شِبْرًا بِشِبْرٍ وَذِرَاعًا بِذِرَاعٍ حَتَّى لَوْ دَخَلُوْا فِيْ جُحْرِ ضَبٍّ لَاتَّبَعْتُمُوْهُمْ. قُلْنَا: يَا رَسُوْلَ اللهِ، آلْيَهُوْدُ وَالنَّصَارَى؟ قَالَ: فَمَنْ؟ مسلم 4: 2054 رقم 6"],["p","Dari Abu Sa’id Al-Khudriy, ia berkata : Rasulullah SAW bersabda, “Sungguh kalian akan mengikuti langkah orang-orang sebelum kalian, sejengkal demi sejengkal dan sehasta demi sehasta, sehingga walaupun mereka memasuki lubang biawak, kalian tetap mengikutinya”. Kami (shahabat) bertanya, “Ya Rasulullah, apakah mereka itu kaum Yahudi dan Nashrani ?”. Beliau bersabda, “Lalu, siapa lagi ?”. [HR. Muslim juz 4, hal. 2054, no. 6]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: بَدَأَ الْاِسْلاَمُ غَرِيْبًا وَ سَيَعُوْدُ كَمَا بَدَأَ غَرِيْبًا فَطُوْبَى لِلْغُرَبَاءِ. مسلم 1: 130 رقم : 232"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Islam itu bermula asing, dan akan kembali asing sebagaimana semula asing. Maka berbahagialah bagi orang-orang yang asing”. [HR Muslim juz 1, hal. 130, no. 232]"],["a","عَنْ عَبْدِ اللهِ بْنِ مَسْعُوْدٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اِنَّ الْاِسْلَامَ بَدَأَ غَرِيْبًا وَسَيَعُوْدُ غَرِيْبًا كَمَا بَدَأَ فَطُوْبَى لِلْغُرَبَاءِ. الترمذى 4: 129، رقم: 2764 هذا حديث حسن غريب صحيح"],["p","Dari ‘Abdullah bin Mas’ud, ia berkata : Rasulullah SAW bersabda, “Sesungguhnya Islam itu bermula asing, dan akan kembali asing sebagaimana semula, maka berbahagialah orang-orang yang asing”. [HR. Tirmidzi juz 4, hal. 129, no. 2764 ini hadits hasan gharib shahih]"],["a","عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اِنَّ الْاِسْلَامَ بَدَأَ غَرِيْبًا وَسَيَعُوْدُ غَرِيْبًا فَطُوْبَى لِلْغُرَبَاءِ. قَالُوْا: يَا رَسُوْلَ اللهِ، وَمَا الْغُرَبَاءُ؟ قَالَ: اَلَّذِيْنَ يُصْلِحُوْنَ عِنْدَ فَسَادِ النَّاسِ. الطبرانى فى المعجم الكبير 6: 164، رقم: 5867"],["p","Dari Sahl bin Sa’d As-Saa’idiy, ia berkata : Rasulullah SAW bersabda, “Sesungguhnya Islam itu bermula asing, dan akan kembali asing, maka berbahagialah orang-orang yang asing”. Para shahabat bertanya, “Siapakah orang yang asing itu ya Rasulullah ?”. Beliau bersabda, “Yaitu orang-orang yang memperbaiki ketika manusia dalam keadaan rusak”. [HR. Thabarani dalam Mu’jamul Al Kabir juz 6, hal. 164, no. 5867]"],["a","عَنْ ثَوْبَانَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا تَزَالُ طَائِفَةٌ مِنْ اُمَّتِيْ ظَاهِرِيْنَ عَلَى الْحَقِّ. لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ حَتَّى يَأْتِيَ اَمْرُ اللهِ وَهُمْ كَذٰلِكَ. مسلم 3: 1523، رقم: 170"],["p","Dari Tsauban, ia berkata : Rasulullah SAW bersabda, “Akan selalu ada segolongan dari ummatku yang menampakkan kebenaran. Tidak akan memudlaratkan kepada mereka orang yang menentangnya, sehingga Allah mendatangkan perintah-Nya, sedangkan mereka tetap demikian itu”. [HR. Muslim juz 3, hal. 1523, no. 170]"],["a","عَنْ مُعَاوِيَةَ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: لَا تَزَالُ طَائِفَةٌ مِنْ اُمَّتِيْ قَائِمَةً بِاَمْرِ اللهِ، لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ اَوْ خَالَفَهُمْ حَتَّى يَأْتِيَ اَمْرُ اللهِ وَهُمْ ظَاهِرُوْنَ عَلَى النَّاسِ. مسلم 3: 1524، رقم: 174"],["p","Dari Mu’awiyah, ia berkata : Aku mendengar Rasulullah SAW bersabda, “Selalu ada segolongan dari ummatku yang menegakkan perintah Allah, tidak akan memudlaratkan kepada mereka orang yang menentangnya atau menyelisihinya, sehingga datang keputusan Allah dan mereka tetap ada di tengah-tengah manusia”. [HR. Muslim juz 3, hal. 1524, no. 174]"],["p","--oo0oo--"]],"c20220605_1284":[["p","Ahad, 05 Juni 2022/05 Dzul Qa’dah 1443 Brosur No. : 2079/2119/IA"],["p","Tazkiyatun Nafs (1)"],["p","Tazkiyah adalah mashdar dari :"],["a","زَكَّى – يُزَكِّى – تَزْكِيًّا وَ تَزْكِيَةً"],["p","Artinya: membersihkan/menyucikan"],["p","Sedangkah nafs, artinya jiwa"],["p","Tazkiyatun nafs artinya “Membersihkan jiwa”"],["p","Allah SWT berfirman :"],["a","وَنَفْسٍ وَّمَا سَوّٰىهَاۖ (7) فَاَلْهَمَهَا فُجُوْرَهَا وَتَقْوٰىهَاۖ (8) قَدْ اَفْلَحَ مَنْ زَكّٰىهَاۖ (9) وَقَدْ خَابَ مَنْ دَسّٰىهَا (10) الشمس : 7-10"],["p","Dan demi jiwa serta penyempurnaannya (ciptaannya), (7)"],["p","maka Allah mengilhamkan kepada jiwa itu (jalan) kefasikan dan ketakwaannya,(8)"],["p","sesungguhnya beruntunglah orang yang menyucikan jiwa itu,(9)"],["p","dan sesungguhnya merugilah orang yang mengotorinya.(10) [QS. Asy Syams : 7 – 10]"],["p","Tazkiyatun nafs yaitu membersihkan jiwa dari sifat sifat buruk dan tercela dan berusaha untuk memperbaikinya dengan mengagungkan Allah dan berbuat amal amal shalih."],["p","Adapun cara membersihkan jiwa, diantaranya :"],["p","1) Bertaubat kembali kepada Allah SWT."],["p","Allah SWT berfirman:"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا تُوْبُوْٓا اِلَى اللّٰهِ تَوْبَةً نَّصُوْحًاۗ عَسٰى رَبُّكُمْ اَنْ يُّكَفِّرَ عَنْكُمْ سَيِّاٰتِكُمْ وَيُدْخِلَكُمْ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُۙ يَوْمَ لَا يُخْزِى اللّٰهُ النَّبِيَّ وَالَّذِيْنَ اٰمَنُوْا مَعَهٗۚ نُوْرُهُمْ يَسْعٰى بَيْنَ اَيْدِيْهِمْ وَبِاَيْمَانِهِمْ يَقُوْلُوْنَ رَبَّنَآ اَتْمِمْ لَنَا نُوْرَنَا وَاغْفِرْ لَنَاۚ اِنَّكَ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ . التحريم : 8"],["p","Hai orang-orang yang beriman, bertaubatlah kepada Allah dengan taubat yang semurni-murninya, mudah-mudahan Tuhan kamu akan menghapus kesalahan-kesalahanmu dan memasukkan kamu ke dalam surga yang mengalir di bawahnya sungai-sungai, pada hari ketika Allah tidak menghinakan Nabi dan orang-orang yang beriman bersama dengan dia; sedang cahaya mereka memancar di hadapan dan di sebelah kanan mereka, sambil mereka mengatakan: \"Ya Tuhan kami, sempurnakanlah bagi kami cahaya kami dan ampunilah kami; sesungguhnya Engkau Maha Kuasa atas segala sesuatu\". [QS. At Tahrim : 8]"],["a","قُلْ يٰعِبَادِيَ الَّذِيْنَ اَسْرَفُوْا عَلٰٓى اَنْفُسِهِمْ لَا تَقْنَطُوْا مِنْ رَّحْمَةِ اللّٰهِ ۗ اِنَّ اللّٰهَ يَغْفِرُ الذُّنُوْبَ جَمِيْعًا ۗ اِنَّهٗ هُوَ الْغَفُوْرُ الرَّحِيْمُ (53) وَاَنِيْبُوْٓا اِلٰى رَبِّكُمْ وَاَسْلِمُوْا لَهٗ مِنْ قَبْلِ اَنْ يَّأْتِيَكُمُ الْعَذَابُ ثُمَّ لَا تُنْصَرُوْنَ (54) وَاتَّبِعُوْٓا اَحْسَنَ مَآ اُنْزِلَ اِلَيْكُمْ مِّنْ رَّبِّكُمْ مِّنْ قَبْلِ اَنْ يَّأْتِيَكُمُ الْعَذَابُ بَغْتَةً وَّاَنْتُمْ لَا تَشْعُرُوْنَ (55) الزمر : 53-55"],["p","Katakanlah: \"Hai hamba-hamba-Ku yang melampaui batas terhadap diri mereka sendiri, janganlah kamu berputus asa dari rahmat Allah. Sesungguhnya Allah mengampuni dosa-dosa semuanya. Sesungguhnya Dialah Yang Maha Pengampun lagi Maha Penyayang. (53)"],["p","Dan kembalilah kamu kepada Tuhanmu, dan berserah dirilah kepada-Nya sebelum datang adzab kepadamu kemudian kamu tidak dapat ditolong (lagi).(54)"],["p","Dan ikutilah sebaik-baik apa yang telah diturunkan kepadamu dari Tuhanmu sebelum datang adzab kepadamu dengan tiba-tiba, sedang kamu tidak menyadarinya, (55) [QS. Az Zumar : 53-55]"],["a","وَسَارِعُوْٓا اِلٰى مَغْفِرَةٍ مِّنْ رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّمٰوٰتُ وَالْاَرْضُلا اُعِدَّتْ لِلْمُتَّقِيْنَ ۙ (133) الَّذِيْنَ يُنْفِقُوْنَ فِى السَّرَّۤاءِ وَالضَّرَّۤاءِ وَالْكٰظِمِيْنَ الْغَيْظَ وَالْعَافِيْنَ عَنِ النَّاسِۗ وَاللّٰهُ يُحِبُّ الْمُحْسِنِيْنَۚ (134) وَالَّذِيْنَ اِذَا فَعَلُوْا فَاحِشَةً اَوْ ظَلَمُوْٓا اَنْفُسَهُمْ ذَكَرُوا اللّٰهَ فَاسْتَغْفَرُوْا لِذُنُوْبِهِمْۗ وَمَنْ يَّغْفِرُ الذُّنُوْبَ اِلَّا اللّٰهُ ۗ وَلَمْ يُصِرُّوْا عَلٰى مَا فَعَلُوْا وَهُمْ يَعْلَمُوْنَ(135) اُولٰۤىِٕكَ جَزَاۤؤُهُمْ مَّغْفِرَةٌ مِّنْ رَّبِّهِمْ وَجَنّٰتٌ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَا ۗ وَنِعْمَ اَجْرُ الْعٰمِلِيْنَ (136) ال عمران : 133-136"],["p","Dan bersegeralah kamu kepada ampunan dari Tuhanmu dan kepada surga yang luasnya seluas langit dan bumi yang disediakan untuk orang-orang yang bertaqwa, (133)"],["p","(yaitu) orang-orang yang menafkahkan (hartanya), baik di waktu lapang maupun sempit, dan orang-orang yang menahan amarahnya dan memaafkan (kesalahan) orang. Allah menyukai orang-orang yang berbuat kebajikan. (134)"],["p","Dan (juga) orang-orang yang apabila mengerjakan perbuatan keji atau menganiaya diri sendiri, mereka ingat akan Allah, lalu memohon ampun terhadap dosa-dosa mereka dan siapa lagi yang dapat mengampuni dosa selain daripada Allah? Dan mereka tidak meneruskan perbuatan kejinya itu, sedang mereka mengetahui. (135)"],["p","Mereka itu balasannya ialah ampunan dari Tuhan mereka dan surga yang di dalamnya mengalir sungai-sungai, sedang mereka kekal di dalamnya; dan itulah sebaik-baik pahala orang-orang yang beramal. (136) [QS. Ali ‘Imraan : 133-136]"],["h","2) Banyak mengingat mati dan kehidupan akhirat"],["p","Allah SWT berfirman:"],["a","قُلْ اِنَّ الْمَوْتَ الَّذِيْ تَفِرُّوْنَ مِنْهُ فَاِنَّهٗ مُلٰقِيْكُمْ ثُمَّ تُرَدُّوْنَ اِلٰى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُوْنَ. الجمعة : 8"],["p","Katakanlah: \"Sesungguhnya kematian yang kamu lari daripadanya, maka sesungguhnya kematian itu akan menemui kamu, kemudian kamu akan dikembalikan kepada (Allah), yang mengetahui yang ghaib dan yang nyata, lalu Dia beritakan kepadamu apa yang telah kamu kerjakan\". [QS. Al Jumu’ah : 8]"],["a","اَيْنَ مَا تَكُوْنُوْا يُدْرِكْكُّمُ الْمَوْتُ وَلَوْ كُنْتُمْ فِيْ بُرُوْجٍ مُّشَيَّدَةٍ . النساء : 78"],["p","Di mana saja kamu berada, kematian akan mendapatkan kamu, kendati pun kamu di dalam benteng yang tinggi lagi kokoh [QS. An Nisaa’ : 78]"],["a","كُلُّ نَفْسٍ ذَاۤىِٕقَةُ الْمَوْتِۗ وَاِنَّمَا تُوَفَّوْنَ اُجُوْرَكُمْ يَوْمَ الْقِيٰمَةِ ۗ فَمَنْ زُحْزِحَ عَنِ النَّارِ وَاُدْخِلَ الْجَنَّةَ فَقَدْ فَازَ ۗ وَمَا الْحَيٰوةُ الدُّنْيَآ اِلَّا مَتَاعُ الْغُرُوْرِ. ال عمران : 185"],["p","Tiap-tiap yang berjiwa akan merasakan mati. Dan sesungguhnya pada hari kiamat sajalah disempurnakan pahalamu. Barang siapa dijauhkan dari neraka dan dimasukkan ke dalam surga, maka sungguh ia telah beruntung. Kehidupan dunia itu tidak lain hanyalah kesenangan yang memperdayakan. [QS. Ali ‘Imraan : 185]"],["a","وَمَا هٰذِهِ الْحَيٰوةُ الدُّنْيَآ اِلَّا لَهْوٌ وَّلَعِبٌۗ وَاِنَّ الدَّارَ الْاٰخِرَةَ لَهِيَ الْحَيَوَانُۘ لَوْ كَانُوْا يَعْلَمُوْنَ . العنكبوت : 64"],["p","Dan tiadalah kehidupan dunia ini melainkan senda gurau dan main-main. Dan sesungguhnya akhirat itulah yang sebenarnya kehidupan, kalau mereka mengetahui. [QS. Al ‘Ankabuut : 64]"],["p","Di dalam hadits disebutkan"],["a","عَنْ اَبيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اَكْثِرُوْا ذِكْرَ هَاذِمِ اللَّذَّاتِ، يَعْنِى الْمَوْتَ. ابن ماجه 2: 1422، رقم: 4258"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Perbanyaklah mengingat pemutus kelezatan-kelezatan, yaitu mati”. [HR, Ibnu Majah juz 2, hal. 1422, no. 4258]"],["a","عَنْ اَبيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اَكْثِرُوْا ذِكْرَ هَاذِمِ اللَّذَّاتِ، اَلْمَوْتَ. ابن حبان 7: 259، رقم: 2992"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Perbanyaklah mengingat pemutus kelezatan-kelezatan, yaitu mati”. [HR, Ibnu Hibban juz 7, hal. 259, no. 2992]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : زُوْرُوا الْقُبُوْرَ فَاِنَّـهَا تُذَكِّرُكُمُ الْآخِرَةَ. ابن ماجه 1: 500، رقم: 1569"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Berziyarah quburlah kalian, karena hal itu akan mengingatkan kalian pada akhirat”. [HR. Ibnu Majah juz 1, hal. 500, no. 1569]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: زَارَ النَّبِيُّ ﷺ قَبْرَ اُمِّهِ فَبَكَى وَاَبْكَى مَنْ حَوْلَهُ. فَقَالَ: اِسْتَأْذَنْتُ رَبِّيْ فِيْ اَنْ اَسْتَغْفِرَ لَـهَا فَلَمْ يُؤْذَنْ لِيْ وَاسْتَأْذَنْتُهُ فِيْ اَنْ اَزُوْرَ قَبْرَهَا فَاُذِنَ لِيْ، فَزُوْرُوا الْقُبُوْرَ، فَاِنَّـهَا تُذَكِّرُ الْمَوْتَ. مسلم 2: 671"],["p","Dari Abu Hurairah, ia berkata : Nabi SAW pernah berziyarah qubur ke qubur ibunya, lalu beliau menangis, dan menyebabkan menangis pula orang-orang yang di sekitarnya. Lalu beliau bersabda, “Aku minta idzin kepada Tuhanku untuk memintakan ampun ibuku, tetapi aku tidak diidzinkan. Dan aku minta idzin kepada-Nya untuk menziyarahi qubur ibuku, lalu diidzinkan. Maka berziyarah quburlah kalian, karena ziyarah qubur itu mengingatkan mati”. [HR. Muslim juz 2, hal. 671, no. 108]"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: يَتْبَعُ الْمَيِّتَ ثَلَاثَةٌ، فَيَرْجِعُ اثْنَانِ وَيَبْقَى وَاحِدٌ. يَتْبَعُهُ اَهْلُهُ وَمَالُهُ وَعَمَلُهُ، فَيَرْجِعُ اَهْلُهُ وَمَالُهُ، وَيَبْقَى عَمَلُهُ. مسلم 4: 2273"],["p","Dari Anas bin Maalik, ia berkata : Rasulullah SAW bersabda, \"Ada tiga hal yang mengikuti mayyit, yang dua akan kembali, sedangkan yang satu tetap menemaninya. Yang mengikutinya adalah keluarganya, hartanya dan amalnya. Lalu keluarganya dan hartanya akan kembali, sedangkan amalnya akan tetap menemaninya\". [HR. Muslim juz 4, hal. 2273, no. 5]"],["p","Allah SWT berfirman :"],["a","مَنْ كَانَ يُرِيْدُ حَرْثَ الْاٰخِرَةِ نَزِدْ لَهٗ فِيْ حَرْثِهٖ ۚ وَمَنْ كَانَ يُرِيْدُ حَرْثَ الدُّنْيَا نُؤْتِهٖ مِنْهَاۙ وَمَا لَهٗ فِى الْاٰخِرَةِ مِنْ نَّصِيْبٍ .الشورى :٢٠"],["p","Barangsiapa yang menghendaki keuntungan di akhirat akan Kami tambah keuntungan itu baginya, dan barangsiapa yang menghendaki keuntungan di dunia akan Kami berikan kepadanya sebagian dari keuntungan dunia dan tidak ada baginya suatu bahagian pun di akhirat. [QS. Asy Syuuraa : 20]"],["a","وَابْتَغِ فِيْمَآ اٰتٰىكَ اللّٰهُ الدَّارَ الْاٰخِرَةَ وَلَا تَنْسَ نَصِيْبَكَ مِنَ الدُّنْيَا وَاَحْسِنْ كَمَآ اَحْسَنَ اللّٰهُ اِلَيْكَ وَلَا تَبْغِ الْفَسَادَ فِى الْاَرْضِ ۗ اِنَّ اللّٰهَ لَا يُحِبُّ الْمُفْسِدِيْنَ. القصص :٧٧"],["p","Dan carilah pada apa yang telah dianugerahkan Allah kepadamu (kebahagiaan) negeri akhirat, dan janganlah kamu melupakan bahagianmu dari (kenikmatan) duniawi dan berbuat baiklah (kepada orang lain) sebagaimana Allah telah berbuat baik kepadamu, dan janganlah kamu berbuat kerusakan di (muka) bumi. Sesungguhnya Allah tidak menyukai orang-orang yang berbuat kerusakan. [QS. Al Qashash : 77]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ قَيْسٍ قَالَ: سَمِعْتُ مُسْتَوْرِدًا اَخَا بَنِيْ فِهْرٍ يَقُوْلُ: قَالَ رَسُوْلُ اللهِ ﷺ : وَاللهِ، مَا الدُّنْيَا فِى الْاٰخِرَةِ اِلَّا مِثْلُ مَا يَجْعَلُ اَحَدُكُمْ اِصْبَعَهُ هٰذِهِ (وَاَشَارَ يَحْيَى بِالسَّبَّابَةِ) فِى الْيَمِّ فَلْيَنْظُرْ بِـمَ يَرْجِعُ. مسلم 4: 2193"],["p","Dari Qais, ia berkata : Aku mendengar Mustaurid saudara dari Bani Fihr berkata : Rasulullah SAW bersabda, \"Demi Allah, tidaklah kehidupan dunia ini jika dibandingkan dengan kehidupan akhirat, kecuali seperti salah seorang diantara kalian memasukkan jarinya ini ke dalam laut. (Yahya (perawi) sambil menunjukkan jari telunjuknya), maka lihatlah seberapa air yang menetes kembali\". [HR. Muslim juz 4, hal. 2193, no. 55]"],["a","عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : لَوْ كَانَتِ الدُّنْيَا تَعْدِلُ عِنْدَ اللهِ جَنَاحَ بَعُوْضَةٍ مَا سَقَى كَافِرًا مِنْهَا شَرْبَةَ مَاءٍ. الترمذى 3: 383، رقم: 2422"],["p","Dari Sahl bin Sa'ad, ia berkata : Rasulullah SAW bersabda, \"Seandainya dunia ini di sisi Allah ada nilainya sesayap nyamuk, niscaya Allah tidak akan memberi minum kepada orang kafir walaupun seteguk air\". [HR. Tirmidzi juz 3, hal. 383, no. 2422]"],["p","Allah SWT berfirman :"],["a","قَدْ اَفْلَحَ مَنْ تَزَكّٰىۙ (14)وَذَكَرَ اسْمَ رَبِّهٖ فَصَلّٰىۗ (15) بَلْ تُؤْثِرُوْنَ الْحَيٰوةَ الدُّنْيَاۖ(16)وَالْاٰخِرَةُ خَيْرٌ وَّاَبْقٰى (17) الاعلى : 14-17"],["p","Sesungguhnya beruntunglah orang yang membersihkan diri (dengan beriman),(14)"],["p","dan dia ingat nama Tuhannya, lalu dia mengerjakan shalat.(15)"],["p","Tetapi kamu (orang-orang kafir) memilih kehidupan duniawi.(16)"],["p","Sedang kehidupan akhirat adalah lebih baik dan lebih kekal.(17) [QS. Al A’laa : 14-17]"],["p","(Bersambung ….)"]],"c20220612_1285":[["p","Ahad, 12 Juni 2022/12 Dzul Qa’dah 1443 Brosur No. : 2080/2120/IA"],["p","Tazkiyatun Nafs (2)"],["h","3) Selalu berdzikir dan mohon ampun kepada Allah"],["p","Allah SWT berfirman :"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اذْكُرُوا اللّٰهَ ذِكْرًا كَثِيْرًاۙ (41) وَّسَبِّحُوْهُ بُكْرَةً وَّاَصِيْلًا (42) هُوَ الَّذِيْ يُصَلِّيْ عَلَيْكُمْ وَمَلٰۤىِٕكَتُهٗ لِيُخْرِجَكُمْ مِّنَ الظُّلُمٰتِ اِلَى النُّوْرِۗ وَكَانَ بِالْمُؤْمِنِيْنَ رَحِيْمًا (43) الاحزاب : 41-43"],["p","Hai orang-orang yang beriman, berdzikirlah (dengan menyebut nama) Allah, dzikir yang sebanyak-banyaknya. (41)"],["p","Dan bertasbihlah kepada-Nya di waktu pagi dan petang. (42)"],["p","Dialah yang memberi rahmat kepadamu dan malaikat-Nya (memohonkan ampunan untukmu), supaya Dia mengeluarkan kamu dari kegelapan kepada cahaya (yang terang). Dan adalah Dia Maha Penyayang kepada orang-orang yang beriman. (43) [QS. Al Ahzaab : 41-43]"],["a","وَاذْكُرْ رَّبَّكَ فِيْ نَفْسِكَ تَضَرُّعًا وَّخِيْفَةً وَّدُوْنَ الْجَهْرِ مِنَ الْقَوْلِ بِالْغُدُوِّ وَالْاٰصَالِ وَلَا تَكُنْ مِّنَ الْغٰفِلِيْنَ. الاعراف : 205"],["p","Dan sebutlah (nama) Tuhanmu dalam hatimu dengan merendahkan diri dan rasa takut, dan dengan tidak mengeraskan suara, di waktu pagi dan petang, dan janganlah kamu termasuk orang-orang yang lalai. [QS. Al A’raaf : 205]"],["a","قُلْ اَؤُنَبِّئُكُمْ بِخَيْرٍ مِّنْ ذٰلِكُمْ ۗ لِلَّذِيْنَ اتَّقَوْا عِنْدَ رَبِّهِمْ جَنّٰتٌ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَا وَاَزْوَاجٌ مُّطَهَّرَةٌ وَّرِضْوَانٌ مِّنَ اللّٰهِ ۗ وَاللّٰهُ بَصِيْرٌۢ بِالْعِبَادِۚ (15) اَلَّذِيْنَ يَقُوْلُوْنَ رَبَّنَآ اِنَّنَآ اٰمَنَّا فَاغْفِرْ لَنَا ذُنُوْبَنَا وَقِنَا عَذَابَ النَّارِۚ (16) اَلصّٰبِرِيْنَ وَالصّٰدِقِيْنَ وَالْقٰنِتِيْنَ وَالْمُنْفِقِيْنَ وَالْمُسْتَغْفِرِيْنَ بِالْاَسْحَارِ (17) ال عمران : 15-17"],["p","Katakanlah: \"Inginkah aku kabarkan kepadamu apa yang lebih baik dari yang demikian itu?\" Untuk orang-orang yang bertaqwa (kepada Allah), pada sisi Tuhan mereka ada surga yang mengalir di bawahnya sungai-sungai; mereka kekal di dalamnya. Dan (mereka dikaruniai) istri-istri yang disucikan serta keridlaan Allah: Dan Allah Maha Melihat akan hamba-hamba-Nya.(15)"],["p","(Yaitu) orang-orang yang berdo’a: \"Ya Tuhan kami, sesungguhnya kami telah beriman, maka ampunilah segala dosa kami dan peliharalah kami dari siksa neraka,\" (16)"],["p","(yaitu) orang-orang yang shabar, yang benar, yang tetap tha’at, yang menafkahkan hartanya (di jalan Allah), dan yang memohon ampun di waktu sahur. (17) [QS. Ali ‘Imraan : 15-17]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ اَبِيْ هُرَيْرَةَ عَنْ رَسُوْلِ اللهِ ﷺ اَنَّهُ قَالَ: قَالَ اللهُ عَزَّ وَجَلَّ: اَنَا عِنْدَ ظَنِّ عَبْدِيْ بيْ وَاَنَا مَعَهُ حَيْثُ يَذْكُرُنِيْ، وَاللهِ لَلّٰهُ اَفْرَحُ بِتَوْبَةِ عَبْدِهِ مِنْ اَحَدِكُمْ يَجِدُ ضَالَّتَهُ بِالْفَلَاةِ. وَمَنْ تَقَرَّبَ اِلَىَّ شِبْرًا تَقَرَّبْتُ اِلَيْهِ ذِرَاعًا، وَمَنْ تَقَرَّبَ اِلَىَّ ذِرَاعًا تَقَرَّبْتُ اِلَيْهِ بَاعًا، وَاِذَا اَقْبَلَ اِلَىَّ يَمْشِى اَقْبَلْتُ اِلَيْهِ اُهَرْوِلُ. مسلم 4: 2102 رقم 1"],["p","Dari Abu Hurairah, dari Rasulullah SAW, beliau bersabda, \"Allah 'Azza wa Jalla berfirman, \"Aku menurut persangkaan hamba-Ku kepada-Ku, dan Aku selalu bersamanya dimana saja ia mengingatku\". Rasulullah SAW bersabda, \"Demi Allah, sesungguhnya Allah lebih senang kepada taubat hamba-Nya daripada seseorang diantara kalian mendapatkan kembali barang-barangnya yang hilang di perjalanan di padang pasir\". Allah berfirman, \"Barangsiapa yang mendekat kepadaku sejengkal, Aku akan mendekat kepadanya sehasta. Dan barangsiapa mendekat kepada-Ku sehasta, Aku akan mendekat kepadanya sedepa. Dan apabila ia mendekat kepadaku dengan berjalan, Aku akan mendekat kepadanya dengan berlari\". [HR. Muslim juz 4, hal. 2102, no. 1]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ ﷺ: يَقُوْلُ اللهُ تَعَالَى: اَنَا عِنْدَ ظَنِّ عَبْدِيْ بِيْ وَاَنَا مَعَهُ اِذَا ذَكَرَنِيْ. فَاِنْ ذَكَرَنِيْ فِيْ نَفْسِهِ ذَكَرْتُهُ فِيْ نَفْسِيْ، وَاِنْ ذَكَرَنِيْ فِيْ مَلَأٍ ذَكَرْتُهُ فِيْ مَلَأٍ خَيْرٍ مِنْهُمْ. وَاِنْ تَقَرَّبَ اِلَيَّ بِشِبْرٍ تَقَرَّبْتُ اِلَيْهِ ذِرَاعًا. وَاِنْ تَقَرَّبَ اِلَيَّ ذِرَاعًا تَقَرَّبْتُ اِلَيْهِ بَاعًا. وَاِنْ اَتَانِيْ يَمْشِيْ اَتَيْتُهُ هَرْوَلَةً. البخارى 8: 171"],["p","Dari Abu Hurairah RA, ia berkata : Nabi SAW bersabda, \"Allah Ta'aalaa berfirman, \"Aku menurut persangkaan hamba-Ku terhadap-Ku, dan Aku besertanya apabila ia mengingat-Ku. Maka jika ia mengingat-Ku di hatinya, Aku pun mengingatnya pada diri-Ku, Jika ia mengingat (menyebut)-Ku pada sekumpulan orang, maka Aku menyebutnya dalam sekumpulan yang lebih baik dari pada mereka. Dan jika ia mendekat kepada-Ku sejengkal, maka Aku akan mendekat kepadanya sehasta. Jika ia mendekat kepada-Ku sehasta, maka Aku akan mendekat kepadanya sedepa. Dan jika ia datang kepada-Ku dengan berjalan, maka Aku akan datang kepadanya dengan berlari\". [HR. Bukhari juz 8, hal. 171]"],["h","4) Ikhlas dalam beramal dan menjauhi riyaa’"],["p","Allah SWT berfirman :"],["a","قُلْ اِنَّ صَلَاتِيْ وَنُسُكِيْ وَمَحْيَايَ وَمَمَاتِيْ لِلّٰهِ رَبِّ الْعٰلَمِيْنَۙ(162) لَا شَرِيْكَ لَهٗ ۚ وَبِذٰلِكَ اُمِرْتُ وَاَنَا۠ اَوَّلُ الْمُسْلِمِيْنَ (163) الانعام : 162-163"],["p","Katakanlah: \"Sesungguhnya shalatku, ibadahku, hidup dan matiku hanyalah untuk Allah, Tuhan semesta alam, (162)"],["p","tiada sekutu bagi-Nya; dan demikian itulah yang diperintahkan kepadaku dan aku adalah orang yang pertama-tama menyerahkan diri (kepada Allah)\". (163) [QS. Al An’aam : 162-163]"],["a","قُلْ اِنِّيْٓ اُمِرْتُ اَنْ اَعْبُدَ اللّٰهَ مُخْلِصًا لَّهُ الدِّيْنَ (11)وَاُمِرْتُ لِاَنْ اَكُوْنَ اَوَّلَ الْمُسْلِمِيْنَ (12) قُلْ اِنِّيْٓ اَخَافُ اِنْ عَصَيْتُ رَبِّيْ عَذَابَ يَوْمٍ عَظِيْمٍ (13) قُلِ اللّٰهَ اَعْبُدُ مُخْلِصًا لَّهٗ دِيْنِيْۚ (14) الزمر : 11-14"],["p","Katakanlah: \"Sesungguhnya aku diperintahkan supaya menyembah Allah dengan memurnikan ketha’atan kepada-Nya dalam (menjalankan) agama. (11)"],["p","Dan aku diperintahkan supaya menjadi orang yang pertama-tama berserah diri\". (12)"],["p","Katakanlah: \"Sesungguhnya aku takut akan siksaan hari yang besar jika aku durhaka kepada Tuhanku\".(13)"],["p","Katakanlah: \"Hanya Allah saja yang aku sembah dengan memurnikan ketha’atan kepada-Nya dalam (menjalankan) agamaku\".(14) [QS. Az Zumar : 11-14]"],["a","وَمَآ اُمِرُوْٓا اِلَّا لِيَعْبُدُوا اللّٰهَ مُخْلِصِيْنَ لَهُ الدِّيْنَ ۙ حُنَفَاۤءَ وَيُقِيْمُوا الصَّلٰوةَ وَيُؤْتُوا الزَّكٰوةَ وَذٰلِكَ دِيْنُ الْقَيِّمَةِ . البينة : 5"],["p","Padahal mereka tidak disuruh kecuali supaya menyembah Allah dengan memurnikan ketha’atan kepada-Nya dalam (menjalankan) agama dengan lurus, dan supaya mereka mendirikan shalat dan menunaikan zakat; dan yang demikian itulah agama yang lurus. [QS. Al Bayyinah : 5]"],["a","اِنَّ الْمُنٰفِقِيْنَ يُخٰدِعُوْنَ اللّٰهَ وَهُوَ خَادِعُهُمْۚ وَاِذَا قَامُوْٓا اِلَى الصَّلٰوةِ قَامُوْا كُسَالٰىۙ يُرَاۤءُوْنَ النَّاسَ وَلَا يَذْكُرُوْنَ اللّٰهَ اِلَّا قَلِيْلًا. النساء: 142"],["p","Sesungguhnya orang-orang munafik itu menipu Allah, dan Allah akan membalas tipuan mereka. Dan apabila mereka berdiri untuk shalat, mereka berdiri dengan malas. Mereka bermaksud riya’ (dengan shalat) di hadapan manusia. Dan tidaklah mereka menyebut Allah kecuali sedikit sekali. [QS. An Nisaa’ : 142]"],["p","Di dalam hadits disebutkan"],["a","عَنْ اَبِيْ اُمَامَةَ الْبَاهِلِيِّ قَالَ: جَاءَ رَجُلٌ اِلىَ النَّبِيِّ ﷺ فَقَالَ: اَرَأَيْتَ رَجُلًا غَزَا يَلْتَمِسُ الْاَجْرَ وَالذِّكْرَ، مَا لَهُ؟ فَقَالَ رَسُوْلُ اللهِ ﷺ : لَا شَيْئَ لَهُ. فَاَعَادَهَا ثَلَاثَ مَرَّاتٍ. يَقُوْلُ لَهُ رَسُوْلُ اللهِ ﷺ : لَا شَيْئَ لَهُ. ثُمَّ قَالَ: اِنَّ اللهَ لَا يَقْبَلُ مِنَ الْعَمَلِ اِلَّا مَا كَانَ لَهُ خَالِصًا وَابْتُغِيَ بِهِ وَجْهُهُ. النسائى 6: 25"],["p","Dari Abu Umamah Al-Bahiliy, ia berkata : Seorang laki-laki datang kepada Nabi SAW lalu bertanya, \"Bagaimanakah pendapat engkau apabila ada seorang laki-laki berperang untuk mencari pahala dan nama ? Lalu apa yang ia dapat ?\". Maka Rasulullah SAW bersabda, \"Ia tidak mendapatkan apa-apa\". Orang itu mengulangi pertanyaannya sampai tiga kali, dan Rasulullah SAW menjawab, \"Ia tidak mendapatkan apa-apa\". Kemudian beliau bersabda, \"Sesungguhnya Allah tidak mau menerima amal kecuali amal yang dilakukan dengan ikhlas karena Allah dan mencari keridlaan-Nya\". [HR. Nasaai juz 6, hal. 25]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: اِنَّ اَوَّلَ النَّاسِ يُقْضَى يَوْمَ الْقِيَامَةِ عَلَيْهِ رَجُلٌ اُسْتُشْهِدَ، فَاُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا. قَالَ: فَمَا عَمِلْتَ فِيْهَا؟ قَالَ: قَاتَلْتُ فِيْـكَ حَتَّى اسْتُشْهِدْتُ. قَالَ: كَذَبْتَ، وَلٰكِنَّكَ قَاتَلْتَ لِاَنْ يُقَالَ جَرِئٌ فَقَدْ قِيْلَ. ثُمَّ اُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ حَتَّى اُلْقِيَ فِى النَّارِ. وَرَجُلٌ تَعَلَّمَ اْلعِلْمَ وَعَلَّمَهُ وَقَرَأَ الْقُرْاۤنَ، فَاُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا. قَالَ: فَمَا عَمِلْـتَ فِيْهَا؟ قَالَ: تَعَلَّمْتُ الْعِلْمَ وَعَلَّمْتُهُ وَقَرَأْتُ فِيْكَ الْقُرْاۤنَ. قَالَ: كَذَبْتَ، وَلٰكِنَّكَ تَعَلَّمْتَ الْعِلْمَ لِيُقَالَ عَالِـمٌ وَقَرَأْتَ الْقُرْاۤنَ لِيُقَالَ هُوَ قَارِئٌ فَقَدْ قِيْلَ. ثُمَّ اُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ حَتَّى اُلْقِيَ فىِ النَّارِ. وَرَجُلٌ وَسَّعَ اللهُ عَلَيْهِ وَاَعْطَاهُ مِنْ اَصْنَافِ الْمَالِ كُلِّهِ، فَاُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا. قَالَ: فَمَا عَمِلْتَ فِيْهَا؟ قَالَ: مَا تَرَكْتُ مِنْ سَبِيْلٍ تُحِبُّ اَنْ يُنْفَقَ فِيْهَا اِلَّا اَنْفَقْتُ فِيْهَا لَكَ. قَالَ: كَذَبْتَ، وَلٰكِنَّكَ فَعَلْتَ لِيُقَالَ: هُوَ جَوَادٌ فَقَدْ قِيْلَ، ثُمَّ اُمِرَ بِهِ فَسُحِبَ عَلىَ وَجْهِهِ ثُـمَّ اُلْقِيَ فِى النَّارِ. مسلم 3: 1514 رقم 152"],["p","Dari Abu Hurairah RA, ia berkata : Saya telah mendengar Rasulullah SAW bersabda, \"Sesungguhnya yang pertama-tama akan diberi keputusan pada hari qiyamat ialah seorang yang mati syahid, lalu ia dibawa dan dihadapkan kepada ni’matnya, maka ia mengakuinya. Allah berfirman, \"Apakah yang kamu lakukan padanya ?\". Dia menjawab, \"Saya telah berjuang untuk-Mu hingga mati syahid\". Allah berfirman, \"Kamu berdusta, tetapi kamu berjuang supaya disebut sebagai pahlawan dan pemberani. Dan telah dikatakan orang yang demikian itu\". Kemudian diperintahkan (kepada malaikat), lalu dia diseret pada mukanya dan dilemparkan ke neraka."],["p","(Kedua) seorang yang belajar ilmu, mengajarkannya dan membaca Al-Qur'an, lalu dihadapkan kepada ni’matnya, maka dia mengakuinya. Allah berfirman, \"Apakah yang kamu lakukan padanya ?\". Dia menjawab, \"Saya mempelajari ilmu dan mengajarkannya serta membaca Al-Qur'an hanya untuk-Mu\". Allah berfirman, \"Kamu berdusta, tetapi kamu mempelajari ilmu supaya disebut sebagai seorang yang 'alim, dan kamu membaca Al-Qur'an supaya disebut sebagai seorang yang pandai membaca Al-Qur'an, dan telah dikatakan orang yang demikian itu\". Kemudian diperintahkan (kepada malaikat), lalu dia diseret pada mukanya dan dilemparkan ke neraka."],["p","(Ketiga) seorang hartawan yang diberi keluasan kekayaan yang bermacam-macam oleh Allah, lalu ia dihadapkan kepada ni’matnya, maka ia mengakuinya. Allah berfirman, \"Apakah yang kamu lakukan padanya ?\". Dia menjawab, \"Tidak satu jalanpun yang Engkau sukai agar jalan itu diberi harta, melainkan sudah saya beri dengan harta itu semata-mata untuk-Mu\". Allah berfirman, \"Kamu berdusta, tetapi kamu berbuat yang demikian itu, agar dikatakan sebagai orang yang dermawan, dan telah dikatakan orang yang demikian itu\". Kemudian diperintahkan (kepada malaikat), lalu dia diseret pada mukanya dan dilemparkan ke neraka\". [HR. Muslim juz 3, hal. 1514, no. 152]"],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ سَمَّعَ، سَمَّعَ اللهُ بِهِ، وَ مَنْ رَاءَى، رَاءَى اللهُ بِهِ. مسلم 4 : 2289 رقم 47"],["p","Dari Ibnu 'Abbas, ia berkata: Rasulullah SAW bersabda, \"Barangsiapa memperdengarkan amal kepada orang lain, maka Allah akan memalukannya (dihari qiyamat). Dan barangsiapa berbuat riya', maka Allah akan membalas riya'nya itu\". [HR. Muslim juz 4, hal. 2289, no. 47]"],["a","عَنْ مَحْمُوْدِ بْنِ لُبَيْدٍ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اِنَّ اَخْوَفَ مَا اَخَافُ عَلَيْكُمْ اَلشِّرْكُ الْاَصْغَرُ. قَالُوْا: وَمَا الشِّرْكُ الْاَصْغَرُ يَا رَسُوْلَ اللهِ؟ قَالَ: اَلرِّيَاءُ. يَقُوْلُ اللهُ عَزَّ وَجَلَّ لَـهُمْ يَوْمَ الْقِيَامَةِ اِذَا جُزِيَ النَّاسُ بِاَعْمَالِـهِمْ: اِذْهَبُوْا اِلىَ الَّذِيْنَ كُنْتُمْ تُرَاءُوْنَ فىِ الدُّنْيَا فَانْظُرُوْا هَلْ تَجِدُوْنَ عِنْدَهُمْ جَزَاءً؟ احمد 9: 160، رقم: 23692"],["p","Dari Mahmud bin Lubaid, bahwasanya Rasulullah SAW bersabda, “Sesungguhnya sesuatu yang paling aku khawatirkan atas kamu sekalian itu adalah syirik kecil”. Kemudian para shahabat bertanya, “Apa syirik kecil itu ya Rasulullah ?”. Rasulullah SAW menjawab, “(Syirik kecil itu ialah) riya’. Besok pada hari qiyamat ketika para manusia diberi balasan dengan amal-amal mereka, Allah ‘azza wa jalla akan berfirman kepada mereka, “Pergilah kamu sekalian kepada orang-orang yang dahulu kamu berbuat riya’ padanya ketika di dunia, maka lihatlah olehmu sekalian apakah kamu mendapati pahala pada mereka ?”. [HR. Ahmad, juz 9, hal. 160, no. 23692]"],["p","(Bersambung ….)"]],"c20220619_1286":[["p","Ahad, 19 Juni 2022/19 Dzul Qa’dah 1443 Brosur No. : 2081/2121/IA"],["p","Tazkiyatun Nafs (3)"],["p","5) Menjaga amalan-amalan yang wajib dan mendekatkan diri dengan amalan-amalan sunnah"],["p","Allah SWT berfirman :"],["a","اُتْلُ مَآ اُوْحِيَ اِلَيْكَ مِنَ الْكِتٰبِ وَاَقِمِ الصَّلٰوةَۗ اِنَّ الصَّلٰوةَ تَنْهٰى عَنِ الْفَحْشَاۤءِ وَالْمُنْكَرِ ۗ وَلَذِكْرُ اللّٰهِ اَكْبَرُ ۗ وَاللّٰهُ يَعْلَمُ مَا تَصْنَعُوْنَ. العنكبوت : 45"],["p","Bacalah apa yang telah diwahyukan kepadamu, yaitu Al Kitab (Al Qur'an) dan dirikanlah shalat. Sesungguhnya shalat itu mencegah dari (perbuatan-perbuatan) keji dan mungkar. Dan sesungguhnya mengingat Allah (shalat) adalah lebih besar (keutamaannya dari ibadah-ibadah yang lain). Dan Allah mengetahui apa yang kamu kerjakan. [QS. Al ‘Ankabuut : 45]"],["a","عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: بُنِيَ الْاِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ اَنْ لَا اِلٰهَ اِلَّا اللهُ واَنَّ مُحَمَّدًا رَسُوْلُ اللهِ، واِقَامِ الصَّلَاةِ، وَاِيْتَاءِ الزَّكَاةِ، وَصَوْمِ رَمَضَانَ، وَحَجِّ الْبَيْتِ. الترمذى 4 : 119 رقم 2736 هذا حديث حسن صحيح"],["p","Dari Ibnu ‘Umar, ia berkata: Rasulullah SAW bersabda: “ Islam didirikan atas lima sendi, yaitu 1) bersaksi bahwasanya tidak ada tuhan selain Allah dan bahwasanya Nabi Muhammad adalah utusan Allah, 2) mendirikan shalat, 3) menunaikan zakat, 4) puasa Ramadlan, dan 5) berhajji ke Baitullah.” [HR. Tirmidzi juz 4, hal, 119, no. 2736, ini hadits hasan shahih]"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ قَالَ: نُـهِيْنَا اَنْ نَسْأَلَ رَسُوْلَ اللهِ ﷺ عَنْ شَيْءٍ. فَكَانَ يُعْجِبُنَا اَنْ يَجِيْءَ الرَّجُلُ مِنْ اَهْلِ الْبَادِيَةِ الْعَاقِلُ فَيَسْأَلُهُ وَنَحْنُ نَسْمَعُ. فَجَاءَ رَجُلٌ مِنْ اَهْلِ الْبَادِيَةِ فَقَالَ: يَا مُحَمَّدُ، اَتَانَا رَسُوْلُكَ فَزَعَمَ لَنَا اَنَّكَ تَزْعُمُ اَنَّ اللهَ اَرْسَلَكَ. قَالَ: صَدَقَ. قَالَ: فَمَنْ خَلَقَ السَّمَاءَ؟ قَالَ: اَللهُ. قَالَ: فَمَنْ خَلَقَ الْاَرْضَ؟ قَالَ: اَللهُ. قَالَ: فَمَنْ نَصَبَ هٰذِهِ الْجِبَالَ وَجَعَلَ فِيْهَا مَا جَعَلَ؟ قَالَ: اَللهُ. قَالَ: فَبِالَّذِيْ خَلَقَ السَّمَاءَ وَخَلَقَ اْلاَرْضَ وَنَصَبَ هٰذِهِ الْجِبَالَ، آللهُ اَرْسَلَكَ؟ قَالَ: نَعَمْ. قَالَ: وَزَعَمَ رَسُوْلُكَ اَنَّ عَلَيْنَا خَمْسَ صَلَوَاتٍ فِيْ يَوْمِنَا وَلَيْلَتِنَا. قَالَ: صَدَقَ. قَالَ: فَبِالَّذِيْ اَرْسَلَكَ، آللهُ اَمَرَكَ بِـهٰذَا؟ قَالَ: نَعَمْ. قَالَ: وَزَعَمَ رَسُوْلُكَ اَنَّ عَلَيْنَا زَكَاةً فِى اَمْوَالِنَا. قَالَ: صَدَقَ. قَالَ: فَبِالَّذِيْ اَرْسَلَكَ، آللهُ اَمَرَكَ بِـهٰذَا؟ قَالَ: نَعَمْ. قَالَ: وَزَعَمَ رَسُوْلُكَ اَنَّ عَلَيْنَا صَوْمَ شَهْرِ رَمَضَانَ فِيْ سَنَتِنَا. قَالَ: صَدَقَ. قَالَ: فَبِالَّذِيْ اَرْسَلَكَ، آللهُ اَمَرَكَ بِـهٰذَا؟ قَالَ: نَعَمْ. قَالَ: وَزَعَمَ رَسُوْلُكَ اَنَّ عَلَيْنَا حَجَّ اْلبَيْتِ مَنِ اسْتَطَاعَ اِلَيْهِ سَبِيْلًا. قَالَ: صَدَقَ. قَالَ: ثُـمَّ وَلَّى. قَالَ: وَالَّذِى بَعَثَكَ بِالْحَقِّ، لَا اَزِيْدُ عَلَيْهِنَّ وَلَا اَنْقُصُ مِنْهُنَّ. فَقَالَ النَّبِيُّ ﷺ: فَاِنْ صَدَقَ لَيَدْخُلَنَّ الْجَنَّةَ. مسلم 1: 41 رقم 10"],["p","Dari Anas bin Malik, ia berkata : Dahulu kami dicegah untuk bertanya kepada Rasulullah SAW tentang sesuatu (yang tidak perlu). Lalu kami merasa senang, karena ada seorang laki-laki dari penduduk Badiyah (orang ‘Arab gunung) yang cerdas, ia bertanya kepada beliau dan kami mendengarnya. Ada seorang laki-laki penduduk Badiyah datang seraya bertanya, “Hai Muhammad, telah datang utusanmu menyampaikan kepada kami, bahwa engkau mengatakan bahwa Allah telah mengutus engkau”. Beliau SAW bersabda, “Benar”. Orang itu lalu bertanya, “Siapakah yang menciptakan langit ?”. Beliau SAW bersabda, “Allah”. Ia bertanya, “Siapa yang menciptakan bumi ?”. Beliau SAW bersabda, “Allah”. Ia bertanya, “Siapakah yang menancapkan gunung-gunung ini dan menjadikan padanya apa-apa yang ada padanya ?”. Beliau SAW bersabda, “Allah”. Ia bertanya lagi, “Demi Tuhan yang telah menciptakan langit, bumi, menancapkan gunung-gunung ini, apakah Allah mengutusmu ?”. Beliau SAW bersabda, “Ya”. Ia berkata, “Dan utusanmu menyampaikan kepada kami bahwa diwajibkan atas kami shalat lima waktu sehari semalam”. Beliau bersabda, “Benar”. Ia bertanya, “Demi Tuhan yang telah mengutus engkau, apakah Allah yang menyuruhmu dengan semua ini ?”. Beliau bersabda, “Ya”. Ia berkata, “Dan utusanmu menyampaikan bahwa wajib atas kami untuk menunaikan zakat dari harta kami”. Beliau bersabda, “Benar”. Ia bertanya, “Demi Tuhan yang telah mengutusmu, apakah Allah menyuruhmu demikian ?”. Beliau SAW bersabda, “Ya”. Ia berkata, “Dan utusanmu menyampaikan kepada kami bahwa wajib atas kami puasa bulan Ramadlan setiap tahun”. Beliau SAW bersabda, “Benar”. Ia bertanya, “Demi Tuhan yang telah mengutusmu, apakah Allah menyuruhmu demikian itu ?”. Beliau SAW bersabda, “Ya”. Ia berkata, “Dan utusanmu menyampaikan kepada kami bahwa wajib atas kami untuk berhajji ke Baitullah bagi orang yang mampu melakukan perjalanannya”. Beliau SAW bersabda, “Benar”. (Anas bin Malik) berkata : Lalu orang itu berpaling sambil berkata, “Demi Tuhan yang telah mengutus engkau dengan benar, aku tidak akan menambah dan tidak akan mengurangi dari semua itu”. Nabi SAW bersabda, “Sungguh, jika benar (yang dikatakan itu), pasti ia masuk surga”. [HR. Muslim juz 1, hal. 41, no. 10]"],["a","عَنْ اَبِيْ هُرَيْرَةَ اَنَّ النَّبِيَّ ﷺ قَالَ: اِنَّ اَوَّلَ مَا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ صَلَاتُهُ. فَاِنْ وُجِدَتْ تَامَّةً كُتِبَتْ تَامَّةً وَاِنْ كَانَ انْتَقَصَ مِنْهَا شَيْءٌ، قَالَ: اُنْظُرُوْا هَلْ تَجِدُوْنَ لَهُ مِنْ تَطَوُّع ٍيُكَمِّلُ لَهُ مَا ضَيَّعَ مِنْ فَرِيْضَةٍ مِنْ تَطَوُّعِهِ. ثُـمَّ سَائِرُ الْاَعْمَالِ تَجْرِيْ عَلَى حَسَبِ ذٰلِكَ. النسائى 1: 233"],["p","Dari Abu Hurairah, bahwasanya Nabi SAW bersabda, “Sesungguhnya pertama-tama perbuatan manusia yang akan dihisab pada hari qiyamat adalah shalat wajibnya. Maka apabila didapati shalat wajibnya itu sempurna, dicatatlah sempurna. Jika didapati shalat wajibnya itu ada kekurangannya, Allah berfirman (kepada para malaikat), “Lihatlah, apakah kalian mendapati shalat sunnahnya untuk menyempurnakan kekurangan shalat wajibnya”. Kemudian semua amal-amal yang wajib diperlakukan seperti itu”. [HR. Nasaiy juz 1, hal. 233]"],["a","عَنْ اَبِيْ هُرَيْرَةَ عَنْ رَسُوْلِ اللهِ ﷺ قَالَ: اَوَّلُ مَا يُحَاسَبُ بِهِ الْعَبْدُ صَلَاتُهُ، فَاِنْ كَانَ اَكْمَلَهَا، وَاِلَّا قَالَ اللهُ عَزَّ وَجَلَّ: اُنْظُرُوْا لِعَبْدِيْ مِنْ تَطَوُّعٍ، فَاِنْ وُجِدَ لَهُ تَطَوُّعٌ، قَالَ: اَكْمِلُوْا بِهِ الْفَرِيْضَةَ. النسائى 1: 234"],["p","Dari Abu Hurairah, dari Rasulullah SAW, beliau bersabda, “Pertama-tama perbuatan manusia yang akan dihisab pada hari qiyamat adalah shalat wajibnya. Jika ia telah menyempurnakan shalat wajibnya, selesailah persoalannya”. Dan jika tidak sempurna shalat wajibnya, Allah ‘Azza wa Jalla berfirman, “Lihatlah pada hamba-Ku dari shalat sunnahnya”, maka jika ia melakukan shalat sunnah, Allah berfirman, ”Sempurnakanlah shalat wajibnya itu dengan shalat sunnahnya”. [HR. Nasaiy juz 1, hal. 234]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ : اِنَّ اللهَ قَالَ: مَنْ عَادَى لِيْ وَلِيًّا فَقَدْ آذَنْتُهُ بِالْحَرْبِ، وَمَا تَقَرَّبَ اِلَيَّ عَبْدِيْ بِشَيْءٍ اَحَبَّ اِلَيَّ مِمَّا افْتَرَضْتُ عَلَيْهِ، وَمَا يَزَالُ عَبْدِيْ يَتَقَرَّبُ اِلَيَّ بِالنَّوَافِلِ حَتَّى اُحِبَّهُ، فَاِذَا اَحْبَبْتُهُ كُنْتُ سَمْعَهُ الَّذِيْ يَسْمَعُ بِهِ وَبَصَرَهُ الَّذِيْ يُبْصِرُ بِهِ وَيَدَهُ الَّتِيْ يَبْطِشُ بِهَا وَرِجْلَهُ الَّتِيْ يَمْشِيْ بِهَا، وَاِنْ سَأَلَنِيْ لَأُعْطِيَنَّهُ وَلَئِنِ اسْتَعَاذَنِيْ لَاُعِيْذَنَّهُ. وَمَا تَرَدَّدْتُ عَنْ شَيْءٍ اَنَا فَاعِلُهُ تَرَدُّدِيْ عَنْ نَفْسِ الْمُؤْمِنِ يَكْرَهُ الْمَوْتَ وَاَنَا اَكْرَهُ مَسَاءَتَهُ.البجارى 7 : 190"],["p","Dari Abu Hurairah, ia berkata: Rasulullah SAW bersabda: ”Sesungguhnya Allah berfirman:”Barangsiapa yang memusuhi wali-Ku (orang yang selalu tha’at kepada Allah dan ikhlas beribadah) maka sungguh Aku mengumumkan perang kepadanya. Dan sungguh hamba-Ku mendekatkan diri dengan sesuatu (amalan) yang Aku cintai dari apa-apa yang telah Aku wajibkan kepadanya. Dan tidak henti-hentinya hamba-Ku mendekatkan diri kepada-Ku dengan amalan-amalan sunnah sehingga Aku mencintainya. Apabila aku mencintainya, maka aku yang menjadi pendengarannya yang ia mendengar dengannya, dan menjadi penglihatannya yang ia melihat dengannya, menjadi tangannya yang ia berbuat dengannya, menjadi kakinya yang ia berjalan dengannya. Dan jika ia meminta kepada-Ku, pasti Aku memberinya, dan jika ia memohon perlindungan kepada-Ku, pasti Aku melindunginya. Dan sungguh Aku berulang-ulang melakukan sesuatu terhadap jiwa orang mukmin, ia tidak suka kematian sedangkan Aku tidak suka keburukannya.” (HR. Bukhari juz 7, hal. 190)"],["p","Keterangan :"],["p","- Yang dimaksud “Aku yang menjadi pendengarannya yang ia mendengar dengannya, dan menjadi penglihatannya yang ia melihat dengannya … dst” ialah pendengaran hamba tersebut selalu digunakan untuk mendengarkan hal-hal yang diridlai Allah, begitupula penglihatannya selalu digunakan untuk melihat hal-hal yang diridlai Allah, begitu seterusnya."],["p","- Namun demikian, kalau sudah waktunya, Allah akan mewafatkannya, karena Allah tidak suka keburukannya (apabila ia lebih lama lagi hidup yang mungkin saja ia akan mengalami keburukan)."],["h","6) Mentadabburi Al Qur’an"],["p","Allah SWT berfirman :"],["a","كِتٰبٌ اَنْزَلْنٰهُ اِلَيْكَ مُبٰرَكٌ لِّيَدَّبَّرُوْٓا اٰيٰتِهٖ وَلِيَتَذَكَّرَ اُولُوا الْاَلْبَابِ.ص: 29"],["p","Ini adalah sebuah kitab yang Kami turunkan kepadamu penuh dengan berkah supaya mereka memperhatikan ayat-ayatnya dan supaya mendapat pelajaran orang-orang yang mempunyai pikiran. [QS. Shaad : 29]"],["a","اَلَمْ يَأْنِ لِلَّذِيْنَ اٰمَنُوْٓا اَنْ تَخْشَعَ قُلُوْبُهُمْ لِذِكْرِ اللّٰهِ وَمَا نَزَلَ مِنَ الْحَقِّۙ وَلَا يَكُوْنُوْا كَالَّذِيْنَ اُوْتُوا الْكِتٰبَ مِنْ قَبْلُ فَطَالَ عَلَيْهِمُ الْاَمَدُ فَقَسَتْ قُلُوْبُهُمْۗ وَكَثِيْرٌ مِّنْهُمْ فٰسِقُوْنَ . الحديد : 16"],["p","Belumkah datang waktunya bagi orang-orang yang beriman, untuk tunduk hati mereka mengingat Allah dan kepada kebenaran yang telah turun (kepada mereka), dan janganlah mereka seperti orang-orang yang sebelumnya telah diturunkan Al Kitab kepadanya, kemudian berlalulah masa yang panjang atas mereka lalu hati mereka menjadi keras. Dan kebanyakan di antara mereka adalah orang-orang yang fasiq. [QS. Al Hadiid : 16]"],["a","يٰٓاَيُّهَا النَّاسُ قَدْ جَاۤءَتْكُمْ مَّوْعِظَةٌ مِّنْ رَّبِّكُمْ وَشِفَاۤءٌ لِّمَا فِى الصُّدُوْرِۙ وَهُدًى وَّرَحْمَةٌ لِّلْمُؤْمِنِيْنَ (57) قُلْ بِفَضْلِ اللّٰهِ وَبِرَحْمَتِهٖ فَبِذٰلِكَ فَلْيَفْرَحُوْاۗ هُوَ خَيْرٌ مِّمَّا يَجْمَعُوْنَ (58) يونس : 57-58"],["p","Hai manusia, sesungguhnya telah datang kepadamu pelajaran dari Tuhanmu dan penyembuh bagi penyakit-penyakit (yang berada) dalam dada dan petunjuk serta rahmat bagi orang-orang yang beriman. (57)"],["p","Katakanlah: \"Dengan karunia Allah dan rahmat-Nya, hendaklah dengan itu mereka bergembira. Karunia Allah dan rahmat-Nya itu adalah lebih baik dari apa yang mereka kumpulkan\". (58) [QS. Yunus : 57-58]"],["h","7) Bermuhaasabah apa yang telah dilakukan untuk bekal akhirat"],["p","Allah SWT berfirman :"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَلْتَنْظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍۚ وَاتَّقُوا اللّٰهَ ۗ اِنَّ اللّٰهَ خَبِيْرٌ ۢ بِمَا تَعْمَلُوْنَ (18) وَلَا تَكُوْنُوْا كَالَّذِيْنَ نَسُوا اللّٰهَ فَاَنْسٰىهُمْ اَنْفُسَهُمْۗ اُولٰۤىِٕكَ هُمُ الْفٰسِقُوْنَ (19) لَا يَسْتَوِيْٓ اَصْحٰبُ النَّارِ وَاَصْحٰبُ الْجَنَّةِۗ اَصْحٰبُ الْجَنَّةِ هُمُ الْفَاۤىِٕزُوْنَ(20)الحشر:18-20"],["p","Hai orang-orang yang beriman, bertaqwalah kepada Allah dan hendaklah setiap diri memperhatikan apa yang telah diperbuatnya untuk hari esok (akhirat), dan bertaqwalah kepada Allah, sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan. (18)"],["p","Dan janganlah kamu seperti orang-orang yang lupa kepada Allah, lalu Allah menjadikan mereka lupa kepada diri mereka sendiri. Mereka itulah orang-orang yang fasiq. (19)"],["p","Tiada sama penghuni-penghuni neraka dengan penghuni-penghuni surga; penghuni-penghuni surga itulah orang-orang yang beruntung. (20) [QS. Al Hasyr : 18-20]"],["a","قُلْ هَلْ نُنَبِّئُكُمْ بِالْاَخْسَرِيْنَ اَعْمَالًا ۗ (103) اَلَّذِيْنَ ضَلَّ سَعْيُهُمْ فِى الْحَيٰوةِ الدُّنْيَا وَهُمْ يَحْسَبُوْنَ اَنَّهُمْ يُحْسِنُوْنَ صُنْعًا (104) الكهف: 103-104"],["p","Katakanlah: \"Apakah akan Kami beritahukan kepadamu tentang orang-orang yang paling merugi perbuatannya?\" (103)"],["p","Yaitu orang-orang yang telah sia-sia perbuatannya dalam kehidupan dunia ini, sedangkan mereka menyangka bahwa mereka berbuat sebaik-baiknya. (104). [QS. Al Kahfi : 103-104]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ اَبِيْ بَرْزَةَ الْاَسْلَمِيِّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا تَزُوْلُ قَدَمَا عَبْدٍ حَتَّى يُسْأَلَ عَنْ عُمْرِهِ فِيْمَا اَفْنَاهُ، وَعَنْ عِلْمِهِ فِيْمَا فَعَلَ، وَعَنْ مَالِهِ مِنْ اَيْنَ اكْتَسَبَهُ وَفِيْمَا اَنْفَقَهُ، وَعَنْ جِسْمِهِ فِيْمَا اَبْلَاهُ. الترمذى 4: 36، رقم: 2532، هذا حديث حسن صحيح"],["p","Dari Abu Barzah Al-Aslamiy, ia berkata : Rasulullah SAW bersabda, “Tidaklah bergerak kedua tapak kaki seorang hamba (pada hari qiyamat), sehingga ia ditanya tentang umurnya untuk apa ia habiskan, tentang ilmunya untuk apa ia gunakan, tentang hartanya dari mana ia mendapatkannya dan untuk apa ia belanjakan, dan tentang badannya untuk apa ia gunakan”. [HR. Tirmidzi juz 4, hal. 36, no. 2532, ia berkata : Ini hadits hasan shahih]"],["p","(Bersambung …)"]],"c20220626_1287":[["p","Ahad, 26 Juni 2022/26 Dzul Qa’dah 1443 Brosur No. : 2082/2122/IA"],["p","Tazkiyatun Nafs (4)"],["h","8) Tunduk patuh, tha’at kepada Allah dan Rasul-Nya"],["p","Firman Allah SWT :"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَقُوْلُوْا قَوْلًا سَدِيْدًاۙ (70) يُّصْلِحْ لَكُمْ اَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوْبَكُمْۗ وَمَنْ يُّطِعِ اللّٰهَ وَرَسُوْلَهٗ فَقَدْ فَازَ فَوْزًا عَظِيْمًا (71) الاحزاب : 70-71"],["p","Hai orang-orang yang beriman, bertakwalah kamu kepada Allah dan katakanlah perkataan yang benar,(70)"],["p","niscaya Allah memperbaiki bagimu amalan-amalanmu dan mengampuni bagimu dosa-dosamu. Dan barang siapa mentha’ati Allah dan Rasul-Nya, maka sesungguhnya ia telah mendapat kemenangan yang besar. (71) [QS. Al Ahzaab : 70-71]"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اَطِيْعُوا اللّٰهَ وَاَطِيْعُوا الرَّسُوْلَ وَاُولِى الْاَمْرِ مِنْكُمْۚ فَاِنْ تَنَازَعْتُمْ فِيْ شَيْءٍ فَرُدُّوْهُ اِلَى اللّٰهِ وَالرَّسُوْلِ اِنْ كُنْتُمْ تُؤْمِنُوْنَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِۗ ذٰلِكَ خَيْرٌ وَّاَحْسَنُ تَأْوِيْلًا. النساء : 59"],["p","Hai orang-orang yang beriman, tha’atilah Allah dan tha’atilah Rasul-Nya, dan ulil amri di antara kamu. Kemudian jika kamu berlainan pendapat tentang sesuatu, maka kembalikanlah ia kepada Allah (Al Qur'an) dan Rasul (sunnahnya), jika kamu benar-benar beriman kepada Allah dan hari kemudian. Yang demikian itu lebih utama (bagimu) dan lebih baik akibatnya. [QS. An Nisaa’ : 59]"],["a","قُلْ اِنْ كُنْتُمْ تُحِبُّوْنَ اللّٰهَ فَاتَّبِعُوْنِيْ يُحْبِبْكُمُ اللّٰهُ وَيَغْفِرْ لَكُمْ ذُنُوْبَكُمْ ۗ وَاللّٰهُ غَفُوْرٌ رَّحِيْمٌ (31) قُلْ اَطِيْعُوا اللّٰهَ وَالرَّسُوْلَ ۚ فَاِنْ تَوَلَّوْا فَاِنَّ اللّٰهَ لَا يُحِبُّ الْكٰفِرِيْنَ(32) ال عمران : 31-32"],["p","Katakanlah: \"Jika kamu (benar-benar) mencintai Allah, ikutilah aku, niscaya Allah mengasihi dan mengampuni dosa-dosamu.\" Allah Maha Pengampun lagi Maha Penyayang. (31)"],["p","Katakanlah: \"Tha’atilah Allah dan Rasul-Nya; jika kamu berpaling, maka sesungguhnya Allah tidak menyukai orang-orang kafir\". (32) [QS. Ali ‘Imraan : 31-32]"],["a","وَاَطِيْعُوا اللّٰهَ وَرَسُوْلَهٗ وَلَا تَنَازَعُوْا فَتَفْشَلُوْا وَتَذْهَبَ رِيْحُكُمْ وَاصْبِرُوْاۗ اِنَّ اللّٰهَ مَعَ الصّٰبِرِيْنَ . الانفال : 46"],["p","Dan tha’atlah kepada Allah dan Rasul-Nya dan janganlah kamu berbantah-bantahan, yang menyebabkan kamu menjadi gentar dan hilang kekuatanmu dan bershabarlah. Sesungguhnya Allah beserta orang-orang yang shabar. [QS. Al Anfaal : 46]"],["a","وَاَطِيْعُوا اللّٰهَ وَاَطِيْعُوا الرَّسُوْلَ وَاحْذَرُوْا ۚ فَاِنْ تَوَلَّيْتُمْ فَاعْلَمُوْٓا اَنَّمَا عَلٰى رَسُوْلِنَا الْبَلٰغُ الْمُبِيْنُ . المائدة : 92"],["p","Dan tha’atlah kamu kepada Allah dan tha’atlah kamu kepada Rasul (Nya) dan berhati-hatilah. Jika kamu berpaling, maka ketahuilah bahwa sesungguhnya kewajiban Rasul Kami, hanyalah menyampaikan (amanat Allah) dengan terang. [QS. Al Maaidah : 92]"],["a","وَمَنْ يُّطِعِ اللّٰهَ وَرَسُوْلَهٗ يُدْخِلْهُ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَا ۗ وَذٰلِكَ الْفَوْزُ الْعَظِيْمُ . النساء : 13"],["p","Barangsiapa tha’at kepada Allah dan Rasul-Nya, niscaya Allah memasukkannya ke dalam surga yang mengalir di dalamnya sungai-sungai, sedang mereka kekal di dalamnya; dan itulah kemenangan yang besar. [QS. An Nisaa’ : 13]"],["a","اِنَّمَا كَانَ قَوْلَ الْمُؤْمِنِيْنَ اِذَا دُعُوْٓا اِلَى اللّٰهِ وَرَسُوْلِهٖ لِيَحْكُمَ بَيْنَهُمْ اَنْ يَّقُوْلُوْا سَمِعْنَا وَاَطَعْنَاۗ وَاُولٰۤىِٕكَ هُمُ الْمُفْلِحُوْنَ (51) وَمَنْ يُّطِعِ اللّٰهَ وَرَسُوْلَهٗ وَيَخْشَ اللّٰهَ وَيَتَّقْهِ فَاُولٰۤىِٕكَ هُمُ الْفَاۤىِٕزُوْنَ (52) النور : 51-52"],["p","Sesungguhnya jawaban orang-orang mukmin, bila mereka dipanggil kepada Allah dan rasul-Nya agar rasul menghukum (mengadili) di antara mereka ialah ucapan.\" \"Kami mendengar dan kami patuh.\" Dan mereka itulah orang-orang yang beruntung. (51)"],["p","Dan barangsiapa yang tha’at kepada Allah dan rasul-Nya dan takut kepada Allah dan bertaqwa kepada-Nya, maka mereka adalah orang-orang yang mendapat kemenangan. (52) [QS. An Nuur: 51-52]"],["a","وَمَا كَانَ لِمُؤْمِنٍ وَّلَا مُؤْمِنَةٍ اِذَا قَضَى اللّٰهُ وَرَسُوْلُهٗٓ اَمْرًا اَنْ يَّكُوْنَ لَهُمُ الْخِيَرَةُ مِنْ اَمْرِهِمْ ۗ وَمَنْ يَّعْصِ اللّٰهَ وَرَسُوْلَهٗ فَقَدْ ضَلَّ ضَلٰلًا مُّبِيْنًا . الاحزاب : 36"],["p","Dan tidaklah patut bagi laki-laki yang mukmin dan tidak (pula) bagi perempuan yang mukmin, apabila Allah dan Rasul-Nya telah menetapkan suatu ketetapan, akan ada bagi mereka pilihan (yang lain) tentang urusan mereka. Dan barangsiapa mendurhakai Allah dan Rasul-Nya maka sungguhlah dia telah sesat, sesat yang nyata. [QS. Al Ahzaab : 36]"],["a","فَلَا وَرَبِّكَ لَا يُؤْمِنُوْنَ حَتّٰى يُحَكِّمُوْكَ فِيْمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوْا فِيْٓ اَنْفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوْا تَسْلِيْمًا .النساء : 65"],["p","Maka demi Tuhanmu, mereka (pada hakekatnya) tidak beriman hingga mereka menjadikan kamu hakim dalam perkara yang mereka perselisihkan, kemudian mereka tidak merasa keberatan dalam hati mereka terhadap putusan yang kamu berikan, dan mereka menerima dengan sepenuhnya. [QS. An Nisaa’ : 65]"],["a","يَوْمَ تُقَلَّبُ وُجُوْهُهُمْ فِى النَّارِ يَقُوْلُوْنَ يٰلَيْتَنَآ اَطَعْنَا اللّٰهَ وَاَطَعْنَا الرَّسُوْلَا۠(66) وَقَالُوْا رَبَّنَآ اِنَّآ اَطَعْنَا سَادَتَنَا وَكُبَرَاۤءَنَا فَاَضَلُّوْنَا السَّبِيْلَا۠ (67)رَبَّنَآ اٰتِهِمْ ضِعْفَيْنِ مِنَ الْعَذَابِ وَالْعَنْهُمْ لَعْنًا كَبِيْرًا (68) الاحزاب : 66-68"],["p","Pada hari ketika muka mereka dibolak-balikkan dalam neraka, mereka berkata: \"Alangkah baiknya, andai kata kami tha’at kepada Allah dan tha’at (pula) kepada Rasul\".(66)"],["p","Dan mereka berkata: \"Ya Tuhan kami, sesungguhnya kami telah mentha’ati pemimpin-pemimpin kami dan pembesar-pembesar kami, lalu mereka menyesatkan kami dari jalan (yang benar).(67)"],["p","Ya Tuhan kami, timpakanlah kepada mereka adzab dua kali lipat dan kutuklah mereka dengan kutukan yang besar\".(68) [QS. Al Ahzaab : 66-68]"],["a","لَقَدْ كَانَ لَكُمْ فِيْ رَسُوْلِ اللّٰهِ اُسْوَةٌ حَسَنَةٌ لِّمَنْ كَانَ يَرْجُوا اللّٰهَ وَالْيَوْمَ الْاٰخِرَ وَذَكَرَ اللّٰهَ كَثِيْرًا . الاحزاب : 21"],["p","Sesungguhnya telah ada pada (diri) Rasulullah itu suri teladan yang baik bagimu (yaitu) bagi orang yang mengharap (rahmat) Allah dan (kedatangan) hari qiyamat dan dia banyak menyebut Allah. [QS. Al Ahzaab : 21]"],["h","9) Tawaadlu’"],["p","Allah SWT berfirman:"],["a","وَلَا تَمْشِ فِى الْاَرْضِ مَرَحًاۚ اِنَّكَ لَنْ تَخْرِقَ الْاَرْضَ وَلَنْ تَبْلُغَ الْجِبَالَ طُوْلًا. الاسراء: 37"],["p","Dan janganlah kamu berjalan di muka bumi ini dengan sombong, karena sesungguhnya kamu sekali-kali tidak dapat menembus bumi dan sekali-kali kamu tidak akan sampai setinggi gunung. [QS. Al-Israa' : 37]"],["a","وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِى الْاَرْضِ مَرَحًاۗ اِنَّ اللّٰهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُوْرٍۚ (18) وَاقْصِدْ فِيْ مَشْيِكَ وَاغْضُضْ مِنْ صَوْتِكَۗ اِنَّ اَنْكَرَ الْاَصْوَاتِ لَصَوْتُ الْحَمِيْرِ (19) لقمان: 18-19"],["p","Dan janganlah kamu memalingkan mukamu dari manusia (karena sombong) dan janganlah kamu berjalan di muka bumi dengan angkuh. Sesungguhnya Allah tidak menyukai orang-orang yang sombong lagi membanggakan diri. (18)"],["p","Dan sederhanalah kamu dalam berjalan dan lunakkanlah suaramu. Sesungguhnya seburuk-buruk suara ialah suara keledai. (19) [QS. Luqmaan: 18-19]"],["a","يٰٓاَيُّهَا النَّاسُ اِنَّا خَلَقْنٰكُمْ مِّنْ ذَكَرٍ وَّاُنْثٰى وَجَعَلْنٰكُمْ شُعُوْبًا وَّقَبَاۤىِٕلَ لِتَعَارَفُوْا ۚ اِنَّ اَكْرَمَكُمْ عِنْدَ اللّٰهِ اَتْقٰىكُمْ ۗ اِنَّ اللّٰهَ عَلِيْمٌ خَبِيْرٌ. الحجرات : 13"],["p","Hai manusia, sesungguhnya Kami menciptakan kamu dari seorang laki-laki dan seorang perempuan dan menjadikan kamu berbangsa-bangsa dan bersuku-suku supaya kamu saling kenal mengenal. Sesungguhnya orang yang paling mulia di antara kamu di sisi Allah ialah orang yang paling bertaqwa di antara kamu. Sesungguhnya Allah Maha Mengetahui lagi Maha Mengenal. [QS. Al Hujuraat : 13]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ اَبِيْ نَضْرَةَ حَدَثَنِيْ مَنْ سَمِعَ خُطْبَةَ رَسُوْلِ اللهِ ﷺ فِيْ وَسَطِ اَيَّامِ التَّشْرِيْقِ. فَقَالَ: يَا اَيُّهَا النَّاسُ، اَلَا اِنَّ رَبَّكُمْ وَاحِدٌ، وَاِنَّ اَبَاكُمْ وَاحِدٌ، اَلَا لَا فَضْلَ لِعَرَبِيٍّ عَلَى اَعْجَمِيٍّ، وَلَا لِعَجَمِيٍّ عَلَى عَرَبِيٍّ، وَلَا لِأَحْمَرَ عَلَى أَسْوَدَ، وَلَا أَسْوَدَ عَلَى أَحْمَرَ، اِلَّا بِالتَّقْوَى. أَبَلَّغْتُ؟ قَالُوْا: بَلَّغَ رَسُوْلُ اللهِ ﷺ. ثُمَّ قَالَ: أَيُّ يَوْمٍ هٰذَا؟ قَالُوْا: يَوْمُ حَرَامٍ. ثُمَّ قَالَ: أَيُّ شَهْرٍ هٰذَا؟ قَالُوا: شَهْرُ حَرَامٍ. قَالَ: ثُمَّ قَالَ: أَيُّ بَلَدٍ هٰذَا؟ قَالُوْا: بَلَدُ حَرَامٍ. قَالَ: فَاِنَّ اللهَ قَدْ حَرَّمَ بَيْنَكُمْ دِمَاءَكُمْ وَاَمْوَالَكُمْ (قَالَ: وَلَا اَدْرِيْ قَالَ اَوْ اَعْرَاضَكُمْ اَمْ لَا) كَحُرْمَةِ يَوْمِكُمْ هٰذَا فِيْ شَهْرِكُمْ هٰذَا فِيْ بَلَدِكُمْ هٰذَا. أَبَلَّغْتُ؟ قَالُوْا: بَلَّغَ رَسُوْلُ اللهِ ﷺ. قَالَ: لِيُبَلِّغِ الشَّاهِدُ الْغَائِبَ. احمد 9 :127 رقم : 23548"],["p","Dari Abu Nadlroh, ia berkata: Telah menceritakan kepadaku orang yang mendengar khuthbahnya Rasulullah SAW pada pertengahan hari tasyriq. Rasulullah SAW bersabda:“Wahai para manusia! Ketahuilah, sesungguhnya Tuhan kalian itu satu. Dan sesungguhnya bapak kalian itu satu. Ketahuilah, tidak ada kelebihan orang Arab atas orang ‘Ajam (selain Arab), tidak ada kelebihan orang selain Arab atas orang Arab, tidak ada kelebihan orang kulit merah atas orang kulit hitam, dan tidak ada pula kelebihan orang kulit hitam atas orang kulit merah, melainkan dengan taqwa. Bukankah aku sudah menyampaikan? Para shahabat menjawab: “Rasulullah SAW sudah menyampaikan”. Beliau bertanya lagi: “Hari apa ini?” Para shahabat menjawab: “Hari Haram”. Beliau SAW bertanya lagi: “Bulan apa ini?” Para shahabat menjawab: “Bulan Haram.” Beliau SAW bertanya lagi: “Negeri apa ini?” Para shahabat menjawab: “Negeri Haram.” Beliau SAW bersabda: “Sesungguhnya Allah telah mengharamkan diantara kalian darah kalian dan harta benda kalian.(Shahabat yang mendengar khuthbah Rasulullah SAW tadi berkata: “Aku tidak tahu beliau SAW menyabdakan “dan kehormatan kalian.” atau tidak) seperti haramnya hari kalian ini, di bulan kalian ini dan di negeri kalian ini. Bukankah aku sudah menyampaikan?” Para shahabat menjawab: “Rasulullah SAW sudah menyampaikan.” Beliau SAW bersabda: “Hendaklah yang hadir menyampaikan kepada yang tidak hadir.” [HR. Ahmad juz 9 hal 127 no 23548]"],["a","عَنْ اَبيْ هُرَيْرَةَ عَنِ النَّبِيِّ ﷺ قَالَ: لَيَنْتَهِيَنَّ اَقْوَامٌ يَفْتَخِرُوْنَ بِاٰبَائِهِمُ الَّذِيْنَ مَاتُوْا، اِنَّمَا هُمْ فَحْمُ جَهَنَّمَ اَوْ لَيَكُوْنُنَّ اَهْوَنَ عَلَى اللهِ مِنَ الْجُعَلِ الَّذِيْ يُدَهْدِهُ الْخِرَاءَ بِاَنْفِهِ. اِنَّ اللهَ اَذْهَبَ عَنْكُمْ عُبِّيَّةَ الْجَاهِلِيَّةِ وَفَخْرَهَا بِالْاٰبَاءِ. اِنَّمَا هُوَ مُؤْمِنٌ تَقِيٌّ وَفَاجِرٌ شَقِيٌّ. اَلنَّاسُ كُلُّهُمْ بَنُوْ اٰدَمَ وَاٰدَمُ خُلِقَ مِنَ التُّرَابِ. الترمذى 5: 390، رقم: 4049، هذا حديث حسن"],["p","Dari Abu Hurairah, dari Nabi SAW, beliau bersabda, \"Hendaklah orang-orang itu berhenti dari membanggakan nenek-moyang mereka yang telah mati, sesungguhnya mereka itu menjadi bara api Jahannam, atau orang-orang itu akan menjadi lebih hina menurut pandangan Allah daripada kumbang pemakan kotoran yang mendorong kotoran dengan moncongnya. Sesungguhnya Allah telah menghilangkan dari kalian kesombongan jahiliyyah dan berbangga dengan nenek moyang. Sesungguhnya manusia itu hanya (ada dua), orang mukmin yang thaat atau orang jahat yang celaka. Manusia semuanya adalah keturunan Adam, dan Adam diciptakan dari tanah\". [HR. Tirmidzi juz 5, hal. 390, no. 4049, Ini hadits hasan]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اِنَّ اللهَ لَا يَنْظُرُ اِلىَ صُوَرِكُمْ وَاَمْوَالِكُمْ وَلٰكِنْ يَنْظُرُ اِلىَ قُلُوْبِكُمْ وَاَعْمَالِكُمْ. مسلم 4: 1987 رقم 34"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Sesungguhnya Allah tidak melihat (menilai) bentuk tubuhmu dan harta-bendamu, tetapi Allah melihat (menilai) pada hatimu dan amalmu\". [HR. Muslim juz 4, hal. 1987 no 34]"],["a","يٰٓاَيَّتُهَا النَّفْسُ الْمُطْمَىِٕنَّةُۙ (27) ارْجِعِيْٓ اِلٰى رَبِّكِ رَاضِيَةً مَّرْضِيَّةً ۚ (28) فَادْخُلِيْ فِيْ عِبٰدِيْۙ (29) وَادْخُلِيْ جَنَّتِيْ (30) الفجر : 27-30"],["p","Hai jiwa yang tenang.(27)"],["p","Kembalilah kepada Tuhanmu dengan hati yang puas lagi diridlai-Nya. (28)"],["p","Maka masuklah ke dalam jemaah hamba-hamba-Ku, (29)"],["p","dan masuklah ke dalam surga-Ku. (30) [QS. Al Fajr : 27 – 30]"],["p","Demikianlah semoga bermanfaat dan semoga Allah mengampuni kita. Aamiin!"],["p","--oo0oo--"]],"c20220703_1288":[["p","Ahad, 3 Juli 2022/04 Dzulhijjah 1443 Brosur No. : 2083/2123/IF"],["p","Qurban"],["h","1. Pengertian Qurban"],["p","Qurban berasal dari bahasa Arab :"],["a","قَرُبَ - يَقْرُبُ - قُرْبًا وَ قُرْبَانًا وَ قِرْبَانًا. المنجد"],["p","Artinya : \"Mendekat/pendekatan\"."],["p","Adapun pengertian Qurban menurut agama yaitu, \"Usaha pendekatan diri dari seorang hamba kepada Penciptanya dengan jalan menyembelih binatang ternak dan dilaksanakan dengan tuntunan, dalam rangka mencari ridla-Nya\"."],["p","Firman Allah SWT :"],["a","لَنْ يَّنَالَ اللهَ لُحُوْمُهَا وَلَا دِمَآؤُهَا وَلٰكِنْ يَّنَالُهُ التَّقْوٰى مِنْكُمْ، كَذٰلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُوا اللهَ عَلٰى مَا هَدٰىكُمْ، وَبَشِّرِ الْمُحْسِنِيْنَ.الحج: 37"],["p","Daging-daging unta itu sekali-kali tidak dapat mencapai (keridlaan) Allah dan tidak (pula) darahnya, tetapi taqwa dari pada kamulah yang dapat mencapainya. Demikianlah Allah telah menundukkannya untuk kamu supaya kamu mengagungkan Allah atas hidayah-Nya kepada kamu. Dan berilah khabar gembira kepada orang-orang yang berbuat baik. [QS. Al-Hajj : 37]"],["h","2. Hukum dan keutamaan Qurban"],["p","Menyembelih qurban pada hari raya 'Iedul Adlha dan hari Tasyriq (tanggal 10, 11, 12 dan 13 Dzulhijjah) ini, hukumnya adalah Sunnah Muakkadah."],["p","Adapun tentang keutamaan qurban, banyak diterangkan di dalam hadits-hadits dla’if, diantaranya sebagai berikut :"],["a","عَنْ عَائِشَةَ اَنَّ النَّبِيَّ ﷺ قَالَ: مَا عَمِلَ ابْنُ اٰدَمَ يَوْمَ النَّحْرِ عَمَلًا اَحَبَّ اِلَى اللهِ عَزَّ وَجَلَّ مِنْ هِرَاقَةِ دَمٍ، وَاِنَّهُ لَيَأْتِى يَوْمَ الْقِيَامَةِ بِقُرُوْنِـهَا وَاَظْلَافِهَا وَاَشْعَارِهَا، وَاِنَّ الدَّمَ لَيَقَعُ مِنَ اللهِ عَزَّ وَجَلَّ بِـمَكَانٍ قَبْلَ اَنْ يَقَعَ عَلَى الْاَرْضِ، فَطِيْبُوْا بِـهَا نَفْسًا. ابن ماجه 2: 1045، رقم: 3126، ضعيف، فى اسناده ابو المثنى و اسمه سليمان بن يزيد"],["p","Dari ‘Aisyah bahwasanya Nabi SAW bersabda, “Tidak ada amal anak Adam pada hari Nahr ('Iedul Adlha) yang paling disukai Allah ‘Azza wa Jalla selain daripada menyembelih qurban, qurban itu akan datang kepada orang-orang yang melakukannya pada hari qiyamat seperti semula, yaitu lengkap dengan anggotanya, tanduk, kuku dan bulunya. Darah qurban itu lebih dahulu jatuh ke suatu tempat yang disediakan Allah ‘Azza wa Jalla sebelum jatuh ke atas tanah. Oleh sebab itu, berqurbanlah kalian dengan senang hati. [HR. Ibnu Majah juz 2, hal. 1045, no. 3126, dlaif, karena dalam sanadnya ada perawi bernama Abul Mutsanna, yang nama aslinya Sulaiman bin Yazid, ia munkarul hadits, laisa bil qowiy (Mizaanul I’tidal 2 : 228 no 3524)]"],["a","عَنْ زَيْدِ بْنِ اَرْقَمَ قَالَ: قَالَ اَصْحَابُ رَسُوْلِ اللهِ ﷺ: يَا رَسُوْلَ اللهِ، مَا هٰذِهِ الْاَضَاحِيُّ؟ قَالَ: سُنَّةُ اَبِيْكُمْ اِبْرَاهِيْمَ. قَالُوْا: فَمَا لَنَا فِيْهَا يَا رَسُوْلَ اللهِ؟ قَالَ: بِكُلِّ شَعَرَةٍ حَسَنَةٌ. قَالُوْا: فَالصُّوْفُ يَا رَسُوْلَ اللهِ؟ قَالَ: بِكُلِّ شَعَرَةٍ مِنَ الصُّوْفِ حَسَنَةٌ. ابن ماجه 2: 1045، رقم: 3127، ضعيف فى اسناده ابو داود واسمه نفيع بن الحارث وعائذ الله"],["p","Dari Zaid bin Arqam, ia berkata : Para shahabat Rasulullah SAW bertanya, \"Ya Rasulullah, apakah udlhiyah itu ?\". Jawab Nabi SAW, \"Itulah sunnah ayahmu, Ibrahim\". Mereka bertanya, \"Apa yang kita peroleh dari udlhiyah itu, ya Rasulullah ?\". Jawab beliau, \"Pada tiap-tiap helai bulunya kita peroleh satu kebaikan. Lalu para shahabat bertanya, “Bagaimana dengan bulu domba, ya Rasulullah ?\". Beliau SAW bersabda, “Pada tiap-tiap helai bulu domba kita peroleh satu kebaikan”. [HR. Ibnu Majah 2 : 1045, no. 3127, dlaif karena dalam sanadnya ada perawi bernama Abu Dawud yang nama aslinya Nufai’ bin Al-Harits, ia matruukul hadits, (Mizaanul I’tidal 4 : 272 no 9115) dan ‘Aaidzullah, ia munkarul hadits (Mizaanul I’tidal 2 : 364, no. 4103)]."],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ وَجَدَ سَعَةً فَلَمْ يُضَحِّ فَلَا يَقْرَبَنَّ مُصَلَّاناَ. احمد 3: 207، رقم: 8280"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Barangsiapa yang mempunyai kemampuan untuk berqurban tetapi tidak mau melaksanakannya, maka janganlah ia dekat-dekat ke tempat shalat kami”. [HR. Ahmad juz 3, hal. 207, no. 8280, dla’if karena dalam sanadnya ada perawi bernama ‘Abdullah bin ‘Ayyaasy]."],["p","Keterangan :"],["p","Hadits riwayat Ahmad di atas dla’if, karena di dalam sanadnya ada perawi bernama ‘Abdullah bin ‘Ayyaasy. Abu Dawud dan Nasaaiy berkata, “Ia dla’if”. Ibnu Yunus berkata, “Ia munkarul hadits”. [Lihat Tahdzibut Tahdzib juz 5, hal. 307]"],["h","3. Tata cara Qurban"],["p","1. Waktu penyembelihan :"],["a","عَنِ البَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: ضَحَّى خَالٌ لِيْ يُقَالُ لَهُ اَبُوْ بُرْدَةَ قَبْلَ الصَّلَاةِ، فَقَالَ لَهُ رَسُوْلُ اللهِ ﷺ: شَاتُكَ شَاةُ لَحْمٍ. فَقَالَ: يَا رَسُولَ اللهِ، اِنَّ عِنْدِيْ دَاجِنًا جَذَعَةً مِنَ الْمَعَزِ. قَالَ: اِذْبَحْهَا، وَلَنْ تَصْلُحَ لِغَيْرِكَ. ثُـمَّ قَالَ: مَنْ ذَبَحَ قَبْلَ الصَّلَاةِ فَاِنَّـمَا يَذْبَحُ لِنَفْسِهِ، وَمَنْ ذَبَحَ بَعْدَ الصَّلَاةِ فَقَدْ تَـمَّ نُسُكُهُ وَاَصَابَ سُنَّةَ الْمُسْلِمِيْنَ. البخارى 6: 236"],["p","Dari Al-Baraa’ bin ‘Aazib RA, ia berkata : Pamanku yang bernama Abu Burdah menyembelih qurban sebelum shalat ‘Ied. Maka Rasulullah SAW bersabda, “Sembelihanmu itu sembelihan untuk dimakan (bukan qurban)”. Kemudian Abu Burdah berkata, “Ya Rasulullah, sesungguhnya saya masih mempunyai kambing jadza’ah yang bagus”. Rasulullah SAW bersabda, “Sembelihlah kambing itu, tetapi kebolehan ini tidak untuk selain kamu”. Kemudian Rasulullah SAW bersabda, “Barangsiapa yang menyembelih sebelum shalat 'ied, maka sesungguhnya ia hanya menyembelih untuk dirinya sendiri (yakni tidak dinilai sebagai ibadah qurban), dan barangsiapa menyembelih sesudah shalat ‘ied maka sempurnalah ibadah sembelihannya dan bersesuaian pelaksanaannya dengan sunnah kaum muslimin\". [HR. Bukhari juz 6, hal. 236]"],["a","عَنْ انَسٍ عَنِ النَّبِيِّ ﷺ قَالَ: مَنْ ذَبَحَ قَبْلَ الصَّلَاةِ فَلْيُعِدْ. البخارى 6: 238"],["p","Dari Anas, dari Nabi SAW, beliau bersabda, “Barangsiapa yang menyembelih sebelum shalat ‘ied, maka hendaklah ia mengulangi”. [HR. Bukhari juz 6, hal. 238]"],["p","Dan berdasar riwayat dari Sulaiman Ibnu Musa dari Jubair Ibnu Muth'im bahwa Nabi SAW bersabda :"],["a","كُلُّ اَيَّامِ التَّشْرِيْقِ ذَبْحٌ. احمد 5: 618، رقم: 16751"],["p","Setiap hari Tasyriq itu adalah hari menyembelih. [HR. Ahmad juz 5, hal. 618, no. 16751]"],["p","Dan riwayat lain dari ‘Ali RA yang semakna dengan yang tersebut diatas sebagai berikut :"],["a","اَيَّامُ النَّحْرِ يَوْمُ اْلاَضْحَى وَثَلَاثَةُ اَيَّامٍ بَعْدَهُ. فى نيل الاوطار 5: 142"],["p","Hari menyembelih itu ialah Hari Raya 'Iedul Adlha dan tiga hari sesudahnya. [Dalam Nailul Authar juz 5, hal. 142]"],["p","Dari hadits-hadits tersebut dapat diambil kesimpulan bahwa waktu yang sah untuk ibadah qurban adalah : \"Sesudah shalat 'Ied hingga akhir hari Tasyriq (tanggal 10, 11, 12 dan 13 Dzulhijjah)\"."],["p","Adapun waktu pelaksanaan shalat 'Iedul Adlha, sebagaimana sabda Nabi SAW :"],["a","قَالَ جُنْدَبٌ، كَانَ النَّبِيُّ ﷺ يُصَلِّى بِنَا يَوْمَ الْفِطْرِ وَالشَّمْسُ عَلَى قَيْدِ رُمْحَيْنِ وَالْاَضْحَى عَلَى قَيْدِ رُمْحٍ. احمد بن حسن"],["p","Telah berkata Jundab, \"Dahulu Nabi SAW shalat 'Iedul Fithri bersama kami, sedang matahari tingginya kadar dua batang tombak, dan (beliau shalat) 'Iedul Adlha (diwaktu matahari) tingginya kadar satu batang tombak\". [HR. Ahmad bin Hasan, dalam Nailul Authar]"],["p","Inilah waktu-waktu yang dituntunkan untuk melaksanakan ibadah qurban, tetapi bila menyembelihnya sebelum shalat 'Iedul Adlha selesai, maka yang demikian ini tidak dinilai sebagai ibadah qurban."],["h","2. Adab dan bacaan ketika menyembelih"],["a","عَنْ اَنَسٍ قَالَ: ضَحَّى رَسُوْلُ اللهِ ﷺ بِكَبْشَيْنِ اَمْلَحَيْنِ اَقْرَنَيْنِ. قَالَ: وَرَأَيْتُهُ يَذْبَحُهُمَا بِيَدِهِ وَرَأَيْتُهُ وَاضِعًا قَدَمَهُ عَلَى صِفَاحِهِمَا، قَالَ: وَسَمَّى وَكَبَّرَ. مسلم 3: 1557 رقم 18"],["p","Dari Anas, ia berkata : Rasulullah SAW menyembelih qurban dengan dua ekor kibasy yang bagus dan bertanduk\". Ia (Anas) berkata, \"Saya melihat beliau menyembelih keduanya dengan tangan beliau sendiri. Dan saya melihat beliau meletakkan kaki beliau diatas batang leher binatang itu”. Ia (Anas) berkata, \"Beliau membaca Basmalah dan bertakbir: Bismillaahi walloohu Akbar. (Dengan nama Allah, dan Allah Maha Besar)\". [HR. Muslim juz 3, hal. 1557, no. 18]."],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: شَهِدْتُ مَعَ رَسُوْلِ اللهِ ﷺ الْاَضْحَى بِالْمُصَلَّى. فَلَمَّا قَضَى خُطْبَتَهُ نَزَلَ مِنْ مِنْبَرِهِ، وَاُتِيَ بِكَبْشٍ فَذَبَحَهُ رَسُوْلُ اللهِ ﷺ بِيَدِهِ وَقَالَ: بِسْمِ اللهِ وَاللهُ اَكْبَرُ، هٰذَا عَنِّيْ وَعَمَّنْ لَـمْ يُضَحِّ مِنْ اُمَّتِى. ابو داود 3: 99، رقم:2810"],["p","Dari Jabir bin Abdullah, ia berkata : Aku shalat ‘Iedul Adlha bersama Rasulullah SAW di mushalla. Setelah beliau selesai berkhutbah, lalu turun dari mimbar, maka didatangkan seekor kibasy, lalu beliau menyembelihnya dengan tangan beliau, dan beliau mengucapkan, “Bismillaahi walloohu Akbar, haadzaa ‘annii wa ‘amman lam yudlohhi min ummatii (Dengan nama Allah dan Allah Maha Besar. (Qurban) ini dariku dan dari ummatku yang tidak berqurban)”. [HR. Abu Dawud juz 3, hal. 99, no. 2810]"],["a","عَنْ عَائِشَةَ اَنَّ رَسُوْلَ اللهِ ﷺ اَمَرَ بِكَبْشٍ اَقْرَنَ يَطَأُ فِيْ سَوَادٍ وَيَبْرُكُ فِيْ سَوَادٍ وَيَنْظُرُ فِيْ سَوَادٍ. فَاُتِيَ بِهِ لِيُضَحِّيَ بِهِ، فَقَالَ لَـهَا: يَا عَائِشَةُ، هَلُمِّى الْمُدْيَةَ. ثُـمَّ قَالَ: اِشْحَذِيْهَا بِحَجَرٍ. فَفَعَلَتْ. ثُـمَّ اَخَذَهَا وَاَخَذَ الْكَبْشَ فَاَضْجَعَهُ ثُـمَّ ذَبَحَهُ. ثُـمَّ قَالَ: بِاسْمِ اللهِ اَللّٰهُمَّ تَقَبَّلْ مِنْ مُحَمَّدٍ وَآلِ مُحَمَّدٍ وَمِنْ اُمَّةِ مُحَمَّدٍ. ثُـمَّ ضَحَّى بِهِ. مسلم 3: 1557 رقم 19"],["p","Dari ‘Aisyah, bahwasanya Rasulullah SAW menyuruh mengambilkan kambing yang bertanduk, hitam kakinya, hitam perutnya, hitam sekeliling matanya. Lalu kambing itu didatangkan untuk disembelih. Maka beliau SAW bersabda, “Hai ‘Aisyah, ambilkanlah pisau”. Beliau bersabda lagi, “Asahlah pisau itu dengan batu”. Kemudian ‘Aisyah melaksanakannya. Kemudian beliau mengambil pisau dan kambing tersebut, lalu membaringkannya untuk menyembelihnya. Beliau membaca, “Bismillaahi Alloohumma taqobbal min Muhammadin wa aali Muhammadin wa min ummati Muhammadin (Dengan nama Allah, ya Allah, terimalah dari Muhammad, keluarga Muhammad dan dari ummat Muhammad)”. Kemudian beliau menyembelihnya. [HR. Muslim juz 3, hal. 1557, no. 19]"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: ضَحَّى رَسُوْلُ اللهِ ﷺ يَوْمَ عِيْدٍ بِكَبْشَيْنِ. فَقَالَ حِيْنَ وَجَّهَهُمَا: اِنِّيْ وَجَّهْتُ وَجْهِيَ لِلَّذِيْ فَطَرَ السَّمٰوٰتِ وَالْاَرْضَ حَنِيْفًا وَّمَا اَنَا مِنَ الْمُشْرِكِيْنَ. اِنَّ صَلَاتِيْ وَنُسُكِيْ وَمَحْيَايَ وَمَمَاتِيْ لِلّٰهِ رَبِّ الْعَالَمِيْنَ، لَا شَرِيْكَ لَهُ وَبِذٰلِكَ اُمِرْتُ وَاَنَا اَوَّلُ الْمُسْلِمِيْنَ. اَللّٰهُمَّ مِنْكَ وَلَكَ عَنْ مُحَمَّدٍ وَاُمَّتِهِ. ابن ماجه 2: 1043، رقم: 3121"],["p","Dari Jabir bin 'Abdullah, ia berkata : Pada hari 'Iedul Adlha Rasulullah SAW berqurban dengan dua ekor kambing. Ketika melaksanakan itu beliau berdoa Innii wajjahtu wajhiya lilladzii fathoros samaawaati wal ardlo haniifaw wa maa ana minal musyrikiin. Inna sholaatii wa nusukii wa mahyaaya wa mamaatii lillaahi robbil 'aalamiin. Laa syariika lahu wa bidzaalika umirtu wa ana awwalul muslimiin. Alloohumma minka wa laka 'an Muhammadin wa ummatihi (Sesungguhnya aku menghadapkan diriku kepada Tuhan Yang menciptakan langit dan bumi dengan cenderung kepada agama yang benar, dan aku bukanlah termasuk orang-orang yang musyrik. Sesungguhnya shalatku, ibadahku, hidupku dan matiku hanyalah untuk Allah Tuhan semesta alam. Tidak ada sekutu bagi-Nya, dan demikian itulah yang diperintahkan kepadaku, dan aku adalah orang yang pertama-tama menyerahkan diri (kepada Allah). Ya Allah, (semua ini) dari Engkau dan untuk Engkau, dari Muhammad dan ummatnya). [HR. Ibnu Majah, juz 2, hal. 1043, no. 3121, dla'if, karena dalam sanadnya ada perawI bernama Abu 'Ayyaasy, ia majhul]"],["a","عَنْ شَدَّادِ بْنِ اَوْسٍ قَالَ: ثِنْتَانِ حَفِظْتُهُمَا مِنْ رَسُوْلِ اللهِ ﷺ. قَالَ: اِنَّ اللهَ كَتَبَ الْاِحْسَانَ عَلَى كُلِّ شَيْءٍ. فَاِذَا قَتَلْتُمْ فَاَحْسِنُوا الْقِتْلَةَ وَاِذَا ذَبَحْتُمْ فَاَحْسِنُوا الذَّبْحَ وَلْيُحِدَّ اَحَدُكُمْ شَفْرَتَهُ فَلْيُرِحْ ذَبِيْحَتَهُ. مسلم 3: 1548 رقم 57"],["p","Dari Syaddad bin Aus, ia berkata : Dua hal yang aku hafal dari Rasulullah SAW, beliau bersabda, “Sesungguhnya Allah mewajibkan berbuat baik pada segala sesuatu. Maka apabila kalian membunuh, bunuhlah dengan baik. Dan apabila kalian menyembelih, sembelihlah dengan baik, hendaklah seseorang diantara kalian menajamkan pisaunya, dan mempermudah (kematian) binatang sembelihannya”. [HR. Muslim juz 3, hal. 1548, no. 57]"],["h","3. Syarat-syarat binatang qurban"],["p","a).Binatang yang diperuntukkan qurban sepanjang tuntunan Rasulullah SAW adalah : Unta, lembu, dan kambing. Dan kadar masing-masing berdasar dhahir hadits/riwayat :"],["p","* 1 ekor kambing untuk seorang bersama ahli rumahnya."],["p","* 1 ekor lembu untuk 7 orang beserta ahli rumahnya."],["p","* 1 ekor unta untuk 7 - 10 orang dan ahli rumahnya."],["a","عَنْ عُمَارَةَ بْنِ عَبْدِ اللّٰهِ قَالَ: سَمِعْتُ عَطَاءَ بْنَ يَسَارٍ يَقُوْلُ: سَأَلْتُ اَبَا اَيُّوْبَ: كَيْفَ كَانَتِ الضَّحَايَا عَلَى عَهْدِ رَسُوْلِ اللهِ ﷺ؟ فَقَالَ: كَانَ الرَّجُلُ يُضَحِّى بِالشَّاةِ عَنْهُ وَعَنْ اَهْلِ بَيْتِهِ. فَيَأْكُلُوْنَ وَيُطْعِمُوْنَ حَتَّى تَبَاهَى النَّاسُ فَصَارَتْ كَمَا تَرَى. الترمذى 3: 31، رقمٓ 1541"],["p","Dari ‘Umaarah bin ‘Abdullah, ia berkata : Aku mendengar 'Atha' bin Yasar dia berkata : Saya bertanya kepada Abu Ayyub (Al-Anshariy), \"Bagaimanakah udlhiyah yang dilakukan di masa Rasulullah SAW ?\". Ia menjawab, \"Seorang laki-laki (di zaman Rasulullah SAW) menyembelih seekor kambing untuknya dan untuk ahli baitnya (rumah tangganya), lalu mereka makan dagingnya dan memberi makan kepada orang lain, sehingga orang-orang bermegah-megah dengan qurban itu sehingga menjadi seperti apa yang engkau saksikan sekarang ini\". [HR. Tirmidzi juz 3, hal. 31, no. 1541, ini hadits hasan shahih]."],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: نَحَرْنَا مَعَ رَسُوْلِ اللهِ ﷺ عَامَ الْحُدَيْبِيَّةِ الْبَدَنَةَ عَنْ سَبْعَةٍ وَالْبَقَرَةَ عَنْ سَبْعَةٍ. مسلم 2: 955 رقم 250"],["p","Dari Jabir bin ’Abdullah, ia berkata, “Kami menyembelih qurban bersama Rasulullah SAW pada tahun Hudaibiyah, seekor unta untuk 7 orang dan seekor lembu untuk 7 orang\". [HR Muslim juz 2, hal. 955, no. 250]."],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: كُنَّا مَعَ رَسُوْلِ اللهِ ﷺ فِيْ سَفَرٍ فَحَضَرَ الْاَضْحَى فَاشْتَرَكْنَا فِى الْبَقَرَةِ سَبْعَةٌ وَفِى الْبَعِيْرِ عَشْرَةٌ. الترمذى 3: 30، رقم: 1537"],["p","Dari Ibnu Abbas, ia berkata, \"Dulu kami pergi bersama Rasulullah SAW, lalu tiba Hari Raya 'Iedul Adlha, maka kami menyembelih qurban seekor lembu untuk tujuh orang dan seekor unta (ba'ir) untuk sepuluh orang\". [HR. Tirmidzi juz 3, hal. 30, no. 1537, hadits hasan gharib]."],["a","عَنْ اَبِيْ رَافِعٍ aقَالَ: ضَحَّى رَسُوْلُ اللهِ ﷺ بِكَبْشَيْنِ اَمْلَحَيْنِ مَوْجُوْءَيْنِ خَصِيَّيْنِ. احمد فى نيل الاوطار 5: 135"],["p","Dari Abu Rafi’ RA, ia berkata, “Rasulullah SAW pernah berqurban dua ekor kambing kibasy yang bagus yang dikebiri”. [HR. Ahmad, dalam Nailul Authar juz 5, hal. 135]"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: ضَحَّى رَسُوْلُ اللهِ ﷺ بِكَبْشَيْنِ سَمِيْنَيْنِ عَظِيْمَيْنِ اَقْرَنَيْنِ مَوْجُوْءَيْنِ. احمد، فى نيل الاوطار 5: 135"],["p","Dari ‘Aisyah RA, ia berkata : Rasulullah SAW menyembelih qurban dengan dua kambing kibasy yang gemuk, besar, bertanduk yang dikebiri. [HR. Ahmad, dalam Nailul Authar juz 5, hal. 135]"],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: قَلَّتِ الْاِبِلُ عَلَى عَهْدِ رَسُوْلِ اللهِ ﷺ فَاَمَرَهُمْ اَنْ يَنْحَرُوا الْبَقَرَ. ابن ماجه 2: 1047، رقم: 3134"],["p","Dari Ibnu 'Abbas, ia berkata : Pernah terjadi pada jaman Rasulullah SAW (jumlah) unta sedikit, maka beliau menyuruh para shahabat berqurban dengan lembu. [HR. Ibnu Majah juz 2, hal. 1047, no. 3134]"],["p","Catatan :"],["p","Masing-masing orang yang turut andil dalam qurban dengan unta/lembu tidak harus sama biaya yang dikeluarkannya, yang penting seekor lembu untuk tujuh orang dan seekor unta digunakan untuk 7-10 orang. Adapun tentang qurban urunan kambing yang biasa dilakukan disekolah-sekolah/kantor, sampai kini kami masih berpendapat : Bahwa hal itu tidak dapat dianggap sebagai ibadah qurban, melainkan tetap sebagai latihan qurban, yang pahalanya adalah sedekah biasa."],["p","b). Tidak sah berqurban dengan binatang yang :"],["p","1.Rusak matanya (buta, juling/kero) sebelah atau kedua-duanya."],["p","2.Terlalu kurus, tak bergajih/terlalu tua tak bersumsum lagi atau patah tanduk/putus telinganya."],["p","3.Sakit."],["p","4.Pincang."],["p","Di dalam hadits disebutkan :"],["a","عَنِ الْبَرَاءِ بْنِ عَازِبٍ aقَالَ: قَامَ فِيْنَا رَسُوْلُ اللهِ ﷺ فَقَالَ: اَرْبَعٌ لَا تَجُوْزُ فِى الضَّحَايَا. اَلْعَوْرَاءُ اْلبَيِّنُ عَوَرُهَا، وَالْمَرِيْضَةُ اْلبَيِّنُ مَرَضُهَا، وَالْعَرْجَاءُ الْبَيِّنُ ظَلَعُهَا وَالْكَبِيْرَةُ الَّتِيْ لَا تُنْقِى. احمد والاربعة وصححه الترمذى وابن حبان، فى بلوغ المرام رقم: 1376"],["p","Dari Baraa' bin 'Aazib RA, ia berkata : Nabi SAW berdiri diantara kami dan bersabda, \"Empat macam yang tidak boleh pada binatang qurban, yaitu: 1. Buta sebelah yang nyata butanya. 2. Yang sakit nyata sakitnya, 3. Yang pincang yang nyata pincangnya, dan 4. Yang tua yang tidak mempunyai sumsum\". [HR. Ahmad dan Arba'ah, dan disahkan oleh Tirmidzi dan Ibnu Hibban, dalam Bulughul Maram, no. 1376]."],["a","عَنْ عَلِيٍّ قَالَ: اَمَرَنَا رَسُوْلُ اللهِ ﷺ اَنْ نَسْتَشْرِفَ الْعَيْنَ وَالْاُذُنَ وَاَنْ لَا نُضَحِّيَ بِـمُقَابَلَةٍ وَلَا مُدَابَرَةٍ وَلَا شَرْقَاءَ وَلَا خَرْقَاءَ. الترمذى3: 28، رقم: 1532"],["p","Dari ‘Ali, ia berkata : Rasulullah SAW menyuruh kepada kami supaya memeriksa mata dan telinga, dan supaya kami tidak berqurban dengan binatang yang telinganya sobek dari bagian muka, yang telinganya sobek dari bagian belakang, yang telinganya sobek dari ujungnya, dan yang berlubang di tengahnya”. [HR. Tirmidzi juz 3, hal. 28, no. 1532, ini hadits hasan shahih]"],["a","عَنْ عَلِيٍّ قَالَ: نَـهَى رَسُوْلُ اللهِ ﷺ اَنْ يُضَحِّيَ بِاَعْضَبِ الْقَرْنِ وَالْاُذُنِ. الترمذى 3: 31، رقم: 1540"],["p","Dari ‘Ali, ia berkata, \"Rasulullah SAW melarang berqurban dengan binatang yang tanduknya atau telinganya hilang separo atau lebih\". [HR. Tirmidzi juz 3, hal. 31, no. 1540, ini hadits hasan shahih]."],["p","c). Keadaan masing-masing binatang qurban itu telah Musinnah (giginya telah berganti/powel). Dan hal ini terjadi pada :"],["p","Kambing yang berumur 1 tahun masuk tahun ke 2, lembu yang berumur 2 tahun masuk tahun ke 3 dan unta yang berumur 5 tahun masuk tahun ke 6. Kecuali bila terpaksa sekali, maka bolehlah berqurban dengan kambing yang jadza'ah (berumur cukup 1 tahun). Di dalam hadits disebutkan:"],["a","عَنْ جَابِرٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا تَذْبَحُوْا اِلَّا مُسِنَّةً اِلَّا اَنْ يَعْسُرَ عَلَيْكُمْ فَتَذْبَحُوْا جَذَعَةً مِنَ الضَّأْنِ. مسلم 3: 1555 رقم 13"],["p","Dari Jabir, ia berkata: Rasulullah SAW bersabda, \"Janganlah kalian menyembelih untuk qurban melainkan yang Musinnah (telah berganti gigi) kecuali jika sukar didapati, maka boleh kalian menyembelih jadza'ah (yang berumur 1 tahun) dari kambing”. [HR. Muslim juz 3, hal. 1555, no. 13]."],["h","4. Pembagian daging Udlhiyah"],["p","Pembagian daging udlhiyah itu ialah sebagian untuk yang berqurban, sebagian untuk dihadiahkan, dan sebagian diberikan kepada faqir miskin. Ibnu Abbas ketika menerangkan sifat Nabi SAW ketika berqurban sebagai berikut :"],["a","وَيُطْعِمُ اَهْلَ بَيْتِهِ الثُّلُثَ وَيُطْعِمُ فُقَرَاءَ جِيْرَانِهِ الثُّلُثَ وَيَتَصَدَّقُ عَلَى السُّؤَالِ بِالثُّلُثِ. المغنى 3: 582"],["p","Dan beliau (Rasulullah SAW) memberi makan ahlul baitnya sepertiga, memberi makan orang-orang faqir tetangganya sepertiga, dan beliau mensedekahkan kepada para peminta sepertiga. [Al-Mughni 3 : 582]."],["h","5. Daging Udlhiyah tidak boleh diberikan sebagai upah"],["p","Daging udlhiyah itu tidak boleh diberikan sebagai upah kepada yang menyembelih. Di dalam hadits disebutkan :"],["a","عَنْ عَلِيِّ بْنِ اَبِيْ طَالِبٍa قَالَ: اَمَرَنِيْ رَسُوْلُ اللهِ ﷺ اَنْ اَقُوْمَ عَلَى بُدْنِهِ وَاَنْ اُقَسِّمَ لُـحُوْمَهَا وَجُلُوْدَهَا وَجِلَالَـهَا عَلَى الْمَسَاكِيْنِ وَلَا اُعْطِيَ فِىْ جَزَارَتِـهَا شَيْئًا مِنْهَا. البخارى ومسلم، فى بلوغ المرام، رقم 1379"],["p","Dari 'Ali bin Abi Thalib RA, ia berkata, \"Saya diperintahkan oleh Rasulullah SAW untuk mengurus qurban-qurban dan supaya saya bagikan daging, kulitnya dan pelananya kepada faqir miskin, dan tidak (boleh) saya memberikan sesuatu sebagai upah dari padanya untuk orang yang menyembelih\". [HR. Bukhari dan Muslim, dalam Bulughul Maram, no. 1379]."],["h","6. Larangan menjual daging Udlhiyah"],["a","عَنْ قَتَادَةَ بْنِ النُّعْمَانِ اَنَّ النَّبِيَّ ﷺ قَالَ: لَا تَبِيْعُوْا لُحُوْمَ الْـهَدْيِ وَالْاَضَاحِى فَكُلُوْا وَتَصَدَّقُوْا وَاسْتَمْتِعُوْا بِجُلُوْدِهَا وَلَا تَبِيْعُوْهَا، وَاِنْ اُطْعِمْتُمْ مِنْ لَحْمِهَا فَكُلُوْا اِنْ شِئْتُمْ. احمد 5: 478، رقم: 16211"],["p","Dari Qatadah bin Nu’man, bahwasanya Nabi SAW bersabda, “Janganlah kalian menjual daging-daging Hadyi (denda hajji) dan daging udlhiyah (qurban), makanlah dan sedeqahkanlah dan manfaatkanlah kulitnya, dan janganlah kalian menjualnya. Dan apabila kalian diberi dagingnya, maka makanlah jika kalian mau”. [HR. Ahmad 5 : 478, no. 16211]"],["p","7.Orang yang akan berqurban dilarang memotong rambut dan kukunya"],["a","عَنْ اُمِّ سَلَمَةَ اَنَّ النَّبِيَّ ﷺ قَالَ: اِذَا رَأَيْتُمْ هِلَالَ ذِى الْحِجَّةِ وَاَرَادَ اَحَدُكُمْ اَنْ يُضَحِّيَ فَلْيُمْسِكْ عَنْ شَعْرِهِ وَاَظْفَارِهِ. مسلم 3: 1565"],["p","Dari Ummu Salamah, bahwasanya Nabi SAW bersabda, “Apabila kalian sudah melihat hilal bulan Dzulhijjah, dan seseorang diantara kalian ingin berqurban, maka hendaklah ia menahan rambut dan kukunya”. [HR. Muslim juz 3, hal. 1565, no. 41]"],["h","8. Perbedaan pendapat tentang hari penyembelihan"],["p","Tentang hari penyembelihan qurban, di kalangan ‘ulama terjadi perbedaan pendapat. Hal ini karena tidak adanya nash yang jelas, baik di dalam Al-Qur’an maupun dari hadits yang shahih."],["p","Pendapat para ‘ulama tersebut sebagai berikut :"],["p","1.Hari penyembelihan adalah 1 hari (tanggal 10 Dzulhijjah)."],["p","Diriwayatkan dari Ibnu Sirin, bahwasanya ia berkata, “Al-Adlhaa (hari penyembelihan) adalah satu hari, yaitu hari Nahr, hari tanggal 10 bulan Dzulhijjah. [Al-Istidzkaar juz 15, hal. 200, no. 21579]"],["p","2.Hari penyembelihan di kota-kota adalah 1 hari, sedangkan di Mina selama 3 hari."],["p","Dari Sa’id bin Jubair dan Jabir bin Zaid, bahwasanya keduanya berkata, “An-Nahr (hari penyembelihan) di kota-kota adalah satu hari, sedangkan di Mina selama tiga hari. [Al-Istidzkaar juz 15, hal. 201, no. 21580; Al-Mughni juz 3, hal. 454]"],["p","Catatan :"],["p","Imam Ibnu ‘Abdil Barr (penyusun Kitab Al-Istidzkaar, wafat tahun 463 H) dan Imam Ibnu Qudamah (penyusun Kitab Al-Mughni, wafat tahun 620 H) menyebutkan riwayat dari Sa’id bin Jubair dan Jabir bin Zaid sebagaimana tersebut di atas. Namun Imam Asy-Syaukaniy (penyusun Kitab Nailul Authaar, wafat tahun 1250 H) menyebutkan riwayat Sa’id bin Jubair dan Jabir bin Zaid sebagai berikut : Berkata Sa’id bin Jubair dan Jabir bin Zaid : Sesungguhnya waktunya (penyembelihan) adalah hari Nahr saja untuk penduduk kota-kota, dan hari-hari tasyriq untuk penduduk desa-desa. (lihat Nailul Authaar juz 5, hal. 142)."],["p","3.Hari penyembelihan adalah selama bulan Dzulhijjah."],["p","Imam Al-Qadli ‘Iyaadl menyebutkan dari sebagian ‘ulama bahwa waktunya penyembelihan adalah selama dalam bulan Dzulhijjah. [Nailul Authaar juz 5, hal. 142]"],["p","4.Hari penyembelihan adalah 3 hari (tanggal 10, 11 dan 12 Dzulhijjah)"],["p","Imam Malik, Abu Hanifah, Ats-Tsauriy (dan shahabat-shahabatnya) berpendapat, Al-Adlha (hari penyembelihan) adalah tiga hari, yaitu hari Nahr dan dua hari sesudahnya. Dan berpendapat seperti itu pula Imam Ahmad bin Hanbal."],["p","Imam Ahmad berkata, “Hari penyembelihan adalah tiga hari. Hari Nahr dan dua hari sesudahnya (berdasarkan bukan hanya dari seorang saja dari shahabat Nabi SAW). [Al-Istidzkaar juz 15, hal. 201, no. 21581-21583]"],["p","5.Hari penyembelihan adalah 4 hari (tgl 10, 11, 12 dan 13 Dzulhijjah)"],["p","Al-Auza’iy, Imam Syafi’iy dan shahabat-shahabatnya berkata, “Hari penyembelihan adalah empat hari, yaitu hari Nahr dan hari-hari tasyriq semuanya, yaitu tiga hari sesudah hari Nahr."],["p","Dan itu juga merupakan pendapatnya Ibnu Syihab Az-Zuhriy, ‘Atha’ dan Al-Hasan. [Al-istidzkaar juz 15, hal. 202, no. 21586-21587]"],["p","Demikianlah pendapat para ‘ulama tentang hari penyembelihan qurban."],["p","Walloohu a’lam."],["p","Keterangan :"],["p","Pendapat yang mengatakan bahwa hari penyembelihan itu selama 4 hari (hari Nahr dan hari-hari tasyriq beralasan dengan hadits sebagai berikut :"],["p","Berdasar riwayat dari Sulaiman Ibnu Musa dari Jubair Ibnu Muth'im bahwa Nabi SAW bersabda :"],["a","كُلُّ اَيَّامِ التَّشْرِيْقِ ذَبْحٌ. احمد 5: 618، رقم: 16751"],["p","Setiap hari Tasyriq itu adalah hari menyembelih. [HR. Ahmad juz 5, hal. 618, no. 16751]"],["p","Dan riwayat lain dari ‘Ali RA yang semakna dengan yang tersebut diatas sebagai berikut :"],["a","اَيَّامُ النَّحْرِ يَوْمُ الْاَضْحَى وَثَلَاثَةُ اَيَّامٍ بَعْدَهُ. فى نيل الاوطار 5: 142"],["p","Hari menyembelih itu ialah Hari Raya 'Iedul Adlha dan tiga hari sesudahnya. [Dalam Nailul Authar juz 5, hal. 142]"],["p","Tetapi hadits riwayat Ahmad tersebut munqathi’, karena Sulaiman bin Musa tidak bertemu dengan Jubair bin Muth’im. Lagi pula Sulaiman bin Musa diperselisihkan tentang tsiqatnya."],["p","Tentang Sulaiman bin Musa ini penjelasannya sebagai berikut :"],["p","Sulaiman bin Musa Al-Qurasyiy Al-Umawiy Al-Asydaq, ahli fiqhnya penduduk Syam pada zamannya, dan disepakati oleh para ‘ulama bahwasanya ia adalah seorang paling pandai dari penduduk Syam setelah Makhuul, Ibnu Ma’in menganggapnya tsabit, begitu pula Ibnu Hibban dan Adz-Dzahabiy, tetapi Bukhari berkata, “Padanya ada hadits-hadits munkar”. An-Nasaa’iy berkata, “Ia adalah seorang ahli fiqh, tetapi tidak kuat dalam hadits\". Ibnu ‘Adiy meletakkan permasalahannya, ia berkata, “Dia adalah seorang ahli fiqh, seorang perawi, menceritakan dari nya orang-orang tsiqat, dan dia merupakan ‘ulama ahli Syam, tetapi dia telah meriwayatkan hadits-hadits yang bersendirian dengan riwayat itu yang tidak diriwayatkan oleh lainnya. Dan dia menurutku, tsabit shaduuq (bisa dipercaya dan jujur)\". [Tentang Sulaiman bin Musa, bisa dibaca pada Tahdzibul Tahdzib juz 4, hal. 197, no. 387; Siyaru a’laamin nubalaa’ juz 5, hal. 433, no. 193]."],["p","Abu ‘Umar (Ibnu ‘Abdil Barr] berkata : Hujjah (alasan) bagi orang yang berpendapat dengan pendapat ini adalah hadits dari Jubair bin Muth’im, dari Nabi SAW bahwasanya beliau bersabda, “Setiap tempat di Makkah adalah tempat menyembelih, dan semua hari-hari tasyriq adalah (waktu) penyembelihan\". Hadits ini diriwayatkan dari Sulaiman bin Musa, dari Ibnu Abi Husein, dari Nafi’ bin Jubair (bin Muth’im dari ayahnya), dan diriwayatkan darinya secara munqathi’ dan muttashil."],["p","Hadits itu juga menjadi muththarib (goncang) dikarenakan tentang Ibnu Abi Husein dan Sulaiman bin Musa, meskipun beliau salah seorang Imam penduduk Syam tentang ‘ilmu, tetapi menurut mereka beliau buruk hafalannya."],["p","Oleh karena itu terkadang dikatakan darinya (Sulaiman bin Musa), dari ‘Abdur Rahman bin Abi Husein, dari Nafi’ bin Jubair bin Muth’im, dan terkadang Nafi’ bin Jubair tidak disebutkan. [Al-Istidzkaar juz 15, hal. 203, no. 21604-21607]"],["p","Ibnu ‘Abdil Barr juga berkata : Tidak benar menurut saya tentang masalah ini melainkan dua pendapat."],["p","Pertama, pedapatnya Imam Malik dan penduduk Kuufah, yaitu hari penyembelihan adalah pada hari Nahr dan dua hari sesudahnya."],["p","Kedua, pendapatnya Imam Syafi’iy dan penduduk Syam, hari penyembelihan adalah pada hari Nahr dan tiga hari sesudahnya."],["p","Dan inilah dua pendapat yang telah diriwayatkan dari beberapa orang ( dari shahabat Nabi SAW)."],["p","Dan tidak ada perbedaan dari seorangpun dari para shahabat yang menyelisihi dari dua pendapat ini, maka tidak ada artinya kita sibuk dengan pendapat-pendapat yang menyelisihi dari kedua pendapat (shahabat) tersebut, karena apa yang menyelisihi dari kedua pendapat itu tidak ada asalnya di dalam sunnah, dan bukan pula pendapat shahabat, dan apa yang di luar dari kedua pendapat ini haruslah ditinggalkan (karena adanya dua pendapat tersebut). [Al-Istidzkaar juz 15, hal. 205, no. 21609-21613] Walloohu a’lam."],["p","Catatan :"],["p","Pendapat para shahabat tersebut sebagai berikut :"],["p","Abu Hurairah dan Anas bin Maalik, diriwayatkan pendapatnya, hari penyembelihan adalah 3 hari."],["p","Abu Sa’id Al-Khudriy, diriwayatkan pendapatnya, hari penyembelihan adalah 4 hari."],["p","Sedangkan ‘Aliy bin Abu Thalib, Ibnu ‘Abbas dan Ibnu ‘Umar, ada diriwayatkan mereka itu pendapatnya 3 hari, dan ada pula diriwayatkan pendapat mereka itu 4 hari. Walloohu a’lam."],["p","Tentang takbir setelah shalat wajib di hari tasyriq"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ يُكَبِّرُ فِيْ صَلَاةِ الْفَجْرِ يَوْمَ عَرَفَةَ اِلىَ صَلَاةِ اْلعَصْرِ مِنْ آخِرِ اَيَّامِ التَّشْرِيْقِ حِيْنَ يُسَلِّمُ مِنَ الْمَكْتُوْبَاتِ. الدارقطنى 2: 49 رقم 27"],["p","Dari Jabir bin ‘Abdullah, ia berkata : Dahulu Rasulullah SAW bertakbir pada shalat Shubuh hari ‘Arafah (tanggal. 9 Dzulhijjah) sampai pada shalat ‘Ashar akhir hari tasyriq setelah salam dari shalat-shalat wajib. [HR. Daraquthniy juz 2, hal. 49, no. 27, dla’if, karena dalam sanadnya ada perawi bernama ‘Amr bin Syamir]"],["p","Keterangan :"],["p","Tentang perawi 'Amr bin Syamir tersebut, Al-Jauzajaaniy berkata, \"Zaaighun kadzdzaab (orang yang menyimpang dan pendusta)\". Bukhari berkata, \"Munkarul hadiits (haditsnya diingkari)\". Nasaiy dan Daraquthniy berkata, \"Matruukul hadiits (haditsnya ditinggalkan)\". Abu Zur'ah berkata, \"Dlo'iiful hadiits (haditsnya lemah)\". Abu Hatim berkata, \"Munkarul hadiits jiddan, dlo'iiful hadiits (haditsnya sangat diingkari, haditsnya lemah)\". [Lihat Lisaanul Miizaan juz 4, hal. 422, no. 6283]"],["p","--oo0oo--"]],"c20220710_1289":[["p","Ahad, 10 Juli 2022/11 Dzulhijjah 1443 Brosur No.: 2084/2124/IF"],["h","'AQIQAH"],["p","Pengertian ‘aqiqah"],["p","Menurut bahasa ‘Aqiqah berasal dari (عَقَّ-يَعُقُّ-عَقًّا) artinya : memotong. Dinamakan ‘Aqiqah (yang dipotong), karena dipotongnya leher binatang dengan penyembelihan itu."],["p","Ada pula yang mengatakan bahwa ‘aqiqah itu asalnya ialah : Rambut yang terdapat pada kepala si bayi ketika ia keluar dari rahim ibu, rambut ini disebut ‘aqiqah, karena ia mesti dicukur."],["p","Adapun menurut istilah agama, yang dimaksud ‘aqiqah ialah : Sembelihan yang disembelih sehubungan dengan kelahiran seorang anak, baik laki-laki ataupun perempuan pada hari yang ke tujuh sejak kelahirannya dengan tujuan semata-mata mencari ridla Allah."],["p","Sejarah ‘aqiqah"],["p","Syariat ‘aqiqah, yaitu menyembelih 2 ekor kambing jika anaknya laki-laki, dan seekor kambing jika anaknya perempuan, telah dikenal dan biasa dilakukan orang sejak zaman jahiliyah, namun dengan cara yang berbeda dengan yang dituntunkan oleh Nabi SAW bagi ummat Islam."],["p","Buraidah berkata :"],["a","كُنَّا فِى الْجَاهِلِيَّةِ اِذَا وُلِدَ لِاَحَدِنَا غُلَامٌ ذَبَحَ شَاةً وَلَطَخَ رَأْسَهُ بِدَمِهَا، فَلَمَّا جَاءَ اللهُ بِالْاِسْلَامِ كُنَّا نَذْبَحُ شَاةً وَ نَحْلِقُ رَأْسَهُ وَنَلْطَخُهُ بزَعْفَرَانٍ. ابو داود 3: 107، رقم: 2843"],["p","Dahulu kami di masa jahiliyah apabila salah seorang diantara kami mempunyai anak, ia menyembelih kambing dan melumuri kepalanya dengan darah kambing itu. Maka setelah Allah mendatangkan Islam, kami menyembelih kambing, mencukur (menggundul) kepala si bayi dan melumurinya dengan minyak wangi. [HR. Abu Dawud juz 3, hal. 107, no. 2843]"],["a","عَنْ عَائِشَةَ قَالَتْ: كَانُوْا فِى الْجَاهِلِيَّةِ اِذَا عَقُّوْا عَنِ الصَّبِيِّ خَضَبُوْا قُطْنَةً بِدَمِ الْعَقِيْقَةِ فَاِذَا حَلَقُوْا رَأْسَ الصَّبِيِّ وَضَعُوْهَا عَلَى رَأْسِهِ، فَقَالَ النَّبِيُّ ﷺ: اِجْعَلُوْا مَكَانَ الدَّمِ خَلُوْقًا. ابن حبان 12: 124، 5308"],["p","Dari 'Aisyah, ia berkata, \"Dahulu orang-orang pada masa jahiliyah apabila mereka ber’aqiqah untuk seorang bayi, mereka melumuri kapas dengan darah ‘aqiqah, lalu ketika mencukur rambut si bayi mereka melumurkan pada kepalanya, maka Nabi SAW bersabda, \"Gantilah darah itu dengan minyak wangi\". [HR. Ibnu Hibban juz 12, hal. 124, no. 5308]"],["p","Demikianlah sejarah syariat ‘aqiqah dalam Islam, dan dari riwayat-riwayat diatas serta riwayat-riwayat lain, tampak jelas bagaimana sikap agama tercinta ini dalam menghadapi adat yang sudah biasa berjalan dan berlaku pada masyarakat dan masih mungkin diluruskan. Tegasnya, Islam sesuai dengan fungsi diturunkannya yaitu sebagai lambang kasih sayang serta memimpin ke arah jalan yang serba positif, maka dalam menghadapi adat-istiadat yang sudah biasa dilaksanakan kelompok manusia, menempuh tiga macam cara yaitu:"],["p","a. Menghapusnya sama sekali, bila didalam adat-istiadat itu mengandung unsur-unsur kemusyrikan yang tidak mungkin diluruskan lagi, maupun hal-hal yang membahayakan keselamatan manusia itu sendiri; baik dari segi ‘aqidah (rohani) maupun bagi tata masyarakatnya."],["p","Dalam hal ini Islam tidak dapat mentolerir atau membiarkannya hidup dan bersemi dalam kehidupan ummatnya, karena sesuai dengan kenyataan, bahwa petani yang pandai serta bertanggungjawab terhadap berhasil dan suburnya sang padi, tidak akan membiarkan hidup alang-alang dan rumput-rumput liar yang ada di sekeliling padinya."],["p","b. Apabila dalam adat-istiadat tersebut mengandung hal-hal yang bertentangan dengan agama akan tetapi masih dapat diluruskan, maka Islam datang untuk meluruskannya dan kemudian berjalan bersama-sama dengan Islam, sebagaimana masalah ‘aqiqah ini."],["p","c. Adapun adat-istiadat yang tidak mengandung unsur-unsur kemusyrikan dan kedhaliman serta tidak bertentangan dengan agama, maka Islam memelihara dan memberi hak hidup baginya untuk berkembang lebih lanjut dalam masyarakat tersebut tanpa sesuatu perubahanpun."],["p","Hal-hal yang disyariatkan sehubungan dengan ‘aqiqah"],["h","A. Yang berhubungan dengan sang anak"],["p","1.Disunnahkan untuk memberi nama dan mencukur rambut (menggundul) pada hari ke-7 sejak hari lahirnya. Misalnya lahir pada hari Ahad, ‘aqiqahnya jatuh pada hari Sabtu."],["p","2. Bagi anak laki-laki disunnahkan ber’aqiqah dengan 2 ekor kambing sedang bagi anak perempuan 1 ekor."],["p","3. ‘Aqiqah ini terutama dibebankan kepada orang tua si anak, tetapi boleh juga dilakukan oleh keluarga yang lain (kakek dan sebagainya)."],["p","4. ‘Aqiqah ini hukumnya sunnah."],["a","عَنْ يُوْسُفَ بْنِ مَاهَكٍ اَنَّـهُمْ دَخَلُوْا عَلَى حَفْصَةَ بِنْتِ عَبْدِ الرَّحْمٰنِ فَسَأَلُوْهَا عَنِ الْعَقِيْقَةِ، فَاَخْبَرَتْـهُمْ اَنَّ عَائِشَةَ اَخْبَرَتْـهَا اَنَّ رَسُوْلَ اللهِ ﷺ اَمَرَهُمْ عَنِ الْغُلَامِ شَاتَانِ مُكَافِئَتَانِ وَعَنِ الْجَارِيَةِ شَاةٌ. الترمذي 3: 35، رقم: 1549"],["p","Dari Yusuf bin Mahak bahwasanya orang-orang datang kepada Hafshah binti 'Abdur Rahman, mereka menanyakan kepadanya tentang 'aqiqah. Maka Hafshah memberitahukan kepada mereka bahwasanya 'Aisyah memberitahu kepadanya bahwa Rasulullah SAW telah memerintahkan para shahabat (agar menyembelih 'aqiqah) bagi anak laki-laki 2 ekor kambing yang sebanding dan untuk anak perempuan 1 ekor kambing. [HR. Tirmidzi juz 3, hal. 35, no. 1549, ini hadits hasan shahih]."],["a","عَنْ سَلْمَانَ بْنِ عَامِرٍ الضَّبِيِّ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: مَعَ الْغُلَامِ عَقِيْقَةٌ فَاَهْرِيْقُوْا عَنْهُ دَمًا وَاَمِيْطُوْا عَنْهُ اْلاَذَى. البخارى 6: 217"],["p","Dari Salman bin ‘Amir Adl-Dlabiy, ia berkata : Saya mendengar Rasulullah SAW bersabda, \"Tiap-tiap anak itu ada ‘aqiqahnya. Maka sembelihlah binatang ‘aqiqah untuknya dan buanglah kotoran darinya (cukurlah rambutnya)\". [HR. Bukhari juz 6, hal. 217]"],["a","عَنْ عَمْرِو بْنِ شُعَيْبٍ عَنْ اَبِيْهِ عَنْ جَدِّهِ قَالَ، قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ اَحَبَّ مِنْكُمْ اَنْ يَنْسُكَ عَنْ وَلَدِهِ فَلْيَفْعَلْ عَنِ الْغُلَامِ شَاتَانِ مُكَافِئَتَانِ وَعَنِ الْجَارِيَةِ شَاةٌ. احمد 2: 604، رقم: 2725"],["p","Dari 'Amr bin Syu'aib dari ayahnya, dari kakeknya, ia berkata, Rasulullah SAW bersabda, \"Barangsiapa berkehendak untuk meng'aqiqahkan anaknya maka kerjakanlah. Untuk anak laki-laki dua ekor kambing yang sebanding dan untuk anak perempuan satu ekor kambing\". [HR. Ahmad juz 2, hal. 604, no. 2725]"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: عَقَّ رَسُوْلُ اللهِ ﷺ عَنِ الْحَسَنِ وَالْحُسَيْنِ يَوْمَ السَّابِعِ وَسَمَّاهُمَا وَاَمَرَ اَنْ يُـمَاطَ عَنْ رُؤُوْسِهِمَا الْاَذَى. الحاكم فى المستدرك 4: 264، رقم: 7588"],["p","Dari 'Aisyah RA, ia berkata, \"Rasulullah SAW pernah ber’aqiqah untuk Hasan dan Husain pada hari ke-7 dari kelahirannya, beliau memberi nama dan memerintahkan supaya dihilangkan kotoran dari kepalanya (dicukur)\". [HR. Hakim, dalam Al-Mustadrak juz 4, hal. 264, no. 7588]"],["p","Keterangan :"],["p","Hasan dan Husain adalah cucu Rasulullah SAW."],["p","Waktu pelaksanaan ‘aqiqah"],["p","Waktu yang dituntunkan oleh Nabi SAW berdasarkan dalil yang paling kuat ialah pada hari ke-7 semenjak kelahiran anak tersebut."],["a","عَنْ سَمُرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اَلْغُلَامُ مُرْتَـهَنٌ بِعَقِيْقَتِهِ يُذْبَحُ عَنْهُ يَوْمَ السَّابِعِ وَيُسَمَّى وَيُحْلَقُ رَأْسُهُ. الترمذى 3: 38، رقم: 1559"],["p","Dari Samurah (bin Jundab), ia berkata : Rasulullah SAW bersabda, \"Anak itu tergadai (tergantung) dengan ‘aqiqahnya yang disembelih untuknya pada hari ke-7, di hari itu ia diberi nama dan dicukur rambutnya\". [HR. Tirmidzi juz 3, hal. 38, no. 1559, ini hadits hasan shahih]"],["a","عَنْ سَمُرَةَ بْنِ جُنْدَبٍ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: كُلُّ غُلَامٍ رَهِيْنَةٌ بِعَقِيْقَتِهِ تُذْبَحُ عَنْهُ يَوْمَ سَابِعِهِ وَيُحْلَقُ وَيُسَمَّى. ابو داود 3: 106، رقم: 2838"],["p","Dari Samurah bin Jundab, bahwasanya Rasulullah SAW bersabda, \"Tiap-tiap anak tergadai (tergantung) dengan ‘aqiqahnya yang disembelih untuknya pada hari ke-7, di hari itu ia dicukur rambutnya dan diberi nama\". [HR. Abu Dawud juz 3, hal. 106, no. 2838]"],["a","عَنْ سَمُرَةَ عَنِ النَّبِيِّ ﷺ قَالَ: كُلُّ غُلَامٍ مُرْتَـهَنٌ بِعَقِيْقَتِهِ. تُذْبَحُ عَنْهُ يَوْمَ السَّابِعِ وَيُحْلَقُ رَأْسُهُ وَيُسَمَّى. ابن ماجه 2: 1056، رقم: 3165"],["p","Dari Samurah, dari Nabi SAW, beliau bersabda, “Setiap anak tergadai dengan ‘aqiqahnya, yang disembelih untuknya pada hari ke-7, dicukur rambutnya, dan diberi nama”. [HR. Ibnu Majah juz 2, hal. 1056, no. 3165]"],["h","B. Yang berhubungan dengan binatang sembelihan"],["p","Dalam masalah ‘aqiqah, binatang yang boleh dipergunakan sebagai sembelihan hanyalah kambing, tanpa memandang apakah jantan atau betina, sebagaimana riwayat di bawah ini :"],["a","عَنْ اُمِّ كُرْزٍ اَنَّـهَا سَأَلَتْ رَسُوْلَ اللهِ ﷺ عَنِ الْعَقِيْقَةِ، فَقَالَ: نَعَمْ. عَنِ الْغُلَامِ شَاتَانِ وَعَنِ الْجَارِيَةِ وَاحِدَةٌ، لَا يَضُرُّكُمْ ذُكْرَانًا كُنَّ اَمْ اِنَاثًا. الترمذى 3: 35، رقم: 1550"],["p","Dari Ummu Kurz (Al-Ka'biyah), bahwasanya ia pernah bertanya kepada Rasulullah SAW tentang ‘aqiqah. Maka jawab beliau SAW, \"Ya, untuk anak laki-laki dua ekor kambing dan untuk anak perempuan satu ekor kambing. Tidak menyusahkanmu baik kambing itu jantan maupun betina\". [HR. Tirmidzi, juz 3, hal. 35, no. 1550, ini hadits shahih]"],["p","Dan kami belum mendapatkan dalil yang lain yang menunjukkan adanya binatang selain kambing yang dipergunakan sebagai ‘aqiqah."],["p","Hal-hal yang perlu diperhatikan :"],["p","Dalam masalah ‘aqiqah ini banyak orang yang melakukannya dengan cara-cara yang tidak sesuai dengan apa yang dituntunkan oleh Nabi SAW. Tetapi bila mereka ditanya dalilnya atau tuntunannya, mereka sendiri tidak dapat mengemukakannya dengan jelas."],["p","Maka dalam brosur ini kami suguhkan kepada saudara-saudara kaum Muslimin, dalil-dalil yang biasa dipergunakan sebagai dasar amalan-amalan yang berhubungan dengan masalah ‘aqiqah, sedang dalil tersebut adalah lemah dan tidak dapat dipergunakan sebagai hujjah/alasan dalam masalah hukum. Diantaranya :"],["p","1. Adzan dan Iqamah pada telinga bayi yang baru lahir."],["a","عَنْ اَبِيْ رَافِعٍ قَالَ: رَأَيْتُ رَسُوْلَ اللهِ ﷺ اَذَّنَ فيْ اُذُنَيِ الْحَسَنِ حِيْنَ وَلَدَتْهُ فَاطِمَةُ بِالصَّلَاةِ. احمد 9: 230، رقم 23930"],["p","Dari Abu Rafi' ia berkata, \"Saya pernah melihat Rasulullah SAW beradzan (sebagaimana adzan) shalat, pada kedua telinga Hasan ketika dilahirkan oleh Fathimah\". [HR. Ahmad juz 9, hal. 230, no. 23930, dla’if karena dalam sanadnya ada perawi bernama ‘Ashim bin ‘Ubaidillah]"],["a","عَنْ عُبَيْدِ اللّٰهِ بْنِ اَبِيْ رَافِعٍ عَنْ اَبِيْهِ قَالَ: رَاَيْتُ رَسُوْلَ اللّٰهِ ﷺ اَذَّنَ فِيْ اُذُنِ الْحَسَنِ بْنِ عَلِيٍ بِالصَّلَاةِ حِيْنَ وَلَدَتْهُ فَاَطِمَةُ رَضِيَ اللهُ عَنْهَا. البيهقى 9: 305"],["p","Dari ‘Ubaidillah bin Abu Rafi’, dari ayahnya, ia berkata : Aku melihat Rasulullah SAW beradzan di telinga Hasan bin ‘Ali, seperti adzan shalat, ketika ia dilahirkan oleh Fathmah RA”. [HR. Baihaqi juz 9, hal. 305]"],["a","عَنْ اَبِيْ رَافِعٍ اَنَّ النَّبِيَّ ﷺ اَذَّنَ فِيْ اُذُنِ الْحَسَنِ وَاْلحُسَيْنِ حِيْنَ وُلِدَا وَاَمَرَ بِهِ. الطبرانى فى المعجم الكبير 1: 313، رقم: 926"],["p","Dari Abu Rafi’ bahwasanya Nabi SAW membaca adzan pada telinga Hasan dan Husain ketika keduanya dilahirkan. Dan beliau menyuruh yang demikian itu. [HR. Thabarani dalam Al-Mu’jamul Kabiir juz 1, hal. 313 no. 926]"],["p","Hadits-hadits tentang mengadzani bayi setelah dilahirkan tersebut kesemuanya diriwayatkan melalui jalan 'Ashim bin 'Ubaidillah."],["p","Tentang ‘Aashim bin ‘Ubaidillah ini, Bukhari berkata : Ia munkarul hadits. Abu Zur’ah berkata : Ia munkarul hadits. Abu Hatim berkata : Ia munkarul hadits. Daraquthni berkata : ia matruukul hadits. Nasa’iy berkata : Ia dla’if. (Lihat Mizaanul I’tidaal juz 2 hal. 353 no. 4056; Tahdziibut Tahdziib juz 5, hal. 42, no. 79)."],["p","Ada lagi hadits yang diriwayatkan Ibnus Sunni demikian :"],["a","عَنْ حُسَيْنِ بْنِ عَلِيٍّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ وُلِدَ لَهُ مَوْلُوْدٌ فَاَذَّنَ فِيْ اُذُنِهِ الْيُمْنَى وَاَقَامَ فِيْ اُذُنِهِ الْيُسْرَى لَـمْ تَضُرَّهُ اُمُّ الصِّبْيَانِ. ابن السنى: 220، رقم: 623"],["p","Dari Husain bin Ali, ia berkata : Rasulullah SAW bersabda, \"Barangsiapa mempunyai anak yang baru dilahirkan, kemudian ia mensuarakan adzan di telinga yang kanan, dan iqamah pada telinga yang kiri, maka anak itu tidak diganggu oleh Ummush Shibyan (sejenis syaithan)\". [HR. Ibnus Sunni hal. 220, no. 623, dla’if karena dalam sanadnya ada perawi bernama Jabbaarah bin Al-Mughlis, Yahya bin ‘Alaa’ dan Marwan bin Salim]"],["p","Hadits ini juga lemah, karena dalam sanadnya ada perawi bernama Jabbaarah bin Al-Mughlis, Yahya bin ‘Alaa’ dan Marwan bin Saalim, ketiganya dla’if."],["p","a. Tentang Jabbaarah bin Al-Mughlis, Al-Bazzaar berkata : ia banyak keliru. Daraquthni berkata : ia matruuk. Bukhari berkata : haditsnya mudltharib. (Lihat Tahdziibut Tahdziib juz 2, hal. 50, no. 87)."],["p","b. Tentang Yahya bin Al-’Alaa’, Imam Ahmad bin Hanbal berkata : ia pendusta. ‘Amr bin ‘Ali, Nasaiy dan Daraquthni berkata : ia matruukul hadits. Abu Zur’ah berkata : haditsnya dla’if. As-Sajiy berkata : ia munkarul hadits. Ad-Daulabiy berkata : ia matruukul hadits. (Lihat Tahdziibut Tahdziib juz 11, hal. 229, no. 427)."],["p","c. Tentang Marwan bin Salim, Bukhari dan Muslim berkata : ia munkarul hadits. Daraquthni berkata : ia matruukul hadits. Abu Hatim berkata : ia munkarul hadits jiddan. Al-Baghawiy berkata : ia munkarul hadits, riwayatnya tidak boleh dijadikan hujjah. (Lihat Tahdziibut Tahdziib juz 10, hal. 84, no. 172)."],["p","2. Tentang ‘aqiqah yang dikerjakan pada selain hari ke-7 yaitu pada hari yang ke-14, ke-21, setelah tua dan sebagainya, sebagai berikut:"],["a","عَنْ عَبْدِ اللهِ بْنِ بُرَيْدَةَ عَنْ اَبِيْهِ عَنِ النَّبِيِّ ﷺ قَالَ: اَلْعَقِيْقَةُ تُذْبَحُ لِسَبْعٍ وَلِاَرْبَعَ عَشْرَةَ وَلِاِحْدَى وَعِشْرِيْنَ. البيهقى 9: 303"],["p","Dari ‘Abdullah bin Buraidah dari ayahnya, dari Nabi SAW beliau bersabda, \" ‘Aqiqah itu disembelih pada hari ke-7, atau ke-14, atau ke-21 nya\". [HR. Baihaqi juz 9, hal. 303, dla’if karena dalam sanadnya ada perawi bernama Isma’il bin Muslim]"],["a","عَنْ عَبْدِ اللهِ بْنِ بُرَيْدَةَ عَنْ اَبِيْهِ اَنَّ النَّبِيَّ ﷺ قَالَ: اَلْعَقِيْقَةُ تُذْبَحُ لِسَبْعٍ اَوْ اَرْبَعَ عَشْرَةَ اَوْ اِحْدَى وَعِشْرِيْنَ. الطبرانى فى الاوسط 5: 457، رقم: 4879"],["p","Dari ‘Abdullah bin Buraidah dari ayahnya, dari Nabi SAW beliau bersabda, \" ‘Aqiqah itu disembelih pada hari ke-7, atau ke-14, atau ke-21 nya\". [HR. Thabarani dalam Al-Ausath juz 5, hal. 457, no. 4879, dla’if karena dalam sanadnya ada perawi bernama Isma’il bin Muslim]"],["p","Keterangan :"],["p","Hadits tentang kebolehan ber’aqiqah pada hari ke-14, dan ke-21 tersebut di atas adalah dla'if, karena dalam sanadnya ada perawi bernama Ismail bin Muslim Al-Makkiy."],["p","Tentang Isma’il bin Muslim Al-Makkiy, Al-Jauzajaaniy berkata : ia waahin jiddan. Abu Zur’ah berkata : ia dla’iful hadits. Abu Hatim berkata : ia dla’iful hadits, kacau pikirannya. Nasaiy berkata : ia matruukul hadits. (Lihat Tahdziibut Tahdziib juz 1, hal. 289, no. 598)."],["p","Adapun riwayat Nabi SAW ber’aqiqah setelah beliau menjadi Nabi, haditsnya sebagai berikut :"],["a","عَنْ اَنَسٍ اَنَّ النَّبِيَّ ﷺ عَقَّ عَنْ نَفْسِهِ بَعْدَ النُّبُوَّةِ. البيهقى 9: 300"],["p","Dari Anas bahwasanya Nabi SAW ber’aqiqah untuk dirinya sesudah beliau menjadi Nabi\". [HR. Baihaqi juz 9, hal. 300, dla’if karena dalam sanadnya ada perawi bernama ‘Abdullah bin Muharrar]"],["p","Keterangan :"],["p","Hadits yang menjelaskan bahwa Nabi SAW ber’aqiqah untuk dirinya setelah menjadi Nabi, ini juga tak dapat dipakai sebagai hujjah/dasar, karena dalam sanadnya ada perawi bernama Abdullah bin Muharrar."],["p","Tentang ‘Abdullah bin Muharrar, Ibnu Ma’in berkata : ia dla’if. ‘Amr bin ‘Ali, Abu Hatim, ‘Ali bin Junaid dan Daraquthni berkata : ia matruukul hadits. Abu Zur’ah berkata : ia dla’iful hadits. Bukhari berkata : ia munkarul hadits. (Lihat Tahdziibut Tahdziib juz 5, hal. 340, no. 661)."],["h","3. Tentang shadaqah seberat rambut yang dicukur dari kepala si Anak"],["a","عَنْ جَعْفَرِ بْنِ مُحَمَّدِ بْنِ عَلِيٍّ عَنْ اَبِيْهِ، اَنَّهُ قَالَ: وَزَنَتْ فَاطِمَةُ بِنْتُ رَسُوْلِ اللهِ ﷺ شَعْرَ حَسَنٍ وَحُسَيْنٍ وَزَيْنَبَ وَاُمِّ كُلْثُوْمٍ فَتَصَدَّقَتْ بِزِنَةِ ذٰلِكَ فِضَّةً. البيهقى فى السنن الكبرى 9: 304"],["p","Dari Ja’far bin Muhammad bin ‘Ali, dari ayahnya, bahwasanya ia berkata : Fathimah binti Rasulullah SAW menimbang rambut kepala Hasan, Husain, Zainab, dan Ummu Kultsum, kemudian bershadaqah dengan perak seberat rambutnya itu”. [HR. Baihaqi dalam As-Sunanul Kubra juz 9, hal. 304]"],["a","a عَنْ مُحَمَّدِ بْنِ عَلِيِّ بْنِ حُسَيْنٍ عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: عَقَّ رَسُولُ اللهِ ﷺ عَنِ الْحَسَنِ بِشَاةٍ وَقَالَ: يَا فَاطِمَةُ، اِحْلِقِيْ رَأْسَهُ وَتَصَدَّقِيْ بِزِنَةِ شَعْرِهِ فِضَّةً, فَوَزَنَّاهُ فَكَانَ وَزْنُهُ دِرْهَمًا وَبَعْضَ دِرْهَمٍ. البيهقى فى السنن الكبرى 9: 304"],["p","Dari Muhammad bin ‘Ali bin Husain, dari ‘Ali RA, ia berkata : Rasulullah SAW ber’aqiqah untuk Hasan dengan seekor kambing, dan beliau bersabda, “Hai Fathimah, cukurlah rambutnya dan bershadaqahlah dengan perak seberat rambutnya itu”. Lalu kami menimbangnya, dan rambutnya itu seberat satu dirham atau setengah dirham. [HR. Baihaqi dalam As-Sunanul Kubra juz 9, hal. 304]"],["a","عَنْ مُحَمَّدِ بْنِ عَلِيِّ بْنِ الْحُسَيْنِ عَنْ عَلِيِّ بْنِ اَبِيْ طَالِبٍ قَالَ: عَقَّ رَسُوْلُ اللهِ ﷺ عَنِ الْحَسَنِ بِشَاةٍ وَقَالَ: يَا فَاطِمَةُ اِحْلِقِيْ رَأْسَهُ وَتَصَدَّقِيْ بِزِنَةِ شَعْرِهِ فِضَّةً. فَوَزَنَتْهُ فَكَانَ وَزْنُهُ دِرْهَمًا اَوْ بَعْضَ دِرْهَمٍ. الترمذى 3: 37، رقم: 1556"],["p","Dari Muhammad bin ‘Ali bin Husain, dari ‘Ali bin Abu Thalib, ia berkata : Rasulullah SAW ber’aqiqah untuk Hasan seekor kambing dan bersabda, \"Ya Fathimah, cukurlah rambutnya dan bershadaqahlah seberat rambut kepalanya dengan perak\". Maka Fathimah menimbangnya, dan adalah beratnya satu dirham atau setengah dirham\". [HR. Tirmidzi juz 3, hal. 37, no. 1556, dan ia mengatakan : Ini hadits hasan gharib, sanadnya tidak sambung]"],["p","Keterangan :"],["p","Hadits-hadits tersebut dla’if, sanadnya munqathi' (terputus), karena Abu Ja'far Muhammad bin ‘Ali bin Husain bin ‘Ali tidak sezaman dengan ‘Ali bin Abu Thalib. 'Ali bin Abu Thalib wafat tahun 40 H, sedangkan Abu Ja'far Muhammad bin 'Ali bin Husain lahir tahun 56 H. [Tahdziibut Tahdziib juz 9, hal. 331, no. 582]"],["p","--oo0oo--"]],"c20220717_1290":[["p","Ahad, 17 Juli 2022/18 Dzulhijjah 1443 Brosur No.: 2085/2125/IA"],["h","ZUHUD DALAM KEHIDUPAN DUNIA"],["p","Perlu disadari bahwa kenikmatan yang berwujud harta benda serta lainnya dan kemiskinan serta kesusahan adalah tidak ada bedanya. Karena seluruh apa yang dirasakan dan dimilikinya tidak lain adalah ujian yang diberikan oleh Allah SWT di dunia yang fana. Kesenangan-kesenangan duniawi itu hanya sebentar dan tidak kekal. Sehingga jangan sampai orang-orang terperdaya, tamak dan rakus terhadap dengan kesenangan-kesenangan, dunia, sehingga lalai dari memperhatikan urusan akhirat."],["p","Banyak orang yang salah paham terhadap zuhud. Banyak yang mengira kalau zuhud adalah meninggalkan harta, menolak segala kenikmatan dunia, dan mengharamkan yang halal. Zuhud bukanlah meninggalkan kenikmatan dunia, bukan berarti mengenakan pakaian yang lusuh, dan bukan berarti miskin. Zuhud juga bukan berarti hanya duduk di masjid, mengaji, berdo’a, beribadah saja tanpa melakukan aktifitas-aktifitas lainnya. Tidak demikian, karena meninggalkan harta adalah sangat mudah, apalagi jika mengharapkan pujian dan popularitas dari orang lain. Kerja mereka cuma minta-minta mengharap sedekah dari orang lain, dengan mengatakan bahwa dirinya ahli ibadah atau keturunan Rasulullah SAW. Padahal Islam mengharuskan umatnya agar memakmurkan bumi, bekerja, menjadi kholifah dan menguasai dunia, tetapi pada saat yang sama tidak tertipu dan terpedaya oleh dunia."],["p","Kehidupan Rasulullah SAW dan sahabatnya adalah pengejawantahan Al-qur’an. Praktek zuhud pada waktu itu bukan isolasi dan sikap eksklusif terhadap dunia, akan tetapi mempunyai pengertian aktif menggeluti kehidupan dunia, akan tetapi dalam rangka menuju kehidupan akhirat. Jadi, Rasulullah dan sahabatnya tidak memisahkan antara dua kehidupan dunia dan akhirat, tetapi satu sama lain mempunyai hubungan. Dinyatakan oleh Allah bahwa dunia adalah ladang untuk menggapai kebahagiaan akhirat. Sebagaimana firman-Nya:"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَلْتَنْظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍۚ وَاتَّقُوا اللّٰهَ ۗ اِنَّ اللّٰهَ خَبِيْرٌ ۢ بِمَا تَعْمَلُوْنَ. الحشر : 18"],["p","Hai orang-orang yang beriman, bertakwalah kepada Allah dan hendaklah setiap diri memperhatikan apa yang telah diperbuatnya untuk hari esok (akhirat), dan bertakwalah kepada Allah, sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan. [Q.S. Al Hasyr : 18]"],["a","وَابْتَغِ فِيْمَآ اٰتٰىكَ اللّٰهُ الدَّارَ الْاٰخِرَةَ وَلَا تَنْسَ نَصِيْبَكَ مِنَ الدُّنْيَا وَاَحْسِنْ كَمَآ اَحْسَنَ اللّٰهُ اِلَيْكَ وَلَا تَبْغِ الْفَسَادَ فِى الْاَرْضِ ۗ اِنَّ اللّٰهَ لَا يُحِبُّ الْمُفْسِدِيْنَ . القصص : 77"],["p","Dan carilah pada apa yang telah dianugerahkan Allah kepadamu (kebahagiaan) negeri akhirat, dan janganlah kamu melupakan bahagianmu dari (kenikmatan) duniawi dan berbuat baiklah (kepada orang lain) sebagaimana Allah telah berbuat baik kepadamu, dan janganlah kamu berbuat kerusakan di (muka) bumi. Sesungguhnya Allah tidak menyukai orang-orang yang berbuat kerusakan.[QS. Al Qoshosh : 77]"],["a","مَنْ كَانَ يُرِيْدُ حَرْثَ الْاٰخِرَةِ نَزِدْ لَهٗ فِيْ حَرْثِهٖۚ وَمَنْ كَانَ يُرِيْدُ حَرْثَ الدُّنْيَا نُؤْتِهٖ مِنْهَاۙ وَمَا لَهٗ فِى الْاٰخِرَةِ مِنْ نَّصِيْبٍ. الشورى : 20"],["p","Barang siapa yang menghendaki keuntungan di akhirat akan Kami tambah keuntungan itu baginya dan barang siapa yang menghendaki keuntungan di dunia Kami berikan kepadanya sebagian dari keuntungan dunia dan tidak ada baginya suatu bahagian pun di akhirat. [Q.S.Asy Syuraa: 20]"],["p","Kehidupan di dunia ini tiada lain hanyalah kesenangan yang memperdayakan. Kesenangan yang dirasakan di dunia ini berupa makanan, minuman, pangkat, kedudukan, kekayaan dan sebagainya pada umumnya itu semua memperdayakan manusia. Banyak orang menyangka bahwa itulah kebahagiaan, sehingga tidak sedikit manusia tenggelam karena terlalu asyik dengan kenikmatan dunia. Padahal kalau manusia kurang pandai mempergunakannya, maka kesenangan itu akan menjadi bencana yang menyebabkan kerugian di dunia dan di akhirat kelak mendapat adzab yang pedih."],["p","Firman Allah SWT :"],["a","اِعْلَمُوْٓا اَنَّمَا الْحَيٰوةُ الدُّنْيَا لَعِبٌ وَّلَهْوٌ وَّزِيْنَةٌ وَّتَفَاخُرٌۢ بَيْنَكُمْ وَتَكَاثُرٌ فِى الْاَمْوَالِ وَالْاَوْلَادِۗ كَمَثَلِ غَيْثٍ اَعْجَبَ الْكُفَّارَ نَبَاتُهٗ ثُمَّ يَهِيْجُ فَتَرٰىهُ مُصْفَرًّا ثُمَّ يَكُوْنُ حُطَامًاۗ وَفِى الْاٰخِرَةِ عَذَابٌ شَدِيْدٌۙ وَّمَغْفِرَةٌ مِّنَ اللّٰهِ وَرِضْوَانٌ ۗ وَمَا الْحَيٰوةُ الدُّنْيَآ اِلَّا مَتَاعُ الْغُرُوْرِ. الحديد:20"],["p","Ketahuilah, bahwa sesungguhnya kehidupan dunia ini hanyalah permainan dan suatu yang melalaikan, perhiasan dan bermegah-megah diantara kamu serta berbangga-banggaan tentang banyaknya harta dan anak, seperti hujan yang tanam-tanamannya mengagumkan para petani, kemudian tanaman itu menjadi kering dan kamu lihat warnanya kuning, kemudian menjadi hancur. Dan di akhirat (nanti) ada adzab yang keras dan ampunan dari Allah serta keridlaan-Nya. Dan kehidupan dunia ini tidak lain hanyalah kesenangan yang menipu. [QS. Al-Hadiid : 20]"],["p","Sebagian manusia dalam kehidupan saat ini hampir menjadi lupa daratan, menjadi ingkar, tidak dapat bersyukur, durhaka dan berkhianat. Mereka melupakan tujuan hidupnya ketika di dunia dan hanya mengejar kenikmatan dunia. Dunia yang dikejar akan berakhir, tempat manusia hidup, tempat manusia memuja kenikmatan. Semuanya menjadi sia-sia belaka."],["p","Allah SWT berfirman:"],["a","وَ مَا الْحَيٰوةُ الدُّنْيَاۤ اِلَّا لَعِبٌ وَّلَهْوٌ ؕ وَلَـلدَّارُ الْاٰخِرَةُ خَيْرٌ لِّـلَّذِيْنَ يَتَّقُوْنَ ؕ اَفَلَا تَعْقِلُوْنَ. الانعام : 32"],["p","Dan tiadalah kehidupan dunia ini, selain dari main-main dan senda gurau belaka. Dan sungguh kampung akhirat itu lebih baik bagi orang-orang yang bertakwa. Maka tidakkah kamu memahaminya? [QS. Al-An’am:32]"],["a","وَمَا هٰذِهِ الْحَيٰوةُ الدُّنْيَآ اِلَّا لَهْوٌ وَّلَعِبٌۗ وَاِنَّ الدَّارَ الْاٰخِرَةَ لَهِيَ الْحَيَوَانُۘ لَوْ كَانُوْا يَعْلَمُوْنَ. العنكبوت : 64"],["p","Dan tiadalah kehidupan dunia ini melainkan senda gurau dan main-main. Dan sesungguhnya akhirat itulah yang sebenarnya kehidupan, kalau mereka mengetahui. [QS. Al-‘Ankabut: 64]"],["p","Sebagai umat muslim, pernahkah kita berdoa kepada Allah dengan segala sesuatu yang kita ingini dalam hati? Terkadang kita menginginkan doa tersebut disegerakan untuk dikabulkan. Namun kita lupa bahwa Allah lebih mengetahui apa yang sesungguhnya terbaik untuk kita. Ketahuilah, bahwa Allah tidak akan menetapkan segala sesuatu bagi hambaNya kecuali dengan kebaikan bagi kita, dan Allah lebih mengetahui sedangkan kita tidak mengetahui."],["a","كُتِبَ عَلَيْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ ۚ وَعَسٰٓى اَنْ تَكْرَهُوْا شَيْـًٔا وَّهُوَ خَيْرٌ لَّكُمْ ۚ وَعَسٰٓى اَنْ تُحِبُّوْا شَيْـًٔا وَّهُوَ شَرٌّ لَّكُمْ ۗ وَاللّٰهُ يَعْلَمُ وَاَنْتُمْ لَا تَعْلَمُوْنَ. البقرة : 216"],["p","Diwajibkan atas kamu berperang, padahal berperang itu adalah sesuatu yang kamu benci. Boleh jadi kamu membenci sesuatu, padahal ia amat baik bagimu, dan boleh jadi (pula) kamu menyukai sesuatu, padahal ia amat buruk bagimu; Allah mengetahui, sedang kamu tidak mengetahui. [Q.S. Al Baqarah : 216]"],["p","Dunia ini memiliki dua sisi yang bertolak belakang yaitu sisi yang menyenangkan dan sisi yang menyedihkan. Sesuatu yang menyenangkan adalah ketika kita mendapatkan kenikmatan, segala keinginan tercapai, jalan-jalan di taman yang kita lalui menjadi indah bagaikan menjadi raja dalam sekejap. Sedangkan kesedihan adalah sesuatu yang tidak menyenangkan, membuat pikiran gelisah, rasa bersalah, terhimpit kekurangan pangan, terancam kenyamanan dan keamanan diri, melihat sesuatu yang tidak disukai dan sebagainya."],["a","فَاَمَّا الْاِنْسَانُ اِذَا مَا ابْتَلٰىهُ رَبُّهٗ فَاَكْرَمَهٗ وَنَعَّمَهٗۙ فَيَقُوْلُ رَبِّيْٓ اَكْرَمَنِۗ(15)وَاَمَّآ اِذَا مَا ابْتَلٰىهُ فَقَدَرَ عَلَيْهِ رِزْقَهٗ ۙ فَيَقُوْلُ رَبِّيْٓ اَهَانَنِ (16) الفجر : 15-16"],["p","Adapun manusia apabila Tuhannya mengujinya lalu dimuliakan-Nya dan diberi-Nya kesenangan, maka dia berkata: \"Tuhanku telah memuliakanku\".(15)"],["p","Adapun bila Tuhannya mengujinya lalu membatasi rezekinya maka dia berkata: \"Tuhanku menghinakanku\". (16) [Q.S. Al Fajr : 15-16]"],["p","Sebesar apa pun nikmat yang diberikan Allah kepada kita, nikmat itu tidak akan pernah terasa jikalau hati kita tidak diliputi rasa syukur kepada Sang Maha Pemberi Rahmat. Bukan karena sedikitnya nikmat yang kita peroleh, akan tetapi lantaran begitu besarnya nikmat itu sehingga tak ada satu pun dari apa yang kita usahakan yang terlepas darinya."],["p","Rasulullah SAW bersabda :"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ اَنَّ رَسُوْلَ اللهِ ﷺ مَرَّ بِالسُّوْقِ دَاخِلًا مِنْ بَعْضِ الْعَالِيَةِ وَالنَّاسُ كَنَفَتَهُ، فَمَرَّ بِجَدْىٍ اَسَكَّ مَيِّتٍ، فَتَنَاوَلَهُ فَاَخَذَ بِاُذُنِهِ ثُمَّ قَالَ: اَيُّكُمْ يُحِبُّ اَنَّ هٰذَا لَهُ بِدِرْهَمٍ؟. فَقَالُوْا: مَا نُحِبُّ اَنَّهُ لَنَا بِشَيْءٍ، وَمَا نَصْنَعُ بِهِ؟ قَالَ: اَتُحِبُّوْنَ اَنَّهُ لَكُمْ؟. قَالُوْا: وَ اللهِ، لَوْ كَانَ حَيًّا كَانَ عَيْبًا فِيْهِ لِاَنَّهُ اَسَكُّ، فَكَيْفَ وَهُوَ مَيِّتٌ؟ فَقَالَ: فَوَ اللهِ، لَلدُّنْيَا اَهْوَنُ عَلَى اللهِ مِنْ هٰذَا عَلَيْكُمْ. مسلم 4: 2272 رقم 2"],["p","Dari Jabir bin 'Abdullah, bahwasanya Rasulullah SAW pernah melewati sebuah pasar, beliau datang dari bagian tanah yang tinggi, sedangkan para shahabat di samping (kiri kanan) beliau. Kemudian beliau melewati bangkai seekor anak kambing yang telinganya perung (kecil), lalu beliau mengambilnya dengan memegang telinganya. Kemudian beliau bersabda, \"Siapakah diantara kalian yang mau membeli ini dengan satu dirham ?\". Para shahabat menjawab, \"Kami tidak mau menukarnya dengan sesuatu milik kami, dan akan kami apakan ?\".Beliau SAW bersabda, \"Apakah kalian suka kalau bangkai ini saya berikan saja untuk kalian ?\". Mereka menjawab, \"Demi Allah,seandainya anak kambing itu dalam keadaan hidup saja ada cacatnya, karena telinganya perung, apalagi anak kambing itu sudah menjadi bangkai ?\". Beliau bersabda, \"Demi Allah, sungguh dunia ini di sisi Allah nilainya lebih rendah daripada bangkai ini di hadapan kalian\". [HR. Muslim juz 4, hal. 2272, no. 2]"],["p","Tidak sedikit orang yang dikaruniakan kekayaan, kesehatan, kelapangan rezeki yang merasa sempit hati lantaran dengki melihat tetangganya mendapatkan nikmat. Ada pula yang orang-orang sengaja mendramatisasi kehidupannya sehingga hidupnya tampak sangat menderita, padahal semua yang ditangisinya hanyalah tak lebih dari fantasi yang tidak pernah terjadi. Ketahuilah bahwa Allah tidak pernah mendzolimi hambanya, tetapi merekalah yang mendzolimi diri mereka sendiri."],["a","...فَمَا كَانَ اللّٰهُ لِيَظْلِمَهُمْ وَلٰكِنْ كَانُوْٓا اَنْفُسَهُمْ يَظْلِمُوْنَ.التوبة:70"],["p","“… maka Allah tidaklah sekali-kali menganiaya mereka, akan tetapi merekalah yang menganiaya diri mereka sendiri.” [QS. At Taubah : 70]"],["a","وَاِذْ تَاَذَّنَ رَبُّكُمْ لَئِنْ شَكَرْتُمْ لَاَزِيْدَنَّـكُمْ وَلَئِنْ كَفَرْتُمْ اِنَّ عَذَابِيْ لَشَدِيْدٌ. ابراهيم : 7"],["p","Dan (ingatlah) ketika Tuhanmu memaklumkan, “Sesungguhnya jika kamu bersyukur, niscaya Aku akan menambah (nikmat) kepadamu, tetapi jika kamu mengingkari (nikmat-Ku), maka pasti azab-Ku sangat berat.” [QS. Ibrahim: 7]"],["p","Dunia yang kita lihat dan rasakan itu merupakan sebagian kecil perumpamaan keadaan di negeri akhirat kelak. Jauh bandingannya dengan keadaan di sana. Jika kita silau terhadap keindahan-keindahan dunia, ketahuilah kelak keindahan dunia ini akan sirna dari ingatan kita ketika kita masuk ke dalam negeri akhirat."],["p","Seindah-indah wajah dunia, tak akan dapat menyamai keindahan surga di negeri akhirat. Dunia yang fana ini serba terbatas. Dunia hanyalah tempat singgah. Ibarat kita dalam perjalanan yang sangat jauh, singgah di bawah pohon satu atau dua jam hanya sekedar untuk minum dan melepaskan lelah."],["p","Rasulullah SAW berpesan agar menyikapi kehidupan dunia dengan sabdanya:"],["a","عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: اَخَذَ رَسُوْلُ اللهِ ﷺ بِمَنْكِبِيْ فَقَالَ: كُنْ فِي الدُّنْيَا كَاَنَّكَ غَرِيْبٌ اَوْ عَابِرُ سَبِيْلٍ. البخارى 7: 170"],["p","Dari 'Abdullah bin 'Umar RA, ia berkata : Rasulullah SAW memegang pundakku lalu bersabda, \"Jadilah kamu di dunia ini seolah-olah kamu seperti orang yang asing atau musafir yang sedang lewat\". [HR. Bukhari juz 7, hal. 170]"],["p","Orang asing adalah seseorang yang tidak memiliki rumah sendiri, tidak punya tempat tinggal sendiri, tidak punya negeri yang didiami secara pribadi. Fisiknya berada di negeri yang asing, tapi hatinya tidak terpikat dengan negeri asing tersebut. Keberadaannya yang sementara di negeri asing dimanfaatkan sebaik mungkin untuk mempersiapkan bekal menuju ke kehidupan selanjutnya. Dunia bagi orang beriman bukanlah negeri untuk menetap, bukan pula sebagai tempat tinggal. Orang bertaqwa memposisikan diri sebagai seorang garib (orang asing) yang tinggal sementara di negeri asing, lalu semangat mempersiapkan bekal untuk kembali ke negeri tempat tinggal sebenarnya.”"],["p","‘Abir sabil (pengembara) adalah orang yang melintasi suatu negeri asing. Ia terus bergerak dan berjalan. Ia melewati negeri asing lalu singgah sejenak. Saat singgah itulah keindahan dan kelezatan duniawi datang mengelilinginya, merayu dan menggodanya. Namun godaan dan rayuan tersebut tidak melenakannya, justru sukses mengelolanya sebagai bekal terbaik."],["p","Seorang musafir boleh jadi singgah sejenak di suatu tempat untuk merehatkan diri karena kelelahan. Tetapi pengembara yang asing singgah sejenak bukan karena kelelahan, tetapi mempersiapkan bekal untuk perjalanan selanjutnya. Segala bentuk permainan dan sendagurau dunia tidak menjadi tipuan baginya, tetapi modal utama keselamatannya. Pengembara yang asing memposisikan dunia sebagai tempat istirahat sejenak untuk kemudian akan ditinggalkan."],["p","Rasulullah SAW bersabda;"],["a","عَنِ ابْنِ عَبَّاسٍ، قَالَ : دَخَلَ عُمَرُ بْنُ الْخَطَّابِ عَلَى النَّبِيِّ ﷺ وَ هُوَ عَلَى حَصِيْرٍ قَدْ اَثَّرَ فِى جَنْبِهِ. فَقَالَ: يَا رَسُوْلَ اللهِ، لَوِ اتَّخَدْتُ فِرَاشًا اَوْثَرَ مِنْ هٰذَا؟ فَقَالَ: يَا عُمَرُ، مَالِيْ وَ لِلدُّنْيَا، وَمَا لِلدُّنْيَا وَلِيْ؟ وَالَّذِيْ نَفْسِيَ بِيَدِهِ، مَا مَثَلِيْ وَ مَثَلُ الدُّنْيَا اِلَّا كَرَاكِبٍ سَارَ فِى يَوْمٍ صَائِفٍ، فَاسْتَظَلَّ تَحْتَ شَجَرَةٍ سَاعَةً مِنْ نَهَارٍ، ثُمَّ رَاحَ وَ تَرَكَهَا. ابن حبان 14 :265 رقم 6352"],["p","Dari Ibnu Abbas, ia berkata: ‘Umar datang kepada Rasulullah SAW, sedangkan beliau di atas tikar dan pada lambung beliau ada bekas tikar. Kemudian (‘Umar) berkata, “Ya Rasulullah, bagaimana seandainya saya buatkan kasur, yang lebih baik dari pada ini?”. Beliau menjawab, “Wahai ‘Umar, apalah urusanku dengan dunia ini, dan apalah urusan dunia ini dengan-ku? Demi Dzat yang aku di tangan-Nya, tidaklah perumpamaan-ku dan perumpamaan dunia ini, kecuali seperti seorang musafir yang menunggang kendaraan berjalan di siang hari yang panas lalu berteduh di bawah pohon sesaat, kemudian pergi meninggalkannya”. [HR. Ibnu Hibban juz 14, hal. 265, no. 6352]"],["p","Inilah dua pesan Nabi SAW menjadi pesan bagi kita selaku umatnya yang setia mengikuti sunnahnya. Jalani tahapan kehidupan dunia yang singkat dengan memposisikan diri sebagai pengembara yang asing yang tidak menjadikan dunia sebagai tujuan, tetapi sebatas tempat persinggahan menyiapkan bekal menuju tahapan kehidupan selanjutnya."],["p","Segala keindahan dan kelezatan dunia bagi banyak orang adalah kenikmatan yang menipunya di dunia dan malapetaka baginya di akhirat. Tetapi bagi pengembara yang asing tidak demikian. Segala keindahan dan kelezatan tersebut tidak menjadikannya terbuai dan terlena sehingga lupa diri dengan statusnya yang hanya singgah sejenak. Tetapi, ia mampu mengelolanya dengan baik dan menjadikannya sebagai bekal dalam perjalanannya menuju akhirat. Ia mampu mengelola kenikmatan duniawi yang semu dan bersifat sementara menjadi modal mulia yang kelak dipergunakan untuk menukarnya dengan kenikmatan surga yang hakiki dan abadi."],["p","bersambung …."]],"c20220724_1291":[["p","Ahad, 24 Juli 2022/25 Dzulhijjah 1443 Brosur No.: 2086/2126/IA"],["p","Zuhud dalam kehidupan dunia (2)"],["p","Jika kita melihat dunia dengan segala kenikmatannya, niscaya kita akan terkesima dan tertarik untuk melakukan apapun demi memenuhi hasrat. Namun perlu disadari bahwa dunia ini hanya sementara dan kampung akhirat adalah abadi. Dunia ibarat surga bagi orang kafir dan penjara bagi orang-orang mukmin."],["a","عَنْ اَبيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اَلدُّنْيَا سِجْنُ الْمُؤْمِنِ وَجَنَّةُ الْكَافِرِ. مسلم 4: 2272"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Dunia ini penjaranya orang mu'min dan surganya orang kafir\". [HR. Muslim juz 4, hal. 2272]"],["p","Dunia ibarat surga bagi orang kafir karena mereka bisa melakukan apa saja yang mereka inginkan di dunia ini. Memuaskan hawa nafsu, memakan makanan tanpa mengenal halal haram, minum khamr, berzina, berjudi dan lain sebagainya. Sebaliknya, dunia ini bagaikan sebuah penjara yang menyesakkan bagi orang-orang mukmin karena mereka harus menahan segala apa yang diperintahkan oleh nafsunya."],["a","زُيِّنَ لِلَّذِيْنَ كَفَرُوا الْحَيٰوةُ الدُّنْيَا وَيَسْخَرُوْنَ مِنَ الَّذِيْنَ اٰمَنُوْا ۘ وَالَّذِيْنَ اتَّقَوْا فَوْقَهُمْ يَوْمَ الْقِيٰمَةِ ۗ وَاللّٰهُ يَرْزُقُ مَنْ يَّشَاۤءُ بِغَيْرِ حِسَابٍ. البقرة: 212"],["p","Kehidupan dunia dijadikan indah dalam pandangan orang-orang kafir, dan mereka memandang hina orang-orang yang beriman. Padahal orang-orang yang bertaqwa itu lebih mulia daripada mereka di hari kiamat. Dan Allah memberi rezeki kepada orang-orang yang dikehendaki-Nya tanpa batas. [QS. Al-Baqarah: 212]"],["p","Ketika orang-orang kafir memamerkan segala kekayaan dunia yang mereka miliki serta merendahkan orang-orang yang beriman dalam kehidupan dunia ini kita tidak usah bersedih hati dan tidak usah merasa rendah diri."],["p","Allah SWT memberikan kabar gembira kepada orang-orang yang beriman dalam firman-Nya :"],["a","وَلَا تَهِنُوْا وَلَا تَحْزَنُوْا وَاَنْتُمُ الْاَعْلَوْنَ اِنْ كُنْتُمْ مُّؤْمِنِيْنَ. ال عمران : 139"],["p","Janganlah kamu bersikap lemah, dan janganlah (pula) kamu bersedih hati, padahal kamulah orang-orang yang paling tinggi (derajatnya), jika kamu orang-orang yang beriman. [Q.S. Ali ‘Imran : 139]"],["p","Biarlah mereka bersenang-senang serta dilalaikan oleh angan-angan kosong mereka, besok pada hari kiamat yaitu hari pembalasan amal, orang-orang yang beriman akan menertawakan mereka dan mereka pun berangan-angan agar dikembalikan ke dunia ini untuk menjadi seorang muslim, Allah SWT berfirman:"],["a","فَالْيَوْمَ الَّذِيْنَ اٰمَنُوْا مِنَ الْكُفَّارِ يَضْحَكُوْنَ. المطففين : 34"],["p","”Maka pada hari ini, orang-orang yang beriman menertawakan orang-orang kafir” [Q.S. Al-Muthaffifin: 34]"],["a","حَتّٰىٓ اِذَا جَاۤءَ اَحَدَهُمُ الْمَوْتُ قَالَ رَبِّ ارْجِعُوْنِ ۙ (99) لَعَلِّيْٓ اَعْمَلُ صَالِحًا فِيْمَا تَرَكْتُ كَلَّا ۗ اِنَّهَا كَلِمَةٌ هُوَ قَاۤىِٕلُهَاۗ وَمِنْ وَّرَاۤىِٕهِمْ بَرْزَخٌ اِلٰى يَوْمِ يُبْعَثُوْنَ (100) المؤمنون : 99-100"],["p","(Demikianlah keadaan orang-orang kafir itu), hingga apabila datang kematian kepada seseorang dari mereka, dia berkata: \"Ya Tuhanku kembalikanlah aku (ke dunia), (99)"],["p","agar aku berbuat amal yang shalih terhadap yang telah aku tinggalkan. Sekali-kali tidak. Sesungguhnya itu adalah perkataan yang diucapkannya saja. Dan di hadapan mereka ada dinding sampai hari mereka dibangkitkan (100). (Q.S. Al Mu’minuun : 99-100)"],["p","Sebagai orang yang beriman jangan tertipu dan terpedaya dengan kehidupan dunia ini. Kehidupan yang penuh senda gurau dan main-main, kehidupan yang sungguh melalaikan. Jangan lupa bahwa dunia hanyalah “Panggung sandiwara” kehidupan dipentaskan. Kita bagaikan aktor dan artis yang sedang memegang peran masing-masing. Sedangkan sutradaranya adalah Allah SWT. Skenarionya adalah Al Qur’an dan As Sunnah. Barang siapa yang memerankan perannya sesuai dengan skenario Allah, maka akan menjadi sebaik-baik makhluk serta memperoleh balasan berupa surga yang penuh dengan kenikmatan. Tetapi bagi mereka yang berperan sesuai kehendak hati dan nafsunya melanggar skenario yang ditetapkan oleh sang Sutradara Kehidupan, mereka akan menjadi seburuk-buruk makhluk serta masuk ke dalam neraka yang menghinakan dan menyengsarakan."],["a","اِنَّ الَّذِيْنَ كَفَرُوْا مِنْ اَهْلِ الْكِتٰبِ وَالْمُشْرِكِيْنَ فِيْ نَارِ جَهَنَّمَ خٰلِدِيْنَ فِيْهَاۗ اُولٰۤىِٕكَ هُمْ شَرُّ الْبَرِيَّةِۗ (6) اِنَّ الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ اُولٰۤىِٕكَ هُمْ خَيْرُ الْبَرِيَّةِۗ (7) جَزَاۤؤُهُمْ عِنْدَ رَبِّهِمْ جَنّٰتُ عَدْنٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَآ اَبَدًا ۗ رَضِيَ اللّٰهُ عَنْهُمْ وَرَضُوْا عَنْهُ ۗ ذٰلِكَ لِمَنْ خَشِيَ رَبَّهٗ (8) البينة : 6-8"],["p","Sesungguhnya orang-orang kafir yakni ahli kitab dan orang-orang musyrik (akan masuk) ke neraka Jahanam; mereka kekal di dalamnya. Mereka itu adalah seburuk-buruk makhluk.(6)"],["p","Sesungguhnya orang-orang yang beriman dan mengerjakan amal shaleh mereka itu adalah sebaik-baik makhluk.(7)"],["p","Balasan mereka di sisi Tuhan mereka ialah surga ‘Adn yang mengalir di bawahnya sungai-sungai; mereka kekal di dalamnya selama-lamanya. Allah ridla terhadap mereka dan mereka pun ridla kepada-Nya. Yang demikian itu adalah (balasan) bagi orang yang takut kepada Tuhannya.(8) [Q.S. Al Bayyinah : 6-8]"],["a","يَوْمَ يَجْمَعُكُمْ لِيَوْمِ الْجَمْعِ ذٰلِكَ يَوْمُ التَّغَابُنِۗ وَمَنْ يُّؤْمِنْۢ بِاللّٰهِ وَيَعْمَلْ صَالِحًا يُّكَفِّرْ عَنْهُ سَيِّاٰتِهٖ وَيُدْخِلْهُ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَآ اَبَدًاۗ ذٰلِكَ الْفَوْزُ الْعَظِيْمُ (9)وَالَّذِيْنَ كَفَرُوْا وَكَذَّبُوْا بِاٰيٰتِنَآ اُولٰۤىِٕكَ اَصْحٰبُ النَّارِ خٰلِدِيْنَ فِيْهَاۗ وَبِئْسَ الْمَصِيْرُ (10) التغابن :9 - 10"],["p","(Ingatlah) hari (yang di waktu itu) Allah mengumpulkan kamu pada hari pengumpulan (untuk dihisab), itulah hari (waktu itu) ditampakkan kesalahan-kesalahan. Dan barang siapa yang beriman kepada Allah dan mengerjakan amal saleh niscaya Allah akan menghapus kesalahan-kesalahannya dan memasukkannya ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya selama-lamanya. Itulah keberuntungan yang besar.(9)"],["p","Dan orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itulah penghuni-penghuni neraka, mereka kekal di dalamnya. Dan itulah seburuk-buruk tempat kembali.(10). [Q.S. At Taghaabun : 9-10]"],["a","لِلَّذِيْنَ اسْتَجَابُوْا لِرَبِّهِمُ الْحُسْنٰىۗ وَالَّذِيْنَ لَمْ يَسْتَجِيْبُوْا لَهٗ لَوْ اَنَّ لَهُمْ مَّا فِى الْاَرْضِ جَمِيْعًا وَّمِثْلَهٗ مَعَهٗ لَافْتَدَوْا بِهٖ ۗ اُولٰۤىِٕكَ لَهُمْ سُوْۤءُ الْحِسَابِ ۙ وَمَأْوٰىهُمْ جَهَنَّمُ ۗ وَبِئْسَ الْمِهَادُ. الرعد :18"],["p","Bagi orang-orang yang memenuhi seruan Tuhannya, (disediakan) pembalasan yang baik. Dan orang-orang yang tidak memenuhi seruan Tuhan, sekiranya mereka mempunyai semua (kekayaan) yang ada di bumi dan (ditambah) sebanyak isi bumi itu lagi besertanya, niscaya mereka akan menebus dirinya dengan kekayaan itu. Orang-orang itu disediakan baginya hisab yang buruk dan tempat kediaman mereka ialah Jahanam dan itulah seburuk-buruk tempat kediaman. [Q.S. Ar-Ra’du : 18]"],["a","وَسِيْقَ الَّذِيْنَ كَفَرُوْٓا اِلٰى جَهَنَّمَ زُمَرًا ۗ حَتّٰىٓ اِذَا جَاۤءُوْهَا فُتِحَتْ اَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَآ اَلَمْ يَأْتِكُمْ رُسُلٌ مِّنْكُمْ يَتْلُوْنَ عَلَيْكُمْ اٰيٰتِ رَبِّكُمْ وَيُنْذِرُوْنَكُمْ لِقَاۤءَ يَوْمِكُمْ هٰذَا ۗ قَالُوْا بَلٰى وَلٰكِنْ حَقَّتْ كَلِمَةُ الْعَذَابِ عَلَى الْكٰفِرِيْنَ (71) قِيْلَ ادْخُلُوْٓا اَبْوَابَ جَهَنَّمَ خٰلِدِيْنَ فِيْهَا ۚ فَبِئْسَ مَثْوَى الْمُتَكَبِّرِيْنَ (72) وَسِيْقَ الَّذِيْنَ اتَّقَوْا رَبَّهُمْ اِلَى الْجَنَّةِ زُمَرًا ۗ حَتّٰىٓ اِذَا جَاۤءُوْهَا وَفُتِحَتْ اَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلٰمٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوْهَا خٰلِدِيْنَ (73) وَقَالُوا الْحَمْدُ لِلّٰهِ الَّذِيْ صَدَقَنَا وَعْدَهٗ وَاَوْرَثَنَا الْاَرْضَ نَتَبَوَّاُ مِنَ الْجَنَّةِ حَيْثُ نَشَاۤءُ ۚ فَنِعْمَ اَجْرُ الْعٰمِلِيْنَ (74) الزمر :71-74"],["p","Orang-orang yang kufur digiring ke (neraka) Jahanam secara berombongan sehingga apabila mereka telah sampai di sana, pintu-pintunya dibuka dan para penjaganya berkata kepada mereka, “Apakah belum pernah datang kepadamu rasul-rasul dari kalanganmu yang membacakan ayat-ayat Tuhanmu dan memperingatkan kepadamu pertemuan (dengan) harimu ini?” Mereka menjawab, “Benar, (telah datang para rasul).” Akan tetapi, ketetapan adzab pasti berlaku terhadap orang-orang kafir. (71)."],["p","Dikatakan (kepada mereka), “Masuklah pintu-pintu (neraka) Jahanam (untuk tinggal) di dalamnya selama-lamanya!” Maka, (neraka Jahanam) itu seburuk-buruk tempat tinggal bagi orang-orang yang takabur. (72)."],["p","Orang-orang yang bertakwa kepada Tuhannya diantar ke dalam surga secara berombongan sehingga apabila mereka telah sampai di sana dan pintu-pintunya telah dibuka, para penjaganya berkata kepada mereka, “Salāmun ‘alaikum (semoga keselamatan tercurah kepadamu), berbahagialah kamu. Maka, masuklah ke dalamnya (untuk tinggal) selama-lamanya!” (73)."],["p","Mereka berkata, “Segala puji bagi Allah yang telah memenuhi janji-Nya dan mewariskan bumi (di akhirat) ini kepada kami sehingga dapat menempati surga sesuai dengan kehendak kami.” (Surga adalah) sebaik-baik balasan bagi orang-orang yang beramal (saleh). (74). [Q.S. Az Zumar : 71-74]"],["p","Seluruh kelezatan di dunia dan pemandangan yang begitu indah, Allah SWT jadikan sebagai cobaan dan ujian dari-Nya. Allah SWT juga memberikan kemampuan kepada para hamba-Nya untuk mengelola isi dunia, lalu Allah melihat bagaimana mereka berbuat. Barang siapa mengambilnya dari yang halal, meletakkannya sesuai dengan haknya, memanfaatkannya agar ia bisa beribadah kepada Allah, maka itu semua menjadi bekal baginya untuk pergi ke tempat yang lebih mulia dan kekal. Dengan demikian, sempurnalah baginya kebahagiaan dunia dan akhirat. Akan tetapi sebaliknya, barang siapa menjadikan dunia sebagai cita-cita terbesarnya dan tujuan serta keinginannya, maka ia akan mendapat dunia sesuai dengan yang telah ditetapkan baginya oleh Allah SWT. Lalu akhirnya hidupnya sengsara, dia tidak merasakan kelezatan dan syahwatnya kecuali hanya sebentar saja. Kelezatannya sedikit, tetapi kesedihannya berkepanjangan."],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِيِّ عَنِ النَّبِيِّ ﷺ قَالَ: اِنَّ الدُّنْيَا حُلْوَةٌ خَضِرَةٌ، وَ اِنَّ اللهَ مُسْتَخْلِفُكُمْ فِيْهَا، فَيَنْظُرُ كَيْفَ تَعْمَلُوْنَ، فَاتَّقُوا الدُّنْيَا وَ اتَّقُوا النِّسَاءَ، فَاِنَّ اَوَّلَ فِتْنَةِ بَنِيْ اِسْرَائِيْلَ كَانَتْ فِى النِّسَاءِ. مسلم 4: 2098 رقم 99"],["p","Dari Abu Sa'id Al-Khudriy, dari Nabi SAW, beliau bersabda, \"Sesungguhnya dunia itu manis dan indah, dan sesungguhnya Allah menjadikan kalian untuk mengelolanya, maka Allah akan melihat bagaimana yang kalian perbuat (berbuat tha'at kepada Allah atau berbuat ma'shiyat). Maka hati-hatilah kalian terhadap dunia, dan hati-hatilah terhadap wanita, karena pertama-tama fitnah yang terjadi di kalangan Bani Israil adalah karena wanita\". [HR. Muslim juz 4, hal. 2098, no 99]"],["a","عَنْ اُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ ﷺ قَالَ: مَا تَرَكْتُ بَعْدِيْ فِتْنَةً اَضَرَّ عَلَى الرِّجَالِ مِنَ النِّسَاءِ. البخاري"],["p","Dari Usamah bin Zaid RA, dari Nabi SAW, beliau bersabda: \"Tidaklah aku meninggalkan sesudahku fitnah yang lebih membahayakan bagi kaum laki-laki daripada fitnah wanita.\" [H.R. Bukhari juz 6. Hal. 124]"],["p","Allah SWT berfirman:"],["a","اِنَّا جَعَلْنَا مَا عَلَى الْاَرْضِ زِيْنَةً لَّهَا لِنَبْلُوَهُمْ اَيُّهُمْ اَحْسَنُ عَمَلًا. الكهف : 7"],["p","Sesungguhnya Kami telah menjadikan apa yang ada di bumi sebagai perhiasan baginya, untuk Kami menguji mereka, siapakah di antaranya yang terbaik perbuatannya. [QS. Al-Kahfi: 7]"],["p","Pada hadits di atas kita diperintahkan oleh Nabi Muhammad SAW untuk hati-hati dan waspada terhadap dua fitnah yang disejajarkan yaitu fitnah dunia dan fitnah wanita. Waspada terhadap dunia maksudnya adalah berhati-hati jangan sampai terpedaya/tertipu oleh manis dan keindahannya, sedangkan waspada terhadap wanita maksudnya adalah berhati-hati terhadap fitnah yang ditimbulkan oleh wanita dengan pesona, rayuan dan godaannya, karena dari keduanya manusia dapat tergelincir ke jurang kebinasaan kalau tidak bisa mengelola dan menyikapinya dengan baik."],["p","Fitnah/ujian yang terbesar bagi kaum laki-laki adalah wanita karena fitnahnya sangat besar dan berbahaya. Sudah berapa banyak orang yang jatuh tergelincir disebabkan wanita. Untuk mengantisipasi hal tersebut Allah telah membuat rambu-rambu peringatan agar manusia ada perhatian dan berusaha semaksimal mungkin untuk menjauhinya. Sebagaimana yang difirman oleh Allah SWT:"],["a","قُلْ لِّلْمُؤْمِنِيْنَ يَغُضُّوْا مِنْ اَبْصَارِهِمْ وَيَحْفَظُوْا فُرُوْجَهُمْۗ ذٰلِكَ اَزْكٰى لَهُمْۗ اِنَّ اللّٰهَ خَبِيْرٌۢ بِمَا يَصْنَعُوْنَ. النور : 30"],["p","Katakanlah kepada orang laki-laki yang beriman: \"Hendaklah mereka menahan pandangannya, dan memelihara kemaluannya; yang demikian itu adalah lebih suci bagi mereka, sesungguhnya Allah Maha Mengetahui apa yang mereka perbuat\". [Q.S. An Nuur : 30]"],["a","عَنِ ابْنِ بُرَيْدَةَ عَنْ اَبِيْهِ قَالَ: قَالَ رَسُوْلُ اللهِ لِعَلِيٍّ: يَا عَلِيُّ، لَا تُتْبِعِ النَّظْرَةَ النَّظْرَةَ فَاِنَّ لَكَ الْاُوْلَى وَ لَيْسَتْ لَكَ الْآخِرَةُ. ابو داود 2: 246، رقم: 2149"],["p","Dari Ibnu Buraidah, dari ayahnya, ia berkata : Rasulullah SAW bersabda kepada ‘Ali, “Hai Ali, janganlah engkau iringkan satu pandangan (kepada wanita) dengan satu pandangan, karena yang pertama itu tidak mengapa, tetapi tidak yang kedua”. [HR. Abu Dawud juz 2, hal. 246, no. 2149]"],["a","وَلَا تَقْرَبُوا الزِّنٰىٓ اِنَّهٗ كَانَ فَاحِشَةً ۗ وَسَاۤءَ سَبِيْلًا. الاشراء : 32"],["p","Dan janganlah kamu mendekati zina; sesungguhnya zina itu adalah suatu perbuatan yang keji dan suatu jalan yang buruk. (Q.S. Al Israa’ : 32)"],["a","اَلَا لَا يَخْلُوَنَّ رَجُلٌ بِامْرَأَةٍ اِلَّا كَانَ ثَالِثُهُمَا الشَّيْطَانَ.الترمدي 3 : 315 رقم 2254 هذا حديث صحيح غريب"],["p","Ingatlah, tidaklah seorang laki-laki bersepi-sepi dengan seorang wanita, melainkan yang ketiganya adalah syaithan. [HR. Tirmidzi juz 3, hal. 315, no. 2254, ia berkata : Ini hadits hasan shahih gharib. Dari 'Umar bin Khaththab]"],["p","--oo0oo--"]],"c20220731_1292":[["p","Ahad, 31 Juli 2022/2 Muharram 1444 Brosur No.: 2087/2127/IA"],["p","Zuhud dalam kehidupan dunia (3)"],["p","Kesederhanaan kehidupan Rasulullah SAW"],["p","Pola hidup sederhana adalah ajaran Nabi SAW yang merupakan pengejawantahan rasa qona’ah dan syukur."],["h","1. Nabi SAW memperbaiki bejana yang retak"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ اَنَّ قَدَحَ النَّبِيِّ ﷺ اِنْكَسَرَ فَاتَّخَذَ مَكَانَ الشَّعْبِ سِلْسِلَةً مِنْ فِضَّةٍ. قَالَ عَاصِمٌ: رَأَيْتُ الْقَدَحَ وَشَرِبْتُ فِيْهِ. البخارى 4 : 47"],["p","Dari Anas bin Malik RA, ia berkata; \"Bahwasanya bejana milik Nabi SAW retak, lalu beliau mengikatnya dengan pengikat dari perak\". 'Ashim (perawi) berkata; \"Aku melihat bejana tersebut lalu kupergunakan untuk minum\". [HR. Bukhari juz 4, hal. 47]"],["p","Umar bin Khaththab juga menambal bajunya."],["a","عَنْ اِسْحَقَ بْنِ عَبْدِ اللهِ بْنِ اَبِيْ طَلْحَةَ أَنَّهُ قَالَ: قَالَ اَنَسُ بْنُ مَالِكٍ: رَأَيْتُ عُمَرَ بْنَ الْخَطَّابِ وَهُوَ يَوْمَئِذٍ اَمِيْرُ الْمَدِيْنَةِ وَقَدْ رَقَعَ بَيْنَ كَتِفَيْهِ بِرُقَعٍ ثَلَاثٍ لَبَّدَ بَعْضَهَا فَوْقَ بَعْضٍ. مالك في الموطأ 2 : 918 رقم 19"],["p","Dari Ishaq bin Abdullah bin Abu Thalhah, ia berkata; Anas bin Maalik berkata; \"Aku melihat ‘Umar bin Khaththab ketika itu menjadi gubernur Madinah, menambal baju pada bagian kedua pundaknya dengan tiga buah tambalan, dia menempelkan sebagian di atas bagian lainnya.\" [HR. Maalik di dalam Al Muwaththo’ juz 2, hal 918, no. 19]"],["h","2. Nabi SAW memohon rezqi sekedar yang memenuhi kebutuhan pokok"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: اَللّٰهُمَّ ارْزُقْ آلَ مُحَمَّدٍ قُوتًا. البخارى 7 : 181"],["p","Dari Abu Hurairah RA, dia berkata; Rasulullah SAW berdo’a: \"Ya Allah, berilah rezqi kepada keluarga Muhammad sekedarnya.\" [HR. Bukhari juz 7, hal. 181]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ ﷺ : اَللّٰهُمَّ اجْعَلْ رِزْقَ آلِ مُحَمَّدٍ قُوتًا. مسلم 4 : 2281 رقم 18"],["p","Dari Abu Hurairah, ia berkata: Rasulullah SAW berdo’a: \"Ya Allah, jadikanlah rezqi keluarga Muhammad sekedarnya.\" [HR. Muslim juz 4, hal 2281, no. 18]"],["h","3. Nabi SAW tidak pernah mendapati banyak makanan dalam kesehariannya"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ اَنَّ رَسُوْلَ اللهِ ﷺ لَمْ يَجْتَمِعْ لَهُ غَدَاءٌ وَلَا عَشَاءٌ مِنْ خُبْزٍ وَلَحْمٍ اِلَّا عَلَى ضَفَفٍ. احمد 4 : 538 رقم 13860"],["p","Dari Anas bin Maalik, bahwasanya Rasulullah SAW tidak pernah terkumpul daging dan roti ketika makan pagi dan makan malam, melainkan di saat sedang menjamu tamu. [HR. Ahmad juz 4, hal. 538, no. 13860]"],["a","عَنْ عَبْدِ الرَّحْمٰنِ بْنِ عَابِسٍ عَنْ اَبِيْهِ قَالَ: قُلْتُ لِعَائِشَةَ اَنَهَى النَّبِيُّ ﷺ اَنْ تُؤْكَلَ لُحُوْمُ الْاَضَاحِى فَوْقَ ثَلَاثٍ؟ قَالَتْ: مَا فَعَلَهُ اِلَّا فِيْ عَامٍ جَاعَ النَّاسُ فِيْهِ فَاَرَادَ اَنْ يُطْعِمَ الْغَنِيُّ الْفَقِيْرَ وَاِنْ كُنَّا لَنَرْفَعُ الْكُرَاعَ فَنَاْكُلُهُ بَعْدَ خَمْسَ عَشْرَةَ. قِيْلَ مَا اضْطَرَّكُمْ اِلَيْهِ؟ فَضَحِكَتْ قَالَتْ: مَا شَبِعَ آلُ مُحَمَّدٍ ﷺ مِنْ خُبْزِ بُرٍّ مَأْدُوْمٍ ثَلَاثَةَ اَيَّامٍ حَتَّى لَحِقَ بِاللهِ . البخارى 6 : 206"],["p","Dari 'Abdurrahman bin ‘Aabis dari bapaknya, ia berkata; \"Aku bertanya kepada Aisyah; 'Apakah Nabi SAW melarang untuk makan daging sembelihan hari raya ‘Iedul Adlha lebih dari tiga hari? ' Aisyah menjawab; \"Beliau tidak melakukan itu kecuali pada tahun orang-orang kelaparan, sehingga beliau berharap orang kaya memberi makan kepada yang miskin. Dan sungguh, dahulu kami makan kaki kambing setelah lima belas hari.\" Lalu dikatakan; 'Apa yang mendorong kalian melakukan itu? ' Aisyah tertawa, lalu berkata; “Keluarga Muhammad SAW tidak pernah merasakan kenyang karena makan roti gandum dengan lauk lebih dari tiga hari hingga beliau bertemu dengan Allah.” [HR. Bukhari juz 6, hal. 206]"],["a","عَنْ عَائِشَةَ قَالَتْ: مَا شَبِعَ آلُ مُحَمَّدٍ ﷺ مِنْ خُبْزِ بُرٍّ فَوْقَ ثَلَاثٍ. مسلم 4 : 2282 رقم 23"],["p","Dari Aisyah, ia berkata: “Keluarga Muhammad SAW tidak pernah merasakan kenyang makan roti gandum lebih dari tiga hari.” [HR. Muslim juz 4, hal. 2282, no. 23]"],["h","4. Terkadang keluarga Nabi SAW tidak mendapati makanan di suatu hari"],["a","عَنْ عَائِشَةَ اُمِّ الْمُؤْمِنِيْنَ قَالَتْ: دَخَلَ عَلَيَّ النَّبِيُّ ﷺ ذَاتَ يَوْمٍ فَقَالَ: هَلْ عِنْدَكُمْ شَيْئٌ؟ فَقُلْنَا: لَا. قَالَ: فَاِنِّيْ اِذَنْ صَائِمٌ. ثُمَّ اَتَانَا يَوْمًا اٰخَرَ فَقُلْنَا: يَا رَسُوْلَ اللهِ اُهْدِيَ لَنَا حَيْسٌ. فَقَالَ: اَرِيْنِيْهِ، فَلَقَدْ اَصْبَحْتُ صَائِمًا. فَاَكَلَ. مسلم 2: 809 رقم 170"],["p","Dari 'Aisyah ummul mukminin, ia berkata, “Pada suatu hari Nabi SAW masuk ke rumah lalu bertanya, \"Apakah kamu mempunyai sesuatu (makanan) ?\" Kami menjawab, \"Tidak ada\". Maka beliau bersabda, \"Bila demikian maka aku akan berpuasa\". Dan pada hari yang lain beliau datang pula, maka kami berkata, \"Ya Rasulullah, ada orang yang menghadiahkan hais (makanan yang dibuat dari korma, samin dan susu kambing) kepada kita\". Beliau bersabda, \"Perlihatkanlah kepadaku, karena sesungguhnya aku berpagi dalam keadaan berpuasa”. Kemudian beliau makan\". [HR. Muslim juz 2, hal. 809, no. 170]"],["a","عَنْ سِمَاكٍ قَالَ: سَمِعْتُ النُّعْمَانَ بْنَ بَشِيْرٍ يَقُوْلُ: اَلَسْتُمْ فِيْ طَعَامٍ وَشَرَابٍ مَا شِئْتُمْ؟ لَقَدْ رَأَيْتُ نَبِيَّكُمْ ﷺ وَمَا يَجِدُ مِنَ الدَّقَلِ مَا يَمْلَأُ بِهِ بَطْنَهُ . مسلم 4 : 2284 رقم 34"],["p","Dari Simak, ia berkata: Aku mendengar An Nu'man bin Basyir berkata: Bukankah kalian makan dan minum semau kalian? Dahulu aku pernah melihat Nabi kalian SAW tidak memiliki kurma paling jelek (sekali pun) untuk mengisi perutnya.” [HR. Muslim juz 4, hal 2284, no. 34]"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ يَأْتِيْ عَلَيْنَا الشَّهْرُ مَا نُوقِدُ فِيْهِ نَارًا اِنَّمَا هُوَ التَّمْرُ وَالْمَاءُ اِلَّا اَنْ نُؤْتَى بِاللُّحَيْمِ. البخارى 7 : 181"],["p","Dari Aisyah RA, dia berkata; \"Pernah selama sebulan tidak ada nyala api dalam rumah kami (tidak memasak), yang ada hanyalah kurma dan air, kecuali bila kami diberi (dikirimi) daging.” [HR. Bukhari juz 7, hal. 181]"],["h","5. Sederhananya sandal Nabi SAW"],["a","عَنْ عِيْسَى بْنِ طَهْمَانَ قَالَ: اَخْرَجَ اِلَيْنَا اَنَسٌ نَعْلَيْنِ جَرْدَاوَيْنِ لَهُمَا قِبَالَانِ. فَحَدَّثَنِيْ ثَابِتٌ الْبُنَانِيُّ بَعْدُ عَنْ اَنَسٍ اَنَّهُمَا نَعْلَا النَّبِيِّ ﷺ. البخارى 4 : 47"],["p","Dari 'Isa bin Thahman, ia berkata; “Anas pernah memperlihatkan kepada kami sepasang sandal yang terbuat bukan dari kulit yang ada talinya di bagian depannya”. Kemudian setelah itu Tsabit Al Bunaniy bercerita kepadaku dari Anas bahwa sandal itu adalah sandal Nabi SAW. [HR. Bukhari juz 4, hal 47]"],["a","عَنْ قَتَادَةَ حَدَّثَنَا اَنَسٌ رَضِيَ اللهُ عَنْهُ اَنَّ نَعْلَ النَّبِيِّ ﷺ كَانَ لَهَا قِبَالَانِ. البخارى 7 : 49"],["p","Dari Qatadah, ia berkata : telah menceritakan kepada kami Anas RA bahwa sandal Nabi SAW memiliki dua tali. [HR. Bukhari juz 7, hal. 49]"],["h","6. Sederhananya tempat tidur Nabi SAW"],["a","عَنْ عَائِشَةَ قَالَتْ: اِنَّمَا كَانَ فِرَاشُ رَسُوْلِ اللهِ ﷺ مِنْ اَدَمٍ وَحَشْوُهُ مِنْ لِيْفٍ. البخارى 7 : 180"],["p","Dari ‘Aisyah, ia berkata: “Dahulu tempat tidur Rasulullah SAW terbuat dari kulit yang di dalamnya diisi serabut”. [HR. Bukhari juz 7, hal. 180]"],["a","عَنْ عَبْدِ اللهِ قَالَ: نَامَ رَسُوْلُ اللهِ ﷺ عَلَى حَصِيْرٍ فَقَامَ وَ قَدْ اَثَّرَ فِى جَنْبِهِ. قُلْنَا: يَا رَسُوْلَ اللهِ، لَوِ اتَّخَذْنَا لَكَ وِطَاءً؟ فَقَالَ: مَا لِيْ وَ لِلدُّنْيَا مَا اَنَا فِى الدُّنْيَا اِلاَّ كَرَاكِبٍ اِسْتَظَلَّ تَحْتَ شَجَرَةٍ ثُمَّ رَاحَ وَ تَرَكَهَا. الترمذى 4 : 17 رقم 2483 هذا حديث صحيح"],["p","Dari Abdullah (bin Mas’ud), ia berkata : Rasulullah SAW tidur di atas tikar kemudian beliau bangun dan tikar itu membekas pada lambung beliau. Kami berkata, “Ya Rasulullah, bagaimana kalau kami buatkan kasur yang empuk untukmu ?”. Beliau menjawab, “Apalah urusanku dengan dunia, tidaklah aku di dunia ini kecuali seperti musafir yang menunggang kendaraan lalu berteduh di bawah pohon, kemudian pergi dan meninggalkannya”. [HR. Tirmidzi juz 4, hal. 17, no. 2483, ini hadits shahih]"],["a","عَنْ عَبْدِ اللهِ بْنِ مَسْعُوْدٍ قَالَ: دَخَلْتُ عَلَى رَسُوْلِ اللهِ ﷺ وَ هُوَ فِيْ غُرْفَةٍ كَاَنَّهَا بَيْتُ حَمَّامٍ وَ هُوَ نَائِمٌ عَلَى حَصِيْرٍ قَدْ اَثَّرَ بِجَنْبِهِ، فَبَكَيْتُ. فَقَالَ: مَا يُبْكِيْكَ يَا عَبْدَ اللهِ؟ قُلْتُ: يَا رَسُوْلَ اللهِ، كِسْرَى وَ قَيْصَرُ يَطَئُوْنَ عَلَى الْخَزِّ وَ الدِّيْبَاجِ وَ الْحَرِيْرِ وَ اَنْتَ نَائِمٌ عَلَى هٰذَا الْحَصِيْرِ قَدْ اَثَّرَ بِجَنْبِكَ. قَالَ: فَلَا تَبْكِ يَا عَبْدَ اللهِ، فَاِنَّ لَهُمُ الدُّنْيَا وَ لَنَا الْاۤخِرَةُ، وَ مَا اَنَا وَ الدُّنْيَا، وَ مَثَلِيْ وَ مَثَلُ الدُّنْيَا اِلَّا كَمَثَلِ رَاكِبٍ نَزَلَ تَحْتَ شَجَرَةٍ ثُمَّ سَارَ وَ تَرَكَهَا. الطبراني في المعجم الكبير 10 : 162 رقم 10327"],["p","Dari ‘Abdullah bin Mas’ud, ia berkata : Saya datang kepada Rasulullah SAW pada waktu itu beliau sedang berada di dalam kamar yang seperti dapur. Beliau tidur di atas tikar yang sungguh tikar itu membekas pada lambungnya, lalu aku menangis. Beliau bertanya, “Apa yang menyebabkan kamu menangis, hai ‘Abdullah ?”. Aku menjawab, “Ya Rasulullah, raja Kisra (Persi) dan Kaisar (Romawi) mereka itu tidur di atas sutra bercampur bulu, sutra tebal dan sutra tipis. Sedangkan engkau tidur di atas tikar ini dan membekas pada lambungmu”. Beliau bersabda, “Jangan menangis hai ‘Abdullah, karena bagi mereka itu dunia dan bagi kita akhirat. Apalah urusanku dengan dunia, perumpamaanku dengan dunia adalah seperti perumpamaan seorang musafir yang menunggang kendaraan lalu singgah di bawah pohon, kemudian dia meneruskan perjalanan dan meninggalkannya”.[HR. Thabaraaniy di dalam Al Mu’jamul Kabir juz 10, hal. 162, no. 10327]"],["a","عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ قَالَ: حَدَّثَنِيْ عُمَرُ بْنُ الْخَطَّابِ، قَالَ: دَخَلْتُ عَلَى رَسُوْلِ اللهِ ﷺ وَ هُوَ عَلَى حَصِيْرٍ، قَالَ: فَجَلَسْتُ، فَاِذَا عَلَيْهِ اِزَارُهُ وَ لَيْسَ عَلَيْهِ غَيْرُهُ وَ اِذَا الْحَصِيْرُ قَدْ اَثَّرَ فِيْ جَنْبِهِ. وَ اِذَا اَنَا بِقَبْضَةٍ مِنْ شَعِيْرٍ نَحْوَ الصَّاعِ وَ قَرَظٍ فِيْ نَاحِيَةٍ فِى الْغُرْفَةِ، وَ اِذَا اِهَابٌ مُعَلَّقٌ فَابْتَدَرَتْ عَيْنَايَ. فَقَالَ: مَا يُبْكِيْكَ يَا ابْنَ الْخَطَّابِ؟ فَقَالَ: يَا نَبِيَّ اللهِ، وَ مَا لِيَ لَا أَبْكِى، وَ هٰذَا الْحَصِيْرُ قَدْ اَثَّرَ فِى جَنْبِكَ، وَ هٰذِهِ خِزَانَتُكَ لَا اَرَى فِيْهَا اِلَّا مَا اَرَى، وَ ذَاكَ كِسْرَى وَ قَيْصَرُ فِى الثِّمَارِ وَ الْاَنْهَارِ وَ اَنْتَ نَبِيُّ اللهِ وَ صَفْوَتُهُ وَ هٰذِهِ خِزَانَتُكَ. قَالَ: يَا ابْنَ الْخَطَّابِ اَمَا تَرْضَى اَنْ تَكُوْنَ لَنَا الْآخِرَةُ وَ لَهُمُ الدُّنْيَا؟ قُلْتُ : بَلَى. ابن ماجه 2 : 1390 رقم 4153"],["p","Dari ‘Abdullah bin ‘Abbas, ia berkata, ‘Umar bin Khaththab menceritakan kepadaku, ia berkara, “Aku datang kepada Rasulullah SAW pada waktu itu beliau di atas tikar”. ‘Umar melanjutkan ceritanya, “Lalu aku duduk. Pada waktu itu beliau hanya mengenakan izaar, dan tikar tersebut membekas pada lambung beliau. Pada waktu itu aku memperhatikan seikat sya’ir (gandum) kira-kira satu sha’ dan qaradh (daun untuk menyamak kulit) berada di bagian kamarnya, di situ ada kulit yang tergantung yang belum disamak, maka kedua mataku meneteskan air mata”. Beliau bertanya, “Apa yang membuat kamu menangis wahai Ibnul Khaththab ?”. (‘Umar) menjawab, “Wahai Nabiyallah, bagaimana aku tidak menangis, tikar ini telah membekas pada punggung engkau. Dan ini simpanan engkau aku tidak melihat barang-barang kecuali apa yang kulihat, sedangkan di sana raja Kisra dan Kaisar mempunyai kebun-kebun yang berbuah dan sungai-sungai, padahal engkau adalah Nabiyullah dan pilihan-Nya, dan hanya ini simpanan engkau”. Rasulullah SAW bersabda, “Hai Ibnul Khaththab, apakah kamu tidak puas bahwa kita mendapatkan akhirat dan mereka mendapatkan dunia ? Aku menjawab:”ya”. [HR. Ibnu Majah juz 2, hal. 1390, no. 4153]"],["h","7. Sederhananya rumah Nabi SAW"],["a","عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ ﷺ اَنَّهَا قَالَتْ: كُنْتُ اَنَامُ بَيْنَ يَدَيْ رَسُوْلِ اللهِ ﷺ وَرِجْلَايَ فِيْ قِبْلَتِهِ، فَاِذَا سَجَدَ غَمَزَنِيْ فَقَبَضْتُ رِجْلَيَّ، فَاِذَا قَامَ بَسَطْتُهُمَا. قَالَتْ: وَالْبُيُوْتُ يَوْمَئِذٍ لَيْسَ فِيْهَا مَصَابِيْحُ. البخارى 1 : 101"],["p","Dari 'Aisyah isteri Nabi SAW, ia berkata, \"Dahulu aku pernah tidur di depan Rasulullah SAW sedangkan kedua kakiku di arah Qiblat (shalatnya). Apabila beliau sujud, beliau menyentuh kakiku, lalu aku tarik kedua kakiku. Apabila beliau berdiri, aku kembali meluruskan kakiku.\" 'Aisyah berkata, \"Pada saat itu di rumah-rumah belum ada lampu penerang.\"[HR. Bukhari juz 1, hal. 101]"],["h","8. Nabi SAW tidak meninggalkan warisan berupa harta"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَقَدْ تُوُفِّيَ النَّبِيُّ ﷺ وَ مَا فِيْ رَفِّيْ مِنْ شَيْءٍ يَأْكُلُهُ ذُوْ كَبِدٍ اِلَّا شَطْرُ شَعِيْرٍ فِيْ رَفٍّ لِيْ فَاَكَلْتُ مِنْهُ حَتَّى طَالَ عَلَيَّ فَكِلْتُهُ فَفَنِيَ. البخارى 7 : 179"],["p","Dari ‘Aisyah RA, ia berkata, “Sungguh Nabi SAW wafat, sedangkan di rak saya tidak ada makanan yang bisa dimakan oleh makhluq yang bernyawa, kecuali sebagian gandum yang berada di rak saya, lalu saya memakannya sampai waktu yang lama (karena berkah), saya mengambilnya sehingga habis”. [HR. Bukhari juz 7, hal. 179]"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تُوُفِّيَ النَّبِيُّ ﷺ وَ دِرْعُهُ مَرْهُوْنَةٌ عِنْدَ يَهُوْدِيٍّ بِثَلاَثِيْنَ يَعْنِى صَاعًا مِنْ شَعِيْرٍ. البخارى 5 : 145"],["p","Dari ‘Aisyah RA, ia berkata, “Nabi SAW wafat, sedangkan baju besi beliau masih digadaikan pada orang Yahudi dengan tiga puluh sha’ gandum”. [HR. Bukhari juz 5, hal 145]"],["a","عَنْ عَمْرِو بْنِ الْحَارِثِ قَالَ: مَا تَرَكَ رَسُوْلُ اللهِ ﷺ دِيْنَارًا وَ لَا دِرْهَمًا وَ لَا عَبْدًا وَ لَا اَمَةً اِلَّا بَغْلَتَهُ الْبَيْضَاءَ الَّتِيْ كَانَ يَرْكَبُهَا وَ سِلَاحَهُ وَ اَرْضًا جَعَلَهَا لِابْنِ السَّبِيْلِ صَدَقَةً. البخارى 5 : 144"],["p","Dari ‘Amr bin Al-Harits, ia berkata, “Rasulullah SAW ketika wafat, beliau tidak meninggalkan dinar dan dirham. Tidak pula budak laki-laki maupun perempuan, melainkan bighal putih yang biasa beliau naiki dan senjata, serta sebidang tanah yang beliau sedekahkan untuk Ibnu Sabil”. [HR. Bukhari juz 5, hal 144]"],["a","عَنْ عَائِشَةَ اَنَّ فَاطِمَةَ وَالْعَبَّاسَ عَلَيْهِمَا السَّلَامُ اَتَيَا اَبَا بَكْرٍ يَلْتَمِسَانِ مِيْرَاثَهُمَا مِنْ رَسُوْلِ اللهِ ﷺ، وَهُمَا حِيْنَئِذٍ يَطْلُبَانِ اَرْضَيْهِمَا مِنْ فَدَكَ وَسَهْمَهُمَا مِنْ خَيْبَرَ. فَقَالَ لَهُمَا اَبُوْ بَكْرٍ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: لَا نُوْرَثُ، مَا تَرَكْنَا صَدَقَةٌ، اِنَّمَا يَأْكُلُ آلُ مُحَمَّدٍ مِنْ هٰذَا الْمَالِ. قَالَ اَبُوْ بَكْرٍ: وَاللهِ، لَا اَدَعُ اَمْرًا رَأَيْتُ رَسُوْلَ اللهِ ﷺ يَصْنَعُهُ فِيْهِ اِلَّا صَنَعْتُهُ. قَالَ: فَهَجَرَتْهُ فَاطِمَةُ فَلَمْ تُكَلِّمْهُ حَتَّى مَاتَتْ. البخارى 8 : 3"],["p","Dari 'Aisyah bahwasanya Fathimah dan ‘Abbas AS datang kepada Abu Bakar untuk meminta bagian warisan keduanya dari Rasulullah SAW, ketika itu keduanya meminta tanah bagiannya di Fadak, dan bagiannya di Khaibar. Maka Abu Bakar menjawab; 'Aku pernah mendengar Rasulullah SAW bersabda: \"Kami tidak diwarisi, dan harta yang kami tinggalkan sebagai sedekah, dan keluarga Muhammad hanyalah makan dari harta ini.\" Lanjut Abu Bakar; 'Demi Allah, aku tidak akan meninggalkan suatu urusan yang aku pernah melihat Rasulullah SAW memperbuatnya, melainkan aku juga memperbuatnya.” 'Urwah berkata:” Semenjak itu Fathimah menjauhi Abu Bakar dan tidak pernah mengajaknya bicara hingga wafat.” [HR. Bukhari juz 8, hal. 3]"],["a","عَنْ عَائِشَةَ اَنَّ النَّبِيَّ ﷺ قَالَ: لَا نُوْرَثُ، مَا تَرَكْنَا صَدَقَةٌ. البخارى 8 : 3"],["p","Dari ‘Aisyah bahwasanya Nabi SAW bersabda: \"Kami tidak diwarisi, dan harta yang kami tinggalkan sebagai sedekah.\" [HR. Bukhari juz 8, hal. 3]"],["p","--oo0oo--"]],"c20220807_1293":[["p","Ahad, 7 Agustus 2022/9 Muharram 1444 Brosur No. : 2088/2128/IA"],["p","Kewajiban menutup ‘aurat, larangan memandang, bersentuhan dengan lawan jenis"],["p","‘Aurat merupakan batasan atau bagian tubuh seseorang yang tidak boleh dipamerkan atau terlihat oleh orang yang tidak mahram, baik laki-laki maupun perempuan. Umumnya, kebanyakan orang lebih fokus pada batasan ‘aurat perempuan, padahal laki-laki juga memiliki batasan ‘aurat yang perlu diperhatikan."],["p","Menutup ‘aurat merupakan kewajiban yang harus dilaksanakan oleh setiap muslim, Allah telah memberi perintah kepada anak Adam atau manusia untuk menutup ‘aurat, menutup ‘aurat dapat membedakan manusia dari makhluk lain."],["a","يٰبَنِيْٓ اٰدَمَ قَدْ اَنْزَلْنَا عَلَيْكُمْ لِبَاسًا يُّوَارِيْ سَوْاٰتِكُمْ وَرِيْشًاۗ وَلِبَاسُ التَّقْوٰى ذٰلِكَ خَيْرٌۗ ذٰلِكَ مِنْ اٰيٰتِ اللّٰهِ لَعَلَّهُمْ يَذَّكَّرُوْنَ. الاعراف : 26"],["p","Hai anak Adam, sesungguhnya Kami telah menurunkan kepadamu pakaian untuk menutupi ‘auratmu dan pakaian indah untuk perhiasan. Dan pakaian takwa itulah yang paling baik. Yang demikian itu adalah sebahagian dari tanda-tanda kekuasaan Allah, mudah-mudahan mereka selalu ingat. [QS. Al A’raaf : 26]"],["p","Menutup ‘aurat dapat menjadi identitas atau pembeda seorang muslim dengan non muslim. Menutup ‘aurat juga berfungsi untuk melindungi diri seorang perempuan dari fitnah maupun bahaya lain, seperti kejahatan. Zaman sekarang banyak terjadi kejahatan dan target korbannya adalah perempuan. Dengan memakai pakaian tertutup, perempuan dapat terhindar dari kejahatan yang tidak diinginkan tersebut. Hal ini dijelaskan oleh Allah SWT pada surat Al Ahzaab ayat 59."],["a","يٰٓاَيُّهَا النَّبِيُّ قُلْ لِّاَزْوَاجِكَ وَبَنٰتِكَ وَنِسَاۤءِ الْمُؤْمِنِيْنَ يُدْنِيْنَ عَلَيْهِنَّ مِنْ جَلَابِيْبِهِنَّۗ ذٰلِكَ اَدْنٰىٓ اَنْ يُّعْرَفْنَ فَلَا يُؤْذَيْنَۗ وَكَانَ اللّٰهُ غَفُوْرًا رَّحِيْمًا. الاحزاب : 59"],["p","Hai Nabi katakanlah kepada istri-istrimu, anak-anak perempuanmu dan istri-istri orang mukmin: \"Hendaklah mereka mengulurkan jilbabnya ke seluruh tubuh mereka\". Yang demikian itu supaya mereka lebih mudah untuk dikenal, karena itu mereka tidak diganggu. Dan Allah adalah Maha Pengampun lagi Maha Penyayang. [QS. Al Ahzaab : 59]"],["p","‘Aurat wanita di dalam shalat"],["a","عَنْ عَائِشَةَ عَنِ النَّبِيِّ ﷺ اَنَّهُ قَالَ: لَا يَقْبَلُ اللهُ صَلَاةَ حَائِضٍ اِلَّا بِخِمَارٍ. ابو داود 1: 173، رقم: 641"],["p","Dari ‘Aisyah dari Nabi SAW, beliau bersabda, “Allah tidak akan menerima shalat wanita yang sudah haidl melainkan dengan kudung kepala”. [HR. Abu Dawud juz 1, hal. 173, no. 641]"],["a","عَنْ عَبْدِ اللهِ بْنِ اَبِيْ قَتَادَةَ عَنْ اَبِيْهِ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا يَقْبَلُ اللهُ مِنِ امْرَأَةٍ صَلَاةً حَتَّى تُوَارِيَ زِيْنَتَهَا وَ لَا مِنْ جَارِيَةٍ بَلَغَتِ الْحَيْضَ حَتَّى تَخْتَمِرَ. الطبرانى في المعجم الاوسط 8: 294، رقم: 7602"],["p","Dari ‘Abdullah bin Abu Qatadah, dari ayahnya, ia berkata: “Rasulullah SAW bersabda, “Allah tidak akan menerima shalat dari seorang wanita sehingga ia menutup perhiasannya, dan tidak (diterima shalat) dari seorang wanita yang sudah baligh sehingga ia berkerudung. [HR. Ath-Thabarani, dalam Al Mu’jamul Ausath juz 8, hal. 294, no. 7602]"],["a","عَنِ ابْنِ عُمَرَ اَنَّ نِسَاءَ النَّبِيِّ ﷺ سَأَلْنَهُ عَنِ الذَّيْلِ، فَقَالَ: اِجْعَلْنَهُ شِبْرًا. فَقُلْنَ: اِنَّ شِبْرًا لَا يَسْتُرُ مِنْ عَوْرَةٍ. فَقَالَ: اِجْعَلْنَهُ ذِرَاعًا. احمد 2: 299، رقم: 5641"],["p","Dari Ibnu ‘Umar, bahwasanya istri-istri Nabi SAW bertanya kepada beliau tentang pinggir kain, maka Rasulullah menjawab, “Panjangkanlah sejengkal”. Mereka berkata, “Sejengkal tidak dapat menutup ‘aurat”. Maka sabda beliau, “Jadikanlah sehasta”. [HR. Ahmad juz 2, hal. 399, no. 5641]"],["a","عَنْ اُمِّ سَلَمَةَ اَنَّهَا سَأَلَتِ النَّبِيَّ ﷺ: اَ تُصَلِّى الْمَرْأَةُ فِى دِرْعٍ وَ خِمَارٍ وَ لَيْسَ عَلَيْهَا اِزَارٌ؟ قَالَ: اِذَا كَانَتِ الدِّرْعُ سَابِغًا يُغَطِّى ظُهُوْرَ قَدَمَيْهَا. ابو داود 1: 173، رقم: 640"],["p","Dari Ummu Salamah, bahwasanya ia bertanya kepada Nabi SAW: “Bolehkah wanita shalat dengan memakai baju panjang dan kerudung, tetapi tidak memakai izar (kain bawahan) ?” Jawab beliau, “Boleh, kalau baju itu panjang hingga menutup bagian luar kedua tapak kakinya”. [HR. Abu Dawud juz 1, hal. 173, no. 640]"],["p","‘Aurat wanita di dalam rumah"],["p","Firman Allah SWT:"],["a","وَقُلْ لِّلْمُؤْمِنٰتِ يَغْضُضْنَ مِنْ اَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوْجَهُنَّ وَلَا يُبْدِيْنَ زِيْنَتَهُنَّ اِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلٰى جُيُوْبِهِنَّۖ وَلَا يُبْدِيْنَ زِيْنَتَهُنَّ اِلَّا لِبُعُوْلَتِهِنَّ اَوْ اٰبَاۤىِٕهِنَّ اَوْ اٰبَاۤءِ بُعُوْلَتِهِنَّ اَوْ اَبْنَاۤىِٕهِنَّ اَوْ اَبْنَاۤءِ بُعُوْلَتِهِنَّ اَوْ اِخْوَانِهِنَّ اَوْ بَنِيْٓ اِخْوَانِهِنَّ اَوْ بَنِيْٓ اَخَوَاتِهِنَّ اَوْ نِسَاۤىِٕهِنَّ اَوْ مَا مَلَكَتْ اَيْمَانُهُنَّ اَوِ التَّابِعِيْنَ غَيْرِ اُولِى الْاِرْبَةِ مِنَ الرِّجَالِ اَوِ الطِّفْلِ الَّذِيْنَ لَمْ يَظْهَرُوْا عَلٰى عَوْرٰتِ النِّسَاۤءِ ۖ وَلَا يَضْرِبْنَ بِاَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِيْنَ مِنْ زِيْنَتِهِنَّۗ وَتُوْبُوْٓا اِلَى اللّٰهِ جَمِيْعًا اَيُّهَ الْمُؤْمِنُوْنَ لَعَلَّكُمْ تُفْلِحُوْنَ. النور : 31"],["p","Katakanlah kepada wanita yang beriman: \"Hendaklah mereka menahan pandangannya, dan memelihara kemaluannya, dan janganlah mereka menampakkan perhiasannya, kecuali yang (biasa) nampak daripadanya. Dan hendaklah mereka menutupkan kain kudung ke dadanya, dan janganlah menampakkan perhiasannya, kecuali kepada suami mereka, atau ayah mereka, atau ayah suami mereka, atau putra-putra mereka, atau putra-putra suami mereka, atau saudara-saudara laki-laki mereka, atau putra-putra saudara laki-laki mereka, atau putra-putra saudara perempuan mereka, atau wanita-wanita Islam, atau budak-budak yang mereka miliki, atau pelayan-pelayan laki-laki yang tidak mempunyai keinginan (terhadap wanita) atau anak-anak yang belum mengerti tentang ‘aurat wanita. Dan janganlah mereka memukulkan kakinya agar diketahui perhiasan yang mereka sembunyikan. Dan bertaubatlah kamu sekalian kepada Allah, hai orang-orang yang beriman supaya kamu beruntung. [QS. An Nuur : 31]"],["a","عَنْ اَنَسٍ اَنَّ النَّبِيَّ ﷺ اَتَى فَاطِمَةَ بِعَبْدٍ قَدْ وَهَبَهُ لَهَا. قَالَ: وَ عَلَى فَاطِمَةَ رَضِيَ اللهُ عَنْهَا ثَوْبٌ اِذَا قَنَّعَتْ بِهِ رَأْسَهَا لَمْ يَبْلُغْ رِجْلَيْهَا وَ اِذَا غَطَّتْ بِهِ رِجْلَيْهَا لَمْ يَبْلُغْ رَأْسَهَا. فَلَمَّا رَأَى النَّبِيُّ ﷺ مَا تَلْقَى، قَالَ: اِنَّهُ لَيْسَ عَلَيْكِ بَأْسٌ، اِنَّمَا هُوَ اَبُوْكِ وَ غُلَامُكِ. ابو داود 4: 62، 4106"],["p","Dari Anas, bahwasanya Nabi SAW pernah memberi kepada Fathimah seorang hamba laki-laki, sedang Fathimah berpakaian yang apabila ia tutup kepalanya, terbuka kakinya, dan apabila ia tutup kakinya terbuka kepalanya. Tatkala melihat keadaan itu, Nabi SAW bersabda, “Tidak mengapa bagimu, karena dia itu seperti bapakmu atau anak laki-lakimu”. [HR. Abu Dawud juz 4, hal. 62, no. 4106]"],["p","‘Aurat wanita di luar rumah"],["a","يٰٓاَيُّهَا النَّبِيُّ قُلْ لِّاَزْوَاجِكَ وَبَنٰتِكَ وَنِسَاۤءِ الْمُؤْمِنِيْنَ يُدْنِيْنَ عَلَيْهِنَّ مِنْ جَلَابِيْبِهِنَّۗ ذٰلِكَ اَدْنٰىٓ اَنْ يُّعْرَفْنَ فَلَا يُؤْذَيْنَۗ وَكَانَ اللّٰهُ غَفُوْرًا رَّحِيْمًا.الاحزاب:59"],["p","Hai Nabi katakanlah kepada istri-istrimu, anak-anak perempuanmu dan istri-istri orang mukmin: \"Hendaklah mereka mengulurkan jilbabnya ke seluruh tubuh mereka\". Yang demikian itu supaya mereka lebih mudah untuk dikenal, karena itu mereka tidak diganggu. Dan Allah adalah Maha Pengampun lagi Maha Penyayang. [QS. Al-Ahzaab : 59]"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا اَنَّ اَسْمَاءَ بِنْتَ اَبِيْ بَكْرٍ دَخَلَتْ عَلَى رَسُوْلِ اللهِ ﷺ وَ عَلَيْهَا ثِيَابٌ رِقَاقٌ، فَاَعْرَضَ عَنْهَا رَسُوْلُ اللهِ ﷺ وَ قَالَ: يَا اَسْمَاءُ اِنَّ الْمَرْأَةَ اِذَا بَلَغَتِ الْمَحِيْضَ لَمْ يَصْلُحْ اَنْ يُرَى مِنْهَا اِلَّا هٰذَا وَ هٰذَا. وَ اَشَارَ اِلَى وَجْهِهِ وَ كَفَّيْهِ. ابو داود و قال: هذا مرسل، خالد ابن دريك لم يدرك عائشة. 4: 62، رقم 4104"],["p","Dari ‘Aisyah RA, ia berkata : Sesungguhnya Asma’ binti Abu Bakar datang menghadap Rasulullah SAW dengan berpakaian tipis, maka Rasulullah SAW berpaling dan bersabda, “Hai Asma’ ! Sesungguhnya seorang wanita apabila sudah haidl, tidak boleh terlihat padanya melainkan ini dan ini”, beliau sambil mengisyaratkan pada wajah dan dua tapak tangan beliau. [HR. Abu Dawud, dan ia berkata : Hadits ini mursal, karena Khalid bin Duraik tidak bertemu ‘Aisyah, juz 4, hal. 62, no. 4104]."],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: صِنْفَانِ مِنْ اَهْلِ النَّارِ لَمْ اَرَهُمَا، قَوْمٌ مَعَهُمْ سِيَاطٌ كَاَذْنَابِ الْبَقَرِ يَضْرِبُوْنَ بِهَا النَّاسَ. وَ نِسَاءٌ كَاسِيَاتٌ عَارِيَاتٌ مُمِيْلَاتٌ مَائِلَاتٌ رُءُوْسُهُنَّ كَأَسْنِمَةِ الْبُخْتِ الْمَائِلَةِ، لَا يَدْخُلْنَ الْجَنَّةَ وَ لَا يَجِدْنَ رِيْحَهَا، وَ اِنَّ رِيْحَهَا لَيُوْجَدُ مِنْ مَسِيْرَةِ كَذَا وَ كَذَا. مسلم 4: 2192 رقم 52"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Ada dua golongan orang ahli neraka yang aku belum pernah melihatnya, yaitu kaum (orang-orang) yang memegang cambuk bagaikan ekor sapi yang digunakan untuk memukul orang lain dan orang perempuan yang berpakaian tetapi seperti telanjang, berlenggak-lenggok kepalanya bagaikan punuk unta yang miring. Maka mereka itu tidak akan masuk surga dan tidak akan mencium baunya, padahal bau surga itu sudah tercium dari jarak perjalanan sekian dan sekian (jarak yang sangat jauh)”. [HR. Muslim juz 4, hal. 2192, no. 52]"],["p","Tentang ‘aurat laki-laki"],["p","‘Aurat laki-laki di dalam shalat adalah antara pusar dan lutut, berdasarkan sabda Nabi SAW kepada Jabir bin ‘Abdullah sebagai berikut:"],["a","فَاِنْ كَانَ وَاسِعًا فَالْتَحِفْ بِهِ وَاِنْ كَانَ ضَيِّقًا فَاتَّزِرْ بِهِ. البخارى 1: 95"],["p","Jika kain itu longgar, maka berselimutlah dengannya. Tetapi jika sempit, maka pakailah untuk izar (kain bawahan yang menutup antara pusar dan bawah lutut). [HR. Bukhari juz 1, hal. 95]"],["p","Adapun tentang ‘aurat laki-laki di luar shalat, dalam hal ini ada 2 pendapat :"],["p","Pendapat pertama : antara pusar sampai lutut, berdasar hadits :"],["a","مَا بَيْنَ السُّرَّةِ اِلَى الرُّكْبَةِ عَوْرَةٌ. الطبرانى فى المعجم الاوسط 8: 372، رقم: 7757"],["p","Apa-apa yang antara pusar sampai lutut adalah ‘aurat. [HR. Thabarani dalam Al Mu’jamul Ausath juz 8, hal. 372, no. 7757, dla’if karena dalam sanadnya ada perawi bernama Ashram bin Hausyab]"],["p","Pendapat kedua : paha tidak termasuk ‘aurat, berdasarkan hadits :"],["a","قَالَ اَنَسٌ: اِنَّ النَّبِيَّ ﷺ يَوْمَ خَيْبَرَ حَسَرَ الْاِزَارَ عَنْ فَخِذِهِ حَتَّى اِنِّيْ اَنْظُرُ اِلَى بَيَاضِ فَخِذِ نَبِيِّ اللهِ ﷺ. البخارى 1: 97"],["p","Anas berkata, “Sesungguhnya di hari peperangan Khaibar, Nabi SAW mengangkat kainnya hingga saya dapat melihat paha Nabi Allah SAW yang putih”. [HR. Bukhari juz 1, hal. 97]"],["p","Laki-laki dilarang memandang wanita dan wanita dilarang memandang laki-laki"],["a","قُلْ لِّلْمُؤْمِنِيْنَ يَغُضُّوْا مِنْ اَبْصَارِهِمْ وَيَحْفَظُوْا فُرُوْجَهُمْۗ ذٰلِكَ اَزْكٰى لَهُمْۗ اِنَّ اللّٰهَ خَبِيْرٌۢ بِمَا يَصْنَعُوْنَ. النور : 30"],["p","Katakanlah kepada orang laki-laki yang beriman: \"Hendaklah mereka menahan pandangannya, dan memelihara kemaluannya; yang demikian itu adalah lebih suci bagi mereka, sesungguhnya Allah Maha Mengetahui apa yang mereka perbuat\".[QS. An Nuur : 30]"],["a","وَقُلْ لِّلْمُؤْمِنٰتِ يَغْضُضْنَ مِنْ اَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوْجَهُنَّ وَلَا يُبْدِيْنَ زِيْنَتَهُنَّ اِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلٰى جُيُوْبِهِنَّۖ النور : 31"],["p","Katakanlah kepada wanita yang beriman: \"Hendaklah mereka menahan pandangannya, dan memelihara kemaluannya, dan janganlah mereka menampakkan perhiasannya, kecuali yang (biasa) nampak daripadanya. Dan hendaklah mereka menutupkan kain kudung ke dadanya… [QS. An Nuur : 31]"],["a","عَنْ جَرِيْرِ بْنِ عَبْدِ اللهِ قَالَ: سَأَلْتُ رَسُوْلَ اللهِ ﷺ عَنْ نَظَرِ الْفُجَاءَةِ، فَاَمَرَنِيْ اَنْ اَصْرِفَ بَصَرِيْ. مسلم 3: 1699 رقم 45"],["p","Dari Jarir bin Abdullah, ia berkata : “Saya pernah bertanya kepada Rasulullah SAW tentang melihat (wanita) dengan tidak sengaja, maka beliau menyuruhku agar aku memalingkan pandanganku”. [HR. Muslim juz 3, hal. 1699, no. 45]"],["a","عَنْ جَرِيْرٍ قَالَ: سَأَلْتُ رَسُوْلَ اللهِ ﷺ عَنْ نَطْرَةِ الْفَجْأَةِ، فَقَالَ: اِصْرِفْ بَصَرَكَ. ابو داود: 2: 246، رقم: 2148"],["p","Dari Jarir, ia berkata : Aku bertanya kepada Rasulullah SAW tentang melihat wanita dengan tidak sengaja, maka beliau bersabda, “Palingkanlah pandanganmu”. [HR. Abu Dawud juz 2, hal. 246, no. 2148]"],["a","عَنِ ابْنِ بُرَيْدَةَ عَنْ اَبِيْهِ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ لِعَلِيٍّ: يَا عَلِيُّ، لَا تُتْبِعِ النَّظْرَةَ النَّظْرَةَ، فَاِنَّ لَكَ الْاُوْلَى وَ لَيْسَتْ لَكَ الْاۤخِرَةُ. ابو داود 2: 246، رقم 2149"],["p","Dari Ibnu Buraidah, dari ayahnya, ia berkata : Rasulullah SAW bersabda kepada ‘Ali : “Hai ‘Ali, janganlah engkau iringkan satu pandangan (kepada wanita) dengan satu pandangan, karena yang pertama itu tidak mengapa, tetapi tidak yang kedua”. [HR. Abu Dawud juz 2, hal. 246, no. 2149]"],["a","عَنْ مَعْقِلِ بْنِ يَسَارٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : لَاَنْ يُطْعَنَ فِيْ رَأْسِ اَحَدِكُمْ بِمِخْيَطٍ مِنْ حَدِيْدٍ خَيْرٌ لَهُ مِنْ اَنْ يَمَسَّ امْرَأَةً لَا تَحِلُّ لَهُ. الطبرانى فى المعجم الكبير 20: 212، رقم: 486"],["p","Dari Ma’qil bin Yasaar, ia berkata : Rasulullah SAW bersabda, “Ditikam seorang diantara kalian di kepalanya dengan jarum dari besi adalah lebih baik daripada ia menyentuh seorang wanita yang tidak halal baginya.” [HR. Thabarani dalam Al Mu’jamul Kabir juz 20, hal. 212, no. 486]"],["p","Keterangan :"],["p","Di dalam Al-Qur'an dan hadits, laki-laki dilarang memandang wanita dan sebaliknya, dan kita diperintah supaya menundukkan pandangan. Kalau pandang memandang saja dilarang, sudah tentu berjabat tangan lebih keras lagi larangannya. Dan jika berjabat tangan saja dilarang, otomatis berciuman, berpelukan, berdansa, dan sebagainya tentu lebih dilarang lagi."],["p","--oo0oo--"]],"c20220814_1294":[["p","Ahad, 14 Agustus 2022/16 Muharram 1444 Brosur No.: 2089/2129/IA"],["p","Malu Dalam Islam"],["p","Ajaran Islam menempatkan rasa malu sebagai bagian yang menyusun cabang keimanan seseorang. Malu adalah akhlaq (perangai) yang mendorong seseorang untuk meninggalkan perbuatan-perbuatan yang buruk dan tercela, sehingga mampu menghalangi seseorang dari melakukan dosa dan maksiat serta mencegah sikap melalaikan hak orang lain."],["p","Keutamaan sifat malu"],["h","1. Malu adalah sifat Nabi SAW"],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِيِّ قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ: اَشَدَّ حَيَاءً مِنَ الْعَذْرَاءِ فِيْ خِدْرِهَا. وَ كَانَ اِذَا كَرِهَ شَيْئًا عَرَفْنَاهُ فِيْ وَجْهِهِ. مسلم 4: 1809 رقم 67"],["p","Dari Abu Sa’id Al-Khudriy, ia berkata, “Adalah Rasulullah SAW itu lebih pemalu dari pada gadis dalam pingitan. Dan apabila beliau tidak suka kepada sesuatu, kami dapat mengetahuinya dari wajah beliau”. [HR Muslim juz 4, hal. 1809, no. 67]"],["a","عَنْ اَبِيْ مَسْعُوْدٍ قَالَ: قَالَ النَّبِيُّ ﷺ: اِنَّ مِمَّا اَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْاُوْلَى اِذَا لَمْ تَسْتَحِ فَاصْنَعْ مَا شِئْتَ. البخارى 7 : 100"],["p","Dari Abu Mas’ud, ia berkata : Nabi SAW bersabda, “Sesungguhnya diantara apa-apa yang didapati orang-orang dari perkataan para Nabi dahulu ialah : Apabila kamu sudah tidak malu, maka berbuatlah sekehendakmu”. [HR. Bukhari juz 7, hal. 100]"],["p","2. Malu akan mendatangkan kebaikan."],["p","Sifat malu mendorong pelakunya untuk menghiasi diri dengan perilaku mulia dan menjauhkan diri dari sifat-sifat yang hina. Malu menjadi pengendali bagi seorang muslim untuk senantiasa berada dalam kebaikan dan berpaling dari segala keburukan atau ma’shiyat sebagaimana halnya dengan iman yang senantiasa mendorong seorang mukmin untuk melakukan kebaikan dan meninggalkan kema’shiyatan."],["p","Rasulullah SAW bersabda:"],["a","عَنْ عِمْرَانَ بْنِ حُصَيْنٍ قَالَ: قَالَ النَّبِيُّ ﷺ : اَلْحَيَاءُ لَا يَأْتِى اِلَّا بِخَيْرٍ. فَقَالَ بُشَيْرُ بْنُ كَعْبٍ: مَكْتُوْبٌ فىِ الْحِكْمَةِ اِنَّ مِنَ الْحَيَاءِ وَقَارًا وَ اِنَّ مِنَ الْحَيَاءِ سَكِيْنَةً. فَقَالَ لَهُ عِمْرَانُ: اُحَدِّثُكَ عَنْ رَسْوْلِ اللهِ ﷺ وَ تُحَدِّثُنِيْ عَنْ صَحِيْفَتِكَ. البخارى 7 : 100"],["p","Dari ‘Imran bin Hushain, ia berkata : Nabi SAW bersabda, “Malu itu tidak mendatangkan kecuali kebaikan”. Lalu Busyair bin Ka’ab berkata, “Tercatat di dalam hikmah sesungguhnya dari malu itu ada ketenangan dan sesungguhnya dari malu itu ada ketenteraman”. Kemudian ‘Imran bin Hushain berkata kepadanya, “Aku menceritakan ini kepadamu dari Rasulullah SAW, (mengapa) kamu menceritakan kepadaku dari catatanmu ?”. [HR Bukhari juz 7, hal. 100]."],["a","عَنْ اَنــَسٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَا كَانَ الْـفُحْشُ فِى شَيْءٍ اِلَّا شَانَهُ وَ مَا كَانَ الْحَيَاءُ فِى شَيْءٍ اِلَّا زَانَهُ. الترمذى 3 : 235 رقم 2040 و قال حديث حسن غريب"],["p","Dari Anas, ia berkata : Rasulullah SAW bersabda, “Tidaklah kekejian dan kata-kata kotor itu berada pada sesuatu melainkan akan menjadikannya buruk, dan malu itu tidaklah berada pada sesuatu melainkan akan menjadikannya indah. [HR Tirmidzi juz 3, hal. 235, no. 2040, ia berkata “Hadits Hasan Gharib”]"],["h","3. Malu adalah cabang keimanan"],["p","Rasulullah SAW bersabda:"],["a","عَنْ عَبْدِ اللهِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ النَّبِيُّ ﷺ عَلَى رَجُلٍ وَ هُوَ يُعَاتِبُ اَخَاهُ فِى الْحَيَاءِ. يَقُوْلُ: اِنَّكَ لَتَسْتَحْيِىْ حَتَّى كَاَنَّهَ يَقُوْلُ قَدْ اَضَرَّ بِكَ. فَقَالَ رَسُوْلُ اللهِ ﷺ: دَعْهُ فَاِنَّ الْحَيَاءَ مِنَ الْاِيْمَانِ. البخارى 7 : 100"],["p","Dari ‘Abdullah bin Umar RA, ia berkata : “Nabi SAW pernah melewati seorang laki-laki yang sedang mencaci saudaranya karena dia pemalu. Orang laki-laki itu berkata (kepada saudaranya), “Sungguh kamu itu pemalu sekali, hingga seolah-olah orang laki-laki itu berkata, “Hal itu akan merugikan kamu”. Maka Rasulullah SAW bersabda, “Biarkan saja dia, sesungguhnya malu itu bagian dari iman”. [HR Bukhari juz 7, hal. 100]"],["a","عَنْ اَبِيْ هُرَيـْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اَلْاِيْمَانُ بِضْعٌ وَسَبْعُوْنَ اَوْ بِضْعٌ وَسِتُّوْنَ شُعْبَةً، فَاَفْضَلُهَا قَوْلُ لَا اِلٰهَ اِلَّا اللهُ، وَاَدْنَاهَا اِمَاطَةُ الْاَذَى عَنِ الطَّرِيْقِ، وَالْحَيَاءُ شُعْبَةٌ مِنَ الْاِيْمَانِ. مسلم 1: 63 رقم 58"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Iman itu ada tujuh puluh cabang lebih atau enam puluh cabang lebih. Yang paling utama ialah ucapan Laa ilaaha illallooh (Tidak ada Tuhan selain Allah), dan yang paling rendah ialah menyingkirkan gangguan di jalan, dan malu adalah salah satu cabang dari iman\". [HR. Muslim juz 1, hal. 63, no. 58]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اَلْاِيْمَانُ بِضْعٌ وَسِتُّوْنَ اَوْ سَبْعُوْنَ بَابًا، اَدْنَاهَا اِمَاطَةُ الْاَذَى عَنِ الطَّرِيْقِ، وَاَرْفَعُهَا قَوْلُ لَا اِلٰهَ اِلَّا اللهُ، وَالْحَيَاءُ شُعْبَةٌ مِنَ الْاِيْمَانِ. ابن ماجه 1: 22، رقم: 57"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Iman itu ada enam puluh cabang lebih atau tujuh puluh cabang lebih. Yang paling rendah adalah menyingkirkan gangguan dari jalan, dan yang paling tinggi ialah ucapan Laa ilaaha illallooh (Tidak ada Tuhan selain Allah), dan malu adalah salah satu cabang dari iman \". [HR. Ibnu Majah juz 1, hal. 22, no. 57]"],["a","عَنْ اَبِيْ اُمَامَةَ عَنِ النَّبِيِّ ﷺ قَالَ: اَلْحَيَاءُ وَ الْعِيُّ شُعْبَتَانِ مِنَ الْاِيْمَانِ. وَ الْبَذَاءُ وَ الْبَيَانُ شُعْبَتَانِ مِنَ النِّفَاقِ. الترمذى و قال هذا حديث حسن غريب"],["p","Dari Abu Umamah, dari Nabi SAW, beliau bersabda, “Malu dan sedikit bicara itu dua cabang dari iman, sedang perkataan kotor dan banyak bicara itu dua cabang dari kemunafiqan”. [HR Tirmidzi, ia berkata, “Ini hadits hasan gharib”, juz 3, hal. 253, no. 2096]"],["p","4. Allah SWT cinta kepada orang-orang yang malu."],["p","Rasulullah SAW bersabda:"],["a","عَنْ عَطَاءٍ عَنْ يَعْلَى اَنَّ رَسُوْلَ اللهِ ﷺ رَاَى رَجُلًا يَغْتَسِلُ بِالْبَرَازِ. فَصَعِدَ الْمِنْبَرَ فَحَمِدَ اللهَ وَاَثْنَى عَلَيْهِ وَقَالَ: اِنَّ اللهَ عَزَّ وَجَلَّ حَلِيْمٌ حَيِيٌّ سِتِّيْرٌ يُحِبُّ الْحَيَاءَ وَالسَّتْرَ، فَاِذَا اغْتَسَلَ اَحَدُكُمْ فَلْيَسْتَتِرْ . النسائى 1 : 100"],["p","Dari 'Atha' dari Ya'la bahwa Rasulullah SAW melihat ada seorang laki-laki mandi di tempat terbuka. Kemudian beliau naik mimbar lalu memuji Allah dan menyanjung-Nya, kemudian bersabda: \"Sesungguhnya Allah Azza wa Jalla Maha Penyantun, Maha Malu, dan Maha Tertutup. Allah cinta terhadap rasa malu dan tertutup, maka apabila salah seorang diantara kalian mandi, hendaklah memasang penutup.\" [ HR. Nasaaiy Juz 1, hal. 100]"],["p","5. Malu adalah akhlaq Islam."],["a","عَنْ زَيْدِ بْنِ طَلْحَةَ بْنِ رُكَانَةَ يَرْفَعُهُ اِلىَ النَّبِيَّ ﷺ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لِكُلّ دِيْنٍ خُلُقٌ. وَ خُلُقُ الْاِسْلَامِ اَلْحَيَاءُ. مالك فى الموطأ 2 : 905 رقم 9"],["p","Dari Zaid bin Thalhah bin Rukanah, ia mengatakannya dari Nabi SAW, Rasulullah SAW bersabda, “Bagi tiap-tiap agama itu ada akhlaqnya, dan akhlaq Islam adalah malu”. [HR Maalik, di dalam Al Muwaththa’ juz 2, hal. 905, no. 9, hadits ini diperselisihkan tentang marfu’nya, kebanyakan perawi meriwayatkan dari Maalik secara mursal]"],["a","عَنْ اَنَسٍ قَالَ : قَالَ رَسُوْلُ اللهِ ﷺ : اِنَّ لِكُلِّ دِيْنٍ خُلُقًا، وَ خُلُقُ الْاِسْلَامِ اَلْحَيَاءُ. ابن ماجه 2 : 1399 رقم 4181"],["p","Dari Anas, ia berkata, Rasulullah SAW bersabda: “Sesungguhnya bagi tiap tiap agama ada akhlaqnya, dan akhlaq Islam adalah malu.” [HR Ibnu Majah Juz 2, hal 1399, no. 4181, dlo’if karena dalam isnadnya ada perawi bernama Mu’awiyah bin Yahya Ash Shodafiy]"],["p","6. Rasa malu mencegah dari melakukan perbuatan ma’shiyat."],["p","Ada salah seorang shahabat yang mengecam saudaranya dalam masalah malu, dan ia berkata kepadanya, “Sungguh, malu telah merugikanmu.” Kemudian Rasulullah SAW bersabda: “Biarkanlah ia, karena sesungguhnya malu itu bagian dari iman."],["a","عَنْ عَبْدِ اللهِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ النَّبِيُّ ﷺ عَلَى رَجُلٍ وَ هُوَ يُعَاتِبُ اَخَاهُ فِى الْحَيَاءِ. يَقُوْلُ: اِنَّكَ لَتَسْتَحْيِىْ حَتَّى كَاَنَّهَ يَقُوْلُ قَدْ اَضَرَّ بِكَ. فَقَالَ رَسُوْلُ اللهِ ﷺ: دَعْهُ فَاِنَّ الْحَيَاءَ مِنَ الْاِيْمَانِ. البخارى 7 : 100"],["p","Dari ‘Abdullah bin Umar RA, ia berkata : “Nabi SAW pernah melewati seorang laki-laki yang sedang mencaci saudaranya karena dia pemalu. Orang laki-laki itu berkata (kepada saudaranya), “Sungguh kamu itu pemalu sekali, hingga seolah-olah orang laki-laki itu berkata, “Hal itu akan merugikan kamu”. Maka Rasulullah SAW bersabda, “Biarkan saja dia, sesungguhnya malu itu bagian dari iman”. [HR Bukhari juz 7, hal. 100]"],["a","عَنْ عَبْدِ اللهِ بْنِ مَسْعُوْدٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اِسْتَحْيُوْا مِنَ اللهِ حَقَّ الْحَيَاءِ، قُلْنَا: يَا نَبِيَّ اللهِ اِنَّا لَنَسْتَحْيِى وَ الْحَمْدُ لِلّٰهِ. قَالَ: لَيْسَ ذَاكَ وَ لٰكِنْ اَلْاِسْتِحْيَاءُ مِنَ اللهِ حَقَّ الْحَيَاءِ اَنْ تَحْفَظَ الرَّأْسَ وَ مَا وَعَى، وَ تَحْفَظَ الْبَطْنَ وَ مَا حَوَى، وَ تَتَذَكَّرَ الْمَوْتَ وَ الْبِلَى، وَ مَنْ اَرَادَ الْآخِرَةَ تَرَكَ زِيْنَةَ الدُّنْيَا، فَمَنْ فَعَلَ ذٰلِكَ فَقَدِ اسْتَحْيَى يَعْنِى مِنَ اللهِ حَقَّ الْحَيَاءِ. الترمذى 4 : 53 رقم 2575"],["p","Dari ‘Abdullah bin Mas’ud, ia berkata : Rasulullah SAW bersabda, “Malulah kalian kepada Allah dengan sebenar-benar malu”. Kami berkata, “Wahai Nabi Allah, sesungguhnya kami malu, Alhamdulillah (segala puji bagi Allah)”. Rasulullah SAW bersabda, “Bukan begitu, tetapi malu kepada Allah dengan sebenar-benar malu itu ialah kamu menjaga kepala dan apa yang ada di dalamnya, kamu menjaga perut dengan segala isinya, dan hendaklah kamu mengingat mati dan kehancuran, dan orang yang menghendaki akhirat dengan meninggalkan kemewahan dunia, barangsiapa yang berbuat demikian, maka sungguh ia telah malu yakni kepada Allah dengan sebenar-benar malu”. [HR Tirmidzi juz 4, hal. 53, no. 2575]"],["p","7. Malu senantiasa seiring dengan iman, bila salah satunya tercabut hilanglah yang lainnya."],["a","عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ ﷺ: اَلْحَيَاءُ وَ الْاِيْمَانُ قَرَنَا جَمِيْعًا. فَاِذَا رُفِعَ اَحَدُهُمَا رُفِعَ الْآخَرُ. الحاكم فى المستدرك 1 : 73 رقم 58"],["p","Dari Ibnu ‘Umar RA, ia berkata : Rasulullah SAW bersabda, “Malu dan iman itu selalu bersama, maka apabila hilang salah satunya hilang pula yang lain”. [HR. Hakim, dalam Al-Mustadrak juz 1, hal. 73, no. 58]"],["p","8. Malu akan mengantarkan seseorang ke Surga."],["p","Rasulullah SAW bersabda:"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اَلْحَيَاءُ مِنَ الْاِيْمَانِ وَ الْاِيْمَانُ فِى الْجَنَّةِ. وَ الْبَذَاءُ مِنَ الْجَفَاءِ وَ الْجَفَاءُ فِى النَّارِ. الترمذى 3 : 247 رقم 2077 و قال هذا حديث حسن صحيح،"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Malu itu sebagian dari iman, dan iman itu di surga. Perkataan kotor itu termasuk perangai yang kasar, dan perangai yang kasar itu di neraka”. [HR Tirmidzi juz 3, hal. 247, no. 2077, ia berkata, “Ini hadits hasan shahih”]"],["p","--oo0oo--"]],"c20220821_1295":[["p","Ahad, 21 Agustus 2022/23 Muharram 1444 Brosur No.: 2090/2130/IA"],["h","SHABAR DAN TAWAKKAL ADALAH SOLUSI DALAM MENGHADAPI UJIAN DAN COBAAN (1)"],["p","Shabar termasuk akhlaq mahmudah yang melekat pada diri orang mukmin. Sebagai orang yang beriman kepada Allah, kita diperintahkan untuk senantiasa bershabar dan bertawakkal selama menjalani ujian-ujian yang diberikan oleh Allah, karena dengan keshabaran dan tawakkal seluruh ujian atau cobaan dan mushibah tersebut bisa dilalui dengan baik, membawa kebaikan, keberkahan, kemuliaan serta keberuntungan. Pada dasarnya Allah akan memberi ujian dan cobaan di setiap hamba-Nya sesuai porsinya masing-masing. Ujian dan cobaan yang diberikan oleh Allah pada setiap manusia berbeda-beda."],["p","Manusia harus berani menghadapi kesulitan dan tetap tabah dalam menghadapi cobaan. Orang yang bershabar mencerminkan nilai keimanan yang kuat. Kedudukan shabar dalam iman bagaikan kepala pada jasad, dan tidak ada keimanan tanpa shabar sebagaimana jasad tidak akan berfungsi tanpa kepala. Keshabaran tidaklah muncul dengan sendirinya, tetapi ia harus diusahakan dan dibiasakan agar menjadi sifat utama pada diri kita. Di sinilah dibutuhkan pengorbanan melawan keinginan hati dan perjuangan menahan hawa nafsu."],["p","Sementara itu, tawakkal merupakan pelengkap sejati sifat shabar. Tawakkal merupakan kerja hati memasrahkan seluruh ujian dan cobaan kepada kehendak-Nya. Tawakkal berkaitan erat dengan keridlaan kita menjadikan Allah sebagai pelindung dan penolong dalam kehidupan. Kehadiran tawakkal dalam diri akan menghadirkan kemudahan dalam mengatasi persoalan, karena kita benar-benar mengharap pertolongan dan kemudahan hanya dari Allah SWT."],["p","Allah SWT memberikan solusi kepada hamba-hambaNya dalam menghadapi ujian dan cobaan dengan firmanNYa:"],["a","وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِّنَ الْخَوْفِ وَالْجُوْعِ وَنَقْصٍ مِّنَ الْاَمْوَالِ وَالْاَنْفُسِ وَالثَّمَرٰتِۗ وَبَشِّرِ الصّٰبِرِيْنَ(155)اَلَّذِيْنَ اِذَآ اَصَابَتْهُمْ مُّصِيْبَةٌ ۗ قَالُوْٓا اِنَّا لِلّٰهِ وَاِنَّآ اِلَيْهِ رٰجِعُوْنَۗ (156 )اُولٰۤىِٕكَ عَلَيْهِمْ صَلَوٰتٌ مِّنْ رَّبِّهِمْ وَرَحْمَةٌ ۗ وَاُولٰۤىِٕكَ هُمُ الْمُهْتَدُوْنَ(157) . البقرة :155- 157"],["p","Dan sungguh akan Kami berikan cobaan kepadamu, dengan sedikit ketakutan, kelaparan, kekurangan harta, jiwa dan buah-buahan. Dan berikanlah berita gembira kepada orang-orang yang shabar,(155)"],["p","(yaitu) orang-orang yang apabila ditimpa mushibah, mereka mengucapkan, \"Innaa lillaahi wa innaa ilaihi raaji`uun\" (156)"],["p","Mereka itulah yang mendapat keberkatan yang sempurna dan rahmat dari Tuhan mereka, dan mereka itulah orang-orang yang mendapat petunjuk. (157). [Q.S Al Baqarah: 155]"],["p","Allah mengabadikan dalam Al-Qur’an tentang kisah keshabaran dan tawakkal Nabi Ayyub AS dalam menghadapi ujian dan cobaan agar dijadikan pelajaran bagi orang-orang yang datang kemudian."],["p","Allah SWT berfirman dalam Surat Shaad ayat 41-44:"],["a","وَاذْكُرْ عَبْدَنَآ اَيُّوْبَۘ اِذْ نَادٰى رَبَّهٗٓ اَنِّيْ مَسَّنِيَ الشَّيْطٰنُ بِنُصْبٍ وَّعَذَابٍۗ(41) اُرْكُضْ بِرِجْلِكَۚ هٰذَا مُغْتَسَلٌۢ بَارِدٌ وَّشَرَابٌ(42) وَوَهَبْنَا لَهٗٓ اَهْلَهٗ وَمِثْلَهُمْ مَّعَهُمْ رَحْمَةً مِّنَّا وَذِكْرٰى لِاُولِى الْاَلْبَابِ(43) وَخُذْ بِيَدِكَ ضِغْثًا فَاضْرِبْ بِّهٖ وَلَا تَحْنَثْ ۗ اِنَّا وَجَدْنٰهُ صَابِرًا ۗ نِعْمَ الْعَبْدُ ۗ اِنَّهٗٓ اَوَّابٌ(44) ص : 41-44"],["p","Dan ingatlah akan hamba Kami Ayyub ketika ia menyeru Tuhannya; \"Sesungguhnya aku diganggu syetan dengan kepayahan dan siksaan\". (41)"],["p","(Allah berfirman): \"Hantamkanlah kakimu; inilah air yang sejuk untuk mandi dan untuk minum. (42)"],["p","Dan Kami anugerahi dia (dengan mengumpulkan kembali) keluarganya dan (Kami tambahkan) kepada mereka sebanyak mereka pula sebagai rahmat dari Kami dan pelajaran bagi orang-orang yang mempunyai pikiran. (43)"],["p","Dan ambillah dengan tanganmu seikat (rumput), maka pukullah dengan itu dan janganlah kamu melanggar sumpah. Sesungguhnya Kami dapati dia (Ayyub) seorang yang shabar. Dialah sebaik-baik hamba. Sesungguhnya dia amat tha’at (kepada Tuhannya). (44) [QS. Shaad : 41-44]"],["p","Tersebutlah sebuah kisah Nabi, yaitu Nabi Ayyub AS. Nabi Ayyub adalah seorang yang sangat kaya. Nabi Ayyub memiliki hewan ternak, budak, dan juga tanah. Nabi Ayyub juga dikaruniai seorang istri dan anak-anak yang baik dan sholehah. Namun pada suatu ketika, atas izin Allah kawanan Iblis menghancurkan dan meluluhlantakkan kekayaan Nabi Ayyub. Hewan-hewan ternak mati satu persatu sehingga habis tak tersisa, kemudian disusul ladang-ladang dan kebun-kebun tanamannya rusak dan menjadi kering dan rumahnya terbakar habis dimakan api. Dalam waktu yang sangat singkat Nabi Ayyub yang tadinya kaya raya tiba-tiba menjadi miskin tidak memiliki apapun selain hatinya yang penuh iman dan taqwa serta jiwanya yang shabar dan tawakkal."],["p","Ujian demi ujian terus menimpanya, anak-anaknya meninggal, hartanya habis tak bersisa, ternaknya binasa, sampai ia sendiri terkena penyakit yang sangat sulit disembuhkan. Seluruh badannya digerogoti penyakit, kecuali lisan yang ia gunakan untuk berdzikir. Hari-hari berlalu, kerabat dan sanak saudara mulai meninggalkan Nabi Ayyub. Tinggallah seorang istri setia yang menemani dan mengurus semua keperluan Nabi Ayyub. Penyakit Nabi Ayyub semakin lama semakin parah. Sekalipun demikian, Nabi Ayyub tetap tabah dan menerimanya sebagai cobaan dari Allah SWT. Keimanannya kepada Allah SWT tidak berkurang sedikitpun, justru beliau semakin rajin beribadah dan mendekatkan diri kepada Allah SWT."],["p","Penyakit Nabi Ayyub sangat parah sehingga ia hanya dapat berbaring. Semakin lama kondisinya semakin memburuk. Penyakit ini ia derita sudah 18 tahun. Selama beliau sakit, seluruh penduduk disekitarnya mengasingkan dirinya. Hanya istrinya yang mengurus segala keperluan Nabi Ayyub. Namun, iblis selalu menghasut istri Nabi Ayyub yang bernama Rahmah. Iblis membisikkan kebencian ke dalam hati istri Nabi Ayyub. Pada suatu hari, istri Nabi Ayyub mengatakan hal-hal yang menyakiti Nabi Ayyub. Nabi Ayyub pun sangat sedih. Ia bersumpah, apabila kelak ia sembuh, ia akan memukul istrinya sebanyak 100 kali. Pada saat kondisi Nabi Ayyub semakin lemah, Allah menurunkan wahyu kepadanya, “Hentakkanlah kakimu; inilah air yang sejuk untuk mandi dan untuk minum.”"],["p","Nabi Ayyub menghentakkan kakinya ke tanah sehingga air keluar. Air tersebut digunakan untuk mandi dan minum Nabi Ayyub. Tidak lama kemudian, tubuh Nabi Ayyub kembali sehat. Bahkan. Ia lebih sehat dan kuat dibanding sebelumnya. Setelah sembuh, istri Nabi Ayyub kembali kepada suaminya. Nabi Ayyub teringat dengan sumpahnya. Namun, ia tidak sampai hati memukul istrinya. Nabi Ayyub mengalami kebingungan akan sumpahnya, ia tidak dapat memenuhi sumpahnya. Akhirnya turunlah perintah Allah agar Nabi Ayyub melaksanakan sumpahnya. Ia diperintahkan untuk memukul istrinya dengan menggunakan 100 helai rumput yang diikat. Kemudian Nabi Ayyub melaksanakan perintah Allah tersebut dengan penuh ketha’atan. Dengan demikian Nabi Ayyub telah memenuhi sumpahnya."],["p","Ada banyak keutamaan yang bisa kita peroleh dari sikap shabar, diantaranya:"],["h","1. Allah memberi ganjaran terbaik bagi hamba-hamba-Nya yang shabar"],["a","قُلْ يٰعِبَادِ الَّذِيْنَ اٰمَنُوا اتَّقُوْا رَبَّكُمْ ۗ لِلَّذِيْنَ اَحْسَنُوْا فِيْ هٰذِهِ الدُّنْيَا حَسَنَةٌ ۗ وَاَرْضُ اللّٰهِ وَاسِعَةٌ ۗ اِنَّمَا يُوَفَّى الصّٰبِرُوْنَ اَجْرَهُمْ بِغَيْرِ حِسَابٍ. الزمر : 10"],["p","Katakanlah: \"Hai hamba-hamba-Ku yang beriman, bertakwalah kepada Tuhanmu\". Orang-orang yang berbuat baik di dunia ini memperoleh kebaikan. Dan bumi Allah itu adalah luas. Sesungguhnya hanya orang-orang yang bershabarlah yang dicukupkan pahala mereka tanpa batas. [Q.S Az-Zumar: 10]"],["a","وَالَّذِيْنَ صَبَرُوا ابْتِغَاۤءَ وَجْهِ رَبِّهِمْ وَاَقَامُوا الصَّلٰوةَ وَاَنْفَقُوْا مِمَّا رَزَقْنٰهُمْ سِرًّا وَّعَلَانِيَةً وَّيَدْرَءُوْنَ بِالْحَسَنَةِ السَّيِّئَةَ اُولٰۤىِٕكَ لَهُمْ عُقْبَى الدَّارِۙ (22) جَنّٰتُ عَدْنٍ يَّدْخُلُوْنَهَا وَمَنْ صَلَحَ مِنْ اٰبَاۤىِٕهِمْ وَاَزْوَاجِهِمْ وَذُرِّيّٰتِهِمْ وَالْمَلٰۤىِٕكَةُ يَدْخُلُوْنَ عَلَيْهِمْ مِّنْ كُلِّ بَابٍۚ(23) سَلٰمٌ عَلَيْكُمْ بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى الدَّارِۗ(24) الرعد : 22-24"],["p","Dan orang-orang yang shabar karena mencari keridlaan Tuhannya, mendirikan shalat, dan menafkahkan sebagian rezeki yang Kami berikan kepada mereka, secara sembunyi atau terang-terangan serta menolak kejahatan dengan kebaikan; orang-orang itulah yang mendapat tempat kesudahan (yang baik),(22)"],["p","(yaitu) surga ‘Adn yang mereka masuk ke dalamnya bersama-sama dengan orang-orang yang shaleh dari bapak-bapaknya, istri-istrinya dan anak cucunya, sedang malaikat-malaikat masuk ke tempat-tempat mereka dari semua pintu;(23)"],["p","(sambil mengucapkan): \"Salaamun 'alaikum bimaa shabartum\". Maka alangkah baiknya tempat kesudahan itu.(24) [QS. Ar Ro’ad : 22-24]"],["a","مَا عِنْدَكُمْ يَنْفَدُ وَمَا عِنْدَ اللّٰهِ بَاقٍۗ وَلَنَجْزِيَنَّ الَّذِيْنَ صَبَرُوْٓا اَجْرَهُمْ بِاَحْسَنِ مَا كَانُوْا يَعْمَلُوْنَ. النحل :96"],["p","Apa yang di sisimu akan lenyap, dan apa yang ada di sisi Allah adalah kekal. Dan sesungguhnya Kami akan memberi balasan kepada orang-orang yang shabar dengan pahala yang lebih baik dari apa yang telah mereka kerjakan. [QS. An Nahl : 96]"],["a","عَنْ صُهَيْبٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : عَجَبًا لِاَمْرِ الْمُؤْمِنِ، اِنَّ اَمْرَهُ كُلَّهُ خَيْرٌ. وَ لَيْسَ ذَاكَ لِاَحَدٍ اِلَّا لِلْمُؤْمِنِ. اِنْ اَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ. وَ اِنْ اَصَابَتْهُ ضَرَّاءُ صَبَرَ، فَكَانَ خَيْرًا لَهُ. مسلم 4: 2295 رقم 64"],["p","Dari Shuhaib, ia berkata : Rasulullah SAW bersabda, \"Mengagumkan sekali urusannya orang mukmin itu. Sesungguhnya urusannya, semuanya menjadi kebaikan baginya. Dan tidak ada yang mendapatkan demikian itu seseorangpun kecuali orang mukmin. Jika mendapatkan kesenangan, bersyukur. Maka yang demikian itu adalah menjadi kebaikan baginya. Dan apabila ditimpa suatu mushibah, bershabar. Maka yang demikian itu menjadi kebaikan pula baginya\". [HR. Muslim juz 4, hal. 2295, no. 64]"],["a","عَنِ الْحَارِثِ بْنِ سُوَيْدٍ قَالَ: قَالَ عَبْدُ اللهِ بْنُ مَسْعُوْدٍ: دَخَلْتُ عَلَى رَسُوْلِ اللهِ ﷺ وَ هُوَ يُوْعَكُ وَعْكًا شَدِيْدًا فَمَسِسْتُهُ بِيَدِى فَقُلْتُ: يَا رَسُوْلَ اللهِ اِنَّكَ تُوْعَكُ وَعْكًا شَدِيْدًا؟ فَقَالَ رَسُوْلُ اللهِ ﷺ: اَجَلْ. اِنّيْ اُوْعَكُ كَمَا يُوْعَكُ رَجُلَانِ مِنْكُمْ. فَقُلْتُ: ذٰلِكَ اَنَّ لَكَ اَجْرَيْنِ؟ فَقَالَ رَسُوْلُ اللهِ ﷺ : اَجَلْ. ثُمَّ قَالَ رَسُوْلُ اللهِ ﷺ : مَا مِنْ مُسْلِمٍ يُصِيْبُهُ اَذًى مَرَضٌ فَمَا سِوَاهُ اِلَّا حَطَّ اللهُ سَيِّئَاتِهِ كَمَا تَحُطُّ الشَّجَرَةُ وَرَقَهَا. البخارى 7: 6"],["p","Dari Al-Harits bin Suwaid, ia berkata : ‘Abdullah bin Mas’ud berkata : Saya pernah datang kepada Rasulullah SAW ketika itu beliau demam panas sekali, lalu saya mengusapnya dengan tangan saya dan berkata, \"Wahai Rasulullah, sesungguhnya engkau menderita demam yang panas sekali\". Lalu Rasulullah SAW menjawab, \"Ya, sesungguhnya aku menderita demam sebagaimana panasnya dua orang diantara kalian\". Saya berkata, \"Yang demikian itu apakah karena engkau mendapatkan dua pahala ?\". Rasulullah SAW menjawab, \"Benar”. Kemudian Rasulullah SAW bersabda, “Tidaklah seorang muslim yang ditimpa penderitaan berupa sakit atau yang lainnya, melainkan dengan itu Allah menggugurkan dosa-dosanya sebagaimana pohon menggugurkan daun-daunnya\". [HR. Bukhari juz 7, hal. 6]"],["a","عَنْ عَبْدِ اللهِ قَالَ: دَخَلْتُ عَلَى رَسُوْلِ اللهِ ﷺ وَ هُوَ يُوْعَكُ فَقُلْتُ: يَا رَسُوْلَ اللهِ اِنَّكَ تُوْعَكُ وَعْكًا شَدِيْدًا؟ قَالَ اَجَلْ. اِنّيْ اُوْعَكُ كَمَا يُوْعَكُ رَجُلَانِ مِنْكُمْ. قُلْتُ: ذٰلِكَ اَنَّ لَكَ اَجْرَيْنِ؟ قَالَ: اَجَلْ، ذٰلِكَ كَذٰلِكَ. مَا مِنْ مُسْلِمٍ يُصِيْبُهُ اَذًى شَوْكَةٌ فَمَا فَوْقَهَا اِلَّا كَفَّرَ اللهُ بِهَا سَيِّئَاتِهِ كَمَا تَحُطُّ الشَّجَرَةُ وَرَقَهَا. البخارى 7: 3"],["p","Dari ‘Abdullah (bin Mas’ud), ia berkata : Saya pernah datang kepada Rasulullah SAW ketika itu beliau demam panas sekali, lalu saya berkata, \"Wahai Rasulullah, sesungguhnya engkau menderita demam yang panas sekali\". (Rasulullah SAW) menjawab, \"Ya, sesungguhnya aku menderita demam sebagaimana panasnya dua orang diantara kalian\". Saya berkata, \"Yang demikian itu apakah karena engkau mendapatkan dua pahala ?\". (Rasulullah SAW) menjawab, \"Benar, seperti demikian itulah. Tidaklah seorang muslim yang ditimpa penderitaan berupa tercocok duri atau yang lebih dari itu, melainkan dengan itu Allah menghapus dosa-dosanya sebagaimana pohon menggugurkan daun-daunnya\". [HR. Bukhari juz 7, hal. 3]"],["h","2. Allah mencintai dan bersama orang-orang yang shabar"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اسْتَعِيْنُوْا بِالصَّبْرِ وَالصَّلٰوةِ ۗ اِنَّ اللّٰهَ مَعَ الصّٰبِرِيْنَ. البقرة :153"],["p","Hai orang-orang yang beriman, mintalah pertolongan (kepada Allah) dengan shabar dan (mengerjakan) shalat, sesungguhnya Allah beserta orang-orang yang shabar. [Q.S Al Baqarah: 153]"],["a","وَاَطِيْعُوا اللّٰهَ وَرَسُوْلَهٗ وَلَا تَنَازَعُوْا فَتَفْشَلُوْا وَتَذْهَبَ رِيْحُكُمْ وَاصْبِرُوْاۗ اِنَّ اللّٰهَ مَعَ الصّٰبِرِيْنَۚ. الانفال : 46"],["p","Dan tha’atlah kepada Allah dan Rasul-Nya dan janganlah kamu berbantah-bantahan, yang menyebabkan kamu menjadi gentar dan hilang kekuatanmu dan bershabarlah. Sesungguhnya Allah beserta orang-orang yang shabar.[QS. Al Anfaal : 46]"],["a","وَاللّٰهُ يُحِبُّ الصّٰبِرِيْنَ. ال عمران : 146"],["p","Dan Allah menyukai orang-orang yang shabar. [QS. Ali ‘Imraan : 146]"],["p","(bersambung)"]],"c20220828_1296":[["p","Ahad, 28 Agustus 2022/30 Muharram 1444 Brosur No.: 2091/2131/IA"],["h","SHABAR DAN TAWAKKAL ADALAH SOLUSI DALAM MENGHADAPI UJIAN DAN COBAAN (2)"],["p","3. Allah mengampuni dosa dan menghapuskan kesalahan-kesalahan orang yang shabar"],["a","وَلَىِٕنْ اَذَقْنَا الْاِنْسَانَ مِنَّا رَحْمَةً ثُمَّ نَزَعْنٰهَا مِنْهُۚ اِنَّهٗ لَيَـُٔوْسٌ كَفُوْرٌ(9) وَلَىِٕنْ اَذَقْنٰهُ نَعْمَاۤءَ بَعْدَ ضَرَّاۤءَ مَسَّتْهُ لَيَقُوْلَنَّ ذَهَبَ السَّيِّاٰتُ عَنِّيْ ۗ اِنَّهٗ لَفَرِحٌ فَخُوْرٌۙ (10) اِلَّا الَّذِيْنَ صَبَرُوْا وَعَمِلُوا الصّٰلِحٰتِۗ اُولٰۤىِٕكَ لَهُمْ مَّغْفِرَةٌ وَّاَجْرٌ كَبِيْرٌ(11). هود : 9 -11"],["p","Dan jika Kami rasakan kepada manusia suatu rahmat (nikmat) dari Kami, kemudian rahmat itu Kami cabut daripadanya, pastilah dia menjadi putus asa lagi tidak berterima kasih.(9)"],["p","Dan jika Kami rasakan kepadanya kebahagiaan sesudah bencana yang menimpanya, niscaya dia akan berkata: \"Telah hilang bencana-bencana itu dari padaku\"; sesungguhnya dia sangat gembira lagi bangga, (10)"],["p","Kecuali orang-orang yang shabar (terhadap bencana), dan mengerjakan amal-amal shaleh; mereka itu beroleh ampunan dan pahala yang besar. [QS. Huud: 9-11]"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ ﷺ قَالَتْ: قَالَ رَسُوْلُ اللهِ ﷺ : مَا مِنْ مُصِيْبَةٍ تُصِيْبُ الْمُسْلِمَ اِلَّا كَـفَّرَ اللهُ بـِهَا عَنْهُ حَتَّى الشَّوْكَةِ يُشَاكُهَا. البخارى 7: 2"],["p","Dari 'Aisyah RA istri Nabi SAW, ia berkata : Rasulullah SAW bersabda, \"Tidaklah suatu mushibah menimpa kepada seorang muslim kecuali dengan itu Allah menghapus dosa darinya, sekalipun hanya tercocok duri\". [HR. Bukhari juz 7, hal. 2]"],["a","عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا تُصِيْبُ الْمُؤْمِنَ شَوْكَةٌ فَمَا فَوْقَهَا اِلَّا قَصَّ اللهُ بِهَا مِنْ خَطِيْئَتِهِ.مسلم 4 : 1992 رقم 48"],["p","Dari ‘Aisyah, ia berkata: Rasulullah SAW bersabda: “Tidaklah mushibah menimpa orang mukmin berupa tercocok duri atau yang lebih dari itu, kecuali dengannya Allah mengurangi dosa-dosanya”.[HR. Muslim juz 4, hal. 1992, no. 48]"],["a","عَنِ الْحَارِثِ بْنِ سُوَيْدٍ قَالَ: قَالَ عَبْدُ اللهِ بْنُ مَسْعُوْدٍ: دَخَلْتُ عَلَى رَسُوْلِ اللهِ ﷺ وَهُوَ يُوْعَكُ وَعْكًا شَدِيْدًا فَمَسِسْتُهُ بِيَدِيْ فَقُلْتُ: يَا رَسُوْلَ اللهِ اِنَّكَ تُوْعَكُ وَعْكًا شَدِيْدًا؟ فَقَالَ رَسُوْلُ اللهِ ﷺ : اَجَلْ. اِنِّيْ اُوْعَكُ كَمَا يُوْعَكُ رَجُلَانِ مِنْكُمْ. فَقُلْتُ: ذٰلِكَ اَنَّ لَكَ اَجْرَيْنِ؟ فَقَالَ رَسُوْلُ اللهِ ﷺ: اَجَلْ. ثُـمَّ قَالَ رَسُوْلُ اللهِ ﷺ : مَا مِنْ مُسْلِمٍ يُصِيْبُهُ اَذًى مَرَضٌ فَمَا سِوَاهُ اِلَّا حَطَّ اللهُ سَيِّئَاتِهِ كَمَا تَحُطُّ الشَّجَرَةُ وَرَقَهَا. البخارى 7: 6"],["p","Dari Al-Harits bin Suwaid, ia berkata : ‘Abdullah bin Mas’ud berkata : Saya pernah datang kepada Rasulullah SAW ketika itu beliau demam panas sekali, lalu saya mengusapnya dengan tangan saya dan berkata, \"Wahai Rasulullah, sesungguhnya engkau menderita demam yang panas sekali\". Lalu Rasulullah SAW menjawab, \"Ya, sesungguhnya aku menderita demam sebagaimana panasnya dua orang diantara kalian\". Saya berkata, \"Yang demikian itu apakah karena engkau mendapatkan dua pahala ?\". Rasulullah SAW menjawab, \"Benar”. Kemudian Rasulullah SAW bersabda, “Tidaklah seorang muslim yang ditimpa penderitaan berupa sakit atau yang lainnya, kecuali dengan itu Allah menggugurkan dosa-dosanya sebagaimana pohon menggugurkan daun-daunnya\". [HR. Bukhari juz 7, hal. 6]"],["a","عَنْ اُمِّ العَلَاءِ قَالَتْ : عَادَنِيْ رَسُوْلُ اللهِ ﷺ وَاَنَا مَرِيْضَةٌ، فَقَالَ: اَبْشِرِيْ يَا اُمَّ الْعَلَاءِ، فَاِنَّ مَرَضَ الْمُسْلِمِ يُذْهِبُ اللهُ بِهِ خَطَايَاهُ كَمَا تُذْهِبُ النَّارُ خَبَثَ الذَّهَبِ وَالفِضَّةِ.ابو داود 3 :184 رقم 3092"],["p","Dari Ummul Al-Alaa’, ia berkata :”Rasulullah SAW menjengukku tatkala aku sedang sakit, lalu beliau bersabda: “Gembirakanlah wahai Ummul ‘Alaa’. Karena sakitnya orang muslim itu dengannya Allah menghilangkan kesalahan-kesalahannya, sebagaimana api menghilangkan kotoran emas dan perak“. [H.R. Abu Dawud juz 3, hal 184, no. 3092]"],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِيِّ وَ عَنْ اَبِيْ هُرَيْرَةَ عَنِ النَّبِيِّ ﷺ قَالَ: مَا يُصِيْبُ الْمُسْلِمَ مِنْ نَصَبٍ وَ لَا وَصَبٍ وَ لَا هَمٍّ وَ لَا حَزَنٍ وَ لَا اَذًى وَ لَا غَمٍّ حَتَّى الشَّوْكَةِ يُشَاكُهَا اِلَّا كَفَّرَ اللهُ بِهَا مِنْ خَطَايَاهُ. البخارى 7 :2"],["p","Dari Abu Sa’id Al Khudriy dan dari Abu Hurairah, dari Nabi SAW, beliau bersabda, “Tidaklah mushibah menimpa kepada orang muslim berupa kepayahan, rasa sakit, kecemasan, duka cita, gangguan, dan tidak pula kesedihan hati, hingga terkena duripun kecuali dengannya Allah menghapus dari kesalahan-kesalahannya”. [HR. Bukhari juz 7, hal. 2]"],["a","عَنْ اَبِيْ سَعِيدٍ وَاَبِيْ هُرَيْرَةَ اَنَّهُمَا سَمِعَا رَسُوْلَ اللهِ ﷺ يَقُوْلُ: مَا يُصِيْبُ الْمُؤْمِنَ مِنْ وَصَبٍ وَلَا نَصَبٍ وَلَا سَقَمٍ وَلَا حَزَنٍ حَتَّى الْهَمِّ يُهَمُّهُ اِلَّا كُفِّرَ بِهِ مِنْ سَيِّئَاتِهِ. مسلم 4 : 1992 رقم 52"],["p","Dari Abu Sa’id (Al Khudriy) dan Abu Hurairah, bahwasanya keduanya mendengar Rasulullah SAW bersabda: “Tidaklah mushibah menimpa orang mukmin berupa rasa sakit, kepayahan, sakit, kesedihan hingga kecemasan melainkan dengannya Allah menghapus dari kesalahan-kesalahannya.” [HR. Muslim juz 4, hal 1992, no 52]"],["a","عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ اُصِيْبَ بِمُصِيْبَةٍ فِيْ مَالِهِ اَوْ جَسَدِهِ فَكَتَمَهَا فَلَمْ يَشْكُهَا اِلَى النَّاسِ كَانَ حَقًّا عَلَى اللهِ اَنْ يَغْفِرَ لَهُ. الطبرانى في المعجم الكبير 11 : 148 رقم 11438"],["p","Dari Ibnu Abbas RA, ia berkata : Rasulullah SAW bersabda, “Barangsiapa yang ditimpa mushibah pada hartanya, atau jasadnya, lalu dia menyembunyikannya dengan tidak mengeluh kepada manusia, maka haq atas Allah untuk mengampuninya”. [HR. Thabarani dalam Al Mu’jamul Kabir juz 11, hal 148, no 11438, dlo’if karena dalam isnadnya ada perawi bernama Baqiyah]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَا يَزَالُ اْلبَلَاءُ بِالْمُؤْمِنِ وَ الْمُؤْمِنَةِ بِنَفْسِهِ وَ وَلَدِهِ وَ مَالِهِ حَتَّى يَلْقَى اللهَ وَ مَا عَلَيْهِ خَطِيْئَةٌ. الترمذى 4 : 28 رقم 2510 هذا حديث حسن صحيح"],["p","Dari Abu Hurairah RA, ia berkata : Rasulullah SAW bersabda, “Terus menerus cobaan menimpa kepada orang mukmin laki-laki dan orang mukmin perempuan pada dirinya, anaknya dan hartanya, sehingga ia bertemu kepada Allah Ta’aalaa dalam keadaan tidak punya dosa”. [HR. Tirmidzi juz 4, hal 28, no. 2510, ini hadits hasan shahih]"],["h","4. Keshabaran adalah pemberian yang terbaik dari Allah SWT"],["a","لَتُبْلَوُنَّ فِيْٓ اَمْوَالِكُمْ وَاَنْفُسِكُمْۗ وَلَتَسْمَعُنَّ مِنَ الَّذِيْنَ اُوْتُوا الْكِتٰبَ مِنْ قَبْلِكُمْ وَمِنَ الَّذِيْنَ اَشْرَكُوْٓا اَذًى كَثِيْرًا ۗ وَاِنْ تَصْبِرُوْا وَتَتَّقُوْا فَاِنَّ ذٰلِكَ مِنْ عَزْمِ الْاُمُوْرِ. ال عمران : 186"],["p","Kamu sungguh-sungguh akan diuji terhadap hartamu dan dirimu. Dan (juga) kamu sungguh-sungguh akan mendengar dari orang-orang yang diberi Kitab sebelum kamu dan dari orang-orang yang mempersekutukan Allah, gangguan yang banyak yang menyakitkan hati. Jika kamu bershabar dan bertakwa, maka sesungguhnya yang demikian itu termasuk urusan yang patut diutamakan. [QS. Ali ‘Imraan : 186]"],["a","وَمَا يُلَقّٰىهَآ اِلَّا الَّذِيْنَ صَبَرُوْاۚ وَمَا يُلَقّٰىهَآ اِلَّا ذُوْ حَظٍّ عَظِيْمٍ. فصلت : 35"],["p","Sifat-sifat yang baik itu tidak dianugerahkan melainkan kepada orang-orang yang shabar dan tidak dianugerahkan melainkan kepada orang-orang yang mempunyai keberuntungan yang besar.[QS. Fushshilat : 35]"],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ اَنَّ نَاسًا مِنَ الْأَنْصَارِ سَأَلُوْا رَسُوْلَ اللهِ ﷺ فَاَعْطَاهُمْ. ثُمَّ سَأَلُوْهُ فَاَعْطَاهُمْ. ثُمَّ سَاَلُوْهُ فَاَعْطَاهُمْ حَتَّى نَفِدَ مَا عِنْدَهُ، فَقَالَ: مَا يَكُوْنُ عِنْدِيْ مِنْ خَيْرٍ فَلَنْ اَدَّخِرَهُ عَنْكُمْ، وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللهُ، وَمَنْ يَسْتَغْنِ يُغْنِهِ اللهُ، وَمَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللهُ، وَمَا اُعْطِيَ اَحَدٌ عَطَاءً خَيْرًا وَاَوْسَعَ مِنَ الصَّبْرِ. البخارى 2 : 129"],["p","Dari Abu Sa'id Al Khudriy RA, bahwasanya ada beberapa orang dari kalangan Anshar meminta (pemberian) kepada Rasulullah SAW, maka beliau memberi kepada mereka. Kemudian mereka meminta lagi, maka beliau memberi. Kemudian mereka meminta lagi, maka beliau memberi lagi, sehingga ketika sudah habis apa yang ada pada beliau, beliau bersabda: \"Sudah tidak ada harta padaku dan tidaklah aku menyembunyikannya dari kalian semua. Namun barangsiapa yang menjaga diri dari meminta-minta, maka Allah akan menjaganya, barangsiapa yang merasa cukup (tidak meminta-minta), maka Allah akan mencukupkannya, dan barangsiapa yang bershabar, maka Allah memberinya keshabaran. Dan tidaklah seseorang diberi suatu pemberian yang lebih baik dan lebih luas dari pada keshabaran [HR. Bukhari juz 2, hal. 129]"],["a","عَنْ سَخْبَرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ اُعْطِيَ فَشَكَرَ، وَ ابْتُلِيَ فَصَبَرَ، وَ ظَلَمَ فَاسْتَغْفَرَ، وَ ظُلِمَ فَغَفَرَ، ثُمَّ سَكَتَ. فَقَالُوْا: يَا رَسُوْلَ اللهِ، مَا لَهُ؟ قَالَ: اُولَئِكَ لَهُمُ الْاَمْنُ وَ هُمْ مُهْتَدُوْنَ. الطبرانى في المعجم الكبير 7 : 138 رقم 6613"],["p","Dari Sakhbarah, ia berkata : Rasulullah SAW bersabda: “Barangsiapa diberi lalu berterima kasih, jika diberi cobaan dia bershabar, jika ia berbuat dhalim lalu mohon ampun, jika didhalimi dia memaafkan”. Kemudian Rasulullah SAW diam. Maka para shahabat bertanya, “Ya Rasulullah, bagaimana orang tersebut ?”. Beliau bersabda, “Mereka orang-orang yang mendapatkan keamanan dan mereka orang-orang yang mendapat petunjuk”. [HR. Thabarani dalam Al Mu’jamul Kabir juz 7, hal. 138, no. 6613, dlo’if karena dalam isnadnya ada perawi bernama Abu Dawud Al A’maa, ia matruk]"],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِيِّ اَنَّ نَاسًا مِنَ الْأَنْصَارِ سَأَلُوْا رَسُوْلَ اللهِ ﷺ فَاَعْطَاهُمْ. ثُمَّ سَأَلُوْهُ فَاَعْطَاهُمْ حَتَّى اِذَا نَفِدَ مَا عِنْدَهُ، قَالَ: مَا يَكُنْ عِنْدِيْ مِنْ خَيْرٍ فَلَنْ اَدَّخِرَهُ عَنْكُمْ، وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللهُ، وَمَنْ يَسْتَغْنِ يُغْنِهِ اللهُ، وَمَنْ يَصْبِرْ يُصَبِّرْهُ اللهُ، وَمَا اُعْطِيَ اَحَدٌ مِنْ عَطَاءٍ خَيْرٌ وَاَوْسَعُ مِنَ الصَّبْرِ. مسلم 2: 729 رقم 124"],["p","Dari Abu Sa'id Al Khudriy, bahwasanya ada beberapa orang dari kalangan Anshar meminta (pemberian) kepada Rasulullah SAW, maka beliau memberi kepada mereka. Kemudian mereka meminta lagi, maka beliau memberi lagi, sehingga ketika sudah habis apa yang ada pada beliau, beliau bersabda: \"Sudah tidak ada harta padaku dan tidaklah aku menyembunyikannya dari kalian semua. Namun barangsiapa yang menjaga diri dari meminta-minta, maka Allah akan menjaganya, barangsiapa yang merasa cukup (tidak meminta-minta), maka Allah akan mencukupkannya, dan barangsiapa yang bershabar, maka Allah memberinya keshabaran. Dan tidaklah seseorang diberi suatu pemberian yang lebih baik dan lebih luas dari pada keshabaran [HR. Muslim juz 2, hal. 729, no. 124]"],["a","عَنْ اَنَسٍ عَنِ النَّبِيِّ ﷺ قَالَ: اِنَّ عِظَمَ الْجَزَاءِ مَعَ عِظَمِ الْبَلَاءِ. وَاِنَّ اللهَ اِذَا اَحَبَّ قَوْمًا اِبْتَلَاهُمْ. فَمَنْ رَضِيَ فَلَهُ الرِّضَى وَمَنْ سَخِطَ فَلَهُ السَّخَطُ. الترمذى 4: 27، رقم: 2507، هذا حديث حسن غريب"],["p","Dari Anas, dari Nabi SAW, beliau bersabda, \"Sesungguhnya besarnya balasan itu tergantung besarnya cobaan. Dan sesungguhnya Allah apabila mencintai suatu kaum, maka Allah memberikan cobaan kepada mereka. Barangsiapa yang ridla, maka dia mendapatkan keridlaan Allah. Dan barangsiapa yang menggerutu (tidak ridla) maka dia mendapatkan murka Allah\". [HR. Tirmidzi juz 4, hal. 27, no. 2507, ini hadits hasan, gharib,]."],["a","عَنْ اَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ ﷺ يَقُوْلُ: اِنَّ اللهَ تَعَالَى قَالَ: اِذَا ابْتَلَيْتُ عَبْدِيْ بِحَبِيْبَتَيْهِ فَصَبَرَ عَوَّضْتُهُ مِنْهُمَا الجَنَّةَ. يُرِيْدُ عَيْنَيْهِ. البخارى 7: 4"],["p","Dari Anas bin Maalik RA, ia berkata : Saya mendengar Nabi SAW bersabda, “Sesungguhnya Allah Ta’aalaa berfirman : Apabila Aku menguji hamba-Ku dengan kedua kecintaannya, lalu ia bershabar, maka Aku akan menggantinya dengan surga”. Yang dimaksud kedua kecintaannya adalah kedua matanya. [HR. Bukhari juz 7, hal. 4]"],["p","(Bersambung)"]],"c20220904_1297":[["p","Ahad, 4 September 2022/ 7 Shafar 1444 Brosur No.: 2092/2132/IA"],["h","SHABAR DAN TAWAKKAL ADALAH SOLUSI DALAM MENGHADAPI UJIAN DAN COBAAN (3)"],["p","5. Orang shabar akan diberi balasan martabat yang tinggi di dalam surga"],["a","وَالَّذِيْنَ صَبَرُوا ابْتِغَاۤءَ وَجْهِ رَبِّهِمْ وَاَقَامُوا الصَّلٰوةَ وَاَنْفَقُوْا مِمَّا رَزَقْنٰهُمْ سِرًّا وَّعَلَانِيَةً وَّيَدْرَءُوْنَ بِالْحَسَنَةِ السَّيِّئَةَ اُولٰۤىِٕكَ لَهُمْ عُقْبَى الدَّارِۙ (22)جَنّٰتُ عَدْنٍ يَّدْخُلُوْنَهَا وَمَنْ صَلَحَ مِنْ اٰبَاۤىِٕهِمْ وَاَزْوَاجِهِمْ وَذُرِّيّٰتِهِمْ وَالْمَلٰۤىِٕكَةُ يَدْخُلُوْنَ عَلَيْهِمْ مِّنْ كُلِّ بَابٍۚ (23)سَلٰمٌ عَلَيْكُمْ بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى الدَّارِ (24) الرعد : 22-24"],["p","Dan orang-orang yang shabar karena mencari keridlaan Tuhannya, mendirikan shalat, dan menafkahkan sebagian rezeki yang Kami berikan kepada mereka, secara sembunyi atau terang-terangan, serta menolak kejahatan dengan kebaikan; orang-orang itulah yang mendapat tempat kesudahan (yang baik),(22)"],["p","(yaitu) surga ‘Adn yang mereka masuk ke dalamnya bersama-sama dengan orang-orang yang shaleh dari bapak-bapaknya, istri-istrinya dan anak cucunya, sedang malaikat-malaikat masuk ke tempat-tempat mereka dari semua pintu; (23)"],["p","(sambil mengucapkan): \"Salaamun 'alaikum bimaa shabartum\". Maka alangkah baiknya tempat kesudahan itu.(24) [Q.S. Ar Ro’ad : 22-24]"],["a","اُولٰۤىِٕكَ يُجْزَوْنَ الْغُرْفَةَ بِمَا صَبَرُوْا وَيُلَقَّوْنَ فِيْهَا تَحِيَّةً وَّسَلٰمًاۙ (75) خٰلِدِيْنَ فِيْهَاۗ حَسُنَتْ مُسْتَقَرًّا وَّمُقَامًا (76). الفرقان : 75 - 76"],["p","Mereka itulah orang-orang yang dibalasi dengan martabat yang tinggi (dalam surga) karena keshabaran mereka dan mereka disambut dengan penghormatan dan ucapan selamat di dalamnya,(75)"],["p","mereka kekal di dalamnya. Surga itu sebaik-baik tempat menetap dan tempat kediaman. (76) [Q.S Al-Furqaan: 75-76]"],["a","عَنْ عَطَاءِ بْنِ اَبِيْ رَبَاحٍ قَالَ: قَالَ لِى ابْنُ عَبَّاسٍ: اَلَا اُرِيْكَ امْرَأَةً مِنْ اَهْلِ الْجَنَّةِ؟ قُلْتُ: بَلَى. قَالَ: هٰذِهِ الْمَرْأَةُ السَّوْدَاءُ اَتَتِ النَّبِيَّ ﷺ فَقَالَتْ: اِنِّيْ اُصْرَعُ وَاِنِّيْ اَتَكَشَّفُ فَادْعُ اللهَ لِيْ. قَالَ: اِنْ شِئْتِ صَبَرْتِ وَلَكِ الْجَنَّةُ، وَاِنْ شِئْتِ دَعَوْتُ اللهَ اَنْ يُعَافِيَكِ. فَقَالَتْ: اَصْبِرُ. فَقَالَتْ: اِنِّيْ اَتَكَشَّفُ فَادْعُ اللهَ لِيْ اَنْ لَا اَتَكَشَّفَ. فَدَعَا لَهَا. البخارى 7 : 4"],["p","Dari ‘Atha’ bin Abu Rabaah, ia berkata. “Ibnu Abbas pernah berkata kepadaku: “Maukah kutunjukkan kepadamu seorang wanita penghuni surga ?”. Aku menjawab: ‘Ya”. Ibnu Abbas berkata: “Wanita berkulit hitam itu pernah datang kepada Nabi SAW seraya berkata: “Sesungguhnya saya sakit ayan dan (‘auratku) terbuka, maka do’akanlah kepada Allah untuk saya”. Rasulullah SAW bersabda: “Jika engkau menghendaki, engkau bisa bershabar dan bagimu surga. Dan, jika engkau menghendaki aku bisa berdo’a kepada Allah sehingga Allah menyembuhkanmu.” Wanita itu berkata: “Aku akan bershabar”. Wanita itu berkata lagi: “Sesungguhnya (‘auratku) terbuka, maka do’akanlah kepada Allah agar ‘auratku tidak terbuka”. Maka Rasulullah SAW mendo’akan wanita tersebut”. [H.R. Bukhari juz 7, hal 4]"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ ﷺ يَقُوْلُ: اِنَّ اللهَ تَعَالَى قَالَ: اِذَا ابْتَلَيْتُ عَبْدِيْ بِحَبِيْبَتَيْهِ فَصَبَرَ عَوَّضْتُهُ مِنْهُمَا الجَنَّةَ. يُرِيْدُ عَيْنَيْهِ. البخارى 7: 4"],["p","Dari Anas bin Maalik RA, ia berkata : Saya mendengar Nabi SAW bersabda, “Sesungguhnya Allah Ta’aalaa berfirman : Apabila Aku menguji hamba-Ku dengan kedua kecintaannya, lalu ia bershabar, maka Aku akan menggantinya dengan surga”. Yang dimaksud kedua kecintaannya adalah kedua matanya. [HR. Bukhari juz 7, hal. 4]"],["h","6. Allah memuji dan menyanjung kepada orang yang shabar"],["a","لَيْسَ الْبِرَّ اَنْ تُوَلُّوْا وُجُوْهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ وَلٰكِنَّ الْبِرَّ مَنْ اٰمَنَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ وَالْمَلٰۤىِٕكَةِ وَالْكِتٰبِ وَالنَّبِيّٖنَ ۚ وَاٰتَى الْمَالَ عَلٰى حُبِّهٖ ذَوِى الْقُرْبٰى وَالْيَتٰمٰى وَالْمَسٰكِيْنَ وَابْنَ السَّبِيْلِۙ وَالسَّاۤىِٕلِيْنَ وَفىِ الرِّقَابِۚ وَاَقَامَ الصَّلٰوةَ وَاٰتَى الزَّكٰوةَ ۚ وَالْمُوْفُوْنَ بِعَهْدِهِمْ اِذَا عَاهَدُوْا ۚ وَالصّٰبِرِيْنَ فِى الْبَأْسَاۤءِ وَالضَّرَّاۤءِ وَحِيْنَ الْبَأْسِۗ اُولٰۤىِٕكَ الَّذِيْنَ صَدَقُوْا ۗ وَاُولٰۤىِٕكَ هُمُ الْمُتَّقُوْنَ. البقرة : 177"],["p","Bukanlah menghadapkan wajahmu ke arah timur dan barat itu suatu kebajikan, akan tetapi sesungguhnya kebajikan itu ialah beriman kepada Allah, hari kemudian, malaikat-malaikat, kitab-kitab, nabi-nabi dan memberikan harta yang dicintainya kepada kerabatnya, anak-anak yatim, orang-orang miskin, musafir (yang memerlukan pertolongan), orang-orang yang meminta-minta, dan (memerdekakan) hamba sahaya. Mendirikan shalat, dan menunaikan zakat; dan orang-orang yang menepati janjinya apabila ia berjanji, dan orang-orang yang shabar dalam kesempitan, penderitaan dan dalam peperangan. Mereka itulah orang-orang yang benar (imannya); dan mereka itulah orang-orang yang bertaqwa. (Q.S. Al Baqarah : 177)"],["a","عَنْ صُهَيْبٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: عَجَبًا لِاَمْرِ الْمُؤْمِنِ، اِنَّ اَمْرَهُ كُلَّهُ خَيْرٌ. وَ لَيْسَ ذَاكَ لِاَحَدٍ اِلَّا لِلْمُؤْمِنِ. اِنْ اَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ. وَ اِنْ اَصَابَتْهُ ضَرَّاءُ صَبَرَ، فَكَانَ خَيْرًا لَهُ. مسلم 4: 2295 رقم 64"],["p","Dari Shuhaib, ia berkata : Rasulullah SAW bersabda, “Mengagumkan sekali urusannya orang mukmin itu. Sesungguhnya urusannya, semuanya menjadi kebaikan baginya. Dan tidak ada yang mendapatkan demikian itu seseorangpun kecuali orang mukmin. Jika mendapatkan kesenangan, bersyukur. Maka yang demikian itu adalah menjadi kebaikan baginya. Dan apabila ditimpa suatu mushibah, bershabar. Maka yang demikian itu menjadi kebaikan pula baginya\". [HR. Muslim juz 4, hal. 2295, no. 64]"],["h","7. Allah melipatgandakan pahala bagi orang yang shabar"],["a","قُلْ يٰعِبَادِ الَّذِيْنَ اٰمَنُوا اتَّقُوْا رَبَّكُمْ ۗ لِلَّذِيْنَ اَحْسَنُوْا فِيْ هٰذِهِ الدُّنْيَا حَسَنَةٌ ۗ وَاَرْضُ اللّٰهِ وَاسِعَةٌ ۗ اِنَّمَا يُوَفَّى الصّٰبِرُوْنَ اَجْرَهُمْ بِغَيْرِ حِسَابٍ. الزمر : 10"],["p","Katakanlah: \"Hai hamba-hamba-Ku yang beriman, bertakwalah kepada Tuhanmu\". Orang-orang yang berbuat baik di dunia ini memperoleh kebaikan. Dan bumi Allah itu adalah luas. Sesungguhnya hanya orang-orang yang bershabarlah yang dicukupkan pahala mereka tanpa batas. (Q.S. Az Zumar : 10)"],["a","مَا عِنْدَكُمْ يَنْفَدُ وَمَا عِنْدَ اللّٰهِ بَاقٍۗ وَلَنَجْزِيَنَّ الَّذِيْنَ صَبَرُوْٓا اَجْرَهُمْ بِاَحْسَنِ مَا كَانُوْا يَعْمَلُوْنَ. النحل : 96"],["p","Apa yang di sisimu akan lenyap, dan apa yang ada di sisi Allah adalah kekal. Dan sesungguhnya Kami akan memberi balasan kepada orang-orang yang shabar dengan pahala yang lebih baik dari apa yang telah mereka kerjakan. (Q.S. An Nahl : 96)"],["h","8. Semakin berat cobaannya semakin sempurna agamanya"],["a","عَنْ مُصْعَبِ بْنِ سَعْدٍ عَنْ اَبِيْهِ قَالَ: قُلْتُ: يَا رَسُوْلَ اللهِ، أَيُّ النَّاسِ اَشَدُّ بَلَاءً؟ قَالَ: اَلْاَنْبِيَاءُ، ثُمَّ اَلْاَمْثَلُ فَالْاَمْثَلُ. يُبْتَلَى الرَّجُلُ عَلَى حَسَبِ دِيْنِهِ، فَاِنْ كَانَ فِيْ دِيْنِهِ صُلْبًا اِشْتَدَّ بَلَاءُهُ، وَ اِنْ كَانَ فِيْ دِيْنِهِ رِقَّةٌ اُبْتُلِيَ عَلَى قَدْرِ دِيْنِهِ. فَمَا يَبْرَحُ الْبَلَاءُ بِالْعَبْدِ حَتَّى يَتْرُكَهُ يَمْشِيْ عَلَى الْاَرْضِ وَ مَا عَلَيْهِ خَطِيْئَةٌ. الترمذى 4 : 28 رقم 2509 هذا حديث حسن صحيح"],["p","Dari Mush’ab bin Sa’ad, dari ayahnya, ia berkata : Aku pernah bertanya, “Ya Rasulullah, siapakah manusia yang paling berat cobaannya ?”. Beliau bersabda, “Para Nabi, kemudian orang yang di bawahnya, kemudian yang di bawahnya lagi. Seseorang akan diberi cobaan menurut kadar agamanya. Apabila agamanya kuat, akan mendapat cobaan yang berat. Dan jika agamanya tipis (lemah) akan diberi cobaan menurut kadar agamanya. Maka terus menerus cobaan menimpa pada hamba sehingga Allah membiarkannya ia berjalan di muka bumi dengan tidak mempunyai dosa”. [HR. Tirmidzi juz 4, hal 28, no. 2509, ini hadits hasan shahih]"],["p","Dalam menghadapi berbagai ujian tersebut, ada beberapa sikap yang harus dilakukan seorang mukmin. Pertama, tetap merasa yakin atau optimistis bahwa akan datang pertolongan Allah kepada kita. Kedua, segera mengucapkan “innaa lillaahi wainnaa ilaihi raaji’uun” (Sesungguhnya kami adalah milik Allah dan kepada-Nya-lah kami kembali). Kalimat ini dinamakan kalimat istirjaa’ (pernyataan kembali kepada Allah). Disunnahkan menyebutnya waktu ditimpa marabahaya/mushibah, baik besar maupun kecil. Sikap selanjutnya adalah bertawakkal kepada Allah. Tawakkal menjadi salah satu syarat bagi seseorang mendapat pertolongan Allah."],["p","Ada hal-hal yang harus kita perhatikan saat bertawakkal."],["p","Pertama, jangan menyandarkan hati kepada selain Allah. Jika kita menyandarkan hati kepada selain Allah saat menghadapi satu masalah atau mushibah, pertolongan Allah akan semakin jauh dari kita."],["p","Kedua, dalam bertawakkal, jangan melakukan ikhtiar yang mudlaratnya lebih besar daripada manfaatnya. Seperti menyelesaikan segala urusan dengan cara-cara yang tidak syar’iy, atau melakukan dengan cara yang haram. Misalnya, ketika seseorang ditimpa sakit yang berkepanjangan tidak kunjung sembuh, lantas karena bingungnya datang kepada dukun dan sejenisnya untuk menyembuhkan penyakitnya. Contoh lain; seorang istri menghadapi suatu masalah dengan suaminya, seharusnya meminta pertolongan kepada Allah supaya diberikan jalan keluar yang terbaik, dengan mengembalikan permasalahannya kepada Allah dan RasulNya, yaitu bermusyawarah dengan pihak keluarga suami dan istri, bukan malah mencari pelarian dengan curhat atau menceritakan persoalan rumah tangganya dengan lelaki lain."],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اَطِيْعُوا اللّٰهَ وَاَطِيْعُوا الرَّسُوْلَ وَاُولِى الْاَمْرِ مِنْكُمْۚ فَاِنْ تَنَازَعْتُمْ فِيْ شَيْءٍ فَرُدُّوْهُ اِلَى اللّٰهِ وَالرَّسُوْلِ اِنْ كُنْتُمْ تُؤْمِنُوْنَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِۗ ذٰلِكَ خَيْرٌ وَّاَحْسَنُ تَأْوِيْلًا. النساء : 59"],["p","Hai orang-orang yang beriman, tha’atilah Allah dan tha’atilah Rasul (Nya), dan ulil amri di antara kamu. Kemudian jika kamu berlainan pendapat tentang sesuatu, maka kembalikanlah ia kepada Allah (Al Qur'an) dan Rasul (sunnahnya), jika kamu benar-benar beriman kepada Allah dan hari kemudian. Yang demikian itu lebih utama (bagimu) dan lebih baik akibatnya. [QS. An Nisaa’ : 59]"],["p","Ketiga, dalam bertawakkal, kita harus berserah diri sepenuhnya kepada Allah dari awwal hingga berakhirnya urusan. Dengan berserah diri kepada Allah, kita akan menjadi tenang sehingga dapat menerima apa pun hasil ikhtiar dengan lapang dada. Karena itu, jangan setengah-setengah dalam memasrahkan diri kepada Allah."],["a","اَللّٰهُ لَآ اِلٰهَ اِلَّا هُوَۗ وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُوْنَ. التغابن : 13"],["p","(Dia-lah) Allah, tidak ada Tuhan (yang berhak disembah) selain Dia. Dan hendaklah orang-orang mukmin bertawakkal kepada Allah saja. (QS. At Taghaabun : 13)"],["a","وَالَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ لَنُبَوِّئَنَّهُمْ مِّنَ الْجَنَّةِ غُرَفًا تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَاۗ نِعْمَ اَجْرُ الْعٰمِلِيْنَۖ (58)الَّذِيْنَ صَبَرُوْا وَعَلٰى رَبِّهِمْ يَتَوَكَّلُوْنَ (59) العنكبوت : 58-59"],["p","Dan orang-orang yang beriman dan mengerjakan amal-amal yang shaleh, sesungguhnya akan Kami tempatkan mereka pada tempat-tempat yang tinggi di dalam surga, yang mengalir sungai-sungai di bawahnya, mereka kekal di dalamnya. Itulah sebaik-baik balasan bagi orang-orang yang beramal, (58)"],["p","(yaitu) yang bershabar dan bertawakkal kepada Tuhannya.(59) [QS. Al ‘Ankabuut : 58-59]"],["a","وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُتَوَكِّلُوْنَ (12) ابراهيم : 12"],["p","Dan hanya kepada Allah saja orang-orang yang bertawakkal itu berserah diri\". [Q.S. Ibrahim : 12]"],["p","Sebagai orang yang beriman hendaklah kita bershabar dengan menahan diri dan berlapang dada, jauhkan rasa cemas serta was-was yang berlebihan. Kembalikan semua yang kita alami kepada Allah Yang Maha Agung dan Maha Mengetahui, karena keshabaran akan selalu berujung kebahagiaan, shabar bukanlah suatu sikap yang mudah kita lakukan, tapi juga tidak sulit kita usahakan. Seringkali bila kita dihadapkan dengan suatu situasi yang sulit, kita mengatakan “Sudah habis keshabaranku”. Padahal keshabaran itu tidak akan habis dan tak ada batasnya."],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اصْبِرُوْا وَصَابِرُوْا وَرَابِطُوْاۗ وَاتَّقُوا اللّٰهَ لَعَلَّكُمْ تُفْلِحُوْنَ. ال عمران : 200"],["p","Hai orang-orang yang beriman, bershabarlah kamu dan kuatkanlah keshabaranmu dan tetaplah bersiap siaga (di perbatasan negerimu) dan bertakwalah kepada Allah supaya kamu beruntung. (Q.S. Ali ‘Imraan : 200)"],["p","Semoga kita semua termasuk orang-orang yang shabar dan tawakkal."],["p","Aamiin"],["p","--oo0oo--"]],"c20220911_1298":[["p","Ahad, 11 September 2022/ 14 Shafar 1444 Brosur No.: 2093/2133/IA"],["h","MAKNA “LAA ILAAHA ILLALLOOH” (1)"],["a","وَاِلٰهُكُمْ اِلٰهٌ وَّاحِدٌۚ لَآاِلٰهَ اِلَّا هُوَ الرَّحْمٰنُ الرَّحِيْمُ . البقرة : 163"],["p","Dan Tuhanmu adalah Tuhan Yang Maha Esa; tidak ada Tuhan (yang berhak disembah) melainkan Dia, Yang Maha Pemurah lagi Maha Penyayang. [QS. Al Baqarah : 163]"],["p","Sesungguhnya kalimat ikhlash yaitu kalimat Laa ilaaha illallooh, karena kalimat tersebut memurnikan ibadah hanya untuk Allah SWT. Karena makna Laa ilaaha illallooh adalah tidak ada yang berhak disembah selain Allah."],["p","Kalimat Laa ilaaha illallooh adalah kalimat yang agung, oleh karenanya Allah mengutus para rasul dan menurunkan kitab-kitab. Dan untuk mewujudkannya Allah memerintahkan kepada orang-orang mukmin untuk berjihad, memerangi orang-orang kafir yang menentangnya. Allah SWT berfirman :"],["a","وَمَآ اَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَّسُوْلٍ اِلَّا نُوْحِيْٓ اِلَيْهِ اَنَّهٗ لَآ اِلٰهَ اِلَّآ اَنَا۠ فَاعْبُدُوْنِ. الانبياء : 25"],["p","Dan Kami tidak mengutus seorang rasul pun sebelum kamu, melainkan Kami wahyukan kepadanya: \"Bahwasanya tidak ada Tuhan (yang hak) melainkan Aku, maka sembahlah olehmu sekalian akan Aku\". [QS. Al Anbiyaa’ : 25]"],["p","Dan semua Rasul seruannya yang pertama dan yang paling utama adalah menyeru kaumnya kepada kalimat Laa illaaha illallooh, yaitu menyembah hanya kepada Allah. Allah SWT berfirman :"],["a","وَلَقَدْ اَرْسَلْنَا نُوْحًا اِلٰى قَوْمِهٖ فَقَالَ يٰقَوْمِ اعْبُدُوا اللّٰهَ مَا لَكُمْ مِّنْ اِلٰهٍ غَيْرُهٗۗ اَفَلَا تَتَّقُوْنَ . المؤمنون : 23"],["p","Dan sesungguhnya Kami telah mengutus Nuh kepada kaumnya, lalu ia berkata: \"Hai kaumku, sembahlah oleh kamu Allah, (karena) sekali-kali tidak ada Tuhan bagimu selain Dia. Maka mengapa kamu tidak bertakwa (kepada-Nya)?\" [QS. Al Mu’minuun : 23]"],["a","وَلَقَدْ بَعَثْنَا فِيْ كُلِّ اُمَّةٍ رَّسُوْلًا اَنِ اعْبُدُوا اللّٰهَ وَاجْتَنِبُوا الطَّاغُوْتَۚ فَمِنْهُمْ مَّنْ هَدَى اللّٰهُ وَمِنْهُمْ مَّنْ حَقَّتْ عَلَيْهِ الضَّلٰلَةُ ۗ فَسِيْرُوْا فِى الْاَرْضِ فَانْظُرُوْا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِيْنَ. النحل : 36"],["p","Dan sesungguhnya Kami telah mengutus rasul pada tiap-tiap ummat (untuk menyerukan): \"Sembahlah Allah (saja), dan jauhilah Thaaghuut itu\", maka di antara ummat itu ada orang-orang yang diberi petunjuk oleh Allah dan ada pula di antaranya orang-orang yang telah pasti kesesatan baginya. Maka berjalanlah kamu di muka bumi dan perhatikanlah bagaimana kesudahan orang-orang yang mendustakan (rasul-rasul). [QS. An Nahl : 36]"],["p","Dahulu orang-orang kafir Makkah yang Rasulullah SAW diutus kepada mereka, mereka mengakui bahwa tidak ada pencipta selain Allah. Allah SWT berfirman :"],["a","وَلَىِٕنْ سَاَلْتَهُمْ مَّنْ خَلَقَهُمْ لَيَقُوْلُنَّ اللّٰهُ فَاَنّٰى يُؤْفَكُوْنَ.الزخرف : 87"],["p","Dan sungguh jika kamu bertanya kepada mereka: \"Siapakah yang menciptakan mereka, niscaya mereka menjawab: \"Allah\", maka bagaimanakah mereka dapat dipalingkan (dari menyembah Allah)?, [QS. Az Zukhruf : 87]"],["p","Namun pengakuan orang-orang kafir Makkah tersebut belum mencukupi untuk mewujudkan tauhid, karena untuk mewujudkan tauhid harus dengan pengertian dan ilmu yang membawa mereka menyembah hanya kepada Allah yang Maha Esa tidak ada sekutu bagiNya. Dan inilah yang dikehendaki oleh Allah SWT dalam firmanNya :"],["a","فَاعْلَمْ اَنَّهٗ لَآ اِلٰهَ اِلَّا اللّٰهُ وَاسْتَغْفِرْ لِذَنْۢبِكَ وَلِلْمُؤْمِنِيْنَ وَالْمُؤْمِنٰتِۚ وَاللّٰهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوٰىكُمْ . محمد : 19"],["p","Maka ketahuilah, bahwa sesungguhnya tidak ada Tuhan (Yang Hak) melainkan Allah dan mohonlah ampunan bagi dosamu dan bagi (dosa) orang-orang mukmin, laki-laki dan perempuan. Dan Allah mengetahui tempat kamu berusaha dan tempat tinggalmu. [QS. Muhammad : 19]"],["p","Orang-orang kafir Quraisy Makkah mengetahui makna kalimat tersebut, tetapi mereka membantah :"],["a","اَجَعَلَ الْاٰلِهَةَ اِلٰهًا وَّاحِدًا ۖ اِنَّ هٰذَا لَشَيْءٌ عُجَابٌ(5) وَانْطَلَقَ الْمَلَاُ مِنْهُمْ اَنِ امْشُوْا وَاصْبِرُوْا عَلٰٓى اٰلِهَتِكُمْ ۖ اِنَّ هٰذَا لَشَيْءٌ يُّرَادُ (6) ص :5 - 6"],["p","Mengapa ia menjadikan tuhan-tuhan itu Tuhan Yang satu saja? Sesungguhnya ini benar-benar suatu hal yang sangat mengherankan.(5)"],["p","Dan pergilah pemimpin-pemimpin mereka (seraya berkata): \"Pergilah kamu dan tetaplah (menyembah) tuhan-tuhanmu, sesungguhnya ini benar-benar suatu hal yang dikehendaki. (6) [QS. Shaad : 5-6]"],["p","Dan ada juga diantara kaum muslimin walaupun mereka itu sudah mengucapkan kalimat Laa ilaaha illallooh, mereka juga shalat, puasa berhajji, bersedekah, tetapi mereka masih melakukan ibadah-ibadah untuk selain Allah, misalnya dengan memohon pertolongan kepada para wali dan orang-orang shalih yang sudah wafat dan bernadzar untuk mereka, atau mereka berdo’a memohon kepada selain Allah. Mereka itu berarti belum mewujudkan makna Laa ilaaha illallooh, karena makna Laa ilaaha illallooh adalah seseorang melakukan ibadah dengan segala macamnya hanya untuk Allah yang Maha Esa, tidak ada sekutu bagiNya."],["p","Oleh karena itu orang yang masih suka beribadah untuk selain Allah, walaupun ia sudah mengucapkan Laa ilaaha illallooh, sudah melaksanakan shalat, puasa, hajji dan mengaku dirinya orang Islam, tetapi kalau masih suka beribadah untuk selain Allah berarti ia masih musyrik (mensekutukan Allah dengan yang lain). Karena seorang hamba tidaklah ia menjadi orang muslim yang benar, dan tidaklah terhindar dari kekalnya di neraka melainkan dengan iman yang murni yang tidak tercampur syirik dan tidak dirusak dengan kekafiran. Allah SWT berfirman :"],["a","اَلَّذِيْنَ اٰمَنُوْا وَلَمْ يَلْبِسُوْٓا اِيْمَانَهُمْ بِظُلْمٍ اُولٰۤىِٕكَ لَهُمُ الْاَمْنُ وَهُمْ مُّهْتَدُوْنَ. الانعام : 82"],["p","Orang-orang yang beriman dan tidak mencampur adukkan iman mereka dengan kedhaliman (syirik), mereka itulah orang-orang yang mendapat keamanan dan mereka itu adalah orang-orang yang mendapat petunjuk. [QS. Al An’aam : 82]"],["p","Dan barangsiapa yang menyembah atau beribadah kepada Allah tetapi masih menyembah atau beribadah kepada selainNya, maka ibadahnya itu tidak bermanfaat. Allah SWT berfirman :"],["a","وَلَقَدْ اُوْحِيَ اِلَيْكَ وَاِلَى الَّذِيْنَ مِنْ قَبْلِكَۚ لَىِٕنْ اَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُوْنَنَّ مِنَ الْخٰسِرِيْنَ. الزمر : 65"],["p","Dan sesungguhnya telah diwahyukan kepadamu dan kepada (nabi-nabi) yang sebelummu: \"Jika kamu mempersekutukan (Tuhan), niscaya akan hapuslah amalmu dan tentulah kamu termasuk orang-orang yang merugi. [QS. Az Zumar : 65]"],["a","ذٰلِكَ هُدَى اللّٰهِ يَهْدِيْ بِهٖ مَنْ يَّشَاۤءُ مِنْ عِبَادِهٖ ۗ وَلَوْ اَشْرَكُوْا لَحَبِطَ عَنْهُمْ مَّا كَانُوْا يَعْمَلُوْنَ. الانعام : 88"],["p","Itulah petunjuk Allah, yang dengannya Dia memberi petunjuk kepada siapa yang dikehendaki-Nya di antara hamba-hamba-Nya. Seandainya mereka mempersekutukan Allah, niscaya lenyaplah dari mereka amalan yang telah mereka kerjakan. [QS. Al An’aam : 88]"],["p","Makna Laa ilaaha illallooh mengandung syarath-syarath yang harus dilaksanakan :"],["p","1) Mengetahui makna Laa ilaaha illallooh dan yang dikehendaki dari kalimat tersebut. Karena kalimat Laa ilaaha illallooh itu berarti menafikan adanya tuhan yang berhak disembah atau diibadahi selain Allah, dan menetapkan bahwa hanya Allah yang berhak disembah atau diibadahi. Allah SWT berfirman :"],["a","فَاعْلَمْ اَنَّهٗ لَآ اِلٰهَ اِلَّا اللّٰهُ وَاسْتَغْفِرْ لِذَنْۢبِكَ وَلِلْمُؤْمِنِيْنَ وَالْمُؤْمِنٰتِۚ وَاللّٰهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوٰىكُمْ . محمد : 19"],["p","Maka ketahuilah, bahwa sesungguhnya tidak ada Tuhan (Yang Hak) melainkan Allah dan mohonlah ampunan bagi dosamu dan bagi (dosa) orang-orang mukmin, laki-laki dan perempuan. Dan Allah mengetahui tempat kamu berusaha dan tempat tinggalmu. [QS. Muhammad : 19]"],["p","Banyak diantara manusia sudah mengucapkan Laa ilaaha illallooh dengan lisannya tetapi tidak mengerti maknanya, sehingga ia terjerumus dalam kemusyrikan."],["p","2) Meyaqini dengan sepenuh hati ucapan Laa ilaaha illallooh tersebut, apabila ia masih ragu-ragu, maka tidaklah bermanfaat. Allah SWT berfirman :"],["a","اِنَّمَا الْمُؤْمِنُوْنَ الَّذِيْنَ اٰمَنُوْا بِاللّٰهِ وَرَسُوْلِهٖ ثُمَّ لَمْ يَرْتَابُوْا وَجَاهَدُوْا بِاَمْوَالِهِمْ وَاَنْفُسِهِمْ فِيْ سَبِيْلِ اللّٰهِ ۗ اُولٰۤىِٕكَ هُمُ الصّٰدِقُوْنَ. الحجرات : 15"],["p","Sesungguhnya orang-orang yang beriman hanyalah orang-orang yang beriman kepada Allah dan Rasul-Nya kemudian mereka tidak ragu-ragu dan mereka berjihad dengan harta dan jiwa mereka pada jalan Allah, mereka itulah orang-orang yang benar. [QS. Al Hujuraat : 15]"],["p","3) Ikhlash, tidak menyekutukanNya dengan sesuatupun, tidak riyaa’ dan tidak sum’ah. Allah SWT berfirman :"],["a","وَمَآ اُمِرُوْٓا اِلَّا لِيَعْبُدُوا اللّٰهَ مُخْلِصِيْنَ لَهُ الدِّيْنَ ۙ حُنَفَاۤءَ وَيُقِيْمُوا الصَّلٰوةَ وَيُؤْتُوا الزَّكٰوةَ وَذٰلِكَ دِيْنُ الْقَيِّمَةِ . البينة : 5"],["p","Padahal mereka tidak disuruh kecuali supaya menyembah Allah dengan memurnikan ketha’atan kepada-Nya dalam (menjalankan) agama dengan lurus, dan supaya mereka mendirikan shalat dan menunaikan zakat; dan yang demikian itulah agama yang lurus. [QS. Al Bayyinah : 5]"],["p","4) Mengucapkan Laa ilaaha illallooh dari lubuk hatinya, tidak berdusta. Allah SWT berfirman :"],["a","اَحَسِبَ النَّاسُ اَنْ يُّتْرَكُوْٓا اَنْ يَّقُوْلُوْٓا اٰمَنَّا وَهُمْ لَا يُفْتَنُوْنَ (2)وَلَقَدْ فَتَنَّا الَّذِيْنَ مِنْ قَبْلِهِمْ فَلَيَعْلَمَنَّ اللّٰهُ الَّذِيْنَ صَدَقُوْا وَلَيَعْلَمَنَّ الْكٰذِبِيْنَ(3) العنكبوت :2-3"],["p","Apakah manusia itu mengira bahwa mereka dibiarkan (saja) mengatakan: \"Kami telah beriman\", sedang mereka tidak diuji lagi? (2)"],["p","Dan sesungguhnya Kami telah menguji orang-orang yang sebelum mereka, maka sesungguhnya Allah mengetahui orang-orang yang benar dan sesungguhnya Dia mengetahui orang-orang yang dusta.(3) [QS. Al ‘Ankabuut : 2-3]"],["p","5) Mencintai kalimat Laa ilaaha illallooh dan apa yang ditunjukkannya. Allah SWT berfirman :"],["a","وَمِنَ النَّاسِ مَنْ يَّتَّخِذُ مِنْ دُوْنِ اللّٰهِ اَنْدَادًا يُّحِبُّوْنَهُمْ كَحُبِّ اللّٰهِ ۗ وَالَّذِيْنَ اٰمَنُوْٓا اَشَدُّ حُبًّا لِّلّٰهِ ۙ وَلَوْ يَرَى الَّذِيْنَ ظَلَمُوْٓا اِذْ يَرَوْنَ الْعَذَابَۙ اَنَّ الْقُوَّةَ لِلّٰهِ جَمِيْعًا ۙ وَّاَنَّ اللّٰهَ شَدِيْدُ الْعَذَابِ. البقرة : 165"],["p","Dan di antara manusia ada orang-orang yang menyembah tandingan-tandingan selain Allah; mereka mencintainya sebagaimana mereka mencintai Allah. Adapun orang-orang yang beriman sangat cinta kepada Allah. Dan jika seandainya orang-orang yang berbuat dhalim itu mengetahui ketika mereka melihat siksa (pada hari qiyamat), bahwa kekuatan itu kepunyaan Allah semuanya dan bahwa Allah amat berat siksaan-Nya (niscaya mereka menyesal). [QS. Al Baqarah : 165]"],["p","6) Melaksanakan amal-amal yang ditunjukkan oleh kalimat Laa ilaaha illallooh. Allah SWT berfirman :"],["a","وَمَنْ اَحْسَنُ دِيْنًا مِّمَّنْ اَسْلَمَ وَجْهَهٗ لِلّٰهِ وَهُوَ مُحْسِنٌ وَّاتَّبَعَ مِلَّةَ اِبْرٰهِيْمَ حَنِيْفًا ۗ وَاتَّخَذَ اللّٰهُ اِبْرٰهِيْمَ خَلِيْلًا. النساء : 125"],["p","Dan siapakah yang lebih baik agamanya daripada orang yang ikhlas menyerahkan dirinya kepada Allah, sedang dia pun mengerjakan kebaikan, dan ia mengikuti agama Ibrahim yang lurus? Dan Allah mengambil Ibrahim menjadi kesayangan-Nya.[QS. An Nisaa’ : 125]"],["p","7) Menyembah atau beribadah hanya untuk Allah yang Maha Esa, tidak ada sekutu bagiNya. Dan meninggalkan semua peribadatan untuk selain Allah. Walaupun sudah mengucap Laa ilaaha illallooh, tetapi apabila masih melakukan ibadah-ibadah untuk selain Allah, maka ia termasuk orang orang yang disebutkan oleh Allah :"],["a","اِنَّهُمْ كَانُوْٓا اِذَا قِيْلَ لَهُمْ لَآ اِلٰهَ اِلَّا اللّٰهُ يَسْتَكْبِرُوْنَ .الصافات : 35"],["p","Sesungguhnya mereka dahulu apabila dikatakan kepada mereka: \"Laa ilaaha illallooh\" (Tiada Tuhan yang berhak disembah melainkan Allah) mereka menyombongkan diri.[QS. Ash Shaaffaat : 35]"],["p","8) Mengkufuri apa yang disembah selain Allah berupa Thaaghuut dan menetapkan menyembah atau beribadah hanya untuk Allah yang Maha Esa. Allah SWT berfirman :"],["a","لَآ اِكْرَاهَ فِى الدِّيْنِۗ قَدْ تَّبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ ۚ فَمَنْ يَّكْفُرْ بِالطَّاغُوْتِ وَيُؤْمِنْۢ بِاللّٰهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقٰى لَا انْفِصَامَ لَهَا ۗ وَاللّٰهُ سَمِيْعٌ عَلِيْمٌ . البقرة : 256"],["p","Tidak ada paksaan untuk (memasuki) agama (Islam); sesungguhnya telah jelas jalan yang benar daripada jalan yang sesat. Karena itu barangsiapa yang ingkar kepada Thaaghuut dan beriman kepada Allah, maka sesungguhnya ia telah berpegang kepada buhul tali yang amat kuat yang tidak akan putus. Dan Allah Maha Mendengar lagi Maha Mengetahui. [QS. Al Baqarah : 256]"],["p","(Bersambung)"]],"c20220918_1299":[["p","Ahad, 18 September 2022/ 21 Shafar 1444 Brosur No.: 2094/2134/IA"],["h","MAKNA “LAA ILAAHA ILLALLOOH” (2)"],["p","Diantara keutamaan Laa ilaaha illallooh :"],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَقِّنُوْا مَوْتَاكُمْ: لَا اِلٰهَ اِلَّا اللّٰهُ. مسلم 2: 631 رقم 1"],["p","Dari Abu Sa’id Al-Khudriy, ia berkata : Rasulullah SAW bersabda, “Talqinkanlah orang-orang yang akan mati diantara kalian dengan kalimat Laa ilaaha illallooh”. [HR. Muslim juz 2, hal. 631, no. 1]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَقِّنُوْا مَوْتَاكُمْ: لَا اِلٰهَ اِلَّا اللّٰهُ. مسلم 2: 631 رقم 2"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Talqinkanlah orang-orang yang akan mati diantara kalian dengan kalimat laa ilaaha illallooh”. [HR. Muslim juz 2, hal. 631, no. 2],"],["a","عَنْ مُعَاذٍ بْنِ جَبَلٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ كَانَ اٰخِرُ كَلَامِهِ لَا اِلٰهَ اِلَّا اللّٰهُ دَخَلَ اْلجَنَّةَ. ابو داود 3: 190، رقم: 3116"],["p","Dari Mu'adz bin Jabal, ia berkata : Rasulullah SAW bersabda, “Barangsiapa yang akhir ucapannya itu laa ilaaha illallooh, maka ia masuk surga\". [HR. Abu Dawud juz 3, hal. 190, no. 3116]"],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِيِّ عَنِ النَّبِيِّ ﷺ قَالَ: لَقِّنُوْا مَوْتَاكُمْ لَا اِلٰهَ اِلَّا اللّٰهُ. الترمذى 2: 225، رقم: 983، حديث حسن صحيح"],["p","Dari Abu Sa'id Al-Khudriy, dari Nabi SAW, beliau bersabda, “Talqinkanlah orang-orang yang akan mati diantara kalian dengan kalimat laa ilaaha illallooh\". [HR. Tirmidzi juz 2, hal. 225, no. 983, hadits hasan shahih]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَقِّنُوْا مَوْتَاكُمْ: لَا اِلٰهَ اِلَّا اللّٰهُ. فَاِنَّهُ مَنْ كَانَ اٰخِرُ كَلِمَتِهِ لَا اِلٰهَ اِلَّا اللّٰهُ عِنْدَ الْمَوْتِ دَخَلَ الْجَنَّةَ، يَوْمًا مِنَ الدَّهْرِ وَاِنْ اَصَابَهُ قَبْلَ ذٰلِكَ مَا اَصَابَهُ. ابن حبان 7: 272، رقم: 3004"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Talqinkanlah orang-orang yang akan mati diantara kalian dengan kalimat laa ilaaha illallooh”, karena barangsiapa yang akhir ucapannya laa ilaaha illallooh ketika akan mati, ia masuk surga, satu hari itu (lebih bermanfaat) daripada sepanjang hidupnya, meskipun sebelumnya ia telah melakukan perbuatan apa saja. [HR. Ibnu Hibban juz 7, hal. 272, no. 3004]"],["a","عَنِ ابْنِ شِهَابٍ قَالَ: اَخْبَرَنِيْ سَعِيْدُ بْنُ الْمُسَيَّبِ عَنْ اَبِيْهِ قَالَ: لَمَّا حَضَرَتْ اَبَا طَالِبٍ الْوَفَاةُ جَاءَهُ رَسُوْلُ اللهِ ﷺ ، فَوَجَدَ عِنْدَهُ اَبَا جَهْلٍ وَعَبْدَ اللهِ بْنَ اَبِيْ اُمَيَّةَ بْنِ الْمُغِيْرَةِ، فَقَالَ رَسُوْلُ اللهِ ﷺ: يَا عَمِّ، قُلْ: لَا اِلٰهَ اِلَّا اللّٰهُ ، كَلِمَةً اَشْهَدُ لَكَ بِـهَا عِنْدَ اللهِ. فَقَالَ اَبُوْ جَهْلٍ وَعَبْدُ اللهِ بْنُ اَبِيْ اُمَيَّةَ: يَا اَبَا طَالِبٍ، اَتَرْغَبُ عَنْ مِلَّةِ عَبْدِ الْمُطَّلِبِ؟ فَلَمْ يَزَلْ رَسُوْلُ اللهِ ﷺ يَعْرِضُهَا عَلَيْهِ وَيُعِيْدُ لَهُ تِلْكَ الْمَقَالَةَ، حَتَّى قَالَ اَبُوْ طَالِبٍ آخِرَ مَا كَلَّمَهُمْ هُوَ عَلَى مِلَّةِ عَبْدِ الْمُطَّلِبِ، وَاَبَى اَنْ يَقُوْلَ: لَا اِلٰهَ اِلَّا اللّٰهُ . فَقَالَ رَسُوْلُ اللهِ ﷺ: اَمَا وَاللهِ، لَاَسْتَغْفِرَنَّ لَكَ مَا لَـمْ اُنْهَ عَنْكَ. فَاَنْزَلَ اللهُ عَزَّ وَجَلَّ: مَا كَانَ لِلنَّبِيِّ وَالَّذِيْنَ اٰمَنُوْآ اَنْ يَّسْتَغْفِرُوْا لِلْمُشْرِكِيْنَ وَلَوْ كَانُوْآ اُولِيْ قُرْبٰى مِنْ بَعْدِ مَا تَبَيَّنَ لَـهُمْ اَنَّـهُمْ اَصْحٰبُ الْجَحِيْمِ (التوبة: 113)، وَاَنْزَلَ اللهُ تَعَالَى فِيْ اَبِيْ طَالِبٍ، فَقَالَ لِرَسُوْلِ اللهِ ﷺ : اِنَّكَ لَا تَـهْدِيْ مَنْ اَحْبَبْتَ وَلٰكِنَّ اللهَ يَهْدِيْ مَنْ يَّشَآءُ، وَهُوَ اَعْلَمُ بِالْمُهْتَدِيْنَ. مسلم 1: 54 رقم 39"],["p","Dari Ibnu Syihab, ia berkata : Telah mengkhabarkan kepadaku Sa’id bin Al-Musayyab dari ayahnya, ia berkata, \"Ketika Abu Thalib menjelang sakaratul maut, Rasulullah SAW menjenguknya. Beliau mendapati Abu Jahal dan Abdullah bin Abu Umayyah bin Al-Mughirah sudah berada di dekatnya. Rasulullah SAW bersabda, \"Wahai paman, ucapkanlah “laa ilaaha illallooh” kalimat yang dengannya aku menjadi saksi untukmu di hadapan Allah”. Lalu Abu Jahal dan Abdullah bin Abu Umayyah berkata, 'Wahai Abu Thalib, apakah kamu benci kepada agama Abdul Muththalib ?”. Rasulullah SAW tidak henti-hentinya menganjurkan supaya mengucap “laa ilaaha illallooh” dan beliau mengulang-ulang kalimat itu, sehingga Abu Thalib mengatakan sebagai ucapan terakhir kepada mereka, bahwa dia tetap pada agama Abdul Muththalib, dan enggan mengucapkan “laa ilaaha illallooh”. Kemudian Rasulullah SAW bersabda: \"Demi Allah, sungguh aku akan memohonkan ampun (kepada Allah) untukmu selama aku belum dilarang”. Kemudian Allah ‘Azza wa Jalla menurunkan ayat, maa kaana linnabiyyi walladdziina aamanuu ayyastaghfiruu lilmusyrikiina walau kaanuu ulii qurbaa min ba’di maa tabayyana lahum annahum ashhaabul jahiim“ (Tidak pantas bagi Nabi dan orang-orang yang beriman memintakan ampun (kepada Allah) bagi orang-orang musyrik walaupun orang-orang musyrik itu kaum kerabatnya setelah nyata bagi mereka bahwa orang-orang musyrik itu adalah penghuni neraka Jahiim)”. (QS. At-Taubah : 113). Dan Allah Ta’aalaa menurunkan ayat berkenaan dengan peristiwa Abu Thalib, Allah berfirman kepada Rasulullah SAW. innaka laa tahdii man ahbabta walaakinnallooha yahdii mayyasyaa’u wa huwa a’lamu bilmuhtadiin “(Sesungguhnya kamu tidak dapat memberi petunjuk kepada orang yang kamu kasihi, tetapi Allah memberi petunjuk kepada orang yang dikehendaki-Nya, dan Allah lebih mengetahui orang-orang yang mau menerima petunjuk)”. (QS. Al-Qashash : 56). [HR. Muslim juz 1, hal. 54, no. 39]"],["a","عَنِ ابْنِ شِهَابٍ قَالَ: اَخْبَرَنِيْ سَعِيْدُ بْنُ الْمُسَيَّبِ عَنْ اَبِيْهِ قَالَ: لَمَّا حَضَرَ اَبَا طَالِبٍ الْوَفَاةُ جَاءَ رَسُوْلُ اللهِ ﷺ فَوَجَدَ عِنْدَهُ اَبَا جَهْلٍ وَعَبْدَ اللهِ بْنَ اَبِيْ اُمَيَّةَ بْنِ الْمُغِيْرَةِ، فَقَالَ رَسُوْلُ اللهِ ﷺ: يَا عَمِّ، قُلْ: لَا اِلٰهَ اِلَّا اللّٰهُ ، اَشْهَدُ لَكَ بِـهَا عِنْدَ اللهِ. قَالَ اَبُوْ جَهْلٍ وَعَبْدُ اللهِ بْنُ اَبِيْ اُمَيَّةَ: يَا اَبَا طَالِبٍ، اَتَرْغَبُ عَنْ مِلَّةِ عَبْدِ الْمُطَّلِبِ؟ قَالَ: فَلَمْ يَزَلِ النَّبِيُّ ﷺ يَعْرِضُهَا عَلَيْهِ وَيُعِيْدُ لَهُ تِلْكَ الْمَقَالَةَ، حَتَّى قَالَ اَبُوْ طَالِبٍ آخِرَ مَا كَلَّمَهُمْ هُوَ عَلَى مِلَّةِ عَبْدِ الْمُطَّلِبِ وَاَبَى اَنْ يَقُوْلَ: لَا اِلٰهَ اِلَّا اللّٰهُ. فَقَالَ رَسُوْلُ اللهِ ﷺ: لَاَسْتَغْفِرَنَّ لَكَ مَا لَـمْ اُنْهَ عَنْكَ. فَاَنْزَلَ اللهُ: مَا كَانَ لِلنَّبِيِّ وَالَّذِيْنَ آمَنُوْآ اَنْ يَّسْتَغْفِرُوْا لِلْمُشْرِكِيْنَ وَلَوْ كَانُوْآ اُولِيْ قُرْبٰى مِنْ بَعْدِ مَا تَبَيَّنَ لَـهُمْ اَنَّـهُمْ اَصْحٰبُ الْجَحِيْمِ. (التوبة: 113), وَاُنْزِلَتْ فِيْ اَبِيْ طَالِبٍ: اِنَّكَ لَا تَـهْدِيْ مَنْ اَحْبَبْتَ وَلٰكِنَّ اللهَ يَهْدِيْ مَنْ يَّشَآءُ، وَهُوَ اَعْلَمُ بِالْمُهْتَدِيْنَ. (القصص: 56) ابن حبان 3: 262، رقم: 982"],["p","Dari Ibnu Syihab, ia berkata : Telah mengkhabarkan kepadaku Sa’id bin Al-Musayyab dari ayahnya, ia berkata, \"Ketika Abu Thalib menjelang sakaratul maut, Rasulullah SAW menjenguknya. Beliau mendapati Abu Jahal dan Abdullah bin Abu Umayyah bin Al-Mughirah sudah berada di dekatnya. Rasulullah SAW bersabda, \"Wahai paman, ucapkanlah “laa ilaaha illallooh” kalimat yang dengannya aku menjadi saksi untukmu di hadapan Allah”. Lalu Abu Jahal dan Abdullah bin Abu Umayyah berkata, 'Wahai Abu Thalib, apakah kamu benci kepada agama Abdul Muththalib ?”. Nabi SAW tidak henti-hentinya menganjurkan supaya mengucap “laa ilaaha illallooh” dan beliau mengulang-ulang kalimat itu, sehingga Abu Thalib mengatakan sebagai ucapan terakhir kepada mereka, bahwa dia tetap pada agama Abdul Muththalib, dan enggan mengucapkan “laa ilaaha illallooh”. Kemudian Rasulullah SAW bersabda: \"(Demi Allah), sungguh aku akan memohonkan ampun (kepada Allah) untukmu selama aku belum dilarang”. Kemudian Allah menurunkan ayat, maa kaana linnabiyyi walladdziina aamanuu ayyastaghfiruu lilmusyrikiina walau kaanuu ulii qurbaa min ba’di maa tabayyana lahum annahum ashhaabul jahiim“ (Tidak pantas bagi Nabi dan orang-orang yang beriman memintakan ampun (kepada Allah) bagi orang-orang musyrik walaupun orang-orang musyrik itu kaum kerabatnya setelah nyata bagi mereka bahwa orang-orang musyrik itu adalah penghuni neraka Jahiim)”. (QS. At-Taubah : 113). Lalu diturunkan ayat berkenaan dengan peristiwa Abu Thalib ayat innaka laa tahdii man ahbabta walaakinnallooha yahdii mayyasyaa’u wa huwa a’lamu bilmuhtadiin “(Sesungguhnya kamu tidak dapat memberi petunjuk kepada orang yang kamu kasihi, tetapi Allah memberi petunjuk kepada orang yang dikehendaki-Nya, dan Allah lebih mengetahui orang-orang yang mau menerima petunjuk)”. (QS. Al-Qashash : 56). [HR. Ibnu Hibban juz 3, hal. 262, no. 982]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اَلْاِيْمَانُ بِضْعٌ وَسَبْعُوْنَ اَوْ بِضْعٌ وَسِتُّوْنَ شُعْبَةً، فَاَفْضَلُهَا قَوْلُ لَا اِلٰهَ اِلَّا اللّٰهُ، وَاَدْنَاهَا اِمَاطَةُ اْلاَذَى عَنِ الطَّرِيْقِ، وَاْلحَيَاءُ شُعْبَةٌ مِنَ اْلاِيْمَانِ. مسلم 1: 63 رقم 58"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Iman itu ada tujuh puluh cabang lebih atau enam puluh cabang lebih. Yang paling utama ialah ucapan Laa ilaaha illallooh (Tidak ada Tuhan selain Allah), dan yang paling rendah ialah menyingkirkan gangguan di jalan, dan malu adalah salah satu cabang dari iman\". [HR. Muslim juz 1, hal. 63, no. 58]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اَلْاِيْمَانُ بِضْعٌ وَسِتُّوْنَ اَوْ سَبْعُوْنَ بَابًا، اَدْنَاهَا اِمَاطَةُ اْلاَذَى عَنِ الطَّرِيْقِ، وَاَرْفَعُهَا قَوْلُ لَا اِلٰهَ اِلَّا اللّٰهُ، وَاْلحَيَاءُ شُعْبَةٌ مِنَ اْلاِيْمَانِ. ابن ماجه 1: 22، رقم: 57"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Iman itu ada enam puluh cabang lebih atau tujuh puluh cabang lebih. Yang paling rendah adalah menyingkirkan gangguan dari jalan, dan yang paling tinggi ialah ucapan Laa ilaaha illallooh (Tidak ada Tuhan selain Allah), dan malu adalah salah satu cabang dari iman \". [HR. Ibnu Majah juz 1, hal. 22, no. 57]"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ : اَفْضَلُ الذِّكْرِ لَا اِلٰهَ اِلَّا اللهُ وَ اَفْضَلُ الدُّعَاءِ اَلْحَمْدُ لِلّٰهِ . ابن ماجه 2 : 1249 رقم 3800"],["p","Dari Jabir bin ‘Abdullah, ia berkata: Aku mendengar Rasulullah SAW bersabda : “ Dzikir yang paling utama adalah ucapan Laa ilaaha illallooh” (Tidak ada Tuhan selain Allah) dan do’a yang paling utama adalah “Alhamdulillaah” (Surat Al Faatihah). [HR. Ibnu Majah juz 2, hal. 1249, no. 3800]"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ : اَفْضَلُ الذِّكْرِ لَا اِلٰهَ اِلَّا اللهُ وَ اَفْضَلُ الدُّعَاءِ اَلْحَمْدُ لِلّٰهِ . الترمذى 5 : 13- رقم 3443"],["p","Dari Jabir bin ‘Abdullah, ia berkata: Aku mendengar Rasulullah SAW bersabda : “ Dzikir yang paling utama adalah ucapan Laa ilaaha illallooh” (Tidak ada Tuhan selain Allah) dan do’a yang paling utama adalah “Alhamdulillaah” (Surat Al Faatihah). [HR. Tirmidzi juz 5, hal. 130, no. 3443]"],["a","عَنْ سَمُرَةَ بْنِ جُنْدَبٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اَحَبُّ الْكَلَامِ اِلَى اللهِ اَرْبَعٌ : سُبْحَانَ اللهِ، وَ الْحَمْدُ لِلّٰهِ، وَ لَا اِلٰهَ اِلَّا اللّٰهُ ، وَ اللهُ اَكْبَرُ، لَا يَضُرُّكَ بِاَيِّهِنَّ بَدَأْتَ. مسلم 3 :1685 رقم 12"],["p","Dari Samurah bin Jundab, ia berkata : Rasulullah SAW bersabda, “Ucapan yang paling disukai Allah itu ada empat. (yaitu) Subhaanallooh, wal hamdu lillaah, wa Laa ilaaha illallooh, walloohu akbar (Maha suci Allah, segala puji bagi Allah, tidak ada Tuhan selain Allah, dan Allah Maha Besar). Tidak mengapa kamu memulai membaca dari mana saja. [HR. Muslim juz 3, hal. 1685, no. 12]."],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : لَاَنْ اَقُوْلَ: سُبْحَانَ اللهِ، وَ الْحَمْدُ لِلّٰهِ وَ لَا اِلٰهَ اِلَّا اللّٰهُ وَ اللهُ اَكْبَرُ اَحَبُّ اِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ. مسلم 4 : 2072 رقم 32"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Sungguh aku membaca Subhaanalloohi wal-hamdu lillaah wa laa ilaaha illallooh walloohu akbar, yang demikian itu lebih aku senangi daripada apa-apa yang disinari matahari (dunia)”. [HR. Muslim juz 4, hal. 2072, no. 32]."],["p","--oo0oo--"]],"c20220925_1300":[["p","Ahad, 25 September 2022 /28 Shafar 1444 Brosur No. : 2095/2135/IF"],["p","Tentang Riba"],["h","1. Pengertian Riba"],["p","Riba menurut bahasa berasal dari kata rabaa–yarbuu–riban, artinya tambahan,"],["p","Riba menurut syara' adalah tambahan tertentu pada tukar-menukar barang ribawiy, atau tambahan tertentu pada harta pokok yang disyaratkan pada hutang-piutang karena adanya penangguhan waktu pembayaran hutang."],["h","2. Hukum Riba"],["p","Riba hukumnya haram, berdasarkan nash-nash sebagai berikut :"],["a","اَلَّذِيْنَ يَأْكُلُوْنَ الرِّبٰوا لَا يَقُوْمُوْنَ اِلَّا كَمَا يَقُوْمُ الَّذِيْ يَتَخَبَّطُهُ الشَّيْطٰنُ مِنَ الْمَسِّ ۗ ذٰلِكَ بِاَنَّهُمْ قَالُوْٓا اِنَّمَا الْبَيْعُ مِثْلُ الرِّبٰواۘ وَاَحَلَّ اللّٰهُ الْبَيْعَ وَحَرَّمَ الرِّبٰواۗ فَمَنْ جَاۤءَهٗ مَوْعِظَةٌ مِّنْ رَّبِّهٖ فَانْتَهٰى فَلَهٗ مَا سَلَفَۗ وَاَمْرُهٗٓ اِلَى اللّٰهِ ۗ وَمَنْ عَادَ فَاُولٰۤىِٕكَ اَصْحٰبُ النَّارِ ۚ هُمْ فِيْهَا خٰلِدُوْنَ .البقرة: 275"],["p","Orang-orang yang makan (mengambil) riba tidak dapat berdiri melainkan seperti berdirinya orang yang kemasukan syaithan lantaran (tekanan) penyakit gila. Keadaan mereka yang demikian itu, adalah disebabkan mereka berkata (berpendapat), sesungguhnya jual-beli itu sama dengan riba, padahal Allah telah menghalalkan jual-beli dan mengharamkan riba. Orang-orang yang telah sampai kepadanya larangan dari Tuhannya, lalu terus berhenti (dari mengambil riba), maka baginya apa yang telah diambilnya dahulu (sebelum datang larangan); dan urusannya (terserah) kepada Allah. Orang yang mengulangi (mengambil riba), maka orang itu adalah penghuni-penghuni neraka; mereka kekal di dalamnya. [QS. Al-Baqarah : 275]"],["a","يَمْحَقُ اللّٰهُ الرِّبٰوا وَيُرْبِى الصَّدَقٰتِ ۗ وَاللّٰهُ لَا يُحِبُّ كُلَّ كَفَّارٍ اَثِيْمٍ. البقرة: 276"],["p","Allah memusnahkan riba dan menyuburkan shadaqah. Dan Allah tidak menyukai setiap orang yang tetap dalam kekafiran, dan selalu berbuat dosa. [QS. Al-Baqarah : 276]"],["a","اِنَّ الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ وَاَقَامُوا الصَّلٰوةَ وَاٰتَوُا الزَّكٰوةَ لَهُمْ اَجْرُهُمْ عِنْدَ رَبِّهِمْۚ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُوْنَ . البقرة: 277."],["p","Sesungguhnya orang-orang yang beriman, mengerjakan amal shalih, mendirikan shalat dan menunaikan zakat, mereka mendapat pahala di sisi Tuhannya. Tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati. [QS. Al-Baqarah : 277]"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَذَرُوْا مَا بَقِيَ مِنَ الرِّبٰوٓا اِنْ كُنْتُمْ مُّؤْمِنِيْنَ. البقرة: 278"],["p","Hai orang-orang yang beriman, bertaqwalah kepada Allah dan tinggalkan sisa riba (yang belum dipungut) jika kamu orang-orang yang beriman. [QS. Al-Baqarah : 278]"],["a","فَاِنْ لَّمْ تَفْعَلُوْا فَأْذَنُوْا بِحَرْبٍ مِّنَ اللّٰهِ وَرَسُوْلِهٖۚ وَاِنْ تُبْتُمْ فَلَكُمْ رُءُوْسُ اَمْوَالِكُمْۚ لَا تَظْلِمُوْنَ وَلَا تُظْلَمُوْنَ. البقرة : 279"],["p","Maka jika kamu tidak mengerjakan (meninggalkan sisa riba), maka ketahuilah, bahwa Allah dan Rasul-Nya akan memerangimu. Dan jika kamu bertaubat (dari pengambilan riba), maka bagimu pokok hartamu; kamu tidak menganiaya dan tidak (pula) dianiaya. [QS. Al-Baqarah : 279]"],["a","وَاِنْ كَانَ ذُوْ عُسْرَةٍ فَنَظِرَةٌ اِلٰى مَيْسَرَةٍ ۗ وَاَنْ تَصَدَّقُوْا خَيْرٌ لَّكُمْ اِنْ كُنْتُمْ تَعْلَمُوْنَ. البقرة: 280"],["p","Dan jika (orang berhutang itu) dalam kesukaran, maka berilah tangguh sampai dia berkelapangan. Dan menyedekahkan (sebagian atau semua hutang) itu, lebih baik bagimu, jika kamu mengetahui. [QS. Al-Baqarah : 280]"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تَأْكُلُوا الرِّبٰوٓا اَضْعَافًا مُّضٰعَفَةً ۖ وَّاتَّقُوا اللّٰهَ لَعَلَّكُمْ تُفْلِحُوْنَ. ال عمران: 130"],["p","Hai orang-orang yang beriman, janganlah kamu memakan riba dengan berlipat ganda dan bertakwalah kamu kepada Allah supaya kamu mendapat keberuntungan. [QS. Ali 'Imraan : 130]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ اَبِيْ هُرَيْرَةَ عَنِ النَّبِيِّ ﷺ قَالَ: اِجْتَنِبُوا السَّبْعَ الْمُوْبِقَاتِ. قَالُوْا: يَا رَسُوْلَ اللهِ، وَمَا هُنَّ؟ قَالَ: اَلشِّرْكُ بِاللهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِى حَرَّمَ اللهُ اِلَّا بِالْحَقِّ، وَاَكْلُ الرِّبَا، وَاَكْلُ مَالِ الْيَتِيْمِ، وَالتَّوَلِّى يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ الْغَافِلَاتِ. البخارى 8: 33"],["p","Dari Abu Hurairah, dari Nabi SAW, beliau bersabda, \"Jauhilah tujuh perkara yang membinasakan”. Para shahabat bertanya, “Wahai Rasulullah, apa tujuh perkara itu ?”. Beliau bersabda, “1. Menyekutukan Allah, 2. Sihir, 3. Membunuh jiwa yang diharamkan oleh Allah kecuali dengan alasan yang dibenarkan, 4. Memakan riba, 5. Memakan harta anak yatim, 6. Melarikan diri dari medan peperangan, 7. Menuduh wanita mu'minat yang menjaga kehormatannya lagi baik-baik berbuat zina”. [HR. Bukhari juz 8, hal. 33]"],["a","عَنْ سَمُرَةَ بْنِ جُنْدَبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ ﷺ: رَأَيْتُ اللَّيْلَةَ رَجُلَيْنِ اَتَيَانِيْ فَاَخْرَجَانِيْ اِلَى اَرْضٍ مُقَدَّسَةٍ، فَانْطَلَقْنَا حَتَّى اَتَيْنَا عَلَى نَـهَرٍ مِنْ دَمٍ فِيْهِ رَجُلٌ قَائِمٌ وَعَلَى وَسَطِ النَّهَرِ رَجُلٌ بَيْنَ يَدَيْهِ حِجَارَةٌ، فَاَقْبَلَ الرَّجُلُ الَّذِيْ فِي النَّهَرِ، فَاِذَا اَرَادَ اَنْ يَخْرُجَ رَمَى الرَّجُلُ بِحَجَرٍ فِيْ فِيْهِ، فَرَدَّهُ حَيْثُ كَانَ، فَجَعَلَ كُلَّمَا جَاءَ لِيَخْرُجَ رَمَى فِي فِيْهِ بِحَجَرٍ، فَيَرْجِعُ كَمَا كَانَ. فَقُلْتُ: مَا هٰذَا؟ فَقَالَ: اَلَّذِيْ رَأَيْتَهُ فِي النَّهَرِ، آكِلُ الرِّبَا. البخارى 3: 11"],["p","Dari Samurah bin Jundab RA, ia berkata; Nabi SAW bersabda, “Pada suatu malam aku bermimpi ada dua orang laki-laki datang kepadaku lalu keduanya membawa aku keluar menuju ke tanah suci. Kemudian kami berangkat hingga tiba di suatu sungai yang airnya berupa darah. Disana ada seorang laki-laki yang berdiri di tengah sungai dan satu orang laki-laki lagi berada (di tepinya) dan didepannya ada (tumpukan) batu. Kemudian orang laki-laki yang berada di tengah-tengah sungai itu ingin keluar, tetapi setiap kali dia hendak keluar dari sungai, maka laki-laki yang di tepi sungai itu melemparinya dengan batu ke arah mulutnya hingga dia kembali ke tempatnya semula di tengah sungai. Begitulah seterusnya, setiap dia hendak keluar dari sungai, orang yang di tepi sungai itu melemparinya dengan batu ke mulutnya sehingga ia kembali ke tempatnya semula. Lalu aku bertanya: “Apa ini ?”. Maka orang yang aku lihat dalam mimpiku itu menjawab, “Orang yang engkau lihat di tengah sungai itu adalah pemakan riba'”. [HR. Bukhari, juz 3, hal. 11]"],["a","عَنْ جَابِرٍ قَالَ: لَعَنَ رَسُوْلُ اللهِ ﷺ آكِلَ الرِّبَا وَمُوْكِلَهُ وَكَاتِبَهُ وَشَاهِدَيْهِ، وَقَالَ: هُمْ سَوَاءٌ. مسلم 3: 1219، رقم: 106"],["p","Dari Jabir, ia berkata : Rasulullah SAW mela'nat pemakan riba, yang memberi makan riba, penulisnya, dan dua orang saksinya. Dan beliau bersabda, \"Mereka itu adalah sama\". [HR. Muslim juz 3, hal. 1219, no. 106]"],["a","عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ، اَنَّ رَسُولَ اللهِ ﷺ لَعَنَ آكِلَ الرِّبَا وَمُؤْكِلَهُ وَشَاهِدِيْهِ وَكَاتِبَهُ. ابن ماجه 2: 764 رقم 2277"],["p","Dari ‘Abdullah bin Mas'ud ia berkata, \"Rasulullah SAW mela’nat pemakan riba, yang memberi makan riba, dua orang saksinya dan penulisnya.\" [HR. Ibnu Majah juz 2, hal 764, no, 2277]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اَتَيْتُ لَيْلَةَ اُسْرِيَ بِيْ عَلَى قَوْمٍ بُطُوْنُهُمْ كَالْبُيُوْتِ فِيْهَا الْحَيَّاتُ تُرَى مِنْ خَارِجِ بُطُوْنِهِمْ. فَقُلْتُ: مَنْ هٰؤُلَاءِ يَا جِبْرَائِيلُ؟ قَالَ: هٰؤُلَاءِ اَكَلَةُ الرِّبَا. ابن ماجه 2: 763 رقم 2273"],["p","Dari Abu Hurairah, ia berkata, \"Rasulullah SAW bersabda: \"Pada malam Isra mi'raj aku mendatangi suatu kaum, perut mereka seperti rumah-rumah yang dihuni oleh ular dan dapat dilihat dari luar perut-perut mereka. Lalu aku bertanya: \"Wahai Jibril, siapakah mereka itu?\" Jibril menjawab, \"Mereka adalah para pemakan riba.\" [HR Ibnu Majah juz 2, hal. 763, no. 2273 dlo’if, karena dalam isnadnya ada perawi bernama ‘Aliy bin Zaid bin Jud’aan]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: اَلرِّبَا سَبْعُوْنَ حُوْبًا اَيْسَرُهَا اَنْ يَنْكِحَ الرَّجُلُ اُمَّهُ. ابن ماجه 2: 764 رقم 2274"],["p","Dari Abu Hurairah ia berkata, \"Rasulullah SAW bersabda: \"Riba itu mempunyai tujuh puluh tingkatan, yang paling ringan adalah seperti seseorang yang berzina dengan ibunya.\" [HR. Ibnu Majah juz 2, hal. 764, no 2274 dlo’if, karena dalam isnadnya ada perawi bernama Abu Ma’syar Najih bin ‘Abdurrahman]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : لَيَأْتِيَنَّ عَلَى النَّاسِ زَمَانٌ لَا يَبْقَى مِنْهُمْ اَحَدٌ اِلَّا آكِلُ الرِّبَا فَمَنْ لَمْ يَأْكُلْ اَصَابَهُ مِنْ غُبَارِهِ. ابن ماجه 2: 765 رقم 2278"],["p","Dari Abu Hurairah ia berkata, \"Rasulullah SAW bersabda: \"Sungguh akan datang kepada manusia suatu zaman, tidak seorang pun dari mereka kecuali akan memakan riba. Dan orang yang tidak memakannya, ia pun akan terkena debunya.\" [HR. Ibnu Majah juz 2, hal 765, no. 2278]"],["p","3. Riba ada 2 macam :"],["p","A. Riba Nasiiah (riba yang berkenaan dengan hutang-piutang)."],["p","B. Riba Fadhl (riba yang berkenaan dengan jual-beli atau tukar menukar barang ribawiy),"],["h","A. Riba Nasiiah"],["p","Riba Nasiiah ialah tambahan tertentu pada harta pokok yang disyaratkan pada hutang-piutang karena adanya penangguhan waktu pembayaran hutang. Misalnya : A berhutang kepada B dengan kesepakatan si A mengembalikan hutangnya itu dalam jangka 1 tahun dengan memberi tambahan (riba) kepada si B. Apabila telah jatuh tempo pelunasan maka si B mengatakan, \"Kamu mengembalikan harta pokok beserta tambahannya, atau kalau belum bisa kamu harus terus menerus memberikan tambahan (riba) sampai waktu kamu bisa mengembalikan hutang itu\". Di dalam hadits disebutkan :"],["a","عَنْ عُبَيْدِ اللهِ بْنِ اَبِيْ يَزِيْدَ اَنَّهُ سَمِعَ ابْنَ عَبَّاسٍ يَقُوْلُ: اَخْبَرَنِيْ اُسَامَةُ بْنُ زَيْدٍ اَنَّ النَّبِىَّ ﷺ قَالَ: اِنَّـمَا الرِّبَا فِى النَّسِيْئَةِ. مسلم 3: 1218، رقم: 102"],["p","Dari 'Ubaidillah bin Abu Yazid, bahwasanya ia mendengar Ibnu 'Abbas berkata : Usamah bin Zaid menceritakan kepadaku, bahwasanya Nabi SAW bersabda, \"Sesungguhnya riba itu pada hutang-piutang\". [HR. Muslim juz 3 hal. 1218, no. 102]"],["a","عَنْ عَطَاءِ بْنِ اَبِيْ رَبَاحٍ اَنَّ اَبَا سَعِيْدٍ الْخُدْرِىَّ لَقِىَ ابْنَ عَبَّاسٍ فَقَالَ لَهُ: اَرَأَيْتَ قَوْلَكَ فِى الصَّرْفِ، اَشَيْئًا سَمِعْتَهُ مِنْ رَسُوْلِ اللهِ ﷺ اَمْ شَيْئًا وَجَدْتَهُ فِيْ كِتَابِ اللهِ عَزَّ وَجَلَّ؟ فَقَالَ ابْنُ عَبَّاسٍ: كَلَّا لَا اَقُوْلُ. اَمَّا رَسُوْلُ اللهِ ﷺ فَاَنْتُمْ اَعْلَمُ بِهِ، وَاَمَّا كِتَابُ اللهِ فَلَا اَعْلَمُهُ. وَلٰكِنْ حَدَّثَنِيْ اُسَامَةُ بْنُ زَيْدٍ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اَلَا اِنَّـمَا الرِّبَا فِى النَّسِيْئَةِ. مسلم 3: 1218، رقم: 104"],["p","Dari 'Atha' bin Abu Rabah bahwasanya Abu Sa'id Al-Khudriy menemui Ibnu 'Abbas, lalu bertanya kepadanya, \"Apakah pendapatmu yang membolehkan tentang tukar-menukar barang yang sejenis (dengan tambahan) itu sesuatu yang engkau dengar dari Rasulullah SAW atau sesuatu yang engkau dapati di dalam kitab Allah 'Azza wa Jalla ?\". Ibnu 'Abbas menjawab, \"Tidak. Aku tidak mengatakan begitu. Adapun Rasulullah SAW, maka engkau lebih tahu terhadap beliau. Adapun dalam kitab Allah, aku tidak mengetahuinya, tetapi Usamah bin Zaid menceritakan kepadaku bahwasanya Rasulullah SAW bersabda, \"Ketahuilah, sesungguhnya riba itu hanya dalam hutang-piutang\". [HR. Muslim juz 3, hal. 1218, no. 104]"],["a","عَنْ اَبِيْ صَالِحٍ قَالَ: سَمِعْتُ اَبَا سَعِيْدٍ الْخُدْرِىَّ يَقُوْلُ: اَلدِّيْنَارُ بِالدِّيْنَارِ، وَالدِّرْهَمُ بِالدِّرْهَمِ، مِثْلًا بِـمِثْلٍ. مَنْ زَادَ اَوِ ازْدَادَ فَقَدْ اَرْبَى. فَقُلْتُ لَهُ: اِنَّ ابْنَ عَبَّاسٍ يَقُوْلُ غَيْرَ هٰذَا. فَقَالَ: لَقَدْ لَقِيْتُ ابْنَ عَبَّاسٍ، فَقُلْتُ: اَرَأَيْتَ هٰذَا الَّذِى تَقُوْلُ اَشَىْءٌ سَمِعْتَهُ مِنْ رَسُوْلِ اللهِ ﷺ اَوْ وَجَدْتَهُ فِيْ كِتَابِ اللهِ عَزَّ وَجَلَّ؟ فَقَالَ: لَـمْ اَسْمَعْهُ مِنْ رَسُوْلِ اللهِ ﷺ وَلَـمْ اَجِدْهُ فِيْ كِتَابِ اللهِ، وَلٰكِنْ حَدَّثَنِيْ اُسَامَةُ بْنُ زَيْدٍ اَنَّ النَّبِىَّ ﷺ قَالَ: اَلرِّبَا فِى النَّسِيْئَةِ. مسلم 3: 1217، رقم: 101"],["p","Dari Abu Shalih, ia berkata ; Saya mendengar Abu Sa'id Al-Khudriy berkata, \"Dinar dengan dinar, dirham dengan dirham, yang sepadan. Barangsiapa menambah atau ditambah, maka ia telah melakukan riba\". Lalu saya berkata kepadanya, \"Sesungguhnya Ibnu ‘Abbas mengatakan tidak seperti ini\". Lalu Abu Sa’id Al-Khudriy menjawab, \"Sungguh saya telah bertemu dengan Ibnu ‘Abbas, lalu saya berkata, \"Apakah yang kamu katakan itu sesuatu yang kamu pernah mendengar langsung dari Rasulullah SAW, atau yang kamu dapatkan di dalam Kitabullah 'Azza wa Jalla ?\". Ibnu 'Abbas menjawab, \"Saya tidak mendengar langsung dari Rasulullah SAW dan tidak pula saya dapatkan didalam Kitabullah, akan tetapi Usamah bin Zaid telah menceritakan kepadaku, bahwa Nabi SAW bersabda: \"Riba itu dalam hutang-piutang\". [HR. Muslim juz 3, hal. 1217, no. 101]"],["p","(Bersambung)"]],"c20221002_1301":[["p","Ahad, 02 Oktober 2022 /6 Rabii’ul Awwal 1444 Brosur No. : 2096/2136/IF"],["p","Tentang Riba"],["p","(lanjutan)"],["h","B. Riba Fadhl"],["p","Riba Fadhl adalah tambahan tertentu pada tukar-menukar barang ribawiy. Di dalam hadits disebutkan :"],["a","عَنْ عُبَادَةَ بْنِ الصَّامِتِ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اَلذَّهَبُ بِالذَّهَبِ، وَالْفِضَّةُ بِالْفِضَّةِ، وَالْبُرُّ بِالْبُرِّ، وَالشَّعِيْرُ بِالشَّعِيْرِ، وَالتَّمْرُ بِالتَّمْرِ، وَالْمِلْحُ بِالْمِلْحِ، مِثْلًا بِـمِثْلٍ سَوَاءً بِسَوَاءٍ يَدًا بِيَدٍ. فَاِذَا اخْتَلَفَتْ هٰذِهِ الْاَصْنَافُ فَبِيْعُوْا كَيْفَ شِئْتُمْ اِذَا كَانَ يَدًا بِيَدٍ. مسلم 3: 1211، رقم:81"],["p","Dari 'Ubaadah bin Shamit, ia berkata, \"Rasulullah SAW bersabda, 'Emas ditukar dengan emas, perak ditukar dengan perak, gandum yang bagus ditukar dengan gandum yang bagus, gandum biasa ditukar dengan gandum biasa, kurma ditukar dengan kurma, dan garam ditukar dengan garam, sepadan dan sama, dan serah terimanya pada saat itu juga. Apabila jenisnya berbeda, maka juallah sekehendak kalian asalkan dengan tunai dan serah terima langsung. [HR. Muslim juz 3, hal. 1211. No. 81]"],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِىِّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اَلذَّهَبُ بِالذَّهَبِ، وَالْفِضَّةُ بِالْفِضَّةِ، وَالْبُرُّ بِالْبُرِّ، وَالشَّعِيْرُ بِالشَّعِيْرِ، وَالتَّمْرُ بِالتَّمْرِ، وَالْمِلْحُ بِالْمِلْحِ، مِثْلًا بـِمِثْلٍ، يَدًا بِيَدٍ، فَمَنْ زَادَ اَوِ اسْتَزَادَ فَقَدْ اَرْبَى اَلْآخِذُ وَالْمُعْطِى فِيْهِ سَوَاءٌ. مسلم 3: 1211، رقم: 82"],["p","Dari Abu Sa'id Al-Khudriy, ia berkata : Rasulullah SAW bersabda, \"Emas ditukar dengan emas, perak dengan perak, gandum yang bagus dengan gandum yang bagus, gandum yang biasa dengan gandum yang biasa, kurma dengan kurma, garam dengan garam, yang sepadan dan secara kontan. Barangsiapa yang menambah atau minta ditambah, maka sungguh ia telah berbuat riba, baik yang meminta maupun yang memberi, padanya adalah sama\". [HR. Muslim juz 3, hal. 1211. No. 82]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اَلتَّمْرُ بِالتَّمْرِ، وَالْحِنْطَةُ بِالْحِنْطَةِ، وَالشَّعِيْرُ بِالشَّعِيْرِ، وَالْمِلْحُ بِالْمِلْحِ مِثْلًا بِـمِثْلٍ، يَدًا بِيَدٍ، فَمَنْ زَادَ اَوِ اسْتَزَادَ فَقَدْ اَرْبَى اِلَّا مَا اخْتَلَفَتْ اَلْوَانُهُ. مسلم 3: 1211، رقم: 83"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Kurma dengan kurma, gandum yang bagus dengan gandum yang bagus, gandum yang biasa dengan gandum yang biasa, garam dengan garam, sepadan dan kontan. Barangsiapa yang menambah atau minta ditambah, sungguh ia telah berbuat riba, kecuali bila berbeda jenisnya\". [HR. Muslim juz 3, hal. 1211, no. 83]"],["a","عَنْ اَبِيْ الْمِنْهَالِ قَالَ: بَاعَ شَرِيْكٌ لِيْ وَرِقًا بِنَسِيْئَةٍ إِلَى الْمَوْسِمِ اَوْ إِلَى الْحَجِّ، فَجَاءَ اِلَيَّ فَاَخْبَرَنِيْ، فَقُلْتُ: هٰذَا اَمْرٌ لَا يَصْلُحُ. قَالَ: قَدْ بِعْتُهُ فِى السُّوْقِ فَلَمْ يُنْكِرْ ذٰلِكَ عَلَىَّ اَحَدٌ. فَاَتَيْتُ الْبَرَاءَ بْنَ عَازِبٍ فَسَأَلْتُهُ. فَقَالَ: قَدِمَ النَّبِىُّ ﷺ الْمَدِيْنَةَ وَنَحْنُ نَبِيْعُ هٰذَا الْبَيْعَ، فَقَالَ: مَا كَانَ يَدًا بِيَدٍ فَلَا بَأْسَ بِهِ، وَمَا كَانَ نَسِيْئَةً فَهُوَ رِبًا. وَائْتِ زَيْدَ بْنَ اَرْقَمَ فَاِنَّهُ اَعْظَمُ تِجَارَةً مِنِّيْ. فَاَتَيْتُهُ فَسَأَلْتُهُ، فَقَالَ مِثْلَ ذٰلِكَ. مسلم 3: 1212، رقم: 86"],["p","Dari Abu Minhal, ia berkata, \"Ada seorang temanku menjual perak dengan sistem pembayaran yang ditangguhkan hingga satu musim atau musim hajji. Lalu ia datang kepadaku memberitahukan hal tersebut. Mendengar hal itu, aku berkata, \"Itu suatu perkara yang tidak baik\". Lalu ia berkata, \"Tetapi saya telah menjualnya di pasar dan tidak ada seorangpun yang mengingkari hal itu\". Kemudian saya datang kepada Al Baraa' bin 'Aazib menanyakan hal itu. Lalu ia berkata, \"Ketika Rasulullah SAW tiba di Madinah, kami biasa melakukan jual beli seperti ini, beliaupun bersabda, \"Jual-beli selama dilakukan dengan kontan, maka hal itu tidak dilarang. Sedangkan jual-beli yang pembayarannya ditangguhkan, maka yang demikian itu adalah riba.” Al Baraa’ bin ‘Aazib berkata: “Datanglah kepada Zaid bin Arqam, karena ia perniagaannya lebih besar daripada perniagaan saya\". Lalu aku (Abu Minhal) pergi menemui Zaid bin Arqam untuk menanyakan hal itu. Ternyata jawabannya sama seperti keterangan yang diberikan Al Baraa' bin 'Aazib tersebut\". [HR. Muslim juz 3, hal. 1212, no. 86]"],["a","عَنْ فَضَالَةَ بْنِ عُبَيْدٍ الاَنْصَارِىِّ قَالَ: اُتِيَ رَسُوْلُ اللهِ ﷺ وَهُوَ بِخَيْبَرَ بِقِلَادَةٍ فِيْهَا خَرَزٌ وَذَهَبٌ وَهِىَ مِنَ الْمَغَانِـمِ تُبَاعُ، فَاَمَرَ رَسُوْلُ اللهِ ﷺ بِالذَّهَبِ الَّذِى فِى الْقِلَادَةِ، فَنُزِعَ وَحْدَهُ. ثُـمَّ قَالَ لَـهُمْ رَسُوْلُ اللهِ ﷺ: اَلذَّهَبُ بِالذَّهَبِ وَزْنًا بِوَزْنٍ. مسلم 3: 1213، رقم: 89"],["p","Dari Fadlalah bin 'Ubaid Al-Anshariy, ia berkata : Ketika Rasulullah SAW di Khaibar, didatangkan kepada beliau berupa kalung dari emas yang ada permatanya, kalung tersebut dari harta rampasan perang yang dijual. Maka Rasulullah SAW menyuruh supaya permata tersebut dilepaskan dari kalung emas itu. Kemudian beliau bersabda kepada mereka \"Emas dengan emas yang sama timbangannya\", [HR. Muslim juz 3, hal. 1213, no. 89]"],["a","عَنْ عَبْدِ الْمَجِيْدِ بْنِ سُهَيْلِ بْنِ عَبْدِ الرَّحْمٰنِ اَنَّهُ سَمِعَ سَعِيْدَ بْنَ الْمُسَيَّبِ يُحَدِّثُ اَنَّ اَبَا هُرَيْرَةَ وَاَبَا سَعِيْدٍ حَدَّثَاهُ اَنَّ رَسُوْلَ اللهِ ﷺ بَعَثَ اَخَا بَنِيْ عَدِىٍّ اَلْاَنْصَارِىَّ فَاسْتَعْمَلَهُ عَلَى خَيْبَرَ، فَقَدِمَ بِتَمْرٍ جَنِيْبٍ، فَقَالَ لَهُ رَسُوْلُ اللهِ ﷺ: اَكُلُّ تَـمْرِ خَيْبَرَ هٰكَذَا؟. قَالَ: لَا، وَاللهِ، يَا رَسُوْلَ اللهِ، اِنَّا لَنَشْتَرِى الصَّاعَ بِالصَّاعَيْنِ مِنَ الْجَمْعِ. فَقَالَ رَسُوْلُ اللهِ ﷺ: لَا تَفْعَلُوْا، وَلٰكِنْ مِثْلًا بِـمِثْلٍ، اَوْ بِيْعُوْا هٰذَا وَاشْتَرُوْا بِثَمَنِهِ مِنْ هٰذَا، وَكَذٰلِكَ الْمِيْزَانُ. مسلم 3: 1215، رقم: 94"],["p","Dari ‘Abdul Majid bin Suhail bin ‘Abdurrahman bahwa ia pernah mendengar Sa'id bin Musayyab menceritakan bahwa Abu Hurairah dan Abu Sa'id menceritakan kepadanya, bahwa Rasulullah SAW mengangkat seorang Anshar dari Bani 'Adiy untuk bertugas di Khaibar. Kemudian ia datang (kepada Rasulullah SAW) dengan membawa kurma yang bagus, maka Rasulullah SAW bertanya kepadanya, \"Apakah semua kurma di Khaibar seperti ini ?\". Ia menjawab, \"Demi Allah, tidak wahai Rasulullah. Sesungguhnya kami membeli kurma satu sha' seperti ini kami tukar dengan dua sha' kurma yang jelek\". Maka Rasulullah SAW bersabda, \"Jangan kalian lakukan lagi perbuatan seperti itu, akan tetapi tukarkan yang sepadan, atau juallah dulu kurmamu, kemudian dengan uang penjualan itu kamu beli kurma yang bagus. Demikian itulah timbangan\". [HR. Muslim juz 3, hal. 1215, no. 94]"],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِىِّ وَعَنْ اَبِيْ هُرَيْرَةَ اَنَّ رَسُوْلَ اللهِ ﷺ اِسْتَعْمَلَ رَجُلًا عَلَى خَيْبَرَ، فَجَاءَهُ بِتَمْرٍ جَنِيْبٍ، فَقَالَ لَهُ رَسُوْلُ اللهِ ﷺ: اَكُلُّ تَـمْرِ خَيْبَرَ هٰكَذَا؟. فَقَالَ: لَا، وَاللهِ، يَا رَسُوْلَ اللهِ، اِنَّا لَنَأْخُذُ الصَّاعَ مِنْ هٰذَا بِالصَّاعَيْنِ، وَالصَّاعَيْنِ بِالثَّلَاثَةِ. فَقَالَ رَسُوْلُ اللهِ ﷺ: فَلَا تَفْعَلْ، بِعِ الْجَمْعَ بِالدَّرَاهِمِ، ثُـمَّ ابْتَعْ بِالدَّرَاهِمِ جَنِيْبًا. مسلم 3: 1215، رقم: 95"],["p","Dari Abu Sa'id Al-Khudriy dan dari Abu Hurairah, bahwa Rasulullah SAW pernah mengangkat seseorang untuk bertugas di Khaibar, Kemudian ia datang kepada Rasulullah SAW dengan membawa kurma yang bagus, lalu Rasulullah SAW bertanya kepadanya, \"Apakah semua kurma Khaibar itu seperti ini ?\". Ia menjawab, \"Tidak. Demi Allah, wahai Rasulullah, sesungguhnya kami menukar satu sha' kurma seperti ini dengan dua sha', atau dua sha' ditukar dengan tiga sha' \". Maka Rasulullah SAW bersabda, \"Jangan kamu lakukan perbuatan seperti itu, juallah kurma yang jelek itu terlebih dahulu dengan dirham, kemudian dengan dirham itu kamu gunakan untuk membeli kurma yang bagus\". [HR. Muslim juz 3, hal. 1215, no. 95]"],["a","عَنْ عُقْبَةَ بْنِ عَبْدِ الْغَافِرِ قَالَ: سَمِعْتُ اَبَا سَعِيْدٍ يَقُوْلُ: جَاءَ بِلَالٌ بِتَمْرٍ بَرْنِىٍّ. فَقَالَ لَهُ رَسُوْلُ اللهِ ﷺ: مِنْ اَيْنَ هٰذَا؟. فَقَالَ بِلَالٌ: تَـمْرٌ كَانَ عِنْدَنَا رَدِىءٌ، فَبِعْتُ مِنْهُ صَاعَيْنِ بِصَاعٍ لِمَطْعَمِ النَّبِىِّ ﷺ. فَقَالَ رَسُوْلُ اللهِ عِنْدَ ذٰلِكَ: اَوَّهْ عَيْنُ الرِّبَا، لَا تَفْعَلْ. وَلٰكِنْ اِذَا اَرَدْتَ اَنْ تَشْتَرِيَ التَّمْرَ فَبِعْهُ بِبَيْعٍ اٰخَرَ، ثُـمَّ اشْتَرِ بِهِ. مسلم 3: 1215، رقم: 96"],["p","Dari 'Uqbah bin ‘Abdul Ghafir, ia berkata ; Saya mendengar Abu Sa'id berkata, \"Suatu ketika Bilal datang dengan membawa kurma Barni (jenis kurma yang bermutu tinggi). Lalu Rasulullah SAW bertanya kepadanya, \"Dari manakah kurma ini ?\". Bilal menjawab, \"Kurma yang ada pada kami yang rendah mutunya, lalu saya menukarkan dua sha' dengan satu sha' kurma ini untuk Nabi SAW\". Lalu ketika itu Rasulullah SAW bersabda: \"Inilah yang disebut riba. Jangan kamu lakukan, akan tetapi apabila kamu ingin membeli kurma yang bagus, juallah terlebih dahulu kurmamu (yang kwalitasnya rendah) kemudian dengan uang hasil penjualannya itu kamu beli kurma yang bagus kwalitasnya\". [HR. Muslim juz 1, hal. 1215, no. 96]"],["a","عَنْ اَبِيْ سَعِيْدٍ قَالَ: اُتِىَ رَسُوْلُ اللهِ ﷺ بِتَمْرٍ. فَقَالَ: مَا هٰذَا التَّمْرُ مِنْ تَـمْرِنَا؟. فَقَالَ الرَّجُلُ: يَا رَسُوْلَ اللهِ بِعْنَا تَـمْرَنَا صَاعَيْنِ بِصَاعٍ مِنْ هٰذَا. فَقَالَ رَسُوْلُ اللهِ ﷺ: هٰذَا الرِّبَا فَرُدُّوْهُ، ثُـمَّ بِيْعُوْا تَـمْرَنَا، وَاشْتَرُوْا لَنَا مِنْ هٰذَا. مسلم 3: 1216، رقم: 97"],["p","Dari Abu Sa'id, ia berkata : Didatangkan kurma kepada Rasulullah SAW, lalu beliau bertanya, \"Apakah kurma ini dari kurma kita ?\". Maka orang laki-laki itu menjawab, \"Ya Rasulullah, kami menukar kurma kita dua sha' dengan satu sha' kurma ini\". Maka Rasulullah SAW bersabda, \"Ini adalah riba. Kembalikanlah kepadanya, lalu juallah kurma kita, lalu belilah untuk kita kurma seperti ini\". [HR. Muslim juz 3, hal. 1216, no. 97]"],["a","عَنْ عَبْدِ الرَّحْمٰنِ بْنِ اَبِيْ بَكْرَةَ قَالَ: قَالَ اَبُوْ بَكْرَةَ رَضِيَ اللهُ عَنْهُ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا تَبِيْعُوا الذَّهَبَ بِالذَّهَبِ اِلَّا سَوَاءً بِسَوَاءٍ، وَالْفِضَّةَ بِالْفِضَّةِ اِلَّا سَوَاءً بِسَوَاءٍ. وَبِيْعُوا الذَّهَبَ بِالْفِضَّةِ وَالْفِضَّةَ بِالذَّهَبِ كَيْفَ شِئْتُمْ. البخارى 3: 30"],["p","Dari 'Abdur Rahman bin Abu Bakrah, ia berkata : Abu Bakrah RA berkata : Rasulullah SAW bersabda, \"Janganlah kalian tukar-menukar emas dengan emas kecuali yang sama, perak dengan perak kecuali yang sama. Dan boleh tukar-menukar emas dengan perak, atau perak dengan emas, sesuai keinginan kalian\". [HR. Bukhari juz 3, hal. 30]"],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِيِّ وَعَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُمَا اَنَّ رَسُوْلَ اللهِ ﷺ اِسْتَعْمَلَ رَجُلًا عَلَى خَيْبَرَ. فَجَاءَهُ بِتَمْرٍ جَنِيْبٍ، فَقَالَ رَسُوْلُ اللهِ ﷺ: اَكُلُّ تَـمْرِ خَيْبَرَ هٰكَذَا؟ قَالَ: لَا، وَاللهِ يَا رَسُوْلَ اللهِ، اِنَّا لَنَأْخُذُ الصَّاعَ مِنْ هٰذَا بِالصَّاعَيْنِ وَالصَّاعَيْنِ بِالثَّلَاثَةِ. فَقَالَ رَسُوْلُ اللهِ ﷺ: لَا تَفْعَلْ. بِعِ الْجَمْعَ بِالدَّرَاهِمِ ثُـمَّ ابْتَعْ بِالدَّرَاهِمِ جَنِيْبًا. البخارى 3: 35"],["p","Dari Abu Sa'id Al-Khudriy dan dari Abu Hurairah RA, bahwasanya Rasulullah SAW pernah menugaskan seseorang di Khaibar. Kemudian orang itu datang dengan membawa kurma yang baik. Maka Rasulullah SAW bertanya, \"Apakah semua kurma Khaibar itu seperti ini ?\". Orang itu menjawab, \"Tidak. Demi Allah wahai Rasulullah, sesungguhnya kami menukar satu sha' dari jenis kurma ini dengan dua sha' kurma yang jelek, dan dua sha' kurma ini dengan tiga sha' kurma yang jelek\". Maka Rasulullah SAW bersabda, \"Jangan kamu lakukan yang demikian itu. Juallah kurma yang jelek itu dengan dirham, kemudian belilah dengan dirham itu kurma yang baik\". [HR. Bukhari juz 3, hal. 35]"],["p","Demikianlah pembahasan tentang Riba menurut Al-Qur'an dan hadits Rasulullah SAW."],["p","--oo0oo—"]],"c20221009_1302":[["p","Ahad, 9 Oktober 2022/13 Rabii’ul Awwal 1444 Brosur No. : 2097/2137/IA"],["h","SYARAT DITERIMANYA AMAL DAN IBADAH"],["p","Agar ibadah diterima di sisi Allah, haruslah terpenuhi dua syarat, yaitu:"],["p","1. Ikhlash karena Allah."],["p","2. Mengikuti tuntunan Nabi Muhammad SAW (ittiba’)."],["p","Jika kedua syarat tersebut tidak terpenuhi atau hanya salah satu syarat saja yang terpenuhi, maka amalan ibadah menjadi tertolak. Berikut dalil-dalil dari Al Qur’an dan As Sunnah."],["h","1. Ikhlash karena Allah"],["p","Allah SWT berfirman :"],["a","قُلْ اِنَّ صَلَاتِيْ وَنُسُكِيْ وَمَحْيَايَ وَمَمَاتِيْ لِلّٰهِ رَبِّ الْعٰلَمِيْنَۙ (162) لَا شَرِيْكَ لَهٗ ۚ وَبِذٰلِكَ اُمِرْتُ وَاَنَا۠ اَوَّلُ الْمُسْلِمِيْنَ (163). الانعام: 162-163"],["p","Katakanlah, \"Sesungguhnya shalatku, ibadahku, hidup dan matiku hanyalah untuk Allah, Tuhan semesta alam, (162)"],["p","tiada sekutu bagi-Nya; dan demikian itulah yang diperintahkan kepadaku dan aku adalah orang yang pertama-tama menyerahkan diri (kepada Allah)\". (163) [QS. Al-An'aam : 162-163]"],["a","قُلْ اِنِّيْٓ اُمِرْتُ اَنْ اَعْبُدَ اللّٰهَ مُخْلِصًا لَّهُ الدِّيْنَ (11) وَاُمِرْتُ لِاَنْ اَكُوْنَ اَوَّلَ الْمُسْلِمِيْنَ (12) قُلْ اِنِّيْٓ اَخَافُ اِنْ عَصَيْتُ رَبِّيْ عَذَابَ يَوْمٍ عَظِيْمٍ (13) قُلِ اللّٰهَ اَعْبُدُ مُخْلِصًا لَّهٗ دِيْنِيْ (14) . الزمر: 11-14"],["p","Katakanlah, \"Sesungguhnya aku diperintahkan supaya menyembah Allah dengan memurnikan ketha'atan kepada-Nya dalam (menjalankan) agama. (11)"],["p","Dan aku diperintahkan supaya menjadi orang yang pertama-tama berserah diri\". (12)"],["p","Katakanlah, \"Sesungguhnya aku takut akan siksaan hari yang besar jika aku durhaka kepada Tuhanku\". (13)"],["p","Katakanlah, \"Hanya Allah saja yang aku sembah dengan memurnikan ketha'atan kepada-Nya dalam (menjalankan) agamaku\". (14) [QS. Az-Zumar : 11-14]"],["a","وَمَآ اُمِرُوْٓا اِلَّا لِيَعْبُدُوا اللّٰهَ مُخْلِصِيْنَ لَهُ الدِّيْنَ ۙ حُنَفَاۤءَ وَيُقِيْمُوا الصَّلٰوةَ وَيُؤْتُوا الزَّكٰوةَ وَذٰلِكَ دِيْنُ الْقَيِّمَةِ . البينة: 5"],["p","Padahal mereka tidak disuruh kecuali supaya menyembah Allah dengan memurnikan ketha'atan kepada-Nya dalam (menjalankan) agama dengan lurus, dan supaya mereka mendirikan shalat dan menunaikan zakat; dan yang demikian itulah agama yang lurus. [QS. Al-Bayyinah : 5]"],["p","Hadits Rasulullah SAW :"],["a","عَنْ عُمَرَ بْنِ الْخَطَّابِ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اِنَّمَا الْاَعْمَالُ بِالنِّيَّةِ. وَاِنَّمَا لاِمْرِئٍ مَا نَوَى. فَمَنْ كَانَتْ هِجْرَتُهُ اِلَى اللهِ وَرَسُوْلِهِ فَهِجْرَتُهُ اِلىَ اللهِ وَرَسُوْلِهِ. وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيْبُهَا اَوِ امْرَأَةٍ يَتَزَوَّجُهَا فَهِجْرَتُهُ اِلىَ مَا هَاجَرَ اِلَيْهِ. مسلم 3: 1515 رقم 155"],["p","Dari ‘Umar bin Khaththab, ia berkata : Rasulullah SAW bersabda, \"Sesungguhnya amal perbuatan itu tergantung niatnya. Dan sesungguhnya seseorang akan mendapatkan sesuai dengan apa yang ia niatkan. Maka barangsiapa yang hijrahnya karena thaat kepada Allah dan Rasul-Nya, maka hijrahnya itu akan diberi balasan pahala thaat kepada Allah dan Rasul-Nya. Dan barangsiapa hijrahnya karena menginginkan dunia yang akan ia dapatkan, atau wanita yang ia akan mengawininya, maka hijrahnya itu akan diberi balasan sesuai niatnya ia berhijrah\". [HR. Muslim juz 3, hal. 1515, no 155]"],["a","عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ ﷺ اُرَاهُ يَقُوْلُ: اَلْاَعْمَالُ بِالنِّيَّةِ. فَمَنْ كَانَتْ هِجْرَتُهُ اِلىَ دُنْيَا يُصِيْبُهَا اَوِ امْرَأَةٍ يَتَزَوَّجُهَا فَهِجْرَتُهُ اِلىَ مَا هَاجَرَ اِلَيْهِ. وَمَنْ كَانَتْ هِجْرَتُهُ اِلَى اللهِ وَرَسُوْلِهِ فَهِجْرَتُهُ اِلىَ اللهِ وَ رَسُوْلِهِ ﷺ. البخارى 4: 252"],["p","Dari ‘Umar RA, ia berkata : Saya mendengar Nabi SAW bersabda, \"Amal perbuatan itu tergantung niatnya. Maka barangsiapa yang hijrahnya karena menginginkan dunia yang akan ia dapatkan, atau wanita yang ia akan mengawininya, maka hijrahnya itu akan diberi balasan sesuai niatnya ia berhijrah. Dan barangsiapa yang hijrahnya itu karena thaat kepada Allah dan Rasul-Nya, maka hijrahnya itu akan diberi balasan pahala thaat kepada Allah dan Rasul-Nya SAW\". [HR. Bukhari juz 4, hal. 252]"],["a","عَنْ اَبِيْ مُوْسَى قَالَ: سُئِلَ رَسُوْلُ اللهِ ﷺ عَنِ الرَّجُلِ يُقَاتِلُ شَجَاعَةً وَيُقَاتِلُ حَمِيَّةً وَيُقَاتِلُ رِيَاءً، اَيُّ ذٰلِكَ فِيْ سَبِيْلِ اللهِ؟ فَقَالَ رَسُوْلُ اللهِ ﷺ : مَنْ قَاتَلَ لِتَكُوْنَ كَلِمَةُ اللهِ هِيَ الْعُلْيَا فَهُوَ فِيْ سَبِيْلِ اللهِ. مسلم 3: 1513 رقم 150"],["p","Dari Abu Musa, ia berkata : Rasulullah SAW pernah ditanya tentang orang yang berperang karena keberanian, orang yang berperang karena membela golongannya dan orang yang berperang karena riya' (ingin dipuji orang), siapa diantara mereka itu yang termasuk di jalan Allah ? Maka Rasulullah SAW menjawab, \"Barangsiapa yang berperang agar supaya kalimat Allah itu yang paling tinggi, maka dialah yang (berperang) dijalan Allah\". [HR. Muslim juz 3, hal. 1513, no 150]"],["a","عَنْ اَبِيْ مُوْسَى رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ اِلىَ النَّبِيِّ ﷺ فَقَالَ: اَلرَّجُلُ يُقَاتِلُ لِلْمَغْنَمِ وَالرَّجُلُ يُقَاتِلُ لِلذِّكْرِ وَالرَّجُلُ يُقَاتِلُ لِيُرَى مَكَانُهُ فَمَنْ فِيِ سَبِيْلِ اللهِ؟ قَالَ: مَنْ قَاتَلَ لِتَكُوْنَ كَلِمَةُ اللهِ هِيَ الْعُلْيَا فَهُوَ فِى سَبِيْلِ اللهِ. البخارى 3: 206"],["p","Dari Abu Musa RA, ia berkata : Seorang laki-laki datang kepada Nabi SAW lalu bertanya, \" Ada orang yang berperang supaya mendapatkan harta rampasan, ada lagi orang yang berperang untuk mendapat sebutan (cari nama), dan ada lagi orang yang berperang supaya dipuji orang (sebagai pemberani), siapa diantara mereka itu yang termasuk dijalan Allah ?. Maka Rasulullah SAW menjawab, \"Barangsiapa yang berperang agar supaya kalimat Allah itu yang paling tinggi, maka dialah yang (berperang) dijalan Allah\". [HR. Bukhari juz 3, hal. 206]"],["a","عَنْ مَحْمُوْدِ بْنِ لُبَيْدٍ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اِنَّ اَخْوَفَ مَا اَخَافُ عَلَيْكُمْ اَلشِّرْكُ الْاَصْغَرُ. قَالُوْا: وَمَا الشِّرْكُ الْاَصْغَرُ يَا رَسُوْلَ اللهِ؟ قَالَ: اَلرِّيَاءُ. يَقُوْلُ اللهُ عَزَّ وَجَلَّ لَـهُمْ يَوْمَ الْقِيَامَةِ اِذَا جُزِيَ النَّاسُ بِاَعْمَالِـهِمْ: اِذْهَبُوْا اِلىَ الَّذِيْنَ كُنْتُمْ تُرَاءُوْنَ فىِ الدُّنْيَا فَانْظُرُوْا هَلْ تَجِدُوْنَ عِنْدَهُمْ جَزَاءً؟ احمد 9: 160، رقم: 23692"],["p","Dari Mahmud bin Lubaid, bahwasanya Rasulullah SAW bersabda, “Sesungguhnya sesuatu yang paling aku khawatirkan atas kamu sekalian itu adalah syirik kecil”. Kemudian para shahabat bertanya, “Apa syirik kecil itu ya Rasulullah ?”. Rasulullah SAW menjawab, “(Syirik kecil itu ialah) riya’. Besok pada hari qiyamat ketika para manusia diberi balasan dengan amal-amal mereka, Allah ‘Azza wa jalla akan berfirman kepada mereka, “Pergilah kamu sekalian kepada orang-orang yang dahulu kamu berbuat riya’ padanya ketika di dunia, maka lihatlah olehmu sekalian apakah kalian mendapati pahala pada mereka ?”. [HR. Ahmad, juz 9, hal. 160, no. 23692]"],["p","2. Mengikuti tuntunan Nabi Muhammad SAW (ittiba’)."],["p","Allah SWT berfirman :"],["a","وَمَآ اٰتٰىكُمُ الرَّسُوْلُ فَخُذُوْهُ وَمَا نَهٰىكُمْ عَنْهُ فَانْتَهُوْاۚ وَاتَّقُوا اللّٰهَ ۗ اِنَّ اللّٰهَ شَدِيْدُ الْعِقَابِ. الحشر : 7"],["p","Apa yang diberikan Rasul kepadamu, maka terimalah. Dan apa yang dilarangnya bagimu tinggalkanlah. Dan bertakwalah kepada Allah. Sesungguhnya Allah sangat keras hukuman-Nya. [QS. Al Hasyr : 7]"],["p","Hadits Rasulullah SAW :"],["a","عَنْ عَائِشَةَ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: مَنْ عَمِلَ عَمَلاً لَيْسَ عَلَيْهِ اَمْرُنَا فَهُوَ رَدٌّ. مسلم 3: 1344 رقم 18"],["p","Dari ‘Aisyah bahwasanya Rasulullah SAW bersabda, “Barangsiapa yang melakukan suatu amalan yang bukan perintah kami, maka ia tertolak”. [HR. Muslim juz 3, hal. 1344, no 18]"],["a","عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ اَحْدَثَ فِى اَمْرِنَا هٰذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ. مسلم 3: 1343 رقم 17"],["p","Dari ‘Aisyah, ia berkata : Rasulullah SAW bersabda, “Barangsiapa mengada-adakan dalam perintah kami ini, apa-apa yang bukan dari padanya, maka ia tertolak”. [HR. Muslim juz 3, hal. 1343, no.17]"],["a","عَنْ مَالِكٍ اَنَّهُ بَلَغَهُ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ : تَرَكْتُ فِيْكُمْ اَمْرَيْنِ لَنْ تَضِلُّوْا مَا مَسَكْتُمْ بِهِمَا، كِتَابَ اللهِ وَ سُنَّةَ نَبِيِّهِ. مالك، فى الموطأ 2: 899 رقم 3"],["p","Dari Maalik, bahwasanya telah sampai kepadanya, bahwasanya Rasulullah SAW bersabda : “Kutinggalkan pada kamu sekalian dua perkara yang kamu tidak akan sesat apabila kamu berpegang teguh kepada keduanya, yaitu Kitab Allah dan sunnah Nabi-Nya\". [HR. Maalik dalam Al-Muwaththa’ juz 2, hal. 899, no 3]"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اِنَّ اَصْدَقَ الْحَدِيْثِ كِتَابُ اللهِ وَ اَحْسَنَ الْهَدْيِ هَدْيُ مُحَمَّدٍ وَ شَرُّ الْاُمُوْرِ مُحْدَثَاتُهَا وَ كُلُّ مُحْدَثَةٍ بِدْعَةٌ وَ كُلُّ بِدْعَةٍ ضَلَالَةٌ وَ كُلُّ ضَلَالَةٍ فِي النَّارِ. النسائى 3: 188"],["p","Dari Jabir bin ‘Abdullah, ia berkata : Rasulullah SAW bersabda, “Sesungguhnya sebenar-benar perkataan ialah Kitab Allah, dan sebaik-baik petunjuk ialah petunjuk Muhammad, dan sejelek-jelek perkara itu yang diada-adakan, dan tiap-tiap yang diada-adakan itu bid’ah, dan tiap-tiap bid’ah itu sesat, dan tiap-tiap kesesatan itu di neraka”. [HR. Nasaai juz 3, hal. 188]"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ يَقُوْلُ: اَمَّا بَعْدُ، فَاِنَّ خَيْرَ الْحَدِيْثِ كِتَابُ اللهِ وَ خَيْرُ الْهُدَى هُدَى مُحَمَّدٍ وَ شَرُّ الْاُمُوْرِ مُحْدَثَاتُهَا وَ كُلُّ بِدْعَةٍ ضَلاَلَةٌ. مسلم 2: 592 رقم 43"],["p","Dari Jabir bin ‘Abdullah, ia berkata : Dahulu Rasulullah SAW bersabda, “Adapun sesudah itu, sesungguhnya sebaik-baik perkataan adalah kitab Allah, dan sebaik-baik petunjuk adalah petunjuk Muhammad, dan seburuk-buruk perkara adalah yang diada-adakan, dan setiap bid’ah adalah sesat. [HR. Muslim juz 2, hal. 592, no 43]"],["a","عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اُوْصِيْكُمْ بِتَقْوَى اللهِ وَ السَّمْعِ وَ الطَّاعَةِ وَ اِنْ كَانَ عَبْدًا حَبَشِيًّا فَاِنَّهُ مَنْ يَعِشْ مِنْكُمْ بَعْدِيْ فَسَيَرَى اِخْتِلَافًا كَثِيْرًا، فَعَلَيْكُمْ بِسُنَّتِيْ وَ سُنَّةِ الْخُلَفَاءِ الرَّاشِدِيْنَ الْمَهْدِيِّيْنَ، فَتَمَسَّكُوْا بِهَا وَ عَضُّوْا عَلَيْهَا بِالنَّوَاجِذِ، وَ اِيَّاكُمْ وَ مُحْدَثَاتِ الْاُمُوْرِ، فَاِنَّ كُلَّ مُحْدَثَةٍ بِدْعَةٌ وَ كُلَّ بِدْعَةٍ ضَلاَلَةٌ. احمد 6: 83، رقم: 17145"],["p","Dari ‘Irbadl bin Sariyah RA, ia berkata : Rasulullah SAW bersabda, “Saya berpesan kepada kamu sekalian, hendaklah kamu sekalian bertaqwa kepada Allah, mendengar dan thaat, sekalipun (yang menjadi pemimpin) budak Habsyiy, karena sesungguhnya orang yang hidup diantara kamu sekalian sesudahku akan melihat perselisihan yang banyak, maka dari itu hendaklah kamu sekalian (berpegang) pada sunnahku dan sunnah para khalifah yang lurus lagi menetapi petunjuk yang benar, berpegang teguhlah padanya dan gigitlah dengan gigi geraham. Dan jauhkanlah kalian dari perkara-perkara yang diada-adakan, karena sesungguhnya tiap-tiap perkara yang diada-adakan itu bid’ah, dan tiap-tiap bid’ah itu sesat”. [HR. Ahmad juz 6, hal. 83, no. 17145]"],["a","عَنْ اَبِيْ هُرَيْرَةَ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: كُلُّ اُمَّتِيْ يَدْخُلُوْنَ الْجَنَّةَ اِلاَّ مَنْ اَبَى. قَالُوْا: يَا رَسُوْلَ اللهِ، وَ مَنْ يَأْبَى؟ قَالَ: مَنْ اَطَاعَنِيْ دَخَلَ الْجَنَّةَ ، وَ مَنْ عَصَانِيْ فَقَدْ اَبَى. البخارى 8: 139"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Sesungguhnya semua ummatku akan masuk surga, kecuali orang yang tidak mau”. Para shahabat bertanya, “Ya Rasulullah, siapakah orang yang tidak mau itu ?”. Beliau SAW bersabda, “Barangsiapa yang menthaatiku, ia pasti masuk surga, dan barangsiapa yang mendurhakaiku, maka berarti ia tidak mau”. [HR. Bukhari juz 8, hal. 139]"],["p","--oo0oo—"]],"c20221016_1303":[["p","Ahad, 16 Oktober 2022/20 Rabii’ul Awwal 1444 Brosur No. : 2098/2138/IA"],["h","HAL HAL YANG MENGHAPUS AMAL (1)"],["p","Allah SWT memerintahkan kepada hamba-Nya supaya tha’at kepada Allah dan Rasul-Nya, dan Allah menjanjikan pahala, namun pahala tersebut bisa gugur dan terhapus karena melanggar larangan larangan Allah."],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اَطِيْعُوا اللّٰهَ وَاَطِيْعُوا الرَّسُوْلَ وَلَا تُبْطِلُوْٓا اَعْمَالَكُمْ. محمد: 33"],["p","Hai orang-orang yang beriman, tha’atlah kepada Allah dan tha’atlah kepada Rasul dan janganlah kamu merusakkan (pahala) amal-amalmu. [QS. Muhammad : 33]"],["p","Hal-hal yang bisa menghapus / merusak pahala amal, diantaranya :"],["h","1. Berbuat syirik (musyrik)"],["p","Allah SWT berfirman:"],["a","يٰٓاَيُّهَا النَّاسُ اعْبُدُوْا رَبَّكُمُ الَّذِيْ خَلَقَكُمْ وَالَّذِيْنَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُوْنَۙ (21) الَّذِيْ جَعَلَ لَكُمُ الْاَرْضَ فِرَاشًا وَّالسَّمَاۤءَ بِنَاۤءً ۖ وَّاَنْزَلَ مِنَ السَّمَاۤءِ مَاۤءً فَاَخْرَجَ بِهٖ مِنَ الثَّمَرٰتِ رِزْقًا لَّكُمْ ۚ فَلَا تَجْعَلُوْا لِلّٰهِ اَنْدَادًا وَّاَنْتُمْ تَعْلَمُوْنَ (22) البقرة : 21-22"],["p","Hai manusia, sembahlah Tuhanmu Yang telah menciptakanmu dan orang-orang yang sebelummu, agar kamu bertakwa. (21)"],["p","Dialah yang menjadikan bumi sebagai hamparan bagimu dan langit sebagai atap, dan Dia menurunkan air (hujan) dari langit, lalu Dia menghasilkan dengan hujan itu segala buah-buahan sebagai rezeki untukmu; karena itu janganlah kamu mengadakan sekutu-sekutu bagi Allah, padahal kamu mengetahui. (22) [ QS. Al Baqarah : 21-22]"],["a","اِنَّ اللّٰهَ لَا يَغْفِرُ اَنْ يُّشْرَكَ بِهٖ وَيَغْفِرُ مَا دُوْنَ ذٰلِكَ لِمَنْ يَّشَاۤءُ ۚ وَمَنْ يُّشْرِكْ بِاللّٰهِ فَقَدِ افْتَرٰٓى اِثْمًا عَظِيْمًا. النساء : 48"],["p","Sesungguhnya Allah tidak akan mengampuni dosa syirik, dan Dia mengampuni segala dosa yang selain dari (syirik) itu, bagi siapa yang dikehendaki-Nya. Barangsiapa yang mempersekutukan Allah, maka sungguh ia telah berbuat dosa yang besar. [QS. An Nisaa’ : 48]"],["a","حُنَفَاۤءَ لِلّٰهِ غَيْرَ مُشْرِكِيْنَ بِهٖۗ وَمَنْ يُّشْرِكْ بِاللّٰهِ فَكَاَنَّمَا خَرَّ مِنَ السَّمَاۤءِ فَتَخْطَفُهُ الطَّيْرُ اَوْ تَهْوِيْ بِهِ الرِّيْحُ فِيْ مَكَانٍ سَحِيْقٍ. الحج : 31"],["p","Dengan ikhlas kepada Allah, tidak mempersekutukan sesuatu dengan Dia. Barangsiapa mempersekutukan sesuatu dengan Allah, maka adalah ia seolah-olah jatuh dari langit lalu disambar oleh burung, atau diterbangkan angin ke tempat yang jauh. [QS. Al Hajj : 31]"],["a","ذٰلِكَ هُدَى اللّٰهِ يَهْدِيْ بِهٖ مَنْ يَّشَاۤءُ مِنْ عِبَادِهٖ ۗ وَلَوْ اَشْرَكُوْا لَحَبِطَ عَنْهُمْ مَّا كَانُوْا يَعْمَلُوْنَ . الانعام:88"],["p","Itulah petunjuk Allah, yang dengannya Dia memberi petunjuk kepada siapa yang dikehendaki-Nya diantara hamba-hamba-Nya. Seandainya mereka mempersekutukan Allah, niscaya lenyaplah dari mereka amalan yang telah mereka kerjakan. [QS. Al-An’aam : 88]"],["a","وَلَقَدْ اُوْحِيَ اِلَيْكَ وَاِلَى الَّذِيْنَ مِنْ قَبْلِكَۚ لَىِٕنْ اَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُوْنَنَّ مِنَ الْخٰسِرِيْنَ. الزمر: 65"],["p","Dan sesungguhnya telah diwahyukan kepadamu dan kepada (Nabi-nabi) yang sebelummu, “Sungguh, jika kamu mempersekutukan (Allah), niscaya akan hapuslah amalmu, dan tentulah kamu termasuk orang-orang yang merugi”. [QS. Az-Zumar : 65]"],["p","Di dalam hadits disebutkan :"],["a","عَنِ ابْنِ شِهَابٍ قَالَ: اَخْبَرَنِيْ سَعِيْدُ بْنُ الْمُسَيَّبِ عَنْ اَبِيْهِ قَالَ: لَمَّا حَضَرَتْ اَبَا طَالِبٍ الْوَفَاةُ جَاءَهُ رَسُوْلُ اللهِ ﷺ ، فَوَجَدَ عِنْدَهُ اَبَا جَهْلٍ وَعَبْدَ اللهِ بْنَ اَبِيْ اُمَيَّةَ بْنِ الْمُغِيْرَةِ، فَقَالَ رَسُوْلُ اللهِ ﷺ: يَا عَمِّ، قُلْ: لَا اِلٰهَ اِلَّا اللّٰهُ ، كَلِمَةً اَشْهَدُ لَكَ بِـهَا عِنْدَ اللهِ. فَقَالَ اَبُوْ جَهْلٍ وَعَبْدُ اللهِ بْنُ اَبِيْ اُمَيَّةَ: يَا اَبَا طَالِبٍ، اَتَرْغَبُ عَنْ مِلَّةِ عَبْدِ الْمُطَّلِبِ؟ فَلَمْ يَزَلْ رَسُوْلُ اللهِ ﷺ يَعْرِضُهَا عَلَيْهِ وَيُعِيْدُ لَهُ تِلْكَ الْمَقَالَةَ، حَتَّى قَالَ اَبُوْ طَالِبٍ آخِرَ مَا كَلَّمَهُمْ هُوَ عَلَى مِلَّةِ عَبْدِ الْمُطَّلِبِ، وَاَبَى اَنْ يَقُوْلَ: لَا اِلٰهَ اِلَّا اللّٰهُ . فَقَالَ رَسُوْلُ اللهِ ﷺ: اَمَا وَاللهِ، لَاَسْتَغْفِرَنَّ لَكَ مَا لَـمْ اُنْهَ عَنْكَ. فَاَنْزَلَ اللهُ عَزَّ وَجَلَّ: مَا كَانَ لِلنَّبِيِّ وَالَّذِيْنَ اٰمَنُوْآ اَنْ يَّسْتَغْفِرُوْا لِلْمُشْرِكِيْنَ وَلَوْ كَانُوْآ اُولِيْ قُرْبٰى مِنْ بَعْدِ مَا تَبَيَّنَ لَـهُمْ اَنَّـهُمْ اَصْحٰبُ الْجَحِيْمِ (التوبة: 113)، وَاَنْزَلَ اللهُ تَعَالَى فِيْ اَبِيْ طَالِبٍ، فَقَالَ لِرَسُوْلِ اللهِ ﷺ : اِنَّكَ لَا تَـهْدِيْ مَنْ اَحْبَبْتَ وَلٰكِنَّ اللهَ يَهْدِيْ مَنْ يَّشَآءُ، وَهُوَ اَعْلَمُ بِالْمُهْتَدِيْنَ. مسلم 1: 54 رقم 39"],["p","Dari Ibnu Syihab, ia berkata : Telah mengkhabarkan kepadaku Sa’id bin Al-Musayyab dari ayahnya, ia berkata, \"Ketika Abu Thalib menjelang sakaratul maut, Rasulullah SAW menjenguknya. Beliau mendapati Abu Jahal dan Abdullah bin Abu Umayyah bin Al-Mughirah sudah berada di dekatnya. Rasulullah SAW bersabda, \"Wahai paman, ucapkanlah “laa ilaaha illallooh” kalimat yang dengannya aku menjadi saksi untukmu di hadapan Allah”. Lalu Abu Jahal dan Abdullah bin Abu Umayyah berkata, 'Wahai Abu Thalib, apakah kamu benci kepada agama Abdul Muththalib ?”. Rasulullah SAW tidak henti-hentinya menganjurkan supaya mengucap “laa ilaaha illallooh” dan beliau mengulang-ulang kalimat itu, sehingga Abu Thalib mengatakan sebagai ucapan terakhir kepada mereka, bahwa dia tetap pada agama Abdul Muththalib, dan enggan mengucapkan “laa ilaaha illallooh”. Kemudian Rasulullah SAW bersabda: \"Demi Allah, sungguh aku akan memohonkan ampun (kepada Allah) untukmu selama aku belum dilarang”. Kemudian Allah ‘Azza wa Jalla menurunkan ayat, maa kaana linnabiyyi walladdziina aamanuu ayyastaghfiruu lilmusyrikiina walau kaanuu ulii qurbaa min ba’di maa tabayyana lahum annahum ashhaabul jahiim“ (Tidak pantas bagi Nabi dan orang-orang yang beriman memintakan ampun (kepada Allah) bagi orang-orang musyrik walaupun orang-orang musyrik itu kaum kerabatnya setelah nyata bagi mereka bahwa orang-orang musyrik itu adalah penghuni neraka Jahiim)”. (QS. At-Taubah : 113). Dan Allah Ta’aalaa menurunkan ayat berkenaan dengan peristiwa Abu Thalib, Allah berfirman kepada Rasulullah SAW. innaka laa tahdii man ahbabta walaakinnallooha yahdii mayyasyaa’u wa huwa a’lamu bilmuhtadiin “(Sesungguhnya kamu tidak dapat memberi petunjuk kepada orang yang kamu kasihi, tetapi Allah memberi petunjuk kepada orang yang dikehendaki-Nya, dan Allah lebih mengetahui orang-orang yang mau menerima petunjuk)”. (QS. Al-Qashash : 56). [HR. Muslim juz 1, hal. 54, no. 39]"],["h","2. Berbuat kufur (kafir)"],["p","Allah SWT berfirman:"],["a","وَالَّذِيْنَ كَفَرُوْٓا اَعْمَالُهُمْ كَسَرَابٍۢ بِقِيْعَةٍ يَّحْسَبُهُ الظَّمْاٰنُ مَاۤءًۗ حَتّٰىٓ اِذَا جَاۤءَهٗ لَمْ يَجِدْهُ شَيْـًٔا وَّوَجَدَ اللّٰهَ عِنْدَهٗ فَوَفّٰىهُ حِسَابَهٗ ۗ وَاللّٰهُ سَرِيْعُ الْحِسَابِ ۙ (39) اَوْ كَظُلُمٰتٍ فِيْ بَحْرٍ لُّجِّيٍّ يَّغْشٰىهُ مَوْجٌ مِّنْ فَوْقِهٖ مَوْجٌ مِّنْ فَوْقِهٖ سَحَابٌۗ ظُلُمٰتٌۢ بَعْضُهَا فَوْقَ بَعْضٍۗ اِذَآ اَخْرَجَ يَدَهٗ لَمْ يَكَدْ يَرٰىهَاۗ وَمَنْ لَّمْ يَجْعَلِ اللّٰهُ لَهٗ نُوْرًا فَمَا لَهٗ مِنْ نُّوْرٍ ࣖ (40) النور : 39-40"],["p","Dan orang-orang yang kafir amal-amal mereka adalah laksana fatamorgana di tanah yang datar, yang disangka air oleh orang yang dahaga, tetapi bila didatanginya dia tidak mendapatinya sesuatu apa pun. Dan di dapatinya (ketetapan) Allah di sisinya, lalu Allah memberikan kepadanya perhitungan amal-amal dengan cukup dan Allah adalah sangat cepat perhitungan-Nya. (39)"],["p","Atau seperti gelap gulita di lautan yang dalam, yang diliputi oleh ombak, yang di atasnya ada ombak (pula), di atasnya (lagi) awan gelap; gelap gulita yang bertindih tindih, apabila dia mengeluarkan tangannya, hampir-hampir dia tidak dapat melihatnya, (dan) barangsiapa yang tidak diberi cahaya (petunjuk) oleh Allah, maka dia tidak mempunyai cahaya sedikit pun.(40) [QS. An Nuur 39-40]"],["a","اِنَّ الَّذِيْنَ يَكْفُرُوْنَ بِاٰيٰتِ اللّٰهِ وَيَقْتُلُوْنَ النَّبِيّٖنَ بِغَيْرِحَقٍّ ۖ وَّيَقْتُلُوْنَ الَّذِيْنَ يَأْمُرُوْنَ بِالْقِسْطِ مِنَ النَّاسِۙ فَبَشِّرْهُمْ بِعَذَابٍ اَلِيْمٍ (21) اُولٰۤىِٕكَ الَّذِيْنَ حَبِطَتْ اَعْمَالُهُمْ فِى الدُّنْيَا وَالْاٰخِرَةِ ۖ وَمَا لَهُمْ مِّنْ نّٰصِرِيْنَ (22) ال عمران : 21 - 22"],["p","Sesungguhnya orang-orang yang kafir kepada ayat-ayat Allah dan membunuh para nabi tanpa hak (alasan yang benar) dan membunuh orang-orang yang menyuruh manusia berbuat adil, maka gembirakanlah mereka bahwa mereka akan menerima siksa yang pedih. (21)"],["p","Mereka itu adalah orang-orang yang lenyap (pahala) amal-amalnya di dunia dan akhirat, dan mereka sekali-kali tidak memperoleh penolong. (22) [QS. Ali ‘Imraan : 21-22]"],["a","وَالَّذِيْنَ كَفَرُوْا فَتَعْسًا لَّهُمْ وَاَضَلَّ اَعْمَالَهُمْ (8) ذٰلِكَ بِاَنَّهُمْ كَرِهُوْا مَآ اَنْزَلَ اللّٰهُ فَاَحْبَطَ اَعْمَالَهُمْ (9) محمد : 8-9"],["p","Dan orang-orang yang kafir maka kecelakaanlah bagi mereka, dan Allah menghapus amal-amal mereka. (8)"],["p","Yang demikian itu adalah karena sesungguhnya mereka benci kepada apa yang diturunkan Allah (Al Qur'an), lalu Allah menghapus amal-amal mereka.(9) [ QS. Muhammad : 8-9]"],["a","اِنَّ الَّذِيْنَ كَفَرُوْا وَصَدُّوْا عَنْ سَبِيْلِ اللّٰهِ وَشَاۤقُّوا الرَّسُوْلَ مِنْۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ الْهُدٰى لَنْ يَّضُرُّوا اللّٰهَ شَيْـًٔاۗ وَسَيُحْبِطُ اَعْمَالَهُمْ (32) يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اَطِيْعُوا اللّٰهَ وَاَطِيْعُوا الرَّسُوْلَ وَلَا تُبْطِلُوْٓا اَعْمَالَكُمْ (33) اِنَّ الَّذِيْنَ كَفَرُوْا وَصَدُّوْا عَنْ سَبِيْلِ اللّٰهِ ثُمَّ مَاتُوْا وَهُمْ كُفَّارٌ فَلَنْ يَّغْفِرَ اللّٰهُ لَهُمْ (34) محمد : 32-34"],["p","Sesungguhnya orang-orang kafir dan menghalangi (manusia) dari jalan Allah serta memusuhi rasul setelah petunjuk itu jelas bagi mereka, mereka tidak dapat memberi mudlarat kepada Allah sedikit pun. Dan Allah akan menghapus (pahala) amal-amal mereka. (32)"],["p","Hai orang-orang yang beriman, tha’atlah kepada Allah dan tha’atlah kepada rasul dan janganlah kamu merusakkan (pahala) amal-amalmu. (33)"],["p","Sesungguhnya orang-orang yang kafir dan menghalangi (manusia) dari jalan Allah kemudian mereka mati dalam keadaan kafir, maka sekali-kali Allah tidak akan memberi ampun kepada mereka. (34) [QS. Muhammad : 32-34]"],["a","اِنَّ الَّذِيْنَ كَفَرُوْا وَمَاتُوْا وَهُمْ كُفَّارٌ فَلَنْ يُّقْبَلَ مِنْ اَحَدِهِمْ مِّلْءُ الْاَرْضِ ذَهَبًا وَّلَوِ افْتَدٰى بِهٖۗ اُولٰۤىِٕكَ لَهُمْ عَذَابٌ اَلِيْمٌ وَّمَا لَهُمْ مِّنْ نّٰصِرِيْنَ . ال عمران : 91"],["p","Sesungguhnya orang-orang yang kafir dan mati sedang mereka tetap dalam kekafirannya, maka tidaklah akan diterima dari seseorang di antara mereka emas sepenuh bumi, walaupun dia menebus diri dengan emas (yang sebanyak) itu. Bagi mereka itulah siksa yang pedih dan sekali-kali mereka tidak memperoleh penolong. [QS. Ali ‘Imraan : 91]"],["a","اِنَّ الَّذِيْنَ كَفَرُوْا لَوْ اَنَّ لَهُمْ مَّا فِى الْاَرْضِ جَمِيْعًا وَّمِثْلَهٗ مَعَهٗ لِيَفْتَدُوْا بِهٖ مِنْ عَذَابِ يَوْمِ الْقِيٰمَةِ مَا تُقُبِّلَ مِنْهُمْ ۚ وَلَهُمْ عَذَابٌ اَلِيْمٌ (36) يُرِيْدُوْنَ اَنْ يَّخْرُجُوْا مِنَ النَّارِ وَمَا هُمْ بِخَارِجِيْنَ مِنْهَا ۖ وَلَهُمْ عَذَابٌ مُّقِيْمٌ (37) المائدة : 36 - 37"],["p","Sesungguhnya orang-orang yang kafir sekiranya mereka mempunyai apa yang di bumi ini seluruhnya dan mempunyai yang sebanyak itu (pula) untuk menebus diri mereka dengan itu dari adzab hari kiamat, niscaya (tebusan itu) tidak akan diterima dari mereka, dan mereka beroleh adzab yang pedih. (36)"],["p","Mereka ingin keluar dari neraka, padahal mereka sekali-kali tidak dapat keluar daripadanya, dan mereka beroleh adzab yang kekal. (37) [QS. Al Maaidah : 36-37]"],["a","لِلَّذِيْنَ اسْتَجَابُوْا لِرَبِّهِمُ الْحُسْنٰىۗ وَالَّذِيْنَ لَمْ يَسْتَجِيْبُوْا لَهٗ لَوْ اَنَّ لَهُمْ مَّا فِى الْاَرْضِ جَمِيْعًا وَّمِثْلَهٗ مَعَهٗ لَافْتَدَوْا بِهٖ ۗ اُولٰۤىِٕكَ لَهُمْ سُوْۤءُ الْحِسَابِ ۙ وَمَأْوٰىهُمْ جَهَنَّمُ ۗ وَبِئْسَ الْمِهَادُ . الرعد :18"],["p","Bagi orang-orang yang memenuhi seruan Tuhannya, (disediakan) balasan yang baik. Dan orang-orang yang tidak memenuhi seruan Tuhan, sekiranya mereka mempunyai semua (kekayaan) yang ada di bumi dan (ditambah) sebanyak isi bumi itu lagi besertanya, niscaya mereka akan menebus dirinya dengan kekayaan itu. Orang-orang itu disediakan baginya hisab yang buruk dan tempat kediaman mereka ialah Jahannam, dan itulah seburuk-buruk tempat kediaman. [QS. Ar Ra’ad : 18]"],["a","وَلَوْ اَنَّ لِلَّذِيْنَ ظَلَمُوْا مَا فِى الْاَرْضِ جَمِيْعًا وَّمِثْلَهٗ مَعَهٗ لَافْتَدَوْا بِهٖ مِنْ سُوْۤءِ الْعَذَابِ يَوْمَ الْقِيٰمَةِۗ وَبَدَا لَهُمْ مِّنَ اللّٰهِ مَا لَمْ يَكُوْنُوْا يَحْتَسِبُوْنَ. الزمر : 47"],["p","Dan sekiranya orang-orang yang dhalim mempunyai apa yang ada di bumi semuanya dan (ada pula) sebanyak itu besertanya, niscaya mereka akan menebus dirinya dengan itu dari siksa yang buruk pada hari kiamat. Dan jelaslah bagi mereka adzab dari Allah yang belum pernah mereka perkirakan. [QS. Az Zumar : 47]"],["a","يُبَصَّرُوْنَهُمْۗ يَوَدُّ الْمُجْرِمُ لَوْ يَفْتَدِيْ مِنْ عَذَابِ يَوْمِىِٕذٍۢ بِبَنِيْهِۙ (11) وَصَاحِبَتِهٖ وَاَخِيْهِۙ (12) وَفَصِيْلَتِهِ الَّتِيْ تُـؤْوِيْهِۙ (13) وَمَنْ فِى الْاَرْضِ جَمِيْعًاۙ ثُمَّ يُنْجِيْهِ (14) المعارج : 11-14"],["p","Sedang mereka saling melihat. Orang kafir ingin kalau sekiranya dia dapat menebus (dirinya) dari adzab hari itu dengan anak-anaknya.(11)"],["p","Dan istrinya dan saudaranya,(12)"],["p","Dan kaum familinya yang melindunginya (di dunia). (13)"],["p","Dan orang-orang di atas bumi seluruhnya, kemudian (mengharapkan) tebusan itu dapat menyelamatkannya. (14) [QS. Al Ma’aarij : 11-14]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ اَنَّهُ حَدَّثَهُمْ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اِنَّ الْعَبْدَ اِذَا وُضِعَ فِيْ قَبْرِهِ وَتَوَلَّى عَنْهُ اَصْحَابُهُ وَاِنَّهُ لَيَسْمَعُ قَرْعَ نِعَالِـهِمْ اَتَاهُ مَلَكَانِ فَيُقْعِدَانِهِ فَيَقُوْلَانِ: مَا كُنْتَ تَقُوْلُ فِيْ هٰذَا الرَّجُلِ لِمُحَمَّدٍ ﷺ؟ فَاَمَّا الْمُؤْمِنُ فَيَقُوْلُ: اَشْهَدُ اَنَّهُ عَبْدُ اللهِ وَرَسُوْلُهُ. فَيُقَالُ لَهُ: اُنْظُرْ اِلَى مَقْعَدِكَ مِنَ النَّارِ قَدْ اَبْدَلَكَ اللهُ بِهِ مَقْعَدًا مِنَ الْجَنَّةِ. فَيَرَاهُمَا جَمِيْعًا.قَالَ: وَاَمَّا الْمُنَافِقُ وَالْكَافِرُ فَيُقَالُ لَهُ: مَا كُنْتَ تَقُوْلُ فِيْ هٰذَا الرَّجُلِ؟ فَيَقُوْلُ: لَا اَدْرِيْ، كُنْتُ اَقُوْلُ مَا يَقُوْلُ النَّاسُ. فَيُقَالُ: لَا دَرَيْتَ وَلَا تَلَيْتَ؟ وَيُضْرَبُ بِـمَطَارِقَ مِنْ حَدِيْدٍ ضَرْبَةً فَيَصِيْحُ صَيْحَةً يَسْمَعُهَا مَنْ يَلِيْهِ غَيْرَ الثَّقَلَيْنِ. البخارى 2: 102"],["p","Dari Anas bin Maalik RA bahwasanya ia menceritakan kepada orang-orang, bahwa Rasulullah SAW bersabda, “Sesungguhnya seorang hamba apabila diletakkan dalam quburnya, dan teman-temannya telah berpaling meninggalkannya, sungguh ia masih mendengar suara sandal mereka, lalu datanglah dua malaikat mendudukkannya dan bertanya kepadanya, “Apa yang kamu yaqini tentang laki-laki ini, yaitu Muhammad SAW ?”. Adapun orang mukmin, maka ia menjawab, “Aku bersaksi bahwa dia adalah hamba Allah dan utusan-Nya”. Maka dikatakan kepadanya, “Lihatlah tempat dudukmu yang di neraka, Allah telah menggantinya dengan tempat duduk di surga”. Maka ia melihat keduanya. Adapun orang munafiq dan orang kafir, ia ditanya, “Apa yang kamu yaqini tentang laki-laki ini ?”. Ia menjawab, “Saya tidak tahu, saya mengatakannya sebagaimana apa yang dikatakan oleh orang-orang”. Maka dikatakan kepadanya, “Kamu tidak tahu dan tidak mau membaca”. Kemudian ia dipukul dengan pemukul dari besi, maka ia berteriak sekeras-kerasnya yang didengar oleh apa yang ada didekatnya selain jinn dan manusia”. [HR. Bukhari juz 2, hal. 102]"],["h","3. Murtad (kembali kafir setelah beriman)"],["p","Allah SWT berfirman :"],["a","اِنَّ الَّذِيْنَ كَفَرُوْا بَعْدَ اِيْمَانِهِمْ ثُمَّ ازْدَادُوْا كُفْرًا لَّنْ تُقْبَلَ تَوْبَتُهُمْ ۚ وَاُولٰۤىِٕكَ هُمُ الضَّاۤلُّوْنَ. ال عمران : 90"],["p","Sesungguhnya orang-orang yang kafir sesudah beriman, kemudian bertambah kekafirannya, sekali-kali tidak akan diterima taubatnya; dan mereka itulah orang-orang yang sesat. [QS. Ali ‘Imraan : 90]"],["a","اِنَّ الَّذِيْنَ اٰمَنُوْا ثُمَّ كَفَرُوْا ثُمَّ اٰمَنُوْا ثُمَّ كَفَرُوْا ثُمَّ ازْدَادُوْا كُفْرًا لَّمْ يَكُنِ اللّٰهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيْلًا . النساء : 137"],["p","Sesungguhnya orang-orang yang beriman kemudian kafir, kemudian beriman (pula), kemudian kafir lagi, kemudian bertambah kekafirannya, maka sekali-kali Allah tidak akan memberi ampunan kepada mereka, dan tidak (pula) menunjuki mereka kepada jalan yang lurus. [QS. An Nisaa’ : 137]"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا مَنْ يَّرْتَدَّ مِنْكُمْ عَنْ دِيْنِهٖ فَسَوْفَ يَأْتِى اللّٰهُ بِقَوْمٍ يُّحِبُّهُمْ وَيُحِبُّوْنَهٗٓ ۙ اَذِلَّةٍ عَلَى الْمُؤْمِنِيْنَ اَعِزَّةٍ عَلَى الْكٰفِرِيْنَۖ يُجَاهِدُوْنَ فِيْ سَبِيْلِ اللّٰهِ وَلَا يَخَافُوْنَ لَوْمَةَ لَاۤىِٕمٍ ۗ ذٰلِكَ فَضْلُ اللّٰهِ يُؤْتِيْهِ مَنْ يَّشَاۤءُۗ وَاللّٰهُ وَاسِعٌ عَلِيْمٌ. المائدة : 54"],["p","Hai orang-orang yang beriman, barang siapa di antara kamu yang murtad dari agamanya, maka kelak Allah akan mendatangkan suatu kaum yang Allah mencintai mereka dan mereka pun mencintai-Nya, yang bersikap lemah lembut terhadap orang-orang mukmin, yang bersikap keras terhadap orang-orang kafir, yang berjihad di jalan Allah, dan yang tidak takut kepada celaan orang yang suka mencela. Itulah karunia Allah, diberikan-Nya kepada siapa yang dikehendaki-Nya, dan Allah Maha Luas (pemberian-Nya) lagi Maha Mengetahui. [QS. Al Maaidah : 54]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ عَبْدِ اللهِ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ يَشْهَدُ اَنْ لَا اِلٰهَ اِلَّا اللهُ وَ اَنِّى رَسُوْلُ اللهِ اِلَّا بِاِحْدَى ثَلاَثٍ. الثَّيِّبُ الزَّانِ وَ النَّفْسُ بِالنَّفْسِ وَ التَّارِكُ لِدِيْنِهِ الْمُفَارِقُ لِلْجَمَاعَةِ. مسلم 3: 1302 رقم 25"],["p","Dari Abdullah (bin Mas’ud) ia berkata, Rasulullah SAW bersabda, “Tidak halal darah orang Islam yang bersaksi bahwa tiada Tuhan selain Allah dan bersaksi bahwa aku utusan Allah, kecuali dengan salah satu dari tiga sebab: 1. Orang yang sudah menikah melakukan zina, 2. Karena membunuh orang, dan 3. Orang yang murtad meninggalkan agamanya, memisahkan dari jamaah kaum muslimin”. [HR. Muslim juz 3, hal. 1302, no. 25]"],["p","(Bersambung)"]],"c20221023_1304":[["p","Ahad, 23 Oktober 2022/27 Rabii’ul Awwal 1444 Brosur No. : 2099/2139/IA"],["h","HAL HAL YANG MENGHAPUS AMAL (2)"],["h","4. Riyaa’, sum’ah"],["p","Allah SWT berfirman:"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تُبْطِلُوْا صَدَقٰتِكُمْ بِالْمَنِّ وَالْاَذٰىۙ كَالَّذِيْ يُنْفِقُ مَالَهٗ رِئَاۤءَ النَّاسِ وَلَا يُؤْمِنُ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِۗ فَمَثَلُهٗ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَاَصَابَهٗ وَابِلٌ فَتَرَكَهٗ صَلْدًا ۗ لَا يَقْدِرُوْنَ عَلٰى شَيْءٍ مِّمَّا كَسَبُوْا ۗ وَاللّٰهُ لَا يَهْدِى الْقَوْمَ الْكٰفِرِيْنَ. البقرة :264"],["p","Hai orang-orang beriman, janganlah kamu menghilangkan (pahala) sedekahmu dengan menyebut-nyebutnya dan menyakiti (perasaan si penerima), seperti orang yang menafkahkan hartanya karena riyaa’ kepada manusia dan dia tidak beriman kepada Allah dan hari kemudian. Maka perumpamaan orang itu seperti batu licin yang di atasnya ada tanah, kemudian batu itu ditimpa hujan lebat, lalu menjadilah dia bersih (tidak bertanah). Mereka tidak menguasai sesuatu pun dari apa yang mereka usahakan; dan Allah tidak memberi petunjuk kepada orang-orang yang kafir.[QS. Al Baqarah : 264]"],["a","اِنَّ الْمُنٰفِقِيْنَ يُخٰدِعُوْنَ اللّٰهَ وَهُوَ خَادِعُهُمْۚ وَاِذَا قَامُوْٓا اِلَى الصَّلٰوةِ قَامُوْا كُسَالٰىۙ يُرَاۤءُوْنَ النَّاسَ وَلَا يَذْكُرُوْنَ اللّٰهَ اِلَّا قَلِيْلًا. النساء : 142"],["p","Sesungguhnya orang-orang munafik itu menipu Allah, dan Allah akan membalas tipuan mereka. Dan apabila mereka berdiri untuk shalat mereka berdiri dengan malas. Mereka bermaksud riyaa’ (dengan shalat) di hadapan manusia. Dan tidaklah mereka menyebut Allah kecuali sedikit sekali. [QS. An Nisaa’ : 142]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ مَحْمُوْدِ بْنِ لُبَيْدٍ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اِنَّ اَخْوَفَ مَا اَخَافُ عَلَيْكُمْ اَلشِّرْكُ الْاَصْغَرُ. قَالُوْا: وَمَا الشِّرْكُ الْاَصْغَرُ يَا رَسُوْلَ اللهِ؟ قَالَ: اَلرِّيَاءُ، يَقُوْلُ اللهُ عَزَّ وَجَلَّ لَـهُمْ يَوْمَ الْقِيَامَةِ اِذَا جُزِيَ النَّاسُ بِاَعْمَالِهِمْ: اِذْهَبُوْا اِلىَ الَّذِيْنَ كُنْتُمْ تُرَاءُوْنَ فىِ الدُّنْيَا فَانْظُرُوْا هَلْ تَجِدُوْنَ عِنْدَهُمْ جَزَاءً؟ احمد 9: 160، رقم: 23692"],["p","Dari Mahmud bin Lubaid, bahwasanya Rasulullah SAW bersabda, “Sesungguhnya sesuatu yang paling aku khawatirkan atas kamu sekalian itu adalah syirik kecil”. Kemudian para shahabat bertanya, “Apa syirik kecil itu ya Rasulullah ?”. Rasulullah SAW menjawab, “(Syirik kecil itu ialah) riyaa’. Besok pada hari qiyamat ketika para manusia diberi balasan dengan amal-amal mereka, Allah ‘azza wa jalla akan berfirman kepada mereka, “Pergilah kamu sekalian kepada orang-orang yang dahulu kamu berbuat riyaa’ padanya ketika di dunia, maka lihatlah olehmu sekalian apakah kamu mendapati pahala pada mereka ?”. [HR. Ahmad, juz 9, hal. 160, no. 23692]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: اِنَّ اَوَّلَ النَّاسِ يُقْضَى يَوْمَ الْقِيَامَةِ عَلَيْهِ رَجُلٌ اُسْتُشْهِدَ، فَاُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا. قَالَ: فَمَا عَمِلْتَ فِيْهَا؟ قَالَ: قَاتَلْتُ فِيْكَ حَتَّى اُسْتُشْهِدْتُ. قَالَ: كَذَبْتَ. وَ لٰكِنَّكَ قَاتَلْتَ لِاَنْ يُقَالَ جَرِئٌ، فَقَدْ قِيْلَ. ثُـمَّ اُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ حَتَّى اُلْقِيَ فِى النَّارِ. وَرَجُلٌ تَعَلَّمَ الْعِلْمَ وَعَلَّمَهُ وَقَرَأَ الْقُرْاٰنَ، فَاُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا. قَالَ: فَمَا عَمِلْتَ فِيْهَا؟ قَالَ: تَعَلَّمْتُ الْعِلْمَ وَعَلَّمْتُهُ وَقَرَأْتُ فِيْكَ الْقُرْاٰنَ. قَالَ: كَذَبْتَ، وَلٰكِنَّكَ تَعَلَّمْتَ الْعِلْمَ لِيُقَالَ عَالِـمٌ وَقَرَأْتَ الْقُرْاٰنَ لِيُقَالَ هُوَ قَارِئٌ، فَقَدْ قِيْلَ. ثُـمَّ اُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ حَتَّى اُلْقِيَ فِى النَّارِ. وَرَجُلٌ وَسَّعَ اللهُ عَلَيْهِ وَاَعْطَاهُ مِنْ اَصْنَافِ الْمَالِ كُلِّهِ، فَاُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا. قَالَ: فَمَا عَمِلْتَ فِيْهَا؟ قَالَ: مَا تَرَكْتُ مِنْ سَبِيْلٍ تُحِبُّ اَنْ يُنْفَقَ فِيْهَا اِلَّا اَنْفَقْتُ فِيْهَا لَكَ. قَالَ: كَذَبْتَ، وَلٰكِنَّكَ فَعَلْتَ لِيُقَالَ هُوَ جَوَادٌ، فَقَدْ قِيْلَ. ثُـمَّ اُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ ثُـمَّ اُلْقِيَ فِى النَّارِ. مسلم 3: 1514 رقم 152"],["p","Dari Abu Hurairah RA, ia berkata : Saya mendengar Rasulullah SAW bersabda, “Sesungguhnya yang pertama akan diberi keputusan pada hari qiyamat ialah seorang yang mati syahid, lalu ia dibawa dan dihadapkan kepada ni’mat (kebaikan-kebaikan)nya, maka ia mengakuinya. Allah berfirman, “Apakah yang kamu lakukan padanya ?”. Ia menjawab, “Saya telah berjuang untuk-Mu hingga mati syahid”. Allah berfirman, “Kamu berdusta, tetapi kamu berjuang supaya disebut sebagai pahlawan dan orang pemberani. Dan telah dikatakan orang yang demikian itu”. Kemudian diperintahkan (kepada malaikat), lalu ia diseret pada mukanya dan dilemparkan ke neraka. (Kedua) seorang yang belajar ilmu, mengajarkannya dan membaca Al-Qur’an. Lalu ia dibawa dan dihadapkan kepada ni’mat (kebaikan-kebaikan)nya, maka ia mengakuinya. Allah berfirman, “Apakah yang kamu lakukan padanya?”. Ia menjawab, “Saya mempelajari ilmu dan mengajarkannya serta membaca Al-Qur’an hanya untuk-Mu”. Allah berfirman, “Kamu berdusta, tetapi kamu mempelajari ilmu supaya disebut sebagai seorang yang alim, dan kamu membaca Al-Qur’an supaya disebut sebagai seorang yang pandai membaca Al-Qur’an, dan telah dikatakan orang yang demikian itu”. Kemudian diperintahkan (kepada malaikat), lalu ia diseret pada mukanya dan dilemparkan ke neraka. (Ketiga) seorang hartawan yang diberi bermacam-macam kekayaan oleh Allah, lalu ia dibawa dan dihadapkan kepada ni’mat (kebaikan-kebaikan)nya, maka ia mengakuinya. Allah berfirman, “Apakah yang kamu lakukan padanya ?”. Ia menjawab, “Tidak satu jalanpun yang Engkau sukai agar jalan itu diberi harta, melainkan sudah saya beri dengan harta itu semata-mata untuk-Mu”. Allah berfirman, “Kamu berdusta, tetapi kamu berbuat yang demikian itu agar disebut sebagai orang yang dermawan, dan telah dikatakan orang yang demikian itu”. Kemudian diperintahkan (kepada malaikat) lalu ia diseret pada mukanya dan dilemparkan ke neraka”. [HR. Muslim juz 3, hal. 1514, no. 152]"],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : مَنْ سَمَّعَ، سَمَّعَ اللهُ بِهِ، وَ مَنْ رَاءَى، رَاءَى اللهُ بِهِ. مسلم 4 : 2289 رقم 47"],["p","Dari Ibnu 'Abbas, ia berkata : Rasulullah SAW pernah bersabda, \"Barangsiapa memperdengarkan amal kepada orang lain, maka Allah akan memalukannya (di hari qiyamat). Dan barangsiapa berbuat riyaa', maka Allah akan membalas riyaa'nya itu\". [HR. Muslim juz 4, hal. 2289, no. 47]"],["h","5. Nifaq (munafiq)"],["p","Allah SWT berfirman:"],["a","اِنَّ الْمُنٰفِقِيْنَ يُخٰدِعُوْنَ اللّٰهَ وَهُوَ خَادِعُهُمْۚ وَاِذَا قَامُوْٓا اِلَى الصَّلٰوةِ قَامُوْا كُسَالٰىۙ يُرَاۤءُوْنَ النَّاسَ وَلَا يَذْكُرُوْنَ اللّٰهَ اِلَّا قَلِيْلًاۖ (142) مُّذَبْذَبِيْنَ بَيْنَ ذٰلِكَۖ لَآ اِلٰى هٰٓؤُلَاۤءِ وَلَآ اِلٰى هٰٓؤُلَاۤءِ ۗ وَمَنْ يُّضْلِلِ اللّٰهُ فَلَنْ تَجِدَ لَهٗ سَبِيْلًا(143) يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تَتَّخِذُوا الْكٰفِرِيْنَ اَوْلِيَاۤءَ مِنْ دُوْنِ الْمُؤْمِنِيْنَ ۚ اَتُرِيْدُوْنَ اَنْ تَجْعَلُوْا لِلّٰهِ عَلَيْكُمْ سُلْطٰنًا مُّبِيْنًا(144) اِنَّ الْمُنٰفِقِيْنَ فِى الدَّرْكِ الْاَسْفَلِ مِنَ النَّارِۚ وَلَنْ تَجِدَ لَهُمْ نَصِيْرًاۙ (145) اِلَّا الَّذِيْنَ تَابُوْا وَاَصْلَحُوْا وَاعْتَصَمُوْا بِاللّٰهِ وَاَخْلَصُوْا دِيْنَهُمْ لِلّٰهِ فَاُولٰۤىِٕكَ مَعَ الْمُؤْمِنِيْنَۗ وَسَوْفَ يُؤْتِ اللّٰهُ الْمُؤْمِنِيْنَ اَجْرًا عَظِيْمًا (146) مَا يَفْعَلُ اللّٰهُ بِعَذَابِكُمْ اِنْ شَكَرْتُمْ وَاٰمَنْتُمْۗ وَكَانَ اللّٰهُ شَاكِرًا عَلِيْمًا (147). النساء : 142-147"],["p","Sesungguhnya orang-orang munafiq itu menipu Allah, dan Allah akan membalas tipuan mereka. Dan apabila mereka berdiri untuk shalat mereka berdiri dengan malas. Mereka bermaksud riyaa’ (dengan shalat) di hadapan manusia. Dan tidaklah mereka menyebut Allah kecuali sedikit sekali. (142)"],["p","Mereka dalam keadaan ragu-ragu antara yang demikian (iman atau kafir), tidak masuk kepada golongan ini (orang-orang beriman) dan tidak (pula) kepada golongan itu (orang-orang kafir). Barangsiapa yang disesatkan Allah, maka kamu sekali-kali tidak akan mendapat jalan (untuk memberi petunjuk) baginya. (143)"],["p","Hai orang-orang yang beriman, janganlah kamu mengambil orang-orang kafir menjadi wali dengan meninggalkan orang-orang mukmin. Inginkah kamu mengadakan alasan yang nyata bagi Allah (untuk menyiksamu)? (144)"],["p","Sesungguhnya orang-orang munafiq itu (ditempatkan) pada tingkatan yang paling bawah dari neraka. Dan kamu sekali-kali tidak akan mendapati seorang penolongpun bagi mereka. (145)"],["p","Kecuali orang-orang yang taubat dan mengadakan perbaikan dan berpegang teguh pada (agama) Allah dan tulus ikhlash (mengerjakan) agama mereka karena Allah. Maka mereka itu adalah bersama-sama orang yang beriman dan kelak Allah akan memberikan kepada orang-orang yang beriman pahala yang besar. (146)"],["p","Mengapa Allah akan menyiksamu, jika kamu bersyukur dan beriman? Dan Allah adalah Maha Mensyukuri lagi Maha Mengetahui. (147) [QS. An Nisaa’: 142-147]"],["a","اَلْمُنٰفِقُوْنَ وَالْمُنٰفِقٰتُ بَعْضُهُمْ مِّنْۢ بَعْضٍۘ يَأْمُرُوْنَ بِالْمُنْكَرِ وَيَنْهَوْنَ عَنِ الْمَعْرُوْفِ وَيَقْبِضُوْنَ اَيْدِيَهُمْۗ نَسُوا اللّٰهَ فَنَسِيَهُمْ ۗ اِنَّ الْمُنٰفِقِيْنَ هُمُ الْفٰسِقُوْنَ (67) وَعَدَ اللّٰهُ الْمُنٰفِقِيْنَ وَالْمُنٰفِقٰتِ وَالْكُفَّارَ نَارَ جَهَنَّمَ خٰلِدِيْنَ فِيْهَاۗ هِيَ حَسْبُهُمْ ۚ وَلَعَنَهُمُ اللّٰهُ ۚ وَلَهُمْ عَذَابٌ مُّقِيْمٌ (68) التوبة : 67-68"],["p","Orang-orang munafiq laki-laki dan perempuan, sebagian dengan sebagian yang lain adalah sama, mereka menyuruh berbuat yang mungkar dan melarang berbuat yang ma’ruf dan mereka menggenggamkan tangannya. Mereka telah lupa kepada Allah, maka Allah melupakan mereka. Sesungguhnya orang-orang munafiq itulah orang-orang yang fasik. (67)"],["p","Allah mengancam orang-orang munafiq laki-laki dan perempuan dan orang-orang kafir dengan neraka Jahannam. Mereka kekal di dalamnya. Cukuplah neraka itu bagi mereka; dan Allah melaknati mereka; dan bagi mereka adzab yang kekal, (68) [QS. At Taubah : 67-68]"],["a","اِذَا جَاۤءَكَ الْمُنٰفِقُوْنَ قَالُوْا نَشْهَدُ اِنَّكَ لَرَسُوْلُ اللّٰهِ ۘ وَاللّٰهُ يَعْلَمُ اِنَّكَ لَرَسُوْلُهٗ ۗ وَاللّٰهُ يَشْهَدُ اِنَّ الْمُنٰفِقِيْنَ لَكٰذِبُوْنَۚ (1) اِتَّخَذُوْٓا اَيْمَانَهُمْ جُنَّةً فَصَدُّوْا عَنْ سَبِيْلِ اللّٰهِ ۗ اِنَّهُمْ سَاۤءَ مَا كَانُوْا يَعْمَلُوْنَ (2) ذٰلِكَ بِاَنَّهُمْ اٰمَنُوْا ثُمَّ كَفَرُوْا فَطُبِعَ عَلٰى قُلُوْبِهِمْ فَهُمْ لَا يَفْقَهُوْنَ(3).المنافقون:1-3"],["p","Apabila orang-orang munafiq datang kepadamu, mereka berkata: \"Kami mengakui, bahwa sesungguhnya kamu benar-benar Rasul Allah\". Dan Allah mengetahui bahwa sesungguhnya kamu benar-benar Rasul-Nya; dan Allah mengetahui bahwa sesungguhnya orang-orang munafiq itu benar-benar orang pendusta. (1)"],["p","Mereka itu menjadikan sumpah mereka sebagai perisai, lalu mereka menghalangi (manusia) dari jalan Allah. Sesungguhnya amat buruklah apa yang telah mereka kerjakan. (2)"],["p","Yang demikian itu adalah karena bahwa sesungguhnya mereka telah beriman, kemudian menjadi kafir (lagi) lalu hati mereka dikunci mati; karena itu mereka tidak dapat mengerti.(3) [QS. Al Munaafiquun : 1-3]"],["p","Di dalam hadits disebutkan :"],["a","عَنِ الْعَلَاءِ بْنِ عَبْدِ الرَّحْمٰنِ اَنَّهُ دَخَلَ عَلَى اَنَسِ بْنِ مَالِكٍ فِيْ دَارِهِ بِالْبَصْرَةِ حِيْنَ انْصَرَفَ مِنَ الظُّهْرِ، وَدَارُهُ بِجَنْبِ الْمَسْجِدِ. فَلَمَّا دَخَلْنَا عَلَيْهِ، قَالَ: اَصَلَّيْتُمُ الْعَصْرَ؟ فَقُلْنَا لَهُ: اِنَّـمَا انْصَرَفْنَا السَّاعَةَ مِنَ الظُّهْرِ. قَالَ: فَصَلُّوا الْعَصْرَ. فَقُمْنَا فَصَلَّيْنَا. فَلَمَّا انْصَرَفْنَا قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: تِلْكَ صَلَاةُ الْمُنَافِقِ، يَجْلِسُ يَرْقُبُ الشَّمْسَ، حَتَّى اِذَا كَانَتْ بَيْنَ قَرْنَيِ الشَّيْطَانِ قَامَ فَنَقَرَهَا اَرْبَعًا، لَا يَذْكُرُاللهَ فِيْهَا اِلَّا قَلِيْلًا. مسلم 1: 434 رقم 195"],["p","Dari Al-‘Alaa’ bin ‘Abdur Rahman bahwasanya ia datang kepada Anas bin Maalik di rumahnya di Bashrah, ketika itu ia baru saja melaksanakan shalat Dhuhur, sedangkan rumah Anas bin Malik berada di samping masjid. Ketika kami masuk kepadanya, ia bertanya, “Apakah kalian sudah shalat ‘Ashar ?”. Kami menjawab, “Kami baru saja melaksanakan shalat Dhuhur”. Anas berkata, “Shalat ‘Ashar lah kalian”. Lalu kami melaksanakan shalat ‘Ashar. Setelah selesai shalat, Anas berkata : Saya mendengar Rasulullah SAW bersabda, \"Itu adalah shalatnya orang munafiq, yaitu ia menunggu sambil mengintai matahari, sehingga apabila matahari berada diantara dua tanduk syaithan, ia baru berdiri untuk shalat, dan ia cepatkan shalatnya (seperti ayam mematuk makanan) empat raka'at, ia tidak mengingat kepada Allah dalam shalatnya itu kecuali sedikit\". [HR. Muslim juz 1, hal. 434, no. 195]"],["a","عَنْ اَنَسٍ اَنَّ النَّبِيَّ ﷺ قَالَ: اِنَّ الْعَبْدَ اِذَا وُضِعَ فِيْ قَبْرِهِ وَتَوَلَّى عَنْهُ اَصْحَابُهُ اَنَّهُ لَيَسْمَعُ قَرْعَ نِعَالِهِمْ، اَتَاهُ مَلَكَانِ فَيُقْعِدَانِهِ فَيَقُوْلَانِ لَهُ: مَا كُنْتَ تَقُوْلُ فِيْ هٰذَا الرَّجُلِ مُحَمَّدٍ ﷺ ؟ فَاَمَّا الْمُؤْمِنُ فَيَقُوْلُ: اَشْهَدُ اَنَّهُ عَبْدُ اللهِ وَرَسُوْلُهُ. فَيُقَالُ لَهُ: اُنْظُرْ اِلَى مَقْعَدِكَ مِنَ النَّارِ قَدْ اَبْدَلَكَ اللهُ بِهِ مَقْعَدًا خَيْرًا مِنْهُ. قَالَ رَسُوْلُ اللهِ ﷺ : فَيَرَاهُمَا جَمِيْعًا. وَاَمَّا الْكَافِرُ اَوِ الْمُنَافِقُ فَيُقَالُ لَهُ: مَا كُنْتَ تَقُوْلُ فِيْ هٰذَا الرَّجُلِ؟ فَيَقُوْلُ: لَا اَدْرِيْ، كُنْتُ اَقُوْلُ كَمَا يَقُوْلُ النَّاسُ. فَيُقَالُ لَهُ: لَا دَرَيْتَ وَلَا تَلَيْتَ. ثُـمَّ يُضْرَبُ ضَرْبَةً بَيْنَ اُذُنَيْهِ فَيَصِيْحُ صَيْحَةً يَسْمَعُهَا مَنْ يَلِيْهِ غَيْرُ الثَّقَلَيْنِ. النسائى 4: 97"],["p","Dari Anas bahwasanya Nabi SAW bersabda, “Sesungguhnya seorang hamba apabila sudah diletakkan di quburnya dan teman-temannya sudah berpaling meninggalkannya, maka si mayyit masih mendengar suara sandal mereka, lalu datanglah dua malaikat mendudukkannya, lalu keduanya bertanya, “Apa pendapatmu tentang orang laki-laki ini yakni Muhammad SAW ?”. Adapun orang yang beriman, ia akan menjawab, “Aku bersaksi bahwasanya dia adalah hamba Allah dan utusan-Nya”. Lalu dikatakan kepadanya, “Lihatlah kepada tempat dudukmu yang di neraka telah diganti Allah dengan tempat duduk yang lebih baik dari padanya”. Rasulullah SAW bersabda, “Maka ia melihat keduanya (surga dan neraka). Adapun orang yang kafir atau munafiq, maka ditanyakan kepadanya, “Apa pendapatmu tentang orang laki-laki ini?”. Maka dia akan menjawab, “Aku tidak tahu, aku mengatakannya seperti halnya orang-orang mengatakannya”. Maka dikatakan kepadanya, “Kamu tidak tahu dan kamu tidak mau membaca”. Kemudian ia dipukul dengan satu pukulan antara kedua telinganya, hingga ia berteriak dengan teriakan yang didengar oleh apasaja yang di sekelilingnya, selain jinn dan manusia”. [HR. Nasaaiy juz 4, hal. 97]"],["h","6. Mengundat-undat pemberian"],["p","Allah SWT berfirman :"],["a","اَلَّذِيْنَ يُنْفِقُوْنَ اَمْوَالَهُمْ فِيْ سَبِيْلِ اللّٰهِ ثُمَّ لَا يُتْبِعُوْنَ مَآ اَنْفَقُوْا مَنًّا وَّلَآ اَذًىۙ لَّهُمْ اَجْرُهُمْ عِنْدَ رَبِّهِمْۚ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُوْنَ (262) قَوْلٌ مَّعْرُوْفٌ وَّمَغْفِرَةٌ خَيْرٌ مِّنْ صَدَقَةٍ يَّتْبَعُهَآ اَذًى ۗ وَاللّٰهُ غَنِيٌّ حَلِيْمٌ (263). البقرة : 262-263"],["p","Orang-orang yang menafkahkan hartanya di jalan Allah, kemudian mereka tidak mengiringi apa yang dinafkahkannya itu dengan menyebut-nyebut pemberiannya dan dengan tidak menyakiti (perasaan si penerima), mereka memperoleh pahala di sisi Tuhan mereka. Tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati. (262)"],["p","Perkataan yang baik dan pemberian maaf lebih baik dari sedekah yang diiringi dengan sesuatu yang menyakitkan (perasaan si penerima). Allah Maha Kaya lagi Maha Penyantun. (263) [QS. Al Baqarah : 262-263]"],["a","يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تُبْطِلُوْا صَدَقٰتِكُمْ بِالْمَنِّ وَالْاَذٰىۙ كَالَّذِيْ يُنْفِقُ مَالَهٗ رِئَاۤءَ النَّاسِ وَلَا يُؤْمِنُ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِۗ فَمَثَلُهٗ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَاَصَابَهٗ وَابِلٌ فَتَرَكَهٗ صَلْدًا ۗ لَا يَقْدِرُوْنَ عَلٰى شَيْءٍ مِّمَّا كَسَبُوْا ۗ وَاللّٰهُ لَا يَهْدِى الْقَوْمَ الْكٰفِرِيْنَ. البقرة : 264"],["p","Hai orang-orang beriman, janganlah kamu menghilangkan (pahala) sedekahmu dengan menyebut-nyebutnya dan menyakiti (perasaan si penerima), seperti orang yang menafkahkan hartanya karena riyaa’ kepada manusia dan dia tidak beriman kepada Allah dan hari kemudian. Maka perumpamaan orang itu seperti batu licin yang di atasnya ada tanah, kemudian batu itu ditimpa hujan lebat, lalu menjadilah dia bersih (tidak bertanah). Mereka tidak menguasai sesuatu pun dari apa yang mereka usahakan; dan Allah tidak memberi petunjuk kepada orang-orang yang kafir. (264) [QS. Al Baqarah : 264]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ عَبْدِ اللهِ بْنِ يَسَارٍ اَلْاَعْرَجِ اَنَّهُ سَمِعَ سَالِمًا يُحَدِّثُ عَنْ اَبِيْهِ عَنِ النَّبِيِّ ﷺ قَالَ: ثَلَاثَةٌ لَا يَنْظُرُ اللهُ اِلَيْهِمْ يَوْمَ الْقِيَامَةِ، عَاقُّ وَالِدَيْهِ وَمُدْمِنُ الْخَمْرِ وَمَنَّانٌ بِمَا اَعْطَى. الحاكم فى المستدرك 4: 163، رقم: 7235، هذا حديث صحيح الاسناد ولم يخرجاه"],["p","Dari ‘Abdullah bin Yasar Al-A’raj bahwasanya ia mendengar Salim menceritakan dari ayahnya, dari Nabi SAW, bahwasanya beliau bersabda, “Tiga orang yang Allah tidak akan melihat kepada mereka pada hari qiyamat, orang yang durhaka kepada kedua orang tuanya, peminum khamr dan orang yang mengundat-undat pemberian”. [HR. Hakim dalam Al-Mustadrak juz 4, hal. 163, no. 7235]"],["a","عَنْ سَالِمِ بْنِ عَبْدِ اللهِ عَنْ اَبِيْهِ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : ثَلَاثَةٌ لَا يَنْظُرُ اللهُ عَزَّ وَجَلَّ اِلَيْهِمْ يَوْمَ الْقِيَامَةِ: اَلْعَاقُّ لِوَالِدَيْهِ وَالْمَرْأَةُ الْمُتَرَجِّلَةُ وَالدَّيُّوثُ، وَثَلَاثَةٌ لَا يَدْخُلُوْنَ الْجَنَّةَ: اَلْعَاقُّ لِوَالِدَيْهِ وَالْمُدْمِنُ عَلَى الْخَمْرِ وَالْمَنَّانُ بِمَا اَعْطَى. النسائي 5 : 80"],["p","Dari Salim bin 'Abdullah dari ayahnya, ia berkata; Rasulullah SAW, bersabda: \"Ada tiga golongan yang Allah “Azza wa Jalla tidak mau melihat mereka pada hari qiyamat: 1) Orang yang durhaka kepada kedua orang tua, 2) Wanita yang bergaya menyerupai laki-laki, dan 3) Dayyuts (orang yang membiarkan perzinaan di rumahnya). Dan ada tiga golongan yang mereka tidak akan masuk surga: 1) Orang yang durhaka kepada kedua orang tua, 2) Peminum khamr, dan 3) Orang yang selalu menyebut-nyebut pemberiannya.\" [HR. Nasaaiy Juz 5, hal 80]"],["a","قَالَ عَبْدُ اللهِ: قَالَ رَسُوْلُ اللهِ ﷺ : ثَلَاثٌ لَا يَدْخُلُوْنَ الْجَنَّةَ وَلَا يَنْظُرُ اللهُ اِلَيْهِمْ يَوْمَ الْقِيَامَةِ: اَلْعَاقُّ وَالِدَيْهِ وَالْمَرْأَةُ الْمُتَرَجِّلَةُ الْمُتَشَبِّهَةُ بِالرِّجَالِ وَالدَّيُّوْثُ، وَثَلَاثَةٌ لَا يَنْظُرُ اللهُ اِلَيْهِمْ يَوْمَ الْقِيَامَةِ: اَلْعَاقُّ وَالِدَيْهِ وَالْمُدْمِنُ مِنَ الْخَمْرِ وَالْمَنَّانُ بِمَا اَعْطَى. احمد 2 : 496 رقم 6188"],["p","Berkata ‘Abdullah (bin ‘Umar), Rasulullah SAW bersabda:” Ada tiga golongan yang tidak akan masuk surga, dan Allah tidak memperhatikan mereka pada hari qiyamat : 1) Orang yang durhaka kepada kedua orang tua, 2) Wanita yang bergaya laki laki yaitu yang menyerupai laki laki, dan 3) Dayyuts (membiarkan perzinaan di rumahnya). Dan tiga golongan yang Allah tidak memperhatikan mereka pada hari qiyamat: 1) Orang yang durhaka kepada kedua orang tua, 2) Peminum khamr, dan 3) Orang yang selalu menyebut-nyebut pemberiannya. [HR. Ahmad Juz 2, hal 496, no 6188]"],["p","(Bersambung)"]],"c20221030_1305":[["p","Ahad, 30 Oktober 2022/4 Rabii’ul Aakhir 1444 Brosur No. : 2100/2140/IA"],["h","HAL HAL YANG MENGHAPUS AMAL (3)"],["h","7. Beramal dengan niat duniawi"],["p","Allah SWT berfirman:"],["a","لَا يَغُرَّنَّكَ تَقَلُّبُ الَّذِيْنَ كَفَرُوْا فِى الْبِلَادِۗ (196) مَتَاعٌ قَلِيْلٌ ۗ ثُمَّ مَأْوٰىهُمْ جَهَنَّمُ ۗ وَبِئْسَ الْمِهَادُ (197) لٰكِنِ الَّذِيْنَ اتَّقَوْا رَبَّهُمْ لَهُمْ جَنّٰتٌ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَا نُزُلًا مِّنْ عِنْدِ اللّٰهِ ۗ وَمَا عِنْدَ اللّٰهِ خَيْرٌ لِّلْاَبْرَارِ (198) ال عمران : 196-198"],["p","Janganlah sekali-kali kamu terperdaya oleh kebebasan orang-orang kafir bergerak di dalam negeri. (196)"],["p","Itu hanyalah kesenangan sementara, kemudian tempat tinggal mereka ialah Jahannam; dan Jahannam itu adalah tempat yang seburuk-buruknya. (197)"],["p","Akan tetapi orang-orang yang bertakwa kepada Tuhan-nya bagi mereka surga yang mengalir sungai-sungai di dalamnya, sedang mereka kekal di dalamnya sebagai tempat tinggal (anugerah) dari sisi Allah. Dan apa yang di sisi Allah adalah lebih baik bagi orang-orang yang berbakti. (198) [QS. Ali ‘Imraan : 196 – 198]"],["a","مَنْ كَانَ يُرِيْدُ ثَوَابَ الدُّنْيَا فَعِنْدَ اللّٰهِ ثَوَابُ الدُّنْيَا وَالْاٰخِرَةِ ۗ وَكَانَ اللّٰهُ سَمِيْعًاۢ بَصِيْرًا. النساء : 134"],["p","Barangsiapa yang menghendaki pahala di dunia saja (maka ia merugi), karena di sisi Allah ada pahala dunia dan akhirat. Dan Allah Maha Mendengar lagi Maha Melihat. [QS. An Nisaa’ : 134]"],["a","مَنْ كَانَ يُرِيْدُ الْحَيٰوةَ الدُّنْيَا وَزِيْنَتَهَا نُوَفِّ اِلَيْهِمْ اَعْمَالَهُمْ فِيْهَا وَهُمْ فِيْهَا لَا يُبْخَسُوْنَ (15) اُولٰۤىِٕكَ الَّذِيْنَ لَيْسَ لَهُمْ فِى الْاٰخِرَةِ اِلَّا النَّارُ ۖ وَحَبِطَ مَا صَنَعُوْا فِيْهَا وَبٰطِلٌ مَّا كَانُوْا يَعْمَلُوْنَ (16) هود : 15-16"],["p","Barangsiapa yang menghendaki kehidupan dunia dan perhiasannya, niscaya Kami berikan kepada mereka balasan pekerjaan mereka di dunia dengan sempurna dan mereka di dunia itu tidak akan dirugikan. (15)"],["p","Itulah orang-orang yang tidak memperoleh di akhirat, kecuali neraka dan lenyaplah di akhirat itu apa yang telah mereka usahakan di dunia dan sia-sialah apa yang telah mereka kerjakan? (16) [QS. Huud : 15-16]"],["a","مَنْ كَانَ يُرِيْدُ الْعَاجِلَةَ عَجَّلْنَا لَهٗ فِيْهَا مَا نَشَاۤءُ لِمَنْ نُّرِيْدُ ثُمَّ جَعَلْنَا لَهٗ جَهَنَّمَۚ يَصْلٰىهَا مَذْمُوْمًا مَّدْحُوْرًا (18) وَمَنْ اَرَادَ الْاٰخِرَةَ وَسَعٰى لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَاُولٰۤىِٕكَ كَانَ سَعْيُهُمْ مَّشْكُوْرًا (19) كُلًّا نُّمِدُّ هٰٓؤُلَاۤءِ وَهٰٓؤُلَاۤءِ مِنْ عَطَاۤءِ رَبِّكَ ۗ وَمَا كَانَ عَطَاۤءُ رَبِّكَ مَحْظُوْرًا (20) الاسراء : 18-20"],["p","Barangsiapa menghendaki kehidupan sekarang (duniawi), maka Kami segerakan baginya di dunia itu apa yang Kami kehendaki bagi orang yang Kami kehendaki dan Kami tentukan baginya neraka Jahannam; ia akan memasukinya dalam keadaan tercela dan terusir. (18)"],["p","Dan barangsiapa yang menghendaki kehidupan akhirat dan berusaha ke arah itu dengan sungguh-sungguh sedang ia adalah mukmin, maka mereka itu adalah orang-orang yang usahanya dibalas dengan baik. (19)"],["p","Kepada masing-masing golongan baik golongan ini maupun golongan itu Kami berikan bantuan dari kemurahan Tuhanmu. Dan kemurahan Tuhanmu tidak dapat dihalangi. (20) [ QS. Al Israa’ : 18-20]"],["a","مَنْ كَانَ يُرِيْدُ حَرْثَ الْاٰخِرَةِ نَزِدْ لَهٗ فِيْ حَرْثِهٖۚ وَمَنْ كَانَ يُرِيْدُ حَرْثَ الدُّنْيَا نُؤْتِهٖ مِنْهَاۙ وَمَا لَهٗ فِى الْاٰخِرَةِ مِنْ نَّصِيْبٍ. الشورى : 20"],["p","Barangsiapa yang menghendaki keuntungan di akhirat akan Kami tambah keuntungan itu baginya dan barangsiapa yang menghendaki keuntungan di dunia Kami berikan kepadanya sebagian dari keuntungan dunia dan tidak ada baginya suatu bahagian pun di akhirat. [QS. Asy Syuuraa : 20]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ عُمَرَ بْنِ اْلخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: اِنَّـمَا الْاَعْمَالُ بِالنِّيَّاتِ وَاِنَّـمَا لِكُلِّ امْرِئٍ مَا نَوَى. فَمَنْ كَانَتْ هِجْرَتُهُ اِلىَ دُنْيَا يُصِيْبُهَا اَوِ امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ اِلىَ مَا هَاجَرَ اِلَيْهِ. البخارى 1: 2"],["p","Dari Umar bin Khaththab RA, ia berkata : Saya mendengar Rasulullah SAW bersabda, \"Sesungguhnya amal perbuatan itu tergantung pada niatnya. Dan sesungguhnya setiap orang akan mendapatkan balasan sesuai dengan niatnya. Maka barangsiapa yang berhijrah karena menginginkan keuntungan dunia yang akan didapatnya atau karena menginginkan wanita yang dia akan mengawininya, maka hijrahnya itu akan mendapatkan sesuai apa yang ia berniat hijrah padanya\". [HR. Bukhari juz 1, hal. 2]"],["a","عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ ﷺ اُرَاهُ يَقُوْلُ: اَلْاَعْمَالُ بِالنِّيَّةِ. فَمَنْ كَانَتْ هِجْرَتُهُ اِلىَ دُنْيَا يُصِيْبُهَا اَوِ امْرَأَةٍ يَتَزَوَّجُهَا فَهِجْرَتُهُ اِلىَ مَا هَاجَرَ اِلَيْهِ. وَمَنْ كَانَتْ هِجْرَتُهُ اِلَى اللهِ وَرَسُوْلِهِ فَهِجْرَتُهُ اِلىَ اللهِ وَ رَسُوْلِهِ ﷺ. البخارى 4: 252"],["p","Dari ‘Umar RA, ia berkata : Saya mendengar Nabi SAW bersabda, \"Amal perbuatan itu tergantung niatnya. Maka barangsiapa yang hijrahnya karena menginginkan dunia yang akan ia dapatkan, atau wanita yang ia akan mengawininya, maka hijrahnya itu akan diberi balasan sesuai niatnya ia berhijrah. Dan barangsiapa yang hijrahnya itu karena thaat kepada Allah dan Rasul-Nya, maka hijrahnya itu akan diberi balasan pahala thaat kepada Allah dan Rasul-Nya SAW\". [HR. Bukhari juz 4, hal. 252]"],["a","عَنْ عُمَرَ بْنِ سُلَيْمَانَ قَالَ : سَمِعْتُ عَبْدَ الرَّحْمٰنِ بْنَ اَبَانَ بْنِ عُثْمَانَ بْنِ عَفَّانَ عَنْ اَبِيْهِ قَالَ: خَرَجَ زَيْدُ بْنُ ثَابِتٍ مِنْ عِنْدِ مَرْوَانَ بِنِصْفِ النَّهَارِ. قُلْتُ: مَا بَعَثَ اِلَيْهِ هٰذِهِ السَّاعَةَ اِلَّا لِشَيْءٍ سَأَلَ عَنْهُ. فَسَأَلْتُهُ. فَقَالَ: سَأَلَنَا عَنْ اَشْيَاءَ سَمِعْنَاهَا مِنْ رَسُوْلِ اللهِ ﷺ. سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: مَنْ كَانَتِ الدُّنْيَا هَمَّهُ فَرَّقَ اللهُ عَلَيْهِ اَمْرَهُ وَجَعَلَ فَقْرَهُ بَيْنَ عَيْنَيْهِ وَلَمْ يَأْتِهِ مِنَ الدُّنْيَا اِلَّا مَا كُتِبَ لَهُ. وَمَنْ كَانَتِ الْآخِرَةُ نِيَّتَهُ جَمَعَ اللهُ لَهُ اَمْرَهُ وَجَعَلَ غِنَاهُ فِيْ قَلْبِهِ وَاَتَتْهُ الدُّنْيَا وَهِيَ رَاغِمَةٌ. ابن ماجه 2 : 1375 رقم 4105"],["p","Dari ‘Umar bin Sulaiman, ia berkata : Saya mendengar ‘Abdurrahman bin Abaan bin ‘Utsman bin ‘affan, dari ayahnya (Abaan bin ‘Utsman) , ia berkata: Zaid bin Tsaabit keluar dari sisi Marwan di saat siang hari, akupun berkata (dalam hati) : “Tidaklah beliau mengutus seseorang kepadanya di saat seperti ini kecuali untuk menanyakan sesuatu kepadanya.” Lalu aku bertanya kepadanya. Maka ia (Zaid bin Tsaabit) menjawab : “Beliau menanyakan kepada kami tentang hal-hal yang kami pernah mendengarnya dari Rasulullah SAW. Aku pernah mendengar Rasulullah SAW bersabda : “Barangsiapa menjadikan dunia sebagai keinginannya, maka Allah akan mencerai-beraikan urusannya, dan Allah akan menjadikan kefaqiran di depan kedua matanya, dan keduniaan tidak akan datang kepadanya melainkan sekedar yang telah ditetapkan untuknya. Dan barangsiapa menjadikan akherat sebagai niatannya, maka Allah akan mengumpulkan urusannya, dan menjadikannya kaya hati, dan dunia akan datang kepadanya dengan tunduk.” [HR. Ibnu Majah juz 2, hal 1375 no 4105]"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : مَنْ كَانَتْ الْآخِرَةُ هَمَّهُ جَعَلَ اللهُ غِنَاهُ فِيْ قَلْبِهِ وَجَمَعَ لَهُ شَمْلَهُ وَاَتَتْهُ الدُّنْيَا وَهِيَ رَاغِمَةٌ. وَمَنْ كَانَتِ الدُّنْيَا هَمَّهُ جَعَلَ اللهُ فَقْرَهُ بَيْنَ عَيْنَيْهِ وَفَرَّقَ عَلَيْهِ شَمْلَهُ وَلَمْ يَأْتِهِ مِنَ الدُّنْيَا اِلَّا مَا قُدِّرَ لَهُ. الترمذى 4 : 57 رقم 2583"],["p","Dari Anas bin Maalik, ia berkata ; Rasululullah SAW bersabda : “Barangsiapa akherat menjadi keinginannya (tujuannya), maka Allah menjadikan kekayaannya di hatinya dan Allah mengumpulkan urusannya (menjadikannya mudah) dan dunia akan datang kepadanya dengan tunduk. Dan barangsiapa dunia menjadi keinginannya, maka Allah akan menjadikan kefaqirannya (kebutuhan-kebutuhannya) di depan kedua matanya dan Allah mencerai-beraikan urusannya dan dunia tidak datang kepadanya melainkan sekedar yang telah ditaqdirkan untuknya.” [HR. Tirmidzi, juz 4, hal. 57, no. 2583]"],["h","8. Melakukan bid’ah"],["p","Allah SWT berfirman:"],["a","وَمَآ اٰتٰىكُمُ الرَّسُوْلُ فَخُذُوْهُ وَمَا نَهٰىكُمْ عَنْهُ فَانْتَهُوْاۚ وَاتَّقُوا اللّٰهَ ۗ اِنَّ اللّٰهَ شَدِيْدُ الْعِقَابِ. الحشر : 7"],["p","Apa yang diberikan Rasul kepadamu, maka terimalah. Dan apa yang dilarangnya bagimu tinggalkanlah. Dan bertakwalah kepada Allah. Sesungguhnya Allah sangat keras hukuman-Nya. [QS. Al Hasyr : 7]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ عَائِشَةَ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: مَنْ عَمِلَ عَمَلاً لَيْسَ عَلَيْهِ اَمْرُنَا فَهُوَ رَدٌّ. مسلم 3: 1344 رقم 18"],["p","Dari ‘Aisyah bahwasanya Rasulullah SAW bersabda, “Barangsiapa yang melakukan suatu amalan yang bukan perintah kami, maka ia tertolak”. [HR. Muslim juz 3, hal. 1344, no 18]"],["a","عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ اَحْدَثَ فِيْ اَمْرِنَا هٰذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ. مسلم 3: 1343 رقم 17"],["p","Dari ‘Aisyah, ia berkata : Rasulullah SAW bersabda, “Barangsiapa mengada-adakan dalam perintah kami ini, apa-apa yang bukan dari padanya, maka ia tertolak”. [HR. Muslim juz 3, hal. 1343, no.17]"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اِنَّ اَصْدَقَ الْحَدِيْثِ كِتَابُ اللهِ وَ اَحْسَنَ الْهَدْيِ هَدْيُ مُحَمَّدٍ وَ شَرُّ الْاُمُوْرِ مُحْدَثَاتُهَا وَ كُلُّ مُحْدَثَةٍ بِدْعَةٌ وَ كُلُّ بِدْعَةٍ ضَلَالَةٌ وَ كُلُّ ضَلَالَةٍ فِي النَّارِ. النسائى 3: 188"],["p","Dari Jabir bin ‘Abdullah, ia berkata : Rasulullah SAW bersabda, “Sesungguhnya sebenar-benar perkataan ialah Kitab Allah, dan sebaik-baik petunjuk ialah petunjuk Muhammad, dan sejelek-jelek perkara itu yang diada-adakan, dan tiap-tiap yang diada-adakan itu bid’ah, dan tiap-tiap bid’ah itu sesat, dan tiap-tiap kesesatan itu di neraka”. [HR. Nasaai juz 3, hal. 188]"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ يَقُوْلُ: اَمَّا بَعْدُ، فَاِنَّ خَيْرَ الْحَدِيْثِ كِتَابُ اللهِ وَ خَيْرُ الْهُدَى هُدَى مُحَمَّدٍ وَ شَرُّ الْاُمُوْرِ مُحْدَثَاتُهَا وَ كُلُّ بِدْعَةٍ ضَلاَلَةٌ. مسلم 2: 592 رقم 43"],["p","Dari Jabir bin ‘Abdullah, ia berkata : Dahulu Rasulullah SAW bersabda, “Adapun sesudah itu, sesungguhnya sebaik-baik perkataan adalah kitab Allah, dan sebaik-baik petunjuk adalah petunjuk Muhammad, dan seburuk-buruk perkara adalah yang diada-adakan, dan setiap bid’ah adalah sesat. [HR. Muslim juz 2, hal. 592, no 43]"],["p","9, Durhaka kepada kedua orang tua"],["p","Allah SWT berfirman :"],["a","وَقَضٰى رَبُّكَ اَلَّا تَعْبُدُوْٓا اِلَّآ اِيَّاهُ وَبِالْوَالِدَيْنِ اِحْسٰنًاۗ اِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ اَحَدُهُمَآ اَوْ كِلٰهُمَا فَلَا تَقُلْ لَّهُمَآ اُفٍّ وَّلَا تَنْهَرْهُمَا وَقُلْ لَّهُمَا قَوْلًا كَرِيْمًا (23) وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيٰنِيْ صَغِيْرًا (24) الاسراء : 23-24"],["p","Dan Tuhanmu telah memerintahkan supaya kamu jangan menyembah selain Dia dan hendaklah kamu berbuat baik pada ibu bapakmu dengan sebaik-baiknya. Jika salah seorang di antara keduanya atau kedua-duanya sampai berumur lanjut dalam pemeliharaanmu, maka sekali-kali janganlah kamu mengatakan kepada keduanya perkataan \"ah\" dan janganlah kamu membentak mereka dan ucapkanlah kepada mereka perkataan yang mulia. (23)"],["p","Dan rendahkanlah dirimu terhadap mereka berdua dengan penuh kesayangan dan ucapkanlah: \"Wahai Tuhanku, kasihilah mereka keduanya, sebagaimana mereka berdua telah mendidik aku di waktu kecil\". (24) [ QS. Al Israa’ : 23-24]"],["a","وَوَصَّيْنَا الْاِنْسَانَ بِوَالِدَيْهِ حُسْنًا ۗ وَاِنْ جَاهَدٰكَ لِتُشْرِكَ بِيْ مَا لَيْسَ لَكَ بِهٖ عِلْمٌ فَلَا تُطِعْهُمَا ۗ اِلَيَّ مَرْجِعُكُمْ فَاُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُوْنَ. العنكبوت : 8"],["p","Dan Kami wajibkan manusia (berbuat) kebaikan kepada dua orang ibu-bapaknya. Dan jika keduanya memaksamu untuk mempersekutukan Aku dengan sesuatu yang tidak ada pengetahuanmu tentang itu, maka janganlah kamu mengikuti keduanya. Hanya kepada-Ku-lah kembalimu, lalu Aku kabarkan kepadamu apa yang telah kamu kerjakan. [QS. Al Ankabuut : 8]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ عَبْدِ الرَّحْمٰنِ بْنِ اَبِيْ بَكْرَةَ عَنْ اَبِيْهِ قَالَ: كُنَّا عِنْدَ رَسُوْلِ اللهِ ﷺ فَقَالَ: اَلَا اُنَبِّئُكُمْ بِاَكْبَرِ الْكَبَائِرِ؟ ثَلَاثًا. اَلْاِشْرَاكُ بِاللهِ وَعُقُوْقُ الْوَالِدَيْنِ وَشَهَادَةُ الزُّوْرِ، اَوْ قَوْلُ الزُّوْرِ. وَكَانَ رَسُوْلُ اللهِ ﷺ مُتَّكِئًا فَجَلَسَ. فَمَا زَالَ يُكَرِّرُهَا حَتَّى قُلْنَا: لَيْتَهُ سَكَتَ. مسلم 1: 91 رقم 143"],["p","Dari ‘Abdur Rahman bin Abu Bakrah dari ayahnya, ia berkata : Dahulu kami sedang di sisi Rasulullah SAW, lalu beliau bersabda, “Maukah aku beritahukan kepada kalian tentang sebesar-besar dosa besar ?\". Beliau mengulanginya tiga kali. Beliau SAW bersabda, “Mensekutukan Allah dengan sesuatu, durhaka kepada kedua orang tua dan menjadi saksi palsu, atau berkata bohong\". Pada waktu itu beliau dalam keadaan bersandar, kemudian beliau duduk tegak dan beliau mengulang-ulang kalimat itu, sehingga (di dalam hati) kami berkata, “Semoga beliau diam\". [HR. Muslim juz 1, hal. 91, no. 143]"],["a","عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو عَنِ النَّبِيِّ ﷺ قَالَ: اَلْكَبَائِرُ اَلْاِشْرَاكُ بِاللهِ وَعُقُوْقُ الْوَالِدَيْنِ وَقَتْلُ النَّفْسِ وَالْيَمِيْنُ الْغَمُوْسُ. البخارى 7: 228"],["p","Dari Abdullah bin 'Amr, dari Nabi SAW, beliau bersabda, “Dosa-dosa besar ialah mensekutukan Allah dengan sesuatu, durhaka kepada kedua orang tua, membunuh orang, dan sumpah palsu\". [HR. Bukhari juz 7, hal. 228]"],["a","عَنْ اَنَسٍ عَنِ النَّبِيِّ ﷺ فِى الْكَبَائِرِ قَالَ: اَلشِّرْكُ بِاللهِ وَعُقُوْقُ الْوَالِدَيْنِ وَقَتْلُ النَّفْسِ وَقَوْلُ الزُّوْرِ. مسلم 1: 91 رقم 144"],["p","Dari Anas, dari Nabi SAW, beliau bersabda tentang dosa-dosa besar, “Menyekutukan Allah dengan sesuatu, durhaka kepada kedua orang tua, membunuh orang dan berkata dusta\". [HR. Muslim juz 2, hal. 91, no. 144]"],["a","عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو بْنِ اْلعَاصِ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: مِنَ الْكَبَائِرِ شَتْمُ الرَّجُلِ وَالِدَيْهِ. قَالُوْا: يَا رَسُوْلَ اللهِ وَهَلْ يَشْتِمُ الرَّجُلُ وَالِدَيْهِ؟ قَالَ: نَعَمْ، يَسُبُّ اَبَا الرَّجُلِ فَيَسُبُّ اَبَاهُ وَيَسُبُّ اُمَّهُ فَيَسُبُّ اُمَّهُ. مسلم 1: 92 رقم 146"],["p","Dari Abdullah bin 'Amr bin Al-'Ash, ia berkata : Sesungguhnya Rasulullah SAW bersabda, “Termasuk dosa-dosa besar ialah seseorang mencaci maki kepada kedua orang tuanya\". Mereka (para shahabat) bertanya, “Ya Rasulullah, apakah ada seseorang mencaci maki kedua orang tuanya ?\". Beliau SAW bersabda, “Ya, ada. Seseorang mencaci maki ayah orang lain, lalu orang lain itu membalas mencaci maki ayah orang itu dan seseorang mencaci maki ibu orang lain, lalu orang lain itu membalas mencaci maki ibunya\". [HR. Muslim juz 1, hal. 92 no. 146]"],["a","عَنْ اَبِي الطُّفَيْلِ قَالَ: قُلْنَا لِعَلِيِّ بْنِ اَبِيْ طَالِبٍ: اَخْبِرْنَا بِشَيْءٍ اَسَرَّهُ اِلَيْكَ رَسُوْلُ اللّٰهِ ﷺ . فَقَالَ: مَا اَسَرَّ اِلَيَّ شَيْئًا كَتَمَهُ النَّاسَ، وَلٰكِنِّيْ سَمِعْتُهُ يَقُوْلُ: لَعَنَ اللّٰهُ مَنْ ذَبَحَ لِغَيْرِ اللّٰهِ، وَلَعَنَ اللّٰهُ مَنْ آوَى مُحْدِثًا، وَلَعَنَ اللّٰهُ مَنْ لَعَنَ وَالِدَيْهِ، وَلَعَنَ اللّٰهُ مَنْ غَيَّرَ الْمَنَارَ. مسلم 3: 1567 رقم 44"],["p","Dari Abuth-Thufail, ia berkata : Kami berkata kepada 'Ali bin Abi Thalib, \"Beritahukanlah kepada kami sesuatu yang Rasulullah SAW merahasiakannya kepadamu !\". Maka 'Ali menjawab, \"Rasulullah SAW tidak merahasiakan kepadaku akan sesuatu yang beliau sembunyikan dari orang-orang, tetapi aku pernah mendengar beliau bersabda, \"Allah mela'nat orang yang menyembelih untuk selain Allah (bukan karena Allah), Allah mela'nat orang yang melindungi orang yang membuat bid'ah, Allah mela'nat orang yang mela'nat kedua orang tuanya, dan Allah mela'nat orang yang merubah tanda batas pekarangan\". [HR. Muslim juz 3, hal. 1567, no. 44]"],["a","عَنْ اَبِيْ عُثْمَانَ عَنْ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: مَنِ ادَّعَى اِلىَ غَيْرِ اَبِيْهِ وَهُوَ يَعْلَمُ اَنَّهُ غَيْرُ اَبِيْهِ فَالْجَنَّةُ عَلَيْهِ حَرَامٌ. فَذَكَرْتُهُ لِاَبِيْ بَكْرَةَ، فَقَالَ: وَاَنَا سَمِعَتْهُ اُذُنَايَ وَوَعَاهُ قَلْبِيْ مِنْ رَسُوْلِ اللهِ ﷺ . البخارى 8: 12"],["p","Dari Abu ‘Utsman, dari Sa’ad (bin Abi Waqqash) RA, ia berkata : Aku mendengar Rasulullah SAW bersabda, “Barangsiapa bernasab (mengakui ayah) kepada yang bukan ayahnya, sedangkan dia mengetahui bahwa orang itu memang bukan ayahnya, maka surga haram baginya”. Lalu aku (Abu ‘Utsman) menanyakan hal itu kepada Abu Bakrah, maka ia menjawab, “Aku mendengar hal itu dengan dua telingaku dan hatiku meyaqininya hal itu dari Rasulullah SAW”. [HR. Bukhari juz 8, hal. 12]"],["a","عَنْ اَبِيْ هُرَيْرَةَ عَنِ النَّبِيِّ ﷺ قَالَ: لَا تَرْغَبُوْا عَنْ آبَائِكُمْ فَمَنْ رَغِبَ عَنْ اَبِيْهِ فَهُوَ كُفْرٌ. البخارى 8: 12"],["p","Dari Abu Hurairah, dari Nabi SAW, beliau bersabda, “Janganlah kalian membenci ayah-ayah kalian. Barangsiapa yang membenci ayahnya, maka ia kufur”. [HR. Bukhari juz 8, hal. 12]"],["a","عَنْ ثَوْبَانَ عَنِ النَّبِيِّ ﷺ قَالَ: ثَلَاثَةٌ لَا يَنْفَعُ مَعَهُنَّ عَمَلٌ: اَلشِّرْكُ بِاللهِ، وَعُقُوْقُ الْوَالِدَيْنِ، وَالْفِرَارُ مِنَ الزَّحْفِ. الطبرانى فى المعجم الكبير 2: 95 رقم 1420"],["p","Dari Tsauban, dari Nabi SAW, beliau bersabda, “Ada tiga perkara yang menjadikan amal seseorang tidak berguna : 1. syirik kepada Allah, 2. durhaka kepada kedua orang tua, dan 3. lari dari medan perang (sebagai pengecut)”. [HR. Thabarani di dalam Al Mu’jamul Kabir juz 2, hal. 95, no. 1420, dlo'if, karena di dalam sanadnya ada perawi bernama Yazid bin Rabi’ah]"],["a","عَنِ الْمُغِيْرَةِ بْنِ شُعْبَةَ عَنْ رَسُوْلِ اللهِ ﷺ قَالَ: اِنَّ اللهَ عَزَّ وَجَلَّ حَرَّمَ عَلَيْكُمْ عُقُوْقَ الْاُمَّهَاتِ وَوَأْدَ الْبَنَاتِ وَمَنْعًا وَهَاتِ وَكَرِهَ لَكُمْ ثَلَاثًا. قِيْلَ وَقَالَ، وَكَثْرَةَ السُّؤَالِ وَاِضَاعَةَ الْمَالِ. مسلم 3: 1341 رقم 12"],["p","Dari Mughirah bin Syu’bah, dari Rasulullah SAW, beliau bersabda, “Sesungguhnya Allah ‘Azza wa Jalla mengharamkan atas kalian durhaka kepada para ibu, mengubur hidup-hidup anak-anak perempuan, dan menahan dan meminta (menahan kewajiban dan meminta yang bukan haknya). Dan Dia benci pada kalian tiga perkara ; Katanya dan katanya, banyak bertanya (yang tidak perlu), dan menghambur-hamburkan harta”. [HR. Muslim juz 3, hal. 1341, no. 12]"],["p","(Bersambung)"]],"c20221106_1306":[["p","Ahad, 6 November 2022/11 Rabii’ul Aakhir 1444 Brosur No. : 2101/2141/IA"],["h","HAL HAL YANG MENGHAPUS AMAL (4)"],["h","10. Mendatangi dhukun"],["a","عَنْ صَفِيَّةَ عَنْ بَعْضِ اَزْوَاجِ النَّبِيّ ﷺ عَنِ النَّبِيّ ﷺ قَالَ: مَنْ اَتَى عَرَّافًا فَسَأَلَهُ عَنْ شَىْءٍ لَمْ تُقْبَلْ لَهُ صَلَاةُ اَرْبَعِيْنَ لَيْلَةً. مسلم 4: 1751 رقم 125"],["p","Dari Shafiyah dari sebagian isteri Nabi SAW dari Nabi SAW, beliau bersabda, \"Barangsiapa yang datang kepada dukun (tukang ramal), lalu menanyakan sesuatu kepadanya, maka tidak diterima shalatnya selama empat puluh malam\". [HR. Muslim juz 4, hal. 1751, no. 125]"],["a","عَنْ عَبْدِ اللهِ قَالَ: مَنْ اَتَى عَرَّافًا اَوْ كَاهِنًا فَسَأَلَهُ يُؤْمِنُ بِمَا يَقُوْلُ فَقَدْ كَفَرَ بِمَا اُنْزِلَ عَلَى مُحَمَّدٍ ﷺ. الطبرانى فى المعجم الكبير 10: 76، رقم: 10005"],["p","Dari ‘Abdullah (bin Mas'ud), ia berkata, \"Barangsiapa yang datang kepada tukang ramal, atau dukun menanyakan sesuatu kepadanya dan percaya kepada apa yang dikatakannya, maka sungguh dia telah kafir kepada apa yang diturunkan kepada Nabi Muhammad SAW\". [HR. Thabarani dalam Al Mu’jamul Kabir juz 10, hal. 76, no. 10005]"],["a","عَنْ وَائِلَةَ بْنِ الْاَسْقَعِ قَالَ سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: مَنْ اَتَى كَاهِنًا فَسَأَلَهُ عَنْ شَىْءٍ حُجِبَتْ عَنْهُ التَّوْبَةُ اَرْبَعِيْنَ لَيْلَةً، فَاِنْ صَدَّقَهُ بِمَا قَالَ كَفَرَ. الطبرانى فى المعجم الكبير 22: 69، رقم: 169"],["p","Dari Waailah bin Asqa', ia berkata : Saya mendengar Rasulullah SAW bersabda, \"Barangsiapa datang kepada dukun menanyakan sesuatu kepadanya, maka tertutup taubat darinya selama empat puluh malam, dan jika ia mempercayai perkataan dukun itu, ia kafir\". [HR. Thabarani dalam Al-Mu’jamul Kabir juz 22, hal. 69, no. 169, dlo’if karena dalam sanadnya ada perawi bernama Sulaiman bin Ahmad Al-Wasithiy, ia matruk]"],["a","عَنْ قَطَنِ بْنِ قَبِيْصَةَ عَنْ اَبِيْهِ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: اَلْعِيَافَةُ وَ الطِّيَرَةُ وَ الطَّرْقُ مِنَ الْجِبْتِ. ابو داود 4: 16، رقم: 3907"],["p","Dari Qathan bin Qabishah dari ayahnya, ia berkata : Saya mendengar Rasulullah SAW bersabda, \"Ramalan dengan tulisan, ramalan dengan burung dan ramalan dengan lemparan kerikil termasuk syirik (menyekutukan Allah)\". [HR. Abu Dawud juz 4, hal. 16, no. 3907]."],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنِ اقْتَبَسَ عِلْمًا مِنَ النُّجُوْمِ اِقْتَبَسَ شُعْبَةً مِنَ السِّحْرِ زَادَ مَا زَادَ. ابو داود 4: 16، رقم: 3905"],["p","Dari Ibnu 'Abbas, ia berkata, Rasulullah SAW bersabda, \"Barangsiapa yang mempelajari ilmu ramalan bintang berarti dia mempelajari satu cabang dari sihir, dan bertambah dosa apabila dia bertambah dalam mempelajarinya\".[HR. Abu Dawud juz 4, hal. 16, no. 3905]"],["a","عَنْ مُعَاوِيَةَ بْنِ اْلحَكَمِ السُّلَمِيّ قَالَ، قُلْتُ: يَا رَسُوْلَ اللهِ اُمُوْرًا كُنَّا نَصْنَعُهَا فِى اْلجَاهِلِيَّةِ. كُنَّا نَأْتِى اْلكُهَّانَ، قَالَ: فَلاَ تَأْتُوا اْلكُهَّانَ. قَالَ، قُلْتُ: كُنَّا نَتَطَيَّرُ. قَالَ: ذَاكَ شَىْءٌ يَجِدُهُ اَحَدُكُمْ فِى نَفْسِهِ، فَلاَ يَصُدَّنَّكُمْ. مسلم 4: 1748 رقم 121"],["p","Dari Mu'awiyah bin Hakam As-Sulamiy, ia berkata : Aku berkata, \"Ya Rasulullah, ada beberapa hal yang biasa kami lakukan pada masa jahiliyah dahulu, yaitu kami biasa datang kepada dukun\". Rasulullah SAW bersabda, \"Jangan lagi kamu datang kepada dukun\". (Mu'awiyah) berkata : Aku berkata, \"Kami juga percaya pada tanda-tanda kesialan\". Rasulullah SAW bersabda, \"Itu sesuatu yang seseorang diantara kalian tidak suka terjadi pada dirinya, maka hal itu jangan sampai menghalangi (mengganggu) kamu sekalian\". [HR. Muslim juz 4, hal. 1748, no. 121]"],["a","عَنْ اَبيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : مَنْ عَقَدَ عُقْدَةً ثُمَّ نَفَثَ فِيْهَا فَقَدْ سَحَرَ، وَ مَنْ سَحَرَ فَقَدْ اَشْرَكَ، وَ مَنْ تَعَلَّقَ شَيئًا وُكِلَ اِلَيْهِ. النسائى 7: 112"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Barangsiapa yang membuat ikatan buhul kemudian meniupnya, maka sungguh ia telah berbuat sihir. Dan barangsiapa berbuat sihir, sungguh ia telah mensekutukan Allah. Dan barangsiapa yang menggantungkan jimat, maka ia diserahkan kepada jimat itu (Allah tidak akan menolongnya). [HR. Nasaai juz 7, hal. 112]"],["a","عَنْ عَبْدِ اللهِ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: اِنَّ الرُّقَى وَ التَّمَائِمَ وَ التِّوَلَةَ شِرْكٌ. ابو داود 4: 9، رقم: 3883"],["p","Dari Abdullah ia berkata, \"Aku pernah mendengar Rasulullah SAW bersabda, \"Sesungguhnya mantra-mantra, jimat-jimat dan tiwalah adalah termasuk syirik”. [HR. Abu Dawud juz 4, hal. 9, no. 3883, dlo’if karena dalam sanadnya ada perawi yang tidak disebutkan namanya]"],["h","11. Mendustakan taqdir"],["a","عَنْ يَحْيَى بْنِ يَعْمَرَ قَالَ: كَانَ اَوَّلَ مَنْ قَالَ فِي الْقَدَرِ بِالْبَصْرَةِ مَعْبَدٌ اَلْجُهَنِيُّ. فَانْطَلَقْتُ اَنَا وَحُمَيْدُ بْنُ عَبْدِ الرَّحْمٰنِ الْحِمْيَرِيُّ حَاجَّيْنِ اَوْ مُعْتَمِرَيْنِ. فَقُلْنَا: لَوْ لَقِيْنَا اَحَدًا مِنْ اَصْحَابِ رَسُوْلِ اللهِ ﷺ فَسَأَلْنَاهُ عَمَّا يَقُوْلُ هٰؤُلَاءِ فِي الْقَدَرِ. فَوُفِّقَ لَنَا عَبْدُ اللهِ بْنُ عُمَرَ بْنِ الْخَطَّابِ دَاخِلًا اَلْمَسْجِدَ، فَاكْتَنَفْتُهُ اَنَا وَصَاحِبِيْ اَحَدُنَا عَنْ يَـمِيْنِهِ وَالْآخَرُ عَنْ شِمَالِهِ. فَظَنَنْتُ اَنَّ صَاحِبِيْ سَيَكِلُ الْكَلَامَ اِلَيَّ، فَقُلْتُ: اَبَا عَبْدِ الرَّحْمٰنِ، اِنَّهُ قَدْ ظَهَرَ قِبَلَنَا نَاسٌ يَقْرَءُوْنَ الْقُرْاٰنَ وَيَتَقَفَّرُوْنَ الْعِلْمَ، وَذَكَرَ مِنْ شَأْنِـهِمْ، وَاَنَّـهُمْ يَزْعُمُوْنَ اَنْ لَا قَدَرَ، وَاَنَّ الْاَمْرَ اُنُفٌ. قَالَ: فَاِذَا لَقِيْتَ اُولٰئِكَ فَاَخْبِرْهُمْ اَنِّيْ بَرِيْءٌ مِنْهُمْ وَاَنَّـهُمْ بُرَاٰءُ مِنِّيْ. وَالَّذِيْ يَحْلِفُ بِهِ عَبْدُ اللهِ بْنُ عُمَرَ، لَوْ اَنَّ لِاَحَدِهِمْ مِثْلَ اُحُدٍ ذَهَبًا فَاَنْفَقَهُ مَا قَبِلَ اللهُ مِنْهُ حَتَّى يُؤْمِنَ بِالْقَدَرِ. ثُـمَّ قَالَ: حَدَّثَنِيْ اَبِيْ عُمَرُ بْنُ الْخَطَّابِ، قَالَ: بَيْنَمَا نَحْنُ عِنْدَ رَسُوْلِ اللهِ ﷺ ذَاتَ يَوْمٍ اِذْ طَلَعَ عَلَيْنَا رَجُلٌ شَدِيْدُ بَيَاضِ الثِّيَابِ، شَدِيْدُ سَوَادِ الشَّعَرِ، لَا يُرَى عَلَيْهِ اَثَرُ السَّفَرِ، وَلَا يَعْرِفُهُ مِنَّا اَحَدٌ، حَتَّى جَلَسَ اِلَى النَّبِيِّ ﷺ، فَاَسْنَدَ رُكْبَتَيْهِ اِلَى رُكْبَتَيْهِ، وَوَضَعَ كَفَّيْهِ عَلَى فَخِذَيْهِ، وَقَالَ: يَا مُحَمَّدُ، اَخْبِرْنِيْ عَنِ الْاِسْلَامِ. فَقَالَ رَسُوْلُ اللهِ ﷺ : اَلْاِسْلَامُ اَنْ تَشْهَدَ اَنْ لَا اِلٰهَ اِلَّا اللهُ وَاَنَّ مُحَمَّدًا رَسُوْلُ اللهِ ﷺ، وَتُقِيْمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُوْمَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ اِنِ اسْتَطَعْتَ اِلَيْهِ سَبِيْلًا. قَالَ: صَدَقْتَ. قَالَ: فَعَجِبْنَا لَهُ يَسْأَلُهُ وَيُصَدِّقُهُ. قَالَ: فَاَخْبِرْنِيْ عَنِ الْاِيْـمَانِ. قَالَ: اَنْ تُؤْمِنَ بِاللهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الْآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ. قَالَ: صَدَقْتَ. قَالَ: فَاَخْبِرْنِيْ عَنِ الْاِحْسَانِ. قَالَ: اَنْ تَعْبُدَ اللهَ كَاَنَّكَ تَرَاهُ، فَاِنْ لَـمْ تَكُنْ تَرَاهُ فَاِنَّهُ يَرَاكَ. قَالَ: فَاَخْبِرْنِيْ عَنِ السَّاعَةِ. قَالَ: مَا الْمَسْئُوْلُ عَنْهَا بِاَعْلَمَ مِنَ السَّائِلِ. قَالَ: فَاَخْبِرْنِيْ عَنْ اَمَارَتِـهَا. قَالَ: اَنْ تَلِدَ الْأَمَةُ رَبَّتَهَا، وَاَنْ تَرَى الْحُفَاةَ الْعُرَاةَ الْعَالَةَ رِعَاءَ الشَّاءِ يَتَطَاوَلُوْنَ فِي الْبُنْيَانِ. قَالَ: ثُـمَّ انْطَلَقَ. فَلَبِثْتُ مَلِيًّا. ثُـمَّ قَالَ لِيْ: يَا عُمَرُ، اَتَدْرِيْ مَنِ السَّائِلُ؟ قُلْتُ: اَللهُ وَرَسُوْلُهُ اَعْلَمُ. قَالَ: فَاِنَّهُ جِبْرِيْلُ اَتَاكُمْ يُعَلِّمُكُمْ دِيْنَكُمْ. مسلم 1: 36 رقم 1"],["p","Dari Yahya bin Ya'mar dia berkata, \"Orang yang pertama kali tidak percaya taqdir di Bashrah adalah Ma'bad Al-Juhaniy. Kemudian ketika aku dan Humaid bin ‘Abdurrahman Al-Himyari pergi hajji atau 'umrah, kami berkata, \"Seandainya kami bertemu dengan salah seorang shahabat Rasulullah SAW, maka kami akan bertanya kepadanya tentang sesuatu yang mereka katakan berkaitan dengan taqdir\". Lalu 'Abdullah bin 'Umar bin Al-Khaththab dipertemukan (oleh Allah) untuk kami ketika dia masuk masjid. Lalu aku dan temanku mendekatinya. Salah seorang dari kami di sebelah kanannya dan yang lain di sebelah kirinya. Aku yaqin bahwa temanku akan mewakilkan pembicaraan kepadaku, maka aku berkata, \"Wahai Abu 'Abdirrahman, sesungguhnya di daerah kami ada orang-orang yang membaca Al-Qur'an dan mencari ilmu, (Yahya bin Ya'mar menceritakan keadaan mereka), tetapi mereka menganggap bahwa taqdir itu tidak ada, dan yang terjadi adalah sesuatu yang baru (tidak didahului oleh taqdir dan ilmu Allah)\". Maka 'Abdullah bin 'Umar menjawab, \"Apabila kamu bertemu dengan orang-orang itu, beritahukanlah kepada mereka bahwa aku berlepas diri dari mereka, dan bahwa mereka berlepas diri dariku. Dan demi Tuhan yang Abdullah bin 'Umar bersumpah dengan-Nya, seandainya salah seorang dari mereka menafqahkan emas sebesar gunung Uhud, niscaya sedeqahnya itu tidak akan diterima oleh Allah sehingga ia beriman kepada taqdir\". Kemudian Ibnu 'Umar berkata : Telah menceritakan kepadaku ayahku, yaitu 'Umar bin Khaththab, ia berkata, \"Dahulu pada suatu hari ketika kami berada di sisi Rasulullah SAW, tiba-tiba datanglah seorang laki-laki yang memakai baju sangat putih, rambutnya sangat hitam, tidak tampak padanya bekas-bekas perjalanan, dan tidak ada seorang pun diantara kami yang mengenalnya, ia datang kepada Nabi SAW lalu menyandarkan dua lututnya pada dua lutut Nabi SAW, dan meletakkan kedua tapak tangannya pada kedua paha Nabi SAW, orang laki-laki itu berkata, \"Ya Muhammad, beritahukanlah kepadaku tentang Islam ?\". Rasulullah SAW menjawab, \"Islam ialah kamu bersaksi bahwa tidak ada Tuhan selain Allah dan bahwa Muhammad adalah utusan Allah, mendirikan shalat, menunaikan zakat, berpuasa Ramadlan, dan berhajji ke Baitullah jika kamu mampu melaksanakannya\". Orang laki-laki itu berkata, \"Kamu benar\". ('Umar bin Khaththab) berkata, \"Maka kami heran terhadapnya, dia menanyakannya dan membenarkannya\". Orang laki-laki itu bertanya lagi, \"Beritahukanlah kepadaku tentang iman?\". Beliau menjawab, \"Iman ialah kamu beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, para Rasul-Nya, beriman kepada hari akhir, dan taqdir baik dan buruk\". Orang laki-laki itu berkata, \"Kamu benar\". Orang laki-laki itu bertanya lagi, \"Beritahukanlah kepadaku tentang ihsan ?\". Beliau menjawab, \"Ihsan ialah kamu menyembah Allah seakan-akan kamu melihat-Nya, jika kamu tidak melihat-Nya, maka sesungguhnya Dia melihatmu\". Orang laki-laki itu bertanya lagi, \"Beritahukanlah kepadaku kapan terjadinya hari qiyamat ?\". Beliau menjawab, \"Orang yang ditanya tidak lebih mengetahui daripada orang yang bertanya\". Orang laki-laki itu bertanya lagi, \"Beritahukanlah kepadaku tentang tanda-tandanya ?\". Beliau menjawab, \"Apabila budak perempuan melahirkan tuannya, (itu diantara tanda-tandanya). Dan kamu melihat orang yang dahulunya tidak beralas kaki, telanjang, miskin, penggembala kambing, mereka bermegah-megah dalam mendirikan bangunan, (itu diantara tanda-tandanya)\". Kemudian orang laki-laki itu pergi. Maka aku tetap saja heran. Kemudian Rasulullah SAW bertanya kepadaku, \"Hai 'Umar, tahukah kamu siapa orang yang bertanya tadi ?\". Aku menjawab, \"Allah dan Rasul-Nya yang lebih mengetahui\". Beliau bersabda, \"Dia adalah Jibril, dia datang kepada kalian untuk mengajarkan agama kalian\". [HR. Muslim juz 1, hal. 36, no. 1]"],["h","12. Berbuat dhalim kepada orang lain"],["p","Allah SWT berfirman :"],["a","قُلْ اِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالْاِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَاَنْ تُشْرِكُوْا بِاللّٰهِ مَا لَمْ يُنَزِّلْ بِهٖ سُلْطٰنًا وَّاَنْ تَقُوْلُوْا عَلَى اللّٰهِ مَا لَا تَعْلَمُوْنَ. الاعراف: 33"],["p","Katakanlah, \"Tuhanku hanya mengharamkan perbuatan yang keji, baik yang nampak atau pun yang tersembunyi, dan perbuatan dosa, melanggar hak manusia tanpa alasan yang benar, (mengharamkan) mempersekutukan Allah dengan sesuatu yang Allah tidak menurunkan hujjah untuk itu dan (mengharamkan) mengada-adakan terhadap Allah apa yang tidak kamu ketahui\". [QS. Al-A'raaf : 33]"],["a","اِنَّ اللّٰهَ يَأْمُرُ بِالْعَدْلِ وَالْاِحْسَانِ وَاِيْتَاۤئِ ذِى الْقُرْبٰى وَيَنْهٰى عَنِ الْفَحْشَاۤءِ وَالْمُنْكَرِ وَالْبَغْيِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُوْنَ. النحل: 90"],["p","Sesungguhnya Allah menyuruh (kamu) berlaku adil dan berbuat kebajikan, memberi kepada kaum kerabat, dan Allah melarang dari perbuatan keji, kemungkaran dan permusuhan. Dia memberi pengajaran kepadamu agar kamu dapat mengambil pelajaran. [QS. An-Nahl : 90]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اَلْمُسْلِمُ اَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَخْذُلُهُ، وَلَا يَحْقِرُهُ، اَلتَّقْوَى هٰهُنَا. وَيُشِيْرُ اِلَى صَدْرِهِ ثَلَاثَ مَرَّاتٍ، بِحَسْبِ امْرِئٍ مِنَ الشَّرِّ اَنْ يَحْقِرَ اَخَاهُ الْمُسْلِمَ. كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ دَمُهُ وَعِرْضُهُ وَمَالُهُ. مسلم 4: 1986 رقم 32"],["p","Dari Abu Hurairah RA, bahwasanya Rasulullah SAW bersabda, “Orang Islam itu saudaranya orang Islam yang lain, tidak boleh berlaku dhalim kepadanya, tidak boleh membiarkannya (dengan tidak mau menolongnya), dan tidak boleh menghinakannya. Taqwa itu di sini”, sambil menunjuk dada beliau tiga kali. “Cukuplah seseorang itu berbuat jahat apabila ia merendahkan saudaranya orang Islam yang lain. Tiap-tiap orang Islam terhadap orang Islam yang lain adalah haram darahnya, kehormatannya dan harta bendanya”. [HR. Muslim juz 4, hal. 1986, no. 32]"],["a","عَنْ اَبِيْ ذَرٍّ عَنِ النَّبِيِّ ﷺ فِيْمَا رَوَى عَنِ اللهِ تَبَارَكَ وَتَعَالَى اَنَّهُ قَالَ: يَا عِبَادِيْ اِنِّيْ حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِيْ، وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا فَلَا تَظَالَمُوْا. يَا عِبَادِيْ كُلُّكُمْ ضَالٌّ اِلَّا مَنْ هَدَيْتُهُ فَاسْتَهْدُوْنِيْ اَهْدِكُمْ. يَا عِبَادِيْ كُلُّكُمْ جَائِعٌ اِلَّا مَنْ اَطْعَمْتُهُ فَاسْتَطْعِمُوْنِيْ اُطْعِمْكُمْ. يَا عِبَادِيْ كُلُّكُمْ عَارٍ اِلَّا مَنْ كَسَوْتُهُ فَاسْتَكْسُوْنِيْ اَكْسُكُمْ. يَا عِبَادِيْ اِنَّكُمْ تُخْطِئُوْنَ بِاللَّيْلِ وَالنَّهَارِ وَاَنَا اَغْفِرُ الذُّنُوْبَ جَمِيْعًا، فَاسْتَغْفِرُوْنِيْ اَغْفِرْ لَكُمْ. مسلم 4: 1994 رقم 55"],["p","Dari Abu Dzarr dari Nabi SAW dalam apa yang beliau riwayatkan dari Allah Tabaaraka wa Ta'aalaa, Allah berfirman, \"Wahai hamba-hamba-Ku, sesungguhnya Aku mengharamkan kedhaliman atas diri-Ku dan Aku menjadikannya haram pula diantara kalian, maka janganlah kalian saling berbuat dhalim. Wahai hamba-hamba-Ku, kalian semua adalah sesat kecuali orang yang Aku beri petunjuk, maka mohonlah petunjuk kepada-Ku, niscaya kalian Aku beri petunjuk. Wahai hamba-hamba-Ku, kalian semua adalah lapar, kecuali orang yang Aku beri makan, maka mohonlah makan kepada-Ku, niscaya kalian Aku beri makan. Wahai hamba-hamba-Ku, kalian semua adalah telanjang, kecuali orang yang Aku beri pakaian, maka mohonlah pakaian kepada-Ku, niscaya kalian Aku beri pakaian. Wahai hamba-hamba-Ku, sesungguhnya kalian semua berbuat dosa di malam dan siang hari, dan Aku mengampuni semua dosa, maka mohonlah ampun kepada-Ku, niscaya kalian Aku beri ampun. [HR. Muslim juz 4, hal. 1994, no. 55]"],["a","عَنْ جَابِرٍ بْنِ عَبْدِ اللهِ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اِتَّقُوا الظُّلْمَ فَاِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ، وَاتَّقُوا الشُّحَّ فَاِنَّ الشُّحَّ اَهْلَكَ مَنْ كَانَ قَبْلَكُمْ، حَمَلَهُمْ عَلَى اَنْ سَفَكُوْا دِمَاءَهُمْ، وَاسْتَحَلُّوْا مَحَارِمَهُمْ. مسلم 4: 1996 رقم 56"],["p","Dari Jabir bin 'Abdullah bahwasanya Rasulullah SAW bersabda, \"Jauhkanlah kalian dari berbuat dhalim, karena sesungguhnya perbuatan dhalim itu (menyebabkan) kegelapan pada hari qiyamat, dan jauhkanlah kalian dari sifat kikir, karena sesungguhnya kikir itulah yang membinasakan orang-orang sebelum kalian, mendorong mereka menumpahkan darah dan menghalalkan yang haram\". [HR. Muslim juz 4, hal 1996, no. 56]"],["a","عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اَتَدْرُوْنَ مَا الْمُفْلِسُ؟ قَالُوْا: اَلْمُفْلِسُ فِيْنَا مَنْ لَا دِرْهَمَ لَهُ وَلَا مَتَاعَ. فَقَالَ: اِنَّ الْمُفْلِسَ مِنْ اُمَّتِيْ مَنْ يَأْتِى يَوْمَ الْقِيَامَةِ بِصَلَاةٍ وَصِيَامٍ وَزَكَاةٍ وَيَأْتِى وَقَدْ شَتَمَ هٰذَا وَقَذَفَ هٰذَا وَاَكَلَ مَالَ هٰذَا وَسَفَكَ دَمَ هٰذَا وَضَرَبَ هٰذَا ، فَيُعْطَى هٰذَا مِنْ حَسَنَاتِهِ وَ هٰذَا مِنْ حَسَنَاتِهِ، فَاِنْ فَنِيَتْ حَسَنَاتُهُ قَبْلَ اَنْ يُقْضَى مَا عَلَيْهِ اُخِذَ مِنْ خَطَايَاهُمْ فَطُرِحَتْ عَلَيْهِ ثُمَّ طُرِحَ فِى النَّارِ. مسلم 4: 1997 رقم 59"],["p","Dari Abu Hurairah RA ia berkata : Rasulullah SAW bersabda, “Tahukah kamu siapakah orang yang disebut pailit itu ?”. Jawab shahabat, “Orang yang disebut pailit diantara kami ialah orang yang tidak punya dirham dan tidak punya barang-barang”. Rasulullah SAW bersabda, “Sesungguhnya orang yang disebut pailit dari ummatku ialah orang yang datang pada hari qiyamat lengkap dengan membawa (pahala) shalatnya, puasanya dan zakatnya. Tetapi di samping itu ia telah mencaci ini dan menuduh ini, memakan hartanya ini dan menumpahkan darahnya ini dan memukul ini, maka diberikan kepada orang yang dianiaya itu dari (pahala) kebaikan amalnya, dan kepada orang yang lainnya lagi (dari pahala) kebaikan amalnya. Maka apabila telah habis (pahala) kebaikannya itu dan belum terbayar semua tuntutan orang-orang yang pernah dianiaya itu, maka diambilkan dari dosa-dosa orang yang telah dianiaya itu dan ditanggungkan kepadanya, lalu ia dilemparkan ke neraka”. [HR. Muslim juz 4, hal. 1997, no.59]"],["a","عَنْ اُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُوْلُ اللهِ ﷺ : اِنَّكُمْ تَخْتَصِمُوْنَ اِلَيَّ وَلَعَلَّ بَعْضَكُمْ اَنْ يَكُوْنَ اَلْحَنَ بِحُجَّتِهِ مِنْ بَعْضٍ فَاَقْضِى لَهُ عَلَى نَحْوٍ مِمَّا اَسْمَعُ مِنْهُ. فَمَنْ قَطَعْتُ لَهُ مِنْ حَقِّ اَخِيْهِ شَيْئًا فَلَا يَأْخُذْهُ فَاِنَّمَا اَقْطَعُ لَهُ بِهِ قِطْعَةً مِنَ النَّارِ. مسلم 3: 1337 رقم 4"],["p","Dari Ummu Salamah RA, ia berkata : Rasulullah SAW bersabda, “Sesungguhnya kalian mengadukan perselisihan kepadaku, barangkali sebagian kalian lebih pintar berhujjah (beralasan) dari pada sebagian yang lain, kemudian aku memberikan keputusan kepadanya berdasarkan apa yang aku dengar darinya. Maka barangsiapa yang aku beri sepotong dari haq saudaranya, maka janganlah ia mengambilnya, karena berarti aku memberinya sepotong api neraka”. [HR. Muslim juz 3, hal 1337, no. 4]"],["a","عَنْ سَعِيْدِ بْنِ زَيْدٍ قَالَ: سَمِعْتُ النَّبِىَّ ﷺ يَقُوْلُ: مَنْ اَخَذَ شِبْرًا مِنَ الْاَرْضِ ظُلْمًا فَاِنَّهُ يُطَوَّقُهُ يَوْمَ الْقِيَامَةِ مِنْ سَبْعِ اَرَضِيْنَ. مسلم 3 : 1231 رقم 140"],["p","Dari Sa'id bin Zaid, ia berkata : Saya mendengar Nabi SAW bersabda, \"Barangsiapa yang mengambil (menyerobot) sejengkal tanah secara dhalim, maka pada hari qiyamat akan dikalungkan tujuh bumi kepadanya\". [HR. Muslim juz 3, hal. 1231, no. 140]"],["p","--oo0oo—"]],"c20221120_1307":[["p","Ahad, 20 November 2022/ 25 Rabii’ul Aakhir 1444 Brosur No. : 2102/2142/IA"],["h","TASYABBUH (1)"],["p","Pengertian Tasyabbuh"],["p","Tasyabbuh berasal dari bahasa Arab:"],["a","تَشَبَّهَ – يَتَشَبَّهُ - تَشَبُّهًا"],["p","berarti menyerupai atau meniru terhadap sesuatu."],["p","Secara isthilah, tasyabbuh adalah sebuah usaha seseorang untuk meniru sosok yang dikaguminya, baik dari tingkah laku, penampilan, hingga sifat-sifatnya dan diaplikasikan dalam kehidupan sehari-hari."],["p","Allah melarang kita kaum muslimin dalam cara beragama seperti orang orang yang telah diturunkan kitab kepada mereka (Yahudi dan Nashrani). Allah SWT berfirman :"],["a","اَلَمْ يَأْنِ لِلَّذِيْنَ اٰمَنُوْٓا اَنْ تَخْشَعَ قُلُوْبُهُمْ لِذِكْرِ اللّٰهِ وَمَا نَزَلَ مِنَ الْحَقِّۙ وَلَا يَكُوْنُوْا كَالَّذِيْنَ اُوْتُوا الْكِتٰبَ مِنْ قَبْلُ فَطَالَ عَلَيْهِمُ الْاَمَدُ فَقَسَتْ قُلُوْبُهُمْۗ وَكَثِيْرٌ مِّنْهُمْ فٰسِقُوْنَ. الحديد : 16"],["p","Belumkah datang waktunya bagi orang-orang yang beriman, untuk tunduk hati mereka mengingat Allah dan kepada kebenaran yang telah turun (kepada mereka), dan janganlah mereka seperti orang-orang yang sebelumnya telah diturunkan Al Kitab kepadanya, kemudian berlalulah masa yang panjang atas mereka lalu hati mereka menjadi keras. Dan kebanyakan di antara mereka adalah orang-orang yang fasiq. [QS. Al Hadiid : 16]"],["p","Diantara kerusakan cara beragama orang-orang Yahudi dan Nashrani tersebut adalah :"],["p","1) Mereka menjadikan orang-orang alimnya, rahib-rahibnya, para pemimpinnya sebagai tuhan-tuhan selain Allah, mereka lebih mentha’ati para pemimpinnya daripada Allah dan Rasul-Nya."],["p","Allah SWT berfirman :"],["a","وَقَالَتِ الْيَهُوْدُ عُزَيْرُنِابْنُ اللّٰهِ وَقَالَتِ النَّصٰرَى الْمَسِيْحُ ابْنُ اللّٰهِ ۗ ذٰلِكَ قَوْلُهُمْ بِاَفْوَاهِهِمْۚ يُضَاهِـُٔوْنَ قَوْلَ الَّذِيْنَ كَفَرُوْا مِنْ قَبْلُ ۗ قَاتَلَهُمُ اللّٰهُ ۚ اَنّٰى يُؤْفَكُوْنَ (30) اِتَّخَذُوْٓا اَحْبَارَهُمْ وَرُهْبَانَهُمْ اَرْبَابًا مِّنْ دُوْنِ اللّٰهِ وَالْمَسِيْحَ ابْنَ مَرْيَمَۚ وَمَآ اُمِرُوْٓا اِلَّا لِيَعْبُدُوْٓا اِلٰهًا وَّاحِدًاۚ لَآ اِلٰهَ اِلَّا هُوَۗ سُبْحٰنَهٗ عَمَّا يُشْرِكُوْنَ (31) التوبة : 30-31"],["p","Orang-orang Yahudi berkata: \"Uzair itu putra Allah\" dan orang Nashrani berkata: \"Al Masih itu putra Allah\". Demikian itulah ucapan mereka dengan mulut mereka, mereka meniru perkataan orang-orang kafir yang terdahulu. Dila’nati Allah-lah mereka; bagaimana mereka sampai berpaling? (30)"],["p","Mereka menjadikan orang-orang alimnya, dan rahib-rahib mereka sebagai tuhan selain Allah, dan (juga mereka mempertuhankan) Al Masih putra Maryam; padahal mereka hanya disuruh menyembah Tuhan Yang Maha Esa; tidak ada Tuhan (yang berhak disembah) selain Dia. Maha Suci Allah dari apa yang mereka persekutukan. (31) [QS. At-Taubah 30-31]"],["a","لَقَدْ كَفَرَ الَّذِيْنَ قَالُوْٓا اِنَّ اللّٰهَ هُوَ الْمَسِيْحُ ابْنُ مَرْيَمَ ۗ وَقَالَ الْمَسِيْحُ يٰبَنِيْٓ اِسْرَاۤءِيْلَ اعْبُدُوا اللّٰهَ رَبِّيْ وَرَبَّكُمْ ۗ اِنَّهٗ مَنْ يُّشْرِكْ بِاللّٰهِ فَقَدْ حَرَّمَ اللّٰهُ عَلَيْهِ الْجَنَّةَ وَمَأْوٰىهُ النَّارُ ۗ وَمَا لِلظّٰلِمِيْنَ مِنْ اَنْصَارٍ(72) لَقَدْ كَفَرَ الَّذِيْنَ قَالُوْٓا اِنَّ اللّٰهَ ثَالِثُ ثَلٰثَةٍ ۘ وَمَا مِنْ اِلٰهٍ اِلَّآ اِلٰهٌ وَّاحِدٌ ۗ وَاِنْ لَّمْ يَنْتَهُوْا عَمَّا يَقُوْلُوْنَ لَيَمَسَّنَّ الَّذِيْنَ كَفَرُوْا مِنْهُمْ عَذَابٌ اَلِيْمٌ(73) اَفَلَا يَتُوْبُوْنَ اِلَى اللّٰهِ وَيَسْتَغْفِرُوْنَهٗۗ وَاللّٰهُ غَفُوْرٌ رَّحِيْمٌ(74) مَا الْمَسِيْحُ ابْنُ مَرْيَمَ اِلَّا رَسُوْلٌۚ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُۗ وَاُمُّهٗ صِدِّيْقَةٌ ۗ كَانَا يَأْكُلٰنِ الطَّعَامَ ۗ اُنْظُرْ كَيْفَ نُبَيِّنُ لَهُمُ الْاٰيٰتِ ثُمَّ انْظُرْ اَنّٰى يُؤْفَكُوْنَ (75) المائدة : 72-75"],["p","Sesungguhnya telah kafirlah orang-orang yang berkata: \"Sesungguhnya Allah adalah Al Masih putra Maryam\", padahal Al Masih (sendiri) berkata: \"Hai Bani Israel, sembahlah Allah Tuhanku dan Tuhanmu\" Sesungguhnya orang yang mempersekutukan (sesuatu dengan) Allah, maka pasti Allah mengharamkan kepadanya surga, dan tempatnya ialah neraka, tidaklah ada bagi orang-orang dhalim itu seorang penolong pun. (72)"],["p","Sesungguhnya kafirlah orang-orang yang mengatakan: \"Bahwasanya Allah salah satu dari yang tiga\", padahal sekali-kali tidak ada Tuhan (yang berhak disembah) selain Tuhan Yang Esa. Jika mereka tidak berhenti dari apa yang mereka katakan itu, pasti orang-orang yang kafir di antara mereka akan ditimpa siksaan yang pedih. (73)"],["p","Maka mengapa mereka tidak bertaubat kepada Allah dan memohon ampun kepada-Nya? Dan Allah Maha Pengampun lagi Maha Penyayang. (74)"],["p","Al Masih putra Maryam hanyalah seorang Rasul yang sesungguhnya telah berlalu sebelumnya beberapa rasul, dan ibunya seorang yang sangat benar, kedua-duanya biasa memakan makanan. Perhatikan bagaimana Kami menjelaskan kepada mereka (ahli Kitab) tanda-tanda kekuasaan (Kami), kemudian perhatikanlah bagaimana mereka berpaling (dari memperhatikan ayat-ayat Kami itu). (75) [QS. Al Maaidah : 72-75]"],["p","2) Para pemimpinnya suka merubah ayat-ayat Allah, sedangkan orang awamnya bertaqlid kepada para pemimpinnya."],["p","Allah SWT berfirman :"],["a","وَمِنْهُمْ اُمِّيُّوْنَ لَا يَعْلَمُوْنَ الْكِتٰبَ اِلَّآ اَمَانِيَّ وَاِنْ هُمْ اِلَّا يَظُنُّوْنَ (78) فَوَيْلٌ لِّلَّذِيْنَ يَكْتُبُوْنَ الْكِتٰبَ بِاَيْدِيْهِمْ ثُمَّ يَقُوْلُوْنَ هٰذَا مِنْ عِنْدِ اللّٰهِ لِيَشْتَرُوْا بِهٖ ثَمَنًا قَلِيْلًا ۗ فَوَيْلٌ لَّهُمْ مِّمَّا كَتَبَتْ اَيْدِيْهِمْ وَوَيْلٌ لَّهُمْ مِّمَّا يَكْسِبُوْنَ (79) البقرة : 78-79"],["p","Dan di antara mereka ada yang buta huruf, tidak mengetahui Al Kitab (Taurat), kecuali dongengan bohong belaka dan mereka hanya menduga-duga. (78)"],["p","Maka kecelakaan yang besarlah bagi orang-orang yang menulis Al Kitab dengan tangan mereka sendiri, lalu dikatakannya: \"Ini dari Allah\", (dengan maksud) untuk memperoleh keuntungan yang sedikit dengan perbuatan itu. Maka kecelakaan besarlah bagi mereka, akibat dari apa yang ditulis oleh tangan mereka sendiri, dan kecelakaan besarlah bagi mereka, akibat dari apa yang mereka kerjakan. (79) [QS. Al Baqarah : 78-79]"],["a","يٰٓاَيُّهَا الرَّسُوْلُ لَا يَحْزُنْكَ الَّذِيْنَ يُسَارِعُوْنَ فِى الْكُفْرِ مِنَ الَّذِيْنَ قَالُوْٓا اٰمَنَّا بِاَفْوَاهِهِمْ وَلَمْ تُؤْمِنْ قُلُوْبُهُمْ ۛ وَمِنَ الَّذِيْنَ هَادُوْا ۛ سَمّٰعُوْنَ لِلْكَذِبِ سَمّٰعُوْنَ لِقَوْمٍ اٰخَرِيْنَۙ لَمْ يَأْتُوْكَ ۗ يُحَرِّفُوْنَ الْكَلِمَ مِنْۢ بَعْدِ مَوَاضِعِهٖۚ يَقُوْلُوْنَ اِنْ اُوْتِيْتُمْ هٰذَا فَخُذُوْهُ وَاِنْ لَّمْ تُؤْتَوْهُ فَاحْذَرُوْا ۗ وَمَنْ يُّرِدِ اللّٰهُ فِتْنَتَهٗ فَلَنْ تَمْلِكَ لَهٗ مِنَ اللّٰهِ شَيْـًٔا ۗ اُولٰۤىِٕكَ الَّذِيْنَ لَمْ يُرِدِ اللّٰهُ اَنْ يُّطَهِّرَ قُلُوْبَهُمْ ۗ لَهُمْ فِى الدُّنْيَا خِزْيٌ ۖ وَّلَهُمْ فِى الْاٰخِرَةِ عَذَابٌ عَظِيْمٌ . المائدة : 41"],["p","Hai Rasul, janganlah hendaknya kamu disedihkan oleh orang-orang yang bersegera (memperlihatkan) kekafirannya, yaitu di antara orang-orang yang mengatakan dengan mulut mereka: \"Kami telah beriman\", padahal hati mereka belum beriman; dan (juga) di antara orang-orang Yahudi. (Orang-orang Yahudi itu) amat suka mendengar (berita-berita) bohong dan amat suka mendengar perkataan-perkataan orang lain yang belum pernah datang kepadamu; mereka mengubah perkataan-perkataan (Taurat) dari tempat-tempatnya. Mereka mengatakan: \"Jika diberikan ini (yang sudah diubah-ubah oleh mereka) kepada kamu, maka terimalah, dan jika kamu diberi yang bukan ini, maka hati-hatilah.\" Barangsiapa yang Allah menghendaki kesesatannya, maka sekali-kali kamu tidak akan mampu menolak sesuatu pun (yang datang) daripada Allah. Mereka itu adalah orang-orang yang Allah tidak hendak menyucikan hati mereka. Mereka beroleh kehinaan di dunia dan di akhirat mereka beroleh siksaan yang besar. [QS. Al Maaidah : 41]"],["a","اَفَتَطْمَعُوْنَ اَنْ يُّؤْمِنُوْا لَكُمْ وَقَدْ كَانَ فَرِيْقٌ مِّنْهُمْ يَسْمَعُوْنَ كَلَامَ اللّٰهِ ثُمَّ يُحَرِّفُوْنَهٗ مِنْۢ بَعْدِ مَا عَقَلُوْهُ وَهُمْ يَعْلَمُوْنَ. البقرة : 75"],["p","Apakah kamu masih mengharapkan mereka akan percaya kepadamu, padahal segolongan dari mereka mendengar firman Allah, lalu mereka mengubahnya setelah mereka memahaminya, sedang mereka mengetahui?[QS. Al Baqarah : 75]"],["a","يٰٓاَهْلَ الْكِتٰبِ قَدْ جَاۤءَكُمْ رَسُوْلُنَا يُبَيِّنُ لَكُمْ كَثِيْرًا مِّمَّا كُنْتُمْ تُخْفُوْنَ مِنَ الْكِتٰبِ وَيَعْفُوْا عَنْ كَثِيْرٍۗ قَدْ جَاۤءَكُمْ مِّنَ اللّٰهِ نُوْرٌ وَّكِتٰبٌ مُّبِيْنٌ. المائدة : 15"],["p","Hai Ahli Kitab, sesungguhnya telah datang kepadamu Rasul Kami, menjelaskan kepadamu banyak dari isi Al Kitab yang kamu sembunyikan, dan banyak (pula yang) dibiarkannya. Sesungguhnya telah datang kepadamu cahaya dari Allah, dan kitab yang menerangkan.[QS. Al Maaidah : 15]"],["p","3) Mereka tidak berhukum dengan hukum Allah."],["p","Allah SWT berfirman :"],["a","اِنَّآ اَنْزَلْنَا التَّوْرٰىةَ فِيْهَا هُدًى وَّنُوْرٌۚ يَحْكُمُ بِهَا النَّبِيُّوْنَ الَّذِيْنَ اَسْلَمُوْا لِلَّذِيْنَ هَادُوْا وَالرَّبَّانِيُّوْنَ وَالْاَحْبَارُ بِمَا اسْتُحْفِظُوْا مِنْ كِتٰبِ اللّٰهِ وَكَانُوْا عَلَيْهِ شُهَدَاۤءَۚ فَلَا تَخْشَوُا النَّاسَ وَاخْشَوْنِ وَلَا تَشْتَرُوْا بِاٰيٰتِيْ ثَمَنًا قَلِيْلًا ۗ وَمَنْ لَّمْ يَحْكُمْ بِمَآ اَنْزَلَ اللّٰهُ فَاُولٰۤىِٕكَ هُمُ الْكٰفِرُوْنَ (44) وَكَتَبْنَا عَلَيْهِمْ فِيْهَآ اَنَّ النَّفْسَ بِالنَّفْسِ وَالْعَيْنَ بِالْعَيْنِ وَالْاَنْفَ بِالْاَنْفِ وَالْاُذُنَ بِالْاُذُنِ وَالسِّنَّ بِالسِّنِّۙ وَالْجُرُوْحَ قِصَاصٌۗ فَمَنْ تَصَدَّقَ بِهٖ فَهُوَ كَفَّارَةٌ لَّهٗ ۗ وَمَنْ لَّمْ يَحْكُمْ بِمَآ اَنْزَلَ اللّٰهُ فَاُولٰۤىِٕكَ هُمُ الظّٰلِمُوْنَ (45) وَقَفَّيْنَا عَلٰٓى اٰثَارِهِمْ بِعِيْسَى ابْنِ مَرْيَمَ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ التَّوْرٰىةِ ۖ وَاٰتَيْنٰهُ الْاِنْجِيْلَ فِيْهِ هُدًى وَّنُوْرٌۙ وَّمُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ التَّوْرٰىةِ وَهُدًى وَّمَوْعِظَةً لِّلْمُتَّقِيْنَۗ (46) وَلْيَحْكُمْ اَهْلُ الْاِنْجِيْلِ بِمَآ اَنْزَلَ اللّٰهُ فِيْهِۗ وَمَنْ لَّمْ يَحْكُمْ بِمَآ اَنْزَلَ اللّٰهُ فَاُولٰۤىِٕكَ هُمُ الْفٰسِقُوْنَ (47) المائدة : 44-47"],["p","Sesungguhnya Kami telah menurunkan Kitab Taurat di dalamnya (ada) petunjuk dan cahaya (yang menerangi), yang dengan Kitab itu diputuskan perkara orang-orang Yahudi oleh nabi-nabi yang menyerahkan diri kepada Allah, oleh orang-orang alim mereka dan pendeta-pendeta mereka, disebabkan mereka diperintahkan memelihara kitab-kitab Allah dan mereka menjadi saksi terhadapnya. Karena itu janganlah kamu takut kepada manusia, (tetapi) takutlah kepada-Ku. Dan janganlah kamu menukar ayat-ayat-Ku dengan harga yang sedikit. Barangsiapa yang tidak memutuskan menurut apa yang diturunkan Allah, maka mereka itu adalah orang-orang yang kafir. (44)"],["p","Dan kami telah tetapkan terhadap mereka di dalamnya (At Taurat) bahwasanya jiwa (dibalas) dengan jiwa, mata dengan mata, hidung dengan hidung, telinga dengan telinga, gigi dengan gigi, dan luka-luka (pun) ada qishashnya. Barangsiapa yang melepaskan (hak qishash) nya, maka melepaskan hak itu (menjadi) penebus dosa baginya. Barangsiapa tidak memutuskan perkara menurut apa yang diturunkan Allah, maka mereka itu adalah orang-orang yang dhalim. (45)"],["p","Dan Kami iringkan jejak mereka (nabi-nabi Bani Israil) dengan ‘Isa putra Maryam, membenarkan kitab yang sebelumnya, yaitu Taurat. Dan Kami telah memberikan kepadanya Kitab Injil sedang di dalamnya (ada) petunjuk dan cahaya (yang menerangi), dan membenarkan kitab yang sebelumnya, yaitu Kitab Taurat. Dan menjadi petunjuk serta pengajaran untuk orang-orang yang bertakwa. (46)"],["p","Dan hendaklah orang-orang pengikut Injil memutuskan perkara menurut apa yang diturunkan Allah di dalamnya. Barangsiapa tidak memutuskan perkara menurut apa yang diturunkan Allah, maka mereka itu adalah orang-orang yang fasiq. (47) [QS. Al Maaidah : 44-47]"],["p","4) Mereka berbuat bid’ah dengan mengadakan peraturan tidak beristri atau tidak bersuami."],["p","Allah SWT berfirman :"],["a","ثُمَّ قَفَّيْنَا عَلٰٓى اٰثَارِهِمْ بِرُسُلِنَا وَقَفَّيْنَا بِعِيْسَى ابْنِ مَرْيَمَ وَاٰتَيْنٰهُ الْاِنْجِيْلَ ۙ وَجَعَلْنَا فِيْ قُلُوْبِ الَّذِيْنَ اتَّبَعُوْهُ رَأْفَةً وَّرَحْمَةً ۗ وَرَهْبَانِيَّةَ ۨ ابْتَدَعُوْهَا مَا كَتَبْنٰهَا عَلَيْهِمْ اِلَّا ابْتِغَاۤءَ رِضْوَانِ اللّٰهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا ۚ فَاٰتَيْنَا الَّذِيْنَ اٰمَنُوْا مِنْهُمْ اَجْرَهُمْ ۚ وَكَثِيْرٌ مِّنْهُمْ فٰسِقُوْنَ. الحديد : 27"],["p","Kemudian Kami iringkan di belakang mereka dengan rasul-rasul Kami dan Kami iringkan (pula) ‘Isa putra Maryam; dan Kami berikan kepadanya Injil dan Kami jadikan dalam hati orang-orang yang mengikutinya rasa santun dan kasih sayang. Dan mereka mengada-adakan rahbaniyyah padahal Kami tidak mewajibkannya kepada mereka tetapi (mereka sendirilah yang mengada-adakannya) untuk mencari keridlaan Allah, lalu mereka tidak memeliharanya dengan pemeliharaan yang semestinya. Maka Kami berikan kepada orang-orang yang beriman di antara mereka pahalanya dan banyak di antara mereka orang-orang yang fasiq. [QS. Al Hadiid : 27]"],["p","(Bersambung)"]],"c20221127_1308":[["p","Ahad, 27 November 2022/ 3 Jumaadal Uulaa 1444 Brosur No.: 2103/2143/IA"],["h","TASYABBUH (2)"],["p","5) Mereka suka memakan makanan yang haram."],["p","Allah SWT berfirman :"],["a","سَمّٰعُوْنَ لِلْكَذِبِ اَكّٰلُوْنَ لِلسُّحْتِۗ فَاِنْ جَاۤءُوْكَ فَاحْكُمْ بَيْنَهُمْ اَوْ اَعْرِضْ عَنْهُمْ ۚ وَاِنْ تُعْرِضْ عَنْهُمْ فَلَنْ يَّضُرُّوْكَ شَيْـًٔا ۗ وَاِنْ حَكَمْتَ فَاحْكُمْ بَيْنَهُمْ بِالْقِسْطِۗ اِنَّ اللّٰهَ يُحِبُّ الْمُقْسِطِيْنَ . المائدة : 42"],["p","Mereka itu adalah orang-orang yang suka mendengar berita bohong, banyak memakan yang haram. Jika mereka (orang Yahudi) datang kepadamu (untuk meminta putusan), maka putuskanlah (perkara itu) di antara mereka, atau berpalinglah dari mereka; jika kamu berpaling dari mereka maka mereka tidak akan memberi mudlarat kepadamu sedikit pun. Dan jika kamu memutuskan perkara mereka, maka putuskanlah (perkara itu) di antara mereka dengan adil, sesungguhnya Allah menyukai orang-orang yang adil. [QS. Al Maaidah : 42]"],["a","وَتَرٰى كَثِيْرًا مِّنْهُمْ يُسَارِعُوْنَ فِى الْاِثْمِ وَالْعُدْوَانِ وَاَكْلِهِمُ السُّحْتَۗ لَبِئْسَ مَا كَانُوْا يَعْمَلُوْنَ (62) لَوْلَا يَنْهٰىهُمُ الرَّبَّانِيُّوْنَ وَالْاَحْبَارُ عَنْ قَوْلِهِمُ الْاِثْمَ وَاَكْلِهِمُ السُّحْتَۗ لَبِئْسَ مَا كَانُوْا يَصْنَعُوْنَ (63) المائدة : 62-63"],["p","Dan kamu akan melihat kebanyakan dari mereka (orang-orang Yahudi) bersegera membuat dosa, permusuhan dan memakan yang haram. Sesungguhnya amat buruk apa yang telah mereka kerjakan itu. (62)"],["p","Mengapa orang-orang alim mereka, pendeta-pendeta mereka tidak melarang mereka mengucapkan perkataan bohong dan memakan yang haram? Sesungguhnya amat buruk apa yang telah mereka kerjakan itu. (63) [QS. Al Maaidah : 62-63]"],["p","6) Mereka suka mempercayai cerita-cerita bohong."],["p","Allah SWT berfirman :"],["a","وَاتَّبَعُوْا مَا تَتْلُوا الشَّيٰطِيْنُ عَلٰى مُلْكِ سُلَيْمٰنَ ۚ وَمَا كَفَرَ سُلَيْمٰنُ وَلٰكِنَّ الشَّيٰطِيْنَ كَفَرُوْا يُعَلِّمُوْنَ النَّاسَ السِّحْرَ وَمَآ اُنْزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوْتَ وَمَارُوْتَ ۗ وَمَا يُعَلِّمٰنِ مِنْ اَحَدٍ حَتّٰى يَقُوْلَآ اِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ ۗ فَيَتَعَلَّمُوْنَ مِنْهُمَا مَا يُفَرِّقُوْنَ بِهٖ بَيْنَ الْمَرْءِ وَزَوْجِهٖ ۗ وَمَا هُمْ بِضَاۤرِّيْنَ بِهٖ مِنْ اَحَدٍ اِلَّا بِاِذْنِ اللّٰهِ ۗ وَيَتَعَلَّمُوْنَ مَا يَضُرُّهُمْ وَلَا يَنْفَعُهُمْ ۗ وَلَقَدْ عَلِمُوْا لَمَنِ اشْتَرٰىهُ مَا لَهٗ فِى الْاٰخِرَةِ مِنْ خَلَاقٍ ۗ وَلَبِئْسَ مَاشَرَوْا بِهٖٓ اَنْفُسَهُمْ ۗ لَوْ كَانُوْا يَعْلَمُوْنَ (102) وَلَوْ اَنَّهُمْ اٰمَنُوْا وَاتَّقَوْا لَمَثُوْبَةٌ مِّنْ عِنْدِ اللّٰهِ خَيْرٌ ۗ لَوْ كَانُوْا يَعْلَمُوْنَ (103) البقرة : 102-103"],["p","Dan mereka mengikuti apa yang dibaca oleh syaitan-syaitan pada masa kerajaan Sulaiman (dan mereka mengatakan bahwa Sulaiman itu mengerjakan sihir), padahal Sulaiman tidak kafir (tidak mengerjakan sihir), hanya syaitan-syaitan itulah yang kafir (mengerjakan sihir). Mereka mengajarkan sihir kepada manusia dan apa yang diturunkan kepada dua orang malaikat di negeri Babil yaitu Harut dan Marut, sedang keduanya tidak mengajarkan (sesuatu) kepada seorang pun sebelum mengatakan: \"Sesungguhnya kami hanya cobaan (bagimu), sebab itu janganlah kamu kafir\". Maka mereka mempelajari dari kedua malaikat itu apa yang dengan sihir itu mereka dapat menceraikan antara seorang (suami) dengan istrinya. Dan mereka itu (ahli sihir) tidak memberi mudlarat dengan sihirnya kepada seorang pun kecuali dengan izin Allah. Dan mereka mempelajari sesuatu yang memberi mudlarat kepadanya dan tidak memberi manfaat. Dan sesungguhnya mereka telah mengetahui bahwa barangsiapa yang menukarnya (kitab Allah) dengan sihir itu, tiadalah baginya keuntungan di akhirat, dan amat jahatlah perbuatan mereka menjual dirinya dengan sihir, kalau mereka mengetahui. (102)"],["p","Sesungguhnya kalau mereka beriman dan bertaqwa, (niscaya mereka akan mendapat pahala), dan sesungguhnya pahala dari sisi Allah adalah lebih baik, kalau mereka mengetahui. (103) [QS. Al Baqarah : 102-103]"],["p","7) Mereka merasa sombong mengaku sebagai anak-anak Allah dan kekasih-kekasih-Nya."],["p","Allah SWT berfirman :"],["a","وَقَالَتِ الْيَهُوْدُ وَالنَّصٰرٰى نَحْنُ اَبْنٰۤؤُا اللّٰهِ وَاَحِبَّاۤؤُهٗ ۗ قُلْ فَلِمَ يُعَذِّبُكُمْ بِذُنُوْبِكُمْ ۗ بَلْ اَنْتُمْ بَشَرٌ مِّمَّنْ خَلَقَۗ يَغْفِرُ لِمَنْ يَّشَاۤءُ وَيُعَذِّبُ مَنْ يَّشَاۤءُۗ وَلِلّٰهِ مُلْكُ السَّمٰوٰتِ وَالْاَرْضِ وَمَا بَيْنَهُمَا ۖ وَاِلَيْهِ الْمَصِيْرُ. المائدة : 18"],["p","Orang-orang Yahudi dan Nashrani mengatakan: \"Kami ini adalah anak-anak Allah dan kekasih-kekasih-Nya\". Katakanlah: \"Maka mengapa Allah menyiksa kamu karena dosa-dosamu?\" (Kamu bukanlah anak-anak Allah dan kekasih-kekasih-Nya), tetapi kamu adalah manusia (biasa) di antara orang-orang yang diciptakan-Nya. Dia mengampuni bagi siapa yang dikehendaki-Nya dan menyiksa siapa yang dikehendaki-Nya. Dan kepunyaan Allah-lah kerajaan langit dan bumi serta apa yang ada antara keduanya. Dan kepada Allah-lah kembali (segala sesuatu). [QS. Al Maaidah : 18]"],["p","8) Mereka menjadikan kuburan para Nabi, pemimpinnya atau orang - orang alimnya sebagai tempat ibadah."],["p","Di dalam hadits disebutkan :"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا اشْتَكَى النَّبِيُّ ﷺ ذَكَرَتْ بَعْضُ نِسَائِهِ كَنِيْسَةً رَأَيْنَهَا بِاَرْضِ الْحَبَشَةِ يُقَالُ لَـهَا مَارِيَةُ. وَكَانَتْ اُمُّ سَلَمَةَ وَاُمُّ حَبِيْبَةَ رَضِيَ اللهُ عَنْهُمَا اَتَتَا اَرْضَ الْحَبَشَةِ فَذَكَرَتَا مِنْ حُسْنِهَا وَتَصَاوِيْرَ فِيْهَا، فَرَفَعَ رَأْسَهُ فَقَالَ: اُولــٰۤئِكَ اِذَا مَاتَ مِنْهُمُ الرَّجُلُ الصَّالِحُ بَنَوْا عَلَى قَبْرِهِ مَسْجِدًا ثُـمَّ صَوَّرُوْا فِيْهِ تِلْكَ الصُّوْرَةَ، اُولـٰۤئِكَ شِرَارُ الْخَلْقِ عِنْدَ اللهِ. البخارى 2: 93"],["p","Dari ‘Aisyah RA, ia berkata : “Ketika Nabi SAW sedang sakit (yakni yang menyebabkan wafat beliau), ada sebagian diantara istri-istri beliau menyebut-nyebut tentang keadaan gereja yang pernah mereka lihat di negeri Habasyah yang diberi nama Mariyah. Dahulu Ummu Salamah dan Ummu Habibah RA pernah datang di negeri Habasyah, lalu mereka menceritakan tentang keindahannya dan lukisan-lukisan yang ada di dalam gereja itu. (Setelah mendengar cerita itu), lalu beliau mengangkat kepalanya dan bersabda: “Mereka itu, jika ada orang shalih diantara mereka yang meninggal dunia, lalu mereka mendirikan masjid (tempat peribadatan) di atas quburnya, lalu mereka membuat di dalamnya berbagai macam lukisan itu. Mereka adalah seburuk-buruk makhluq di sisi Allah”. [HR. Bukhari juz 2, hal. 93]"],["a","عَنِ ابْنِ شِهَابٍ اَخْبَرَنِيْ عُبَيْدُ اللهِ بْنُ عَبْدِ اللهِ اَنَّ عَائِشَةَ وَعَبْدَ اللهِ بْنَ عَبَّاسٍ قَالَا: لَمَّا نُزِلَ بِرَسُوْلِ اللهِ ﷺ طَفِقَ يَطْرَحُ خَمِيْصَةً لَهُ عَلَى وَجْهِهِ، فَاِذَا اغْتَمَّ كَشَفَهَا عَنْ وَجْهِهِ. فَقَالَ وَهُوَ كَذٰلِكَ: لَعْنَةُ اللهِ عَلَى الْيَهُوْدِ وَالنَّصَارَى، اِتَّخَذُوْا قُبُوْرَ اَنْبِيَائِهِمْ مَسَاجِدَ. يُحَذِّرُ مِثْلَ مَا صَنَعُوْا. مسلم 1: 377 رقم 22"],["p","Dari Ibnu Syihab, ia berkata : Mengkhabarkan kepadaku ‘Ubaidullah bin ‘Abdillah bahwasanya ‘Aisyah dan ‘Abdullah bin Abbas berkata : “Ketika Rasulullah SAW hampir wafat, beliau lalu menutupkan pakaiannya pada wajah beliau. Apabila beliau sedih, beliau membuka kain itu dari wajah beliau. Dalam keadaan demikian itu beliau bersabda: “Semoga la’nat Allah ditimpakan kepada orang-orang Yahudi dan Nashrani, mereka menjadikan quburan-quburan nabinya sebagai masjid-masjid”. Beliau memperingatkan (kaum muslimin agar tidak berbuat) seperti yang mereka lakukan. [HR. Muslim juz 1, hal. 377, no. 22]"],["a","عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُوْلُ اللهِ ﷺ فِيْ مَرَضِهِ الَّذِيْ لَـمْ يَقُمْ مِنْهُ: لَعَنَ اللهُ الْيَهُوْدَ وَالنَّصَارَى اِتَّخَذُوْا قُبُوْرَ اَنْبِيَائِهِمْ مَسَاجِدَ. قَالَتْ: فَلَوْلَا ذَاكَ اُبْرِزَ قَبْرُهُ، غَيْرَ اَنَّهُ خُشِيَ اَنْ يُتَّخَذَ مَسْجِدًا. مسلم 1: 376 رقم 19"],["p","Dari ‘Aisyah, ia berkata : Rasulullah SAW bersabda ketika beliau sakit yang tidak bisa bangun lagi (sakit yang menyebabkan beliau wafat):“Semoga Allah mela’nat orang-orang Yahudi dan Nashrani, mereka menjadikan quburan Nabi-nabi mereka sebagai masjid-masjid”. Kemudian ‘Aisyah berkata: “Seandainya bukan karena hal itu, tentu qubur (Nabi SAW) itu ditinggikan. Namun dikhawatirkan akan dijadikan sebagai masjid”. [HR. Muslim juz 1, hal. 376, no. 19]"],["p","Rasulullah SAW sebagai Nabi dan Rasul yang terakhir memberitahukan kepada ummatnya bahwa ummat Islam akan mengikuti langkah langkah Yahudi dan Nashrani."],["p","Di dalam hadits disebutkan :"],["a","عَنْ اَبِيْ سَعِيْدِ الْخُدْرِيِّ عَنِ النَّبِيِّ ﷺ قَالَ: لَتَتْبَعُنَّ سُنَنَ مَنْ كَانَ قَبْلَكُمْ شِبْرًا شِبْرًا وَ ذِرَاعًا بِذِرَاعٍ حَتَّى لَوْ دَخَلُوْا جُحْرَ ضَبٍّ تَبِعْتُمُوْهُمْ. قُلْنَا: يَا رَسُوْلَ اللهِ، آلْيَهُوْدُ وَ النَّصَارَى؟ قَالَ: فَمَنْ؟ البخارى 8: 151"],["p","Dari Abu Sa’id Al-Khudriy, dari Nabi SAW, beliau bersabda: “Sungguh kalian akan mengikuti langkah orang-orang sebelum kalian, sejengkal demi sejengkal dan sehasta demi sehasta, sehingga walaupun mereka memasuki lubang biawak, kalian tetap mengikutinya”. Kami (shahabat) bertanya: “Ya Rasulullah, apakah mereka itu kaum Yahudi dan Nashrani?” Beliau bersabda: “Lalu, siapa lagi ?”. [HR. Bukhari juz 8, hal. 151]"],["a","عَنْ اَبِيْ سَعِيْدِ الْخُدْرِيِّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : لَتَتْبَعُنَّ سُنَنَ الَّذِيْنَ مِنْ قَبْلِكُمْ شِبْرًا بِشِبْرٍ وَ ذِرَاعًا بِذِرَاعٍ حَتَّى لَوْ دَخَلُوْا فِيْ جُحْرِ ضَبٍّ لَاتَّبَعْتُمُوْهُمْ. قُلْنَا: يَا رَسُوْلَ اللهِ، آلْيَهُوْدُ وَ النَّصَارَى؟ قَالَ: فَمَنْ ؟ مسلم 4: 2054 رقم 6"],["p","Dari Abu Sa’id Al-Khudriy, ia berkata : Rasulullah SAW bersabda: “Sungguh kalian akan mengikuti langkah orang-orang sebelum kalian, sejengkal demi sejengkal dan sehasta demi sehasta, sehingga walaupun mereka memasuki lubang biawak, kalian tetap mengikutinya”. Kami (shahabat) bertanya: “Ya Rasulullah, apakah mereka itu kaum Yahudi dan Nashrani ?”. Beliau bersabda: “Lalu, siapa lagi ?”. [HR. Muslim juz 4, hal. 2054, no. 6]"],["a","عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : لَيَأْتِيَنَّ عَلَى اُمَّتِيْ مَا اَتَى عَلَى بَنِيْ اِسْرَائِيْلَ حَذْوَ النَّعْلِ بِالنَّعْلِ، حَتَّى اِنْ كَانَ مِنْهُمْ مَنْ اَتَى اُمَّهُ عَلَانِيَةً لَكَانَ فِيْ اُمَّتِيْ مَنْ يَصْنَعُ ذٰلِكَ، وَاِنَّ بَنِيْ اِسْرَائِيْلَ تَفَرَّقَتْ عَلَى ثِنْتَيْنِ وَسَبْعِيْنَ مِلَّةً، وَتَفْتَرِقُ اُمَّتِيْ عَلَى ثَلَاثٍ وَسَبْعِيْنَ مِلَّةً، كُلُّهُمْ فِي النَّارِ اِلَّا مِلَّةً وَاحِدَةً. قَالَ: مَنْ هِيَ يَا رَسُوْلَ اللهِ؟ قَالَ: مَا اَنَا عَلَيْهِ وَاَصْحَابِيْ. الترمذى 4: 135، رقم 2779 هذا حديث حسن غريب مفسر"],["p","Dari 'Abdullah bin 'Amr, ia berkata : Rasulullah SAW bersabda: \"Sungguh akan datang pada ummatku sebagaimana yang datang pada Bani Israil, setapak demi setapak, sehingga jika ada di kalangan mereka orang yang mengumpuli ibunya dengan terang-terangan, tentu ada pula di kalangan ummatku yang berbuat seperti itu. Dan sesungguhnya Bani Israil terpecah menjadi 72 golongan, dan ummatku akan terpecah menjadi 73 golongan, semuanya di neraka kecuali satu golongan\". Ada shahabat yang bertanya, \"Siapa itu ya Rasulullah ?\". Beliau bersabda: \"Yaitu golongan yang aku dan para shahabatku ada padanya\". [HR. Tirmidzi juz 4, hal. 135, no. 2779. Ini hadits hasan gharib mufassar]"],["p","Dan barangsiapa menyerupai suatu kaum, maka ia termasuk bagian dari mereka. Di dalam hadits disebutkan :"],["a","عَنِ ابْنِ عُمَرَ قَالَ : قَالَ رَسُوْلُ اللهِ ﷺ : مَنْ تَشَبَّهَ بِقَوْمٍ فَهُوَ مِنْهُمْ. ابو داود 4 : 44 رقم 4031"],["p","Dari Ibnu ‘Umar, ia berkata: Rasulullah SAW bersabda: “Barangsiapa menyerupai (meniru) suatu kaum, maka ia termasuk dari mereka”.[HR. Abu Dawud juz 4, hal 44, no. 4031]"],["a","عَنْ عَمْرِو بْنِ شُعَيْبٍ عَنْ اَبِيْهِ عَنْ جَدِّهِ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: لَيْسَ مِنَّا مَنْ تَشَبَّهَ بِغَيْرِنَا، لَا تَشَبَّهُوْا بِالْيَهُودِ وَلَا بِالنَّصَارَى، فَاِنَّ تَسْلِيْمَ الْيَهُوْدِ الْإِشَارَةُ بِالْأَصَابِعِ وَتَسْلِيْمَ النَّصَارَى الْإِشَارَةُ بِالْأَكُفِّ . الترمذى 4: 159 رقم 2836"],["p","Dari 'Amr bin Syu'aib dari Ayahnya dari kakeknya, bahwasanya Rasulullah SAW bersabda: \"Bukan termasuk golongan kami orang yang menyerupai selain kami, janganlah kalian menyerupai orang-orang Yahudi dan orang-orang Nashrani, sesungguhnya salamnya orang-orang Yahudi adalah memberikan isyarat dengan jari jari tangan, sedangkan salamnya orang orang Nashrani adalah memberikan isyarat dengan telapak tangan.\" [HR. Tirmidzi juz 4, hal. 159, no. 2836, dlo’if, karena dalam isnadnya ada perawi bernama Ibnu Lahi’ah, dan juga hadits ini diperselisihkan tentang marfu’ atau mauqufnya]."],["a","عَنِ ابْنِ عُمَرَ قَالَ : قَالَ رَسُوْلُ اللهِ ﷺ : بُعِثْتُ بَيْنَ يَدَيِ السَّاعَةِ بِالسَّيْفِ حَتَّى يُعْبَدَ اللهُ لَاشَرِيْكَ لَهُ، وَ جُعِلَ رِزْقِيْ تَحْتَ ظِلِّ رُمْحِيْ، وَ جُعِلَ الذِّلَّةُ وَ الصِّغَارُ عَلَى مَنْ خَالَفَ اَمْرِيْ، وَ مَنْ تَشَبَّهَ بِقَوْمٍ فَهُوَ مِنْهُمْ . احمد 2 : 310 رقم 5115"],["p","Dari Ibnu ‘Umar, ia berkata: Rasulullah SAW bersabda: “Aku diutus dengan pedang menjelang hari qiyamat sehingga hanya Allah saja yang disembah, tidak ada sekutu bagi-Nya, dijadikan rizqiku di bawah bayangan tombakku, dan dijadikan kehinaan dan kerendahan bagi siapa saja yang menyelisihi urusanku. Barangsiapa yang menyerupai suatu kaum, maka ia termasuk golongan mereka.” [HR. Ahmad juz 2, hal. 310, no. 5115]"],["p","Sesungguhnya tasyabbuh (meniru gaya) orang kafir secara lahiriyah mewariskan kecintaan dan kesetiaan dalam batin. Begitu pula kecintaan dalam batin mewariskan tasyabbuh secara lahiriyah."],["p","(Bersambung)"]],"c20221204_1309":[["p","Ahad, 4 Desember 2022/10 Jumaadal Uulaa 1444 Brosur No. : 2104/2144/IA"],["h","TASYABBUH (3)"],["p","Larangan laki-laki menyerupai wanita dan wanita menyerupai laki-laki"],["p","Laki-laki yang sengaja menyerupai wanita dalam berpakaian, berdandan, bertingkah laku, berbicara, bergaya dan sebagainya adalah haram. Demikian pula wanita yang menyerupai laki-laki, berdasarkan hadits-hadits sebagai berikut :"],["a","عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَعَنَ رَسُوْلُ اللهِ ﷺ الْمُتَشَبِّهِيْنَ مِنَ الرِّجَالِ بِالنِّسَاءِ، وَ الْمُتَشَبِّهَاتِ مِنَ النِّسَاءِ بِالرِّجَالِ. البخارى 7: 55"],["p","Dari Ibnu ‘Abbas RA, ia berkata, “Rasulullah SAW mela’nat orang laki-laki yang menyerupai wanita, dan para wanita yang menyerupai laki-laki”. [HR. Bukhari juz 7, hal. 55]"],["a","عَنِ ابْنِ عَبَّاسٍ عَنِ النَّبِيِّ ﷺ اَنَّهُ لَعَنَ الْمُتَشَبِّهَاتِ مِنَ النِّسَاءِ بِالرِّجَالِ، وَ الْمُتَشَبِّهِيْنَ مِنَ الرِّجَالِ بِالنِّسَاءِ. ابو داود 4: 60، رقم: 4097"],["p","Dari Ibnu ‘Abbas, dari Nabi SAW, bahwasanya beliau mela’nat wanita yang menyerupai laki-laki, dan laki-laki yang menyerupai wanita. [HR. Abu Dawud juz 4, hal. 60, no. 4097]"],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: لَعَنَ النَّبِيُّ ﷺ الْمُخَنَّثِيْنَ مِنَ الرِّجَالِ، وَ الْمُتَرَجِّلَاتِ مِنَ النِّسَاءِ. وَ قَالَ: اَخْرِجُوْهُمْ مِنْ بُيُوْتِكُمْ. البخارى 7: 55"],["p","Dari Ibnu 'Abbas, ia berkata : “Rasulullah SAW mela’nat para laki-laki yang bergaya seperti wanita, dan para wanita yang bergaya seperti laki-laki. Dan beliau bersabda: “Keluarkanlah mereka dari rumah-rumah kalian”. [HR. Bukhari juz 7, hal. 55]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: لَعَنَ رَسُوْلُ اللهِ ﷺ الرَّجُلَ يَلْبَسُ لِبْسَةَ الْمَرْأَةِ، وَ الْمَرْأَةَ تَلْبَسُ لِبْسَةَ الرَّجُلِ. ابو داود 4: 60، رقم: 4098"],["p","Dari Abu Hurairah, ia berkata: \"Rasulullah SAW mela’nat orang laki-laki yang memakai pakaian wanita, dan wanita yang memakai pakaian laki-laki\". [HR. Abu Dawud juz 4, hal. 60, no. 4098]."],["a","عَنِ ابْنِ عَبَّاسٍ اَنَّ امْرَأَةً مَرَّتْ عَلَى رَسُوْلِ اللهِ ﷺ مُتَقَلِّدَةً قَوْسًا، فَقَالَ النَّبِيُّ ﷺ : لَعَنَ اللهُ الْمُتَشَبِّهَاتِ مِنَ النِّسَاءِ بِالرِّجَالِ، وَ الْمُتَشَبِّهِيْنَ مِنَ الرِّجَالِ بِالنِّسَاءِ. الطبرانى فى المعجم الاوسط 5: 14، رقم: 4015"],["p","Dari Ibnu ‘Abbas, bahwasanya ada seorang wanita berselempang busur panah lewat di depan Rasulullah SAW, maka Nabi SAW bersabda: “Allah mela’nat para wanita yang menyerupai laki-laki, dan para laki-laki yang menyerupai wanita”. [HR. Thabaraniy dalam Al-Mu’jamul Ausath, juz 5, hal. 14, no. 4015, hadits ini dla’if karena dalam sanadnya ada perawi bernama ‘Ali bin Sa’id Ar-Raaziy]"],["a","عَنْ رَجُلٍ مِنْ هُذَيْلٍ قَالَ: رَأَيْتُ عَبْدَ اللهِ بْنَ عَمْرِو بْنِ الْعَاصِى، وَ مَنْزِلُهُ فِى الْحِلِّ، وَ مَسْجِدُهُ فِى الْحَرَمِ قَالَ: فَبَيْنَا اَنَا عِنْدَهُ رَأَى اُمَّ سَعِيْدٍ اِبْنَةَ اَبِيْ جَهْلٍ مُتَقَلِّدَةً قَوْسًا، وَ هِيَ تَمْشِى مِشْيَةَ الرَّجُلِ. فَقَالَ عَبْدُ اللهِ: مَنْ هٰذِهِ؟ قَالَ الْهُذَلِيُّ فَقُلْتُ: هٰذِهِ اُمُّ سَعِيْدٍ بِنْتُ اَبِيْ جَهْلٍ. فَقَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: لَيْسَ مِنَّا مَنْ تَشَبَّهَ بِالرِّجَالِ مِنَ النِّسَاءِ، وَ لَا مَنْ تَشَبَّهَ بِالنِّسَاءِ مِنَ الرّجَالِ. احمد 2: 640، رقم: 6892"],["p","Dari seorang laki-laki suku Hudzail, ia berkata : “Saya pernah melihat ‘Abdullah bin ‘Amr bin 'Ash, orang tersebut rumahnya di tanah halal sedang masjidnya di tanah haram. Pada suatu ketika saya sedang berada di sisinya, kemudian dia (‘Abdullah bin 'Amr) melihat Ummu Sa'id binti Abu Jahal berselempang busur panah berjalan seperti berjalannya orang laki-laki. Lalu ‘Abdullah (bin ‘Amr) bertanya : \"Siapa wanita ini ?\". Orang dari Hudzail itu berkata : Lalu aku menjawab : \"Ini Ummu Sa'id binti Abu Jahal\". Lalu ‘Abdullah bin ‘Amr berkata : “Aku mendengar Rasulullah SAW bersabda: \"Bukan dari golongan kami wanita yang menyerupai laki-laki, dan laki-laki yang menyerupai wanita\". [HR. Ahmad juz 2, hal. 640, no. 6892, dla’if karena dalam sanadnya ada perawi yang tidak disebutkan namanya]"],["a","عَنْ اَبِيْ هُرَيْرَةَ اَنَّ النَّبِيَّ ﷺ اُتِيَ بِمُخَنَّثٍ قَدْ خَضَبَ يَدَيْهِ وَ رِجْلَيْهِ بِالْحِنَّاءِ، فَقَالَ النَّبِيُّ ﷺ : مَا بَالُ هٰذَا؟ فَقِيْلَ: يَا رَسُوْلَ اللهِ، يَتَشَبَّهُ بِالنِّسَاءِ. فَأُمِرَ فَنُفِيَ اِلَى النَّقِيْعِ. فَقَالُوْا: يَا رَسُوْلَ اللهِ، اَلَا نَقْتُلُهُ؟ فَقَالَ: اِنِّيْ نُهِيْتُ عَنْ قَتْلِ الْمُصَلِّيْنَ. ابو داود 4: 282 رقم 4928"],["p","Dari Abu Hurairah, bahwasanya dibawa kepada Nabi SAW seorang laki-laki yang berlagak seperti wanita, dia memberi warna dengan hinna' (quitec) pada (kuku-kuku) kedua tangan dan kakinya. Maka Rasulullah SAW bertanya : \"Kenapa orang ini ?\" Ada shahabat yang menjawab: “Ya Rasulullah, orang laki-laki itu berlagak seperti wanita\". Lalu diperintahkan (oleh Rasulullah SAW) supaya orang tersebut diasingkan ke Naqi' (suatu tempat di daerah Muzainah, perjalanan dua malam dari Madinah). Lalu shahabat bertanya: \"Ya Rasulullah, apakah tidak kita bunuh saja orang itu ?\" Beliau menjawab: \"Sesungguhnya aku dilarang membunuh orang-orang yang shalat\". [HR. Abu Dawud juz 4, hal. 282, no. 4928]"],["p","Larangan wanita menyambung rambut, mencukur Alis, menjarangkan gigi, dan bertatto."],["p","Islam melarang para wanita menyambung rambut, mencabut bulu dahi atau mencukur alis, mengikir giginya supaya jarang dan kelihatan cantik, dan wanita yang mencacah (bertatto), berdasar hadits-hadits sebagai berikut :"],["a","عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا اَنَّ جَارِيَةً مِنَ الْاَنْصَارِ تَزَوَّجَتْ وَ اَنَّهَا مَرِضَتْ فَتَمَعَّطَ شَعَرُهَا، فَاَرَادُوْا اَنْ يَصِلُوْهَا، فَسَأَلُوا النَّبِيَّ ﷺ ، فَقَالَ: لَعَنَ اللهُ الْوَاصِلَةَ وَ الْمُسْتَوْصِلَةَ. البخارى 7: 62"],["p","Dari 'Aisyah RA, bahwasanya ada seorang wanita Anshar menikah, dan ia terserang penyakit sehingga rambutnya rontok. Lalu keluarganya ingin menyambung rambutnya, maka mereka bertanya kepada Nabi SAW, maka Nabi SAW bersabda : \"Allah mela’nat wanita yang menyambung rambut dan wanita yang minta disambung rambutnya\". [HR. Bukhari juz 7, hal. 62]"],["a","عَنْ اَسْمَاءَ قَالَتْ: سَأَلَتِ امْرَأَةٌ النَّبِيَّ ﷺ فَقَالَتْ: يَا رَسُوْلَ اللهِ، اِنَّ ابْنَتِيْ اَصَابَتْهَا الْحَصْبَةُ فَامَّرَقَ شَعَرُهَا، وَ اِنِّيْ زَوَّجْتُهَا، اَفَأَصِلُ فِيْهِ؟ فَقَالَ: لَعَنَ اللهُ الْوَاصِلَةَ وَ الْمَوْصُوْلَةَ. البخارى 7: 63"],["p","Dari Asma', ia berkata : “Ada seorang wanita bertanya kepada Nabi SAW. Ia berkata: \"Ya Rasulullah, sesungguhnya anak perempuan saya terkena sakit panas sehingga rambutnya rontok, dan saya telah menikahkannya. Apakah boleh saya sambung rambutnya ?\". Maka Rasulullah SAW bersabda: \"Allah mela’nat wanita yang menyambung rambut dan wanita yang disambung rambutnya\". [HR. Bukhari juz 7, hal. 63]"],["a","عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَعَنَ النَّبِيُّ ﷺ الْوَاصِلَةَ وَ الْمُسْتَوْصِلَةَ، وَ الْوَاشِمَةَ وَ الْمُسْتَوْشِمَةَ. البخارى 7: 63"],["p","Dari Ibnu Umar RA, ia berkata: \"Nabi SAW mela’nat wanita yang menyambung rambut dan wanita yang minta disambung rambutnya, (dan mela’nat) wanita yang mencacah (mentatto) dan wanita yang minta dicacah (ditatto)\". [HR. Bukhari juz 7, hal. 63]."],["a","عَنْ اَسْمَاءَ بِنْتِ اَبيْ بَكْرٍ قَالَتْ: لَعَنَ رَسُوْلُ اللهِ ﷺ الْوَاصِلَةَ وَ الْمُسْتَوْصِلَةَ. البخارى 7: 62"],["p","Dari Asma' binti Abu Bakar, ia berkata: \"Rasulullah SAW mela’nat wanita yang menyambung rambut dan wanita yang minta disambung rambutnya\". [HR. Bukhari juz 7, hal. 62]."],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: لُعِنَتِ الْوَاصِلَةُ وَ الْمُسْتَوْصِلَةُ، وَ النَّامِصَةُ وَ الْمُتَنَمِّصَةُ، وَ الْوَاشِمَةُ وَ الْمُسْتَوْشِمَةُ مِنْ غَيْرِ دَاءٍ. ابو داود 4: 78، رقم: 4170"],["p","Dari Ibnu Abbas, ia berkata, \"Telah dila’nat wanita yang menyambung rambut dan wanita yang minta disambung rambutnya, wanita yang mencabut bulu dahi (atau ngerik alis) dan wanita yang dicabut bulu dahinya (atau dikerik alisnya), dan wanita yang mencacah (mentatto) dan wanita yang minta dicacah (ditatto) bukan karena sakit\". [HR. Abu Dawud juz 4, hal. 78, no. 4170]."],["a","عَنْ عَلْقَمَةَ قَالَ: لَعَنَ عَبْدُ اللهِ الْوَاشِمَاتِ وَ الْمُتَنَمِّصَاتِ وَ الْمُتَفَلِّجَاتِ لِلْحُسْنِ الْمُغَيِّرَاتِ خَلْقَ اللهِ. فَقَالَتْ اُمُّ يَعْقُوْبَ: مَا هٰذَا؟ قَالَ عَبْدُ اللهِ: وَ مَا لِيْ لَا اَلْعَنُ مَنْ لَعَنَ رَسُوْلُ اللهِ ﷺ وَ فِيْ كِتَابِ اللهِ. قَالَتْ: وَ اللهِ، لَقَدْ قَرَأْتُ مَا بَيْنَ لَوْحَيْنِ فَمَا وَجَدْتُهُ. قَالَ: وَ اللهِ، لَاِنْ قَرَأْتِيْهِ وَجَدْتِيْهِ: وَ مَا آتَاكُمُ الرَّسُوْلُ فَخُذُوْهُ، وَ مَا نَهَاكُمْ عَنْهُ فَانْتَهُوْا. البخارى 7: 63"],["p","Dari ‘Alqamah, ia berkata : ‘Abdullah (bin Mas’ud) mela’nat wanita-wanita yang mencacah (mentatto), mela’nat wanita-wanita yang dicabut bulu dahinya (atau dikerik alisnya), dan wanita-wanita yang menjarangkan giginya supaya cantik, yaitu para wanita yang mengubah ciptaan Allah\". Lalu Ummu Ya’qub berkata (kepada Ibnu Mas'ud) “Apa ini ?”. Maka ‘Abdullah bin Mas'ud berkata: \"Mengapa aku tidak boleh mela’nat kepada orang yang dila’nat oleh Rasulullah SAW sedangkan di dalam kitab Allah (sudah dijelaskan): “Wanita itu berkata: “Demi Allah, sungguh aku telah membaca semuanya, tetapi aku tidak mendapatinya”. ‘Abdullah (bin Mas’ud) berkata: “Demi Allah, kalau kamu membacanya, pasti kamu mendapatinya. (Allah berfirman yang artinya), \"Apa yang didatangkan oleh Rasul kepada kalian, maka terimalah dia, dan apa yang dilarang oleh Rasul kepada kalian, maka tinggalkanlah\". (Al-Hasyr : 7). [HR. Bukhari juz 7, hal. 63]."],["a","عَنْ عَبْدِ اللهِ قَالَ: لَعَنَ رَسُوْلُ اللهِ ﷺ اَلْوَاشِمَاتِ وَ الْمُوْتَشِمَاتِ وَ الْمُتَنَمِّصَاتِ وَ الْمُتَفَلِّجَاتِ لِلْحُسْنِ الْمُغَيِّرَاتِ. النسائى 8: 146"],["p","Dari ‘Abdullah (bin Mas’ud), ia berkata : “Rasulullah SAW mela’nat wanita yang mentatto dan wanita yang minta ditatto, wanita yang mencabut bulu dahinya (mengerik alisnya), dan wanita yang menjarangkan giginya supaya cantik, yaitu para wanita yang merubah ciptaan Allah”. [HR. An-Nasaiy juz 8, hal. 146]"],["a","عَنْ سَعِيْدِ بْنِ الْمُسَيَّبِ قَالَ: قَدِمَ مُعَاوِيَةُ الْمَدِيْنَةَ فَخَطَبَنَا، وَ اَخْرَجَ كُبَّةً مِنْ شَعَرٍ، فَقَالَ: مَا كُنْتُ أُرَى اَنَّ اَحَدًا يَفْعَلُهُ اِلَّا الْيَهُوْدَ. اِنَّ رَسُوْلَ اللهِ ﷺ بَلَغَهُ فَسَمَّاهُ الزُّوْرَ. مسلم 3: 1680رقم 123"],["p","Dari Sa’id bin Musayyab, ia berkata, Mu'awiyah datang di Madinah lalu berkhutbah kepada kami, dia mengeluarkan seikat rambut lalu berkata : \"Aku tidak pernah melihat seorang pun yang berbuat demikian ini kecuali orang-orang Yahudi. Sesungguhnya Rasulullah SAW ketika hal itu sampai kepada beliau, menamakannya dengan Az-zuur (kepalsuan). [HR. Muslim juz 3, hal. 1680, no. 123]"],["p","Tentang wanita mencukur (menggundul) rambut kepalanya"],["a","عَنْ عَائِشَةَ اَنَّ النَّبِيَّ ﷺ نَهَى اَنْ تَحْلِقَ الْمَرْأَةُ رَأْسَهَا. الترمذى 2: 198، رقم: 918"],["p","Dari ‘Aisyah, bahwasanya Nabi SAW melarang wanita mencukur (menggundul) rambut kepalanya. [HR. Tirmidzi juz 2, hal. 198, no. 918, hadits ini munqathi’ karena Qatadah bin Di’aamah tidak bertemu dengan ‘Aisyah]."],["a","عَنْ خِلَاسِ بْنِ عَمْرٍو عَنْ عَلِيٍّ قَالَ: نَهَى رَسُوْلُ اللهِ ﷺ اَنْ تَحْلِقَ الْمَرْأَةُ رَأْسَهَا. الترمذى 2: 198، رقم: 917"],["p","Dari Khilas bin ‘Amr, dari ‘Ali ia berkata: “Rasulullah SAW melarang wanita mencukur (menggundul) rambut kepalanya”. [HR. Tirmidzi, juz 2, hal. 198, no. 917, hadits ini diperselisihkan tentang muttashilnya, karena pada riwayat yang lain tidak menyebutkan dari ‘Ali, maka mursal, karena Khilas bin ‘Amr tidak bertemu dengan Nabi SAW.]"],["a","عَنْ صَفِيَّةَ بِنْتِ شَيْبَةَ قَالَتْ: اَخْبَرَتْنِيْ اُمُّ عُثْمَانَ بِنْتُ اَبِيْ سُفْيَانَ اَنَّ ابْنَ عَبَّاسٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : لَيْسَ عَلَى النِّسَاءِ الْحَلْقُ اِنَّمَا عَلَى النِّسَاءِ التَّقْصِيرُ. ابو داود 2 : 203 رقم 1985"],["p","Dari Shafiyah binti Syaibah, ia berkata : Telah mengkhabarkan kepadaku Ummu ‘Utsman, bahwasanya Ibnu ‘Abbas berkata: “Rasulullah SAW bersabda: “ Tidak ada pada wanita (ketika tahallul) mencukur (menggundul) rambut, sesungguhnya yang ada pada wanita hanyalah memotong rambut.” [HR. Abu Dawud Juz 2, hal 203, no. 1985]"],["p","--oo0oo--"]],"c20221218_1310":[["p","Ahad, 18 Desember 2022/24 Jumaadal Uulaa 1444 Brosur No. : 2105/2145/IA"],["p","Kewajiban mengikuti sunnah Nabi dan menjauhi bid'ah"],["p","Kewajiban mengikuti sunnah Nabi"],["p","Mengikuti dan berpegang teguh pada Sunnah Nabi SAW. adalah suatu kewajiban atas setiap individu muslim dan muslimah yang senantiasa mendambakan keselamatan dan kebahagiaan hidup di dunia dan akhirat."],["p","Siapa yang mengikuti sunnah dan mengamalkannya, maka dia telah mengamalkan Al-Qur’an. Sama halnya, siapa yang menaati Rasulullah SAW berarti dia telah menaati Allah."],["a","مَنْ يُّطِعِ الرَّسُوْلَ فَقَدْ اَطَاعَ اللّٰهَ ۚ وَمَنْ تَوَلّٰى فَمَآ اَرْسَلْنٰكَ عَلَيْهِمْ حَفِيْظًا. النساء : 80"],["p","Barang siapa yang menaati Rasul itu, sesungguhnya ia telah menaati Allah. Dan barang siapa yang berpaling (dari ketaatan itu), maka Kami tidak mengutusmu untuk menjadi pemelihara bagi mereka. [Q.S. An Nisaa’: 80]"],["p","Yang dimaksudkan dengan Sunnah Nabi ialah petunjuk dan tuntunan apa saja yang datang dari Nabi SAW. kepada kita dengan jalan periwayatan yang shahih baik berkaitan dengan perkara aqidah, ibadah, mu’amalah, akhlaq & adab, maupun selainnya dari perkara-perkara agama Islam."],["p","Diantara dalil-dalil syar’i yang menunjukkan kewajiban mengikuti dan berpegang teguh pada Sunnah Nabi SAW. dalam setiap urusan agama ialah sebagai berikut:"],["p","Firman Allah SWT :"],["a","قُلْ اِنْ كُنْتُمْ تُحِبُّوْنَ اللّٰهَ فَاتَّبِعُوْنِيْ يُحْبِبْكُمُ اللّٰهُ وَيَغْفِرْ لَكُمْ ذُنُوْبَكُمْ ۗ وَاللّٰهُ غَفُوْرٌ رَّحِيْمٌ. ال عمران : 31"],["p","Katakanlah: \"Jika kamu (benar-benar) mencintai Allah, ikutilah aku, niscaya Allah mengasihi dan mengampuni dosa-dosamu.\" Allah Maha Pengampun lagi Maha Penyayang. [QS. Ali ‘Imraan: 31]"],["a","فَلَا وَرَبِّكَ لَا يُؤْمِنُوْنَ حَتّٰى يُحَكِّمُوْكَ فِيْمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوْا فِيْٓ اَنْفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوْا تَسْلِيْمًا. النساء : 65"],["p","Maka demi Tuhanmu, mereka (pada hakekatnya) tidak beriman hingga mereka menjadikan kamu hakim dalam perkara yang mereka perselisihkan, kemudian mereka tidak merasa keberatan dalam hati mereka terhadap putusan yang kamu berikan, dan mereka menerima dengan sepenuhnya. [QS. An-Nisaa’: 65]"],["a","تَرَكْتُ فِيْكُمْ اَمْرَيْنِ لَنْ تَضِلُّوْا مَا مَسَكْتُمْ بِهِمَا: كِتَابَ اللهِ وَ سُنَّةَ نَبِيِّهِ. مالك، فى الموطأ 2: 899"],["p","Kutinggalkan pada kamu sekalian dua perkara yang kamu tidak akan sesat apabila kamu berpegang teguh kepada keduaya, yaitu : Kitab Allah dan sunnah Nabi-Nya\". [HR. Malik dalam Al-Muwaththa’ juz 2, hal. 899]"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اِنَّ اَصْدَقَ الْحَدِيْثِ كِتَابُ اللهِ وَ اَحْسَنَ الْهَدْيِ هَدْيُ مُحَمَّدٍ وَ شَرُّ الْاُمُوْرِ مُحْدَثَاتُهَا وَ كُلُّ مُحْدَثَةٍ بِدْعَةٌ وَ كُلُّ بِدْعَةٍ ضَلَالَةٌ وَ كُلُّ ضَلَالَةٍ فِي النَّارِ. النسائى 3: 188"],["p","Dari Jabir bin ‘Abdullah, ia berkata : Rasulullah SAW bersabda, “Sesungguhnya sebenar-benar perkataan ialah Kitab Allah, dan sebaik-baik petunjuk ialah petunjuk Muhammad, dan sejelek-jelek perkara itu yang diada-adakan, dan tiap-tiap yang diada-adakan itu bid’ah, dan tiap-tiap bid’ah itu sesat, dan tiap-tiap kesesatan itu di neraka”. [HR. Nasai juz 3, hal. 188]"],["a","عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: كَانَ رَسُوْلُ اللهِ ﷺ يَقُوْلُ: اَمَّا بَعْدُ فَاِنَّ خَيْرَ الْحَدِيْثِ كِتَابُ اللهِ وَ خَيْرُ الْهُدَى هُدَى مُحَمَّدٍ وَ شَرُّ الْاُمُوْرِ مُحْدَثَاتُهَا وَ كُلُّ بِدْعَةٍ ضَلاَلَةٌ. مسلم 2: 592"],["p","Dari Jabir bin ‘Abdullah, ia berkata : Adalah Rasulullah SAW bersabda, “Adapun sesudah itu, sesungguhnya sebaik-baik perkataan adalah kitab Allah, dan sebaik-baik petunjuk adalah petunjuk Muhammad, dan seburuk-buruk perkara adalah yang diada-adakan, dan setiap bid’ah adalah sesat. [HR. Muslim juz 2, hal. 592]"],["a","عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اُوْصِيْكُمْ بِتَقْوَى اللهِ وَ السَّمْعِ وَ الطَّاعَةِ وَ اِنْ كَانَ عَبْدًا حَبَشِيًّا فَاِنَّهُ مَنْ يَعِشْ مِنْكُمْ بَعْدِى فَسَيَرَى اِخْتِلَافًا كَثِيْرًا، فَعَلَيْكُمْ بِسُنَّتِيْ وَ سُنَّةِ الْخُلَفَاءِ الرَّاشِدِيْنَ الْمَهْدِيّيْنَ، فَتَمَسَّكُوْا بِهَا وَ عَضُّوْا عَلَيْهَا بِالنَّوَاجِذِ، وَ اِيَّاكُمْ وَ مُحْدَثَاتِ الْاُمُوْرِ، فَاِنَّ كُلَّ مُحْدَثَةٍ بِدْعَةٌ وَ كُلَّ بِدْعَةٍ ضَلَالَةٌ. احمد 6: 83، رقم: 17145"],["p","Dari ‘Irbadl bin Sariyah RA, ia berkata : Rasulullah SAW bersabda, “Saya berpesan kepada kamu sekalian, hendaklah kamu sekalian bertaqwa kepada Allah, mendengar dan thaat, sekalipun (yang menjadi pemimpin) budak Habsyiy, karena sesungguhnya orang yang hidup diantara kamu sekalian sesudahku akan melihat perselisihan yang banyak, maka dari itu hendaklah kamu sekalian (berpegang) pada sunnahku dan sunnah para khalifah yang lurus lagi menetapi petunjuk yang benar, berpegang teguhlah padanya dan gigitlah dengan gigi geraham. Dan jauhkanlah kalian dari perkara-perkara yang diada-adakan, karena sesungguhnya tiap-tiap perkara yang diada-adakan itu bid’ah, dan tiap-tiap bid’ah itu sesat”. [HR. Ahmad juz 6, hal. 83, no. 17145]"],["a","عَنْ عَبْدِ اللهِ بْنِ مَسْعُوْدٍ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اِنَّمَا هُمَا اثْنَتَانِ الْكَلَامُ وَ الْهَدْيُ فَاَحْسَنُ الْكَلَامِ كَلَامُ اللهِ وَ اَحْسَنُ الْهَدْيِ هَدْيُ مُحَمَّدٍ. اَلَا وَ اِيَّاكُمْ وَ مُحْدَثَاتِ الْاُمُوْرِ فَاِنَّ شَرَّ الْاُمُوْرِ مُحْدَثَاتُهَا وَ كُلَّ مُحْدَثَةٍ بِدْعَةٌ وَ كُلَّ بِدْعَةٍ ضَلَالَةٌ. ابن ماجه 1: 18، رقم: 46"],["p","Dari ‘Abdullah bin Mas’ud bahwasanya Rasulullah SAW bersabda, “Sesungguhnya ada dua perkara (yang penting), yaitu perkataan dan petunjuk. Maka sebaik-baik perkataan ialah firman Allah, dan sebaik-baik petunjuk ialah petunjuk Muhammad. Ketahuilah, jauhkanlah kalian dari perkara yang diada-adakan, karena sesungguhnya sejelek-jelek perkara itu yang diada-adakan, dan tiap-tiap yang diada-adakan itu bid’ah, dan tiap-tiap bid’ah itu sesat”. [HR. Ibnu Majah juz 1, hal. 18, no. 46]"],["a","عَنْ اَبِيْ هُرَيْرَةَ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: كُلُّ اُمَّتِيْ يَدْخُلُوْنَ الْجَنَّةَ اِلَّا مَنْ اَبَى. قَالُوْا: يَا رَسُوْلَ اللهِ، وَ مَنْ يَأْبَى؟ قَالَ: مَنْ اَطَاعَنِيْ دَخَلَ الْجَنَّةَ وَ مَنْ عَصَانِيْ فَقَدْ اَبَى. البخارى 8: 139"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Sesungguhnya semua ummatku akan masuk surga, kecuali orang yang tidak mau”. Para shahabat bertanya, “Ya Rasulullah, siapakah orang yang tidak mau itu ?”. Beliau SAW bersabda, “Barangsiapa yang menthaatiku, ia pasti masuk surga, dan barangsiapa yang mendurhakaiku, maka berarti ia tidak mau”. [HR. Bukhari juz 8, hal. 139]"],["p","Bid’ah dan bahayanya"],["a","عَنْ عَائِشَةَ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ اَمْرُنَا فَهُوَ رَدٌّ. مسلم 3: 1344"],["p","Dari ‘Aisyah bahwasanya Rasulullah SAW bersabda, “Barangsiapa yang melakukan suatu amalan yang bukan perintah kami, maka ia tertolak”. [HR. Muslim juz 3, hal. 1344]"],["a","عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُوْلُ اللهِ ﷺ : مَنْ اَحْدَثَ فِى اَمْرِنَا هٰذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ. مسلم 3: 1343"],["p","Dari ‘Aisyah, ia berkata : Rasulullah SAW bersabda, “Barangsiapa mengada-adakan dalam perintah kami ini, apa-apa yang bukan dari padanya, maka ia tertolak”. [HR. Muslim juz 3, hal. 1343]"],["a","عَنْ اَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : مَنْ رَغِبَ عَنْ سُنَّتِيْ فَلَيْسَ مِنّيْ. مسلم 2: 1020"],["p","Dari Anas RA, ia berkata : Rasulullah SAW bersabda, “Barangsiapa yang membenci sunnahku, maka ia bukan dari golonganku”. [HR. Muslim juz 2, hal. 1020]"],["a","عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اَبَى اللهُ اَنْ يَقْبَلَ عَمَلَ صَاحِبِ بِدْعَةٍ حَتَّى يَدَعَ بِدْعَتَهُ. ابن ماجه 1: 19، رقم: 50"],["p","Dari ‘Abdullah bin ‘Abbas, ia berkata : Rasulullah SAW bersabda, “Allah tidak mau menerima amal orang ahli bid’ah sehingga ia meninggalkan bid’ahnya”. [HR. Ibnu Majah juz 1, hal. 19, no. 50, dla’if karena dalam sanadnya ada perawi yang bernama Abu Zaid dan Abu Mughirah, keduanya majhul]"],["a","عَنْ حُذَيْفَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : لَا يَقْبَلُ اللهُ لِصَاحِبِ بِدْعَةٍ صَوْمًا وَ لَا صَلَاةً وَ لَا صَدَقَةً وَ لَا حَجًّا وَ لَا عُمْرَةً وَ لَا جِهَادًا وَ لَا صَرْفًا وَ لَا عَدْلًا. يَخْرُجُ مِنَ الْاِسْلَامِ كَمَا تَخْرُجُ الشَّعَرَةُ مِنَ الْعَجِيْنِ. ابن ماجه 1: 19، رقم: 49"],["p","Dari Hudzaifah, ia berkata : Rasulullah SAW bersabda, “Allah tidak mau menerima dari orang ahli bid’ah akan puasanya, shalatnya, shadaqahnya, hajjinya, ‘umrahnya, jihadnya, taubatnya dan tidak pula tebusannya, ia telah keluar dari Islam seperti keluarnya sehelai rambut dari adonan tepung”. [HR. Ibnu Majah juz 1, hal. 19, no. 49, dla’if karena dalam sanadnya ada perawi yang bernama Muhammad bin Mihshan, ia pendusta]"],["a","عَنِ الْحَكَمِ بْنِ عُمَيْرٍ الثِّمَالِيِّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اَلْاَمْرُ الْمُفْظِعُ وَ الْحِمْلُ الْمُضْلِعُ وَ الشَّرُّ الَّذِى لَا يَنْقَطِعُ اِظْهَارُ الْبِدَعِ. الطبرانى، فى الكبير 3: 219، رقم: 3194"],["p","Dari Al-Hakam bin ‘Umair Ats-Tsimaliy, ia berkata : Rasulullah SAW bersabda, “Perkara yang sangat jelek, dan beban yang amat berat, dan perbuatan jahat yang tidak ada putusnya ialah menampakkan perbuatan- perbuatan bid’ah”. [HR. Thabrani dalam Al-Kabir juz 3, hal. 219, no. 3194, dla’if karena dalam sanadnya ada perawi yang bernama Baqiyah bin Walid, ia didlo'ifkan oleh Imam Al-Haitsamiy]"],["a","عَنْ عَبْدِ اللهِ قَالَ: قَالَ النَّبِيُّ ﷺ: اَنَا فَرَطُكُمْ عَلَى الْحَوْضِ لَيُرْفَعَنَّ اِلَيَّ رِجَالٌ مِنْكُمْ حَتَّى اِذَا اَهْوَيْتُ لِاُنَاوِلَهُمُ اخْتُلِجُوْا دُوْنِيْ فَاَقُوْلُ أَيْ رَبِّ اَصْحَابِيْ فَيَقُوْلُ: لَا تَدْرِى مَا اَحْدَثُوْا بَعْدَكَ. البخارى 8: 87"],["p","Dari Abdullah (bin Mas’ud), ia berkata : Rasulullah SAW bersabda, Aku adalah pendahulu kamu di telaga (haudl). Sungguh ada orang-orang diantara kalian yang diangkat kepadaku, sehingga ketika aku mengulurkan (tangan) untuk menjangkau mereka, maka mereka ditarik dariku. Lalu aku berseru, “Wahai Tuhanku, mereka itu ummatku”. Maka Allah berfirman, “Kamu tidak tahu apa yang mereka lakukan sesudahmu”. [HR. Bukhari juz 8, hal. 87]"],["p","Ummat Islam akan mengikuti jejak orang-orang dahulu"],["a","عَنْ اَبِيْ سَعِيْدِ الْخُدْرِيّ عَنِ النَّبِيّ ﷺ قَالَ: لَتَتْبَعُنَّ سُنَنَ مَنْ كَانَ قَبْلَكُمْ شِبْرًا شِبْرًا وَ ذِرَاعًا بِذِرَاعٍ حَتَّى لَوْ دَخَلُوْا جُحْرَ ضَبٍّ تَبِعْتُمُوْهُمْ. قُلْنَا: يَا رَسُوْلَ اللهِ، آلْيَهُوْدُ وَ النَّصَارَى؟ قَالَ: فَمَنْ؟ البخارى 8: 151"],["p","Dari Abu Sa’id Al-Khudriy, dari Nabi SAW, beliau bersabda, “Sungguh kalian akan mengikuti langkah orang-orang sebelum kalian, sejengkal demi sejengkal dan sehasta demi sehasta, sehingga walaupun mereka memasuki lubang biawak, kalian tetap mengikutinya”. Kami (shahabat) bertanya, “Ya Rasulullah, apakah mereka itu kaum Yahudi dan Nashrani ?”. Beliau bersabda, “Lalu, siapa lagi ?”. [HR. Bukhari juz 8, hal. 151]"],["a","عَنْ اَبِيْ سَعِيْدِ الْخُدْرِيِّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : لَتَتْبَعُنَّ سُنَنَ الَّذِيْنَ مِنْ قَبْلِكُمْ شِبْرًا بِشِبْرٍ وَ ذِرَاعًا بِذِرَاعٍ حَتَّى لَوْ دَخَلُوْا فِي جُحْرِ ضَبٍّ لَاتَّبَعْتُمُوْهُمْ. قُلْنَا: يَا رَسُوْلَ اللهِ، آلْيَهُوْدُ وَ النَّصَارَى؟ قَالَ: فَمَنْ؟ مسلم 4: 2054"],["p","Dari Abu Sa’id Al-Khudriy, ia berkata : Rasulullah SAW bersabda, “Sungguh kalian akan mengikuti langkah orang-orang sebelum kalian, sejengkal demi sejengkal dan sehasta demi sehasta, sehingga walaupun mereka memasuki lubang biawak, kalian tetap mengikutinya”. Kami (shahabat) bertanya, “Ya Rasulullah, apakah mereka itu kaum Yahudi dan Nashrani ?”. Beliau bersabda, “Lalu, siapa lagi ?”. [HR. Muslim juz 4, hal. 2054]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : لَتَتَّبِعُنَّ سُنَّةَ مَنْ كَانَ قَبْلَكُمْ بَاعًا بِبَاعٍ، وَ ذِرَاعًا بِذِرَاعٍ وَ شِبْرًا بِشِبْرٍ حَتَّى لَوْ دَخَلُوْا فِى جُحْرِ ضَبٍّ لَدَخَلْتُمْ فِيْهِ. قَالُوْا: يَا رَسُوْلَ اللهِ، آلْيَهُوْدُ وَ النَّصَارَى؟ قَالَ: فَمَنْ اِذًا. ابن ماجه 2: 1322، رقم: 3994"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Sungguh kalian akan mengikuti langkah orang-orang sebelum kalian, sedepa demi sedepa, sehasta demi sehasta, sejengkal demi sejengkal, sehingga walaupun mereka memasuki lubang biawak, kalian akan memasukinya juga”. Para shahabat bertanya, “Ya Rasulullah, apakah mereka itu Yahudi dan Nashrani ?”. Beliau menjawab, “Siapa lagi kalau bukan mereka ?”. [HR. Ibnu Majah juz 2, hal. 1322, no. 3994]"],["p","Penegak Sunnah akan selalu ada sepanjang masa"],["a","عَنْ ثَوْبَانَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : لَا تَزَالُ طَائِفَةٌ مِنْ اُمَّتِيْ ظَاهِرِيْنَ عَلَى الْحَقِّ. لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ حَتَّى يَأْتِيَ اَمْرُ اللهِ وَ هُمْ كَذٰلِكَ. مسلم 3: 1523، رقم: 170"],["p","Dari Tsauban, ia berkata : Rasulullah SAW bersabda, “Akan selalu ada segolongan dari ummatku yang menampakkan kebenaran. Tidak akan memudlaratkan kepada mereka orang yang menentangnya, sehingga Allah mendatangkan perintah-Nya, sedangkan mereka tetap demikian itu”. [HR. Muslim juz 3, hal. 1523, no. 170]"],["a","عَنْ مُعَاوِيَةَ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: لَا تَزَالُ طَائِفَةٌ مِنْ اُمَّتِيْ قَائِمَةً بِاَمْرِ اللهِ لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ اَوْ خَالَفَهُمْ حَتَّى يَأْتِيَ اَمْرُ اللهِ وَ هُمْ ظَاهِرُوْنَ عَلَى النَّاسِ. مسلم 3: 1524 رقم 174"],["p","Dari Mu’awiyah, ia berkata : Aku mendengar Rasulullah SAW bersabda, “Selalu ada segolongan dari ummatku yang menegakkan perintah Allah, tidak akan memudlaratkan kepada mereka orang yang menentangnya atau menyelisihinya, sehingga datang keputusan Allah dan mereka tetap ada di tengah-tengah manusia”. [HR. Muslim juz 3, hal. 1524, no. 174]"],["a","عَنْ عَبْدِ اللهِ بْنِ مَسْعُوْدٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اِنَّ الْاِسْلَامَ بَدَأَ غَرِيْبًا وَ سَيَعُوْدُ غَرِيْبًا كَمَا بَدَأَ فَطُوْبَى لِلْغُرَبَاءِ. الترمذى 4: 129"],["p","Dari ‘Abdullah bin Mas’ud, ia berkata : Rasulullah SAW bersabda, “Sesungguhnya Islam itu bermula asing, dan akan kembali asing sebagaimana semula, maka berbahagialah orang-orang yang asing”. [HR. Tirmidzi juz 4, hal. 129, no. 2764]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : بَدَأَ الْاِسْلَامُ غَرِيْبًا وَ سَيَعُوْدُ كَمَا بَدَأَ غَرِيْبًا فَطُوْبَى لِلْغُرَبَاءِ. مسلم 1: 130"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, “Islam itu bermula asing, dan akan kembali asing sebagaimana semula asing. Maka berbahagialah bagi orang-orang yang asing”. [HR Muslim juz 1, hal. 130]"],["a","عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ : اِنَّ الْاِسْلَامَ بَدَأَ غَرِيْبًا وَ سَيَعُوْدُ غَرِيْبًا فَطُوْبَى لِلْغُرَبَاءِ. قَالُوْا: يَا رَسُوْلَ اللهِ، وَ مَا الْغُرَبَاءُ ؟ قَالَ: اَلَّذِيْنَ يُصْلِحُوْنَ عِنْدَ فَسَادِ النَّاسِ. الطبرانى فى المعجام الكبير 6: 164، رقم: 5867"],["p","Dari Sahl bin Sa’d As-Saa’idiy, ia berkata : Rasulullah SAW bersabda, “Sesungguhnya Islam itu bermula asing, dan akan kembali asing, maka berbahagialah orang-orang yang asing”. Para shahabat bertanya, “Siapakah orang yang asing itu ya Rasulullah ?”. Beliau bersabda, “Yaitu orang-orang yang memperbaiki ketika manusia dalam keadaan rusak”. [HR. Thabarani dalam Al Mu’jamu Al-Kabir juz 6, hal. 164, no. 5867]"],["p","--oo0oo--"]],"c20221225_1311":[["p","Ahad, 25 Desember 2022/ 1 Jumaadal Aakhirah 1444 Brosur No.: 2106/2146/IA"],["p","Muhaasabah"],["p","Kaum muslimin dan muslimat rahimakumullah, di penghujung tahun ini mengingatkan kita akan semakin bertambahnya umur kita, tetapi pada hakikatnya kesempatan hidup kita di dunia ini semakin berkurang, yang berarti pula kita semakin dekat dengan qubur."],["p","Allah SWT senantiasa mencurahkan ni'mat-Nya kepada kita dengan bermacam-macam ni'mat yang banyak sekali, yang sungguh kita tidak mungkin bisa menghitungnya. Allah SWT berfirman :"],["a","وَاِنْ تَعُدُّوْا نِعْمَتَ اللّٰهِ لَا تُحْصُوْهَا . ابرهيم: 34"],["p","Dan jika kamu menghitung-hitung ni'mat Allah, niscaya kamu tidak dapat menghitungnya. [QS. Ibrahim : 34]"],["p","Diantara sekian banyak ni'mat Allah yang dicurahkan kepada kita ialah kita hidup di dunia ini. Dunia memang indah, sangat menarik, akan tetapi jangan sampai keindahan dunia ini membuat kita lupa kepada Allah, Tuhan yang telah menciptakan segalanya. Allah SWT berfirman :"],["a","اِعْلَمُوْٓا اَنَّمَا الْحَيٰوةُ الدُّنْيَا لَعِبٌ وَّلَهْوٌ وَّزِيْنَةٌ وَّتَفَاخُرٌ ۢبَيْنَكُمْ وَتَكَاثُرٌ فِى الْاَمْوَالِ وَالْاَوْلَادِۗ كَمَثَلِ غَيْثٍ اَعْجَبَ الْكُفَّارَ نَبَاتُهٗ ثُمَّ يَهِيْجُ فَتَرٰىهُ مُصْفَرًّا ثُمَّ يَكُوْنُ حُطَامًاۗ وَفِى الْاٰخِرَةِ عَذَابٌ شَدِيْدٌۙ وَّمَغْفِرَةٌ مِّنَ اللّٰهِ وَرِضْوَانٌ ۗ وَمَا الْحَيٰوةُ الدُّنْيَآ اِلَّا مَتَاعُ الْغُرُوْرِ . الحديد: 20"],["p","Ketahuilah, bahwa sesungguhnya kehidupan dunia itu hanyalah permainan dan suatu yang melalaikan, perhiasan dan bermegah-megah antara kamu serta berbangga-bangga tentang banyaknya harta dan anak, seperti hujan yang tanam-tanamannya mengagumkan para petani; kemudian tanaman itu menjadi kering dan kamu lihat warnanya kuning kemudian menjadi hancur. Dan di akhirat (nanti) ada adzab yang keras dan ampunan dari Allah serta keridlaan-Nya. Dan kehidupan dunia ini tidak lain hanyalah kesenangan yang menipu. [QS. Al-Hadiid : 20]"],["a","زُيِّنَ لِلنَّاسِ حُبُّ الشَّهَوٰتِ مِنَ النِّسَاۤءِ وَالْبَنِيْنَ وَالْقَنَاطِيْرِ الْمُقَنْطَرَةِ مِنَ الذَّهَبِ وَالْفِضَّةِ وَالْخَيْلِ الْمُسَوَّمَةِ وَالْاَنْعَامِ وَالْحَرْثِ ۗ ذٰلِكَ مَتَاعُ الْحَيٰوةِ الدُّنْيَا ۗ وَاللّٰهُ عِنْدَهٗ حُسْنُ الْمَاٰبِ (14) قُلْ اَؤُنَبِّئُكُمْ بِخَيْرٍ مِّنْ ذٰلِكُمْ ۗ لِلَّذِيْنَ اتَّقَوْا عِنْدَ رَبِّهِمْ جَنّٰتٌ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَا وَاَزْوَاجٌ مُّطَهَّرَةٌ وَّرِضْوَانٌ مِّنَ اللّٰهِ ۗ وَاللّٰهُ بَصِيْرٌ ۢبِالْعِبَادِ (15) ال عمران: 14-15"],["p","Dijadikan indah pada (pandangan) manusia kecintaan kepada apa-apa yang diingini, yaitu: wanita-wanita, anak-anak, harta yang banyak dari jenis emas, perak, kuda pilihan, binatang-binatang ternak dan sawah ladang. Itulah kesenangan hidup di dunia, dan di sisi Allah-lah tempat kembali yang baik (surga). (14)"],["p","Katakanlah, \"Inginkah aku khabarkan kepadamu apa yang lebih baik dari yang demikian itu ? . Untuk orang-orang yang bertaqwa (kepada Allah), pada sisi Tuhan mereka ada surga yang mengalir di bawahnya sungai-sungai; mereka kekal di dalamnya. Dan (mereka dikaruniai) istri-istri yang disucikan serta keridlaan Allah. Dan Allah Maha Melihat akan hamba-hamba-Nya.” [QS. Ali 'Imraan : 14-15]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ اَبِيْ سَعِيْدٍ الْخُدْرِيِّ عَنِ النَّبِيِّ ﷺ قَالَ: اِنَّ الدُّنْيَا حُلْوَةٌ خَضِرَةٌ، وَاِنَّ اللهَ مُسْتَخْلِفُكُمْ فِيْهَا، فَيَنْظُرُ كَيْفَ تَعْمَلُوْنَ، فَاتَّقُوا الدُّنْيَا وَاتَّقُوا النِّسَاءَ، فَاِنَّ اَوَّلَ فِتْنَةِ بَنِيْ اِسْرَائِيْلَ كَانَتْ فِى النِّسَاءِ. مسلم 4: 2098 رقم 99"],["p","Dari Abu Sa'id Al-Khudriy, dari Nabi SAW, beliau bersabda, \"Sesungguhnya dunia itu manis dan indah, dan sesungguhnya Allah menjadikan kalian untuk mengelolanya, maka Allah akan melihat bagaimana yang kalian perbuat (berbuat tha'at kepada Allah atau berbuat ma'shiyat). Maka hati-hatilah kalian terhadap dunia, dan hati-hatilah terhadap wanita, karena pertama-tama fitnah yang terjadi di kalangan Bani Israil adalah karena wanita\". [HR. Muslim juz 4, hal. 2098, no. 99]"],["a","عَنْ سَعِيْدِ بْنِ الْمُسَيَّبِ اَنَّ اَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ سَمِعْتُ رَسُوْلَ اللهِ ﷺ يَقُوْلُ: لَا يَزَالُ قَلْبُ الْكَبِيْرِ شَابًّا فِي اثْنَتَيْنِ، فِيْ حُبِّ الدُّنْيَا وَطُوْلِ الْأَمَلِ. البخارى 7: 171"],["p","Dari Sa'id bin Al-Musayyab, bahwasanya Abu Hurairah RA berkata, \"Aku mendengar Rasulullah SAW bersabda, \"Senantiasalah hati orang tua menjadi muda untuk mendapatkan dua keinginan, yaitu cinta dunia dan tingginya keinginan\". [HR. Bukhari juz 7, hal. 171]"],["a","عَنْ عَبَّاسِ بْنِ سَهْلِ بْنِ سَعْدٍ قَالَ: سَمِعْتُ ابْنَ الزُّبَيْرِ عَلَى الْمِنْبَرِ بِـمَكَّةَ فِيْ خُطْبَتِهِ يَقُوْلُ: يَا اَيُّهَا النَّاسُ، اِنَّ النَّبِيَّ ﷺ كَانَ يَقُوْلُ: لَوْ اَنَّ ابْنَ آدَمَ اُعْطِيَ وَادِيًا مَلْأً مِنْ ذَهَبٍ اَحَبَّ اِلَيْهِ ثَانِيًا وَلَوْ اُعْطِيَ ثَانِيًا اَحَبَّ اِلَيْهِ ثَالِثًا وَلَا يَسُدُّ جَوْفَ ابْنِ آدَمَ اِلَّا التُّرَابُ، وَيَتُوْبُ اللهُ عَلَى مَنْ تَابَ. البخارى 7: 175"],["p","Dari 'Abbas bin Sahl bin Sa'ad, ia berkata : Aku mendengar Ibnuz Zubair berkhutbah di atas mimbar di Makkah, ia berkata : Wahai para manusia, sesungguhnya Nabi SAW bersabda, \"Seandainya anak Adam diberi kekayaan harta satu lembah penuh berupa emas, tentu ia masih menginginkan lembah yang kedua, dan seandainya ia diberi dua lembah emas, tentu ia masih menginginkan lembah yang ketiga, dan tidak ada yang menutup perut anak Adam kecuali tanah. Dan Allah akan menerima taubatnya orang yang mau bertaubat\". [HR Bukhari juz 7, hal. 175]"],["p","Dunia memang indah dan sangat menarik, tetapi sifatnya hanya sementara, hanya seperti permainan yang tidak lama kemudian akan selesai, dan yang ada tinggal lelahnya. Atau seperti senda gurau yang membuat orang menjadi lupa kepada kewajibannya. Maka banyak orang yang terpedaya dengan keindahan dunia, sehingga membanggakan keturunannya, banyaknya harta dan anak, banyak pendukung dan anak buah, tingginya pangkat dan jabatan, dan lain sebagainya, padahal semuanya itu akan sirna, tak ubahnya seperti tanaman yang subur yang menyenangkan orang yang melihatnya, tetapi tidak lama kemudian tanaman itu akan kering, menjadi kuning dan akhirnya akan hancur."],["p","Itulah gambaran kesenangan hidup di dunia yang indah ini, maka jangan sampai kita terlena hanya mengutamakan kesenangan dunia sehingga melupakan akhirat, karena kesenangan di dunia ini hanya kesenangan yang sedikit apabila dibandingkan dengan kesenangan di akhirat. Allah SWT berfirman :"],["a","لَا يَغُرَّنَّكَ تَقَلُّبُ الَّذِيْنَ كَفَرُوْا فِى الْبِلَادِۗ (196) مَتَاعٌ قَلِيْلٌ ۗ ثُمَّ مَأْوٰىهُمْ جَهَنَّمُ ۗ وَبِئْسَ الْمِهَادُ(197) لٰكِنِ الَّذِيْنَ اتَّقَوْا رَبَّهُمْ لَهُمْ جَنّٰتٌ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَا نُزُلًا مِّنْ عِنْدِ اللّٰهِ ۗ وَمَا عِنْدَ اللّٰهِ خَيْرٌ لِّلْاَبْرَارِ (198) ال عمران: 196-198"],["p","Janganlah sekali-kali kamu terperdaya oleh kebebasan orang-orang kafir bergerak di dalam negeri. (196)"],["p","Itu hanyalah kesenangan sementara, kemudian tempat tinggal mereka ialah Jahannam; dan Jahannam itu adalah tempat yang seburuk-buruknya. (197)"],["p","Akan tetapi orang-orang yang bertaqwa kepada Tuhan-nya bagi mereka surga yang mengalir sungai-sungai di dalamnya, sedang mereka kekal di dalamnya, sebagai tempat tinggal (anugerah) dari sisi Allah. Dan apa yang di sisi Allah adalah lebih baik bagi orang-orang yang berbakti. (198) [QS. Ali 'Imraan : 196-198]"],["p","Di dalam hadits juga disebutkan :"],["a","عَنْ قَيْسٍ قَالَ: سَمِعْتُ مُسْتَوْرِدًا اَخَا بَنِيْ فِهْرٍ يَقُوْلُ: قَالَ رَسُوْلُ اللهِ ﷺ: وَاللهِ، مَا الدُّنْيَا فِى اْلاٰخِرَةِ اِلَّا مِثْلُ مَا يَجْعَلُ اَحَدُكُمْ اِصْبَعَهُ هٰذِهِ (وَاَشَارَ يَحْيَى بِالسَّبَّابَةِ) فِى الْيَمِّ فَلْيَنْظُرْ بِـمَ يَرْجِعُ. مسلم 4: 2193"],["p","Dari Qais, ia berkata : Aku mendengar Mustaurid saudara dari Bani Fihr berkata : Rasulullah SAW bersabda, \"Demi Allah, tidaklah kehidupan dunia ini jika dibandingkan dengan kehidupan akhirat, kecuali seperti salah seorang diantara kalian memasukkan jarinya ini ke dalam laut. (Yahya (perawi) sambil menunjukkan jari telunjuknya), maka lihatlah seberapa air yang menetes kembali\". [HR. Muslim juz 4, hal. 2193, no. 55]"],["a","عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَوْ كَانَتِ الدُّنْيَا تَعْدِلُ عِنْدَ اللهِ جَنَاحَ بَعُوْضَةٍ مَا سَقَى كَافِرًا مِنْهَا شَرْبَةَ مَاءٍ. الترمذى 3: 383، رقم: 2422"],["p","Dari Sahl bin Sa'ad, ia berkata : Rasulullah SAW bersabda, \"Seandainya dunia ini di sisi Allah ada nilainya sesayap nyamuk, niscaya Allah tidak akan memberi minum kepada orang kafir walaupun seteguk air\". [HR. Tirmidzi juz 3, hal. 383, no. 2422]"],["p","Oleh sebab itu keni'matan yang telah diberikan oleh Allah kepada kita hendaklah kita syukuri. Allah SWT berfirman :"],["a","لَىِٕنْ شَكَرْتُمْ لَاَزِيْدَنَّكُمْ وَلَىِٕنْ كَفَرْتُمْ اِنَّ عَذَابِيْ لَشَدِيْدٌ . ابرهيم: 7"],["p","Sesungguhnya jika kamu bersyukur, pasti Kami akan menambah (ni'mat) kepadamu, dan jika kamu mengingkari (ni'mat-Ku), maka sesungguhnya adzab-Ku sangat pedih. [QS. Ibrahim : 7]"],["a","عَنْ اَبِيْ هُرَيْرَةَ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: اُنْظُرُوْا اِلَى مَنْ هُوَ اَسْفَلَ مِنْكُمْ، وَلَا تَنْظُرُوْا اِلَى مَنْ هُوَ فَوْقَكُمْ، فَاِنَّهُ اَجْدَرُ اَنْ لَا تَزْدَرُوْا نِعْمَةَ اللهِ عَلَيْكُمْ. ابن ماجه 2: 1387، رقم: 4142"],["p","Dari Abu Hurairah, ia berkata : Rasulullah SAW bersabda, \"Lihatlah kepada yang di bawah kalian, dan janganlah kalian melihat kepada orang yang di atas kalian. Karena yang demikian itu lebih pantas agar kalian tidak meremehkan ni'mat Allah yang telah diberikan kepada kalian\". [HR. Ibnu Majah juz 2, hal. 1387, no. 4142]"],["p","Hidup di dunia ini tidak lama, waktunya terbatas, dan semua manusia akan mati, baik dengan sebab sakit, atau sebab-sebab lainnya. Dan apabila telah tiba saatnya, maka kematian pasti akan menemui kita. Allah SWT berfiman :"],["a","قُلْ اِنَّ الْمَوْتَ الَّذِيْ تَفِرُّوْنَ مِنْهُ فَاِنَّهٗ مُلٰقِيْكُمْ ثُمَّ تُرَدُّوْنَ اِلٰى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُوْنَ . الجمعة: 8"],["p","Katakanlah, \"Sesungguhnya kematian yang kamu lari daripadanya, maka sesungguhnya kematian itu akan menemui kamu, kemudian kamu akan dikembalikan kepada (Allah), yang mengetahui yang ghaib dan yang nyata, lalu Dia beritakan kepadamu apa yang telah kamu kerjakan\". [QS. Al-Jumu'ah : 8]"],["a","اَيْنَمَا تَكُوْنُوْا يُدْرِكْكُّمُ الْمَوْتُ وَلَوْ كُنْتُمْ فِيْ بُرُوْجٍ مُّشَيَّدَةٍ . النساء: 78"],["p","Di mana saja kamu berada, kematian akan mendapatkan kamu, kendati pun kamu di dalam benteng yang tinggi lagi kokoh. [QS. An-Nisaa' : 78]"],["a","كُلُّ نَفْسٍ ذَاۤىِٕقَةُ الْمَوْتِۗ وَاِنَّمَا تُوَفَّوْنَ اُجُوْرَكُمْ يَوْمَ الْقِيٰمَةِ ۗ فَمَنْ زُحْزِحَ عَنِ النَّارِ وَاُدْخِلَ الْجَنَّةَ فَقَدْ فَازَ ۗ وَمَا الْحَيٰوةُ الدُّنْيَآ اِلَّا مَتَاعُ الْغُرُوْرِ . ال عمران: 185"],["p","Tiap-tiap yang berjiwa akan merasakan mati. Dan sesungguhnya pada hari qiyamat sajalah disempurnakan pahalamu. Barangsiapa dijauhkan dari neraka dan dimasukkan ke dalam surga, maka sungguh ia telah beruntung. Kehidupan dunia itu tidak lain hanyalah kesenangan yang memperdayakan. [QS. Ali 'Imraan : 185]"],["a","وَلِكُلِّ اُمَّةٍ اَجَلٌۚ فَاِذَا جَاۤءَ اَجَلُهُمْ لَا يَسْتَأْخِرُوْنَ سَاعَةً وَّلَا يَسْتَقْدِمُوْنَ . الاعراف: 34"],["p","Tiap-tiap ummat mempunyai batas waktu; maka apabila telah datang waktunya, mereka tidak dapat mengundurkannya barang sesaat pun dan tidak dapat (pula) memajukannya. [QS. Al-A'raaf : 34]"],["p","Dan apabila manusia meninggal dunia, akan diantar oleh tiga hal, yang dua akan kembali, sedangkan yang satu akan terus menemaninya. Di dalam hadits disebutkan :"],["a","عَنْ اَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: يَتْبَعُ الْمَيِّتَ ثَلَاثَةٌ، فَيَرْجِعُ اثْنَانِ وَيَبْقَى وَاحِدٌ. يَتْبَعُهُ اَهْلُهُ وَمَالُهُ وَعَمَلُهُ، فَيَرْجِعُ اَهْلُهُ وَمَالُهُ، وَيَبْقَى عَمَلُهُ. مسلم 4: 2273 رقم 5"],["p","Dari Anas bin Maalik, ia berkata : Rasulullah SAW bersabda, \"Ada tiga hal yang mengikuti mayyit, yang dua akan kembali, sedangkan yang satu tetap menemaninya. Yang mengikutinya adalah keluarganya, hartanya dan amalnya. Lalu keluarganya dan hartanya akan kembali, sedangkan amalnya akan tetap menemaninya\". [HR. Muslim juz 4, hal. 2273, no. 5]"],["p","Oleh sebab itu marilah sisa umur dan kesempatan yang masih diberikan oleh Allah, kita gunakan sebaik-baiknya untuk bertaubat kepada Allah dan menambah amal kebaikan untuk bekal hidup kita di ahirat kelak."],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ لِرَجُلٍ وَهُوَ يَعِظُهُ: اِغْتَنِمْ خَمْسًا قَبْلَ خَمْسٍ: شَبَابَكَ قَبْلَ هَرَمِكَ، وَصِحَّتَكَ قَبْلَ سَقَمِكَ، وَغِنَاكَ قَبْلَ فَقْرِكَ، وَفَرَاغَكَ قَبْلَ شُغْلِكَ، وَحَيَاتَكَ قَبْلَ مَوْتِكَ. البيهقى فى شعب الايمان 7: 263، رقم: 10248"],["p","Dari Ibnu Abbas, ia berkata : Rasulullah SAW bersabda kepada seorang laki-laki, pada waktu itu beliau menasehatinya, “Gunakanlah lima (kesempatan) sebelum datangnya lima (kesempitan)"],["p","1. Gunakan masa mudamu sebelum datang masa tuamu,"],["p","2. Gunakan masa sehatmu sebelum datang masa sakitmu,"],["p","3. Gunaan masa kayamu sebelum datang masa faqir (miskin)mu,"],["p","4. Gunakan masa longgarmu sebelum datang masa sibukmu,"],["p","5. Gunakan masa hidupmu sebelum datang kematianmu”."],["p","[HR. Baihaqiy dalam Syu'abul iimaan juz 7, hal.263, no. 10248]"],["p","Dan sebaik-baik orang adalah yang panjang umurnya dan baik amalnya, sedangkan seburuk-buruk orang adalah yang panjang umurnya, tetapi jelek perbuatannya. Di dalam hadits disebutkan :"],["a","عَنْ عَبْدِ الرَّحْمٰنِ بْنِ اَبِيْ بَكْرَةَ عَنْ اَبِيْهِ، اَنَّ رَجُلًا قَالَ: يَا رَسُوْلَ اللهِ، اَيُّ النَّاسِ خَيْرٌ؟، قَالَ: مَنْ طَالَ عُمُرُهُ وَحَسُنَ عَمَلُهُ. قَالَ: فَاَيُّ النَّاسِ شَرٌّ؟ قَالَ: مَنْ طَالَ عُمُرُهُ وَسَاءَ عَمَلُهُ. الترمذى 3: 387، رقم: 2432، هذا حديث حسن صحيح."],["p","Dari 'Abdurrahman bin Abu Bakrah, dari ayahnya, bahwasanya ada seorang laki-laki bertanya, \"Ya Rasulullah, bagaimana orang yang paling baik itu ?\". Beliau bersabda, \"Orang yang panjang umurnya dan baik amalnya\". Lalu orang tersebut bertanya lagi, \"Lalu bagaimana orang yang paling buruk itu ?\". Beliau bersabda, \"Orang yang panjang umurnya, tetapi jelek amalnya\". [HR. Tirmidzi juz 3, hal. 387, no. 2432, ia berkata : Ini hadits hasan shahih]"],["p","Keni'matan yang diberikan oleh Allah kepada kita di dunia ini, di akhirat nanti akan dimintai pertanggungjawabannya oleh Allah. Allah SWT berfirman :"],["a","وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهٖ عِلْمٌ ۗ اِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ اُولٰۤىِٕكَ كَانَ عَنْهُ مَسْـُٔوْلًا . الاسراء: 36"],["p","Dan janganlah kamu mengikuti apa yang kamu tidak mempunyai pengetahuan tentangnya. Sesungguhnya pendengaran, penglihatan dan hati, semuanya itu akan diminta pertanggungan jawabnya. [QS. Al-Israa' : 36]"],["a","ثُمَّ لَتُسْـَٔلُنَّ يَوْمَىِٕذٍ عَنِ النَّعِيْمِ . التكاثر: 8"],["p","kemudian kamu pasti akan ditanyai pada hari itu tentang keni'matan (yang kamu megah-megahkan di dunia itu). [QS. At-Takaatsur : 8]"],["p","Di dalam hadits disebutkan :"],["a","عَنْ اَبِيْ بَرْزَةَ الْاَسْلَمِيِّ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: لَا تَزُوْلُ قَدَمَا عَبْدٍ حَتَّى يُسْأَلَ عَنْ عُمْرِهِ فِيْمَا اَفْنَاهُ، وَعَنْ عِلْمِهِ فِيْمَا فَعَلَ، وَعَنْ مَالِهِ مِنْ اَيْنَ اكْتَسَبَهُ وَفِيْمَا اَنْفَقَهُ، وَعَنْ جِسْمِهِ فِيْمَا اَبْلَاهُ. الترمذى 4: 36، رقم: 2532، هذا حديث حسن صحيح"],["p","Dari Abu Barzah Al-Aslamiy, ia berkata : Rasulullah SAW bersabda, “Tidaklah bergerak kedua tapak kaki seorang hamba (pada hari qiyamat), sehingga ia ditanya tentang umurnya untuk apa ia habiskan, tentang ilmunya untuk apa ia gunakan, tentang hartanya dari mana ia mendapatkannya dan untuk apa ia belanjakan, dan tentang badannya untuk apa ia gunakan”. [HR. Tirmidzi juz 4, hal. 36, no. 2532, ia berkata : Ini hadits hasan shahih]"],["p","Oleh karena itu marilah dengan datangnya tahun baru ini, kita gunakan untuk mengoreksi diri kita masing-masing untuk bermuhaasabah."],["a","حَاسِبُوْا اَنْفُسَكُمْ قَبْلَ اَنْ تُحَاسَبُوْا وَزِنُوْا اَنْفُسَكُمْ قَبْلَ اَنْ تُوْزَنُوْا."],["p","Hitung-hitunglah diri kalian sebelum (amal) kalian dihitung (oleh Allah), dan timbang-timbanglah (amal kalian) sebelum (amal) kalian ditimbang (oleh Allah)."],["p","Diriwayatkan bahwa 'Umar bin Khaththab pernah berpidato, dan diantara isi pidatonya itu beliau menganjurkan agar bermuhaasabah."],["a","عَنْ عُمَرَ ابْنِ الْخَطَّابِ اَنَّهُ قَالَ فِيْ خُطْبَتِهِ: حَاسِبُوْا اَنْفُسَكُمْ قَبْلَ اَنْ تُحَاسَبُوْا، وَزِنُوْا اَنْفُسَكُمْ قَبْلَ اَنْ تُوْزَنُوْا، وَتَزَيَّنُوْا لِلْعَرَضِ اْلاَكْبَرِ يَوْمَ تُعْرَضُوْنَ لَا يَخْفَى مِنْكُمْ خَافِيَةٌ. ابن ابى شيبة 7: 115، رقم: 34448"],["p","Dari 'Umar bin Khaththab, bahwasanya ia berkata di dalam pidatonya, \"Hitung-hitunglah diri kalian sebelum (amal) kalian dihitung (oleh Allah), timbang-timbanglah (amal) kalian sebelum (amal) kalian ditimbang (oleh Allah). Dan berhiaslah kalian untuk menyambut pertemuan agung pada hari kamu sekalian dihadapkan (kepada Allah) dan tidak ada sesuatupun dari kalian yang tersembunyi\". [HR. Ibnu Abi Syaibah juz 7, hal. 115, no. 34448]"],["p","Apabila kita enggan untuk mengoreksi diri dan bermuhaasabah, bukan tidak mungkin kita termasuk orang yang paling rugi, sebagaimana firman Allah :"],["a","قُلْ هَلْ نُنَبِّئُكُمْ بِالْاَخْسَرِيْنَ اَعْمَالًا ۗ (103) اَلَّذِيْنَ ضَلَّ سَعْيُهُمْ فِى الْحَيٰوةِ الدُّنْيَا وَهُمْ يَحْسَبُوْنَ اَنَّهُمْ يُحْسِنُوْنَ صُنْعًا (104) الكهف: 103-104"],["p","Katakanlah, \"Apakah akan Kami beritahukan kepadamu tentang orang-orang yang paling merugi perbuatannya? (103)"],["p","Yaitu orang-orang yang telah sia-sia perbuatannya dalam kehidupan dunia ini, sedangkan mereka menyangka bahwa mereka berbuat sebaik-baiknya.” (104) [QS. Al-Kahfi : 103-104]"],["p","Atau bahkan kita termasuk orang yang pailit, sebagaimana disebutkan dalam hadits :"],["a","عَنْ اَبِيْ هُرَيْرَةَ اَنَّ رَسُوْلَ اللهِ ﷺ قَالَ: اَتَدْرُوْنَ مَا الْمُفْلِسُ؟ قَالُوْا: اَلْمُفْلِسُ فِيْنَا مَنْ لَا دِرْهَمَ لَهُ وَلَا مَتَاعَ. فَقَالَ: اِنَّ الْمُفْلِسَ مِنْ اُمَّتِيْ يَأْتِيْ يَوْمَ الْقِيَامَةِ بِصَلَاةٍ وَصِيَامٍ وَزَكَاةٍ وَيَأْتِيْ قَدْ شَتَمَ هٰذَا، وَقَذَفَ هٰذَا، وَاَكَلَ مَالَ هٰذَا وَسَفَكَ دَمَ هٰذَا، وَضَرَبَ هٰذَا، فَيُعْطَى هٰذَا مِنْ حَسَنَاتِهِ، وَهٰذَا مِنْ حَسَنَاتِهِ، فَاِنْ فَنِيَتْ حَسَنَاتُهُ قَبْلَ اَنْ يُقْضَى مَا عَلَيْهِ اُخِذَ مِنْ خَطَايَاهُمْ فَطُرِحَتْ عَلَيْهِ ثُـمَّ طُرِحَ فِى النَّارِ. مسلم 4: 1997 رقم 59"],["p","Dari Abu Hurairah, bahwasanya Rasulullah SAW bersabda, \"Tahukah kalian siapakah orang yang disebut pailit itu ?\" Jawab para shahabat, \"Orang yang pailit diantara kami ialah orang yang tidak punya dirham dan tidak punya barang-barang\". Rasulullah SAW bersabda, \"Sesungguhnya orang yang pailit dari ummatku ialah orang yang datang pada hari qiyamat lengkap dengan membawa (pahala) shalatnya, puasanya dan zakatnya. Tetapi di samping itu ia telah mencaci ini, dan menuduh ini, memakan hartanya ini, dan menumpahkan darahnya ini, dan memukul ini, maka diberikan kepada orang yang dianiaya itu dari (pahala) kebaikan amalnya, dan kepada orang yang lainnya lagi (dari pahala) kebaikan amalnya. Maka apabila telah habis (pahala) kebaikannya itu dan belum terbayar semua tuntutan orang-orang yang pernah dianiaya tersebut, maka diambilkan dari dosa-dosa orang yang telah dianiaya itu dan ditanggungkan kepadanya, lalu ia dilemparkan ke neraka\". [HR. Muslim juz 4, hal 1997, no. 59]"],["p","Hidup di dunia ini hanya sebentar, dan hidup yang haqiqi adalah hidup di akhirat kelak. Allah SWT berfirman :"],["a","وَمَا هٰذِهِ الْحَيٰوةُ الدُّنْيَآ اِلَّا لَهْوٌ وَّلَعِبٌۗ وَاِنَّ الدَّارَ الْاٰخِرَةَ لَهِيَ الْحَيَوَانُۘ لَوْ كَانُوْا يَعْلَمُوْنَ . العنكبوت: 64"],["p","Dan tiadalah kehidupan dunia ini melainkan senda gurau dan main-main. Dan sesungguhnya akhirat itulah yang sebenarnya kehidupan, kalau mereka mengetahui. [QS. Al-'Ankabuut : 64]"],["p","Dan diriwayatkan, barangsiapa yang sudah berumur 40 tahun, kebaikannya belum bisa mengalahkan keburukannya, maka bersiap-siaplah masuk neraka."],["a","عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُوْلُ اللهِ ﷺ: مَنْ اَتَى عَلَيْهِ اَرْبَعُوْنَ سَنَةً فَلَمْ يَغْلِبْ خَيْرُهُ شَرَّهُ فَلْيَتَجَهَّزْ اِلَى النَّارِ. الموضوعات 1: 178"],["p","Dari Ibnu 'Abbas, ia berkata : Rasulullah SAW bersabda, \"Barangsiapa yang sudah mencapai umur 40 tahun, kebaikannya belum bisa mengalahkan keburukannya, maka hendaklah ia bersiap-siap masuk neraka\". [Al-Maudluu'aat oleh Imam Abul Faraj Abdur Rahman bin 'Aliy bin Al-Jauziy Al-Qurasyiy juz 1, hal. 178, hadits ini sangat dla'if, karena dalam sanadnya ada beberapa perawi yang dla'if, yaitu Robaah bin Ahmad; ia sangat dlaif. Adapun Jarir : para 'ulama hadits meninggalkan haditsnya. Dan Dlohhaak, ia tidak bertemu dengan Ibnu 'Abbas]"],["p","Dan Rasulullah SAW berpesan kepada kita supaya bertaqwa kepada Allah di mana saja kita berada."],["a","عَنْ اَبِيْ ذَرٍّ قَالَ: قَالَ لِيْ رَسُوْلُ اللهِ ﷺ: اِتَّقِ اللهَ حَيْثُمَا كُنْتَ، وَاَتْبِعِ السَّيِّئَةَ الْحَسَنَةَ تَـمْحُهَا، وَخَالِقِ النَّاسَ بِخُلُقٍ حَسَنٍ. الترمذى 3: 239، رقم: 2053، هذا حديث حسن صحيح"],["p","Dari Abu Dzarr, ia berkata : Rasulullah SAW bersabda kepadaku, \"Bertaqwalah kamu kepada Allah dimana saja kamu berada, dan ikutilah perbuatan buruk dengan perbuatan yang baik, niscaya perbuatan yang baik itu akan menghapusnya. Dan bergaullah dengan manusia dengan akhlaq yang baik\". [HR. Tirmidzi juz 3, hal. 239, no. 2053, Ini hadits hasan shahih]"],["p","Oleh karena itu marilah sisa umur yang masih diberikan oleh Allah SWT kepada kita ini, kita gunakan untuk meningkatkan iman dan taqwa kita kepada Alllah, karena hanya dengan iman dan taqwa itulah Allah menjauhkan manusia dari neraka dan memasukkan ke surga. Kita tingkatkan persatuan dan kerukunan sesama muslim, karena sesama muslim adalah bersaudara, dan kita jauhi berbantah, perselisihan, pertengkaran dan perpecahan, karena perpecahan itu akan melemahkan kekuatan kita. Allah SWT berfirman :"],["a","وَاَطِيْعُوا اللّٰهَ وَرَسُوْلَهٗ وَلَا تَنَازَعُوْا فَتَفْشَلُوْا وَتَذْهَبَ رِيْحُكُمْ وَاصْبِرُوْاۗ اِنَّ اللّٰهَ مَعَ الصّٰبِرِيْنَ . الانفال: 46"],["p","Dan tha'atlah kepada Allah dan Rasul-Nya dan janganlah kamu berbantah-bantahan, yang menyebabkan kamu menjadi gentar dan hilang kekuatanmu dan bershabarlah. Sesungguhnya Allah beserta orang-orang yang shabar. [QS. Al-Anfaal : 46]"],["p","Untuk melengkapi muhaasabah kita, marilah kita perhatikan beberapa pesan Al-Ustadz ‘Abdullah Thufail Saputro."],["p","Pesan Al-Ustadz ‘Abdullah Thufail Saputro (Pendiri MTA)"],["p","Mari pada akhir tahun ini kita evaluasi kepada diri kita masing masing."],["p","1. Kalau ternyata hasil evaluasi itu menunjukkan kemajuan di bidang duniawi tetapi merosot di bidang ukhrowi cepat cepatlah sadar sebelum terjadi penyesalan yang tidak berguna, perbaiki diri dan tingkatkan nilai nilai ukhrowi."],["p","2. Kalau nilai nilai ukhrowi meningkat tetapi nilai duniawi berkurang adalah suatu pertanda baik, peliharalah nilai ukhrowi itu dan tingkatkan nilai duniawi."],["p","3. Kalau nilai duniawi dan ukhrowi sejajar, saudara perlu banyak prihatin, terus berusaha meningkatkan nilai ukhrowi karena saudara dalam ujian."],["p","4. Bagaimanapun sakitnya kalau nikmat duniawi itu dicabut tidak ada artinya apa apa dibanding apabila nilai ukhrowi dicabut."],["p","5. Kalau yang dicabut nilai duniawi sangat kecil pengaruhnya dalam kehidupan."],["p","6. Kalau yang tercabut itu nilai ukhrowi sangat berpengaruh dalam kehidupan karena bukan saja akan menimpa diri sendiri tetapi akan dirasakan oleh segenap keluarga dan masyarakat. Karena bukan dirinya saja yang sesat, bahkan akan tumbuh daya yang kuat untuk menyesatkan orang lain."],["p","7. Retaknya hati dari rasa persaudaraan dengan sesama saudara sepengajian tidak akan dapat ditebus dengan tersambungnya hati yang seindah apapun pada tata lahirnya, dengan sebanyak banyaknya sekalipun dengan orang orang yang tidak mengaji."],["p","8. Siksaan batin itu tidak dapat ditebus dengan yang lahir atau yang bersifat lahiriyah sedunia ini dan isinya, karena obat batin itu batin pula obatnya, dan obat lahir dapat diobati dengan obat batin."],["p","9. Kadang orang tersilau oleh kertas pembungkus yang indah warna dan bahannya sehingga terkena sugesti dalam menilai isinya walaupun isi itu tidak berharga bahkan berbahaya."],["p","10. Bungkus yang baik tidak mutlak sebagai alamat baiknya isi yang dibungkus tetapi isi yang baik akan tetap baik walaupun tanpa bungkus."],["p","Semanggi, 4 April 1985"],["p","Demikianlah semoga Allah menuntun kita ke jalan yang benar, dan semoga Allah mengampuni kita. Aamiin."],["p","--oo0oo—"]]};